import { setWorkerUrl } from 'maplibre-gl';
import maplibreWorkerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';
import { MapmlViewer } from './elements/mapml-viewer';
import { MapLayer } from './elements/map-layer';
import { MapExtent } from './elements/map-extent';
import { MapFeature } from './elements/map-feature';
import { MapA } from './elements/map-a';
import { MapInput } from './elements/map-input';
import { MapLink } from './elements/map-link';
import { MapMeta } from './elements/map-meta';
import { MapSelect } from './elements/map-select';
import { MapStyle } from './elements/map-style';
import { MapTitle } from './elements/map-title';
import { MapCaption } from './elements/map-caption';
import { MapTile } from './elements/map-tile';

export {
  MapmlViewer,
  MapLayer,
  MapExtent,
  MapFeature,
  MapA,
  MapInput,
  MapLink,
  MapMeta,
  MapSelect,
  MapStyle,
  MapTitle,
  MapCaption,
  MapTile
};
export type { LayerExtent } from './elements/map-layer';
export type {
  MapmlCoord,
  EnvelopeCorner,
  MapmlExtent,
  PcrsBounds,
  MapmlCS
} from './core/crs';
export type { MapmlProjection, UnsupportedMapmlProjection } from './core/projection';
export {
  MAPML_PROJECTIONS,
  MAPML_RENDERER_UNSUPPORTED_PROJECTIONS,
  isMapmlProjection,
  isUnsupportedMapmlProjection
} from './core/projection';
export type {
  MapRenderer,
  RendererInitOptions,
  RasterTileLayerOptions,
  FeatureCollectionLayerOptions
} from './renderer/MapRenderer';
export { MapLibreRenderer } from './renderer/MapLibreRenderer';
export type { MapInputDef, TemplateEvaluationResult } from './core/template';
export { evaluateTileTemplate } from './core/template';
export type {
  FeatureCS,
  FeatureShape,
  FeaturePointShape,
  FeatureLineStringShape,
  FeaturePolygonShape
} from './core/feature';
export {
  parseCoordinatesText,
  parseGeometryCS,
  shapesFromGeometry,
  shapesToGeoJson,
  shapesToPcrsBounds
} from './core/feature';
export type { ExtentMeta, MapMetaName, ZoomMeta } from './core/mapMeta';
export {
  MAP_META_NAMES,
  isMapMetaName,
  parseExtentMeta,
  parseMetaContent,
  parseZoomMeta
} from './core/mapMeta';
export type {
  GeoJsonInput,
  GeoJsonFeature,
  GeoJsonFeatureCollection,
  GeoJsonGeometry,
  Geojson2MapmlOptions
} from './core/geojson2mapml';
export { geojson2mapml } from './core/geojson2mapml';
export type {
  Mapml2GeojsonOptions,
  Mapml2GeojsonFeatureCollection,
  Mapml2GeojsonFeature,
  Mapml2GeojsonGeometry
} from './core/mapml2geojson';
export { mapml2geojson } from './core/mapml2geojson';

// MapML.js-parity: hang `geojson2mapml` + `mapml2geojson` off the
// global `M` singleton so pages can call `M.geojson2mapml(json,
// options)` / `M.mapml2geojson(layer, options)` unchanged. Mirrors
// `M.geojson2mapml = Util.geojson2mapml` / `M.mapml2geojson =
// Util.mapml2geojson` in `../MapML.js/src/mapml/GlobalM.js`. Done
// here (not in `src/i18n/locale.ts`) to avoid a circular import —
// `geojson2mapml` itself imports `M` to default the `locale` argument.
import { M } from './i18n/locale';
import { geojson2mapml as _geojson2mapml } from './core/geojson2mapml';
import { mapml2geojson as _mapml2geojson } from './core/mapml2geojson';
M.geojson2mapml = _geojson2mapml;
M.mapml2geojson = _mapml2geojson;
export { M };

// Point MapLibre at its background worker before any `<mapml-viewer>`
// constructs a map. The worker ships as a sibling ESM chunk emitted by
// the bundler (`?worker&url`); consumers load only this library and
// never wire the worker themselves.
setWorkerUrl(maplibreWorkerUrl);

if (typeof customElements !== 'undefined') {
  const define = (name: string, ctor: CustomElementConstructor): void => {
    if (!customElements.get(name)) customElements.define(name, ctor);
  };
  // Define leaf elements before their consumers so upgrade order
  // guarantees a `<map-link>`'s synchronous `getInputs()` call sees
  // already-upgraded `<map-select>` / `<map-input>` siblings. Custom
  // elements are upgraded synchronously as `define()` runs, so a link
  // defined before its select would have its connectedCallback fire
  // (and read siblings) while those siblings are still plain
  // HTMLElements — breaking `instanceof MapSelect` gates.
  define('mapml-viewer', MapmlViewer);
  define('map-layer', MapLayer);
  define('map-extent', MapExtent);
  define('map-feature', MapFeature);
  define('map-a', MapA);
  define('map-input', MapInput);
  define('map-meta', MapMeta);
  define('map-select', MapSelect);
  define('map-style', MapStyle);
  define('map-title', MapTitle);
  define('map-caption', MapCaption);
  define('map-tile', MapTile);
  define('map-link', MapLink);
}
