import { osmtilePcrsToGcrs, osmtileTilematrixToPcrs } from '../core/crs';
import { shadowCrossingClosest } from '../core/shadow';

/**
 * Something that owns a contiguous run of `<map-tile>` elements and
 * turns it into a rendered layer. Implemented in a later slice by the
 * `<map-link rel="features">` run-group (fetched GeoServer LayerGroup
 * content) and, optionally, by `<map-layer>` (inline authored tiles).
 *
 * A `<map-tile>` registers with the nearest owner on connect and
 * unregisters on disconnect; `notifyMapTilesChanged` is the coalesced
 * "a `src` changed, re-upload the run" signal. The owner is
 * responsible for partitioning its children into contiguous
 * tile/feature runs (DOM order === paint order) and building one
 * renderer handle per run.
 */
export interface MapTileRunOwner {
  registerMapTile(tile: MapTile): void;
  unregisterMapTile(tile: MapTile): void;
  notifyMapTilesChanged(): void;
}

/** Duck-typed guard for {@link MapTileRunOwner} on an ancestor element. */
function isMapTileRunOwner(el: Element): el is Element & MapTileRunOwner {
  return (
    typeof (el as Partial<MapTileRunOwner>).registerMapTile === 'function' &&
    typeof (el as Partial<MapTileRunOwner>).unregisterMapTile === 'function' &&
    typeof (el as Partial<MapTileRunOwner>).notifyMapTilesChanged === 'function'
  );
}

/** Geographic (WGS84) bounding box of a tile, `[west, south, east, north]`. */
export type MapTileGcrsBounds = [number, number, number, number];

/**
 * `<map-tile>` — a single statically-placed raster tile.
 *
 * MapML.js renders these with a Leaflet `GridLayer` subclass
 * (`MapTileLayer`) keyed by `col:row:zoom`. This port has no per-tile
 * DOM; a contiguous run of `<map-tile>` siblings is rendered as one
 * MapLibre raster source whose cells resolve to each tile's `src` via
 * the shared `mapmltile://` protocol handler (see
 * `../renderer/mapLibreMapTileProtocol.ts`).
 *
 * `row` / `col` / `zoom` are **immutable** once the element connects
 * (they identify the tile's cell in the pyramid and can't change
 * without becoming a different tile) — matches MapML.js's
 * `HTMLTileElement`, which snapshots them in `connectedCallback` and
 * ignores later writes. Only `src` is mutable.
 *
 * OSMTILE only: `col` / `row` / `zoom` map onto the standard
 * Web-Mercator `x` / `y` / `z` grid.
 */
export class MapTile extends HTMLElement {
  static readonly observedAttributes = ['row', 'col', 'zoom', 'src'] as const;

  /** Guards `attributeChangedCallback` until after `connectedCallback`. */
  #hasConnected = false;
  #initialRow = 0;
  #initialCol = 0;
  #initialZoom = 0;
  #owner: MapTileRunOwner | null = null;

  /** Immutable tile row (Web-Mercator `y`). Snapshotted at connect. */
  get row(): number {
    return this.#hasConnected
      ? this.#initialRow
      : parseTileInt(this.getAttribute('row'), 0);
  }
  set row(val: number) {
    if (this.#hasConnected) return;
    const n = parseTileInt(String(val), NaN);
    if (!Number.isNaN(n)) this.setAttribute('row', String(n));
  }

  /** Immutable tile column (Web-Mercator `x`). Snapshotted at connect. */
  get col(): number {
    return this.#hasConnected
      ? this.#initialCol
      : parseTileInt(this.getAttribute('col'), 0);
  }
  set col(val: number) {
    if (this.#hasConnected) return;
    const n = parseTileInt(String(val), NaN);
    if (!Number.isNaN(n)) this.setAttribute('col', String(n));
  }

  /** Immutable tile zoom (Web-Mercator `z`). Snapshotted at connect. */
  get zoom(): number {
    return this.#hasConnected
      ? this.#initialZoom
      : parseTileInt(this.getAttribute('zoom'), 0);
  }
  set zoom(val: number) {
    if (this.#hasConnected) return;
    const n = parseTileInt(String(val), NaN);
    if (!Number.isNaN(n) && n >= 0 && n <= 25) this.setAttribute('zoom', String(n));
  }

  /** Mutable tile image URL. */
  get src(): string {
    return this.hasAttribute('src') ? this.getAttribute('src')! : '';
  }
  set src(val: string) {
    if (val) this.setAttribute('src', val);
  }

  /**
   * Registry sub-key this tile occupies in the `mapmltile://`
   * protocol table: `"z/x/y"` (OSMTILE `col`/`row`/`zoom`).
   */
  get tileKey(): string {
    return `${this.zoom}/${this.col}/${this.row}`;
  }

  /**
   * WGS84 bounding box `[west, south, east, north]` of the tile's
   * footprint. Owners union these across a run to set the raster
   * source's `bounds`.
   */
  get gcrsBounds(): MapTileGcrsBounds {
    const [westPcrs, northPcrs] = osmtileTilematrixToPcrs(this.col, this.row, this.zoom);
    const [eastPcrs, southPcrs] = osmtileTilematrixToPcrs(
      this.col + 1,
      this.row + 1,
      this.zoom
    );
    const [west, north] = osmtilePcrsToGcrs(westPcrs, northPcrs);
    const [east, south] = osmtilePcrsToGcrs(eastPcrs, southPcrs);
    return [west, south, east, north];
  }

  override getAttribute(name: string): string | null {
    if (this.#hasConnected) {
      switch (name) {
        case 'row':
          return String(this.#initialRow);
        case 'col':
          return String(this.#initialCol);
        case 'zoom':
          return String(this.#initialZoom);
      }
    }
    return super.getAttribute(name);
  }

  override setAttribute(name: string, value: string): void {
    if (this.#hasConnected) {
      switch (name) {
        case 'row':
        case 'col':
        case 'zoom':
          return;
      }
    }
    super.setAttribute(name, value);
  }

  connectedCallback(): void {
    // Snapshot the immutable identity attributes. Any attribute-setter
    // calls the parser made before this point have already landed;
    // from here on `row` / `col` / `zoom` are frozen.
    this.#initialZoom = parseTileInt(super.getAttribute('zoom'), 0);
    this.#initialRow = parseTileInt(super.getAttribute('row'), 0);
    this.#initialCol = parseTileInt(super.getAttribute('col'), 0);
    this.#hasConnected = true;

    // Shadow-crossing walk: a `<map-tile>` grafted into a
    // `<map-link rel="features">` shadow root must still reach the
    // owner that hosts the run.
    this.#owner = shadowCrossingClosest(this, isMapTileRunOwner);
    this.#owner?.registerMapTile(this);
  }

  disconnectedCallback(): void {
    const owner = this.#owner;
    this.#owner = null;
    owner?.unregisterMapTile(this);
  }

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (!this.#hasConnected) return;
    // `row` / `col` / `zoom` are frozen post-connect (the setAttribute
    // override blocks author writes; a stray change here is ignored).
    if (name === 'src' && oldValue !== newValue) {
      this.#owner?.notifyMapTilesChanged();
    }
  }
}

/** Parse an integer tile coordinate, returning `fallback` on failure. */
function parseTileInt(raw: string | null, fallback: number): number {
  if (raw === null) return fallback;
  const n = parseInt(raw, 10);
  return Number.isNaN(n) ? fallback : n;
}
