/**
 * Attribution prefix inserted into every viewer's attribution popover.
 *
 * The base64 payload is the W3C Community-and-Business-Groups icon,
 * mirrored from `../MapML.js/src/mapml/control/AttributionButton.js` so
 * MapML-MapLibre pages carry the same badge as MapML.js. The Ukraine
 * flag + Leaflet link that upstream also injects are omitted here — the
 * former is a policy decision authors can add themselves via
 * `<map-link rel="license">`, and Leaflet is not our renderer. In
 * Leaflet's place we append the MapLibre wordmark logo (linking to the
 * project) immediately to the right of the CG link. The logo is
 * {@link MAPLIBRE_LOGO_ICON} — the official maplibre.org brand mark in
 * its site colours — sized inline by `.mapml-maplibre-logo`
 * (attributionControl.css.ts).
 *
 * Injected as `customAttribution` on {@link MapmlAttributionControl}, our
 * subclass of MapLibre's `AttributionControl` which forces the prefix
 * left-most (MapLibre's stock control length-sorts) and preserves layer
 * insertion order for the rest. The control prepends a keyboard-shortcuts
 * opener button to the left of this prefix.
 */
const MAPS4HTML_W3CCG_ICON =
  'data:image/x-icon;base64,';

const MAPS4HTML_ATTRIBUTION_HTML =
  `<img src="${MAPS4HTML_W3CCG_ICON}" style="position: relative; top: 5px" alt="W3C Community and Business Groups logo"> ` +
  `<a href="https://www.w3.org/community/maps4html/" target="_blank" rel="noopener">Maps for HTML Community Group</a>` +
  ` | <a href="https://maplibre.org/" target="_blank" rel="noopener" title="MapLibre">` +
  `<img src="${MAPLIBRE_LOGO_ICON}" class="mapml-maplibre-logo" alt="MapLibre"></a>`;

/**
 * `<mapml-viewer>` — top-level MapML map element.
 *
 * Wires the element shell to a {@link MapLibreRenderer} and, when the
 * `controls` attribute is set, installs the MapML.js-style control suite:
 *
 *   top-left:    Zoom (`maplibregl.NavigationControl`), Reload, Fullscreen
 *   top-right:   LayerControl
 *   bottom-left: Scale
 *   bottom-right: Attribution (compact) — geolocate stacks above it when
 *                 opted in via `controlslist="geolocation"`
 *
 * The attribution control is **sacred**: it's installed on connect
 * regardless of the `controls` attribute or `controlslist` tokens, and
 * always carries the Maps for HTML Community Group prefix. Every other
 * control can be hidden or opted into via the `controlslist` attribute
 * (subtractive tokens `noreload`, `nofullscreen`, `nozoom`, `nolayer`,
 * `noscale`; additive tokens `geolocation`, `search`), exposed as a live
 * {@link ControlsTokenList} on {@link MapmlViewer.controlsList}.
 *
 * `<map-layer>` children register themselves with this viewer so the
 * LayerControl can list them; changes are broadcast via the
 * `mapml:layerschanged` event.
 *
 * The viewer also maintains a bounded "history ring" of past views (one
 * entry per `moveend`, capped at {@link MapmlViewer.HISTORY_LIMIT}). The
 * ring drives the {@link ReloadButton}: it's enabled whenever the ring
 * has more than one entry, and clicking it calls {@link MapmlViewer.reload}
 * to rewind to the initial entry. Structural changes to the ring are
 * broadcast via `mapml:historychanged`.
 */
export class MapmlViewer extends HTMLElement {
  static readonly observedAttributes = [
    'lat',
    'lon',
    'zoom',
    'bearing',
    'pitch',
    'view',
    'projection',
    'controls',
    'controlslist',
    'width',
    'height',
    'static',
    'featureindex'
  ] as const;

  static readonly HISTORY_LIMIT = 64;

  #renderer = new MapLibreRenderer();
  #container: HTMLDivElement;
  #connected = false;
  #layers: MapLayer[] = [];
  #controls: ControlsBag = {};
  /**
   * The attribution control. Not part of {@link ControlsBag} because it's
   * installed once on {@link connectedCallback} and only removed on
   * disconnect — the `controls` attribute and `controlslist` tokens have
   * no effect on it. See {@link #installAttribution}.
   */
  #attribution: MapmlAttributionControl | null = null;
  /**
   * The map-level context menu. Sacred (same lifecycle as attribution):
   * installed once on {@link connectedCallback}, torn down on disconnect.
   * It must survive `controls=false` because it hosts the very item
   * ("Toggle Controls") and keyboard shortcut (`T`) that flip the
   * attribute back on — mirroring MapML.js's approach, where the map's
   * context menu lives on the map itself (`contextMenu: true` at
   * construction) rather than on the toggleable control bag.
   */
  #contextMenu: ContextMenu | null = null;

  /**
   * Debug overlay (tile grid + coordinate panel + layer bounding
   * boxes). Lazily created the first time {@link toggleDebug} runs;
   * reachable only via the context menu's "Toggle Debug Mode" item.
   */
  #debug: DebugOverlay | null = null;
  /**
   * Tokenised `controlslist` attribute. Created in {@link connectedCallback}
   * (needs `this` to be in the DOM before we can reflect back to the
   * attribute without hitting an infinite loop via `attributeChangedCallback`).
   */
  #controlsList: ControlsTokenList | null = null;

  #history: HistoryEntry[] = [];
  #historyIndex = -1;
  /**
   * The resolved presentation / camera {@link MapmlView}. Set once on
   * connect (folding the `projection="GLOBE"` alias + warnings there,
   * so `moveend` capture doesn't re-warn) and updated by {@link setView}.
   */
  #view: MapmlView = 'map';
  /**
   * Counter of upcoming `moveend` events to skip when recording history.
   * Set by {@link MapmlViewer.reload}/{@link MapmlViewer.back}/{@link MapmlViewer.forward}
   * so the resulting moveend doesn't push a duplicate history entry.
   */
  #traversalCall = 0;

  /** Microtask coalescing flag for {@link notifyLayersChanged}. */
  #layersChangedScheduled = false;

  /**
   * Set of `<map-link rel="query">` descendants that have registered
   * themselves via {@link registerQueryLink}. Size is the *only*
   * thing consulted \u2014 the actual click-dispatch iteration walks the
   * DOM at click time (via `querySelectorAll`) to guarantee DOM
   * order across layers / extents / templates. The set is here
   * because we install and uninstall the single map-level click
   * listener lazily: no registered query links \u2192 no listener; adding
   * the first one installs it, removing the last one uninstalls it.
   */
  #queryLinks: Set<MapLink> = new Set();

  /**
   * Bound `click` listener for the query-response coordinator. Stored
   * so {@link #uninstallQueryClickListener} can hand the same
   * function reference to `map.off` \u2014 MapLibre keys listeners by
   * identity.
   */
  #queryClickListener: ((e: maplibregl.MapMouseEvent) => void) | undefined;

  /**
   * The `.mapml-crosshair` reticle DOM element. Mounted inside the
   * MapLibre map container (sibling of the canvas) once the renderer
   * is ready; visibility is toggled via the `hidden` attribute in
   * {@link #updateCrosshairVisibility}. Undefined until installed,
   * cleared to undefined on {@link disconnectedCallback}.
   *
   * The crosshair implements Q.28.* of BEHAVIOURS.md \u2014 the keyboard-
   * accessible centre-of-map indicator that lets a keyboard user
   * fire a query at the map centre via Space or Enter. Ports
   * MapML.js's `src/mapml/layers/Crosshair.js`.
   */
  #crosshair: HTMLDivElement | undefined;

  /**
   * `true` while the map canvas is in a keyboard-navigation focus
   * state — flipped on `focus` (Tab-in, or programmatic `.focus()`
   * from a keyboard-driven flow such as popup Escape or the popup's
   * zoom-to-here link) and on `keydown` events on the canvas.
   * Mouse users don't see the crosshair since they can just click
   * where they want; the flag is cleared on `mousedown` on the
   * canvas and on `blur`. The `focus`-event path is distinguished
   * from mouse-click focus via {@link #recentPointerDown}, which
   * suppresses the focus handler when a `mousedown` has just fired
   * on the same canvas (browsers dispatch `mousedown` before
   * `focus`). This makes the crosshair appear immediately when a
   * keyboard user Tabs into the map, rather than waiting for the
   * first arrow-key press.
   */
  #mapKeyboardFocused = false;

  /**
   * Set for one microtask by {@link #onCanvasMouseDown}. Consulted
   * by {@link #onCanvasFocus} to suppress the "focus reveals the
   * crosshair" flip when the focus was triggered by a mouse click
   * (the browser fires `mousedown` then `focus` for a click on a
   * tabbable element). Cleared on a `setTimeout(0)` tick so that
   * subsequent programmatic `.focus()` calls (e.g. popup close
   * restoring focus to the canvas) are treated as keyboard-driven.
   */
  #recentPointerDown = false;

  /**
   * Attribute-mutation observer for the `checked` / `disabled` /
   * `hidden` attributes anywhere in the viewer subtree. These
   * attributes on `<map-layer>` / `<map-extent>` / `<map-link>`
   * flip whether a query link is "actively queryable" \u2014 which
   * gates crosshair visibility. Distinct from `mapml:layerschanged`
   * because the checked-attribute flow deliberately skips that
   * event (to avoid LayerControl rebuild loops); the observer is
   * a targeted subscription for the crosshair specifically.
   */
  #queryableAttrObserver: MutationObserver | null = null;

  /**
   * Watches this element's subtree for `<map-caption>` additions,
   * removals, and text edits, and mirrors the first caption's
   * `textContent` onto our `aria-label`. Installed once in
   * {@link connectedCallback}, torn down in {@link disconnectedCallback}.
   * See {@link #syncCaptionAriaLabel}.
   */
  #captionObserver: MutationObserver | null = null;
  /**
   * The `<map-caption>` element whose `textContent` we're currently
   * mirroring into `aria-label`. `null` when we don't own the
   * attribute (either no caption exists, or the author set aria-label
   * themselves).
   *
   * We track the element identity — not just the text — because
   * MapML.js's behaviour is to abandon aria-label when the originally
   * adopted caption is removed, even if a sibling caption remains.
   */
  #trackedCaption: MapCaption | null = null;
  /**
   * The last `aria-label` value we wrote. Used to detect author
   * overrides: if `getAttribute('aria-label')` differs from this,
   * the author has taken over and we release management.
   */
  #lastWrittenAriaLabel: string | null = null;
  /**
   * Snapshot of the viewer's `outerHTML` at the moment
   * {@link connectedCallback} first runs. Consumed by
   * {@link MapmlViewer.viewSource}, which opens a new tab containing
   * this text (pretty-printed for readability).
   *
   * Captured once (`null` beforehand) so subsequent runtime mutations
   * of the light DOM — pastes, `<map-layer>` additions, drag-and-drop —
   * don't drift the "source" view away from the author's original
   * markup. Matches MapML.js's `this._source = this.outerHTML`
   * assignment in `src/mapml-viewer.js#connectedCallback`.
   */
  #source: string | null = null;

  /**
   * Bound `drop` / `dragover` handlers installed on the host in
   * {@link connectedCallback} and removed in {@link disconnectedCallback}.
   * Both are stored so `removeEventListener` sees the exact same
   * function reference we added. See {@link #installDragDropHandlers}
   * for the behavioural contract.
   */
  #boundDropHandler: ((event: DragEvent) => void) | null = null;
  #boundDragoverHandler: ((event: DragEvent) => void) | null = null;

  /**
   * Live-region `<output>` used by the `announceMovement` feature to
   * spell out movement / zoom / bounds events for screen-reader users.
   *
   * Null unless `M.options.announceMovement === true` at
   * {@link connectedCallback} time. When enabled, appended to the
   * viewer's shadow root as the *first* `<output>` element so that
   * `shadowRoot.querySelector('output')` returns this one (matching
   * MapML.js's fixture-side selector). Text updates funnel through
   * {@link #maybeAnnounceMovement}, invoked from {@link #onMoveEnd}
   * after each real moveend + also on the clamped-to-min-zoom no-op
   * case so users hear "At minimum zoom level, zoom out disabled".
   */
  #announceMovementOutput: HTMLOutputElement | null = null;

  /**
   * Feature-index a11y overlay (reticle + numbered results). Mounted once
   * the map exists ({@link #mountFeatureIndexOverlay}); `null` before that
   * and after {@link disconnectedCallback}.
   */
  #featureIndexOverlay: FeatureIndexOverlay | null = null;

  /**
   * Live source of truth for the feature-index overlay, ignoring the
   * {@link M.options.featureIndexOverlayOption} preference. Seeded from the
   * initial `featureindex` attribute at connect; the {@link featureIndex}
   * getter folds the tri-state preference over this to produce the
   * *effective* state.
   */
  #featureIndex = false;

  /**
   * Whether {@link featureIndex} property changes mirror back to the
   * `featureindex` attribute. True only when the attribute was present at
   * connect or has since been written by the author, so control-driven
   * toggles don't churn the attribute (mirrors the input `value` vs
   * `defaultValue` pattern).
   */
  #reflectFeatureIndexAttr = false;

  /** Re-entrancy guard while the setter mirrors to the attribute. */
  #reflectingFeatureIndex = false;

  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });

    const style = document.createElement('style');
    style.textContent = `${maplibreCss}
:host { display: block; position: relative; width: 100%; height: 100%; }
.container { position: absolute; inset: 0; }
${layerControlCss}
${reloadButtonCss}
${viewControlCss}
${staticControlCss}
${compassControlCss}
${featureIndexControlCss}
${contextMenuCss}
${iconOverridesCss}
${crosshairCss}
${featurePopupCss}
${featureFocusCss}
${featureIndexOverlayCss}
${searchControlCss}
${attributionControlCss}
${debugOverlayCss}`;
    root.appendChild(style);

    this.#container = document.createElement('div');
    this.#container.className = 'container';
    root.appendChild(this.#container);
  }

  connectedCallback(): void {
    if (this.#connected) return;
    this.#connected = true;

    // Snapshot the author's markup once, before we mount any controls
    // or observers that could mutate light-DOM. `viewSource()` serves
    // this back verbatim (pretty-printed) so the "View Source"
    // context-menu item always shows the original, not the post-run
    // DOM. Matches MapML.js.
    this.#source = this.outerHTML;

    // Initialise the token list before we install controls, since the
    // install logic reads `contains('geolocation')` etc. Reflect the
    // attribute's initial value in without triggering a re-entrant call.
    this.#controlsList = new ControlsTokenList(
      this.getAttribute('controlslist'),
      this,
      'controlslist',
      CONTROLSLIST_TOKENS
    );

    const projAttr = this.getAttribute('projection');
    if (projAttr !== null) this.#warnIfBadProjection(projAttr);
    const projection: MapmlProjection =
      projAttr !== null && isMapmlProjection(projAttr) ? projAttr : 'OSMTILE';

    const view = this.#resolveInitialView();
    this.#view = view;
    const profile = viewProfile(view);
    // Author `pitch` wins; otherwise the view supplies its default
    // (e.g. 60° for `perspective`). `map` view ignores both — the
    // renderer snaps the camera flat in `applyViewMode`.
    const pitchAttr = this.getAttribute('pitch');
    const initialPitch = pitchAttr !== null ? Number(pitchAttr) : profile.defaultPitch;
    const bearingAttr = this.getAttribute('bearing');
    const initialBearing = bearingAttr !== null ? Number(bearingAttr) : 0;

    const initOptions: RendererInitOptions = {
      container: this.#container,
      projection,
      view,
      center: [
        Number(this.getAttribute('lon') ?? 0),
        Number(this.getAttribute('lat') ?? 0)
      ],
      zoom: Number(this.getAttribute('zoom') ?? 0),
      bearing: initialBearing,
      pitch: initialPitch,
      // Pipe our MapML locale into MapLibre's own i18n so stock
      // controls (zoom / fullscreen / attribution toggle / geolocate)
      // pick up the same language as our custom controls and menus.
      // Set once at map construction — same lifetime constraint as
      // MapML.js, where `_setLocale` runs once per install.
      locale: mapmlLocaleToMapLibre(this.locale),
      // Also hand the full MapML {@link Locale} bundle over for the
      // renderer-owned surfaces MapLibre doesn't localise for us
      // (feature-popup "Zoom to here" link + `dfFeatureCaption`
      // fallback heading).
      mapmlLocale: this.locale,
      // `<map-a>`-wrapped feature activation (mouse click or
      // keyboard Enter/Space on a focused proxy). Route through
      // {@link handleFeatureLink} so `_self` / `_parent` / `_blank`
      // / `_top` semantics + `#z,lon,lat` pan-only shape work
      // identically across input modalities. Keeping this outside
      // the renderer means the renderer stays free of any
      // `<mapml-viewer>` / `<map-layer>` imports.
      onFeatureLinkActivate: (item) => {
        const link = readFeatureLink(item.properties);
        if (link === null) return;
        // `item.featureEl` is the `<map-feature>` that emitted
        // this focus item; walk to its owning `<map-layer>` for
        // the `_self` in-place-replace semantics.
        const owningLayer =
          item.featureEl instanceof MapFeature ? item.featureEl.parentLayer : null;
        handleFeatureLink(this, owningLayer, link);
      }
    };
    // Honour viewer-level <map-meta name="zoom" content="min=…,max=…">
    // as the renderer's zoom bounds. Layer-level meta is handled
    // separately once the layer extent infrastructure lands.
    const zoomMeta = this.#findViewerZoomMeta();
    if (zoomMeta !== null) {
      initOptions.minZoom = zoomMeta.min;
      initOptions.maxZoom = zoomMeta.max;
    }

    this.#renderer.init(initOptions);

    // Reflect any pre-existing width/height attributes onto the host.
    this.#applySizeAttribute('width');
    this.#applySizeAttribute('height');

    void this.#initialView();

    // Attribution is *sacred* — installed once on connect regardless of the
    // `controls` attribute, and only torn down on disconnect. Authors who
    // forget `<map-link rel="license">` still get haunted by the Maps for
    // HTML Community Group attribution.
    void this.#installAttribution();

    // The map-level context menu is also *sacred*: it hosts the
    // "Toggle Controls" item and the `T` keyboard shortcut that flip
    // the `controls` attribute, so tearing it down when controls are
    // off would strand the user with no way to bring them back.
    this.#installContextMenu();

    // Mirror the first <map-caption>'s text into aria-label. Also
    // sacred: if the author bothered to write a caption, we honour
    // it even when controls are off.
    this.#installCaptionObserver();

    // Mount the keyboard-query centre indicator. Also sacred \u2014
    // authors can't opt out of accessibility affordances by omitting
    // `controls`; a `<map-link rel="query">` needs a keyboard entry
    // point regardless.
    this.#installCrosshair();

    // Drag-and-drop of MapML / GeoJSON / URL / `<map-layer>` snippets
    // onto the viewer. Also sacred — mirrors MapML.js's
    // `src/mapml-viewer.js#_setUpEvents`, where the drop + dragover
    // handlers are wired unconditionally, not gated on `controls`.
    this.#installDragDropHandlers();

    // Screen-reader movement announcements (`M.options.announceMovement`).
    // Off by default — authors opt in via `<map-options>` in `<head>`,
    // matching MapML.js. Reads the flag once here so per-viewer
    // enable/disable follows the same lifecycle as the rest of the
    // sacred / opt-in a11y affordances.
    if (M.options.announceMovement) {
      this.#installAnnounceMovement();
    }

    if (this.hasAttribute('controls')) {
      void this.#installControls();
    }

    // Honour the initial `static` attribute state now that the map is
    // created. Ports the trailing `this._toggleStatic()` in MapML.js's
    // `connectedCallback`. Handler disable/enable is synchronous; the
    // zoom-button toggle also runs after `#installControls` awaits
    // whenReady, so re-run once controls settle.
    this.#toggleStatic();
    if (this.hasAttribute('static') && this.hasAttribute('controls')) {
      void this.#renderer.whenReady().then(() => this.#toggleStatic());
    }

    // Feature-index a11y overlay. Seed the live property from the initial
    // `featureindex` attribute (the author's initial declaration only) and
    // record whether to reflect later property changes back to the
    // attribute. The tri-state `M.options.featureIndexOverlayOption`
    // preference is folded in by the {@link featureIndex} getter, so it can
    // force the state on/off regardless of markup. Mount the overlay once
    // the map exists.
    this.#reflectFeatureIndexAttr = this.hasAttribute('featureindex');
    this.#featureIndex = this.hasAttribute('featureindex');
    void this.#renderer.whenReady().then(() => this.#mountFeatureIndexOverlay());
  }

  disconnectedCallback(): void {
    this.#uninstallControls();
    this.#uninstallQueryClickListener();
    this.#queryLinks.clear();
    this.#uninstallCrosshair();
    this.#uninstallDragDropHandlers();
    this.#uninstallAnnounceMovement();
    this.#featureIndexOverlay?.destroy();
    this.#featureIndexOverlay = null;
    this.#contextMenu?.destroy();
    this.#contextMenu = null;
    this.#debug?.disable();
    this.#debug = null;
    this.#captionObserver?.disconnect();
    this.#captionObserver = null;
    this.#trackedCaption = null;
    this.#lastWrittenAriaLabel = null;
    this.#renderer.destroy();
    this.#history = [];
    this.#historyIndex = -1;
    this.#traversalCall = 0;
    this.#view = 'map';
    this.#connected = false;
  }

  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (!this.#connected) return;
    if (
      name === 'lat' ||
      name === 'lon' ||
      name === 'zoom' ||
      name === 'bearing' ||
      name === 'pitch'
    ) {
      // Ignore mutations. These attributes are STATE REFLECTION /
      // write-once configuration, not live controls: the renderer is
      // the source of truth, {@link #updateViewAttrs} writes lat/lon/
      // zoom/bearing/pitch back on every `moveend`, and the
      // author-facing API for driving the camera is {@link zoomTo} /
      // {@link setView}. Author `setAttribute` calls silently no-op.
      // Matches MapML.js, whose `attributeChangedCallback` has no case
      // for lat/lon/zoom (silent fall-through), so
      // `viewer.setAttribute('zoom', '5')` also doesn't move the map
      // there. (`view` is deliberately NOT in this group — see below.)
      return;
    }
    if (name === 'controls') {
      if (newValue !== null) {
        void this.#installControls();
      } else {
        this.#uninstallControls();
      }
    } else if (name === 'controlslist') {
      // Guard against re-entrance: our own setter reflects back here.
      if (this.#controlsList && !this.#controlsList.valueSet) {
        this.#controlsList.value = newValue;
      }
      // Re-install controls so the new token set takes effect. Cheap:
      // MapLibre's addControl/removeControl are idempotent per instance,
      // and #installControls guards on `!this.#controls.<key>`.
      if (this.hasAttribute('controls')) {
        this.#uninstallControls();
        void this.#installControls();
      }
    } else if (name === 'projection') {
      if (newValue !== null) this.#warnIfBadProjection(newValue);
      // Live projection switching is not supported in v1; the warning is
      // the only behaviour. We still dispatch `map-projectionchange`
      // so `viewer.matchMedia('(map-projection: …)')` matchers
      // re-evaluate — matches MapML.js's own dispatch site in
      // `src/mapml-viewer.js`.
      if (oldValue !== newValue) {
        this.dispatchEvent(new CustomEvent('map-projectionchange'));
      }
    } else if (name === 'view') {
      // `view` is a discrete mode selector (like `projection`), not the
      // continuous state above — so live author writes
      // (`setAttribute('view', …)` / `viewer.view = …`) ARE honoured.
      // Route through {@link setView} so a switch into a tilt-capable
      // view seeds its default pitch, matching the programmatic API.
      // The self-write {@link #applyView} performs when reflecting the
      // attribute re-enters here, but by then `next === this.#view`, so
      // it's a no-op — that comparison is the re-entrancy guard.
      const next: MapmlView =
        newValue !== null && isMapmlView(newValue) ? newValue : 'map';
      if (newValue !== null && !isMapmlView(newValue)) {
        console.warn(`Undefined view: ${newValue}; falling back to "map".`);
      }
      if (next !== this.#view) this.setView({ view: next });
    } else if (name === 'width' || name === 'height') {
      this.#applySizeAttribute(name);
    } else if (name === 'static') {
      this.#toggleStatic();
    } else if (name === 'featureindex') {
      // Ignore our own mirror writes (setter -> setAttribute).
      if (this.#reflectingFeatureIndex) return;
      // A runtime author write opts the attribute into live reflection so
      // `[featureindex]` stays honest; removal keeps reflection on but
      // turns the overlay off.
      const present = newValue !== null;
      this.#reflectFeatureIndexAttr = present || this.#reflectFeatureIndexAttr;
      this.#setFeatureIndex(present, true);
    }
  }

  get renderer(): MapLibreRenderer {
    return this.#renderer;
  }

  /** True while the map-level context menu is showing. */
  get contextMenuOpen(): boolean {
    return this.#contextMenu?.isOpen ?? false;
  }

  /**
   * Toggle the debug overlay on / off. Mirrors MapML.js's
   * `mapEl.toggleDebug()`; wired to the context menu's "Toggle Debug
   * Mode" item (and its `D` shortcut).
   */
  toggleDebug(): void {
    if (this.#debug === null) this.#debug = new DebugOverlay(this);
    this.#debug.toggle();
  }

  /**
   * Boolean reflection of the `controls` attribute. Assigning a truthy
   * value adds the attribute (which triggers `#installControls` via
   * {@link attributeChangedCallback}); assigning a falsy value removes
   * it (triggering `#uninstallControls`). Mirrors MapML.js's
   * `get controls() / set controls(value)` in `src/mapml-viewer.js`.
   *
   * This is the property surface the context menu's "Toggle Controls"
   * item and the `T` keyboard shortcut flip — all UI state changes
   * flow through the attribute observer, so there is exactly one code
   * path controlling install/uninstall.
   */
  get controls(): boolean {
    return this.hasAttribute('controls');
  }
  set controls(value: boolean) {
    if (value) {
      this.setAttribute('controls', '');
    } else {
      this.removeAttribute('controls');
    }
  }

  /**
   * Boolean reflection of the `static` attribute. When present, disables
   * all user-driven map interaction (drag pan, scroll/touch/double-click
   * zoom, box zoom, keyboard, drag rotate) and disables the zoom-control
   * buttons. Ports MapML.js's `get static() / set static(value)` in
   * `src/mapml-viewer.js`.
   */
  get static(): boolean {
    return this.hasAttribute('static');
  }
  set static(value: boolean) {
    if (value) {
      this.setAttribute('static', '');
    } else {
      this.removeAttribute('static');
    }
  }

  /**
   * Effective feature-index overlay state: the live {@link #featureIndex}
   * property with the tri-state {@link M.options.featureIndexOverlayOption}
   * user / UA preference folded over it. A `'on'` / `'off'` preference wins
   * over author markup and the megaphone control (like
   * `prefers-reduced-motion`); `undefined` defers to the property.
   *
   * Unlike {@link static}, this is NOT a plain attribute reflection: the
   * `featureindex` attribute is only the author's *initial* declaration,
   * and the property is the source of truth. Assigning drives the overlay
   * and, when the attribute was present at connect (or written since),
   * mirrors back to it.
   */
  get featureIndex(): boolean {
    const pref = M.options.featureIndexOverlayOption;
    if (pref === 'on') return true;
    if (pref === 'off') return false;
    return this.#featureIndex;
  }
  set featureIndex(value: boolean) {
    this.#setFeatureIndex(!!value, false);
  }

  /**
   * Apply a new raw feature-index property value. `fromAttribute` is true
   * when driven by {@link attributeChangedCallback}, in which case we must
   * NOT mirror back to the attribute (it's already the write we're
   * reacting to). Otherwise mirror only when {@link #reflectFeatureIndexAttr}.
   */
  #setFeatureIndex(next: boolean, fromAttribute: boolean): void {
    this.#featureIndex = next;
    if (!fromAttribute && this.#reflectFeatureIndexAttr) {
      this.#reflectingFeatureIndex = true;
      if (next) this.setAttribute('featureindex', '');
      else this.removeAttribute('featureindex');
      this.#reflectingFeatureIndex = false;
    }
    this.#applyFeatureIndex();
  }

  /**
   * Enable / disable the overlay to match the current *effective* state
   * (preference folded in) and broadcast `mapml:featureindexchanged` so the
   * megaphone control and any author listeners re-render.
   */
  #applyFeatureIndex(): void {
    const effective = this.featureIndex;
    if (this.#featureIndexOverlay) {
      if (effective) this.#featureIndexOverlay.enable();
      else this.#featureIndexOverlay.disable();
    }
    this.dispatchEvent(
      new CustomEvent('mapml:featureindexchanged', {
        detail: { active: effective }
      })
    );
  }

  /**
   * Create the {@link FeatureIndexOverlay} once the map is ready and apply
   * the current effective state. The inbound-feature data source is the
   * renderer's {@link FeatureFocusIndex} (via
   * {@link MapLibreRenderer.featureIndexHost}), which already tracks the
   * in-viewport, in-zoom feature set nearest-to-centre first.
   */
  #mountFeatureIndexOverlay(): void {
    const map = this.#renderer.map;
    const host = this.#renderer.featureIndexHost;
    if (!map || !host || this.#featureIndexOverlay) return;
    this.#featureIndexOverlay = new FeatureIndexOverlay(map, host, this.locale);
    if (this.featureIndex) this.#featureIndexOverlay.enable();
  }

  /**
   * Tokenised representation of the `controlslist` attribute. Read/write:
   * assigning a string is equivalent to `setAttribute('controlslist', v)`;
   * use the DOMTokenList methods (`add`, `remove`, `toggle`, `replace`,
   * `contains`, `supports`) for finer-grained mutation.
   *
   * Returns `null` before `connectedCallback` has run.
   */
  get controlsList(): ControlsTokenList | null {
    return this.#controlsList;
  }
  set controlsList(value: string) {
    if (this.#controlsList) {
      this.#controlsList.value = value;
    } else {
      // Pre-connect: fall back to attribute reflection; the token list
      // will be built off this value in connectedCallback.
      this.setAttribute('controlslist', value);
    }
  }

  /** Resolves once the underlying MapLibre map has finished loading. */
  whenReady(): Promise<void> {
    return this.#renderer.whenReady();
  }

  /**
   * Active locale for UI strings (context menu, control labels).
   *
   * Resolution mirrors MapML.js's `_setLocale`
   * (`src/mapml-viewer.js`): match the viewer against the CSS
   * `:lang()` selector for every bundled tag (`en`/`fr`/`ja`/`sv`/
   * `uk`), which automatically respects the `lang` attribute inherited
   * from `<html lang="…">` all the way down. Anything that doesn't
   * match a bundled tag (including `lang="browser-language"`) falls
   * through to `M.options.locale` — the browser-picked default or an
   * `<map-options>`-injected bundle.
   *
   * The getter re-reads on every access, so authors can swap
   * `M.options.locale` at runtime — though controls already mounted
   * won't relabel (matches MapML.js, which reads locale once per
   * install).
   */
  get locale(): Locale {
    return getViewerLocale(this);
  }

  /** Reflected projection — value is one of {@link MapmlProjection}. */
  get projection(): MapmlProjection {
    const a = this.getAttribute('projection');
    return a !== null && isMapmlProjection(a) ? a : 'OSMTILE';
  }
  set projection(value: string) {
    this.setAttribute('projection', value);
  }

  /**
   * Presentation / camera mode: `map` (default), `globe`, or `perspective`.
   * The getter resolves the effective view, folding the deprecated
   * `projection="GLOBE"` alias into `globe` and unknown values into `map`.
   *
   * Unlike the continuous {@link lat} / {@link lon} / {@link zoom} state
   * (reflected back on every `moveend`, so author writes are ignored),
   * `view` is a live mode selector like {@link projection}: assigning
   * `viewer.view = 'globe'` or `setAttribute('view', 'globe')` switches the
   * regime at runtime ({@link attributeChangedCallback}), seeding the target
   * view's default pitch. Use {@link setView} to change the view *and* the
   * camera (lat/lon/zoom/bearing/pitch) in a single call.
   */
  get view(): MapmlView {
    return this.#connected ? this.#view : this.#resolveInitialView();
  }
  set view(value: string) {
    if (value) this.setAttribute('view', String(value));
  }

  /**
   * Camera rotation, in degrees. State reflection like {@link lat}: written
   * back on every `moveend` in tilt-capable views. Author writes after
   * connect are ignored — use {@link setView}.
   */
  get bearing(): number {
    return +(this.getAttribute('bearing') ?? 0);
  }
  set bearing(value: number | string) {
    this.setAttribute('bearing', String(value));
  }

  /** Camera tilt, in degrees. See {@link bearing}. */
  get pitch(): number {
    return +(this.getAttribute('pitch') ?? 0);
  }
  set pitch(value: number | string) {
    this.setAttribute('pitch', String(value));
  }

  /**
   * Numeric width attribute, in CSS pixels. Returns the host's current
   * client width when no `width` attribute is set, matching the MapML.js
   * semantics.
   */
  get width(): number {
    const a = this.getAttribute('width');
    return a !== null ? Number(a) : this.clientWidth;
  }
  set width(value: number) {
    this.setAttribute('width', String(value));
  }

  /** Numeric height attribute, in CSS pixels. */
  get height(): number {
    const a = this.getAttribute('height');
    return a !== null ? Number(a) : this.clientHeight;
  }
  set height(value: number) {
    this.setAttribute('height', String(value));
  }

  /**
   * Latitude of the current map centre, in degrees. Getter returns the
   * numeric value of the `lat` attribute (0 when absent) — matching
   * MapML.js's `get lat()`.
   *
   * Setter mirrors MapML.js: assigning a falsy value is ignored;
   * assigning any truthy value writes it verbatim via `setAttribute`.
   * The moveend reflection ({@link #updateViewAttrs}) also goes through
   * this setter so all attribute writes share one code path.
   */
  get lat(): number {
    return +(this.getAttribute('lat') ?? 0);
  }
  set lat(value: number | string) {
    if (value) this.setAttribute('lat', String(value));
  }

  /** Longitude of the current map centre, in degrees. See {@link lat}. */
  get lon(): number {
    return +(this.getAttribute('lon') ?? 0);
  }
  set lon(value: number | string) {
    if (value) this.setAttribute('lon', String(value));
  }

  /**
   * Current map zoom level. Getter returns the numeric value of the
   * `zoom` attribute (0 when absent).
   *
   * Setter mirrors MapML.js exactly: values that don't `parseInt` to a
   * non-negative integer in `[0, 25]` are silently dropped. That means
   * fractional zooms (which MapLibre supports natively) are truncated
   * to their integer part when reflected — a deliberate choice, since
   * the MapML `zoom` axis is integer-only.
   */
  get zoom(): number {
    return +(this.getAttribute('zoom') ?? 0);
  }
  set zoom(value: number | string) {
    const parsed = parseInt(String(value), 10);
    if (!isNaN(parsed) && parsed >= 0 && parsed <= 25) {
      this.setAttribute('zoom', String(parsed));
    }
  }

  /** Pan + zoom to the given geographic location and zoom level. */
  zoomTo(lat: number, lon: number, zoom: number): void;
  /**
   * Pan + zoom, also setting the camera `bearing` / `pitch`. Angles are
   * only honoured in tilt-capable views (`globe` / `perspective`); in
   * `map` view the renderer keeps the camera flat.
   */
  zoomTo(lat: number, lon: number, zoom: number, bearing: number, pitch: number): void;
  zoomTo(lat: number, lon: number, zoom: number, bearing?: number, pitch?: number): void {
    const map = this.#renderer.map;
    if (!map) return;
    const opts: maplibregl.JumpToOptions = { center: [lon, lat], zoom };
    if (bearing !== undefined) opts.bearing = bearing;
    if (pitch !== undefined) opts.pitch = pitch;
    map.jumpTo(opts);
  }

  /**
   * Programmatically drive the view + camera in one call. The `view`
   * selector is also settable on its own (live) via `viewer.view = …` /
   * `setAttribute('view', …)`; `bearing` / `pitch` remain write-once
   * attributes ({@link attributeChangedCallback} ignores author writes),
   * so this is the way to set those after connect.
   *
   * - `view` switches the presentation regime (`map` / `globe` /
   *   `perspective`) — its own projection + tilt locks are applied via
   *   {@link MapRenderer.applyViewMode}. Omit to keep the current view.
   * - `lat` / `lon` / `zoom` / `bearing` / `pitch` are each optional and
   *   default to the map's current value, so callers can nudge one axis
   *   without disturbing the rest.
   *
   * When switching *into* a tilt-capable view without an explicit
   * `pitch`, the view's default pitch (e.g. 60° for `perspective`) is
   * applied so the mode is visibly distinct. The resulting `moveend`
   * records a history entry carrying the new view + camera, so
   * back / forward / reload round-trip across views.
   */
  setView(options: {
    view?: MapmlView;
    lat?: number;
    lon?: number;
    zoom?: number;
    bearing?: number;
    pitch?: number;
  }): void {
    const map = this.#renderer.map;
    if (!map) return;

    const switchingView = options.view !== undefined && options.view !== this.#view;
    if (options.view !== undefined) {
      const nextView = isMapmlView(options.view) ? options.view : 'map';
      this.#applyView(nextView);
    }

    const profile = viewProfile(this.#view);
    const center = map.getCenter();
    const opts: maplibregl.JumpToOptions = {
      center: [options.lon ?? center.lng, options.lat ?? center.lat],
      zoom: options.zoom ?? map.getZoom()
    };
    if (profile.allowTilt) {
      opts.bearing = options.bearing ?? map.getBearing();
      // On a fresh switch into a tilt-capable view, seed the view's
      // default pitch when the caller didn't specify one.
      opts.pitch =
        options.pitch ?? (switchingView ? profile.defaultPitch : map.getPitch());
    } else {
      // Non-tilt (`map`) view pins the camera flat. Fold the reset into
      // this single jumpTo (rather than a separate renderer setBearing /
      // setPitch) so the switch fires exactly one moveend.
      opts.bearing = 0;
      opts.pitch = 0;
    }
    map.jumpTo(opts);
  }

  /**
   * One-shot geolocation. Ports MapML.js's `mapEl.locate(options)` in
   * `src/mapml-viewer.js`, which delegates to Leaflet's `map.locate`.
   *
   * MapLibre GL JS has no `map.locate` equivalent, so we call the
   * browser's `navigator.geolocation.getCurrentPosition` directly and
   * translate the result into the same DOM events MapML.js emits:
   *
   *   - `maplocationfound` — `detail: { latlng: { lat, lng }, accuracy }`
   *   - `locationerror`    — `detail: { error }`
   *
   * Options mirror the subset of Leaflet's locate-options MapML.js
   * honours:
   *   - `setView` (default `true`) — recentre the map on the fix.
   *   - `zoomTo` — MapML.js's alias for `setView`; wins when both are
   *     given (upstream deletes `setView` and rewrites it from `zoomTo`).
   *   - `maxZoom` (default `16`) — zoom level applied when recentring.
   *   - `enableHighAccuracy` / `timeout` / `maximumAge` — forwarded to
   *     `getCurrentPosition`.
   *
   * Unlike MapML.js we don't stop an in-progress geolocate-control watch
   * first: the one-shot fix recentres on the same coordinates the watch
   * would, so there's nothing to fight.
   */
  locate(options?: {
    setView?: boolean;
    zoomTo?: boolean;
    maxZoom?: number;
    enableHighAccuracy?: boolean;
    timeout?: number;
    maximumAge?: number;
  }): void {
    const geo = navigator.geolocation;
    if (!geo) {
      this.dispatchEvent(
        new CustomEvent('locationerror', {
          detail: { error: 'Geolocation API is not available.' }
        })
      );
      return;
    }
    const setView = options?.zoomTo ?? options?.setView ?? true;
    const maxZoom = options?.maxZoom ?? 16;
    geo.getCurrentPosition(
      (pos) => {
        const { latitude, longitude, accuracy } = pos.coords;
        if (setView) {
          this.#renderer.map?.jumpTo({
            center: [longitude, latitude],
            zoom: maxZoom
          });
        }
        this.dispatchEvent(
          new CustomEvent('maplocationfound', {
            detail: { latlng: { lat: latitude, lng: longitude }, accuracy }
          })
        );
      },
      (err) => {
        this.dispatchEvent(
          new CustomEvent('locationerror', { detail: { error: err.message } })
        );
      },
      {
        enableHighAccuracy: options?.enableHighAccuracy ?? false,
        timeout: options?.timeout,
        maximumAge: options?.maximumAge
      } as PositionOptions
    );
  }

  /**
   * Open a new window / tab containing the viewer's captured markup
   * for the "View Source" affordance.
   *
   * The source is the snapshot taken by {@link connectedCallback} — so
   * pastes and other runtime mutations don't drift what the user
   * sees away from the original document.
   *
   * MapML.js's `viewSource()` blobs `outerHTML` verbatim (a single
   * long line). MapML-MapLibre pretty-prints it via
   * {@link prettyPrintMapml} so the tab shows a readable, indented
   * tree — the user still sees the same MapML, just formatted.
   *
   * Uses a `blob:` URL + `window.open` so the new tab has an isolated
   * origin (nothing on the source page can script into it). Called
   * from the map-level context menu's "View Source" item and its
   * `V` shortcut.
   */
  viewSource(): void {
    const raw = this.#source ?? this.outerHTML;
    let body: string;
    try {
      // Re-parse the snapshot in a detached document so we don't have
      // to walk the live viewer (which has been mutated by observers /
      // upgrades). Falls back to raw text on any parser hiccup.
      const doc = new DOMParser().parseFromString(raw, 'text/html');
      const root = doc.querySelector('mapml-viewer');
      body = root !== null ? prettyPrintMapml(root) : raw;
    } catch {
      body = raw;
    }
    const blob = new Blob([body], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    window.open(url, '_blank');
    // Delay revocation so the new tab has time to load the blob URL.
    // Same trade-off MapML.js makes (it revokes immediately, which
    // works in current browsers because the blob is copied on `open`,
    // but delaying is safer).
    setTimeout(() => URL.revokeObjectURL(url), 60_000);
  }

  /**
   * Build a `<map-layer>` from GeoJSON and append it to this viewer.
   *
   * Mirrors MapML.js's `mapEl.geojson2mapml` (`src/mapml-viewer.js`).
   * Delegates the actual construction to the renderer-agnostic
   * {@link geojsonToMapmlLayer} helper; the wrapper only supplies the
   * viewer's projection as the default (when the caller didn't
   * override it via `options.projection`) and appends the result.
   *
   * @returns The appended `<map-layer>` element, so callers can chain
   *   further mutations (e.g. tweak the label, register listeners).
   */
  geojson2mapml(
    json: GeoJsonInput | string,
    options: Geojson2MapmlOptions = {}
  ): HTMLElement {
    const opts: Geojson2MapmlOptions = { ...options };
    if (opts.projection === undefined) opts.projection = this.projection;
    const layer = geojsonToMapmlLayer(json, opts, this.locale);
    this.appendChild(layer);
    return layer;
  }

  /**
   * MapML-flavoured `matchMedia`. Returns a live `MediaQueryList`-shaped
   * matcher augmented with map-specific features (`map-projection`,
   * `map-zoom`, `map-*-easting` / `map-*-northing`) plus `prefers-lang`
   * / `prefers-color-scheme` / `prefers-map-content`. See
   * [src/elements/matchMedia.ts](./matchMedia.ts) for the full feature
   * list and change-detection cadence. Mirrors MapML.js's
   * `HTMLMapmlViewerElement.prototype.matchMedia`.
   */
  matchMedia(query: string): MediaQueryList {
    return viewerMatchMedia.call(this, query);
  }

  #applySizeAttribute(name: 'width' | 'height'): void {
    const value = this.getAttribute(name);
    if (value === null || value === '') {
      this.style.removeProperty(name);
    } else {
      this.style[name] = `${Number(value)}px`;
    }
    // Tell MapLibre the container changed size so the canvas resizes.
    this.#renderer.map?.resize();
  }

  /**
   * Emit a console warning for `projection` values that the renderer cannot
   * use. Distinguishes the two failure modes:
   *   - **Unsupported**: a name that is defined by MapML but unavailable on
   *     MapLibre (`WGS84`, `CBMTILE`, `APSTILE`).
   *   - **Undefined**: any other unknown string.
   * In both cases the viewer falls back to `OSMTILE`.
   */
  #warnIfBadProjection(value: string): void {
    if (isMapmlProjection(value)) return;
    if (isUnsupportedMapmlProjection(value)) {
      console.warn(
        `MapML projection "${value}" is not supported by the MapLibre renderer; ` +
          `falling back to OSMTILE. Provide a <map-link rel="alternate" ` +
          `projection="OSMTILE" href="…"> for a Mercator equivalent.`
      );
    } else {
      console.warn(`Undefined projection: ${value}`);
    }
  }

  /**
   * Resolve the effective {@link MapmlView} from the `view` attribute,
   * with two fallbacks:
   *   - An unknown `view` value warns and resolves to `map`.
   *   - When `view` is absent but the deprecated `projection="GLOBE"`
   *     alias is present, resolve to `globe` (with a soft note).
   */
  #resolveInitialView(): MapmlView {
    const attr = this.getAttribute('view');
    if (attr !== null) {
      if (isMapmlView(attr)) return attr;
      console.warn(`Undefined view: ${attr}; falling back to "map".`);
      return 'map';
    }
    if ((this.getAttribute('projection') ?? '').toUpperCase() === 'GLOBE') {
      console.warn(
        'projection="GLOBE" is deprecated for selecting the globe camera; ' +
          'use view="globe" instead.'
      );
      return 'globe';
    }
    return 'map';
  }

  /** Registered `<map-layer>` children, in document order. */
  get layers(): readonly MapLayer[] {
    return this.#layers;
  }

  /**
   * The multi-CRS extent envelope for the *currently visible* map
   * view, in the shape MapML.js exposes on `<mapml-viewer>.extent`.
   * See {@link MapmlExtent} in `src/core/crs.ts` for the field layout.
   *
   *   - `topLeft` / `bottomRight` are derived from MapLibre's
   *     `map.getBounds()` (GCRS lon/lat corners), projected to PCRS,
   *     then handed to {@link formatPcrsExtent} to fill in the
   *     per-zoom `tcrs` / `tilematrix` arrays.
   *   - `zoom.minZoom` / `zoom.maxZoom` prefer the map's declared
   *     range (from viewer-level `<map-meta name="zoom">` or the map
   *     option) when it isn't at the projection default; otherwise
   *     they aggregate across every registered `<map-layer>.extent.zoom`
   *     \u2014 same fallback MapML.js uses when `map.getMaxZoom()` is
   *     unset.
   *
   * Returns `null` until the underlying MapLibre map is instantiated.
   */
  get extent(): MapmlExtent | null {
    const map = this.#renderer.map;
    if (!map) return null;
    const projection = this.projection;

    // MapLibre's `map.getBounds()` can wrap horizontally when zoomed
    // out (returning e.g. west < -180\u00b0 or east > 180\u00b0 to describe
    // multiple visible world copies). MapML.js's Leaflet map never
    // wraps, so its `viewer.extent` bbox always sits within the
    // primary world. Clamp to [-180, 180] for portability so
    // `topLeft.pcrs`/`.gcrs` stay inside the projection's valid range
    // and cross-implementation code reads the same values.
    const b = map.getBounds();
    const west = Math.max(-180, Math.min(180, b.getWest()));
    const east = Math.max(-180, Math.min(180, b.getEast()));
    const south = Math.max(-90, Math.min(90, b.getSouth()));
    const north = Math.max(-90, Math.min(90, b.getNorth()));
    const pcrs = gcrsCornersToPcrsBounds([west, south], [east, north]);

    // MapML.js prefers `map.getMinZoom()` / `getMaxZoom()` when the
    // author set them (via `<map-meta name="zoom">` \u2014 which we
    // forward into RendererInitOptions at init time); it falls back to
    // aggregating layer zoom ranges only when the map itself hasn't
    // been pinned. We approximate that by checking whether the viewer
    // has a `<map-meta name="zoom">` of its own; if so, the renderer's
    // min/max is authoritative. If not, we aggregate.
    let minZoom: number;
    let maxZoom: number;
    if (this.#findViewerZoomMeta() !== null) {
      minZoom = map.getMinZoom();
      maxZoom = map.getMaxZoom();
    } else {
      let acc: { minZoom: number; maxZoom: number } | null = null;
      for (const layer of this.#layers) {
        const z = layer.extent?.zoom;
        if (z === undefined || z === null) continue;
        acc =
          acc === null
            ? { minZoom: z.minZoom, maxZoom: z.maxZoom }
            : {
                minZoom: Math.min(acc.minZoom, z.minZoom),
                maxZoom: Math.max(acc.maxZoom, z.maxZoom)
              };
      }
      if (acc !== null) {
        minZoom = acc.minZoom;
        maxZoom = acc.maxZoom;
      } else {
        minZoom = 0;
        maxZoom = projectionMaxZoom(projection);
      }
    }

    return formatPcrsExtent(pcrs, projection, { minZoom, maxZoom });
  }

  registerLayer(layer: MapLayer): void {
    if (this.#layers.includes(layer)) return;
    this.#layers.push(layer);
    // Keep document order.
    this.#layers.sort((a, b) => {
      const pos = a.compareDocumentPosition(b);
      if (pos & Node.DOCUMENT_POSITION_FOLLOWING) return -1;
      if (pos & Node.DOCUMENT_POSITION_PRECEDING) return 1;
      return 0;
    });
    this.notifyLayersChanged();
  }

  unregisterLayer(layer: MapLayer): void {
    const i = this.#layers.indexOf(layer);
    if (i >= 0) {
      this.#layers.splice(i, 1);
      this.notifyLayersChanged();
    }
  }

  /**
   * Schedule a `mapml:layerschanged` dispatch on the next microtask.
   * Multiple calls in the same synchronous block (e.g. during HTML-parser
   * insertion of a `<map-layer>` subtree, where the parent's connect fires
   * before the children have finished upgrading) coalesce into a single
   * event so consumers always observe the fully-settled DOM.
   */
  notifyLayersChanged(): void {
    if (this.#layersChangedScheduled) return;
    this.#layersChangedScheduled = true;
    queueMicrotask(() => {
      this.#layersChangedScheduled = false;
      // Reassert renderer painter order from the DOM (the source of
      // truth the layer-control drag rewrites). Handles whose remote
      // content loaded after the initial layout added their native
      // layer at the TOP of the MapLibre stack; restacking here snaps
      // the whole tree back to DOM order (coalesced across the burst).
      const root = this.#renderer.root;
      if (this.#renderer.map) {
        // `#layers` is kept in document order; when every layer's group
        // is attached, re-sort root's children to match so
        // programmatically-inserted layers can't linger in connection
        // order. Each layer likewise re-sorts its own `<map-extent>`
        // children from the DOM. `reorder` cascades every leaf;
        // otherwise fall back to a plain restack until the remaining
        // groups connect.
        for (const layer of this.#layers) layer.reassertExtentOrder();
        const desired = this.#layers.map((l) => l.group);
        if (
          desired.length === root.size &&
          desired.every((g) => root.hasLayer(g))
        ) {
          root.reorder(desired);
        } else {
          root.restack();
        }
      }
      this.dispatchEvent(new CustomEvent('mapml:layerschanged'));
    });
  }

  /**
   * Register a `<map-link rel="query">` with the viewer's query-click
   * coordinator. Called from {@link MapLink}'s `#applyQuery` in place
   * of the previous per-link `map.on('click', ...)`.
   *
   * The coordinator maintains a single map-level `click` listener
   * that, on each click, walks *all* registered query links in DOM
   * order, filters by {@link MapLink.isVisible}, fires every
   * matching link's fetch in parallel, and opens a *single* popup
   * with the concatenated features. This aggregation is the
   * behaviour authors expect when multiple queryable extents cover
   * the same click point \u2014 matches MapML.js's
   * `QueryHandler._query` which does the same across all templates
   * in the top queryable layer.
   *
   * Registration is idempotent; teardown flows through
   * {@link unregisterQueryLink}. The map click listener installs
   * lazily on the first registration and uninstalls on the last
   * un-registration so viewers with no query links don't pay the
   * cost of a global click listener.
   *
   * @internal Not part of the public custom-element API surface;
   * called by MapLink only.
   */
  registerQueryLink(link: MapLink): void {
    if (this.#queryLinks.has(link)) return;
    const wasEmpty = this.#queryLinks.size === 0;
    this.#queryLinks.add(link);
    if (wasEmpty) this.#installQueryClickListener();
    // A newly-registered link may flip the "any queryable link is
    // active" predicate from false to true and reveal the reticle
    // (if the canvas is already keyboard-focused).
    this.#updateCrosshairVisibility();
    // Surface the owning layer's license in the attribution control.
    // A query-only layer registers no MapLibre source, so its
    // `<map-link rel="license">` text would otherwise be lost.
    this.#syncQueryAttributions();
  }

  /**
   * Unregister a `<map-link rel="query">` from the coordinator.
   * Uninstalls the map click listener when the last link
   * unregisters. Called from {@link MapLink}'s `#teardown`.
   *
   * @internal Not part of the public custom-element API surface.
   */
  unregisterQueryLink(link: MapLink): void {
    if (!this.#queryLinks.delete(link)) return;
    if (this.#queryLinks.size === 0) this.#uninstallQueryClickListener();
    // A removed query link can't keep contributing to an open query
    // popup — dismiss it so it doesn't linger over a layer that just
    // left the map. No-op when the open popup is a static
    // `<map-feature>` click rather than a query response.
    this.#renderer.closeQueryPopup();
    // Reticle may need to hide when the last queryable link is
    // removed (or the last visible one).
    this.#updateCrosshairVisibility();
    // Drop the (now-departed) layer's query-only attribution entry.
    this.#syncQueryAttributions();
  }

  /**
   * Push the current set of query-only layer attributions into the
   * attribution control. Reads each registered link's
   * {@link MapLink.queryAttribution} live, so this reflects the
   * present `<map-link rel="license">` state each time it runs.
   * No-op until the attribution control is installed; callers that
   * may run before install (e.g. {@link registerQueryLink} during
   * the connect race) are covered by a re-sync in
   * {@link #installAttribution}.
   */
  #syncQueryAttributions(): void {
    if (!this.#attribution) return;
    const attrs: string[] = [];
    for (const link of this.#queryLinks) {
      const a = link.queryAttribution;
      if (a) attrs.push(a);
    }
    this.#attribution.setExtraAttributions(attrs);
  }

  #installQueryClickListener(): void {
    // Defer until the renderer is ready \u2014 registrations that arrive
    // during the connect race would otherwise try to reach a null
    // map. Once the map exists this is idempotent (the guard checks
    // `#queryClickListener` first).
    void this.#renderer.whenReady().then(() => {
      if (this.#queryClickListener !== undefined) return;
      if (this.#queryLinks.size === 0) return;
      const map = this.#renderer.map;
      if (!map) return;
      const listener = (e: maplibregl.MapMouseEvent): void => {
        void this.#handleQueryClick(e);
      };
      this.#queryClickListener = listener;
      map.on('click', listener);
    });
  }

  #uninstallQueryClickListener(): void {
    const listener = this.#queryClickListener;
    if (!listener) return;
    this.#queryClickListener = undefined;
    this.#renderer.map?.off('click', listener);
  }

  /**
   * Dispatch a map-canvas click across every registered query link
   * and open a single aggregated popup with the merged results.
   *
   * Iteration walks the light-DOM `<map-link rel="query">`
   * descendants in document order (rather than the register-time
   * `#queryLinks` set, which doesn't preserve DOM order after
   * append/remove churn). Only links that are registered *and*
   * currently visible participate. Failed fetches or empty
   * responses contribute zero features but don't abort the group;
   * `Promise.allSettled` matches MapML.js's `_query` semantics.
   *
   * The popup opens once with `features = [...link1, ...link2, ...]`
   * so the nav bar's `<` / `>` cycle through them all as `1/N`
   * where N is the sum across links.
   */
  async #handleQueryClick(e: maplibregl.MapMouseEvent): Promise<void> {
    const map = this.#renderer.map;
    if (!map) return;
    // Snapshot registered links + the click / view state up front so
    // async churn between now and popup-open time doesn't shift the
    // ground under us.
    const registered = this.#queryLinks;
    if (registered.size === 0) return;
    const clickLng = e.lngLat.lng;
    const clickLat = e.lngLat.lat;

    // DOM order: walk `<map-link>` descendants and filter to the
    // subset that (a) registered themselves with the coordinator,
    // (b) satisfy {@link MapLink.isVisible} (tref present, not
    // disabled, current zoom in-range, bounds overlap the viewport)
    // and (c) whose owning `<map-extent>.renders` is true
    // (`checked` on both the extent and the parent `<map-layer>`).
    // An unchecked extent must not fire its query links even though
    // MapLibre's `click` event still fires on the canvas \u2014 matches
    // MapML.js's `queryable()`, which gates on
    // `layer.checked && !layer.hidden && rel="query"` before
    // enrolling a template in the click dispatch.
    // DOM order: walk `<map-link>` descendants and filter to the
    // subset that (a) registered themselves with the coordinator,
    // (b) satisfy {@link MapLink.isVisible} (tref present, not
    // disabled, current zoom in-range, bounds overlap the viewport)
    // and (c) whose owning `<map-extent>.renders` is true
    // (`checked` on both the extent and the parent `<map-layer>`).
    // An unchecked extent must not fire its query links even though
    // MapLibre's `click` event still fires on the canvas — matches
    // MapML.js's `queryable()`, which gates on
    // `layer.checked && !layer.hidden && rel="query"` before
    // enrolling a template in the click dispatch.
    //
    // `<map-layer src="…">` grafts extents + links into its shadow
    // root; we walk each layer's `contentRoot` so shadow-hosted
    // query links are found alongside inline ones, in DOM order.
    const domLinks: MapLink[] = [];
    for (const layer of this.#layers) {
      for (const el of layer.contentRoot.querySelectorAll<MapLink>('map-link')) {
        if (!registered.has(el)) continue;
        if (!el.isVisible()) continue;
        if (el.parentExtent?.renders !== true) continue;
        domLinks.push(el);
      }
    }
    if (domLinks.length === 0) return;

    // Fire every link's fetch concurrently. Each link handles its
    // own URL resolution, fetch, parse, and error logging \u2014 we just
    // aggregate their eventual features arrays.
    const settled = await Promise.allSettled(
      domLinks.map((link) => link.performQueryFetch(e))
    );

    const merged: QueryFeatureProperties[] = [];
    for (const r of settled) {
      if (r.status === 'fulfilled' && r.value.length > 0) {
        merged.push(...r.value);
      }
    }
    if (merged.length === 0) return;

    this.#renderer.openContentPopup({
      lngLat: [clickLng, clickLat],
      features: merged
    });
  }

  /**
   * Mount the `.mapml-crosshair` reticle inside the MapLibre map
   * container (sibling of the canvas) once the renderer is ready.
   * Wires the keyboard-focus tracker and layers-changed observer
   * that together drive {@link #updateCrosshairVisibility}.
   *
   * Called from {@link connectedCallback}; idempotent \u2014 subsequent
   * calls short-circuit when the reticle already exists.
   */
  #installCrosshair(): void {
    void this.#renderer.whenReady().then(() => {
      if (this.#crosshair !== undefined) return;
      if (!this.#connected) return;
      const map = this.#renderer.map;
      if (!map) return;
      const container = map.getContainer();
      const el = document.createElement('div');
      el.className = 'mapml-crosshair';
      el.setAttribute('hidden', '');
      // `aria-hidden` so screen readers don't announce the decorative
      // reticle. Keyboard users get their affordance from the
      // Space/Enter handler and the resulting popup's live content.
      el.setAttribute('aria-hidden', 'true');
      el.innerHTML = crosshairSvg;
      container.appendChild(el);
      this.#crosshair = el;

      // Canvas focus / mouse-vs-keyboard tracking. A keyboard-driven
      // focus event (Tab-in, or programmatic `.focus()` after a
      // keyboard-triggered popup dismissal) reveals the reticle
      // immediately; a mouse click sets `#recentPointerDown` in the
      // preceding `mousedown` handler, which suppresses the same
      // `focus` handler so mouse users don't get a spurious reticle.
      // `keydown` remains a secondary trigger for the reticle so
      // any subsequent arrow-key nav re-asserts the state after a
      // spurious clear.
      const canvas = map.getCanvas();
      canvas.addEventListener('focus', this.#onCanvasFocus);
      canvas.addEventListener('keydown', this.#onCanvasKeyDown);
      canvas.addEventListener('mousedown', this.#onCanvasMouseDown);
      canvas.addEventListener('blur', this.#onCanvasBlur);

      // Re-tally crosshair visibility when `<map-layer>` `checked`
      // or `disabled` state flips, so a user un-checking the
      // queryable layer sees the reticle disappear (matches
      // MapML.js's `Crosshair._toggleEvents` semantics via
      // `map.on('layeradd layerremove overlayremove', \u2026)`).
      this.addEventListener('mapml:layerschanged', this.#updateCrosshairVisibility);

      // `mapml:layerschanged` fires for most layer-state changes but
      // deliberately skips the `<map-extent[checked]>` toggle path
      // (to avoid a LayerControl rebuild feedback loop). Watch the
      // relevant attributes directly so the reticle reacts to author
      // (or user) toggling `checked` / `disabled` / `hidden` on
      // `<map-layer>` / `<map-extent>` / `<map-link>` regardless of
      // which internal signal path the change flowed through.
      this.#queryableAttrObserver = new MutationObserver(() => {
        this.#updateCrosshairVisibility();
      });
      this.#queryableAttrObserver.observe(this, {
        attributes: true,
        attributeFilter: ['checked', 'disabled', 'hidden'],
        subtree: true
      });
    });
  }

  /**
   * Uninstall the crosshair reticle and its event listeners. Called
   * from {@link disconnectedCallback}.
   */
  #uninstallCrosshair(): void {
    const map = this.#renderer.map;
    const canvas = map?.getCanvas();
    canvas?.removeEventListener('focus', this.#onCanvasFocus);
    canvas?.removeEventListener('keydown', this.#onCanvasKeyDown);
    canvas?.removeEventListener('mousedown', this.#onCanvasMouseDown);
    canvas?.removeEventListener('blur', this.#onCanvasBlur);
    this.removeEventListener('mapml:layerschanged', this.#updateCrosshairVisibility);
    this.#queryableAttrObserver?.disconnect();
    this.#queryableAttrObserver = null;
    this.#crosshair?.remove();
    this.#crosshair = undefined;
    this.#mapKeyboardFocused = false;
    this.#recentPointerDown = false;
  }

  /**
   * `focus` handler on the canvas. Reveals the crosshair as soon as
   * the map takes keyboard focus, so a Tab-in — or a programmatic
   * focus restore following a keyboard-driven popup dismissal or a
   * zoom-to-here link activation — immediately shows the reticle.
   * Suppressed when a `mousedown` on the same canvas just fired
   * (browsers dispatch `mousedown` before `focus` for a click on a
   * tabbable element, so mouse-triggered focus is filtered here).
   */
  #onCanvasFocus = (): void => {
    if (this.#recentPointerDown) return;
    if (!this.#mapKeyboardFocused) {
      this.#mapKeyboardFocused = true;
      this.#updateCrosshairVisibility();
    }
  };

  #onCanvasKeyDown = (e: KeyboardEvent): void => {
    // Bail out entirely while the map context menu is open. MapML.js
    // gates its own keydown handling on `_mapMenuVisible`, so arrow
    // keys and single-letter shortcuts route through the menu (not
    // through the canvas pan / query pipeline). Without this the
    // canvas would preventDefault ArrowUp/Down/Left/Right for its
    // own pan handler and steal them from the menu.
    if (this.#contextMenu?.isOpen) return;
    // Belt-and-braces: `focus` should have already flipped us into
    // keyboard-nav mode, but arrow-key nav after a mouse blip
    // re-asserts here too.
    if (!this.#mapKeyboardFocused) {
      this.#mapKeyboardFocused = true;
      this.#updateCrosshairVisibility();
    }
    // Space (' ') or Enter fires a synthetic click at the map centre
    // \u2014 the keyboard equivalent of clicking the reticle. Guards on
    // the crosshair being visible so we don't query when there's no
    // queryable layer to query (matches MapML.js's
    // `_queryTopLayerAtMapCenter` which returns early when
    // `map.isFocused` is false or no queryable layer is present).
    if (e.key === ' ' || e.key === 'Enter') {
      if (this.#crosshair?.hasAttribute('hidden')) return;
      // Space would otherwise scroll the page, and Enter might
      // submit an ancestor form; suppress both.
      e.preventDefault();
      this.#triggerKeyboardQuery(e);
      return;
    }
    // Arrow-key pan + `+`/`-` zoom. MapLibre's default keyboard
    // handler is disabled in the renderer's `init` so we can provide
    // MapML.js parity here: base pan step 80 CSS px, Shift multiplies
    // by 3 (bigger pan), Ctrl divides by 5 (smaller pan). Zoom
    // shortcuts are `=`/`+` (in) and `-`/`_` (out); Shift multiplies
    // the zoom delta by 3. Matches Leaflet's
    // `L.Map.Keyboard.keyCodes` + MapML.js's `handlers/keyboard.js`
    // override.
    if (e.altKey || e.metaKey) return;
    const map = this.#renderer.map;
    if (!map) return;
    if (
      e.key === 'ArrowLeft' ||
      e.key === 'ArrowRight' ||
      e.key === 'ArrowUp' ||
      e.key === 'ArrowDown'
    ) {
      const basePan = 80;
      const factor = e.shiftKey ? 3 : e.ctrlKey ? 1 / 5 : 1;
      const step = basePan * factor;
      let dx = 0;
      let dy = 0;
      if (e.key === 'ArrowLeft') dx = -step;
      else if (e.key === 'ArrowRight') dx = step;
      else if (e.key === 'ArrowUp') dy = -step;
      else if (e.key === 'ArrowDown') dy = step;
      e.preventDefault();
      map.panBy([dx, dy], { duration: 0 });
      return;
    }
    if (
      e.key === '=' ||
      e.key === '+' ||
      e.key === '-' ||
      e.key === '_'
    ) {
      const delta = e.key === '=' || e.key === '+' ? 1 : -1;
      const magnitude = e.shiftKey ? 3 : 1;
      e.preventDefault();
      map.setZoom(map.getZoom() + delta * magnitude);
      return;
    }
  };

  #onCanvasMouseDown = (): void => {
    // Mouse click clears the keyboard-focus indicator \u2014 mouse
    // users don't need the reticle since they can click where they
    // want. Matches MapML.js's Crosshair which flips `isFocused`
    // to false on `mousedown`. Also flags the following `focus`
    // event as mouse-triggered so {@link #onCanvasFocus} doesn't
    // re-reveal the reticle on the same click.
    this.#recentPointerDown = true;
    setTimeout(() => {
      this.#recentPointerDown = false;
    }, 0);
    if (this.#mapKeyboardFocused) {
      this.#mapKeyboardFocused = false;
      this.#updateCrosshairVisibility();
    }
  };

  #onCanvasBlur = (): void => {
    if (this.#mapKeyboardFocused) {
      this.#mapKeyboardFocused = false;
      this.#updateCrosshairVisibility();
    }
  };

  /**
   * Toggle the reticle's `hidden` attribute based on the current
   * (keyboard-focus AND at-least-one-actively-queryable-link) state.
   *
   * The "queryable" check mirrors MapML.js's `layer.queryable()`:
   * a link contributes iff it's registered with the coordinator
   * (i.e. was ever successfully `#applyQuery`-ed), passes
   * {@link MapLink.isVisible} (has a tref, not disabled, its zoom /
   * bounds cover the current view), AND its owning `<map-extent>`
   * currently `renders` (both the extent and parent `<map-layer>`
   * are `checked` and the extent isn't `disabled`). This is the
   * same gate {@link #handleQueryClick} uses to decide which links
   * fire, so the reticle is exactly present when a keyboard query
   * would actually do something.
   */
  #updateCrosshairVisibility = (): void => {
    if (!this.#crosshair) return;
    const shouldShow =
      this.#mapKeyboardFocused && this.#anyQueryLinkActive();
    if (shouldShow) this.#crosshair.removeAttribute('hidden');
    else this.#crosshair.setAttribute('hidden', '');
  };

  #anyQueryLinkActive(): boolean {
    for (const link of this.#queryLinks) {
      if (!link.isVisible()) continue;
      if (link.parentExtent?.renders !== true) continue;
      return true;
    }
    return false;
  }

  /**
   * Fire a synthetic click at the map's current centre through the
   * viewer's query-click coordinator. Reuses the entire click \u2192
   * fetch \u2192 popup pipeline so a Space/Enter keyboard trigger is
   * indistinguishable (from the popup's perspective) from a mouse
   * click at the centre. Ports MapML.js's
   * `QueryHandler._queryTopLayerAtMapCenter`.
   */
  #triggerKeyboardQuery(originalEvent: KeyboardEvent): void {
    const map = this.#renderer.map;
    if (!map) return;
    const centre = map.getCenter();
    const point = map.project(centre);
    // Build the minimum `MapMouseEvent`-shaped object the
    // coordinator + downstream `performQueryFetch` read: `lngLat`
    // (for click-point substitution + popup anchor) and `point`
    // (for cursor pixel i/j templates). The other MapLibre fields
    // are un-consulted downstream but included for defensive
    // hygiene.
    const mockEvent = {
      lngLat: centre,
      point,
      originalEvent: originalEvent as unknown as MouseEvent,
      target: map,
      type: 'click',
      defaultPrevented: false,
      preventDefault: () => {
        /* no-op */
      }
    } as unknown as maplibregl.MapMouseEvent;
    void this.#handleQueryClick(mockEvent);
  }

  /**
   * Commit a `<map-layer>` reorder produced by drag-to-reorder in the
   * layer control. `newOrder` is the intended final DOM order (top of
   * the visible stack last, matching MapML.js's z-index convention).
   *
   * Behaviour, ported from MapML.js's mouse/touch drop handler in
   * `createLayerControlForLayer.js`:
   *   1. Each `<map-layer>` in the new order is re-appended to the
   *      viewer, tagged with `data-moving` first so its connect/
   *      disconnect callbacks (and its extents' and links') no-op —
   *      the renderer layers survive the DOM move intact.
   *   2. The viewer's cached `#layers` array is resorted by document
   *      position.
   *   3. Renderer layers owned by each `<map-layer>` are moved to the
   *      top of the MapLibre stack in the new DOM order. Because
   *      `moveLayer(id)` (no `beforeId`) inserts at the top, iterating
   *      DOM-bottom-to-top leaves the last-moved on top.
   *   4. `mapml:layerschanged` is dispatched so the layer control
   *      (and anyone else observing) rebuilds against the new order.
   */
  applyLayerReorder(newOrder: readonly MapLayer[]): void {
    if (newOrder.length === 0) return;
    // Move each layer to end-of-viewer in the intended order. Because
    // `appendChild` on an already-parented node moves rather than
    // duplicates, the final result is that light-DOM order matches
    // `newOrder`.
    for (const layer of newOrder) {
      layer.setAttribute('data-moving', '');
      this.appendChild(layer);
      layer.removeAttribute('data-moving');
    }
    // The cached `#layers` array wasn't touched by register/unregister
    // during the move; resort it from the fresh DOM order.
    this.#resortLayers();
    // Restack via a single `root.reorder(...)` call — the group
    // cascade walks every leaf in the tree (each layer group +
    // its child extent groups + their handles) in the new order
    // and calls `moveAbove` on each. Extent groups are children of
    // their owning layer groups, so we only reorder root here.
    this.#renderer.root.reorder(this.#layers.map((l) => l.group));
    this.notifyLayersChanged();
  }

  /**
   * Commit a `<map-extent>` reorder within `owningLayer`. Same
   * mechanics as {@link applyLayerReorder} but scoped to the extents
   * of a single parent `<map-layer>`. Ports the drop handler from
   * MapML.js's `createLayerControlForExtent.js`.
   */
  applyExtentReorder(owningLayer: MapLayer, newOrder: readonly MapExtent[]): void {
    if (newOrder.length === 0) return;
    for (const extent of newOrder) {
      extent.setAttribute('data-moving', '');
      owningLayer.appendChild(extent);
      extent.removeAttribute('data-moving');
    }
    // Reorder the extent groups within their owning layer's group.
    // The layer group's own reorder cascade restacks each extent's
    // leaves in the new DOM order.
    owningLayer.group.reorder(newOrder.map((e) => e.group));
    this.notifyLayersChanged();
  }

  /** Resort `#layers` by document position, without mutating membership. */
  #resortLayers(): void {
    this.#layers.sort((a, b) => {
      const pos = a.compareDocumentPosition(b);
      if (pos & Node.DOCUMENT_POSITION_FOLLOWING) return -1;
      if (pos & Node.DOCUMENT_POSITION_PRECEDING) return 1;
      return 0;
    });
  }

  /** Number of entries currently in the history ring. */
  get historyLength(): number {
    return this.#history.length;
  }

  /** Zero-based index of the active history entry, or -1 if empty. */
  get historyIndex(): number {
    return this.#historyIndex;
  }

  /**
   * Rewind to the initial (oldest) history entry and reset the ring to
   * contain only that entry.
   */
  reload(): void {
    const map = this.#renderer.map;
    if (!map || this.#history.length === 0) return;
    const initial = this.#history[0]!;
    this.#history = [initial];
    this.#historyIndex = 0;
    this.#traversalCall = 1;
    this.#dispatchHistoryChanged();
    this.#applyHistoryEntry(initial);
    map.getCanvas().focus();
  }

  /** Move one step back through the history ring, if possible. */
  back(): void {
    if (this.#historyIndex <= 0) return;
    const map = this.#renderer.map;
    if (!map) return;
    this.#historyIndex--;
    const prev = this.#history[this.#historyIndex]!;
    this.#traversalCall = 1;
    this.#dispatchHistoryChanged();
    this.#applyHistoryEntry(prev);
  }

  /** Move one step forward through the history ring, if possible. */
  forward(): void {
    if (this.#historyIndex + 1 >= this.#history.length) return;
    const map = this.#renderer.map;
    if (!map) return;
    this.#historyIndex++;
    const next = this.#history[this.#historyIndex]!;
    this.#traversalCall = 1;
    this.#dispatchHistoryChanged();
    this.#applyHistoryEntry(next);
  }

  /**
   * Switch the presentation / camera regime to `view`: track the
   * resolved mode, reflect the `view` attribute, apply the renderer's
   * projection + tilt locks, and broadcast `mapml:viewchanged` so the
   * {@link ViewControl} (and any author listener) can update. No-op
   * when already in `view`.
   */
  #applyView(view: MapmlView): void {
    if (view === this.#view) return;
    this.#view = view;
    this.setAttribute('view', view);
    this.#renderer.applyViewMode(view);
    this.dispatchEvent(
      new CustomEvent('mapml:viewchanged', { detail: { view } })
    );
  }

  /**
   * Apply a snapshotted {@link HistoryEntry} to the map — the single
   * restore path used by {@link reload}, {@link back}, and
   * {@link forward}.
   *
   * Restores the full camera state: the `view` regime (projection +
   * tilt locks, via {@link MapRenderer.applyViewMode}) plus centre /
   * zoom / bearing / pitch. `projection` (the CRS) is captured on the
   * entry but not re-applied — live CRS switching isn't supported in v1
   * (see {@link attributeChangedCallback}'s `projection` branch); the
   * `view` camera regime is separate and *is* restored.
   */
  #applyHistoryEntry(entry: HistoryEntry): void {
    const map = this.#renderer.map;
    if (!map) return;
    // Restore the camera regime first (projection + tilt locks) so the
    // subsequent jumpTo's bearing / pitch are honoured. Reflect the
    // `view` attribute + track the resolved mode.
    this.#applyView(entry.view);
    map.jumpTo({
      center: entry.center,
      zoom: entry.zoom,
      bearing: entry.bearing,
      pitch: entry.pitch
    });
  }

  /**
   * After MapLibre's first `load` fires, apply any author-supplied
   * `<map-meta name="extent">` as the initial view (when no explicit
   * `lat`/`lon`/`zoom` attributes are set), then prime the history ring
   * with that view as the first entry.
   */
  async #initialView(): Promise<void> {
    await this.#renderer.whenReady();
    if (!this.#connected) return;
    const map = this.#renderer.map;
    if (!map) return;

    const hasExplicitView =
      this.hasAttribute('lat') ||
      this.hasAttribute('lon') ||
      this.hasAttribute('zoom');
    if (!hasExplicitView) {
      const extentMeta = this.#findViewerExtentMeta();
      if (extentMeta !== null) {
        const [minLon, minLat] = osmtilePcrsToGcrs(
          extentMeta.bounds.min[0],
          extentMeta.bounds.min[1]
        );
        const [maxLon, maxLat] = osmtilePcrsToGcrs(
          extentMeta.bounds.max[0],
          extentMeta.bounds.max[1]
        );
        map.fitBounds([[minLon, minLat], [maxLon, maxLat]], {
          animate: false,
          padding: 0
        });
        if (extentMeta.zoom !== undefined) map.setZoom(extentMeta.zoom);
      }
    } else {
      // Re-assert the authored centre / zoom now that the style (and, for
      // `view="globe"`, the globe projection) has finished loading.
      // MapLibre's globe can leave its camera at latitude 0 until the first
      // explicit camera command — a construction-time race whose outcome
      // varies by browser/timing — so this fresh `jumpTo` makes the initial
      // view deterministic (it's what a manual `zoomTo` to the same values
      // does). It's a no-op when construction already applied the camera,
      // and runs before the `moveend` handler is wired below, so it neither
      // reflects attributes nor records a spurious history entry.
      map.jumpTo({ center: [this.lon, this.lat], zoom: this.zoom });
    }

    this.#history = [this.#captureCurrentView()];
    this.#historyIndex = 0;
    map.on('moveend', this.#onMoveEnd);
    // Re-tally per-view disabled state whenever the map view changes.
    // Extents flip disabled/enabled as their bounds move in/out of the
    // viewport (and as the current zoom leaves each link's zoom
    // range). Matches MapML.js's `_validateDisabled` firing on
    // `moveend` inside `TemplatedTileLayer._handleMoveEnd`.
    map.on('moveend', this.#revalidateDisabled);
    // Run once now so the initial view already reflects any
    // out-of-view layers as disabled.
    this.#revalidateDisabled();
    this.#dispatchHistoryChanged();
  }

  /**
   * Look up a direct-child `<map-meta name="extent">` of this viewer
   * (ignoring nested `<map-meta>` inside `<map-layer>`) and parse its
   * content. Returns `null` when absent or malformed. Reprojection
   * uses the viewer's own `projection`, so PCRS / TCRS / TILEMATRIX
   * / GCRS extents are all accepted uniformly.
   */
  #findViewerExtentMeta(): ExtentMeta | null {
    const direct = this.querySelector(
      ':scope > map-meta[name="extent"]'
    ) as MapMeta | null;
    if (direct === null) return null;
    return parseExtentMeta(direct.content, this.projection);
  }

  /**
   * Look up a direct-child `<map-meta name="zoom" content="min=…,max=…">`
   * and parse its content. Returns `null` when absent or malformed.
   *
   * Reads `content` via `getAttribute` rather than the `MapMeta.content`
   * getter because element upgrade order is not guaranteed \u2014 our
   * `connectedCallback` can fire while a light-DOM `<map-meta>`
   * child is still an unupgraded `HTMLElement`, on which `.content`
   * returns `undefined` and crashes {@link parseZoomMeta}'s
   * `String.prototype.split` call.
   */
  #findViewerZoomMeta(): ZoomMeta | null {
    const direct = this.querySelector(':scope > map-meta[name="zoom"]');
    if (direct === null) return null;
    return parseZoomMeta(direct.getAttribute('content'));
  }

  #captureCurrentView(): HistoryEntry {
    const map = this.#renderer.map!;
    const c = map.getCenter();
    const projAttr = this.getAttribute('projection') ?? 'OSMTILE';
    const projection: MapmlProjection = isMapmlProjection(projAttr) ? projAttr : 'OSMTILE';
    return {
      center: [c.lng, c.lat],
      zoom: map.getZoom(),
      bearing: map.getBearing(),
      pitch: map.getPitch(),
      view: this.#view,
      projection
    };
  }

  /**
   * Reflect the map's current centre / zoom / camera back onto the
   * `lat` / `lon` / `zoom` / `bearing` / `pitch` attributes. Ports
   * MapML.js's `_updateMapCenter`, called from its `moveend` handler.
   *
   * Safe to write these attributes freely: {@link attributeChangedCallback}
   * short-circuits them (they're state reflection, not configuration),
   * so no re-entrance is possible.
   *
   * Writes go through the property setters, so MapML.js's parsing /
   * validation semantics apply — notably, fractional MapLibre zooms
   * are truncated to their integer part by {@link zoom}'s setter.
   * `bearing` / `pitch` are only reflected in tilt-capable views; in
   * `map` view they're pinned to 0 and left off the markup to keep it
   * clean.
   */
  #updateViewAttrs(): void {
    const map = this.#renderer.map;
    if (map === undefined) return;
    const c = map.getCenter();
    this.lat = c.lat;
    this.lon = c.lng;
    this.zoom = map.getZoom();
    if (viewProfile(this.#view).allowTilt) {
      this.bearing = map.getBearing();
      this.pitch = map.getPitch();
    } else {
      // `map` view pins the camera flat; drop any lingering bearing /
      // pitch markup (e.g. left over from a prior tilt-capable view) so
      // the reflected attributes don't lie. The getters return 0 when
      // the attributes are absent, matching the pinned camera.
      this.removeAttribute('bearing');
      this.removeAttribute('pitch');
    }
  }

  #onMoveEnd = (): void => {
    // Reflect the new centre / zoom back to `lat` / `lon` / `zoom`
    // attributes on every moveend — even on traversal (back /
    // forward / reload) calls, so scripts reading the attributes
    // after a programmatic view change see the new values. Matches
    // MapML.js's `_setUpEvents` order: `_updateMapCenter()` first,
    // `_addToHistory()` second — the traversal-skip only applies
    // to history.
    this.#updateViewAttrs();
    // Broadcast a `map-moveend` DOM event so `viewer.matchMedia(…)`
    // matchers (and any author-registered listeners) can re-evaluate
    // their `map-zoom` / `map-*-easting` / `map-*-northing`
    // features. Matches MapML.js's `map-moveend` dispatch in
    // `src/mapml-viewer.js` (fired from its own `moveend` handler).
    this.dispatchEvent(
      new CustomEvent('map-moveend', { detail: { target: this } })
    );
    if (this.#traversalCall > 0) {
      this.#traversalCall--;
      return;
    }
    const entry = this.#captureCurrentView();
    // Don't push a duplicate entry — e.g. when MapLibre clamps a
    // zoom-out request that's already at min zoom, moveend still fires
    // but no actual movement happened.
    const current = this.#history[this.#historyIndex];
    const isDuplicate =
      current !== undefined &&
      current.zoom === entry.zoom &&
      current.center[0] === entry.center[0] &&
      current.center[1] === entry.center[1] &&
      current.bearing === entry.bearing &&
      current.pitch === entry.pitch &&
      current.view === entry.view;
    if (!isDuplicate) {
      // Truncate any forward branch and append.
      this.#history.length = this.#historyIndex + 1;
      this.#history.push(entry);
      this.#historyIndex++;
      if (this.#history.length > MapmlViewer.HISTORY_LIMIT) {
        const overflow = this.#history.length - MapmlViewer.HISTORY_LIMIT;
        this.#history.splice(0, overflow);
        this.#historyIndex -= overflow;
      }
      this.#dispatchHistoryChanged();
    }
    // Screen-reader announcement — runs on every non-traversal
    // moveend regardless of whether an entry was pushed. Matches
    // MapML.js's `AnnounceMovement.announceBounds`, which fires on
    // every `map-moveend` when the handler is enabled, including
    // clamped-to-min-zoom no-ops where the moveend fires but nothing
    // actually moved. Bounces the map back to the previous history
    // entry when the new view falls outside the aggregate layer
    // bounds.
    if (this.#announceMovementOutput) {
      this.#announceMovement(isDuplicate);
    }
  };

  /**
   * Re-run every `<map-extent>`'s disabled check, then let each
   * `<map-layer>` re-tally. Fired on `moveend` (bounds may now
   * overlap / not overlap each extent's declared bounds; current zoom
   * may have entered / left a link's zoom range). Also called once
   * from {@link connectedCallback}'s post-load hook so the initial
   * view already flags any out-of-view extents.
   *
   * The extent's own `<map-input>` and `<map-meta>` don't change per
   * moveend, so `<map-extent>.extent` is stable across this call \u2014
   * only the *intersection* with `<mapml-viewer>.extent` changes. The
   * layer's tally is a pure function of its extents' disabled state,
   * so the layer control only rebuilds if at least one extent flipped
   * (via `notifyLayersChanged`'s coalescer).
   */
  #revalidateDisabled = (): void => {
    for (const layer of this.#layers) {
      // `layer.contentRoot` returns the layer's shadow root when it
      // carries a `src` attribute (remote-content mode), else the
      // layer element itself. Iterating that root's `.children`
      // yields the grafted `<map-extent>`s in either case.
      for (const child of layer.contentRoot.children) {
        if (child.tagName.toLowerCase() !== 'map-extent') continue;
        const ext = child as HTMLElement & { validateDisabled?: () => boolean };
        ext.validateDisabled?.();
      }
      layer.validateDisabled();
    }
  };

  #dispatchHistoryChanged(): void {
    this.dispatchEvent(
      new CustomEvent('mapml:historychanged', {
        detail: { length: this.#history.length, index: this.#historyIndex }
      })
    );
  }

  /**
   * Installs the attribution control. Called once from {@link connectedCallback};
   * lives outside {@link #installControls} so the `controls` attribute and
   * `controlslist` tokens can never hide it. Authors who forget
   * `<map-link rel="license">` still get haunted by the Maps for HTML
   * Community Group attribution in the compact popover.
   *
   * The `customAttribution` value is the Maps4HTML Community Group icon
   * (base64-inlined W3C-CG icon, mirrored from MapML.js's `AttributionButton.js`)
   * plus a link. MapLibre appends this to whatever the tile sources supply.
   */
  async #installAttribution(): Promise<void> {
    await this.#renderer.whenReady();
    if (!this.#connected || this.#attribution) return;

    this.#attribution = new MapmlAttributionControl({
      compact: true,
      customAttribution: MAPS4HTML_ATTRIBUTION_HTML,
      locale: this.locale
    });
    this.#renderer.addControl(this.#attribution, 'bottom-right');

    // Query links may have registered before the control existed
    // (connect race); surface their layers' licenses now.
    this.#syncQueryAttributions();

    const map = this.#renderer.map;
    if (!map) return;

    const attrib = map
      .getContainer()
      .querySelector<HTMLDetailsElement>('.maplibregl-ctrl-attrib');
    if (attrib) {
      // Match MapML.js's ARIA shape so screen readers announce the
      // attribution as a labelled group.
      attrib.setAttribute('role', 'group');
      attrib.setAttribute('aria-label', 'Map data attribution');
    }
    // MapLibre opens the compact <details> on initial render and can
    // re-open it when a source's attribution lands late (after an early
    // `idle`). Collapse now if the map is already settled, and on every
    // `idle` thereafter — the op is idempotent, and once MapLibre's
    // `maplibregl-compact` class is set the panel no longer re-opens.
    const collapse = (): void => {
      const a = map
        .getContainer()
        .querySelector<HTMLDetailsElement>('.maplibregl-ctrl-attrib');
      if (a) {
        a.removeAttribute('open');
        a.classList.remove('maplibregl-compact-show');
      }
    };
    if (map.loaded()) collapse();
    map.on('idle', collapse);
  }

  async #installControls(): Promise<void> {
    await this.#renderer.whenReady();
    if (!this.#connected || !this.hasAttribute('controls')) return;

    // Order matters: MapLibre stacks each position vertically in install order.
    // `controlslist` tokens gate each install decision. Subtractive tokens
    // (`nozoom`, `noreload`, `nofullscreen`, `nolayer`, `noscale`) skip a
    // default-on control; additive tokens (`geolocation`, `search`) opt
    // *in* to a default-off control. See CONTROLSLIST_TOKENS.
    const list = this.#controlsList;
    const has = (token: string): boolean => !!list && list.contains(token);

    // top-left: zoom, search, reload, fullscreen (order matches
    // MapML.js `_createControls`; MapLibre stacks each position
    // vertically in install order).
    if (!this.#controls.nav && !has('nozoom')) {
      this.#controls.nav = new maplibregl.NavigationControl({ showCompass: false });
      this.#renderer.addControl(this.#controls.nav, 'top-left');
    }
    if (!this.#controls.search && has('search')) {
      // Matches MapML.js's `_createControls`: search is the 2nd
      // top-left slot, immediately after zoom and before reload.
      // The button is always accepted; the search UI gracefully
      // no-ops when no checked `<map-layer>` advertises a
      // `<map-link rel="search">`.
      const search = new MapmlSearchControl(this);
      this.#controls.search = search;
      this.#renderer.addControl(search, 'top-left');
    }
    if (!this.#controls.reload && !has('noreload')) {
      this.#controls.reload = new ReloadButton(this);
      this.#renderer.addControl(this.#controls.reload, 'top-left');
    }
    if (!this.#controls.fullscreen && !has('nofullscreen')) {
      // Fullscreen the viewer host (not just the map container) so the
      // shadow-DOM context menu, which is a sibling of the map container,
      // remains rendered in fullscreen mode.
      this.#controls.fullscreen = new maplibregl.FullscreenControl({ container: this });
      this.#renderer.addControl(this.#controls.fullscreen, 'top-left');
    }

    // top-right: layer control (and its right-click menu piggybacks on the
    // same `nolayer` gate — no menu if there's no control to target)
    if (!this.#controls.layerControl && !has('nolayer')) {
      this.#controls.layerControl = new LayerControl(this);
      this.#renderer.addControl(this.#controls.layerControl, 'top-right');
    }
    if (!this.#controls.layerContextMenu && !has('nolayer')) {
      // Owns the .mapml-layer-menu / .mapml-extent-menu right-click menus
      // that target the LayerControl's fieldsets. Independent of the main
      // map-canvas ContextMenu, but mounted in the same shadow root so its
      // positioning is unconstrained by MapLibre's control wells.
      this.#controls.layerContextMenu = new LayerContextMenu(
        this,
        this.shadowRoot!,
        this.locale
      );
    }
    // top-right (below the layer control, above the view toggle): compass.
    // Opt-in via `controlslist="compass"` (default-off). Installed after the
    // LayerControl so MapLibre stacks it beneath.
    if (!this.#controls.compass && has('compass')) {
      this.#controls.compass = new CompassControl(this);
      this.#renderer.addControl(this.#controls.compass, 'top-right');
    }
    // top-right (below the compass): view toggle. Opt-in via
    // `controlslist="view"` (default-off, like search / geolocation).
    // Installed after the compass so MapLibre stacks it beneath.
    if (!this.#controls.viewControl && has('view')) {
      this.#controls.viewControl = new ViewControl(this);
      this.#renderer.addControl(this.#controls.viewControl, 'top-right');
    }
    // top-right (below the view toggle): static toggle. Opt-in via
    // `controlslist="static"` (default-off). Installed after the
    // ViewControl so MapLibre stacks it beneath.
    if (!this.#controls.staticControl && has('static')) {
      this.#controls.staticControl = new StaticControl(this);
      this.#renderer.addControl(this.#controls.staticControl, 'top-right');
    }
    // top-right (below the static toggle): feature-index overlay toggle.
    // Opt-in via `controlslist="featureindex"` (default-off). Installed
    // after the StaticControl so MapLibre stacks it beneath.
    if (!this.#controls.featureIndexControl && has('featureindex')) {
      this.#controls.featureIndexControl = new FeatureIndexControl(this);
      this.#renderer.addControl(this.#controls.featureIndexControl, 'top-right');
    }

    // bottom-left: scale
    if (!this.#controls.scale && !has('noscale')) {
      this.#controls.scale = new MapmlScaleControl({ unit: 'metric' });
      this.#renderer.addControl(this.#controls.scale, 'bottom-left');
    }

    // bottom-right: attribution is sacred and installed elsewhere (see
    // #installAttribution / connectedCallback). Geolocate stacks above it
    // when opted in via `controlslist="geolocation"`.
    if (!this.#controls.geolocate && has('geolocation')) {
      // Use a local so subsequent reads narrow cleanly (property
      // assignment on `#controls.geolocate` doesn't propagate the
      // non-undefined refinement across the `addControl` call).
      const geolocate = new MapmlGeolocateControl(
        {
          positionOptions: { enableHighAccuracy: false },
          trackUserLocation: true
        },
        this.locale
      );
      this.#controls.geolocate = geolocate;
      this.#renderer.addControl(geolocate, 'bottom-right');
    }
  }

  /**
   * Installs the map-level context menu. Sacred lifecycle: called once
   * from {@link connectedCallback}, torn down only on disconnect. Lives
   * outside {@link #installControls} because the menu itself is how the
   * user (via right-click, `Shift+F10`, or the ContextMenu key) or
   * shortcut (`T`) flips the `controls` attribute back on — destroying
   * it with `controls=false` would strand them.
   *
   * Matches MapML.js, where the map's context menu is enabled at map
   * construction (`contextMenu: true`) and individual items are
   * enabled/disabled rather than the whole menu torn down.
   */
  #installContextMenu(): void {
    if (this.#contextMenu) return;
    this.#contextMenu = new ContextMenu(this, this.shadowRoot!, this.locale);
  }

  /**
   * Wire `dragover` + `drop` listeners on the viewer host so authors
   * (or their users) can drag a `<map-layer>` snippet, `<map-feature>`
   * snippet, absolute URL, or GeoJSON blob onto the map and have it
   * appended as a new layer. Ports the `_dropHandler` / `_dragoverHandler`
   * pair from `../MapML.js/src/mapml-viewer.js#_setUpEvents`.
   *
   * Behaviour (parity with MapML.js):
   *   - `dragover`: preventDefault + set `dropEffect = 'copy'` so the
   *     browser shows a "copy" cursor and actually delivers the drop
   *     (the default handler cancels drops on elements that aren't
   *     drop targets).
   *   - `drop`: preventDefault, pull `dataTransfer.getData('text')`,
   *     and hand it to {@link pasteToViewer} — same routing as the
   *     context-menu Paste item and Ctrl+V, so drop / paste / click-
   *     paste all support the same set of inputs.
   *
   * Both listeners are installed on the viewer host (not the shadow-
   * DOM container) so authors can drop anywhere on the map surface,
   * including into gaps between MapLibre-owned controls.
   */
  #installDragDropHandlers(): void {
    if (this.#boundDropHandler !== null) return;
    this.#boundDropHandler = (event: DragEvent): void => {
      event.preventDefault();
      const text = event.dataTransfer?.getData('text') ?? '';
      if (!text) return;
      void pasteToViewer(this, text, this.locale);
    };
    this.#boundDragoverHandler = (event: DragEvent): void => {
      event.preventDefault();
      if (event.dataTransfer) event.dataTransfer.dropEffect = 'copy';
    };
    this.addEventListener('drop', this.#boundDropHandler);
    this.addEventListener('dragover', this.#boundDragoverHandler);
  }

  #uninstallDragDropHandlers(): void {
    if (this.#boundDropHandler !== null) {
      this.removeEventListener('drop', this.#boundDropHandler);
      this.#boundDropHandler = null;
    }
    if (this.#boundDragoverHandler !== null) {
      this.removeEventListener('dragover', this.#boundDragoverHandler);
      this.#boundDragoverHandler = null;
    }
  }

  /**
   * Mount the screen-reader live region used by
   * `M.options.announceMovement`. Ports the observable-DOM half of
   * `../MapML.js/src/mapml/handlers/AnnounceMovement.js` \u2014 the
   * actual per-moveend announcement logic lives in
   * {@link #announceMovement}, driven from {@link #onMoveEnd}.
   *
   * The `<output>` is appended to the viewer's shadow root as its
   * first `<output>` child so `shadowRoot.querySelector('output')`
   * returns this one (matching the upstream test selector); it sits
   * ahead of `MapmlScaleControl`'s own hidden output which lives
   * inside the MapLibre container. `role="status"` +
   * `aria-live="polite"` + `aria-atomic="true"` mirror the ARIA
   * shape MapML.js declares in `mapml.css` for
   * `.mapml-screen-reader-output`.
   */
  #installAnnounceMovement(): void {
    if (this.#announceMovementOutput !== null) return;
    const output = document.createElement('output');
    output.className = 'mapml-screen-reader-output';
    output.setAttribute('role', 'status');
    output.setAttribute('aria-live', 'polite');
    output.setAttribute('aria-atomic', 'true');
    // Prepend so this `<output>` sits ahead of the scale control's
    // own `<output>` (which lives inside `#container`), keeping
    // `shadowRoot.querySelector('output')` pointing at this one.
    this.shadowRoot!.insertBefore(output, this.shadowRoot!.firstChild);
    this.#announceMovementOutput = output;
  }

  #uninstallAnnounceMovement(): void {
    this.#announceMovementOutput?.remove();
    this.#announceMovementOutput = null;
  }

  /**
   * Compute the aggregate `<map-layer>` PCRS extent \u2014 union of
   * every registered layer's `extent.topLeft/bottomRight.pcrs`. Used
   * by {@link #announceMovement} to detect out-of-bounds moves so
   * they can be bounced back to the last in-bounds view.
   *
   * Returns `null` when no layer has a computable extent yet
   * (`viewer.extent` before any layer registers, or an empty viewer).
   * Ports the fold done by MapML.js's `AnnounceMovement.totalBounds`.
   */
  #totalLayerPcrsBounds(): PcrsBounds | null {
    let acc: PcrsBounds | null = null;
    for (const layer of this.#layers) {
      const ext = layer.extent;
      if (ext === null) continue;
      const bounds: PcrsBounds = {
        min: [ext.topLeft.pcrs.horizontal, ext.bottomRight.pcrs.vertical],
        max: [ext.bottomRight.pcrs.horizontal, ext.topLeft.pcrs.vertical]
      };
      if (acc === null) {
        acc = bounds;
      } else {
        acc = {
          min: [Math.min(acc.min[0], bounds.min[0]), Math.min(acc.min[1], bounds.min[1])],
          max: [Math.max(acc.max[0], bounds.max[0]), Math.max(acc.max[1], bounds.max[1])]
        };
      }
    }
    return acc;
  }

  /**
   * Compute the current map view's PCRS bounds. Mirrors the bounds
   * math in {@link MapmlViewer.extent}'s getter but returns just the
   * `PcrsBounds` needed for overlap testing.
   */
  #currentViewPcrsBounds(): PcrsBounds | null {
    const map = this.#renderer.map;
    if (!map) return null;
    const b = map.getBounds();
    const west = Math.max(-180, Math.min(180, b.getWest()));
    const east = Math.max(-180, Math.min(180, b.getEast()));
    const south = Math.max(-90, Math.min(90, b.getSouth()));
    const north = Math.max(-90, Math.min(90, b.getNorth()));
    return gcrsCornersToPcrsBounds([west, south], [east, north]);
  }

  /**
   * Update the screen-reader live region after a moveend. Called from
   * {@link #onMoveEnd} whenever `M.options.announceMovement` is on.
   *
   * Behaviour (parity with MapML.js's `AnnounceMovement.announceBounds`):
   *   - If the new view falls outside the aggregate layer bounds
   *     *or* the current zoom is below the layer minimum, bounce the
   *     map back to the previous history entry (`back()` + tail-pop)
   *     and announce the direction based on how the popped entry
   *     compared to the restored one (`amWestBound` / `amEastBound` /
   *     `amNorthBound` / `amSouthBound` / `amZoomedOut`).
   *   - Otherwise announce `"{amZoom} N"`. When zoom just entered
   *     the min or max zoom level (relative to the previous history
   *     entry), prefix with `amMinZoom` / `amMaxZoom` so the user
   *     hears "At minimum zoom level, zoom out disabled zoom level 0".
   *
   * `isDuplicate` distinguishes the clamped-to-min-zoom no-op case
   * (moveend fired but no entry pushed) from a real move. Duplicates
   * skip the bounce-back path but still re-announce the current zoom
   * with the min / max prefix if applicable.
   */
  #announceMovement(isDuplicate: boolean): void {
    const output = this.#announceMovementOutput;
    if (!output) return;
    const map = this.#renderer.map;
    if (!map) return;
    const locale = this.locale;
    const currentZoom = map.getZoom();
    const layerBounds = this.#totalLayerPcrsBounds();
    const viewBounds = this.#currentViewPcrsBounds();
    const minZoom = map.getMinZoom();
    const maxZoom = map.getMaxZoom();

    // Out-of-bounds check: view must overlap layer bounds, and zoom
    // must sit within the map's declared min / max. Skipped when
    // there's no layer yet (fresh viewer with no `<map-layer>`) —
    // matches MapML.js which only bounces when `totalLayerBounds`
    // has been populated.
    let visible = true;
    if (layerBounds !== null && viewBounds !== null) {
      visible =
        currentZoom >= minZoom &&
        currentZoom <= maxZoom &&
        pcrsBoundsOverlap(viewBounds, layerBounds);
    }

    if (!visible && !isDuplicate) {
      // Bounce back. Grab the entry we're about to leave (the
      // out-of-bounds one at head) and the one we're returning to
      // (its immediate predecessor). Announce the direction based on
      // how they differ, then `back()` + trim the tail so forward()
      // can't take us back to the invalid view.
      const outOfBoundsPos = this.#history[this.#historyIndex];
      const inBoundsPos = this.#history[this.#historyIndex - 1];
      if (outOfBoundsPos !== undefined && inBoundsPos !== undefined) {
        this.back();
        // `back()` decremented historyIndex; strip the invalid tail.
        this.#history.length = this.#historyIndex + 1;
        // Direction message. Zoom difference wins over pan
        // difference (matches MapML.js's ordering).
        if (outOfBoundsPos.zoom !== inBoundsPos.zoom) {
          output.textContent = locale.amZoomedOut;
        } else if (outOfBoundsPos.center[0] > inBoundsPos.center[0]) {
          output.textContent = locale.amEastBound;
        } else if (outOfBoundsPos.center[0] < inBoundsPos.center[0]) {
          output.textContent = locale.amWestBound;
        } else if (outOfBoundsPos.center[1] > inBoundsPos.center[1]) {
          output.textContent = locale.amNorthBound;
        } else if (outOfBoundsPos.center[1] < inBoundsPos.center[1]) {
          output.textContent = locale.amSouthBound;
        } else {
          // Same center and zoom — shouldn't happen given the
          // out-of-bounds check above, but fall back to a plain
          // zoom-level announcement.
          output.textContent = `${locale.amZoom} ${currentZoom}`;
        }
        return;
      }
    }

    // In-bounds announcement. Prefix with amMinZoom / amMaxZoom when
    // this move just entered min / max (i.e. the previous history
    // entry was at a different zoom). Matches MapML.js — its check
    // is `mapZoom !== prevZoom`, so a repeated Minus at min zoom
    // announces plain "zoom level 0" the second time, not the
    // boundary message. `isDuplicate` implies same zoom as previous,
    // so the boundary prefix drops off automatically.
    const prev = this.#history[this.#historyIndex - 1];
    const prevZoom = prev !== undefined ? prev.zoom : currentZoom;
    const standard = `${locale.amZoom} ${currentZoom}`;
    if (currentZoom === maxZoom && currentZoom !== prevZoom) {
      output.textContent = `${locale.amMaxZoom} ${standard}`;
    } else if (currentZoom === minZoom && currentZoom !== prevZoom) {
      output.textContent = `${locale.amMinZoom} ${standard}`;
    } else {
      output.textContent = standard;
    }
  }

  /**
   * Install the `<map-caption>` observer. Watches this element's
   * subtree for caption additions/removals and text-content edits,
   * calling {@link #syncCaptionAriaLabel} on any change. Ports the
   * `mapCaptionObserver` behaviour from `../MapML.js/src/mapml-viewer.js`
   * plus the per-caption `MutationObserver` from `../MapML.js/src/map-caption.js`,
   * but consolidated onto the viewer so `<map-caption>` itself stays
   * a bare tag.
   *
   * Runs an initial sync in case captions were parsed before this
   * observer was hooked up (unlikely — `connectedCallback` fires
   * before children are attached — but harmless and cheap).
   */
  #installCaptionObserver(): void {
    if (this.#captionObserver) return;
    this.#syncCaptionAriaLabel();
    this.#captionObserver = new MutationObserver(() => this.#syncCaptionAriaLabel());
    this.#captionObserver.observe(this, {
      childList: true,
      subtree: true,
      characterData: true
    });
  }

  /**
   * Reconcile our `aria-label` with the first `<map-caption>`
   * descendant. Rules (mirroring MapML.js):
   *
   *   - Adopt the first `<map-caption>` descendant only when
   *     aria-label is absent — never clobber an author-set value.
   *   - Once adopted, mirror text edits to the adopted caption onto
   *     aria-label.
   *   - When the adopted caption is removed, remove aria-label —
   *     don't re-elect a sibling caption (matches MapML.js's
   *     `mapCaptionObserver`, which watches for the original caption
   *     identity and clears the attribute when it disappears).
   *   - If the author sets aria-label out from under us (value
   *     differs from what we last wrote), release management and
   *     never touch aria-label again unless it's cleared.
   *
   * "First" means the first descendant in tree order — same as
   * MapML.js's `this.querySelector('map-caption')`. Nested captions
   * inside `<map-layer>` are eligible if they precede any top-level
   * caption, matching MapML.js.
   */
  #syncCaptionAriaLabel(): void {
    const currentAria = this.getAttribute('aria-label');

    // Author overrode our value → release management.
    if (
      this.#trackedCaption !== null &&
      currentAria !== this.#lastWrittenAriaLabel
    ) {
      this.#trackedCaption = null;
      this.#lastWrittenAriaLabel = null;
    }

    if (this.#trackedCaption !== null) {
      // We're managing. If the tracked caption was removed, abandon.
      if (!this.contains(this.#trackedCaption)) {
        this.removeAttribute('aria-label');
        this.#trackedCaption = null;
        this.#lastWrittenAriaLabel = null;
        return;
      }
      // Otherwise sync any text changes.
      const text = this.#trackedCaption.textContent ?? '';
      if (text !== currentAria) {
        this.setAttribute('aria-label', text);
        this.#lastWrittenAriaLabel = text;
      }
      return;
    }

    // Not managing. Only adopt if aria-label is absent (respect the author).
    if (currentAria !== null) return;
    const firstCaption = this.querySelector<MapCaption>('map-caption');
    if (firstCaption === null) return;
    const text = firstCaption.textContent ?? '';
    this.setAttribute('aria-label', text);
    this.#trackedCaption = firstCaption;
    this.#lastWrittenAriaLabel = text;
  }

  #uninstallControls(): void {
    for (const key of Object.keys(this.#controls) as (keyof ControlsBag)[]) {
      const ctrl = this.#controls[key];
      if (!ctrl) continue;
      if (key === 'layerContextMenu') {
        (ctrl as LayerContextMenu).destroy();
      } else {
        this.#renderer.removeControl(ctrl as maplibregl.IControl);
      }
      delete this.#controls[key];
    }
  }

  /**
   * Toggle MapLibre interaction handlers and the zoom-control buttons
   * based on whether the `static` attribute is present. Ports MapML.js's
   * `_toggleStatic` in `src/mapml-viewer.js`. Called from
   * {@link attributeChangedCallback} and once from {@link connectedCallback}
   * after the renderer is initialised so the initial attribute state is
   * honoured.
   *
   * `map.keyboard` is deliberately excluded: the renderer disables
   * MapLibre's stock keyboard handler for good (its Shift/Ctrl+Arrow
   * bindings tilt/rotate rather than pan) and the viewer owns keyboard
   * input via {@link #onCanvasKeyDown}. Re-enabling it here would make
   * the stock handler fire *alongside* ours (double zoom, phantom
   * pitch, wrong pan step), so keyboard is left untouched.
   */
  #toggleStatic(): void {
    const map = this.#renderer.map;
    if (!map) return;
    const isStatic = this.hasAttribute('static');
    const handlers = [
      map.dragPan,
      map.scrollZoom,
      map.doubleClickZoom,
      map.touchZoomRotate,
      map.touchPitch,
      map.boxZoom,
      map.dragRotate
    ];
    for (const h of handlers) {
      if (!h) continue;
      if (isStatic) h.disable();
      else h.enable();
    }
    // The `nozoom` controlslist token / `controls` attribute may have
    // suppressed the nav control entirely; guard with `?.`.
    const zoomButtons = this.shadowRoot?.querySelectorAll<HTMLButtonElement>(
      '.maplibregl-ctrl-zoom-in, .maplibregl-ctrl-zoom-out'
    );
    zoomButtons?.forEach((btn) => {
      btn.disabled = isStatic;
    });
    // Let the StaticControl button (and any author listeners) sync their
    // pressed state to the new attribute value.
    this.dispatchEvent(new CustomEvent('mapml:staticchanged'));
  }
}

interface ControlsBag {
  nav?: maplibregl.NavigationControl;
  reload?: ReloadButton;
  fullscreen?: maplibregl.FullscreenControl;
  layerControl?: LayerControl;
  compass?: CompassControl;
  viewControl?: ViewControl;
  staticControl?: StaticControl;
  featureIndexControl?: FeatureIndexControl;
  scale?: MapmlScaleControl;
  geolocate?: MapmlGeolocateControl;
  layerContextMenu?: LayerContextMenu;
  search?: MapmlSearchControl;
}

interface HistoryEntry {
  center: [number, number];
  zoom: number;
  bearing: number;
  pitch: number;
  view: MapmlView;
  projection: MapmlProjection;
}

/**
 * Translate a MapML {@link Locale} into MapLibre's own i18n key
 * namespace (`NavigationControl.ZoomIn`, `FullscreenControl.Enter`,
 * etc.). Only surfaces MapML.js localizes are mapped; MapLibre-only
 * strings (`NavigationControl.ResetBearing`, `LogoControl.Title`,
 * `ScaleControl.*`, `AttributionControl.MapFeedback`,
 * `GeolocateControl.LocationNotAvailable`) fall back to MapLibre's
 * English defaults because we have no MapML equivalent yet.
 *
 * `GeolocateControl.FindMyLocation` is redirected to `btnLocTrackOff`
 * (the "Show my location" affordance) — matches MapML.js's initial
 * state. The tracking-state transitions (ACTIVE_LOCK / BACKGROUND)
 * are handled dynamically by {@link MapmlGeolocateControl}.
 */
function mapmlLocaleToMapLibre(locale: Locale): Record<string, string> {
  return {
    'NavigationControl.ZoomIn': locale.btnZoomIn,
    'NavigationControl.ZoomOut': locale.btnZoomOut,
    'FullscreenControl.Enter': locale.btnFullScreen,
    'FullscreenControl.Exit': locale.btnExitFullScreen,
    'AttributionControl.ToggleAttribution': locale.btnAttribution,
    'GeolocateControl.FindMyLocation': locale.btnLocTrackOff
  };
}
