/**
 * Framework-agnostic ordered container of renderer layers, with
 * cascading rendered-state + opacity and the "child index === z-position"
 * invariant that MapML.js relies on Leaflet's `L.LayerGroup` for.
 *
 * The primitive knows nothing about MapLibre, DOM, or the MapML
 * elements — those layer on top in `src/core/mapml/` and `src/renderer/`.
 * A concrete `RendererLayer` handle is produced per-kind by the
 * `MapRenderer` factory in Stage 5; Stage 1 tests satisfy the contract
 * with hand-rolled spies.
 *
 * TERMINOLOGY:
 *   - `LayerGroup.setRendered(bool)` / `isRendered` / `effectiveRendered`
 *     — the on/off *toggle* semantic: is this group in the render list?
 *     Composed via `AND` up the ancestor chain. Matches
 *     `<map-extent>.renders` in the port today; distinct from
 *     MapML.js's `<map-link>.isVisible()` which is a viewport-
 *     intersection predicate (that concept stays on `<map-link>`).
 *   - `RendererLayer.setVisible(bool)` — the *native renderer* push,
 *     e.g. MapLibre's `layout.visibility: 'visible' | 'none'`. Fires
 *     only when the group's `effectiveRendered` flips.
 *
 * `LayerGroup` deliberately does NOT implement `RendererLayer` — the
 * two concepts are separate and the union `GroupChild` handles the
 * composite pattern via `instanceof LayerGroup` discrimination.
 */

/** Opaque callback returned by every `on…` subscription. */
export type Unsubscribe = () => void;

/**
 * Contract every *leaf* in the tree satisfies. Groups are a separate
 * type (`LayerGroup`) — the composite pattern uses the `GroupChild`
 * union rather than interface subtyping, so leaf-only ops like
 * `setVisible` stay leaf-only.
 */
export interface RendererLayer {
  readonly id: string;
  readonly kind:
    | 'raster-tile'
    | 'wms-tile'
    | 'image'
    | 'feature-collection'
    | 'vector-tile'
    | 'map-tile-run'
    | 'mapml-tile';
  /**
   * MapLibre-side stacking anchor: the id of the real renderer layer
   * that sits at the top of this handle's stack. For simple handles
   * (raster / wms / image) this equals `id`. For composite handles
   * (feature-collection with fill / line / circle sub-layers) this
   * is the top-most sub-layer's id.
   *
   * Used by `moveAbove` implementations to know which concrete
   * layer to insert *above* when the caller passes a composite as
   * the anchor.
   */
  readonly topStackingId: string;
  setVisible(visible: boolean): void;
  setOpacity(opacity: number): void;
  moveAbove(below?: RendererLayer): void;
  remove(): void;
}

export type GroupChild = LayerGroup | RendererLayer;

export interface LayerGroupOptions {
  rendered?: boolean;
  opacity?: number;
}

function clampOpacity(o: number): number {
  if (!Number.isFinite(o)) return 1;
  if (o < 0) return 0;
  if (o > 1) return 1;
  return o;
}

/**
 * A helper the group uses to distinguish leaves from nested groups.
 * Leaves don't track ancestors — they just apply whatever push the
 * group hands them via `setVisible` / `setOpacity`. Groups compute
 * their own effective value from their `#parent` chain.
 *
 * Uses `instanceof` so subclasses of `LayerGroup` (`MapmlLayerGroup`,
 * `FeatureAggregatorGroup`, and any future ones) all match.
 */
function isGroup(child: GroupChild): child is LayerGroup {
  return child instanceof LayerGroup;
}

/**
 * Reverse-lookup for leaf `RendererLayer`s: leaves don't have a
 * `#parent` field (their concrete implementations live in
 * `src/renderer/`), but `insertLayerAt` needs to know the previous
 * parent so re-parenting fires the correct `add` / `remove` events.
 * We use a module-level `WeakMap` keyed on the handle identity —
 * only `LayerGroup` mutates it, so external code can't corrupt it.
 * Groups track their parent via their own `#parent` field.
 */
const leafParent = new WeakMap<RendererLayer, LayerGroup>();

export class LayerGroup {
  readonly id: string;
  /**
   * Discriminator so consumers iterating `.children()` can tell a
   * group from a leaf without importing the class. Deliberately
   * distinct from any `RendererLayer.kind` value; leaves have
   * concrete kinds like `'raster-tile'` while groups are always
   * `'group'`. `instanceof LayerGroup` is the preferred discriminator
   * inside this module; the `.kind` field is the public alternative.
   */
  readonly kind = 'group' as const;

  #children: GroupChild[] = [];
  #parent: LayerGroup | null = null;
  #rendered: boolean;
  #opacity: number;
  /** Snapshot of `effectiveRendered()` we last pushed to leaves / fired. */
  #lastEffectiveRendered: boolean;
  /** Snapshot of `effectiveOpacity()` we last pushed to leaves / fired. */
  #lastEffectiveOpacity: number;

  #addListeners = new Set<(child: GroupChild) => void>();
  #removeListeners = new Set<(child: GroupChild) => void>();
  #reorderListeners = new Set<() => void>();
  #effectiveRenderedListeners = new Set<(v: boolean) => void>();
  #effectiveOpacityListeners = new Set<(o: number) => void>();

  constructor(id: string, options: LayerGroupOptions = {}) {
    this.id = id;
    this.#rendered = options.rendered ?? true;
    this.#opacity = clampOpacity(options.opacity ?? 1);
    // Root-of-tree defaults: no ancestor, so effective = own.
    this.#lastEffectiveRendered = this.#rendered;
    this.#lastEffectiveOpacity = this.#opacity;
  }

  // ── membership ──────────────────────────────────────────────────

  addLayer(child: GroupChild): this {
    return this.insertLayerAt(this.#children.length, child);
  }

  insertLayerAt(index: number, child: GroupChild): this {
    // Duplicate-id guard within this group. Global uniqueness (across
    // sibling groups) is the concrete renderer's problem.
    for (const existing of this.#children) {
      if (existing !== child && existing.id === child.id) {
        throw new Error(
          `LayerGroup "${this.id}": duplicate child id "${child.id}"`
        );
      }
    }
    // Re-parenting: detach from the previous parent first so that
    // parent's `remove` listener fires exactly once. `#detach`
    // handles the self-move case (re-inserting under the same
    // group at a different index).
    if (isGroup(child)) {
      if (child.#parent !== null && child.#parent !== this) {
        child.#parent.removeLayer(child);
      }
    } else {
      const prev = leafParent.get(child);
      if (prev !== undefined && prev !== this) {
        prev.removeLayer(child);
      }
    }
    // Self-move: remove existing entry so the reinsert lands at the
    // requested index rather than duplicating.
    const existingIdx = this.#children.indexOf(child);
    if (existingIdx >= 0) {
      this.#children.splice(existingIdx, 1);
    }
    const clamped = Math.max(0, Math.min(index, this.#children.length));
    this.#children.splice(clamped, 0, child);
    if (isGroup(child)) child.#parent = this;
    else leafParent.set(child, this);
    // Push the current effective state onto the newly-attached child
    // so leaves land in the right visibility / opacity immediately.
    this.#pushEffectiveToChild(child);
    for (const l of this.#addListeners) l(child);
    return this;
  }

  removeLayer(child: GroupChild): this {
    const idx = this.#children.indexOf(child);
    if (idx < 0) return this;
    this.#children.splice(idx, 1);
    if (isGroup(child)) {
      if (child.#parent === this) child.#parent = null;
    } else {
      if (leafParent.get(child) === this) leafParent.delete(child);
    }
    for (const l of this.#removeListeners) l(child);
    return this;
  }

  clearLayers(): this {
    // Snapshot: `removeLayer` mutates `#children` mid-iteration.
    const snapshot = this.#children.slice();
    for (const c of snapshot) this.removeLayer(c);
    return this;
  }

  hasLayer(child: GroupChild): boolean {
    return this.#children.includes(child);
  }

  get size(): number {
    return this.#children.length;
  }

  isEmpty(): boolean {
    // Recursive: a group of empty groups is still empty from a
    // renderer POV. Callers (e.g. LayerControl's "hide empty layer")
    // want the leaf count, not the direct-child count.
    for (const c of this.#children) {
      if (isGroup(c)) {
        if (!c.isEmpty()) return false;
      } else {
        return false;
      }
    }
    return true;
  }

  parent(): LayerGroup | null {
    return this.#parent;
  }

  root(): LayerGroup {
    // eslint-disable-next-line @typescript-eslint/no-this-alias
    let cur: LayerGroup = this;
    while (cur.#parent !== null) cur = cur.#parent;
    return cur;
  }

  *children(): IterableIterator<GroupChild> {
    for (const c of this.#children) yield c;
  }

  *leaves(): IterableIterator<RendererLayer> {
    for (const c of this.#children) {
      if (isGroup(c)) {
        yield* c.leaves();
      } else {
        yield c;
      }
    }
  }

  eachLayer(fn: (child: GroupChild) => void): void {
    for (const c of this.#children) fn(c);
  }

  // ── rendered-state (toggle cascade) ───────────────────────

  /** Own state; ignore ancestors. See `effectiveRendered` for the composed value. */
  isRendered(): boolean {
    return this.#rendered;
  }

  /**
   * `AND`-composed with every ancestor's own `#rendered`. When any
   * ancestor is toggled off the whole subtree comes out of the
   * render list, regardless of what descendants say about
   * themselves.
   */
  effectiveRendered(): boolean {
    if (!this.#rendered) return false;
    if (this.#parent === null) return true;
    return this.#parent.effectiveRendered();
  }

  setRendered(rendered: boolean): void {
    if (this.#rendered === rendered) return;
    this.#rendered = rendered;
    this.#recomputeEffectiveRendered();
  }

  // ── opacity ─────────────────────────────────────────────────────

  getOpacity(): number {
    return this.#opacity;
  }

  effectiveOpacity(): number {
    const own = this.#opacity;
    if (this.#parent === null) return own;
    return own * this.#parent.effectiveOpacity();
  }

  setOpacity(opacity: number): void {
    const next = clampOpacity(opacity);
    if (this.#opacity === next) return;
    this.#opacity = next;
    this.#recomputeEffectiveOpacity();
  }

  // ── reorder / z-order ───────────────────────────────────────────

  reorder(newOrder: readonly GroupChild[]): void {
    if (newOrder.length !== this.#children.length) {
      throw new Error(
        `LayerGroup "${this.id}": reorder length ${newOrder.length} ` +
          `!= current ${this.#children.length}`
      );
    }
    // Permutation validation: every item must be a current member.
    for (const c of newOrder) {
      if (!this.#children.includes(c)) {
        throw new Error(
          `LayerGroup "${this.id}": reorder includes unknown/non-member child`
        );
      }
    }
    this.#children = newOrder.slice();
    this.restack();
    for (const l of this.#reorderListeners) l();
  }

  /**
   * Re-establish renderer painter order for every leaf in this
   * subtree from the current tree order: bottom→top, first leaf goes
   * to "top of stack" (no anchor), each subsequent leaf stacks above
   * the previous.
   *
   * Unlike {@link reorder} this takes no new order and fires no
   * reorder listeners — it simply reasserts the existing tree order
   * against the renderer. A handle's native layer is created at the
   * TOP of the renderer stack (MapLibre `addLayer` with no `beforeId`),
   * so a handle whose remote content loads *after* the initial layout
   * would otherwise paint above earlier layers regardless of its
   * logical position. Callers invoke this after asynchronous handle
   * creation to snap the stack back to DOM order.
   */
  restack(): void {
    let below: RendererLayer | undefined;
    for (const leaf of this.leaves()) {
      leaf.moveAbove(below);
      below = leaf;
    }
  }

  moveChild(child: GroupChild, toIndex: number): void {
    if (!this.#children.includes(child)) return;
    const current = this.#children.slice();
    const from = current.indexOf(child);
    current.splice(from, 1);
    const clamped = Math.max(0, Math.min(toIndex, current.length));
    current.splice(clamped, 0, child);
    this.reorder(current);
  }

  // ── composite tree ops (a group is a movable / removable block) ──

  /**
   * Restack every leaf in this group so the entire subtree sits
   * contiguously above `below` (or at the top when `below` is
   * omitted). Groups aren't renderer-stacked themselves — only
   * their leaves are — so the semantic "move this subtree" cashes
   * out as a per-leaf `moveAbove` cascade.
   */
  moveAbove(below?: RendererLayer): void {
    let anchor = below;
    for (const leaf of this.leaves()) {
      leaf.moveAbove(anchor);
      anchor = leaf;
    }
  }

  remove(): void {
    // Detach from parent first so listeners on the parent see the
    // "remove" for this group before we tear down our children.
    if (this.#parent !== null) {
      this.#parent.removeLayer(this);
    }
    // Snapshot: `removeLayer` mutates `#children` mid-iteration.
    const snapshot = this.#children.slice();
    for (const c of snapshot) {
      if (isGroup(c)) c.remove();
      else c.remove();
      // In both cases, drop the entry from our own child list. For
      // groups, `remove()` recurses into parent detach; for leaves,
      // we mutate `#children` directly here.
    }
    // After recursion, the child list is guaranteed drained. Clear
    // any stray entries defensively (idempotent second-call safety).
    this.#children.length = 0;
  }

  // ── events ──────────────────────────────────────────────────────

  onAdd(fn: (child: GroupChild) => void): Unsubscribe {
    this.#addListeners.add(fn);
    return () => {
      this.#addListeners.delete(fn);
    };
  }

  onRemove(fn: (child: GroupChild) => void): Unsubscribe {
    this.#removeListeners.add(fn);
    return () => {
      this.#removeListeners.delete(fn);
    };
  }

  onReorder(fn: () => void): Unsubscribe {
    this.#reorderListeners.add(fn);
    return () => {
      this.#reorderListeners.delete(fn);
    };
  }

  onEffectiveRenderedChange(fn: (v: boolean) => void): Unsubscribe {
    this.#effectiveRenderedListeners.add(fn);
    return () => {
      this.#effectiveRenderedListeners.delete(fn);
    };
  }

  onEffectiveOpacityChange(fn: (o: number) => void): Unsubscribe {
    this.#effectiveOpacityListeners.add(fn);
    return () => {
      this.#effectiveOpacityListeners.delete(fn);
    };
  }

  // ── internals ───────────────────────────────────────────────────

  /**
   * Push the current effective rendered-state + opacity onto a
   * freshly-attached child so it lands in the correct state
   * immediately (no lag until the next explicit set).
   */
  #pushEffectiveToChild(child: GroupChild): void {
    const v = this.effectiveRendered();
    const o = this.effectiveOpacity();
    if (isGroup(child)) {
      // The child group's own state is preserved; only its cached
      // effective snapshot needs updating so its own descendants
      // land in the composed state.
      child.#recomputeEffectiveRendered();
      child.#recomputeEffectiveOpacity();
    } else {
      child.setVisible(v);
      child.setOpacity(o);
    }
  }

  #recomputeEffectiveRendered(): void {
    const next = this.effectiveRendered();
    const changed = next !== this.#lastEffectiveRendered;
    this.#lastEffectiveRendered = next;
    // Cascade to descendants only when *our* effective flipped —
    // otherwise leaves would receive redundant setVisible calls and
    // spy-based tests would see false positives. Group children
    // always recurse because their own axes may have changed
    // independently even if ours didn't.
    for (const c of this.#children) {
      if (isGroup(c)) {
        c.#recomputeEffectiveRendered();
      } else if (changed) {
        c.setVisible(next);
      }
    }
    if (changed) {
      for (const l of this.#effectiveRenderedListeners) l(next);
    }
  }

  /**
   * Subclass hook. Concrete subclasses that add extra axes to
   * `effectiveRendered()` (e.g. `MapmlLayerGroup`'s `checked` /
   * `disabled`) call this after mutating their own axis to trigger
   * the leaf cascade + change-event fire. Not part of the public
   * API — underscore prefix marks it internal-to-the-hierarchy.
   */
  protected _recomputeEffectiveRendered(): void {
    this.#recomputeEffectiveRendered();
  }

  #recomputeEffectiveOpacity(): void {
    const next = this.effectiveOpacity();
    const changed = next !== this.#lastEffectiveOpacity;
    this.#lastEffectiveOpacity = next;
    for (const c of this.#children) {
      if (isGroup(c)) {
        c.#recomputeEffectiveOpacity();
      } else if (changed) {
        c.setOpacity(next);
      }
    }
    if (changed) {
      for (const l of this.#effectiveOpacityListeners) l(next);
    }
  }
}
