import { isMapMetaName, type MapMetaName } from '../core/mapMeta';

/**
 * `<map-meta>` — author-supplied default for `projection` / `extent` / `cs` /
 * `zoom`. Mirrors MapML.js's element of the same name but stays intentionally
 * minimal: it carries `name` and `content` attributes and exposes them as
 * typed getters. Consumers (`<mapml-viewer>`, `<map-layer>`) look up child
 * `<map-meta>` elements and pull the relevant content via the parsers in
 * `src/core/mapMeta.ts`.
 *
 * `<map-meta>` produces no visible output and registers no MapLibre layer.
 */
export class MapMeta extends HTMLElement {
  static readonly observedAttributes = ['name', 'content'] as const;

  /** Returns the `name` attribute, or `null` if absent / unrecognised. */
  get name(): MapMetaName | null {
    const a = this.getAttribute('name');
    return a !== null && isMapMetaName(a) ? a : null;
  }
  set name(value: MapMetaName) {
    this.setAttribute('name', value);
  }

  /** Raw `content` attribute value, or `null` if absent. */
  get content(): string | null {
    return this.getAttribute('content');
  }
  set content(value: string | null) {
    if (value === null) this.removeAttribute('content');
    else this.setAttribute('content', value);
  }
}
