import type * as GeoJSON from 'geojson';

let nextLinkId = 0;

/** Monotonic id source for `rel="features"` grafted tile-run raster sources. */
let nextMapTileRunId = 0;

/**
 * Web-Mercator (OSMTILE) slippy-tile coordinate for a lng/lat at an
 * integer zoom. Used by `rel="tile" type="text/mapml"` to prune
 * harvested tiles outside the current viewport. Floors to the tile the
 * point falls in — matching the standard XYZ grid GeoServer's
 * `tilematrix` col/row use.
 */
function lngLatToTile(lng: number, lat: number, z: number): [number, number] {
  const n = 2 ** z;
  const x = Math.floor(((lng + 180) / 360) * n);
  const latRad = (lat * Math.PI) / 180;
  const y = Math.floor(
    ((1 - Math.log(Math.tan(latRad) + 1 / Math.cos(latRad)) / Math.PI) / 2) * n
  );
  return [x, y];
}

// Any `image/*` subtype is acceptable — MapLibre downloads the tile via
// the browser's image loader, so anything the browser can decode as an
// image works. The default when no `type` attribute is present is
// `image/*`, matching MapML.js's `get type()` in `src/map-link.js`
// ("return this.getAttribute('type') || 'image/*'").
const IMAGE_TYPE = /^image\//i;

/**
 * MIME type for the pmtiles-backed `<map-link rel="tile">` variant.
 * Matches MapML.js's `<map-link rel="tile" type="application/pmtiles">`
 * shape. The link's `tref` points at a `.pmtiles` archive; the
 * renderer wraps it behind the shared `pmtiles://` protocol handler
 * and adds one style layer per entry in the sibling JSON stylesheet's
 * `layers[]`.
 */
const PMTILES_TILE_TYPE = 'application/pmtiles';

/**
 * MIME type for the raw Mapbox Vector Tile variant of
 * `<map-link rel="tile">`. Tref is an XYZ tile URL template
 * (`https://server/{z}/{x}/{y}.mvt`, or author-named
 * `{level}`/`{col}`/`{row}` variables backed by `<map-input>`s);
 * the URL-template engine rewrites author variables to
 * MapLibre-native `{z}`/`{x}`/`{y}` and the renderer serves the
 * tiles via MapLibre's stock HTTP loader (no protocol handler
 * needed). The style pipeline is identical to the pmtiles branch:
 * both share the sibling `<map-link rel="stylesheet"
 * type="application/vnd.maplibre-style+json">`'s `layers[]`.
 *
 * IANA-registered MIME (RFC 8447) so no vendor suffix needed.
 */
const MVT_TILE_TYPE = 'application/vnd.mapbox-vector-tile';

/**
 * MIME type for the MapML-document variant of `<map-link rel="tile">`.
 * The `tref` points at a per-tile *MapML document* (GeoServer's
 * `format=text/mapml` WMTS output) rather than an image or vector
 * tile. Each fetched tile can carry stacked raster `<map-tile>` runs
 * *and* `<map-feature>`s; the renderer's `mapmlmetatile://` protocol
 * handler serves the raster runs while the link harvests the features
 * into its own GeoJSON source. See {@link MapLink.#applyMapmlTile}.
 *
 * OSMTILE only for now. The dispatch is a `type`-keyed branch so the
 * same `rel="tile"` machinery can later serve other document media
 * types (e.g. JSON tiles).
 */
const MAPML_TILE_TYPE = 'text/mapml';

/**
 * The set of MIME types that route through the vector-tile branch
 * (`#applyVectorTile`). Both share the same stylesheet contract
 * (`application/vnd.maplibre-style+json`) and the same
 * discover-stylesheet / build-layers / hand-to-renderer pipeline;
 * they diverge only in the shape of the MapLibre source spec
 * (`{ url: 'pmtiles://…' }` vs `{ tiles: [...] }`), which is
 * chosen by the {@link MapLink#type} branch inside the handle.
 */
const VECTOR_TILE_TYPES: readonly string[] = [
  PMTILES_TILE_TYPE,
  MVT_TILE_TYPE
];

/**
 * MIME type for the JSON MapLibre-style stylesheet that pairs with
 * `<map-link rel="tile" type="application/pmtiles">` and
 * `<map-link rel="tile" type="application/vnd.mapbox-vector-tile">`.
 * Analogue of MapML.js's `application/pmtiles+stylesheet` (a
 * JavaScript ES module exporting protomaps-leaflet symbolizer
 * rules), swapped for a plain JSON document following the MapLibre
 * style specification's `layers[]` shape
 * (https://maplibre.org/maplibre-style-spec/layers/). Chosen `+json`
 * structured-syntax suffix per RFC 6839 so it's clear the document
 * is JSON.
 *
 * Not IANA-registered — invented for MapML the same way
 * `application/pmtiles+stylesheet` was in MapML.js, and for the same
 * reason: we need a way to declare the link's payload shape so the
 * element can route it correctly.
 */
const MAPLIBRE_STYLE_JSON_TYPE = 'application/vnd.maplibre-style+json';

/**
 * Selector for finding an applicable MapLibre-style JSON stylesheet
 * in the link's ancestor chain. Same shape as MapML.js's
 * `map-link[rel="stylesheet"][type="application/pmtiles+stylesheet"]:not([disabled])`,
 * just with the MapLibre-style-JSON MIME type substituted.
 */
const MAPLIBRE_STYLE_SELECTOR =
  `map-link[rel="stylesheet"][type="${MAPLIBRE_STYLE_JSON_TYPE}"]:not([disabled])`;

/**
 * Absolute-URL matcher for the {@link MapLink.#resolveAgainstBase}
 * fast path. Matches:
 *   - `scheme://…` (e.g. `https://tile.example/…`)
 *   - `//host/…` (protocol-relative)
 *   - `data:…` / `blob:…` (opaque schemes)
 *
 * Anything not matching is treated as a relative reference and gets
 * resolved against the link's base URL.
 */
const ABSOLUTE_URL_RE = /^([a-z][a-z0-9+.-]*:|\/\/)/i;

/**
 * `<map-link>` — minimal skeleton.
 *
 * Initial scope: `rel="tile" type="image/*"` inside a `<map-extent>` whose
 * sibling `<map-input>` elements declare the variables referenced by `tref`.
 * The URL template engine rewrites the author-chosen variable names to
 * MapLibre-native `{x}/{y}/{z}` tokens for the OSMTILE / Web Mercator case.
 *
 * Other `rel` values (`features`, `image`, `query`, `style`, `alternate`,
 * `self`, `license`, `legend`, `stylesheet`, …) are recognised but
 * currently no-ops in `#apply()`. `rel="legend"` is consumed
 * declaratively by the owning `<map-layer>`'s layer-control row
 * (see {@link MapLayer.legendUrl}) — no renderer registration is
 * needed for it.
 */
export class MapLink extends HTMLElement implements MapTileRunOwner {
  static readonly observedAttributes = ['rel', 'tref', 'type', 'tms', 'disabled', 'href', 'media'] as const;

  /**
   * Renderer-side layer id we registered under. Retained for logging
   * / debugging and for the transitional `#registeredId` field's
   * historical semantics; the primary handle reference lives on
   * {@link #handle}.
   */
  #registeredId: string | undefined;
  /**
   * The `RendererLayer` handle created by the renderer's factory when
   * this link applies a `rel="tile"` / `rel="image"`. Owned by this
   * link; the extent's `LayerGroup` holds a reference too via
   * `extent.group.addLayer(handle)`. On teardown we detach from the
   * group and call `handle.remove()` to tear down the MapLibre state.
   */
  #handle: RendererLayer | undefined;
  #connected = false;
  /**
   * Bound `moveend` listener for `rel="image"` links. Retained so
   * {@link #teardown} can remove the exact function reference we
   * registered — MapLibre keys listeners by identity, so a fresh
   * closure would leak the old one.
   */
  #moveendListener: (() => void) | undefined;
  /**
   * `true` while this link is registered with the viewer's
   * query-click coordinator (see {@link MapmlViewer.registerQueryLink}).
   * Set in `#applyQuery`, cleared in `#teardown`. Guards against
   * double-registrations and against unregistering a link that
   * never registered.
   */
  #registeredAsQueryLink = false;
  /**
   * Monotonic token for the current in-flight `rel="features"` fetch.
   * Every new fetch pass bumps this and captures the value; when the
   * fetch resolves we bail out if the token has since moved (another
   * moveend / tref change kicked off a newer load). Prevents stale
   * grafts when the viewer pans rapidly.
   */
  #featuresFetchToken = 0;
  /**
   * `true` while `rel="features"` is running in remote (tref-driven)
   * mode. Set in `#applyFeatures`, cleared in `#teardown`. Guards the
   * cleanup path so a shadow-root wipe only fires for links that
   * actually installed a graft.
   */
  #featuresRemoteActive = false;

  /**
   * `<map-tile>` elements grafted into this link's shadow root by a
   * `rel="features"` fetch. A GeoServer LayerGroup response may mix
   * `<map-tile>` raster runs with `<map-feature>` vector runs; each
   * grafted tile registers here on connect via {@link registerMapTile}
   * because this link is the nearest {@link MapTileRunOwner} across the
   * shadow boundary. Rendered as a single `mapmltile://`-backed raster
   * source by {@link #rebuildTiles}. Empty for every non-features link.
   */
  #mapTiles = new Set<MapTile>();
  /** Coalescing flag for {@link notifyMapTilesChanged}. */
  #mapTilesChangeScheduled = false;
  /**
   * Handle rendering {@link #mapTiles} as one raster mosaic.
   * `undefined` until the first tile registers; torn down when the
   * last tile leaves or the link tears down. Lives in the parent
   * extent's group (beneath the layer-level aggregated feature source
   * in paint order, so vector features overlay the raster mosaic).
   */
  #tileRunHandle: MapTileRunRendererLayer | undefined;
  /**
   * `rel="tile" type="text/mapml"` mode. The protocol-backed raster
   * handle (one MapLibre source per stacked `<map-tile>` run). Distinct
   * from {@link #handle} so teardown can dispose it alongside the
   * {@link #mapmlFeatureHandle} without conflating the two. `undefined`
   * for every other link mode.
   */
  #mapmlTileHandle: MapmlTileRendererLayer | undefined;
  /**
   * `rel="tile" type="text/mapml"` mode. Link-owned GeoJSON source
   * holding the `<map-feature>`s harvested from fetched tiles. Not
   * grafted into the shadow root (the features are converted to
   * GeoJSON directly), so it renders without re-parenting — matching
   * MapML.js's render-don't-reparent behaviour for tiled features.
   */
  #mapmlFeatureHandle: FeatureRendererLayer | undefined;
  /**
   * Harvested GeoJSON features keyed by tile key (`"z/x/y"`). Rebuilt
   * into {@link #mapmlFeatureHandle}'s source on each flush. Pruned on
   * `moveend` to the current zoom + viewport tile range so stale tiles
   * don't accumulate.
   */
  #mapmlTileFeatures = new Map<string, GeoJSON.Feature[]>();
  /**
   * The tile zoom currently backing {@link #mapmlTileFeatures}. When a
   * parsed tile arrives at a different zoom (pan across a zoom change,
   * or GeoServer over-zoom clamping), the accumulated features are
   * stale and get cleared. `undefined` until the first tile parses.
   */
  #mapmlActiveZoom: number | undefined;
  /** Microtask coalescing flag for {@link #scheduleMapmlFeatureFlush}. */
  #mapmlFlushScheduled = false;

  /**
   * Contributor handle registered with the owning `<map-layer>`'s
   * style aggregator (see
   * {@link ../elements/map-layer.MapLayer.registerStyle}) while
   * this link is running as `rel="stylesheet"`. The `cssText` field
   * is mutated in place on fetch success so the layer sees fresh
   * text without needing a re-register — matches the
   * MutationObserver-driven update path used by `<map-style>`.
   *
   * `null` when the link is not (or no longer) a stylesheet. Set in
   * `#applyStylesheet`, cleared in `#teardown`.
   */
  #stylesheetContributor: { cssText: string; isActive: boolean } | null = null;
  /**
   * The `<map-layer>` we registered the stylesheet contributor with.
   * Captured at register time so `#teardown` can unregister even
   * when the link has since been detached from its ancestor chain.
   */
  #stylesheetOwner: MapLayer | null = null;
  /**
   * Monotonic token for the current in-flight `rel="stylesheet"`
   * fetch. Same pattern as `#featuresFetchToken` — bumped on every
   * new fetch; a resolving fetch that finds the token has moved
   * discards its response rather than overwriting a newer one.
   */
  #stylesheetFetchToken = 0;
  /**
   * Parsed MapLibre style JSON for a `rel="stylesheet"
   * type="application/vnd.maplibre-style+json"` link. Populated after the
   * `href` has been fetched and parsed. Only the `layers[]` slice is
   * consumed by the vector-tile link path (see {@link #applyVectorTile});
   * the object as a whole is retained so future callers can inspect
   * `sources` / `sprite` / etc.
   */
  #pmtilesStyle: {
    layers: ReadonlyArray<Record<string, unknown>>;
    glyphs?: string;
  } | null = null;
  /**
   * In-flight (or resolved) promise for the pmtiles JSON stylesheet's
   * fetch + parse. Sibling `<map-link rel="tile"
   * type="application/pmtiles">` links await this via
   * {@link whenPmtilesStyleReady} before creating their vector layer.
   * Reset on `href` change / teardown so consumers awaiting a stale
   * promise don't clobber a fresh one.
   */
  #pmtilesStyleReady: Promise<void> | null = null;
  /**
   * Resolver for {@link #pmtilesStyleReady}. Called from
   * {@link #applyPmtilesStylesheet}'s success path so any awaiting
   * pmtiles tile link unblocks; called with rejection on fetch error
   * so a broken stylesheet doesn't hang its consumers.
   */
  #pmtilesStyleReadyResolve: (() => void) | null = null;
  #pmtilesStyleReadyReject: ((err: Error) => void) | null = null;
  /**
   * For `rel="tile"` vector-tile links: the `<map-link
   * rel="stylesheet" type="application/vnd.maplibre-style+json">`
   * currently backing this link's rendered layers, or `null` when the
   * link is inactive. Set at the tail of {@link #applyVectorTile},
   * cleared by {@link #teardown}. Consumed by
   * {@link refreshIfStylesheetChanged} so a sibling stylesheet's
   * enable/disable cascade skips tile links whose active stylesheet
   * wouldn't change anyway \u2014 avoiding redundant renderer teardowns.
   */
  #activeStylesheet: MapLink | null = null;
  /**
   * The {@link #pmtilesStyleGeneration} value of {@link #activeStylesheet}
   * at the time {@link #applyVectorTile} last consumed it. Used by
   * {@link refreshIfStylesheetChanged} to force a re-apply when the
   * stylesheet element identity is unchanged but its `href` swapped
   * (and thus the fetched `layers[]` differ from what we painted with).
   * Without this, an `href` swap on an in-scope stylesheet would leave
   * sibling tile links painting with the pre-swap style layers because
   * the identity check alone can't tell same-element / new-content
   * apart.
   */
  #activeStylesheetGeneration = 0;
  /**
   * Monotonic counter bumped at the start of every
   * {@link #applyPmtilesStylesheet} run (i.e. every `href` swap /
   * initial load / dynamic append). Consumed by sibling tile links
   * via {@link #activeStylesheetGeneration} to detect "same stylesheet
   * element, new fetched content" \u2014 a case the identity check in
   * {@link refreshIfStylesheetChanged} can't catch. Never reset; a
   * teardown + reconnect will still increment past whatever a stale
   * consumer recorded, so the mismatch triggers the expected refresh.
   */
  #pmtilesStyleGeneration = 0;
  /**
   * Monotonic guard for {@link #applyVectorTile}'s async path. Bumped
   * by {@link #teardown} (and at entry to `#applyVectorTile`) so any
   * `await`s that resume with a stale token bail out before creating
   * a duplicate MapLibre source / style layers. Same shape as
   * `#stylesheetFetchToken` \u2014 without it, a `refresh()` fired mid-
   * flight would race two `createVectorTileLayer` calls and leak the
   * older handle.
   */
  #vectorTileApplyToken = 0;
  /**
   * The `<div>` returned by {@link getLayerControlOption} for a
   * `rel="style"` / `rel="self style"` / `rel="style self"` link —
   * a radio input + label that the enclosing `<map-layer>`'s
   * {@link MapLayer.getLayerControlHTML} slots into an
   * `.mapml-layer-item-style` `<details>`. Built in
   * {@link #applyStyle}, dropped in {@link #teardown}. Radios in
   * the same group share a `name` derived from the owning layer
   * so at most one alternate style is picked at a time.
   */
  #styleOption: HTMLDivElement | null = null;
  /**
   * Captured at connect-time. By the time `disconnectedCallback` runs the
   * link is already detached from its ancestor chain, so `closest()` would
   * return `null` and we'd leak the renderer layer.
   */
  #owningViewer: MapmlViewer | null = null;
  #owningExtent: MapExtent | null = null;

  /**
   * Live matcher returned by {@link MapmlViewer.matchMedia} while the
   * `media` attribute is populated. `null` when the attribute is
   * absent / empty, or before the initial async registration completes.
   * Owned by this link; disposed in {@link #teardownMediaQuery}.
   */
  #mql: MediaQueryList | null = null;
  /**
   * Bound change handler shared across the `#mql` lifetime.
   * Retained so `removeEventListener` sees the same identity used at
   * registration time — MapLibre / MediaQueryList both key listeners
   * by identity, and re-binding on every registration would leak the
   * previous closure.
   *
   * The handler's job is trivial: flip `this.disabled` to match the
   * inverted verdict. All downstream teardown/reapply cascades
   * through the existing `disabled` attributeChangedCallback path
   * (which calls {@link #teardown} + {@link #apply}), matching
   * MapML.js's `<map-link>._registerMediaQuery` shape.
   */
  #mqlChangeHandler: (() => void) | null = null;
  /**
   * Monotonic token bumped on every {@link #registerMediaQuery} call.
   * When {@link MapmlViewer.whenReady} resolves we bail if the token
   * has since moved — protects against a stale async registration
   * clobbering a fresher `media` value or a disconnect.
   */
  #mqlRegisterToken = 0;

  get rel(): string {
    return (this.getAttribute('rel') ?? '').toLowerCase();
  }

  get tref(): string {
    return this.getAttribute('tref') ?? '';
  }

  get href(): string {
    return this.getAttribute('href') ?? '';
  }

  get type(): string {
    // Default to `image/*` when the attribute is absent, matching
    // MapML.js. Non-image tile types (text/mapml, application/pmtiles)
    // must be declared explicitly.
    return this.getAttribute('type') || 'image/*';
  }

  get tms(): boolean {
    return this.hasAttribute('tms');
  }

  get disabled(): boolean {
    return this.hasAttribute('disabled');
  }

  /**
   * Reflect a JS write to the `disabled` attribute. Matches
   * MapML.js's `<map-link>.disabled` setter in `src/map-link.js`.
   * The subsequent `attributeChangedCallback` tears the link down
   * (releasing any renderer layer / listener / query registration
   * / shadow-root graft) and re-runs `#apply()` on the way back to
   * enabled.
   */
  set disabled(value: boolean) {
    if (value) this.setAttribute('disabled', '');
    else this.removeAttribute('disabled');
  }

  /**
   * The current `media` attribute value, or empty string when absent.
   * When non-empty, the link is gated by a {@link MediaQueryList} the
   * viewer builds via {@link MapmlViewer.matchMedia}: whenever the
   * query does not match, this link is `disabled` (via {@link disabled}),
   * which cascades through the existing extent/layer disabled tally.
   * Matches MapML.js's `<map-link>.media` on `src/map-link.js`.
   */
  get media(): string {
    return this.getAttribute('media') ?? '';
  }
  set media(value: string) {
    if (value === '' || value === null || value === undefined) {
      this.removeAttribute('media');
    } else {
      this.setAttribute('media', value);
    }
  }

  get viewer(): MapmlViewer | null {
    return (
      this.#owningViewer ??
      (shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null)
    );
  }

  get parentExtent(): MapExtent | null {
    // Shadow-crossing walker: Slice B lands remote content inside
    // `<map-layer>`'s shadow root, and `closest()` does not cross
    // shadow boundaries.
    return (
      this.#owningExtent ??
      shadowCrossingClosest(
        this,
        (el): el is MapExtent => el instanceof MapExtent
      )
    );
  }

  get parentLayer(): MapLayer | null {
    return shadowCrossingClosest(
      this,
      (el): el is MapLayer => el instanceof MapLayer
    );
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<mapml-viewer>`
   * (or `null` when this link is detached). Thin alias for the
   * shadow-crossing {@link viewer} getter — kept for source
   * compatibility with MapML.js callers (`link.getMapEl()`).
   */
  getMapEl(): MapmlViewer | null {
    return this.viewer;
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<map-layer>` (or
   * `null` when this link is detached). Thin alias for the
   * shadow-crossing {@link parentLayer} getter — kept for source
   * compatibility with MapML.js callers (`link.getLayerEl()`).
   */
  getLayerEl(): MapLayer | null {
    return this.parentLayer;
  }

  /**
   * Base URL against which this link's `tref` (and any `href`)
   * should resolve. For **shadow-hosted links** (i.e. this link
   * lives inside a `<map-layer src="…">` remote MapML doc), the
   * base is the remote doc's URL — so relative `tref`s in a
   * remote doc address the remote server, not the host HTML page.
   * For **light-DOM links**, the base is this element's own
   * `baseURI` (the host page).
   *
   * Mirrors MapML.js's `getBase()` in `src/map-link.js:920-936`.
   * The check `getRootNode() instanceof ShadowRoot` is the DOM-
   * standard way to detect shadow hosting.
   */
  #getBaseUrl(): string {
    const root = this.getRootNode();
    if (root instanceof ShadowRoot) {
      const host = root.host as HTMLElement;
      const src = host.getAttribute('src');
      if (src) return new URL(src, host.baseURI).href;
    }
    return this.baseURI;
  }

  /**
   * Resolve a `tref` (possibly relative, possibly containing
   * `{z}`/`{x}`/`{y}`-style placeholders) against this link's
   * {@link #getBaseUrl}.
   *
   * Two subtleties:
   *   1. **Absolute URLs are returned as-is.** The WHATWG URL
   *      parser round-trips `{` → `%7B` even for absolute URLs,
   *      which would break MapLibre's tile-URL template engine.
   *      Since an absolute URL doesn't need base resolution, we
   *      just short-circuit.
   *   2. **Relative URLs preserve `{…}` placeholders.** Each
   *      placeholder is temporarily swapped for a URL-safe
   *      sentinel before `new URL(…)` runs, then swapped back on
   *      the way out. This keeps `{z}/{x}/{y}` intact for relative
   *      tile templates in a remote MapML doc.
   */
  #resolveAgainstBase(url: string): string {
    // Fast path: absolute URL (or protocol-relative). Return
    // unchanged so `{z}` etc. stay literal.
    if (ABSOLUTE_URL_RE.test(url)) return url;
    // Relative resolution with placeholder preservation.
    const placeholders: string[] = [];
    const marked = url.replace(/\{[^}]+\}/g, (m) => {
      const key = `__MAPML_PH_${placeholders.length}__`;
      placeholders.push(m);
      return key;
    });
    const resolved = new URL(marked, this.#getBaseUrl()).href;
    return resolved.replace(
      /__MAPML_PH_(\d+)__/g,
      (_m, idx) => placeholders[Number(idx)]!
    );
  }

  /**
   * The multi-CRS extent envelope for this link's `tref` (matches the
   * shape of `<map-extent>.extent` / `<map-layer>.extent`). Returns
   * `null` for links that don't carry a URL template (`rel="license"`,
   * `rel="self"`, `rel="style"`, `rel="stylesheet"`, `rel="alternate"`
   * without a tref, \u2026) and for links that aren't inside a
   * `<map-extent>` (\u2014 there's no CRS context in which to compute
   * the envelope).
   *
   * Derivation mirrors MapML.js's `<map-link>.getBounds()` +
   * `_getZoomBounds`:
   *
   *   - Only the `<map-input>` elements *referenced by this tref*
   *     contribute to the link's bounds and zoom range \u2014 so a link
   *     can be more specific than its enclosing extent (e.g. a WMS
   *     `rel="image"` link whose tref binds four location inputs to
   *     `bbox={w},{s},{e},{n}` inherits their min/max even when the
   *     extent's other inputs have none).
   *   - **bounds** fallback: referenced `<map-input type="location">`
   *     pair \u2192 parent `<map-extent>`'s `<map-meta name="extent">`
   *     \u2192 parent `<map-layer>`'s `<map-meta name="extent">` \u2192
   *     projection whole extent.
   *   - **zoom** fallback: parent extent's `<map-meta name="zoom">`
   *     \u2192 parent layer's `<map-meta name="zoom">` \u2192 referenced
   *     `<map-input type="zoom">` min/max \u2192 projection native
   *     range (0..24 for OSMTILE).
   */
  get extent(): MapmlExtent | null {
    // `rel="features"` supports a tref-less inline mode where the
    // link's `<map-feature>` children live directly in the light DOM.
    // Every other rel value (tile/image/query/…) requires a tref to
    // have an extent \u2014 without one there's nothing to render or
    // fetch, so `.extent` is meaningless.
    const isInlineFeatures =
      this.rel === 'features' && !this.hasAttribute('tref');
    if (!this.hasAttribute('tref') && !isInlineFeatures) return null;
    const extent = this.parentExtent;
    if (extent === null) return null;
    const projection = extent.units;
    const layer = this.parentLayer;

    const allInputs = extent.getInputs();
    const tokens = trefTokens(this.tref);
    const referenced =
      tokens.length === 0 ? allInputs : allInputs.filter((i) => tokens.includes(i.name));

    let pcrs = inputsToPcrsBounds(referenced, projection);
    if (pcrs === null) {
      const em = extent.extentMeta;
      if (em !== null) {
        pcrs = em.bounds;
      } else {
        const lm = layer?.extentMeta ?? null;
        if (lm !== null) {
          pcrs = lm.bounds;
        } else {
          pcrs = projectionPcrsBounds(projection);
        }
      }
    }

    const extentZm = extent.zoomMeta;
    const layerZm = layer?.zoomMeta ?? null;
    const inputZ = inputsToZoomRange(referenced);
    const zoom =
      extentZm !== null
        ? { minZoom: extentZm.min, maxZoom: extentZm.max }
        : layerZm !== null
          ? { minZoom: layerZm.min, maxZoom: layerZm.max }
          : inputZ !== null
            ? inputZ
            : { minZoom: 0, maxZoom: projectionMaxZoom(projection) };

    return formatPcrsExtent(pcrs, projection, zoom);
  }

  /**
   * True when this link would render at the map's current view: it
   * has a `tref` (or is a `rel="features"` inline link), isn't
   * `disabled`, its `.extent.zoom` covers the current zoom, and its
   * `.extent` PCRS bounds overlap the viewer's PCRS bounds. Returns
   * `false` for tref-less non-features links (they render nothing to
   * check).
   *
   * Ports MapML.js's `<map-link>.isVisible()` +
   * `TemplatedTileLayer.isVisible()`. Consumed by
   * {@link MapExtent#validateDisabled} to decide whether an extent
   * has anything to draw at the current view \u2014 an extent with no
   * visible template becomes `disabled` even when its projection
   * matches the viewer's.
   */
  isVisible(): boolean {
    if (this.disabled) return false;
    const isInlineFeatures =
      this.rel === 'features' && !this.hasAttribute('tref');
    if (!this.hasAttribute('tref') && !isInlineFeatures) return false;
    const linkExt = this.extent;
    if (linkExt === null) return false;
    const viewer = this.viewer;
    const viewerExt = viewer?.extent;
    if (viewerExt === null || viewerExt === undefined) return false;
    const map = viewer!.renderer.map;
    if (!map) return false;
    const z = map.getZoom();
    if (z < linkExt.zoom.minZoom || z > linkExt.zoom.maxZoom) return false;
    const linkPcrs = {
      min: [
        linkExt.topLeft.pcrs.horizontal,
        linkExt.bottomRight.pcrs.vertical
      ] as [number, number],
      max: [
        linkExt.bottomRight.pcrs.horizontal,
        linkExt.topLeft.pcrs.vertical
      ] as [number, number]
    };
    const viewPcrs = {
      min: [
        viewerExt.topLeft.pcrs.horizontal,
        viewerExt.bottomRight.pcrs.vertical
      ] as [number, number],
      max: [
        viewerExt.bottomRight.pcrs.horizontal,
        viewerExt.topLeft.pcrs.vertical
      ] as [number, number]
    };
    return pcrsBoundsOverlap(linkPcrs, viewPcrs);
  }

  /**
   * Pan + zoom the viewer to this link's bounds. No-op when the link
   * has no `tref` (there's no CRS context in which to compute the
   * envelope) or isn't inside a `<map-extent>`.
   *
   * Uses the same `fitBounds` + zoom-range clamp pattern as
   * {@link MapExtent.zoomTo} / {@link MapLayer.zoomTo}: MapLibre picks
   * the natural zoom that fits the bbox, capped at
   * `.extent.zoom.maxZoom`, then bumped up to `.zoom.minZoom` if it
   * lands below. Mirrors MapML.js's `<map-link>.zoomTo()` via
   * `Util.getMaxZoom(bounds, map, minZoom, maxZoom)`.
   */
  zoomTo(): void {
    const map = this.viewer?.renderer.map;
    if (!map) return;
    const ext = this.extent;
    if (ext === null) return;
    const west = ext.topLeft.gcrs.horizontal;
    const north = ext.topLeft.gcrs.vertical;
    const east = ext.bottomRight.gcrs.horizontal;
    const south = ext.bottomRight.gcrs.vertical;
    map.fitBounds(
      [
        [west, south],
        [east, north]
      ],
      {
        animate: false,
        padding: 0,
        maxZoom: ext.zoom.maxZoom
      }
    );
    if (map.getZoom() < ext.zoom.minZoom) {
      map.setZoom(ext.zoom.minZoom);
    }
  }

  connectedCallback(): void {
    // `data-moving` on an ancestor `<map-layer>` / `<map-extent>`
    // signals that the parent is being re-parented as part of the
    // layer-control drag-to-reorder shuffle. Skip apply so the
    // renderer layer we already registered stays attached across the
    // DOM move — matches MapML.js's `data-moving` contract in
    // `src/map-link.js`.
    if (this.closest('[data-moving]')) return;
    // Shadow-crossing lookups: remote-hosted links (Slice B) sit
    // inside `<map-layer>`'s shadow root, so `Element.closest` alone
    // would stop at the shadow boundary and return null.
    this.#owningViewer = shadowCrossingClosestByTag(
      this,
      'mapml-viewer'
    ) as MapmlViewer | null;
    this.#owningExtent = shadowCrossingClosestByTag(
      this,
      'map-extent'
    ) as MapExtent | null;
    this.#connected = true;
    void this.#apply();
    // Register the media-query gate after the initial apply, matching
    // MapML.js's `<map-link>.connectedCallback` ordering. When the
    // media query doesn't match, `#registerMediaQuery` sets
    // `this.disabled = true`, which triggers the usual
    // `attributeChangedCallback` → `#teardown` cascade — a small
    // wasted round-trip on the mismatch case, but keeps the
    // "matches from the start" fast path allocation-free.
    if (this.media !== '') {
      void this.#registerMediaQuery(this.media);
    }
  }

  disconnectedCallback(): void {
    // See connectedCallback: skip teardown when this link is only
    // being re-parented as part of a drag-to-reorder DOM shuffle.
    if (this.closest('[data-moving]')) return;
    this.#connected = false;
    this.#teardownMediaQuery();
    this.#teardown();
    this.#owningViewer = null;
    this.#owningExtent = null;
  }

  attributeChangedCallback(
    name: string,
    oldValue: string | null,
    newValue: string | null
  ): void {
    if (!this.#connected) return;
    if (name === 'media') {
      // Media changes route through the media-query pipeline, which
      // in turn drives `disabled` — that then re-enters
      // `attributeChangedCallback('disabled', …)` and runs the usual
      // teardown + apply below. Skipping the direct teardown here
      // avoids a redundant round-trip on the (common) mismatch case.
      if (oldValue !== newValue) {
        void this.#registerMediaQuery(newValue ?? '');
      }
      return;
    }
    // Simplest correct strategy: tear down and re-register.
    this.#teardown();
    void this.#apply();
    // A `rel="features"` link's `disabled` (or `rel`, or `tref`)
    // toggle changes what the enclosing `<map-layer>`'s aggregated
    // GeoJSON source should contain: inline light-DOM children of
    // a now-disabled link must drop out of the source (and re-enter
    // when re-enabled). The rebuild walker in
    // `MapLayer.#rebuildFeatures` reads the link's `disabled`
    // attribute directly, so all we need to do here is nudge the
    // layer to re-run that walk. Idempotent — no-op if there are
    // no features under this layer.
    if (this.rel === 'features') {
      this.parentLayer?.notifyFeaturesChanged();
    }
    // A `rel="stylesheet" type="application/vnd.maplibre-style+json"`
    // link's `disabled` (or `href`) toggle changes which stylesheet
    // sibling vector-tile links should pick. Cascade the re-pick
    // through {@link refreshIfStylesheetChanged} so untouched links
    // (those whose active stylesheet wouldn't change) short-circuit
    // without a MapLibre teardown. Matches MapML.js's
    // "first stylesheet within scope, `:not([disabled])`" contract
    // dynamically rather than only at initial apply.
    if (
      this.rel === 'stylesheet' &&
      this.type === MAPLIBRE_STYLE_JSON_TYPE
    ) {
      this.#refreshVectorTileSiblings();
    }
  }

  /**
   * Public teardown + re-apply, callable from
   * {@link MapExtent.refreshLinks}. Used by `<map-select>` change
   * events (and any future sibling that mutates the extent's
   * template-variable set) so the link picks up the new value on
   * the next fetch / registration pass. No-op when the link isn't
   * connected \u2014 the reactive connect path will apply anyway.
   */
  refresh(): void {
    if (!this.#connected) return;
    this.#teardown();
    void this.#apply();
  }

  /**
   * Vector-tile-specific variant of {@link refresh}: for a
   * `rel="tile"` link whose `type` is one of the vector-tile MIMEs,
   * inspect which stylesheet {@link #findPmtilesStylesheet} would
   * pick right now, and only tear down + re-apply when that answer
   * differs from the currently active stylesheet
   * (`#activeStylesheet`). A no-op for any other link.
   *
   * Called from a sibling `rel="stylesheet"
   * type="application/vnd.maplibre-style+json"` link on
   * enable/disable / `href` / `media` transitions via
   * {@link #refreshVectorTileSiblings}, so the "first stylesheet
   * within scope, `:not([disabled])`" contract stays live across
   * runtime toggles (light/dark theme switch, `disabled` toggles
   * from author code, etc.). Skipping the teardown when the pick
   * wouldn't change avoids a MapLibre source rebuild + tile
   * re-fetch on every stylesheet edit.
   */
  refreshIfStylesheetChanged(): void {
    if (!this.#connected) return;
    if (this.rel !== 'tile') return;
    if (!VECTOR_TILE_TYPES.includes(this.type)) return;
    const desired = this.#findPmtilesStylesheet();
    // Identity match: same stylesheet element still wins the pick.
    // Compare the recorded generation against the current one to
    // catch the "same element, `href` swapped" case where the fetched
    // `layers[]` differ from what we painted with. When identity
    // differs (or one side is null) a re-apply is always warranted.
    if (
      desired === this.#activeStylesheet &&
      (desired === null ||
        desired.#pmtilesStyleGeneration === this.#activeStylesheetGeneration)
    ) {
      return;
    }
    this.#teardown();
    void this.#apply();
  }

  /**
   * Iterate every vector-tile link in this stylesheet's scope and
   * ask each to re-pick its stylesheet. Called from
   * {@link attributeChangedCallback} on `disabled` / `href` toggles
   * of a `rel="stylesheet"
   * type="application/vnd.maplibre-style+json"` link, and from the
   * success path of {@link #applyPmtilesStylesheet} (which fires on
   * initial load + dynamic append), so the "first stylesheet within
   * scope in document order" invariant matches MapML.js's
   * `map-link[rel="stylesheet"][type="\u2026"]:not([disabled])`
   * selector semantic dynamically \u2014 not only at initial apply.
   *
   * Scope walks the same containers `#findPmtilesStylesheet` would
   * search: this stylesheet's parent container (map-extent, map-
   * layer, layer-, or a shadow root for remote layers). Every
   * light-DOM descendant of that container whose tag is `map-link`
   * and whose `rel` / `type` mark it as a vector-tile link gets
   * `refreshIfStylesheetChanged()`. No shadow-boundary crossing:
   * remote-hosted stylesheets and remote-hosted tile links share
   * the same shadow root and are both direct/deep light-DOM
   * descendants of it.
   */
  #refreshVectorTileSiblings(): void {
    if (this.rel !== 'stylesheet') return;
    if (this.type !== MAPLIBRE_STYLE_JSON_TYPE) return;
    const scope = this.parentNode;
    if (scope === null) return;
    // `parentNode` is either the container element (light DOM) or a
    // ShadowRoot (remote-hosted). Both accept `querySelectorAll`.
    const selector =
      `map-link[rel="tile"][type="${PMTILES_TILE_TYPE}"], ` +
      `map-link[rel="tile"][type="${MVT_TILE_TYPE}"]`;
    const links = (scope as ParentNode).querySelectorAll(selector);
    for (const el of Array.from(links)) {
      if (el instanceof MapLink) {
        el.refreshIfStylesheetChanged();
      }
    }
  }

  async #apply(): Promise<void> {
    if (this.disabled) return;
    const viewer = this.viewer;
    if (!viewer) return;

    const rel = this.rel;
    if (rel === 'tile') {
      await this.#applyTile(viewer);
      return;
    }
    if (rel === 'image') {
      await this.#applyImage(viewer);
      return;
    }
    if (rel === 'query') {
      await this.#applyQuery(viewer);
      return;
    }
    if (rel === 'features') {
      await this.#applyFeatures(viewer);
      return;
    }
    if (rel === 'stylesheet') {
      await this.#applyStylesheet();
      return;
    }
    if (
      rel === 'style' ||
      rel === 'self' ||
      rel === 'style self' ||
      rel === 'self style'
    ) {
      this.#applyStyle();
      return;
    }
    // Other rel values are not yet supported by this renderer skeleton.
  }

  async #applyTile(viewer: MapmlViewer): Promise<void> {
    // Vector-tile branch. Both `application/pmtiles` (archive
    // delivery) and `application/vnd.mapbox-vector-tile` (XYZ HTTP
    // delivery) share the same stylesheet contract \u2014 a sibling
    // `<map-link rel="stylesheet"
    // type="application/vnd.maplibre-style+json">` whose `layers[]`
    // describes how MapLibre should paint the vector tiles. The
    // two shapes diverge only inside the renderer handle, where
    // the source spec picks between `{ url: 'pmtiles://\u2026' }` and
    // `{ tiles: [\u2026] }`.
    if (VECTOR_TILE_TYPES.includes(this.type)) {
      await this.#applyVectorTile(viewer);
      return;
    }
    if (this.type === MAPML_TILE_TYPE) {
      await this.#applyMapmlTile(viewer);
      return;
    }
    if (!IMAGE_TYPE.test(this.type)) {
      console.warn(
        `<map-link rel="tile">: unsupported type ${JSON.stringify(this.type)}; ` +
          'supported types are image/* (raster), application/pmtiles ' +
          `(pmtiles archive), or ${MVT_TILE_TYPE} (XYZ MVT tiles). ` +
          'The two vector types require a sibling <map-link ' +
          `rel="stylesheet" type="${MAPLIBRE_STYLE_JSON_TYPE}">. ` +
          'Omit the `type` attribute to accept the image/* default.'
      );
      return;
    }

    const tref = this.tref;
    if (!tref) {
      console.warn('<map-link rel="tile"> missing `tref` attribute; ignoring.');
      return;
    }

    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        '<map-link rel="tile"> must be inside a <map-extent> with matching <map-input> children. Ignoring.'
      );
      return;
    }

    const result = evaluateTileTemplate(tref, extent.getInputs(), extent.units);
    if (result.kind === 'error') {
      console.warn(`<map-link rel="tile">: ${result.reason}`);
      return;
    }

    await viewer.whenReady();
    if (!this.#connected) return;

    const id = `map-link-${++nextLinkId}`;
    const attribution = this.#extractAttribution();
    const spec = this.#extentSpec();

    if (result.kind === 'wms-tile') {
      // Bbox-per-tile shape. The template URL still contains the
      // four corner tokens; the renderer's `mapmlwmstile://`
      // protocol handler substitutes them per tile. The CS to
      // substitute in is inferred from the first corner input's
      // units — every corner input in a well-formed extent shares
      // the same units (mixing `units="pcrs"` with `units="gcrs"`
      // on the same tref would produce nonsensical bboxes).
      const unitsForCorners = this.#wmsTileUnits(result.cornerMap, extent);
      this.#handle = viewer.renderer.createWmsTileLayer({
        id,
        templateUrl: this.#resolveAgainstBase(result.templateUrl),
        cornerMap: result.cornerMap,
        unitsForCorners,
        scheme: this.tms ? 'tms' : 'xyz',
        visible: extent.renders,
        ...(attribution !== undefined ? { attribution } : {}),
        ...spec
      });
    } else {
      this.#handle = viewer.renderer.createRasterTileLayer({
        id,
        // Resolve relative trefs against the owning `<map-layer>`'s
        // `src` when this link is shadow-hosted. Absolute trefs pass
        // through unchanged. `{z}`/`{x}`/`{y}` placeholders survive
        // WHATWG URL parsing.
        tiles: [this.#resolveAgainstBase(result.url)],
        scheme: this.tms ? 'tms' : 'xyz',
        visible: extent.renders,
        ...(attribution !== undefined ? { attribution } : {}),
        ...spec
      });
    }

    this.#registeredId = id;
    // Add the handle to the extent's group. The group's cascade
    // pushes the current effective rendered + opacity onto the
    // handle immediately via `#pushEffectiveToChild`. Also notifies
    // the layer control that this extent now has content.
    extent.group.addLayer(this.#handle);
    extent.viewer?.notifyLayersChanged();

    // Now that this template is registered and would answer
    // `isVisible()` truthfully, re-run the parent extent's disabled
    // check. Matches MapML.js's `_enableLink()`, which finishes with
    // `this.getLayerEl()._validateDisabled()` so the extent (and its
    // owning layer) leave the transient `disabled` state they may
    // have been placed in when the extent connected before its links
    // had upgraded (a race common on paste / dynamic insertion).
    extent.validateDisabled();
  }

  /**
   * Set up a `rel="tile" type="text/mapml"` link: a templated fetch of
   * per-tile *MapML documents* (GeoServer's
   * `format_options=…mapmlusetiles:true;mapmlusefeatures:true` WMTS
   * output). Each fetched tile can carry stacked raster `<map-tile>`
   * runs *and* `<map-feature>`s.
   *
   * Two renderer layers back this one link:
   *   - a {@link MapmlTileRendererLayer} that owns one MapLibre raster
   *     source per `<map-tile>` run (`mapmlmetatile://` protocol drives
   *     the fetch + parse + per-run byte extraction), and
   *   - a link-owned {@link FeatureRendererLayer} GeoJSON source that
   *     holds the harvested `<map-feature>`s.
   *
   * The features are converted to GeoJSON directly (via
   * {@link MapFeature.toGeoJsonFeatures} on a detached, upgraded copy)
   * rather than re-parented into the shadow root — MapML.js renders
   * tiled features without re-parenting for the same
   * wasteful-to-graft reason, and a link-owned source keeps them off
   * the enclosing `<map-layer>`'s aggregated source.
   *
   * OSMTILE only. The dispatch is `type`-keyed so the same machinery
   * can later serve other document media types (e.g. JSON tiles).
   */
  async #applyMapmlTile(viewer: MapmlViewer): Promise<void> {
    const tref = this.tref;
    if (!tref) {
      console.warn(
        '<map-link rel="tile" type="text/mapml"> missing `tref` attribute; ignoring.'
      );
      return;
    }

    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        '<map-link rel="tile" type="text/mapml"> must be inside a <map-extent> with matching <map-input> children. Ignoring.'
      );
      return;
    }

    const result = evaluateTileTemplate(tref, extent.getInputs(), extent.units);
    if (result.kind === 'error') {
      console.warn(`<map-link rel="tile" type="text/mapml">: ${result.reason}`);
      return;
    }
    if (result.kind !== 'maplibre-tile' && result.kind !== 'wms-tile') {
      console.warn(
        '<map-link rel="tile" type="text/mapml">: tref must resolve to a ' +
          '{z}/{x}/{y} tile template (WMTS) or a {bbox} corner template ' +
          '(WMS GetMap). Ignoring.'
      );
      return;
    }

    await viewer.whenReady();
    if (!this.#connected) return;
    const map = viewer.renderer.map;
    if (!map) return;

    const id = `map-link-${++nextLinkId}`;
    const attribution = this.#extractAttribution();
    const spec = this.#extentSpec();

    // WMTS tref: template carries `{z}/{x}/{y}` (MapLibre expands them).
    // WMS-bbox tref: template carries the four `{corner}` tokens which
    // the `mapmlmetatile://` handler resolves per tile from z/x/y — the
    // same shape the raster `mapmlwmstile://` path uses. Either way the
    // fetched document may stack raster `<map-tile>` runs *and*
    // `<map-feature>`s (recall Spearfish).
    const wmsCorners =
      result.kind === 'wms-tile'
        ? {
            cornerMap: result.cornerMap,
            unitsForCorners: this.#wmsTileUnits(result.cornerMap, extent),
            scheme: this.tms ? ('tms' as const) : ('xyz' as const)
          }
        : undefined;
    const template = this.#resolveAgainstBase(
      result.kind === 'wms-tile' ? result.templateUrl : result.url
    );

    // Raster runs first so their MapLibre layers land BELOW the feature
    // layers created next — features must overlay the raster (painter
    // order). The group's child order (raster then features) matches, so
    // any later reorder cascade keeps features on top.
    const tileHandle = viewer.renderer.createMapmlTileLayer({
      id,
      template,
      visible: extent.renders,
      ...(attribution !== undefined ? { attribution } : {}),
      ...(wmsCorners ?? {}),
      ...spec,
      onTileParsed: (info) => {
        this.#onMapmlTileParsed(info);
      }
    });

    // Link-owned GeoJSON source for the harvested `<map-feature>`s.
    // Created empty up front so the first parsed tile has a target.
    const featureHandle = viewer.renderer.createFeatureCollectionLayer({
      id: `${id}::features`,
      data: { type: 'FeatureCollection', features: [] },
      visible: extent.renders,
      ...(attribution !== undefined ? { attribution } : {})
    });

    this.#handle = tileHandle;
    this.#mapmlTileHandle = tileHandle;
    this.#mapmlFeatureHandle = featureHandle;
    this.#registeredId = id;

    // Raster runs beneath, harvested features above (painter order).
    extent.group.addLayer(tileHandle);
    extent.group.addLayer(featureHandle);
    extent.viewer?.notifyLayersChanged();

    // Prune stale-zoom / off-view harvested tiles as the user
    // navigates so the link-owned source doesn't grow without bound.
    // Also reharvest every visible cell at the current zoom — MapLibre's
    // own raster cache short-circuits protocol invocation on revisit,
    // so features would otherwise drop out on zoom-back / pan-back.
    // `harvestMetaTile` dedupes via the shared parse cache and replays
    // `onTileParsed` on cache hits.
    const listener = (): void => {
      if (this.#registeredId !== id) return;
      const currentMap = viewer.renderer.map;
      if (!currentMap) return;
      this.#reharvestVisibleMapmlTiles(currentMap, id);
      this.#pruneMapmlTileFeatures(currentMap);
    };
    this.#moveendListener = listener;
    map.on('moveend', listener);

    extent.validateDisabled();
  }

  /**
   * `mapmlmetatile://` per-tile parse callback. Grows the raster-run
   * source set to match the tile's `<map-tile>` run count, and harvests
   * the tile's `<map-feature>`s into {@link #mapmlTileFeatures} keyed by
   * tile key. Fired once per unique tile (the protocol dedupes fetch +
   * parse across run sources).
   */
  #onMapmlTileParsed(info: {
    key: string;
    z: number;
    x: number;
    y: number;
    doc: XMLDocument;
    runCount: number;
  }): void {
    if (!this.#connected) return;
    if (info.runCount > 0) this.#mapmlTileHandle?.setRunCount(info.runCount);

    this.#mapmlActiveZoom = info.z;

    // Overwrite (not append) under this key so a re-parse of the same
    // cell dedupes rather than doubling its features. Features from
    // other zooms are cleared later by `#pruneMapmlTileFeatures` on
    // moveend, which lets a mid-flight zoom-transition parse land
    // without wiping the last-visible frame's features.
    this.#mapmlTileFeatures.set(info.key, this.#harvestFeatures(info.doc));
    this.#scheduleMapmlFeatureFlush();
  }

  /**
   * Convert every `<map-feature>` in a parsed tile document to GeoJSON
   * WITHOUT connecting it to the live tree. Each feature is imported
   * into the host document (so its custom element upgrades) and
   * converted via {@link MapFeature.toGeoJsonFeatures}, which needs only
   * the detached subtree plus the OSMTILE projection default — no
   * re-parenting into the shadow root.
   */
  #harvestFeatures(doc: XMLDocument): GeoJSON.Feature[] {
    const out: GeoJSON.Feature[] = [];
    // The tile's coordinate system is declared once in `<map-head>`
    // (`<map-meta name="cs">`), not on each geometry. A detached
    // `<map-feature>` can't walk up to that meta, so its `cs` getter
    // would fall back to `gcrs` and pass PCRS metres through untouched.
    // Copy the head value onto each geometry so the conversion is right.
    const csMeta = doc.querySelector('map-meta[name="cs"]');
    const cs = csMeta?.getAttribute('content')?.trim() ?? '';
    for (const el of doc.querySelectorAll('map-feature')) {
      const imported = document.importNode(el, true);
      customElements.upgrade(imported);
      if (imported instanceof MapFeature) {
        if (cs !== '') {
          const geom = imported.querySelector(':scope > map-geometry');
          if (geom !== null && !geom.hasAttribute('cs')) {
            geom.setAttribute('cs', cs);
          }
        }
        out.push(...imported.toGeoJsonFeatures());
      }
    }
    return out;
  }

  /** Microtask-coalesced flush of {@link #mapmlTileFeatures} → source. */
  #scheduleMapmlFeatureFlush(): void {
    if (this.#mapmlFlushScheduled) return;
    this.#mapmlFlushScheduled = true;
    queueMicrotask(() => {
      this.#mapmlFlushScheduled = false;
      this.#flushMapmlFeatures();
    });
  }

  /**
   * Rebuild the link-owned GeoJSON source from every harvested tile and
   * re-apply the enclosing `<map-layer>`'s compiled paint. The paint
   * re-read each flush lets late-loading `<map-style>` blocks land
   * without a style subscription — tiles keep arriving, so a flush
   * always follows a style load.
   */
  #flushMapmlFeatures(): void {
    const handle = this.#mapmlFeatureHandle;
    if (!handle) return;
    const features: GeoJSON.Feature[] = [];
    for (const arr of this.#mapmlTileFeatures.values()) {
      for (const f of arr) features.push(f);
    }
    // Stable numeric ids so click-to-popup can locate a hit by
    // `(source, id)`, matching `MapLayer.#rebuildFeatures`.
    features.forEach((f, i) => {
      f.id = i;
    });
    handle.setData({ type: 'FeatureCollection', features });
    const overrides = this.parentLayer?.featurePaintOverrides();
    if (overrides) handle.setStyle(overrides);
  }

  /**
   * Kick off a `harvestMetaTile` for every cell the current viewport
   * covers at the map's floor zoom. Idempotent — the shared parse
   * cache dedupes concurrent requests and `#onMapmlTileParsed`
   * overwrites its per-tile bucket by key, so replaying on a cached
   * parse doesn't inflate the feature list.
   *
   * Called on every moveend because MapLibre's own raster cache can
   * serve a previously-fetched tile from bytes without invoking the
   * `mapmlmetatile://` protocol handler, which would otherwise be the
   * only path that harvests features — revisiting a zoom / pan target
   * would leave the feature source empty.
   */
  #reharvestVisibleMapmlTiles(map: MapLibreMap, id: string): void {
    const z = Math.floor(map.getZoom());
    if (!Number.isFinite(z) || z < 0) return;
    const bounds = map.getBounds();
    const [nwX, nwY] = lngLatToTile(bounds.getWest(), bounds.getNorth(), z);
    const [seX, seY] = lngLatToTile(bounds.getEast(), bounds.getSouth(), z);
    for (let x = nwX; x <= seX; x++) {
      for (let y = nwY; y <= seY; y++) {
        void harvestMetaTile(id, z, x, y);
      }
    }
  }

  /**
   * Drop harvested tiles that are no longer at the active zoom or
   * inside the current viewport's tile range (with a one-tile margin),
   * then flush if anything changed. Keeps {@link #mapmlTileFeatures}
   * bounded across a long pan session.
   */
  #pruneMapmlTileFeatures(map: MapLibreMap): void {
    // Prune against the *map's* current zoom rather than the last
    // parsed tile's zoom — mid-zoom-transition parses can race with
    // moveend and would otherwise anchor the prune to a stale z.
    const z = Math.floor(map.getZoom());
    if (!Number.isFinite(z) || z < 0) return;
    const bounds = map.getBounds();
    const [nwX, nwY] = lngLatToTile(bounds.getWest(), bounds.getNorth(), z);
    const [seX, seY] = lngLatToTile(bounds.getEast(), bounds.getSouth(), z);
    const x0 = nwX - 1;
    const x1 = seX + 1;
    const y0 = nwY - 1; // north → smaller y
    const y1 = seY + 1;
    let changed = false;
    for (const key of [...this.#mapmlTileFeatures.keys()]) {
      const parts = key.split('/');
      const kz = Number(parts[0]);
      const kx = Number(parts[1]);
      const ky = Number(parts[2]);
      if (kz !== z || kx < x0 || kx > x1 || ky < y0 || ky > y1) {
        this.#mapmlTileFeatures.delete(key);
        changed = true;
      }
    }
    if (changed) this.#scheduleMapmlFeatureFlush();
  }

  /**
   * Set up a `rel="tile"` link whose `type` is one of the
   * vector-tile MIMEs \u2014 `application/pmtiles` for archive delivery
   * or `application/vnd.mapbox-vector-tile` for XYZ HTTP delivery.
   *
   * Both shapes share the same rendering pipeline: a sibling
   * `<map-link rel="stylesheet"
   * type="application/vnd.maplibre-style+json">` supplies a MapLibre
   * style-spec `layers[]` array (plus optional top-level `glyphs`),
   * and the renderer factory creates one MapLibre source + one style
   * layer per stylesheet entry. The two branches diverge only in the
   * source spec shape:
   *
   *   - **pmtiles**: `{ type: 'vector', url: 'pmtiles://<tref>' }`,
   *     served via the shared `pmtiles://` protocol handler. The
   *     archive URL is passed to the handle as `tileUrl`; MapML
   *     `<map-input>` variables are OPTIONAL and, when present, get
   *     rewritten to MapLibre-native `{z}`/`{x}`/`{y}` by
   *     {@link evaluateTileTemplate} (some pmtiles archives are
   *     served through a paging endpoint that expects tile
   *     coordinates in the query string).
   *   - **XYZ MVT**: `{ type: 'vector', tiles: [<tref>] }`, served
   *     over plain HTTP by MapLibre's built-in tile loader. The
   *     tref MUST contain either MapLibre-native `{z}`/`{x}`/`{y}`
   *     tokens or `<map-input>`-declared substitutes; a variable-
   *     free tref is an authoring error.
   *
   * Discovery of the JSON stylesheet mirrors MapML.js's pmtiles
   * branch in `src/map-link.js`: for local-DOM authoring, walk the
   * ancestor chain looking for a `map-extent` / `map-layer` /
   * `layer-` that contains an applicable stylesheet; for remote
   * authoring (a `<map-layer src="\u2026">`), check the enclosing
   * `<map-extent>` first, then the layer's shadow-root direct
   * children. First hit in document order wins (matching MapML.js's
   * "first stylesheet within scope" semantics).
   */
  async #applyVectorTile(viewer: MapmlViewer): Promise<void> {
    // Snapshot our monotonic token so post-await continuations can
    // detect a mid-flight teardown/refresh (`#teardown` bumps this
    // to signal "start over"). Every `await` below is followed by
    // a token check.
    const token = ++this.#vectorTileApplyToken;
    const tref = this.tref;
    const linkType = this.type;
    if (!tref) {
      console.warn(
        `<map-link rel="tile" type="${linkType}"> missing \`tref\` attribute; ignoring.`
      );
      return;
    }

    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        `<map-link rel="tile" type="${linkType}"> must be inside a <map-extent>. Ignoring.`
      );
      return;
    }

    // Discover the applicable JSON stylesheet.
    const stylesheetLink = this.#findPmtilesStylesheet();
    if (!stylesheetLink) {
      console.warn(
        `<map-link rel="tile" type="${linkType}"> tref="${tref}": ` +
          `no applicable <map-link rel="stylesheet" type="${MAPLIBRE_STYLE_JSON_TYPE}"> ` +
          'found in the enclosing <map-extent>, <map-layer>, or shadow root. ' +
          'Add one alongside this link to describe how the vector tiles should be painted.'
      );
      return;
    }

    // Await the stylesheet's fetch + parse. If the stylesheet has a
    // pending fetch, this yields until it settles. On rejection the
    // stylesheet is unusable; bail with a warning rather than
    // installing a source without any layers.
    try {
      await stylesheetLink.whenPmtilesStyleReady();
    } catch (err) {
      console.warn(
        `<map-link rel="tile" type="${linkType}"> tref="${tref}": ` +
          `stylesheet failed to load \u2014 ${(err as Error).message ?? String(err)}`
      );
      return;
    }
    // Bail if a `refresh()` / `disconnectedCallback` bumped the token
    // (or disconnected us) while we were awaiting the stylesheet.
    if (
      token !== this.#vectorTileApplyToken ||
      !this.#connected
    ) {
      return;
    }
    const style = stylesheetLink.pmtilesStyle;
    if (!style || !Array.isArray(style.layers) || style.layers.length === 0) {
      console.warn(
        `<map-link rel="tile" type="${linkType}"> tref="${tref}": ` +
          'stylesheet has no `layers` \u2014 nothing to render.'
      );
      return;
    }

    // Resolve the tref. When `<map-input>` tokens are present,
    // rewrite author-named tokens to MapLibre-native
    // `{z}`/`{x}`/`{y}` via the URL-template engine. When absent
    // (typical for `.pmtiles` archive URLs), pass the resolved
    // URL through unchanged. For XYZ MVT we ADDITIONALLY warn when
    // no tokens are present at all \u2014 a MVT XYZ template without
    // `{z}`/`{x}`/`{y}` would ask MapLibre to fetch the same tile
    // for every viewport, which is almost certainly a mistake.
    let resolvedUrl: string;
    const hasTokens = /\{[A-Za-z_][\w-]*\}/.test(tref);
    if (hasTokens) {
      const result = evaluateTileTemplate(tref, extent.getInputs(), extent.units);
      if (result.kind === 'error') {
        console.warn(
          `<map-link rel="tile" type="${linkType}">: ${result.reason}`
        );
        return;
      }
      if (result.kind === 'wms-tile') {
        console.warn(
          `<map-link rel="tile" type="${linkType}"> tref="${tref}": ` +
            'WMS-per-tile bbox variables are not supported on vector-tile trefs. ' +
            'Use zoom / column / row inputs, or (for pmtiles) a variable-free archive URL.'
        );
        return;
      }
      resolvedUrl = this.#resolveAgainstBase(result.url);
    } else {
      if (linkType === MVT_TILE_TYPE) {
        console.warn(
          `<map-link rel="tile" type="${linkType}"> tref="${tref}": ` +
            'XYZ MVT tref must include `{z}`/`{x}`/`{y}` (or `<map-input>`- ' +
            'declared substitutes); a variable-free tref would fetch the same ' +
            'tile URL for every viewport.'
        );
        return;
      }
      resolvedUrl = this.#resolveAgainstBase(tref);
    }

    await viewer.whenReady();
    // Second token check: `refresh()` may have fired again while
    // the map was warming up.
    if (
      token !== this.#vectorTileApplyToken ||
      !this.#connected
    ) {
      return;
    }

    const id = `map-link-${++nextLinkId}`;
    const attribution = this.#extractAttribution();
    const spec = this.#extentSpec();
    const common = {
      id,
      styleLayers: style.layers,
      visible: extent.renders,
      ...(style.glyphs !== undefined ? { glyphs: style.glyphs } : {}),
      ...(attribution !== undefined ? { attribution } : {}),
      ...spec
    };

    this.#handle =
      linkType === PMTILES_TILE_TYPE
        ? viewer.renderer.createVectorTileLayer({
            source: 'pmtiles',
            tileUrl: resolvedUrl,
            ...common
          })
        : viewer.renderer.createVectorTileLayer({
            source: 'xyz-mvt',
            tiles: [resolvedUrl],
            scheme: this.tms ? 'tms' : 'xyz',
            ...common
          });

    this.#registeredId = id;
    // Record which stylesheet backed this handle so a later cascade
    // (see `refreshIfStylesheetChanged`) can decide whether a
    // re-apply is actually necessary. The generation snapshot lets
    // us also catch same-identity / new-content changes (i.e. `href`
    // swap on the stylesheet) where the identity check alone would
    // pass and miss the update.
    this.#activeStylesheet = stylesheetLink;
    this.#activeStylesheetGeneration = stylesheetLink.#pmtilesStyleGeneration;
    extent.group.addLayer(this.#handle);
    extent.viewer?.notifyLayersChanged();
    extent.validateDisabled();
  }

  /**
   * Locate an applicable pmtiles JSON stylesheet for this link.
   *
   * Search rules mirror MapML.js's `<map-link>._createTemplatedLink()`
   * pmtiles branch in `src/map-link.js`:
   *
   *   1. **Remote-layer (shadow-hosted) authoring**: the link lives
   *      inside a `<map-layer src="\u2026">`'s shadow root. First look
   *      inside the enclosing `<map-extent>`; if not found there,
   *      look at direct-child stylesheets of the shadow root
   *      (`:host > \u2026` in CSS terms).
   *   2. **Local authoring**: walk the ancestor chain looking for a
   *      `<map-extent>` / `<map-layer>` / `<layer->` that contains
   *      the stylesheet. First match wins; document-order does the
   *      right thing when multiple stylesheets are in scope, matching
   *      MapML.js's "first stylesheet within scope" semantics.
   */
  #findPmtilesStylesheet(): MapLink | null {
    const layer = this.parentLayer;
    const isRemoteLayer = layer !== null && layer.hasAttribute('src');
    if (isRemoteLayer) {
      // Prefer a stylesheet in the enclosing map-extent.
      const extent = this.parentExtent;
      const inExtent = extent?.querySelector(MAPLIBRE_STYLE_SELECTOR) as
        | MapLink
        | null;
      if (inExtent) return inExtent;
      // Fall back to direct children of the layer's shadow root
      // (`:host > selector`). Slot-crossing lookups aren't needed
      // here because remote-content stylesheets sit as light-DOM
      // children of the fetched MapML doc's `<map-layer>`, which we
      // graft into the layer's shadow root at connect time.
      const root = this.getRootNode();
      if (root instanceof ShadowRoot) {
        for (const child of Array.from(root.children)) {
          if (child.matches(MAPLIBRE_STYLE_SELECTOR)) {
            return child as MapLink;
          }
        }
      }
      return null;
    }
    // Local authoring: walk ancestors, checking each container-like
    // element for a stylesheet child.
    let el: Element | null = this.parentElement;
    while (el) {
      const tag = el.tagName;
      if (tag === 'MAP-EXTENT' || tag === 'MAP-LAYER' || tag === 'LAYER-') {
        const found = el.querySelector(MAPLIBRE_STYLE_SELECTOR) as
          | MapLink
          | null;
        if (found) return found;
      }
      el = el.parentElement;
    }
    return null;
  }

  /**
   * The parsed MapLibre style JSON, once
   * {@link whenPmtilesStyleReady} has resolved. `null` before the
   * first successful fetch (and after teardown). Consumed by sibling
   * `<map-link rel="tile" type="application/pmtiles">` links via
   * {@link #findPmtilesStylesheet}.
   */
  get pmtilesStyle(): {
    layers: ReadonlyArray<Record<string, unknown>>;
    glyphs?: string;
  } | null {
    return this.#pmtilesStyle;
  }

  /**
   * Resolves once this link's pmtiles JSON stylesheet has been
   * fetched and parsed. Returns a rejected promise on fetch failure
   * or when the link is not a pmtiles stylesheet (so a consumer that
   * awaits this on the wrong link doesn't hang indefinitely).
   *
   * Public because sibling `<map-link rel="tile"
   * type="application/pmtiles">` links await it before creating
   * their vector-tile layer. The promise identity is reset on each
   * `href` change / teardown, matching the token-based fetch-flap
   * suppression used elsewhere in this file.
   */
  whenPmtilesStyleReady(): Promise<void> {
    if (this.rel !== 'stylesheet' || this.type !== MAPLIBRE_STYLE_JSON_TYPE) {
      return Promise.reject(
        new Error(
          `whenPmtilesStyleReady called on a <map-link> that isn't a MapLibre-style JSON stylesheet ` +
            `(rel="${this.rel}", type="${this.type}").`
        )
      );
    }
    // Already resolved: return a resolved promise cheaply.
    if (this.#pmtilesStyle !== null) return Promise.resolve();
    // In-flight fetch: piggyback on the existing promise.
    if (this.#pmtilesStyleReady !== null) return this.#pmtilesStyleReady;
    // No fetch has been started yet (link may not have run its
    // `#apply()` pass, e.g. called before connectedCallback).
    // Create the ready promise now; #applyPmtilesStylesheet will
    // resolve/reject it when it fetches.
    this.#pmtilesStyleReady = new Promise<void>((resolve, reject) => {
      this.#pmtilesStyleReadyResolve = resolve;
      this.#pmtilesStyleReadyReject = reject;
    });
    return this.#pmtilesStyleReady;
  }

  /**
   * Set up a `rel="image"` template as a MapLibre `type: "image"`
   * source, then register a `moveend` listener that recomputes the
   * URL + corner coordinates every time the viewport changes.
   *
   * The initial resolve happens once the map has fired `load` so
   * `map.getBounds()` returns the real viewport (not the constructor
   * defaults). Every subsequent `moveend` re-resolves the template
   * against the new view — matches MapML.js's
   * `TemplatedImageLayer._onMoveEnd`.
   */
  async #applyImage(viewer: MapmlViewer): Promise<void> {
    const tref = this.tref;
    if (!tref) {
      console.warn('<map-link rel="image"> missing `tref` attribute; ignoring.');
      return;
    }

    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        '<map-link rel="image"> must be inside a <map-extent> with matching <map-input> children. Ignoring.'
      );
      return;
    }

    await viewer.whenReady();
    if (!this.#connected) return;
    const map = viewer.renderer.map;
    if (!map) return;

    const inputs = extent.getInputs();
    const units = extent.units;

    // Resolve once against the current view. If the resolution fails
    // (missing input, unsupported axis, non-OSMTILE), warn and bail out
    // — we don't want to register a listener that will fail on every
    // moveend.
    const first = evaluateImageTemplate(tref, inputs, units, buildViewSnapshot(map));
    if (first.kind === 'error') {
      console.warn(`<map-link rel="image">: ${first.reason}`);
      return;
    }

    const id = `map-link-${++nextLinkId}`;
    const attribution = this.#extractAttribution();
    const imageHandle = viewer.renderer.createImageLayer({
      id,
      // Resolve relative trefs against the owning `<map-layer>`'s
      // `src` when this link is shadow-hosted. `evaluateImageTemplate`
      // has already fully expanded query-string variables, so no
      // placeholder concerns here.
      url: this.#resolveAgainstBase(first.url),
      coordinates: first.coordinates,
      visible: extent.renders,
      ...(attribution !== undefined ? { attribution } : {})
    });
    this.#handle = imageHandle;

    this.#registeredId = id;
    extent.group.addLayer(imageHandle);
    extent.viewer?.notifyLayersChanged();

    // Re-resolve on every viewport change. The listener holds `this`
    // via a bound arrow; the reference is stored on `#moveendListener`
    // so teardown can pass the same function to `map.off`.
    const listener = (): void => {
      // The link may have been detached between the fire and the
      // callback invocation; short-circuit if so.
      if (this.#registeredId !== id) return;
      const currentMap = viewer.renderer.map;
      if (!currentMap) return;
      const view = buildViewSnapshot(currentMap);
      const next = evaluateImageTemplate(tref, extent.getInputs(), extent.units, view);
      if (next.kind === 'error') {
        // Author changed inputs live and the template no longer
        // resolves. Warn but keep the previous frame — a single
        // moveend blip shouldn't tear down the whole layer.
        console.warn(`<map-link rel="image">: ${next.reason}`);
        return;
      }
      imageHandle.update({
        url: this.#resolveAgainstBase(next.url),
        coordinates: next.coordinates
      });
    };
    this.#moveendListener = listener;
    map.on('moveend', listener);

    extent.validateDisabled();
  }

  /**
   * Set up a `rel="query"` link. No renderer layer is added \u2014 a
   * query is a *click handler* that fetches a server response and
   * opens a popup at the click location. We don't register our own
   * `map.on('click', ...)` here \u2014 instead we register with the
   * viewer's query-click coordinator, which iterates every
   * registered query link on each click and opens a *single*
   * popup with the aggregated features from every visible link.
   * This gives the expected "1/N total across all queried links"
   * counter that MapML.js provides via `QueryHandler._query` (which
   * fires every template in the top queryable layer in parallel and
   * concatenates the returned features).
   */
  async #applyQuery(viewer: MapmlViewer): Promise<void> {
    const tref = this.tref;
    if (!tref) {
      console.warn('<map-link rel="query"> missing `tref` attribute; ignoring.');
      return;
    }

    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        '<map-link rel="query"> must be inside a <map-extent> with matching <map-input> children. Ignoring.'
      );
      return;
    }

    await viewer.whenReady();
    if (!this.#connected) return;

    // Join the viewer's query-click coordinator. It maintains a
    // single map-level `click` handler that walks every registered
    // query link in DOM order, filters by {@link isVisible}, fires
    // each visible link's `performQueryFetch` in parallel via
    // `Promise.allSettled`, concatenates the resulting features
    // arrays, and opens one popup with the aggregate.
    viewer.registerQueryLink(this);
    this.#registeredAsQueryLink = true;

    // A query link participates in the extent's disabled-cascade
    // via `isVisible()`; a bare `<map-link rel="query">` with a
    // `tref` will now flip the extent to enabled if it was
    // otherwise-empty.
    extent.validateDisabled();
  }

  /**
   * Set up a `rel="features"` link. Two modes, distinguished by the
   * presence of a `tref` attribute:
   *
   *   * **Remote**: `tref` is set. On the initial `whenReady()` and
   *     every subsequent `moveend`, we evaluate the template against
   *     the current viewport, fetch the resulting MapML fragment,
   *     parse the XML, and adopt every `<map-feature>` (and other
   *     legal fragment content) into a shadow root on this link.
   *     Grafted `<map-feature>` elements upgrade + connect on
   *     insertion; each one walks up via `shadowCrossingClosestByTag`
   *     to register with the enclosing `<map-layer>`, which rebuilds
   *     its aggregated GeoJSON source to include them. Mirrors
   *     MapML.js's `TemplatedFeaturesOrTilesLayer._onMoveEnd`
   *     lifecycle.
   *   * **Inline**: no `tref`. The link acts as a light-DOM
   *     container: authored `<map-feature>` children live directly
   *     under `<map-link>` and don't require any fetch. The
   *     `<map-layer>` rebuild walker (see
   *     `MapLayer.#rebuildFeatures`) dives into `<map-link
   *     rel="features">.children` to pick them up. No shadow root is
   *     attached in this mode \u2014 leaving the light DOM authoritative.
   *
   * Neither mode registers its own renderer layer with the extent:
   * the aggregated source is owned by `<map-layer>`, so per-layer
   * visibility / opacity fan-out already covers the features under
   * this link. This matches the existing inline-under-`<map-layer>`
   * feature model.
   */
  async #applyFeatures(viewer: MapmlViewer): Promise<void> {
    const extent = this.parentExtent;
    if (!extent) {
      console.warn(
        '<map-link rel="features"> must be inside a <map-extent>. Ignoring.'
      );
      return;
    }

    await viewer.whenReady();
    if (!this.#connected) return;

    // Inline mode: no tref \u2192 features are already light-DOM
    // children. They register with the enclosing `<map-layer>` on
    // their own; nothing to fetch, no listener to install. The
    // extent's disabled-cascade still needs to know we're a
    // renderable participant \u2014 `isVisible()` returns true for a
    // `rel="features"` inline link when the current view intersects
    // the extent's bbox + zoom.
    if (!this.hasAttribute('tref')) {
      extent.validateDisabled();
      return;
    }

    // Remote mode: attach shadow root, install moveend listener,
    // fire an initial fetch. Grafted features register with the
    // outer `<map-layer>` when they connect, so the layer's rebuild
    // walker picks them up automatically.
    this.#ensureShadowRoot();
    this.#featuresRemoteActive = true;

    const map = viewer.renderer.map;
    if (!map) return;

    // Re-validate the extent's disabled state BEFORE the initial
    // fetch. The extent may have been flagged `disabled` back when
    // it ran its own `connectedCallback` — at that point its
    // `<map-link>` children (including this one) hadn't upgraded
    // yet, so `#anyTemplateVisible()` walked raw HTMLElements whose
    // `isVisible()` was `undefined`. Now that we're upgraded, a
    // re-run picks us up and clears the stale `disabled` state
    // before `#fetchFeaturesForView` reads `extent.renders`.
    // Without this the initial fetch is skipped and features only
    // appear after the first user pan (moveend re-runs
    // `#anyTemplateVisible()` via the viewer's `#revalidateDisabled`
    // handler). The equivalent seam in MapML.js is
    // `TemplatedFeaturesOrTilesLayer._onAdd` calling `_validateDisabled`
    // on install.
    extent.validateDisabled();

    // Initial fetch against the current viewport. Failing to resolve
    // the template up-front is a warn-and-skip: we still install the
    // moveend listener in case the author adds inputs live.
    void this.#fetchFeaturesForView(map, viewer);

    const listener = (): void => {
      if (!this.#connected || !this.#featuresRemoteActive) return;
      const currentMap = viewer.renderer.map;
      if (!currentMap) return;
      void this.#fetchFeaturesForView(currentMap, viewer);
    };
    this.#moveendListener = listener;
    map.on('moveend', listener);
  }

  /**
   * Called by {@link MapExtent} when its `checked` state flips, so a
   * `rel="features"` remote link can (re)fetch fresh data for the
   * current viewport now that the extent is (again) rendering. No-op
   * for inline (no-tref) links \u2014 those don't fetch, and their light-
   * DOM `<map-feature>` children are re-picked-up by the layer's
   * rebuild walker on the next `notifyFeaturesChanged` pass.
   *
   * @internal Called only by `MapExtent.attributeChangedCallback`.
   */
  refreshFeatures(): void {
    if (!this.#featuresRemoteActive) return;
    const viewer = this.viewer;
    const map = viewer?.renderer.map;
    if (!viewer || !map) return;
    void this.#fetchFeaturesForView(map, viewer);
  }

  /**
   * {@link MapTileRunOwner} — a `<map-tile>` grafted into this
   * `rel="features"` link's shadow root registers on connect.
   * Schedules a coalesced rebuild of the tile-run raster source.
   */
  registerMapTile(tile: MapTile): void {
    if (this.#mapTiles.has(tile)) return;
    this.#mapTiles.add(tile);
    this.notifyMapTilesChanged();
  }

  /**
   * {@link MapTileRunOwner} — a grafted `<map-tile>` unregisters on
   * disconnect (the previous graft is wiped before each fetch). When
   * the last tile leaves, {@link #rebuildTiles} tears the source down.
   */
  unregisterMapTile(tile: MapTile): void {
    if (!this.#mapTiles.delete(tile)) return;
    this.notifyMapTilesChanged();
  }

  /**
   * {@link MapTileRunOwner} — coalesced rebuild trigger. A whole
   * graft's worth of tile connects / disconnects in one synchronous
   * block (see {@link #fetchFeaturesForView}) folds into a single
   * source upload on the next microtask, mirroring
   * {@link MapLayer.notifyFeaturesChanged}.
   */
  notifyMapTilesChanged(): void {
    if (this.#mapTilesChangeScheduled) return;
    this.#mapTilesChangeScheduled = true;
    queueMicrotask(() => {
      this.#mapTilesChangeScheduled = false;
      void this.#rebuildTiles();
    });
  }

  /**
   * Rebuild the raster source backing this link's grafted
   * `<map-tile>` run. Collects every registered tile's `src` into a
   * `"z/x/y"` → URL table (relative srcs resolved against the link's
   * base), unions their footprints for the source `bounds`, and hands
   * the result to the renderer's `mapmltile://` handle. Lazy-creates
   * the handle on the first non-empty pass and slots it into the
   * parent extent's group so opacity + rendered-state cascade from the
   * extent / layer reach it; tears it down when the last tile is gone.
   *
   * The MapML.js analog is `TemplatedFeaturesOrTilesLayer` building a
   * `MapTileLayer` per contiguous `<map-tile>` run. This port folds a
   * link's tiles into ONE source: OSMTILE tiles at a given zoom never
   * overlap, so a single raster mosaic is equivalent and avoids the
   * per-run bookkeeping. (Arbitrary interleaving of raster runs ABOVE
   * feature runs within one link is not modelled here — grafted
   * features aggregate at the `<map-layer>` level and paint above this
   * source.)
   */
  async #rebuildTiles(): Promise<void> {
    const viewer = this.viewer;
    if (!viewer) return;
    await viewer.whenReady();
    // Bail if we disconnected (or got re-hosted) while awaiting the
    // initial style load.
    if (!this.#connected || this.viewer !== viewer) return;
    const extent = this.parentExtent ?? this.#owningExtent;
    if (extent === null) return;

    const tiles = new Map<string, string>();
    for (const tile of this.#mapTiles) {
      const src = tile.src;
      if (src === '') continue;
      // Iteration is registration (== graft-append == DOM) order; a
      // later duplicate cell wins, matching a re-declared tile.
      tiles.set(tile.tileKey, this.#resolveAgainstBase(src));
    }

    if (tiles.size === 0) {
      if (this.#tileRunHandle !== undefined) {
        const handle = this.#tileRunHandle;
        this.#tileRunHandle = undefined;
        extent.group.removeLayer(handle);
        handle.remove();
        viewer.notifyLayersChanged();
      }
      return;
    }

    if (this.#tileRunHandle !== undefined) {
      // Same run, changed `src`(s): re-register the table + force a
      // reload through the protocol handler.
      this.#tileRunHandle.setTiles(tiles);
      return;
    }

    const id = `map-tiles-${++nextMapTileRunId}`;
    // No `minzoom` / `maxzoom` / `bounds` on the source. The grafted
    // `<map-tile>`s are standard web-mercator (OSMTILE === XYZ) tiles,
    // and GeoServer (mapmlfeatures) picks the tile zoom from the
    // request's `bbox` + `width`/`height` — i.e. the on-screen
    // resolution. MapLibre's zoom is defined for 512px tiles, so a
    // 256px raster source's native covering zoom is `mapZoom + 1`,
    // which is exactly the zoom GeoServer returns for that resolution.
    // Leaving the source's zoom range and bounds unconstrained lets
    // MapLibre request that natural zoom on every view; the per-view
    // registry (refreshed on each `moveend` refetch, re-uploaded via
    // `setTiles`) is the sole data gate. Clamping the source to the
    // first view's tile zoom/bounds instead froze it: after a zoom or
    // pan MapLibre kept requesting the stale `z/x/y`, which the fresh
    // registry no longer held, and the mosaic went blank.
    this.#tileRunHandle = viewer.renderer.createMapTileRunLayer({
      id,
      tiles,
      visible: extent.renders
    });
    extent.group.addLayer(this.#tileRunHandle);
    viewer.notifyLayersChanged();
  }

  /**
   * Attach (or reuse) a shadow root on this link. Used by remote-mode
   * `rel="features"` to graft the fetched MapML fragment. `mode:
   * 'open'` so external JS + tests can inspect the grafted content
   * via `linkEl.shadowRoot`. Mirrors {@link MapLayer.#ensureShadowRoot}.
   */
  #ensureShadowRoot(): ShadowRoot {
    return this.shadowRoot ?? this.attachShadow({ mode: 'open' });
  }

  /**
   * One remote-mode fetch pass: evaluate the template against the
   * current view, GET `text/mapml`, parse the response as XML, and
   * adopt every `<map-feature>` (plus `<map-tile>` / `<map-link>` /
   * `<map-meta>` / `<map-style>`) into the shadow root, replacing
   * any previous graft. Adopted `<map-feature>` elements register
   * with the enclosing `<map-layer>` on connect, which triggers a
   * rebuild of the aggregated GeoJSON source.
   *
   * Concurrency: every call bumps `#featuresFetchToken`; if a
   * newer call has started by the time this one resolves, we bail
   * out. Never throws: network / parse / template errors log
   * a warning and leave the previous graft in place (matches
   * MapML.js's `_onMoveEnd` swallow-and-continue behaviour). The
   * one exception: when {@link isVisible} is false (out of zoom
   * range or bounds), we intentionally clear the shadow root so
   * a layer that just moved out of view doesn't leak stale
   * features onto the aggregated source.
   */
  async #fetchFeaturesForView(map: MapLibreMap, viewer: MapmlViewer): Promise<void> {
    const extent = this.parentExtent ?? this.#owningExtent;
    if (extent === null) return;
    const tref = this.tref;
    if (tref === '') return;

    const token = ++this.#featuresFetchToken;

    // Not rendering (extent or layer unchecked, or extent disabled):
    // don't fire a fetch \u2014 there's nothing to draw and the
    // aggregated-source walker in `MapLayer.#rebuildFeatures` filters
    // by `extent.renders` too. Keep any prior graft in the shadow
    // root; the walker will skip it while unchecked and pick it
    // back up on re-check. Fresh data on re-check comes from
    // `MapExtent.attributeChangedCallback('checked')` calling
    // {@link refreshFeatures} on each child `rel="features"` link.
    if (!extent.renders) {
      return;
    }

    // Off-view / off-zoom: wipe any previously-grafted features so
    // they don't stay on the aggregated GeoJSON source. Matches
    // MapML.js's `_onMoveEnd` shortcut: `if (!this.isVisible())
    // { this.clearLayers(); return; }`.
    if (!this.isVisible()) {
      if (this.shadowRoot && this.shadowRoot.children.length > 0) {
        this.shadowRoot.replaceChildren();
      }
      return;
    }

    const view = buildViewSnapshot(map);
    const resolved = evaluateFeaturesTemplate(
      tref,
      extent.getInputs(),
      extent.units,
      view
    );
    if (resolved.kind === 'error') {
      console.warn(`<map-link rel="features">: ${resolved.reason}`);
      return;
    }
    const url = this.#resolveAgainstBase(resolved.url);

    let response: Response;
    try {
      response = await fetch(url, {
        redirect: 'follow',
        headers: { Accept: 'text/mapml' }
      });
    } catch (err) {
      console.warn(
        `<map-link rel="features"> fetch failed for ${url}: ${
          err instanceof Error ? err.message : String(err)
        }`
      );
      return;
    }
    if (token !== this.#featuresFetchToken) return;
    if (!this.#connected) return;
    if (!response.ok) {
      console.warn(
        `<map-link rel="features"> non-OK response for ${url}: HTTP ${response.status}`
      );
      return;
    }
    const text = await response.text();
    if (token !== this.#featuresFetchToken) return;
    if (!this.#connected) return;

    const parser = new DOMParser();
    let doc: XMLDocument;
    try {
      doc = parser.parseFromString(text, 'application/xml');
    } catch (err) {
      console.warn(
        `<map-link rel="features"> XML parse failed for ${url}: ${
          err instanceof Error ? err.message : String(err)
        }`
      );
      return;
    }
    if (doc.querySelector('parsererror')) {
      console.warn(`<map-link rel="features"> XML parse error in ${url}`);
      return;
    }

    // Same legal-content query MapML.js uses in
    // `TemplatedFeaturesOrTilesLayer._onMoveEnd` \u2014 excludes
    // `<map-extent>` (which would nest an inner templated layer)
    // but includes tiles + features + any accompanying styles /
    // meta / license links from the fragment's `<map-head>`.
    const grafts = doc.querySelectorAll(
      'map-head > map-link, map-body > map-link,' +
        'map-head > map-meta, map-body > map-meta,' +
        'map-head > map-style, map-body > map-style,' +
        'map-tile, map-feature'
    );

    const shadow = this.#ensureShadowRoot();
    // Wipe old graft first so grafted `<map-feature>` disconnect
    // callbacks fire in a defined order (before the new ones connect).
    // This produces a single coalesced rebuild on the enclosing
    // `<map-layer>` \u2014 both unregister-batches and register-batches
    // schedule via the same microtask flag.
    shadow.replaceChildren();

    const frag = document.createDocumentFragment();
    for (const node of grafts) {
      // Adopt from the XML doc into the host document so custom-
      // element upgrade kicks in. Because the fetched doc's
      // `<mapml->` root carries `xmlns="http://www.w3.org/1999/xhtml"`,
      // adopted elements arrive in the HTML namespace and upgrade
      // automatically on insertion.
      frag.appendChild(document.adoptNode(node));
    }
    if (token !== this.#featuresFetchToken) return;
    if (!this.#connected) return;
    shadow.appendChild(frag);
    // Suppress unused warning until the viewer plumbing needs it.
    void viewer;
  }

  /**
   * Resolve this link's `tref` against the given click event,
   * fetch the URL, parse the response, and return the array of
   * feature-shaped popup entries. Called by
   * {@link MapmlViewer#handleQueryClick} \u2014 the viewer's central
   * coordinator \u2014 for every registered + visible query link on
   * each map click, and aggregates the results into a single
   * popup.
   *
   * Never throws: network errors, non-OK responses, malformed
   * responses, disabled-links, and links that can't resolve their
   * template all short-circuit to an empty array so the coordinator
   * treats them as "this link contributed nothing to the group".
   *
   * @internal Called only by MapmlViewer's coordinator.
   */
  async performQueryFetch(
    e: MapMouseEvent
  ): Promise<QueryFeatureProperties[]> {
    if (this.disabled) return [];
    const viewer = this.viewer;
    if (!viewer) return [];
    const map = viewer.renderer.map;
    if (!map) return [];
    const tref = this.tref;
    const extent = this.parentExtent ?? this.#owningExtent;
    if (tref === '' || extent === null) return [];

    const view = buildViewSnapshot(map);
    const click = buildClickSnapshot(map, e, view);
    const resolved = evaluateQueryTemplate(
      tref,
      extent.getInputs(),
      extent.units,
      view,
      click
    );
    if (resolved.kind === 'error') {
      console.warn(`<map-link rel="query">: ${resolved.reason}`);
      return [];
    }

    // Resolve relative trefs against the owning `<map-layer>`'s
    // `src` when this link is shadow-hosted, else against the host
    // page. This is what makes `queryFeatureCSFallback`-style
    // remote docs work: their `tref`s are relative to the remote
    // doc's URL, not the page's.
    const url = this.#resolveAgainstBase(resolved.url);

    let response: Response;
    try {
      response = await fetch(url, { redirect: 'follow' });
    } catch (err) {
      console.warn(
        `<map-link rel="query"> fetch failed for ${url}: ${
          err instanceof Error ? err.message : String(err)
        }`
      );
      return [];
    }
    if (!this.#connected) return [];
    if (!response.ok) {
      console.warn(
        `<map-link rel="query"> non-OK response for ${url}: HTTP ${response.status}`
      );
      return [];
    }
    const contentType = (response.headers.get('Content-Type') ?? '').toLowerCase();
    const text = await response.text();
    if (!this.#connected) return [];

    // Snapshot the map's zoom at fetch-completion time so query
    // responses that don't declare a `<map-feature zoom="N">`
    // attribute get a sensible default for their "Zoom to here"
    // link. `Math.round` matches MapML `<map-input type="zoom">`
    // integer semantics.
    const currentZoom = Math.round(map.getZoom());
    return parseQueryResponse(
      contentType,
      text,
      e.lngLat.lng,
      e.lngLat.lat,
      extent.units,
      viewer.locale,
      currentZoom
    );
  }

  /**
   * Track D — `<map-link rel="stylesheet" href="…">`. Fetches the CSS
   * text at `href` and registers a
   * {@link ../elements/map-layer.StyleContributor} with the enclosing
   * `<map-layer>`'s style aggregator, so the compiled rules feed the
   * same paint-expression pipeline as inline `<map-style>` blocks.
   * DOM styling (Track A) also applies — MapLibre's fetch response
   * is mirrored into a `<style>` in the viewer shadow root by the
   * layer's aggregator, so popup / control CSS in the stylesheet
   * works too (via the compiled ruleset falling through to unknown-
   * property paths, which are silently dropped for paint but still
   * present in the mirrored `<style>`).
   *
   * The contributor object is retained across fetch cycles: on
   * `href` change we bump `#stylesheetFetchToken`, re-fetch, and
   * mutate the same contributor in place — so the layer doesn't
   * see a register/unregister flap. Registration happens on the
   * first successful fetch; contribution is inactive (`isActive =
   * false`) until then, matching the "no styles applied until the
   * stylesheet has actually loaded" `<link rel="stylesheet">`
   * baseline behaviour.
   *
   * Concurrency: same monotonic-token guard as `rel="features"`.
   * Errors log a warning and leave the previous contribution in
   * place (idempotent — a subsequent successful fetch overwrites
   * the stale text).
   */
  async #applyStylesheet(): Promise<void> {
    const href = this.href;
    if (href === '') {
      console.warn(
        '<map-link rel="stylesheet">: missing `href` attribute; nothing to fetch.'
      );
      return;
    }
    // Branch on `type`: the JSON MapLibre-style variant is a distinct
    // pipeline from CSS. It doesn't register with the layer's style
    // aggregator (nothing to compile into paint expressions or mirror
    // into a `<style>`); it just fetches the JSON, parses it, and
    // signals sibling pmtiles tile links via
    // {@link whenPmtilesStyleReady}.
    if (this.type === MAPLIBRE_STYLE_JSON_TYPE) {
      await this.#applyPmtilesStylesheet(href);
      return;
    }
    // Walk up to the enclosing `<map-layer>`. Missing → the link is
    // used out-of-context; log and bail. Direct-child-of-viewer
    // authoring isn't in scope for v1 — style scoping is per-layer.
    const owner = this.parentLayer;
    if (owner === null) {
      console.warn(
        '<map-link rel="stylesheet">: no enclosing <map-layer>; ' +
          'stylesheet is scoped to a layer\'s features + shadow-root DOM.'
      );
      return;
    }
    // Register a fresh contributor if we don't already have one.
    // (Re-using the same object across href changes means the
    // layer's aggregator sees the mutated `cssText` without a
    // register / unregister flap.)
    if (this.#stylesheetContributor === null) {
      this.#stylesheetContributor = { cssText: '', isActive: false };
      this.#stylesheetOwner = owner;
      owner.registerStyle(this.#stylesheetContributor);
    } else if (this.#stylesheetOwner !== owner) {
      // Owner changed (rare — link re-parented). Unregister from
      // the old owner and register with the new.
      this.#stylesheetOwner?.unregisterStyle(this.#stylesheetContributor);
      this.#stylesheetOwner = owner;
      owner.registerStyle(this.#stylesheetContributor);
    }

    const token = ++this.#stylesheetFetchToken;
    const resolvedUrl = this.#resolveAgainstBase(href);
    let text: string;
    try {
      const response = await fetch(resolvedUrl);
      if (!response.ok) {
        console.warn(
          `<map-link rel="stylesheet" href="${href}">: HTTP ${response.status}; ignoring.`
        );
        return;
      }
      text = await response.text();
    } catch (err) {
      console.warn(
        `<map-link rel="stylesheet" href="${href}">: fetch failed — ${
          (err as Error).message ?? String(err)
        }`
      );
      return;
    }
    // Newer fetch already started (href changed, or link torn down
    // + re-applied). Discard our response — the newer call owns
    // the contributor now.
    if (token !== this.#stylesheetFetchToken) return;
    if (!this.#connected || this.#stylesheetContributor === null) return;

    this.#stylesheetContributor.cssText = text;
    this.#stylesheetContributor.isActive = true;
    this.#stylesheetOwner?.notifyStylesChanged();
  }

  /**
   * Fetch a MapLibre-style JSON document at `href` and store the
   * parsed result on {@link #pmtilesStyle}. Signals sibling pmtiles
   * tile links via the {@link whenPmtilesStyleReady} promise.
   *
   * Unlike the CSS stylesheet path, this variant does NOT register
   * with the enclosing `<map-layer>`'s style aggregator \u2014 the
   * output is consumed directly by the pmtiles tile-link renderer,
   * not compiled into paint expressions for feature layers.
   *
   * The ready promise identity is captured at fetch start and
   * released on completion. Consumers calling
   * {@link whenPmtilesStyleReady} before this method runs get a
   * pre-allocated promise that resolves when this method finishes.
   *
   * Concurrency: same monotonic-token guard as the CSS branch.
   * Errors reject the ready promise so awaiting consumers unblock
   * (rather than hang) on a broken stylesheet.
   */
  async #applyPmtilesStylesheet(href: string): Promise<void> {
    // Bump the generation before we start the new fetch so sibling
    // tile links inspecting {@link refreshIfStylesheetChanged} see a
    // mismatch against the generation they recorded on their last
    // apply. Without this, an `href` swap on an in-scope stylesheet
    // would leave siblings painting with the stale `layers[]` (the
    // identity check alone can't distinguish "same element / new
    // content"). Bumping *before* the fetch (rather than on success)
    // ensures the synchronous `#refreshVectorTileSiblings()` call from
    // `attributeChangedCallback` sees the new generation and forces a
    // re-apply that then awaits this fetch's `whenPmtilesStyleReady()`.
    this.#pmtilesStyleGeneration++;
    // Materialise the ready promise up-front so pmtiles tile links
    // that call `whenPmtilesStyleReady()` mid-fetch get a
    // subscription to *this* fetch's outcome (rather than a
    // resolved promise for the previous fetch's payload).
    if (this.#pmtilesStyleReady === null) {
      this.#pmtilesStyleReady = new Promise<void>((resolve, reject) => {
        this.#pmtilesStyleReadyResolve = resolve;
        this.#pmtilesStyleReadyReject = reject;
      });
    }

    const token = ++this.#stylesheetFetchToken;
    const resolvedUrl = this.#resolveAgainstBase(href);
    let json: unknown;
    try {
      const response = await fetch(resolvedUrl);
      if (!response.ok) {
        const err = new Error(
          `HTTP ${response.status} fetching stylesheet at ${href}`
        );
        console.warn(
          `<map-link rel="stylesheet" href="${href}">: ${err.message}; ignoring.`
        );
        this.#pmtilesStyleReadyReject?.(err);
        this.#pmtilesStyleReadyResolve = null;
        this.#pmtilesStyleReadyReject = null;
        return;
      }
      json = await response.json();
    } catch (err) {
      const wrapped =
        err instanceof Error ? err : new Error(String(err));
      console.warn(
        `<map-link rel="stylesheet" href="${href}">: fetch failed \u2014 ${wrapped.message}`
      );
      this.#pmtilesStyleReadyReject?.(wrapped);
      this.#pmtilesStyleReadyResolve = null;
      this.#pmtilesStyleReadyReject = null;
      return;
    }
    // Newer fetch already started (href changed, or link torn down
    // + re-applied). Discard our response.
    if (token !== this.#stylesheetFetchToken) return;
    if (!this.#connected) return;

    // Validate the parsed shape. MapLibre style specs are objects
    // with a `layers` array; treat anything else as an authoring
    // error and reject.
    if (
      typeof json !== 'object' ||
      json === null ||
      !Array.isArray((json as { layers?: unknown }).layers)
    ) {
      const err = new Error(
        'MapLibre style JSON is missing a `layers` array; nothing to render.'
      );
      console.warn(
        `<map-link rel="stylesheet" href="${href}"> type="${MAPLIBRE_STYLE_JSON_TYPE}": ${err.message}`
      );
      this.#pmtilesStyleReadyReject?.(err);
      this.#pmtilesStyleReadyResolve = null;
      this.#pmtilesStyleReadyReject = null;
      return;
    }

    this.#pmtilesStyle = {
      layers: (json as { layers: ReadonlyArray<Record<string, unknown>> })
        .layers,
      // Forward the optional `glyphs` field so pmtiles tile links can
      // wire `map.setGlyphs(...)`. The value can be omitted entirely,
      // in which case any `symbol` layer with a `text-field` will
      // silently render nothing — the standard MapLibre behaviour
      // when a font server isn't configured.
      ...(typeof (json as { glyphs?: unknown }).glyphs === 'string'
        ? { glyphs: (json as { glyphs: string }).glyphs }
        : {})
    };
    this.#pmtilesStyleReadyResolve?.();
    this.#pmtilesStyleReadyResolve = null;
    this.#pmtilesStyleReadyReject = null;
    // Cascade to sibling vector-tile links now that this stylesheet
    // has usable `layers[]`. Two authoring paths matter:
    //   * Dynamic append \u2014 a stylesheet added at runtime via
    //     `layer.append(link)` shows up here (its `connectedCallback`
    //     fires `#apply` -> `#applyPmtilesStylesheet`). Sibling tile
    //     links registered before we existed had `#activeStylesheet
    //     === null`; they now re-pick us.
    //   * `href` swap on an existing stylesheet \u2014 the fetched
    //     `layers[]` may differ from what its consumers were painting
    //     with. `refreshIfStylesheetChanged` catches this via the
    //     `#pmtilesStyleGeneration` bump at the top of this method
    //     (identity is unchanged but generation moved), so consumers
    //     tear down and re-apply against the new `layers[]`.
    // Tile links awaiting `whenPmtilesStyleReady()` unblock via the
    // resolver above and don't need the cascade; the cascade covers
    // the "no consumer was waiting yet" case.
    this.#refreshVectorTileSiblings();
  }

  /**
   * Build the radio-button `<div>` returned by
   * {@link getLayerControlOption} for a `rel="style"` /
   * `rel="self style"` / `rel="style self"` (and the underspecified
   * `rel="self"`) link. The div is not appended anywhere here — the
   * enclosing `<map-layer>`'s {@link MapLayer.getLayerControlHTML}
   * gathers every style link's option and drops them into a shared
   * `<details class="mapml-layer-item-style">` fieldset.
   *
   * Ports MapML.js's `_createSelfOrStyleLink()` in
   * `src/map-link.js`. Two shape details worth calling out:
   *
   *   1. **Radio grouping.** All radios in the same owning
   *      `<map-layer>` share a `name` attribute so exactly one is
   *      picked at a time. The `<map-layer>` is captured at build
   *      time so a subsequent teardown / rebuild in a fresh
   *      fieldset uses the same group name (or a fresh one if the
   *      layer identity has changed).
   *   2. **`self` vs `style`.** `rel="self style"` (or
   *      `rel="style self"`) means "this link URL is the *currently
   *      loaded* stylesheet"; its radio starts checked. Plain
   *      `rel="style"` marks an *alternate*, unchecked at start.
   *
   * On click, the radio dispatches a bubbling `changestyle`
   * `CustomEvent` at the owning `<map-layer>` carrying the resolved
   * `href` in `detail.src`. The layer's listener sets its `src`
   * attribute to that URL, which triggers `attributeChangedCallback
   * → #loadRemote` — matching MapML.js's `layer.js` `_onAdd`
   * handler that pipes `changestyle` into `this.src = e.detail.src`.
   */
  #applyStyle(): void {
    const owner = this.parentLayer;
    if (owner === null) {
      // No enclosing <map-layer>: style link is orphaned. Nothing to
      // participate in a layer-control radio group with, so skip.
      return;
    }

    // Resolve the href once so the `data-href` we hand to the
    // change-listener is absolute — a relative `href` in a remote
    // MapML doc must resolve against that doc's URL, not the host
    // page's. `#resolveAgainstBase` handles the shadow-hosting case.
    const href = this.href;
    if (href === '') {
      // Nothing to switch to; still produce a radio so the label
      // shows, but leave `data-href` empty (click will no-op).
    }

    const div = document.createElement('div');
    const input = document.createElement('input');
    input.type = 'radio';
    const optionId = `mapml-style-option-${++nextLinkId}`;
    input.id = optionId;
    // Radio-group name is stable per owning layer so all this
    // layer's style links radio-group together. `nextControlId`
    // gives us a monotonic suffix; capture on the owner so
    // subsequent rebuilds reuse it.
    const ownerWithGroup = owner as MapLayer & { _styleGroupName?: string };
    if (!ownerWithGroup._styleGroupName) {
      ownerWithGroup._styleGroupName = `mapml-style-group-${++nextLinkId}`;
    }
    input.name = ownerWithGroup._styleGroupName;
    input.value = this.getAttribute('title') ?? '';
    input.setAttribute(
      'data-href',
      href === '' ? '' : this.#resolveAgainstBase(href)
    );
    const label = document.createElement('label');
    label.setAttribute('for', optionId);
    label.textContent = this.getAttribute('title') ?? '';

    // `rel="self style"` / `rel="style self"` marks the currently
    // loaded stylesheet — its radio starts checked so authors can
    // *see* which alternate is currently active.
    const rel = this.rel;
    if (rel === 'self style' || rel === 'style self') {
      input.checked = true;
    }

    input.addEventListener('click', (e) => {
      const target = e.currentTarget as HTMLInputElement;
      const src = target.getAttribute('data-href') ?? '';
      if (!src) return;
      e.stopPropagation();
      // Dispatch on the owning layer (captured at build time). The
      // layer's `changestyle` listener sets its `src` attribute,
      // which triggers a re-fetch via `attributeChangedCallback`.
      owner.dispatchEvent(
        new CustomEvent('changestyle', { detail: { src } })
      );
    });

    div.appendChild(input);
    div.appendChild(label);
    this.#styleOption = div;
    // Nudge the layer control to rebuild so a freshly-connected
    // style link becomes visible in the settings panel without
    // waiting for the next layer-level event.
    this.viewer?.notifyLayersChanged();
  }

  /**
   * MapML.js JS-API parity: return the radio-button `<div>` this
   * link contributes to its owning `<map-layer>`'s layer-control
   * fieldset for `rel="style"` / `rel="self style"` /
   * `rel="style self"` links. Returns `null` for every other rel.
   *
   * Called by {@link MapLayer.getLayerControlHTML} while building
   * the layer's `<details class="mapml-layer-item-style">` group.
   */
  getLayerControlOption(): HTMLDivElement | null {
    return this.#styleOption;
  }

  /**
   * Wire (or rewire) this link's `media` gate.
   *
   * Ports MapML.js's `<map-link>._registerMediaQuery` in
   * `src/map-link.js`. Idempotent per attribute value; the change
   * handler is bound lazily on the first call so
   * `removeEventListener` sees the same identity across
   * re-registrations.
   *
   * - When `mq` is a non-empty string, we await the viewer's
   *   `whenReady` (`viewer.matchMedia` needs a live extent for the
   *   `map-*-easting` / `map-*-northing` features), build a fresh
   *   `MediaQueryList`, run the change handler once to seed
   *   `disabled`, and subscribe to the `change` event.
   * - When `mq` is empty, we tear the matcher down and force
   *   `disabled = false`, mirroring MapML.js's "no / empty media
   *   attribute matches" branch.
   *
   * All downstream teardown / re-apply cascades through the
   * `disabled` attribute observer — we intentionally don't call
   * `#apply` / `#teardown` here directly, so this method has a
   * single side effect (`this.disabled = …`) and stays cheap on
   * repeated calls.
   */
  async #registerMediaQuery(mq: string): Promise<void> {
    if (this.#mqlChangeHandler === null) {
      this.#mqlChangeHandler = (): void => {
        if (this.#mql === null) return;
        this.disabled = !this.#mql.matches;
      };
    }
    // Drop any prior subscription first, in every branch — a media
    // attribute swap (or removal) is authoritative.
    this.#teardownMediaQuery();

    if (mq === '') {
      // Empty / removed media attribute: matches unconditionally.
      // Force `disabled = false`; the attribute observer will fire
      // `#apply` if we were previously disabled.
      this.disabled = false;
      return;
    }

    const viewer = this.viewer ?? this.#owningViewer;
    if (viewer === null) return;

    // Guard against a stale `whenReady` resolution clobbering a
    // fresher `media` value. Bumped for each registration; the
    // resolve callback bails if the token has moved.
    this.#mqlRegisterToken += 1;
    const token = this.#mqlRegisterToken;
    await viewer.whenReady();
    if (
      token !== this.#mqlRegisterToken ||
      !this.#connected ||
      this.media !== mq
    ) {
      return;
    }
    this.#mql = viewer.matchMedia(mq);
    // Initial evaluation seeds `disabled` before we subscribe, so
    // the attribute observer runs at most once per registration.
    this.#mqlChangeHandler();
    this.#mql.addEventListener('change', this.#mqlChangeHandler);
  }

  /**
   * Tear down the current `#mql` subscription, if any. Idempotent.
   * Retains `#mqlChangeHandler` across calls so a subsequent
   * registration reuses the same bound identity.
   */
  #teardownMediaQuery(): void {
    if (this.#mql !== null && this.#mqlChangeHandler !== null) {
      this.#mql.removeEventListener('change', this.#mqlChangeHandler);
    }
    this.#mql = null;
  }

  #teardown(): void {
    // Invalidate any in-flight `#applyVectorTile` so its post-await
    // continuations bail before double-registering a layer. Cheap
    // \u2014 the token is a number.
    this.#vectorTileApplyToken++;
    this.#activeStylesheet = null;
    this.#activeStylesheetGeneration = 0;

    const viewer = this.viewer ?? this.#owningViewer;
    const map = viewer?.renderer.map;

    // Detach the moveend listener (image + features remote links)
    // regardless of whether a renderer layer was ever installed \u2014
    // query links don't have this listener but the field is safely
    // undefined.
    if (map && this.#moveendListener) {
      map.off('moveend', this.#moveendListener);
    }
    this.#moveendListener = undefined;

    // Features remote-mode: wipe any grafted shadow content so the
    // enclosing `<map-layer>`'s aggregated GeoJSON source drops the
    // grafted features on the next rebuild (triggered by each
    // grafted feature's `disconnectedCallback` firing). Bumping the
    // fetch token guards against a mid-flight fetch resurrecting
    // grafts after teardown.
    if (this.#featuresRemoteActive) {
      this.#featuresFetchToken++;
      if (this.shadowRoot && this.shadowRoot.children.length > 0) {
        this.shadowRoot.replaceChildren();
      }
      this.#featuresRemoteActive = false;
    }

    // Query links live in the viewer's query-click coordinator
    // rather than owning a map-level click listener directly.
    // Unregister so the coordinator uninstalls its own click
    // handler if we were the last participant.
    if (this.#registeredAsQueryLink) {
      viewer?.unregisterQueryLink(this);
      this.#registeredAsQueryLink = false;
    }

    // Stylesheet contributor: bump the fetch token so any in-flight
    // fetch discards its response, unregister from the layer's style
    // aggregator, and drop our references. `notifyStylesChanged` is
    // called by `unregisterStyle`, so the aggregator recompiles
    // without our rules on the next microtask.
    if (this.#stylesheetContributor !== null) {
      this.#stylesheetFetchToken++;
      this.#stylesheetOwner?.unregisterStyle(this.#stylesheetContributor);
      this.#stylesheetContributor = null;
      this.#stylesheetOwner = null;
    }

    // MapLibre-style JSON stylesheet: bump the fetch token so any
    // in-flight fetch discards its response, drop the parsed style,
    // and reject any awaiting `whenPmtilesStyleReady()` promise so
    // consumers unblock rather than hang across a teardown.
    if (
      this.#pmtilesStyle !== null ||
      this.#pmtilesStyleReady !== null
    ) {
      this.#stylesheetFetchToken++;
      this.#pmtilesStyle = null;
      const reject = this.#pmtilesStyleReadyReject;
      this.#pmtilesStyleReady = null;
      this.#pmtilesStyleReadyResolve = null;
      this.#pmtilesStyleReadyReject = null;
      reject?.(new Error('<map-link> was torn down before stylesheet loaded'));
    }

    // `rel="style"` alternate-style radio option: drop the DOM
    // reference so the next `#apply()` builds a fresh element and
    // the layer control rebuild picks it up. No unregister needed
    // — the option div is a child of the layer control fieldset,
    // which gets replaced on the next `notifyLayersChanged`.
    if (this.#styleOption !== null) {
      this.#styleOption = null;
      // Nudge the layer control to drop the stale option from any
      // currently-visible fieldset. If the link was mid-teardown
      // as part of a full re-parenting the viewer may be null;
      // that's fine — the next rebuild will pick up the change.
      viewer?.notifyLayersChanged();
    }

    const extent = this.parentExtent ?? this.#owningExtent;

    if (this.#handle !== undefined) {
      const handle = this.#handle;
      this.#handle = undefined;
      this.#registeredId = undefined;
      // Detach from the extent's group first so no stale reference
      // remains to a dead handle, then tear down the underlying
      // MapLibre state. Both are idempotent; safe if the extent has
      // already disposed of the group.
      extent?.group.removeLayer(handle);
      handle.remove();
      extent?.viewer?.notifyLayersChanged();
    }
    // Tear down the grafted-tile raster mosaic (rel="features"). The
    // grafted `<map-tile>` disconnect callbacks that follow a shadow-
    // root wipe fire `unregisterMapTile` → `notifyMapTilesChanged`,
    // but that microtask rebuild bails because the link is no longer
    // connected — so drop the handle synchronously here.
    if (this.#tileRunHandle !== undefined) {
      const tileHandle = this.#tileRunHandle;
      this.#tileRunHandle = undefined;
      extent?.group.removeLayer(tileHandle);
      tileHandle.remove();
      extent?.viewer?.notifyLayersChanged();
    }
    // Tear down the `rel="tile" type="text/mapml"` link-owned feature
    // source (the raster-run handle rides on `#handle`, disposed above).
    // Clear the harvested-tile state so a re-apply starts clean.
    if (this.#mapmlFeatureHandle !== undefined) {
      const featureHandle = this.#mapmlFeatureHandle;
      this.#mapmlFeatureHandle = undefined;
      extent?.group.removeLayer(featureHandle);
      featureHandle.remove();
      extent?.viewer?.notifyLayersChanged();
    }
    this.#mapmlTileHandle = undefined;
    this.#mapmlTileFeatures.clear();
    this.#mapmlActiveZoom = undefined;
    this.#mapTiles.clear();
    // Mirror of the `#apply()` revalidation — removing the last
    // visible template on an extent should flip it (and its owning
    // layer) back to disabled without waiting for the next `moveend`.
    extent?.validateDisabled();
  }

  /**
   * Derive the source-spec extent slice ({@link RasterTileLayerOptions.minzoom}
   * / {@link RasterTileLayerOptions.maxzoom} /
   * {@link RasterTileLayerOptions.bounds}) that the renderer should
   * apply from the link's {@link extent} getter. Returns an object
   * ready to spread into the layer options; empty when the link has
   * no derivable extent (no tref / no parent extent).
   *
   * Priority (folded into `.extent`):
   *   - **zoom range** \u2014 parent-extent `<map-meta name="zoom">`
   *     \u2192 parent-layer `<map-meta name="zoom">` \u2192 sibling
   *     `<map-input type="zoom">` `min`/`max` \u2192 projection default.
   *   - **spatial bounds** \u2014 referenced `<map-input type="location">`
   *     min/max (interpreted at the sibling zoom input's `value`
   *     when the axes are in tilematrix/tcrs space \u2014 exactly the
   *     "z binds x/y" contract) \u2192 parent extent's
   *     `<map-meta name="extent">` \u2192 parent layer's
   *     `<map-meta name="extent">` \u2192 projection default.
   *
   * The zoom-range fallback to "projection default" and the bounds
   * fallback to "projection default" both mean "no useful
   * constraint", so we deliberately suppress those cases: pushing
   * `minzoom: 0, maxzoom: 24` and world-wide `bounds` to MapLibre
   * would be no-ops that just add noise to the serialised style.
   * We only forward values that came from a `<map-meta>` or
   * `<map-input>` \u2014 anything else is "unset".
   */
  #extentSpec(): {
    minzoom?: number;
    maxzoom?: number;
    bounds?: [number, number, number, number];
  } {
    const parent = this.parentExtent;
    if (parent === null) return {};
    const allInputs = parent.getInputs();
    const tokens = trefTokens(this.tref);
    const referenced =
      tokens.length === 0
        ? allInputs
        : allInputs.filter((i) => tokens.includes(i.name));

    const out: {
      minzoom?: number;
      maxzoom?: number;
      bounds?: [number, number, number, number];
    } = {};

    // Zoom: prefer extent-meta \u2192 layer-meta \u2192 input min/max.
    // Skip the "projection default" fallback \u2014 that's not a real
    // constraint. Also skip when there's neither a zoom input nor
    // any `<map-meta name="zoom">` in scope.
    const extentZm = parent.zoomMeta;
    const layerZm = this.parentLayer?.zoomMeta ?? null;
    const inputZ = inputsToZoomRange(referenced);
    if (extentZm !== null) {
      out.minzoom = extentZm.min;
      out.maxzoom = extentZm.max;
    } else if (layerZm !== null) {
      out.minzoom = layerZm.min;
      out.maxzoom = layerZm.max;
    } else if (inputZ !== null) {
      out.minzoom = inputZ.minZoom;
      out.maxzoom = inputZ.maxZoom;
    }

    // Bounds: prefer `<map-input type="location">` min/max
    // (interpreted at the sibling zoom input's `value` for
    // tilematrix / tcrs axes \u2014 the "z binds x/y" contract) \u2192
    // extent-meta \u2192 layer-meta. Skip the projection default.
    const pcrs = inputsToPcrsBounds(referenced, parent.units);
    if (pcrs !== null) {
      // Convert PCRS \u2192 GCRS (WGS84 degrees) for MapLibre's
      // source-spec `bounds` field.
      const gcrs = pcrsBoundsToGcrs(pcrs, parent.units);
      if (gcrs !== null) out.bounds = gcrs;
    } else {
      const em = parent.extentMeta;
      if (em !== null) {
        const gcrs = pcrsBoundsToGcrs(em.bounds, parent.units);
        if (gcrs !== null) out.bounds = gcrs;
      } else {
        const lm = this.parentLayer?.extentMeta ?? null;
        if (lm !== null) {
          const gcrs = pcrsBoundsToGcrs(lm.bounds, parent.units);
          if (gcrs !== null) out.bounds = gcrs;
        }
      }
    }
    return out;
  }

  /**
   * Inspect the `<map-input>`s named in `cornerMap` and return
   * whichever CS (`'pcrs'` or `'gcrs'`) those inputs declare via
   * `units`. `units="tilematrix"` is treated as PCRS to match MapML.js's
   * `TemplatedTileLayer._setUpTileTemplateVars`, which stores
   * tilematrix-labelled easting/northing inputs into the PCRS bucket.
   *
   * When corner inputs mix units — e.g. two `pcrs` and two `gcrs` in
   * the same tref — we fall back to `pcrs`. That case is an authoring
   * bug (WMS GetMap can only take one CS per request), but silently
   * picking one avoids a runtime crash; the resulting requests will
   * miss the map obviously enough that the author will notice.
   */
  #wmsTileUnits(
    cornerMap: Record<string, 'west' | 'south' | 'east' | 'north'>,
    extent: MapExtent
  ): 'pcrs' | 'gcrs' {
    const inputs = extent.getInputs();
    const inputByName = new Map(inputs.map((i) => [i.name, i]));
    for (const name of Object.keys(cornerMap)) {
      const input = inputByName.get(name);
      if (input?.units === 'gcrs') return 'gcrs';
    }
    return 'pcrs';
  }

  /**
   * Build attribution HTML from the owning layer's `<map-link rel="license">`
   * children. MapML conveys attribution through license links (per the
   * `<map-link>` spec — "the hyperlink is presented in the attribution
   * control") rather than an `attribution=` attribute. Multiple license
   * links are joined with `; ` for parity with MapLibre's own multi-source
   * attribution joiner.
   */
  /**
   * Public read of the owning layer's attribution string (its
   * `<map-link rel="license">` children, formatted). Used by the
   * viewer's query-click coordinator to surface attribution for
   * layers whose only renderable children are `<map-link rel="query">`
   * — such a layer registers no MapLibre source/image layer, so its
   * license text has nothing to ride on and would otherwise be lost.
   * Returns `undefined` when the owning layer declares no licenses.
   */
  get queryAttribution(): string | undefined {
    return this.#extractAttribution();
  }

  #extractAttribution(): string | undefined {
    const layer = this.parentLayer;
    if (!layer) return undefined;
    const parts: string[] = [];
    // `layer.contentRoot` is the layer's shadow root when it's in
    // remote mode (`src` attribute present), else the layer element
    // itself — so `<map-link rel="license">` copied from a remote
    // MapML `<map-head>` surfaces here alongside inline licenses.
    for (const child of layer.contentRoot.children) {
      if (child.tagName.toLowerCase() !== 'map-link') continue;
      const rel = (child.getAttribute('rel') ?? '').toLowerCase();
      if (rel !== 'license') continue;
      const title = child.getAttribute('title') ?? '';
      const href = child.getAttribute('href') ?? '';
      if (!title && !href) continue;
      parts.push(formatLicenseLink(title, href));
    }
    return parts.length > 0 ? parts.join('; ') : undefined;
  }
}

function formatLicenseLink(title: string, href: string): string {
  const text = escapeHtml(title || href);
  // Scheme-allowlist the author-supplied href: a `javascript:` /
  // `data:` license URL would otherwise execute on click even though
  // the attribute value is HTML-escaped. Non-http(s) hrefs render as
  // inert text. `noreferrer` closes the referrer-leak side channel.
  const safeHref = sanitizeHttpUrl(href);
  if (!safeHref) return text;
  return `<a href="${escapeHtml(safeHref)}" target="_blank" rel="noopener noreferrer">${text}</a>`;
}

/**
 * Resolve `raw` against the document base and return it only when the
 * scheme is `http:`/`https:`. Returns `''` for other schemes
 * (`javascript:`, `data:`, `blob:`, …) and malformed URLs.
 */
function sanitizeHttpUrl(raw: string): string {
  if (!raw) return '';
  try {
    const u = new URL(raw, document.baseURI);
    if (u.protocol === 'http:' || u.protocol === 'https:') return u.href;
  } catch {
    // malformed URL — fall through to empty return
  }
  return '';
}

/**
 * Convert a PCRS bbox (projection meters) to a MapLibre-shaped
 * `[west, south, east, north]` GCRS bbox (WGS84 degrees) for the
 * `bounds` field on a source spec.
 *
 * Returns `null` for non-OSMTILE projections \u2014 the port doesn't
 * carry the pcrs\u2192gcrs transforms for other projections yet. Same
 * v1 block as everywhere else; the caller silently omits `bounds`
 * in that case (matches "no useful constraint").
 */
function pcrsBoundsToGcrs(
  bounds: PcrsBounds,
  projection: string
): [number, number, number, number] | null {
  if (projection !== 'OSMTILE') return null;
  const [minX, minY] = bounds.min;
  const [maxX, maxY] = bounds.max;
  const [west, south] = osmtilePcrsToGcrs(minX, minY);
  const [east, north] = osmtilePcrsToGcrs(maxX, maxY);
  return [west, south, east, north];
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Snapshot the current viewport for `rel="image"` template resolution.
 * Both PCRS and GCRS bboxes describe the same rectangle so authors can
 * declare their `<map-input>` variables in either CS.
 *
 * `widthPx` / `heightPx` come from the map container's CSS pixel
 * dimensions \u2014 what a WMS server expects to render at
 * (deviceScale is a client-side rendering concern, not part of the
 * request). `zoom` is rounded to the nearest integer to match MapML
 * semantics (`<map-input type="zoom">` values are integers).
 */
function buildViewSnapshot(map: MapLibreMap): ViewSnapshot {
  const b = map.getBounds();
  const container = map.getContainer();
  // Clamp latitudes to the Web Mercator range: globe view (and very
  // zoomed-out mercator) reports bounds past ±85.05°, which would push a
  // mercator image source's coordinates to an out-of-bounds tile and
  // make MapLibre throw. The pcrs projection already clamps internally.
  const gcrs = {
    west: b.getWest(),
    south: Math.max(b.getSouth(), -MAX_MERCATOR_LATITUDE),
    east: b.getEast(),
    north: Math.min(b.getNorth(), MAX_MERCATOR_LATITUDE)
  };
  const [pWest, pSouth] = osmtileGcrsToPcrs(gcrs.west, gcrs.south);
  const [pEast, pNorth] = osmtileGcrsToPcrs(gcrs.east, gcrs.north);
  return {
    widthPx: container.clientWidth,
    heightPx: container.clientHeight,
    zoom: Math.round(map.getZoom()),
    gcrs,
    pcrs: {
      west: pWest,
      south: pSouth,
      east: pEast,
      north: pNorth
    }
  };
}

/**
 * Snapshot a click event for `rel="query"` template resolution. The
 * cursor position is expressed in every CRS a `<map-input>` might
 * declare so {@link evaluateQueryTemplate} can do a straight lookup
 * per token.
 *
 * OSMTILE only. Non-OSMTILE projections would need proj4 to
 * transform the GCRS click position into their PCRS \u2014 same block
 * as everywhere else in v1.
 */
function buildClickSnapshot(
  map: MapLibreMap,
  e: MapMouseEvent,
  view: ViewSnapshot
): ClickSnapshot {
  const zoom = Math.round(map.getZoom());
  const lng = e.lngLat.lng;
  const lat = e.lngLat.lat;
  const [pcrsX, pcrsY] = osmtileGcrsToPcrs(lng, lat);
  const tcrs = osmtilePcrsToTcrs(pcrsX, pcrsY, zoom);
  const col = Math.floor(tcrs.horizontal / OSMTILE_TILE_SIZE);
  const row = Math.floor(tcrs.vertical / OSMTILE_TILE_SIZE);
  // PCRS bbox of the tile containing the click. Same corner math the
  // `mapmlwmstile://` image protocol uses (top-left of (col,row),
  // bottom-right of (col+1,row+1)), so a tiled query's bbox lines up
  // exactly with the tile the user clicked.
  const [tileWest, tileNorth] = osmtileTilematrixToPcrs(col, row, zoom);
  const [tileEast, tileSouth] = osmtileTilematrixToPcrs(col + 1, row + 1, zoom);
  // `iPx` / `jPx` are the `units="map" axis="i|j"` cursor pixel that
  // WMS GetFeatureInfo unprojects *linearly within the Mercator BBOX*.
  // The raw container pixel (`e.point.x/y`) only maps linearly to that
  // bbox in flat, untilted map view; on the globe (or a tilted
  // perspective camera) the same pixel lands on a wildly different
  // Mercator point, so GeoServer returns the wrong feature. Reproject
  // the click's Mercator position into the view's Mercator bbox instead
  // — this yields a self-consistent (BBOX, WIDTH, HEIGHT, I, J) triple
  // in every view mode and collapses to `e.point.x/y` in flat map view.
  // Rounded to integer (WMS rejects fractional I/J with `InvalidPoint`)
  // and clamped to the viewport so edge clicks past the clamped bbox
  // don't produce out-of-range pixels.
  const spanX = view.pcrs.east - view.pcrs.west;
  const spanY = view.pcrs.north - view.pcrs.south;
  const rawI = spanX !== 0 ? ((pcrsX - view.pcrs.west) / spanX) * view.widthPx : 0;
  const rawJ = spanY !== 0 ? ((view.pcrs.north - pcrsY) / spanY) * view.heightPx : 0;
  const iPx = Math.min(Math.max(Math.round(rawI), 0), Math.max(view.widthPx - 1, 0));
  const jPx = Math.min(Math.max(Math.round(rawJ), 0), Math.max(view.heightPx - 1, 0));
  return {
    iPx,
    jPx,
    gcrs: { lng, lat },
    pcrs: { easting: pcrsX, northing: pcrsY },
    tcrs: { x: tcrs.horizontal, y: tcrs.vertical },
    tilematrix: { column: col, row: row },
    tile: {
      i: Math.round(tcrs.horizontal) - col * OSMTILE_TILE_SIZE,
      j: Math.round(tcrs.vertical) - row * OSMTILE_TILE_SIZE
    },
    tileBounds: {
      west: tileWest,
      south: tileSouth,
      east: tileEast,
      north: tileNorth
    }
  };
}
