/**
 * `<map-title>` — accessible title for the owning `<map-layer>`.
 *
 * Minimal element: carries `textContent` and nothing else. `<map-layer>`'s
 * `label` getter promotes a direct-child `<map-title>` (present when the
 * layer is loaded from a remote MapML doc — the fetched document's
 * `<map-head><map-title>…</map-title></map-head>` is grafted into the
 * layer's shadow root, and the layer's label reflects it) above the
 * host's own `label` attribute.
 *
 * Mirrors MapML.js's `<map-title>` in `src/mapml/layers/MapLayer.js`
 * `_initialize`, which reads the title from the fetched doc and marks
 * it as read-only in the layer control. This port ships the read side
 * only; the layer control has no rename affordance yet.
 *
 * The element produces no visible output and registers no MapLibre layer.
 */
export class MapTitle extends HTMLElement {
  /**
   * Trimmed `textContent`, or `null` when empty. `<map-layer>.label`
   * uses `null` as the signal to fall back to the `label` attribute.
   */
  get value(): string | null {
    const raw = this.textContent?.trim();
    return raw !== undefined && raw.length > 0 ? raw : null;
  }
}
