/**
 * MapML locale strings.
 *
 * The JSON files under `_locales/{lang}/messages.json` are vendored from the
 * `mapml-extension` project (https://github.com/Maps4HTML/mapml-extension)
 * so MapML-MapLibre presents the same UI text as MapML.js and the
 * Firefox MapML extension across all five shipped languages.
 *
 * Format: WebExtension messages.json — each entry is
 *   `{ "key": { "message": "...", "description": "..." } }`.
 * We flatten to `{ key: "..." }` at module load.
 *
 * Shortcut hints (e.g. `(Alt+Left Arrow)`) are *not* localized in
 * MapML.js — they stay in English so users see the same key in the
 * label and the keyboard. We follow the same policy.
 *
 * Locale resolution model (matches MapML.js's `_setLocale` in
 * `src/mapml-viewer.js` + `GlobalM.js`):
 *
 *   1. Five bundles are frozen at module load and exposed on the
 *      {@link M} singleton as `M.options.localeEn` / `localeFr` /
 *      `localeJa` / `localeSv` / `localeUk` (mirrors MapML.js which
 *      only bundles `localeEn` + `localeFr`; we ship more but the
 *      shape is identical). These never change after init.
 *   2. `M.options.locale` starts as the bundle that best matches
 *      `navigator.language`, defaulting to English. **Authors can
 *      replace it at runtime** by dropping a `<map-options>` element
 *      into `<head>` whose `innerHTML` is a JSON object with a
 *      `locale` field — its keys are copied over
 *      `M.options.locale` before any viewer connects.
 *   3. Per-viewer, {@link getViewerLocale} matches the viewer against
 *      the CSS `:lang()` selector (which respects the `lang`
 *      attribute inherited from `<html lang="…">` all the way down)
 *      and picks the corresponding bundle. Anything that doesn't
 *      match a bundled tag falls through to `M.options.locale`.
 *
 * `M` is also attached to `window` (browsers only) as a compatibility
 * escape hatch — `window.M.options.locale` is the same API MapML.js
 * pages use to inspect or override the active locale.
 */

import enRaw from './_locales/en/messages.json';
import frRaw from './_locales/fr/messages.json';
import jaRaw from './_locales/ja/messages.json';
import svRaw from './_locales/sv/messages.json';
import ukRaw from './_locales/uk/messages.json';

type RawLocale = Record<string, { message: string; description?: string }>;

/** Subset of locale keys consumed by MapML-MapLibre. Extend as porting progresses. */
export interface Locale {
  // Context-menu items
  cmBack: string;
  cmForward: string;
  cmReload: string;
  cmToggleControls: string;
  cmToggleDebug: string;
  cmCopyCoords: string;
  cmCopyMapML: string;
  cmCopyExtent: string;
  cmCopyLocation: string;
  cmPasteLayer: string;
  cmViewSource: string;
  // Button labels reused in the menu / on stock MapLibre controls
  btnFullScreen: string;
  btnExitFullScreen: string;
  btnZoomIn: string;
  btnZoomOut: string;
  btnAttribution: string;
  // Geolocate control — matches MapML.js `GeolocationButton`
  btnLocTrackOff: string;
  btnLocTrackOn: string;
  btnLocTrackLastKnown: string;
  btnMyLocTrackOn: string;
  btnMyLastKnownLocTrackOn: string;
  // Search control — matches MapML.js `SearchButton`
  /** `title` / `aria-label` for the search-open button. */
  btnSearch: string;
  /** `title` / `aria-label` for the search panel's close button. */
  btnSearchClose: string;
  /** `placeholder` for the search input. */
  searchPlaceholder: string;
  /** Fallback label when a search result feature has no name-like property. */
  searchResultWithNoName: string;
  // View control — toggles the `<mapml-viewer view>` presentation mode.
  // Opt-in via `controlslist="view"`.
  /** `title` / `aria-label` prefix for the view-toggle button. */
  btnView: string;
  /** Display name of the `map` (2-D) view. */
  viewMap: string;
  /** Display name of the `globe` view. */
  viewGlobe: string;
  /** Display name of the `perspective` (tilted) view. */
  viewPerspective: string;
  // Static control — toggles the `<mapml-viewer static>` attribute.
  // Opt-in via `controlslist="static"`.
  /** `title` / `aria-label` for the static-toggle button. */
  btnStatic: string;
  // Compass control — resets the camera to north-up. Opt-in via
  // `controlslist="compass"`.
  /** `title` / `aria-label` for the compass (reset-north) button. */
  btnCompass: string;
  // Feature-index overlay control — the numbered a11y list of features
  // overlapping the map-centre reticle. Opt-in via
  // `controlslist="featureindex"`.
  /** `title` / `aria-label` for the feature-index toggle button. */
  btnFeatureIndex: string;
  /** Overlay message when no feature overlaps the reticle. */
  fIndexNoFeatures: string;
  /** Overlay key `9` label — page to the next set of results. */
  fIndexMoreResults: string;
  /** Overlay key `8` label — page to the previous set of results. */
  fIndexPreviousResults: string;
  // Layer/extent right-click submenus
  lmZoomToLayer: string;
  lmCopyLayer: string;
  lmZoomToExtent: string;
  lmCopyExtent: string;
  // Layer-control fieldset controls (per-layer / per-extent)
  lmLayerSettings: string;
  lmRemoveLayer: string;
  lmExtentSettings: string;
  lmRemoveExtent: string;
  /**
   * Summary label for the `<details class="mapml-layer-item-style">`
   * radio group emitted per `<map-layer>` that advertises two or
   * more `rel="style"` links. Mirrors MapML.js's `locale.lmStyle`
   * (used by `layer.js#getAlternateStyles`).
   */
  lmStyle: string;
  lcOpacity: string;
  // Default display labels
  dfLayer: string;
  dfExtent: string;
  /**
   * Label applied to the `<map-layer>` wrapper that the paste action
   * generates when the clipboard contains a `<map-feature>` snippet.
   * Mirrors MapML.js's `locale.dfPastedLayer`.
   */
  dfPastedLayer: string;
  /**
   * Heading text for a feature-popup that has no
   * `<map-featurecaption>`. Mirrors MapML.js's `locale.dfFeatureCaption`.
   */
  dfFeatureCaption: string;
  // Feature-popup surfaces
  /**
   * Link label rendered at the bottom of a `<map-feature>` popup that
   * pans + zooms the viewer to the feature. Mirrors MapML.js's
   * `locale.popupZoom` (used by `attachZoomLink` in `MapLayer.js`).
   */
  popupZoom: string;
  /**
   * Column header for the "property name" column of the default
   * `<map-properties>` table emitted by
   * {@link buildPropertiesTable}. Mirrors MapML.js's
   * `locale.popupPropName` (used by `Util._properties2Table`).
   */
  popupPropName: string;
  /**
   * Column header for the "property value" column of the default
   * `<map-properties>` table. Mirrors MapML.js's
   * `locale.popupPropValue`.
   */
  popupPropValue: string;
  /**
   * `title` / `aria-label` for the popup nav bar's `|<` button, which
   * closes the popup and focuses the map. Mirrors MapML.js's
   * `locale.kbdFocusMap` (used by `_attachSkipButtons`).
   */
  kbdFocusMap: string;
  /**
   * `title` / `aria-label` for the popup nav bar's `<` button, which
   * cycles to the previous popup-carrying feature. Mirrors MapML.js's
   * `locale.kbdPrevFeature`.
   */
  kbdPrevFeature: string;
  /**
   * `title` / `aria-label` for the popup nav bar's `>` button, which
   * cycles to the next popup-carrying feature. Mirrors MapML.js's
   * `locale.kbdNextFeature`.
   */
  kbdNextFeature: string;
  /**
   * `title` / `aria-label` for the popup nav bar's `>|` button, which
   * closes the popup and focuses the first control. Mirrors MapML.js's
   * `locale.kbdFocusControls`.
   */
  kbdFocusControls: string;
  // Keyboard-shortcuts dialog — opened from the attribution popover.
  // Mirrors MapML.js's `AttributionButton` `.shortcuts-dialog`.
  /** Dialog heading + attribution-popover opener button label. */
  kbdShortcuts: string;
  /** `<b>` heading for the movement-keys list. */
  kbdMovement: string;
  /** `<b>` heading for the feature-navigation-keys list. */
  kbdFeature: string;
  /** List item: pan up. */
  kbdPanUp: string;
  /** List item: pan down. */
  kbdPanDown: string;
  /** List item: pan left. */
  kbdPanLeft: string;
  /** List item: pan right. */
  kbdPanRight: string;
  /** List item suffix: pan increment (with Shift / Ctrl modifiers). */
  kbdPanIncrement: string;
  /** List item: zoom in/out three levels (with Shift + / -). */
  kbdZoom: string;
  // AnnounceMovement — screen-reader movement announcements (opt-in
  // via `M.options.announceMovement`). Ported from MapML.js's
  // `AnnounceMovement` handler + the `am*` block in
  // `src/mapml/_locales/*/messages.json`.
  amZoom: string;
  amMaxZoom: string;
  amMinZoom: string;
  amZoomedOut: string;
  amDraggedOut: string;
  amEastBound: string;
  amWestBound: string;
  amNorthBound: string;
  amSouthBound: string;
}

/**
 * Ordered list of every {@link Locale} key MapML-MapLibre consumes today.
 *
 * Exported so bundle-integrity tests (and future features) can iterate
 * without hard-coding the list. Used at module load to `flatten` the
 * vendored WebExtension `messages.json` shape into a plain
 * `{ key: string }` record.
 */
export const LOCALE_KEYS: ReadonlyArray<keyof Locale> = [
  'cmBack',
  'cmForward',
  'cmReload',
  'cmToggleControls',
  'cmToggleDebug',
  'cmCopyCoords',
  'cmCopyMapML',
  'cmCopyExtent',
  'cmCopyLocation',
  'cmPasteLayer',
  'cmViewSource',
  'btnFullScreen',
  'btnExitFullScreen',
  'btnZoomIn',
  'btnZoomOut',
  'btnAttribution',
  'btnLocTrackOff',
  'btnLocTrackOn',
  'btnLocTrackLastKnown',
  'btnMyLocTrackOn',
  'btnMyLastKnownLocTrackOn',
  'btnSearch',
  'btnSearchClose',
  'searchPlaceholder',
  'searchResultWithNoName',
  'btnView',
  'viewMap',
  'viewGlobe',
  'viewPerspective',
  'btnStatic',
  'btnCompass',
  'btnFeatureIndex',
  'fIndexNoFeatures',
  'fIndexMoreResults',
  'fIndexPreviousResults',
  'lmZoomToLayer',
  'lmCopyLayer',
  'lmZoomToExtent',
  'lmCopyExtent',
  'lmLayerSettings',
  'lmRemoveLayer',
  'lmExtentSettings',
  'lmRemoveExtent',
  'lmStyle',
  'lcOpacity',
  'dfLayer',
  'dfExtent',
  'dfPastedLayer',
  'dfFeatureCaption',
  'popupZoom',
  'popupPropName',
  'popupPropValue',
  'kbdFocusMap',
  'kbdPrevFeature',
  'kbdNextFeature',
  'kbdFocusControls',
  'kbdShortcuts',
  'kbdMovement',
  'kbdFeature',
  'kbdPanUp',
  'kbdPanDown',
  'kbdPanLeft',
  'kbdPanRight',
  'kbdPanIncrement',
  'kbdZoom',
  'amZoom',
  'amMaxZoom',
  'amMinZoom',
  'amZoomedOut',
  'amDraggedOut',
  'amEastBound',
  'amWestBound',
  'amNorthBound',
  'amSouthBound'
];

/**
 * Flatten a WebExtension `messages.json` structure to a plain `Locale`
 * record. Missing keys fall back to `fallback` (typically English) so
 * per-language JSON files that lag behind the interface still yield a
 * complete object.
 */
function flatten(raw: RawLocale, fallback?: Locale): Locale {
  const out = {} as Locale;
  for (const k of LOCALE_KEYS) {
    out[k] = raw[k]?.message ?? fallback?.[k] ?? k;
  }
  return out;
}

/**
 * The five bundled locales.
 *
 * `localeEn` is built first (no fallback); every other bundle falls
 * back to it for keys the vendored JSON hasn't been updated for. Frozen
 * so authors can't accidentally mutate a shared object — mirrors
 * MapML.js's `M.options.localeEn` (a deep-copy taken at init time).
 */
export const localeEn: Locale = Object.freeze(flatten(enRaw as RawLocale));
export const localeFr: Locale = Object.freeze(flatten(frRaw as RawLocale, localeEn));
export const localeJa: Locale = Object.freeze(flatten(jaRaw as RawLocale, localeEn));
export const localeSv: Locale = Object.freeze(flatten(svRaw as RawLocale, localeEn));
export const localeUk: Locale = Object.freeze(flatten(ukRaw as RawLocale, localeEn));

/**
 * Map of bundled locale tags → `Locale`. Used by {@link getViewerLocale}
 * to build the `:lang()` selector chain (`:lang(fr)`, `:lang(ja)`…)
 * and to look up the corresponding bundle when a viewer matches.
 */
export const BUNDLED_LOCALES: Readonly<Record<string, Locale>> = Object.freeze({
  en: localeEn,
  fr: localeFr,
  ja: localeJa,
  sv: localeSv,
  uk: localeUk
});

/** Default locale, used as a fallback when nothing better matches. */
export const defaultLocale: Locale = localeEn;

/**
 * Pick a bundled locale by BCP-47 tag, matching only the primary
 * subtag (e.g. `fr-CA` → `fr`). Falls back to English when nothing
 * matches.
 *
 * Used by {@link M} at module init to seed `M.options.locale` from
 * `navigator.language`.
 */
export function pickLocale(lang: string | undefined | null): Locale {
  if (!lang) return defaultLocale;
  const primary = lang.toLowerCase().split('-')[0]!;
  return BUNDLED_LOCALES[primary] ?? defaultLocale;
}

/**
 * The `M.options` singleton, MapML.js-parity.
 *
 * `locale` is a mutable, plain (unfrozen) object so `<map-options>`
 * runtime overrides can write into it via {@link applyMapOptionsOverride}.
 * The five `locale{Lang}` bundles are frozen copies of the vendored
 * strings and never change after module load.
 *
 * Note: authors can inspect or replace `M.options.locale` directly, but
 * doing so *after* controls have installed themselves will not relabel
 * the already-mounted DOM — matches MapML.js, which reads the locale
 * once per install.
 */
export interface MOptions {
  locale: Locale;
  localeEn: Locale;
  localeFr: Locale;
  localeJa: Locale;
  localeSv: Locale;
  localeUk: Locale;
  /**
   * Default coordinate system used by the context menu's “Copy →
   * Extent” item. Mirrors MapML.js's `M.options.defaultExtCoor`
   * (`src/mapml/DefaultMapOptions.js`) — authors can mutate this at
   * runtime to change the shape of the copied `<map-meta name="extent">`.
   * Accepted values: `'pcrs'`, `'gcrs'`, `'tcrs'`, `'tilematrix'`.
   */
  defaultExtCoor: string;
  /**
   * Default coordinate system used by the context menu's “Copy →
   * Location” item. Mirrors MapML.js's `M.options.defaultLocCoor`.
   * Accepted values: `'gcrs'`, `'pcrs'`, `'tcrs'`, `'tilematrix'`,
   * `'tile'`, `'map'`.
   */
  defaultLocCoor: string;
  /**
   * Screen-reader movement announcements opt-in. Mirrors MapML.js's
   * `M.options.announceMovement` (`src/mapml/DefaultMapOptions.js`).
   *
   * When `true`, each `<mapml-viewer>` mounts a live `<output>`
   * element in its shadow root and updates it on every `moveend` with
   * the current zoom level or a bounds/zoom guard message (e.g.
   * "At minimum zoom level, zoom out disabled zoom level 0",
   * "Reached west bound, panning west disabled"). Out-of-bounds
   * pans and zooms are also bounced back to the previous history
   * entry, matching MapML.js's `AnnounceMovement` handler.
   *
   * Read once per viewer at `connectedCallback` time (matches
   * MapML.js, which enables/disables the handler per viewer on
   * construction). Authors typically enable it via a
   * `<map-options>{"announceMovement": true}</map-options>` element
   * in `<head>` before the MapML script tag.
   */
  announceMovement: boolean;
  /**
   * Feature-index accessibility overlay preference. Tri-state:
   *   - `'on'`  — force the overlay on, overriding author markup / UI.
   *   - `'off'` — force it off, overriding author markup / UI.
   *   - `undefined` — no preference (default); the viewer's
   *     `featureindex` attribute / `featureIndex` property decides.
   *
   * This is a user / UA preference (like `prefers-reduced-motion`): when
   * set to `'on'` or `'off'` it wins over the author's `featureindex`
   * attribute and the megaphone control, and that control renders
   * pressed-and-disabled to signal the preference can't be overridden
   * from map UI.
   *
   * BREAKING CHANGE vs MapML.js, whose `featureIndexOverlayOption` is a
   * boolean defaulting to `false`. For back-compat a legacy boolean in
   * `<map-options>` is migrated on read: `true` → `'on'`, `false` →
   * `undefined` (no-preference, so it doesn't suppress the new author
   * `featureindex` attribute). See {@link applyMapOptionsOverride}.
   */
  featureIndexOverlayOption?: 'on' | 'off' | undefined;
}

/** Deep-copy so `M.options.locale` is mutable independent of the frozen bundles. */
function cloneLocale(src: Locale): Locale {
  const out = {} as Locale;
  for (const k of LOCALE_KEYS) out[k] = src[k];
  return out;
}

const _initialLocale: Locale =
  typeof navigator !== 'undefined' ? pickLocale(navigator.language) : defaultLocale;

/**
 * The `M` compatibility singleton. Mirrors MapML.js's `window.M` so
 * pages that inspect or override `M.options.locale` work here too.
 * Also attached to `window` (browsers only) as a side-effect below.
 *
 * Additional members are bolted on from other modules to avoid
 * circular imports — e.g. `M.geojson2mapml` is assigned in
 * `src/index.ts`. The type below lists them as optional so
 * consumers can call them without a cast.
 */
export interface MSingleton {
  options: MOptions;
  /**
   * MapML.js-parity binding. Assigned in `src/index.ts`; call as
   * `M.geojson2mapml(json, options?)` to get back a detached
   * `<map-layer>` element to append. Mirrors
   * `M.geojson2mapml = Util.geojson2mapml` from MapML.js's
   * `src/mapml/GlobalM.js`.
   *
   * The signature is intentionally lax so this file can stay
   * independent of `src/core/geojson2mapml.ts` (avoiding the circular
   * import that would arise if the pure function imported `M` for
   * its locale default *and* this interface referenced the function's
   * exported type). See `src/index.ts` for the assignment site.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  geojson2mapml?: (json: any, options?: any, locale?: Locale) => HTMLElement;
  /**
   * MapML.js-parity binding. Assigned in `src/index.ts`; call as
   * `M.mapml2geojson(layerEl, options?)` to get a GeoJSON
   * `FeatureCollection`. Mirrors `M.mapml2geojson =
   * Util.mapml2geojson` from `../MapML.js/src/mapml/GlobalM.js`.
   *
   * Signature intentionally lax for the same reason as
   * {@link geojson2mapml}.
   */
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  mapml2geojson?: (layer: Element, options?: any) => any;
}

export const M: MSingleton = {
  options: {
    locale: cloneLocale(_initialLocale),
    localeEn,
    localeFr,
    localeJa,
    localeSv,
    localeUk,
    // MapML.js parity: `src/mapml/DefaultMapOptions.js` sets these to
    // `'pcrs'` and `'gcrs'` respectively. The context-menu Copy items
    // read the live value from `M.options` at click time so pages that
    // mutate these before opening the menu see the effect immediately.
    defaultExtCoor: 'pcrs',
    defaultLocCoor: 'gcrs',
    // MapML.js parity: `src/mapml/DefaultMapOptions.js#announceMovement`.
    // Off by default; authors opt in via `<map-options>` in `<head>`
    // (parsed by `applyMapOptionsOverride` at module load) or by
    // writing `M.options.announceMovement = true` before mounting a
    // `<mapml-viewer>`.
    announceMovement: false,
    // Tri-state feature-index overlay preference; no preference by
    // default. Legacy boolean `<map-options>` values are migrated in
    // `applyMapOptionsOverride`.
    featureIndexOverlayOption: undefined
  }
};

/**
 * MapML.js-parity runtime override: if `<head>` contains a
 * `<map-options>` element with JSON in its `innerHTML`, merge its
 * top-level fields into {@link M.options} — mirrors
 * `Object.assign(M.options, JSON.parse(mapOptions.innerHTML))` in
 * `MapML.js/src/mapml/GlobalM.js`.
 *
 * Authors typically use this to ship a bespoke `locale` bundle
 * (e.g. Ukrainian for `<mapml-viewer lang="browser-language">` when
 * `navigator.language` is `uk`), replacing the browser-picked default
 * entirely — merge semantics are per-key on `M.options.locale`, not on
 * the individual entries within, so partial overrides drop unlisted
 * strings.
 *
 * Called once from this module's top-level so pages that place
 * `<map-options>` in `<head>` before the MapML script tag get the
 * expected pre-connect behaviour.
 */
export function applyMapOptionsOverride(): void {
  if (typeof document === 'undefined') return;
  const el = document.head?.querySelector('map-options');
  if (!el) return;
  const raw = el.innerHTML.trim();
  if (!raw) return;
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    console.warn('MapML: <map-options> in <head> is not valid JSON; ignored.', err);
    return;
  }
  if (parsed === null || typeof parsed !== 'object') return;
  // Object.assign at the top level, matching MapML.js. Only `locale` is
  // consumed today, but future MapML.js-parity fields (e.g. defaultCS)
  // will land the same way.
  Object.assign(M.options, parsed as Partial<MOptions>);
  // Migrate the legacy boolean `featureIndexOverlayOption` (MapML.js) to
  // the tri-state model: `true` → 'on', `false` → undefined (no
  // preference, so it doesn't suppress an author `featureindex`
  // attribute). Anything other than 'on' / 'off' normalises to undefined.
  const fio = (M.options as { featureIndexOverlayOption?: unknown })
    .featureIndexOverlayOption;
  if (fio === true) M.options.featureIndexOverlayOption = 'on';
  else if (fio !== 'on' && fio !== 'off')
    M.options.featureIndexOverlayOption = undefined;
}

/**
 * Resolve a viewer's active `Locale` using MapML.js's `_setLocale`
 * semantics: match the element against `:lang(tag)` for every bundled
 * language, and fall back to `M.options.locale` (the browser-picked or
 * `<map-options>`-injected default) when no bundled tag matches.
 *
 * `:lang()` matching automatically respects the ancestor `lang`
 * attribute chain, so `<html lang="fr"> ... <mapml-viewer>` picks
 * French even without a `lang` on the viewer itself. `<mapml-viewer
 * lang="browser-language">` intentionally doesn't match any bundled
 * `:lang(…)`, so it falls through to `M.options.locale` — the same
 * escape hatch MapML.js uses.
 */
export function getViewerLocale(viewer: Element): Locale {
  for (const [tag, bundle] of Object.entries(BUNDLED_LOCALES)) {
    try {
      if (viewer.matches(`:lang(${tag})`)) return bundle;
    } catch {
      // JSDOM / very old browsers may throw on unknown selectors; fall through.
    }
  }
  return M.options.locale;
}

// Attach `M` to `window` for author / test / debug convenience — matches
// MapML.js where `window.M = M`. Guarded so this module is safe to
// import in Node (build tools, unit tests).
if (typeof window !== 'undefined') {
  (window as unknown as { M?: MSingleton }).M = M;
}

// Apply any pre-existing `<map-options>` runtime override. Must run
// once at module load so viewers connected on `DOMContentLoaded` see
// the overridden `M.options.locale`.
applyMapOptionsOverride();

