/**
 * Stylesheet for the {@link FeatureIndexOverlay} — the feature-index
 * accessibility overlay (a centred reticle box + an `aria-live` `<output>`
 * listing the features that overlap the reticle, numbered `1`..`7` with
 * `8`/`9` paging).
 *
 * Ported from MapML.js's `src/mapml.css` ("Feature Index" section). Sizes
 * and positions are kept 1:1 so the overlay looks identical across
 * renderers; positions are relative to the map container the overlay
 * appends its reticle box + `<output>` into.
 *
 * Injected into the viewer's shadow styles alongside the other control
 * stylesheets.
 */
export const featureIndexOverlayCss = /* css */ `
.mapml-feature-index-box {
  margin: -8% 0 0 -8%;
  width: 16%;
  left: 50%;
  top: 50%;
  position: absolute;
  z-index: 10000;
  outline: 2px solid #fff;
}

.mapml-feature-index-box:after {
  display: block;
  content: '';
  padding-top: 100%;
}

.mapml-feature-index-box > svg {
  position: absolute;
  width: 100%;
  height: 100%;
}

.mapml-feature-index {
  outline: 1px solid #000000;
  contain: content;
  border-radius: 4px;
  background-color: #fff;
  cursor: default;
  z-index: 1000;
  position: absolute;
  top: auto;
  left: 50%;
  transform: translateX(-50%);
  bottom: 30px;
  padding-top: 5px;
  height: 92px;
  width: 450px;
  font-size: 16px;
}

.mapml-feature-index-content > span {
  width: 140px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  display: inline-block;
  padding-left: 5px;
  padding-right: 5px;
}

.mapml-feature-index-content > span > kbd {
  background-color: lightgrey;
  padding-right: 4px;
  padding-left: 4px;
  border-radius: 4px;
}

/* The trailing ", " node is a screen-reader-only auditory pause. */
.mapml-feature-index-content > span > span {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* Hides the aria-live output from sighted users while keeping it in the
 * accessibility tree (screen readers still announce its contents). */
.mapml-feature-index.mapml-screen-reader-output {
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  height: 1px;
  overflow: hidden;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}
`;
