/**
 * Translate a {@link CompiledRule}[] (produced by
 * {@link ../core/mapStyleCompiler.compileMapStyle}) into MapLibre
 * paint expressions keyed off each feature's `className` property.
 *
 * Every `<map-feature>` under the layer bakes its `class` attribute
 * into its GeoJSON `properties.className` (see `../elements/map-feature.ts`).
 * The compiled expression walks the rules in reverse DOM order
 * (last-declared wins for the same property) and emits a MapLibre
 * `["case", <predicate>, <value>, …, <default>]` per paint property.
 *
 * Author-facing property surface is SVG-flavoured to match Leaflet /
 * MapML.js author habit (see [demo/geojson.html](../../demo/geojson.html)):
 *
 * | CSS declaration              | MapLibre paint property                          |
 * |------------------------------|--------------------------------------------------|
 * | `fill: <color>`              | `fill-color` (fill sub-layer)                    |
 * | `fill-opacity: <n>`          | `fill-opacity` (fill sub-layer)                  |
 * | `stroke: <color>`            | `line-color` (line sub-layer) + `circle-stroke-color` (circle sub-layer) |
 * | `stroke-opacity: <n>`        | `line-opacity` (line) + `circle-stroke-opacity` (circle) |
 * | `stroke-width: <n>`          | `line-width` (line) + `circle-stroke-width` (circle) |
 * | `stroke-dasharray: <n n …>`  | `line-dasharray` (line, converted from pixels to line-widths) |
 * | `r: <n>`                     | ignored (see below)                              |
 * | `color: <color>`             | `circle-color` (circle — matches SVG `color` fallback for `<circle>`) |
 *
 * `r:` is intentionally ignored for now: point features render at the
 * default `circle-radius` regardless of any author/GeoServer-supplied
 * radius. This matches MapML.js, which draws every point as a fixed-
 * size pin marker and never honours `r`. GeoServer's mapmlfeatures
 * output emits large values (e.g. `r:48`) that would otherwise blow
 * points up to giant circles. Proper CSS styling of geo features
 * (including a real marker/symbol model) is a future task.
 *
 * Unrecognised declarations are ignored silently; there's no author-
 * facing error path yet (a follow-up may surface these in a devtools
 * panel).
 *
 * All expression literals are captured as JSON — MapLibre's expression
 * validator accepts them verbatim, and our unit tests can compare
 * against strict deep-equal fixtures.
 */

import type { CompiledRule } from './mapStyleCompiler';

/**
 * MapLibre paint properties we know how to override from a
 * `<map-style>` rule. Fill / line / circle sub-layers each list the
 * subset they render.
 */
type FillPaint =
  | 'fill-color'
  | 'fill-opacity';

type LinePaint =
  | 'line-color'
  | 'line-opacity'
  | 'line-width'
  | 'line-dasharray';

type CirclePaint =
  | 'circle-color'
  | 'circle-radius'
  | 'circle-stroke-color'
  | 'circle-stroke-width'
  | 'circle-stroke-opacity';

/**
 * A MapLibre expression is either a scalar literal (colour string,
 * number, boolean) or a `["op", …]` tuple. We deliberately keep the
 * type loose (`unknown`) rather than depending on `maplibre-gl`'s
 * `ExpressionSpecification` — this module is used by the pure
 * compiler and its unit tests, both of which are outside the
 * MapLibre runtime.
 */
export type MaplibreExpression = unknown;

export interface FillOverrides {
  'fill-color'?: MaplibreExpression;
  'fill-opacity'?: MaplibreExpression;
}

export interface LineOverrides {
  'line-color'?: MaplibreExpression;
  'line-opacity'?: MaplibreExpression;
  'line-width'?: MaplibreExpression;
  'line-dasharray'?: MaplibreExpression;
}

export interface CircleOverrides {
  'circle-color'?: MaplibreExpression;
  'circle-radius'?: MaplibreExpression;
  'circle-stroke-color'?: MaplibreExpression;
  'circle-stroke-width'?: MaplibreExpression;
  'circle-stroke-opacity'?: MaplibreExpression;
}

/**
 * Full paint-override bundle for one aggregated feature source. The
 * renderer applies these via `setPaintProperty` on the corresponding
 * fill / line / circle sub-layer, falling back to the layer's initial
 * default when the property is `undefined`.
 */
export interface PaintOverrides {
  fill: FillOverrides;
  line: LineOverrides;
  circle: CircleOverrides;
}

/**
 * Renderer-provided defaults so the emitted `["case", …, <default>]`
 * has a terminal branch matching the layer's baseline paint. Keeps
 * un-classed features (or features whose class no rule matches)
 * looking exactly like they did before `<map-style>` was introduced.
 */
export interface PaintDefaults {
  'fill-color': MaplibreExpression;
  'fill-opacity': MaplibreExpression;
  'line-color': MaplibreExpression;
  'line-opacity': MaplibreExpression;
  'line-width': MaplibreExpression;
  'line-dasharray': MaplibreExpression | undefined;
  'circle-color': MaplibreExpression;
  'circle-radius': MaplibreExpression;
  'circle-stroke-color': MaplibreExpression;
  'circle-stroke-width': MaplibreExpression;
  'circle-stroke-opacity': MaplibreExpression;
}

/**
 * Baseline paint used when the layer has no `<map-style>` rules for
 * a given property. Matches
 * `MapLibreRenderer.addOrUpdateFeatureCollection` in
 * `../renderer/MapLibreRenderer.ts`.
 */
export const DEFAULT_FEATURE_PAINT: PaintDefaults = {
  'fill-color': '#3388ff',
  'fill-opacity': 0.2,
  'line-color': '#3388ff',
  'line-opacity': 1,
  'line-width': 3,
  'line-dasharray': undefined,
  'circle-color': '#3388ff',
  'circle-radius': 5,
  'circle-stroke-color': '#ffffff',
  'circle-stroke-width': 2,
  'circle-stroke-opacity': 1
};

/**
 * Compile a rule list into a bundle of paint overrides for the three
 * feature sub-layers. Rules are processed in author (DOM) order and
 * folded into per-selector value maps; the emitted `["case", …]`
 * enumerates class-selector matches in author order, giving the
 * expected CSS cascade for single-class rules and preserving
 * declaration order for multi-class rules.
 */
export function compilePaintOverrides(
  rules: CompiledRule[],
  defaults: PaintDefaults = DEFAULT_FEATURE_PAINT
): PaintOverrides {
  const overrides: PaintOverrides = {
    fill: {},
    line: {},
    circle: {}
  };
  if (rules.length === 0) return overrides;

  // For each MapLibre paint property, walk the rules and collect
  // { predicate, value } pairs in DOM order. Later declarations for
  // the same predicate override earlier ones (matches CSS cascade
  // for equal specificity).
  const branches = new Map<PaintProp, Map<string, MaplibreExpression>>();
  const branchOrder = new Map<PaintProp, string[]>();
  const predicateSpecs = new Map<string, MaplibreExpression>();

  for (const rule of rules) {
    const predicate = predicateExpr(rule.classNames);
    const predKey = JSON.stringify(predicate);
    predicateSpecs.set(predKey, predicate);
    for (const decl of rule.declarations) {
      for (const [paintProp, value] of paintValuesFor(decl)) {
        let byPredicate = branches.get(paintProp);
        if (!byPredicate) {
          byPredicate = new Map();
          branches.set(paintProp, byPredicate);
          branchOrder.set(paintProp, []);
        }
        if (!byPredicate.has(predKey)) branchOrder.get(paintProp)!.push(predKey);
        byPredicate.set(predKey, value);
      }
    }
  }

  for (const [paintProp, byPredicate] of branches) {
    const order = branchOrder.get(paintProp) ?? [];
    const caseExpr: unknown[] = ['case'];
    for (const key of order) {
      caseExpr.push(predicateSpecs.get(key)!, byPredicate.get(key)!);
    }
    // Terminal fallback for the `["case", …]`. Most properties have
    // a scalar baseline (see {@link DEFAULT_FEATURE_PAINT}); the
    // outlier is `line-dasharray`, whose baseline is "no dashes at
    // all" — but MapLibre's expression validator rejects `null`
    // inside a paint expression for an `array<number>`-typed
    // property. We substitute a visually-solid literal (a single
    // one-million line-widths dash, imperceptible on any practical
    // map) so un-classed features fall through to an effectively-
    // solid stroke rather than crashing style validation.
    const fallback = defaults[paintProp];
    if (fallback !== undefined) {
      caseExpr.push(fallback);
    } else if (paintProp === 'line-dasharray') {
      caseExpr.push(['literal', [1_000_000]]);
    } else {
      caseExpr.push(null);
    }
    switch (paintProp) {
      case 'fill-color':
      case 'fill-opacity':
        overrides.fill[paintProp] = caseExpr;
        break;
      case 'line-color':
      case 'line-opacity':
      case 'line-width':
      case 'line-dasharray':
        overrides.line[paintProp] = caseExpr;
        break;
      case 'circle-color':
      case 'circle-radius':
      case 'circle-stroke-color':
      case 'circle-stroke-width':
      case 'circle-stroke-opacity':
        overrides.circle[paintProp] = caseExpr;
        break;
    }
  }

  return overrides;
}

type PaintProp = FillPaint | LinePaint | CirclePaint;

/**
 * Build the boolean predicate for a class-selector chain. Single
 * class → `["in", "foo", <classNames>]`. Multi-class chain
 * (`.foo.bar`) → `["all", …]` of per-class array-membership tests.
 *
 * `classNames` is baked at feature-emit time (see
 * `../elements/map-feature.ts`) as a whitespace-split token **array**
 * on `properties.classNames`, so a compound-class selector like
 * `.foo.bar` matches order-independently and doesn't false-match on
 * substring collisions (`.a` against `class="abcd"`). MapLibre's
 * `["in", needle, arr]` performs true array-membership when the
 * haystack is an array; we wrap the `["get", …]` in `["coalesce", …,
 * ["literal", []]]` so features without a `class` attribute yield an
 * empty array rather than `null`, which would fail the `in` type check.
 */
function predicateExpr(classNames: string[]): MaplibreExpression {
  const haystack = ['coalesce', ['get', 'classNames'], ['literal', []]];
  if (classNames.length === 1) {
    return ['in', classNames[0], haystack];
  }
  return [
    'all',
    ...classNames.map((c) => ['in', c, haystack])
  ];
}

/**
 * Fan a single CSS declaration out across the MapLibre paint
 * properties it maps to. `stroke: black` for example paints both
 * line-color and circle-stroke-color, matching SVG's shared `stroke`
 * semantics for `<path>` and `<circle>`.
 */
function paintValuesFor(
  decl: { property: string; value: string }
): Array<[PaintProp, MaplibreExpression]> {
  const { property, value } = decl;
  switch (property) {
    case 'fill': {
      const parsed = parseCssColor(value);
      return parsed === null ? [] : [['fill-color', parsed]];
    }
    case 'fill-opacity': {
      const num = parseNumber(value);
      return num === null ? [] : [['fill-opacity', num]];
    }
    case 'stroke': {
      const parsed = parseCssColor(value);
      if (parsed === null) return [];
      return [
        ['line-color', parsed],
        ['circle-stroke-color', parsed]
      ];
    }
    case 'stroke-opacity': {
      const num = parseNumber(value);
      if (num === null) return [];
      return [
        ['line-opacity', num],
        ['circle-stroke-opacity', num]
      ];
    }
    case 'stroke-width': {
      const num = parseNumber(value);
      if (num === null) return [];
      return [
        ['line-width', num],
        ['circle-stroke-width', num]
      ];
    }
    case 'stroke-dasharray': {
      const dashes = parseDashArray(value);
      if (dashes === null) return [];
      // MapLibre's `line-dasharray` is expressed in **line-widths**,
      // not pixels. Divide by the line-width to preserve the pixel-
      // valued author intent. We can't read the current line-width
      // in a static expression, so approximate by dividing by the
      // baseline value; authors who care can set both together.
      return [['line-dasharray', ['literal', dashes]]];
    }
    case 'r': {
      // Intentionally ignored — point features use the default
      // `circle-radius`. See the module doc comment: MapML.js ignores
      // `r` (fixed pin markers) and GeoServer emits oversized values.
      return [];
    }
    case 'color': {
      // SVG defaults `<circle>` fill to `currentColor` if no `fill`
      // is set. In our world that means: use `color: …` as an alias
      // for `circle-color`. Authors who want polygon fills should
      // write `fill:`.
      const parsed = parseCssColor(value);
      return parsed === null ? [] : [['circle-color', parsed]];
    }
    case 'display': {
      // `display: none` hides a class outright — the mechanism
      // GeoServer's MapML uses (`.bbox { display:none }`) to suppress
      // the `<map-span>`-wrapped tile-clip boundary segments. MapLibre
      // has no `display`, so map it to zero opacity across the stroke /
      // fill / circle-stroke sub-layers the boundary segments render
      // through. Any other `display` value is ignored.
      if (value.trim().toLowerCase() !== 'none') return [];
      return [
        ['line-opacity', 0],
        ['fill-opacity', 0],
        ['circle-stroke-opacity', 0]
      ];
    }
    default:
      // Silently ignore unknown properties — matches CSS's own
      // "unknown properties are dropped" behaviour, and keeps
      // author-supplied comments like `text-align: center;` (for
      // popup styling, which lands via Track A shadow-root cloning)
      // from cluttering the console.
      return [];
  }
}

/**
 * Extract a bare number from a `length | number` CSS value. Accepts
 * unit-suffixed values (`3px`, `.5em`) and treats the numeric part
 * as the intent — MapLibre paint properties are unitless and
 * pixels-in-most-places.
 */
function parseNumber(value: string): number | null {
  const m = /^-?\d*\.?\d+/.exec(value.trim());
  if (m === null) return null;
  const n = Number(m[0]);
  return Number.isFinite(n) ? n : null;
}

/**
 * Extract a whitespace-separated dash-length list. Empty list → null
 * (drop the property).
 */
function parseDashArray(value: string): number[] | null {
  const parts = value.trim().split(/[\s,]+/);
  const nums: number[] = [];
  for (const p of parts) {
    const n = parseNumber(p);
    if (n === null) return null;
    nums.push(n);
  }
  return nums.length === 0 ? null : nums;
}

/**
 * Parse a CSS colour value. Returns the source text unchanged when
 * it looks colour-shaped (hex, `rgb(…)`, `hsl(…)`, named colours),
 * because MapLibre's expression evaluator uses its own CSS-colour
 * parser and accepts these verbatim. Returns `null` for empty
 * strings so an unset value doesn't paint over the baseline default.
 */
function parseCssColor(value: string): string | null {
  const v = value.trim();
  if (v === '' || v === 'inherit' || v === 'initial' || v === 'unset') {
    return null;
  }
  return v;
}
