import * as maplibregl from 'maplibre-gl';

import type { Locale } from '../i18n/locale';

/**
 * MapML-flavoured geolocate control.
 *
 * Extends MapLibre's `GeolocateControl` for MapML.js parity with
 * `src/mapml/control/GeolocationButton.js`, which localises three
 * distinct surfaces:
 *
 *   1. The **button title** — cycles between:
 *        - `btnLocTrackOff`       — inactive
 *        - `btnLocTrackOn`        — ACTIVE_LOCK (following the user)
 *        - `btnLocTrackLastKnown` — BACKGROUND (tracking, panned away)
 *   2. The **user-location dot** `title` + `aria-label` — flips between
 *        - `btnMyLocTrackOn`         — ACTIVE_LOCK
 *        - `btnMyLastKnownLocTrackOn` — BACKGROUND
 *   3. A **permanent visible tooltip** anchored to the dot in the
 *      ACTIVE_LOCK state. MapML.js gets this for free from Leaflet's
 *      `bindTooltip(text, { permanent: true })`. MapLibre doesn't have
 *      a marker-tooltip primitive, so we mount a `maplibregl.Popup`
 *      (no close button, no close-on-move/click, no focus steal)
 *      pinned to the most-recent geolocation fix and update its
 *      lng/lat as fixes arrive.
 *
 * MapLibre-stock behaviour we don't need to override:
 *   - Initial "off" title is already set by MapLibre from our per-map
 *     `locale` MapOption (`GeolocateControl.FindMyLocation` →
 *     `btnLocTrackOff`).
 *   - Class transitions on the button (`.maplibregl-ctrl-geolocate-{
 *     active,background,waiting}`) are done by MapLibre; we observe
 *     them via a `MutationObserver` and rewrite everything else.
 */
export class MapmlGeolocateControl extends maplibregl.GeolocateControl {
  readonly #locale: Locale;
  #map: maplibregl.Map | undefined;
  #container: HTMLElement | undefined;
  #observer: MutationObserver | undefined;
  #popup: maplibregl.Popup | undefined;
  /** Last geolocation fix, cached so we can re-attach the popup on state changes. */
  #lastFix: [number, number] | undefined;

  constructor(options: maplibregl.GeolocateControlOptions, locale: Locale) {
    super(options);
    this.#locale = locale;
  }

  override onAdd(map: maplibregl.Map): HTMLElement {
    this.#map = map;
    const container = super.onAdd(map);
    this.#container = container;

    // MapLibre's _finishSetupUI runs asynchronously (permission
    // probe); the button may not exist synchronously. Poll a few
    // frames until it appears, then attach the button-title observer.
    const attach = (): void => {
      const btn = container.querySelector<HTMLButtonElement>(
        'button.maplibregl-ctrl-geolocate'
      );
      if (!btn) {
        window.requestAnimationFrame(attach);
        return;
      }
      this.#updateAll(btn);
      this.#observer = new MutationObserver(() => this.#updateAll(btn));
      this.#observer.observe(btn, { attributes: true, attributeFilter: ['class'] });
    };
    attach();

    // Cache each geolocation fix so we can (re)position the popup as
    // the user moves. MapLibre re-fires `geolocate` on every watch
    // update, so this stays current without extra bookkeeping.
    this.on('geolocate', this.#onGeolocate);
    // When the user manually stops tracking, MapLibre removes the
    // dot but we still need to tear down our popup.
    this.on('trackuserlocationend', this.#onTrackEnd);
    return container;
  }

  override onRemove(): void {
    this.off('geolocate', this.#onGeolocate);
    this.off('trackuserlocationend', this.#onTrackEnd);
    this.#observer?.disconnect();
    this.#observer = undefined;
    this.#removePopup();
    // MapLibre's current `IControl.onRemove` signature is `(): void`
    // (the map ref is retrieved via `this._map` internally). Call
    // super with no arg to stay compatible with the base contract.
    super.onRemove();
    this.#map = undefined;
    this.#container = undefined;
    this.#lastFix = undefined;
  }

  #onGeolocate = (e: unknown): void => {
    // MapLibre types the payload as GeolocationPosition-like; be
    // permissive to avoid a wider ambient-types dependency.
    const coords = (e as { coords?: { longitude?: number; latitude?: number } })?.coords;
    if (!coords || typeof coords.longitude !== 'number' || typeof coords.latitude !== 'number') {
      return;
    }
    this.#lastFix = [coords.longitude, coords.latitude];
    const btn = this.#container?.querySelector<HTMLButtonElement>(
      'button.maplibregl-ctrl-geolocate'
    );
    if (btn) this.#updateAll(btn);
  };

  #onTrackEnd = (): void => {
    this.#removePopup();
    // The dot is torn down by MapLibre; nothing left to label.
  };

  /**
   * Rewrite (1) the button title, (2) the dot's `title` + `aria-label`
   * and (3) the permanent popup, all in one pass so no partial state
   * is observable to tests or ATs.
   */
  #updateAll(btn: HTMLButtonElement): void {
    const cs = btn.classList;
    const active = cs.contains('maplibregl-ctrl-geolocate-active');
    const background = cs.contains('maplibregl-ctrl-geolocate-background');

    // (1) Button title — matches MapML.js's 3-state contract.
    let buttonTitle: string;
    if (background) buttonTitle = this.#locale.btnLocTrackLastKnown;
    else if (active) buttonTitle = this.#locale.btnLocTrackOn;
    else buttonTitle = this.#locale.btnLocTrackOff;
    btn.title = buttonTitle;
    btn.setAttribute('aria-label', buttonTitle);

    // (2) + (3) Dot + popup. Dot only exists once MapLibre has
    // received a fix, so skip if the fix hasn't arrived yet.
    const dot = this.#findDot();
    if (background) {
      if (dot) {
        // Hover-only label: matches MapML.js's non-permanent tooltip
        // for the last-known state (`bindTooltip(text)`).
        dot.title = this.#locale.btnMyLastKnownLocTrackOn;
        dot.setAttribute('aria-label', this.#locale.btnMyLastKnownLocTrackOn);
        this.#markDotFocusable(dot);
      }
      this.#removePopup();
    } else if (active) {
      if (dot) {
        dot.title = this.#locale.btnMyLocTrackOn;
        dot.setAttribute('aria-label', this.#locale.btnMyLocTrackOn);
        this.#markDotFocusable(dot);
      }
      // Permanent visible tooltip — MapML.js's
      // `bindTooltip(text, { permanent: true })` equivalent.
      this.#ensurePopup(this.#locale.btnMyLocTrackOn);
    } else {
      // OFF / WAITING_ACTIVE — no dot, no popup.
      this.#removePopup();
    }
  }

  /**
   * Make the user-location dot a keyboard tab stop, matching MapML.js
   * behaviour (which inherits it from Leaflet's `Marker` `keyboard: true`
   * default — `_icon` gets `tabindex="0"` + `role="button"`).
   *
   * MapLibre's `Marker` doesn't do this: `.maplibregl-user-location-dot`
   * is a plain `<div>` with no tabindex. Making it focusable puts it in
   * the natural tab sequence between the map canvas (which comes first
   * in DOM) and the control wells (which come after), so Tab out of the
   * canvas lands on the dot before reaching any control — same order
   * MapML.js authors and tests rely on.
   *
   * We use `role="img"` (not MapML.js's inherited `role="button"`)
   * because the dot is a passive indicator: activating it wouldn't do
   * anything useful today (no popup interaction), and `role="img"`
   * matches the localised `aria-label` semantics for a screen reader
   * announcing "My current location, shown on map".
   *
   * When tracking ends, MapLibre removes the dot from the DOM
   * entirely, so no explicit cleanup is needed on our side.
   */
  #markDotFocusable(dot: HTMLElement): void {
    if (dot.getAttribute('tabindex') !== '0') dot.setAttribute('tabindex', '0');
    if (dot.getAttribute('role') !== 'img') dot.setAttribute('role', 'img');
  }

  /**
   * Look up the MapLibre-owned user-location dot inside the map
   * container. The dot only exists once a location fix has arrived,
   * so this may return null even while the control is active.
   */
  #findDot(): HTMLElement | null {
    return (
      this.#map?.getContainer().querySelector<HTMLElement>('.maplibregl-user-location-dot') ??
      null
    );
  }

  /**
   * Attach a permanent MapLibre `Popup` to the current geolocation
   * fix, or reposition it if already mounted. No-op if we haven't
   * received a fix yet. Options:
   *   - `closeButton: false`      — visible label, no dismiss X.
   *   - `closeOnClick/Move: false` — persists across pan / zoom / tap.
   *   - `focusAfterOpen: false`   — don't yank focus into the popup on
   *                                  open (matches Leaflet tooltip semantics).
   *   - `className: 'mapml-user-location-popup'` — hook for future CSS.
   *   - `anchor: 'bottom'` + `offset: 15` — sits above the dot.
   */
  #ensurePopup(text: string): void {
    if (!this.#map || !this.#lastFix) return;
    if (!this.#popup) {
      this.#popup = new maplibregl.Popup({
        closeButton: false,
        closeOnClick: false,
        closeOnMove: false,
        focusAfterOpen: false,
        anchor: 'bottom',
        offset: 15,
        className: 'mapml-user-location-popup'
      });
    }
    this.#popup.setText(text);
    this.#popup.setLngLat(this.#lastFix);
    if (!this.#popup.isOpen()) {
      this.#popup.addTo(this.#map);
    }
  }

  #removePopup(): void {
    this.#popup?.remove();
    this.#popup = undefined;
  }
}
