/**
 * Compile the text content of a `<map-style>` (or the response body of
 * a `<map-link rel="stylesheet">`) into a normalised rule set suitable
 * for {@link ./paintExpressions.compilePaintOverrides} to translate
 * into MapLibre paint expressions.
 *
 * v1 supports **class selectors only** (`.foo`, `.foo.bar`) — matches
 * every published MapML sample and every `<map-style>` in the demo
 * folder. Non-class selectors (type, attribute, pseudo-class,
 * descendant / combinator, `*`) are skipped with a warning. `@media`,
 * `@supports`, and other at-rules are skipped in v1; media-query
 * gating lives on the `<map-style media="…">` attribute instead
 * (evaluated via `viewer.matchMedia` — see
 * [../elements/map-style.ts](../elements/map-style.ts)'s
 * `#registerMediaQuery`).
 *
 * Declaration values are stored as source text (via `css-tree`'s
 * `generate()`), which lets MapLibre's own colour + number parsers
 * consume them unchanged (see `../renderer/paintExpressions.ts`).
 *
 * Author-facing property surface is SVG-flavoured (`fill`, `stroke`,
 * `stroke-width`, `fill-opacity`, `stroke-opacity`, `stroke-dasharray`,
 * `r`, …) to match Leaflet / MapML.js author habit. The property→
 * MapLibre-paint mapping lives in `paintExpressions.ts`; this module
 * is deliberately unopinionated about which properties "count".
 */

// css-tree ships subpath entries — pulling from the root is easiest
// for TypeScript declaration resolution and Rolldown still tree-shakes
// the parser + generator paths cleanly. Bundle-size impact measured
// against the previous `dist/mapml-maplibre.js` will land in the PR
// description.
import { parse, generate, type CssNode } from 'css-tree';

/** One `property: value;` pair from a CSS declaration block. */
export interface CompiledDeclaration {
  /** Source-cased CSS property name (`fill`, `stroke-width`, `r`). */
  property: string;
  /**
   * Declaration value as source text (round-tripped through
   * `css-tree`'s `generate()`). Preserves author formatting where it
   * matters (e.g. `rgb(255 0 0 / .5)`), which MapLibre's colour
   * parser accepts verbatim.
   */
  value: string;
}

/** One compiled CSS rule. */
export interface CompiledRule {
  /**
   * Class-selector token set: `[".foo"]` for `.foo`, `[".foo", ".bar"]`
   * for `.foo.bar` (all-of, i.e. the feature must carry every listed
   * class). Multiple selectors on one rule (`.a, .b`) each become
   * their own {@link CompiledRule}.
   */
  classNames: string[];
  declarations: CompiledDeclaration[];
}

/** Result of compiling one `<map-style>` block. */
export interface CompiledStyle {
  rules: CompiledRule[];
  /**
   * Human-readable notes about selectors / at-rules that were
   * skipped. Callers may surface these via `console.warn` (the
   * `<map-style>` element does exactly that on first compile).
   */
  warnings: string[];
}

/**
 * Parse CSS text into a normalised {@link CompiledStyle}. Never
 * throws — malformed input falls through to an empty ruleset with a
 * warning, matching CSS's own error-recovery semantics.
 */
export function compileMapStyle(cssText: string): CompiledStyle {
  const rules: CompiledRule[] = [];
  const warnings: string[] = [];

  if (cssText === '' || cssText === null || cssText === undefined) {
    return { rules, warnings };
  }

  let ast: CssNode;
  try {
    ast = parse(cssText, { context: 'stylesheet', positions: false });
  } catch (err) {
    warnings.push(
      `<map-style>: CSS parse error — ${(err as Error).message ?? String(err)}`
    );
    return { rules, warnings };
  }

  // Iterate the stylesheet's top-level children directly rather than
  // via `walk()`. Two reasons: (1) `walk()`'s visitor return-value
  // "skip subtree" marker isn't typed in `@types/css-tree`, forcing
  // ugly casts; (2) shallow iteration means nested at-rule bodies
  // (`@media (map-zoom: 14) { .a { … } }`) don't leak their rules
  // into our output — matches CSS semantics where a rule inside an
  // unmatched `@media` block doesn't apply.
  if (ast.type !== 'StyleSheet') return { rules, warnings };
  for (const node of ast.children) {
    if (node.type === 'Atrule') {
      // v1: no `@media` / `@supports` / `@keyframes` / `@font-face`
      // inside `<map-style>`. Media-query gating lives on the
      // element's `media` attribute (see
      // `../elements/map-style.ts` `#registerMediaQuery`).
      warnings.push(
        `<map-style>: @${node.name} is not supported (use the media attribute for zoom-scoped styling)`
      );
      continue;
    }
    if (node.type !== 'Rule') continue;
    // Each comma-separated selector (`.a, .b`) becomes its own
    // CompiledRule. css-tree exposes the prelude as a SelectorList
    // whose children are Selectors.
    if (node.prelude.type !== 'SelectorList') continue;
    const declarations = collectDeclarations(node);
    if (declarations.length === 0) continue;
    for (const selector of node.prelude.children) {
      if (selector.type !== 'Selector') continue;
      const classNames = collectClassSelector(selector, warnings);
      if (classNames === null) continue;
      rules.push({ classNames, declarations });
    }
  }

  return { rules, warnings };
}

/**
 * A "supported" selector is a chain of one-or-more class selectors
 * only. Everything else (type, universal, attribute, pseudo, combinator)
 * causes the selector to be dropped with a warning. Returns the
 * collected class-name tokens, or `null` if the selector was rejected.
 */
function collectClassSelector(
  selector: CssNode,
  warnings: string[]
): string[] | null {
  if (selector.type !== 'Selector') return null;
  const classNames: string[] = [];
  for (const child of selector.children) {
    if (child.type === 'ClassSelector') {
      classNames.push(child.name);
      continue;
    }
    // Anything else — TypeSelector, AttributeSelector, PseudoClass,
    // Combinator, WhiteSpace, etc. — is unsupported.
    warnings.push(
      `<map-style>: skipped selector "${generate(selector)}" — only class selectors are supported in v1`
    );
    return null;
  }
  if (classNames.length === 0) {
    warnings.push(
      `<map-style>: skipped empty selector "${generate(selector)}"`
    );
    return null;
  }
  return classNames;
}

/** Walk a rule's `{ … }` block and pull out its declarations in order. */
function collectDeclarations(rule: CssNode): CompiledDeclaration[] {
  if (rule.type !== 'Rule') return [];
  if (rule.block.type !== 'Block') return [];
  const decls: CompiledDeclaration[] = [];
  for (const item of rule.block.children) {
    if (item.type !== 'Declaration') continue;
    decls.push({
      property: item.property.toLowerCase(),
      value: generate(item.value).trim()
    });
  }
  return decls;
}
