/**
 * Attribution-control stylesheet for the MapML-MapLibre
 * {@link MapmlAttributionControl}.
 *
 * Ported subset of `MapML.js/src/mapml.css` covering the keyboard-shortcuts
 * dialog that `AttributionButton` injects into the map container. The
 * selectors are kept identical to MapML.js so authors familiar with it can
 * target the same classes:
 *
 *   .shortcuts-dialog          — the modal `<dialog>` element
 *   .shortcuts-button          — the opener button in the attribution popover
 *
 * The `.shortcuts-button` also carries `.mapml-button` (defined in
 * layerControl.css.ts) for the generic seamless-button reset.
 *
 * `.mapml-maplibre-logo` sizes the official MapLibre wordmark
 * ({@link MAPLIBRE_LOGO_ICON}) so it renders inline in the
 * `|`-separated attribution row.
 */
export const attributionControlCss = /* css */ `
.shortcuts-dialog {
  position: relative;
}

.shortcuts-dialog > ul > li > kbd {
  background-color: lightgrey;
  padding-right: 4px;
  padding-left: 4px;
  border-radius: 4px;
}

.shortcuts-dialog > button {
  font-size: inherit;
}

.shortcuts-dialog > button.shortcuts-close {
  position: absolute;
  top: 8px;
  right: 8px;
}

.shortcuts-dialog > ul {
  padding: 0;
  list-style-type: none;
}

img.mapml-maplibre-logo {
  height: 16px;
  width: auto;
  vertical-align: middle;
}
`;
