/**
 * Stylesheet for the {@link DebugOverlay} coordinate panel.
 *
 * Ported from MapML.js's `mapml.css` debug-mode rules (`.mapml-debug*`).
 * The panel is a `<table>` mounted inside the MapLibre map container,
 * *before* the `.maplibregl-control-container` so it stacks below the
 * Coordinates are rendered as `<tr>` rows updated on `mousemove`. The
 * tile grid is a container of positioned `.mapml-debug-tile` divs
 * (one per visible OSMTILE tile), and the layer bounding boxes are
 * GeoJSON line / fill / circle layers that need no CSS.
 */
export const debugOverlayCss = /* css */ `
.mapml-debug {
  contain: content;
  max-height: 100%;
  max-width: 100%;
  border-radius: 4px;
  padding: 5px 10px;
  background-color: #fff;
  cursor: default;
  /* Sit above MapLibre's control wells (z-index:2) so the coordinate
     panel is not overwritten by the scale bar / attribution, matching
     MapML.js. The full-map tile grid stays low (z-index:0) so it never
     obscures popups. */
  z-index: 3;
  position: absolute;
  display: block;
  top: auto;
  right: 5px;
  bottom: 5px;
  left: 5px;
  width: fit-content;
  font: inherit;
  pointer-events: none;
}

.mapml-debug-banner {
  font-weight: bold;
  text-transform: uppercase;
  display: inline-block;
  text-align: left;
  line-height: 2;
}

.mapml-debug-panel {
  font-family: monospace;
}

.mapml-debug-coordinates {
  padding-left: 4px;
  padding-right: 4px;
}

.mapml-debug,
.mapml-debug * {
  border-collapse: collapse;
  border-spacing: 0;
}

.mapml-debug-coordinates:empty {
  display: none;
}

.mapml-debug-coordinates > * {
  display: inline;
}

.mapml-debug-grid {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  /* See .mapml-debug: stay below the later-appended feature popup. */
  z-index: 0;
  font-family: monospace;
  color: #f00;
}

.mapml-debug-tile {
  position: absolute;
  box-sizing: border-box;
  outline: 1px dashed red;
  text-indent: 6px;
  line-height: 1.8;
  white-space: nowrap;
}
`;
