import type { Map as MapLibreMap } from 'maplibre-gl';

import type { Locale } from '../i18n/locale';

/**
 * One feature that can appear in the {@link FeatureIndexOverlay}. Supplied
 * by the {@link FeatureIndexHost} (typically derived from the renderer's
 * in-viewport `<map-feature>` set), with a GCRS bounding box (degrees) so
 * the overlay can test it against the reticle, and an {@link activate}
 * callback the overlay invokes when the user presses the feature's number
 * key.
 *
 * `activate` implements the "popup if present, else focus" contract: the
 * host opens the feature's `<map-properties>` popup when it has one,
 * otherwise sends keyboard focus to the feature. Keeping that decision on
 * the host side avoids coupling the overlay to the popup / focus-proxy
 * pipelines.
 */
export interface FeatureIndexEntry {
  /** Accessible name (from `<map-featurecaption>`), used as the list label. */
  label: string;
  /** GCRS bounding box, in degrees. */
  bboxWest: number;
  bboxSouth: number;
  bboxEast: number;
  bboxNorth: number;
  /** Open the feature's popup, or focus it when it has none. */
  activate(): void;
}

/**
 * Data source seam for the overlay. Returns the features currently
 * eligible for indexing (in viewport, within their zoom range), in the
 * order they should be numbered. Implemented by the renderer's
 * {@link import('./FeatureFocusIndex').FeatureFocusIndex}, exposed to the
 * viewer via {@link import('./MapLibreRenderer').MapLibreRenderer.featureIndexHost}.
 */
export interface FeatureIndexHost {
  getInboundEntries(): readonly FeatureIndexEntry[];
  /**
   * Subscribe to changes in the inbound-entry set — fired after the host
   * recomputes it (view change or feature add / remove). Returns an
   * unsubscribe function. The overlay uses this instead of `moveend` so it
   * reads a fresh set: the host refreshes asynchronously, so a synchronous
   * `moveend` read would be one event stale, and feature loads don't fire
   * `moveend` at all.
   */
  onEntriesChanged(listener: () => void): () => void;
}

/**
 * Options bag for {@link FeatureIndexOverlay.enable}. Intentionally empty
 * for now — reticle size, page size, etc. will land here once concrete
 * options exist. See TODO.md.
 */
export type FeatureIndexOverlayOptions = Record<string, never>;

/** Square reticle outline, mirrors MapML.js's `FeatureIndexOverlay` SVG. */
const RETICLE_SVG =
  '<svg xmlns="http://www.w3.org/2000/svg" xml:space="preserve" viewBox="0 0 100 100">' +
  '<path fill="none" stroke="#000" stroke-linecap="round" stroke-linejoin="round" ' +
  'stroke-width="3" d="M0 0h100v100H0z" color="#000" overflow="visible"/></svg>';

/** Reticle box width as a fraction of the map container (CSS `width: 16%`). */
const RETICLE_FRACTION = 0.16;

/** Features shown per page before paging kicks in. */
const PAGE_SIZE = 7;

/** One numbered / toggle row in the paged results model. */
interface PagedFeature {
  label: string;
  /** 1-based feature index, or 0 for the paging toggle rows. */
  index: number;
  /** Present only on real features (absent on Previous/More toggle rows). */
  activate?: () => void;
}

/**
 * FeatureIndexOverlay — the numbered accessibility overlay that lists the
 * features overlapping a centred reticle box, letting a keyboard / screen-
 * reader user jump to any of them by pressing its number.
 *
 * Faithful port of MapML.js's
 * {@link https://github.com/Maps4HTML/MapML.js/blob/main/src/mapml/layers/FeatureIndexOverlay.js FeatureIndexOverlay},
 * adapted from Leaflet to MapLibre + TypeScript:
 *   - The reticle bounds are computed by projecting the map centre ± half
 *     the reticle box directly to `LngLat` (GCRS), rather than going
 *     through PCRS — the overlap test then runs against each entry's GCRS
 *     bbox.
 *   - The in-viewport feature set + per-feature activation are abstracted
 *     behind {@link FeatureIndexHost} / {@link FeatureIndexEntry} instead
 *     of reaching into Leaflet's `map.featureIndex.inBoundFeatures`.
 *   - List rows are built with DOM nodes + `textContent` (not `innerHTML`)
 *     so author-supplied captions can't inject markup.
 *
 * Behaviour parity:
 *   - Keys `1`–`7` activate the corresponding feature (popup, else focus).
 *   - Key `9` pages to the next set of results ("More results"); key `8`
 *     pages back ("Previous results").
 *   - "No features found" when nothing overlaps the reticle.
 *   - The `<output role="status" aria-live="polite" aria-atomic="true">`
 *     is visually hidden (`.mapml-screen-reader-output`) until
 *     {@link enable}d, so sighted users only see the reticle.
 *
 * Wired into the viewer via its public {@link import('../elements/mapml-viewer').MapmlViewer.featureIndex}
 * property, which calls {@link enable} / {@link disable}. The inbound-
 * feature data source ({@link FeatureIndexHost}) is the renderer's
 * {@link import('./FeatureFocusIndex').FeatureFocusIndex}.
 */
export class FeatureIndexOverlay {
  #map: MapLibreMap;
  #host: FeatureIndexHost;
  #locale: Locale;

  #box: HTMLDivElement;
  #output: HTMLOutputElement;
  #body: HTMLSpanElement;

  /** Current paging model: an array of pages, each an array of rows. */
  #pages: PagedFeature[][] = [];
  /** Index into {@link #pages} of the page currently rendered in {@link #body}. */
  #pageIndex = 0;
  /** True between {@link enable} and {@link disable}. */
  #active = false;
  /**
   * True while a feature-content popup is open. The reticle box is hidden
   * in this state so the popup reads clearly over the map centre (parity
   * with MapML.js, which hides its reticle `_container` while a popup is
   * up); the results `<output>` stays live so number-key switching and
   * screen-reader readout keep working.
   */
  #popupOpen = false;

  /** Unsubscribe from the host's entry-change notifications (set while active). */
  #unsubscribeHost: (() => void) | null = null;

  constructor(map: MapLibreMap, host: FeatureIndexHost, locale: Locale) {
    this.#map = map;
    this.#host = host;
    this.#locale = locale;

    const container = map.getContainer();

    this.#box = document.createElement('div');
    this.#box.className = 'mapml-feature-index-box';
    this.#box.innerHTML = RETICLE_SVG;
    this.#box.setAttribute('hidden', '');
    container.appendChild(this.#box);

    this.#output = document.createElement('output');
    this.#output.className = 'mapml-feature-index mapml-screen-reader-output';
    this.#output.setAttribute('role', 'status');
    this.#output.setAttribute('aria-live', 'polite');
    this.#output.setAttribute('aria-atomic', 'true');
    container.appendChild(this.#output);

    this.#body = document.createElement('span');
    this.#body.className = 'mapml-feature-index-content';
    this.#output.appendChild(this.#body);
  }

  /**
   * Show the reticle + results overlay and start tracking the map. Rebuilds
   * the results immediately and whenever the host's inbound set changes
   * (view change or feature add / remove), and listens for the `1`–`9`
   * number keys on the map container (so keys still fire while a feature
   * popup holds focus — the popup lives inside the container and the event
   * bubbles up). Also tracks content-popup open/close to hide / restore the
   * reticle box.
   *
   * `options` is a future-proofing hook (reticle / page sizing, etc.) and
   * is currently unused — see {@link FeatureIndexOverlayOptions}.
   */
  enable(_options?: FeatureIndexOverlayOptions): void {
    if (this.#active) return;
    this.#active = true;
    this.#output.classList.remove('mapml-screen-reader-output');
    // Recompute when the host refreshes its inbound set — this covers
    // pan / zoom (incl. programmatic `zoomTo` / `fitBounds`) and feature
    // add / remove. The host refreshes asynchronously, so subscribing here
    // (rather than to `moveend`) guarantees we read the fresh set.
    this.#unsubscribeHost = this.#host.onEntriesChanged(this.#checkOverlap);
    const container = this.#map.getContainer();
    container.addEventListener('keydown', this.#onKeyDown);
    container.addEventListener('mapml:contentpopupopen', this.#onPopupOpen);
    container.addEventListener('mapml:contentpopupclose', this.#onPopupClose);
    this.#syncBoxVisibility();
    this.#checkOverlap();
  }

  /** Hide the overlay and stop tracking the map. */
  disable(): void {
    if (!this.#active) return;
    this.#active = false;
    this.#popupOpen = false;
    this.#output.classList.add('mapml-screen-reader-output');
    this.#unsubscribeHost?.();
    this.#unsubscribeHost = null;
    const container = this.#map.getContainer();
    container.removeEventListener('keydown', this.#onKeyDown);
    container.removeEventListener('mapml:contentpopupopen', this.#onPopupOpen);
    container.removeEventListener('mapml:contentpopupclose', this.#onPopupClose);
    this.#syncBoxVisibility();
  }

  /** Tear down: remove listeners + DOM. */
  destroy(): void {
    this.disable();
    this.#box.remove();
    this.#output.remove();
  }

  /** A feature-content popup opened: hide the reticle behind it. */
  #onPopupOpen = (): void => {
    this.#popupOpen = true;
    this.#syncBoxVisibility();
  };

  /** The feature-content popup closed: restore the reticle if still active. */
  #onPopupClose = (): void => {
    this.#popupOpen = false;
    this.#syncBoxVisibility();
  };

  /** Reticle box is visible only while active with no popup open over it. */
  #syncBoxVisibility(): void {
    if (this.#active && !this.#popupOpen) this.#box.removeAttribute('hidden');
    else this.#box.setAttribute('hidden', '');
  }

  /**
   * Reticle bounds in GCRS degrees: project the map centre to pixels,
   * expand by half the reticle box size on each axis, and unproject the
   * corners back to `LngLat`. Ports MapML.js's `_calculateReticleBounds`
   * (which does the same in PCRS via `pixelToPCRSBounds`).
   */
  #calculateReticleBounds(): {
    west: number;
    south: number;
    east: number;
    north: number;
  } {
    const map = this.#map;
    const containerWidth = map.getContainer().clientWidth;
    let reticlePx = this.#box.getBoundingClientRect().width;
    if (!(reticlePx > 0)) reticlePx = containerWidth * RETICLE_FRACTION;
    const half = reticlePx / 2;
    const centre = map.project(map.getCenter());
    // y grows downward, so the north-east corner is (x+half, y-half).
    const sw = map.unproject([centre.x - half, centre.y + half]);
    const ne = map.unproject([centre.x + half, centre.y - half]);
    return { west: sw.lng, south: sw.lat, east: ne.lng, north: ne.lat };
  }

  /**
   * Rebuild the results list from the host's in-viewport features, keeping
   * only those whose bbox overlaps the reticle. Ports `_checkOverlap`.
   */
  #checkOverlap = (): void => {
    const reticle = this.#calculateReticleBounds();
    const entries = this.#host.getInboundEntries();

    this.#body.replaceChildren();
    this.#pageIndex = 0;
    this.#pages = [];

    let index = 1;
    for (const entry of entries) {
      const overlaps =
        reticle.west <= entry.bboxEast &&
        reticle.east >= entry.bboxWest &&
        reticle.south <= entry.bboxNorth &&
        reticle.north >= entry.bboxSouth;
      if (!overlaps) continue;

      if (index <= PAGE_SIZE) {
        this.#body.appendChild(this.#updateOutput(entry.label, index, index));
      }
      if ((index - 1) % PAGE_SIZE === 0) {
        this.#pages.push([]);
      }
      this.#pages[Math.floor((index - 1) / PAGE_SIZE)]!.push({
        label: entry.label,
        index,
        activate: entry.activate.bind(entry)
      });
      // As soon as a second page starts, surface the "More results" (9) row.
      if (this.#pages[1] && this.#pages[1].length === 1) {
        this.#body.appendChild(
          this.#updateOutput(this.#locale.fIndexMoreResults, 0, 9)
        );
      }
      index += 1;
    }

    this.#addToggleKeys();

    if (index === 1) {
      const noFeatures = document.createElement('span');
      noFeatures.textContent = this.#locale.fIndexNoFeatures;
      this.#body.appendChild(noFeatures);
    }
  };

  /**
   * Build one list row: `<span data-index><kbd>key</kbd> label<span>, </span></span>`.
   * The trailing ", " is a screen-reader auditory pause (hidden via CSS).
   * Uses `textContent` throughout so captions can't inject markup. Ports
   * `_updateOutput`.
   */
  #updateOutput(label: string, index: number, key: number): HTMLSpanElement {
    const span = document.createElement('span');
    span.setAttribute('data-index', String(index));
    const kbd = document.createElement('kbd');
    kbd.textContent = String(key);
    span.appendChild(kbd);
    span.appendChild(document.createTextNode(' ' + label));
    const pause = document.createElement('span');
    pause.textContent = ', ';
    span.appendChild(pause);
    return span;
  }

  /**
   * Append the paging toggle rows ("Previous results" / "More results") to
   * each page's model so `_newContent` can render them with keys 8 / 9.
   * Ports `_addToggleKeys`.
   */
  #addToggleKeys(): void {
    const pages = this.#pages;
    for (let i = 0; i < pages.length; i++) {
      if (pages[i]!.length === 0) return;
      if (pages[i - 1]) {
        pages[i]!.push({ label: this.#locale.fIndexPreviousResults, index: 0 });
      }
      if (pages[i + 1] && pages[i + 1]!.length > 0) {
        pages[i]!.push({ label: this.#locale.fIndexMoreResults, index: 0 });
      }
    }
  }

  /**
   * Render the page `direction` steps away from the one currently shown.
   * Ports `_newContent`.
   */
  #newContent(direction: 1 | -1): void {
    const first = this.#body.firstElementChild;
    if (!first) return;
    const currentIndex = Number(first.getAttribute('data-index'));
    const targetPage =
      this.#pages[Math.floor((currentIndex - 1) / PAGE_SIZE) + direction];
    if (!targetPage || targetPage.length === 0) return;

    this.#body.replaceChildren();
    this.#pageIndex += direction;
    for (let i = 0; i < targetPage.length; i++) {
      const feature = targetPage[i]!;
      let key = i + 1;
      if (feature.label === this.#locale.fIndexMoreResults) key = 9;
      if (feature.label === this.#locale.fIndexPreviousResults) key = 8;
      this.#body.appendChild(
        this.#updateOutput(feature.label, feature.index, key)
      );
    }
  }

  /**
   * Number-key handler: `1`–`7` activate the matching feature on the
   * current page; `8` / `9` page backwards / forwards. Ports `_onKeyDown`.
   */
  #onKeyDown = (e: KeyboardEvent): void => {
    if (e.key >= '1' && e.key <= '7') {
      const page = this.#pages[this.#pageIndex];
      if (!page) return;
      const feature = page[Number(e.key) - 1];
      if (feature?.activate) feature.activate();
    } else if (e.key === '8') {
      this.#newContent(-1);
    } else if (e.key === '9') {
      this.#newContent(1);
    }
  };
}
