/**
 * Small DOM helpers shared by `<map-layer>` and `<map-extent>` when
 * they emit their layer-control fieldsets. These exist so both elements
 * produce identical markup for things like the settings-gear icon and
 * unique element ids — there's no Leaflet `stamp` available, so we use
 * a module-local monotonic counter.
 */

const SVG_NS = 'http://www.w3.org/2000/svg';

let counter = 0;
/** Monotonic id suffix; replaces Leaflet's `stamp()` for layer-control DOM. */
export function nextControlId(): number {
  return ++counter;
}

/**
 * MapML.js settings-gear SVG (three vertical dots). Produced as an
 * actual SVG node so it round-trips through the shadow root correctly.
 */
export function settingsGearSvg(): SVGSVGElement {
  const svg = document.createElementNS(SVG_NS, 'svg');
  svg.setAttribute('viewBox', '0 0 24 24');
  svg.setAttribute('height', '22');
  svg.setAttribute('width', '22');
  svg.setAttribute('fill', 'currentColor');

  const bg = document.createElementNS(SVG_NS, 'path');
  bg.setAttribute('d', 'M0 0h24v24H0z');
  bg.setAttribute('fill', 'none');
  svg.appendChild(bg);

  const fg = document.createElementNS(SVG_NS, 'path');
  fg.setAttribute(
    'd',
    'M12 8c1.1 0 2-.9 2-2s-.9-2-2-2-2 .9-2 2 .9 2 2 2zm0 2c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2zm0 6c-1.1 0-2 .9-2 2s.9 2 2 2 2-.9 2-2-.9-2-2-2z'
  );
  svg.appendChild(fg);

  return svg;
}
