import * as maplibregl from 'maplibre-gl';
import type { Map as MapLibreMap } from 'maplibre-gl';
import type { Locale } from '../i18n/locale';

/**
 * Options for {@link MapmlAttributionControl}. Extends the subset of
 * MapLibre's `AttributionControlOptions` we use with a required
 * {@link Locale} so the control can render the localized
 * keyboard-shortcuts opener button + dialog.
 */
export interface MapmlAttributionControlOptions {
  compact?: boolean;
  customAttribution?: string | string[];
  locale: Locale;
}

/**
 * MapML-flavoured attribution control.
 *
 * Extends MapLibre's `AttributionControl` and overrides `_updateAttributions`
 * to:
 *
 *   1. Prepend a keyboard-shortcuts opener button, left-most in the
 *      expanded popover. Clicking it opens a modal `<dialog>` listing the
 *      pan/zoom/feature-navigation key bindings — mirrors MapML.js's
 *      `AttributionButton` `.shortcuts-dialog`.
 *
 *   2. Put the Maps for HTML Community Group prefix (icon + link) next,
 *      i.e. immediately right of the shortcuts button — MapML.js policy.
 *      MapLibre's stock control sorts attributions by length, which
 *      pushes our long HTML prefix to the right.
 *
 *   3. Preserve source insertion order for the rest. Sources are added
 *      to the map in `<map-layer>` DOM order, so this yields layer-order
 *      attribution. MapLibre's stock control length-sorts and does
 *      substring-dedup, both of which scramble that order.
 *
 *   4. Bypass MapLibre's `DOM.sanitize`, which strips `src` attributes
 *      containing `data:` URLs and thereby breaks the inlined W3C-CG
 *      badge (the icon renders as a broken image otherwise). Inputs are
 *      trusted: the prefix is a hardcoded constant in mapml-viewer.ts;
 *      `<map-link rel="license">` title/href values are escaped in
 *      map-link.ts's `formatLicenseLink`.
 *
 * All other behaviour (compact toggle, resize/drag reactivity, `<details>`
 * open state, ARIA wiring) is inherited unchanged from the base class.
 */
export class MapmlAttributionControl extends maplibregl.AttributionControl {
  #locale: Locale;
  #dialog: HTMLDialogElement | null = null;
  /**
   * Standalone attribution strings not tied to a MapLibre source or
   * layer — set via {@link setExtraAttributions}. Used for layers
   * whose only renderable children are `<map-link rel="query">`,
   * which register no source that would otherwise carry an
   * `attribution` string.
   */
  #extraAttributions: readonly string[] = [];

  constructor(options: MapmlAttributionControlOptions) {
    const base: {
      compact?: boolean;
      customAttribution?: string | string[];
    } = {};
    if (options.compact !== undefined) base.compact = options.compact;
    if (options.customAttribution !== undefined)
      base.customAttribution = options.customAttribution;
    super(base);
    this.#locale = options.locale;
  }

  override onAdd(map: MapLibreMap): HTMLElement {
    // super.onAdd() builds `_innerContainer` and calls
    // `_updateAttributions`, which already renders the opener button.
    const container = super.onAdd(map);
    this.#installShortcutsDialog(map);
    this._innerContainer.addEventListener('click', this.#onInnerClick);
    return container;
  }

  override onRemove(): void {
    this._innerContainer?.removeEventListener('click', this.#onInnerClick);
    this.#dialog?.remove();
    this.#dialog = null;
    super.onRemove();
  }

  /**
   * Creates the modal `<dialog class="shortcuts-dialog">` once and
   * appends it to the map container (so `showModal()` renders it in the
   * top layer, centred over the map). Mirrors MapML.js's
   * `AttributionButton.onAdd`.
   */
  #installShortcutsDialog(map: MapLibreMap): void {
    const l = this.#locale;
    const dialog = document.createElement('dialog');
    dialog.className = 'shortcuts-dialog';
    dialog.setAttribute('autofocus', '');
    dialog.innerHTML =
      `<b>${l.kbdShortcuts} </b>` +
      `<button type="button" aria-label="Close" class="shortcuts-close mapml-button"><span aria-hidden="true">&#10005;</span></button>` +
      `<ul><b>${l.kbdMovement}</b>` +
      `<li><kbd>&#8593;</kbd> ${l.kbdPanUp}</li>` +
      `<li><kbd>&#8595;</kbd> ${l.kbdPanDown}</li>` +
      `<li><kbd>&#8592;</kbd> ${l.kbdPanLeft}</li>` +
      `<li><kbd>&#8594;</kbd> ${l.kbdPanRight}</li>` +
      `<li><kbd>+</kbd> ${l.btnZoomIn}</li>` +
      `<li><kbd>-</kbd> ${l.btnZoomOut}</li>` +
      `<li><kbd>shift</kbd> + <kbd>&#8592;/&#8593;/&#8594;/&#8595;</kbd> 3x ${l.kbdPanIncrement}</li>` +
      `<li><kbd>ctrl</kbd> + <kbd>&#8592;/&#8593;/&#8594;/&#8595;</kbd> 0.2x ${l.kbdPanIncrement}</li>` +
      `<li><kbd>shift</kbd> + <kbd>+/-</kbd> ${l.kbdZoom}</li></ul>` +
      `<ul><b>${l.kbdFeature}</b>` +
      `<li><kbd>&#8592;/&#8593;</kbd> ${l.kbdPrevFeature}</li>` +
      `<li><kbd>&#8594;/&#8595;</kbd> ${l.kbdNextFeature}</li></ul>`;
    dialog.addEventListener('click', (e) => {
      // Close on the X button; also swallow clicks so they don't
      // propagate to the map.
      const target = e.target as HTMLElement | null;
      if (target?.closest('.shortcuts-close')) dialog.close();
      e.stopPropagation();
    });
    // Close on Escape. The viewer's keyboard handler preventDefaults the
    // Escape keydown, which suppresses the dialog's native cancel, so
    // handle it explicitly before it reaches the map.
    dialog.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        dialog.close();
      }
    });
    map.getContainer().appendChild(dialog);
    this.#dialog = dialog;
  }

  #onInnerClick = (e: MouseEvent): void => {
    const target = e.target as HTMLElement | null;
    if (target?.closest('.shortcuts-button')) {
      e.preventDefault();
      this.#dialog?.showModal();
    }
  };

  /**
   * Replace the set of standalone attribution strings (see
   * {@link #extraAttributions}) and re-render. Called by the viewer's
   * query-click coordinator whenever a `<map-link rel="query">`
   * registers or unregisters, so a query-only layer's license shows
   * in the attribution control alongside source-backed layers.
   */
  setExtraAttributions(attributions: readonly string[]): void {
    this.#extraAttributions = attributions.slice();
    this._updateAttributions();
  }

  override _updateAttributions(): void {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const style = (this._map as any)?.style;
    if (!style) return;

    const parts: string[] = [];
    const seen = new Set<string>();

    // 1) Custom prefix always FIRST.
    const custom = this.options.customAttribution;
    if (typeof custom === 'string') {
      const trimmed = custom.trim();
      if (trimmed && !seen.has(trimmed)) {
        parts.push(custom);
        seen.add(trimmed);
      }
    } else if (Array.isArray(custom)) {
      for (const c of custom) {
        if (typeof c !== 'string') continue;
        const trimmed = c.trim();
        if (!trimmed || seen.has(trimmed)) continue;
        parts.push(c);
        seen.add(trimmed);
      }
    }

    // 2) Source attributions in insertion order (= layer add order).
    //    `tileManagers` is a plain object; ES2015+ preserves insertion
    //    order for string keys, which matches MapLibre's own iteration.
    const tileManagers = style.tileManagers ?? {};
    for (const id in tileManagers) {
      const tm = tileManagers[id];
      if (!(tm.used || tm.usedForTerrain)) continue;
      const src = tm.getSource?.();
      const attr: unknown = src?.attribution;
      if (typeof attr !== 'string') continue;
      const trimmed = attr.trim();
      if (!trimmed || seen.has(trimmed)) continue;
      parts.push(attr);
      seen.add(trimmed);
    }

    // 3) Image-layer attributions, keyed by the layer's `metadata`
    //    slot. MapLibre's `ImageSourceSpecification` doesn't declare
    //    an `attribution` field (unlike raster/vector/geojson), so
    //    `<map-link rel="image">` stashes its attribution on the
    //    layer's `metadata['mapml:attribution']` instead. Iteration
    //    order matches `<map-layer>` DOM order because layers are
    //    added in that order and `map.getStyle().layers` preserves
    //    that ordering. We call `getStyle()` (which serializes the
    //    live layer set) rather than reaching into `style.stylesheet`,
    //    because `stylesheet.layers` is only populated when the map
    //    was initialised from a URL / JSON string \u2014 our viewer
    //    boots from an empty inline style spec, so that path stays
    //    empty regardless of `addLayer` calls.
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const publicStyle = (this._map as any)?.getStyle?.();
    const publicLayers: Array<{ metadata?: unknown }> = publicStyle?.layers ?? [];
    for (const layer of publicLayers) {
      const meta = layer.metadata;
      if (meta === null || typeof meta !== 'object') continue;
      const attr = (meta as Record<string, unknown>)['mapml:attribution'];
      if (typeof attr !== 'string') continue;
      const trimmed = attr.trim();
      if (!trimmed || seen.has(trimmed)) continue;
      parts.push(attr);
      seen.add(trimmed);
    }

    // 4) Standalone attributions not tied to a source or layer —
    //    `<map-link rel="query">`-only layers, pushed via
    //    {@link setExtraAttributions}. Appended after source /
    //    image-layer attributions; deduped against them.
    for (const attr of this.#extraAttributions) {
      const trimmed = attr.trim();
      if (!trimmed || seen.has(trimmed)) continue;
      parts.push(attr);
      seen.add(trimmed);
    }

    // Keyboard-shortcuts opener button, left-most. Not part of `parts`
    // (which is deduped attribution text); it's interactive UI wired to
    // the modal `<dialog>` via `#onInnerClick`.
    const buttonHtml = this.#locale
      ? `<button type="button" class="shortcuts-button mapml-button">${this.#locale.kbdShortcuts}</button>`
      : '';

    const attribHtml = parts.join(' | ');
    const html =
      buttonHtml && attribHtml ? `${buttonHtml} | ${attribHtml}` : attribHtml;
    if (html === this._attribHTML) return;
    this._attribHTML = html;

    if (parts.length > 0) {
      // Direct innerHTML assignment; deliberately bypasses MapLibre's
      // DOM.sanitize. See file header for the trust argument.
      this._innerContainer.innerHTML = html;
      this._container.classList.remove('maplibregl-attrib-empty');
    } else {
      this._container.classList.add('maplibregl-attrib-empty');
    }
  }
}
