/**
 * Parsers for `<map-meta name>` content strings.
 *
 * MapML.js encodes `<map-meta>` content as a comma-separated list of
 * `key=value` pairs (whitespace tolerant). For `name="extent"`, the
 * recognised keys are of the form `top-left-<axis>` / `bottom-right-<axis>`
 * where `<axis>` names an axis in one of the four MapML coordinate
 * systems (GCRS `longitude`/`latitude`, PCRS `easting`/`northing`,
 * TCRS `x`/`y`, TILEMATRIX `column`/`row`). An optional `zoom=N` pins
 * a single zoom level and is *required* for TCRS / TILEMATRIX (the
 * mapping to projected space depends on the tile pyramid level).
 *
 * The parser dispatches on the axis of the first non-`zoom` key to
 * infer the CS, matching MapML.js's `Util.getBoundsFromMeta`. The
 * result is always PCRS bounds so downstream code (fitBounds, extent
 * envelope construction) can consume it uniformly, regardless of how
 * the author chose to encode the box.
 */

import {
  axisPairToPcrsBounds,
  axisToCS,
  csToAxes,
  type AxisPair,
  type MapmlCS,
  type PcrsBounds
} from './crs';
import type { MapmlProjection } from './projection';

/** Names that `<map-meta name>` may take, per MapML.js. */
export const MAP_META_NAMES = ['projection', 'extent', 'cs', 'zoom'] as const;
export type MapMetaName = (typeof MAP_META_NAMES)[number];

export function isMapMetaName(value: string): value is MapMetaName {
  return (MAP_META_NAMES as readonly string[]).includes(value);
}

/**
 * Split a `<map-meta content>` string into a plain key/value record.
 * Returns an empty object for null/empty input. Trims whitespace on both
 * sides of `=` and around items. Duplicate keys: last one wins.
 */
export function parseMetaContent(content: string | null): Record<string, string> {
  const out: Record<string, string> = {};
  if (content === null) return out;
  for (const pair of content.split(',')) {
    const eq = pair.indexOf('=');
    if (eq <= 0) continue;
    const key = pair.slice(0, eq).trim();
    const value = pair.slice(eq + 1).trim();
    if (key !== '') out[key] = value;
  }
  return out;
}

/**
 * Result of {@link parseExtentMeta}: the author's `top-left` /
 * `bottom-right` corner pair already reprojected into PCRS meters, plus
 * the pinned `zoom` (if any).
 *
 * The parser resolves the source CS (GCRS / PCRS / TCRS / TILEMATRIX)
 * internally so callers never need to switch on it — matches upstream
 * `Util.getBoundsFromMeta`, which likewise returns PCRS.
 */
export interface ExtentMeta {
  /** PCRS bounds, normalised so `min.x < max.x` and `min.y < max.y`. */
  bounds: PcrsBounds;
  /** Optional pinned zoom (extract from `zoom=N` in the content string). */
  zoom?: number;
}

/**
 * Parse a `<map-meta name="extent">` content string into PCRS bounds.
 *
 * The CS is discovered at runtime from the first `top-left-<axis>` /
 * `bottom-right-<axis>` key encountered: `axisToCS(axis)` yields
 * `GCRS` / `PCRS` / `TCRS` / `TILEMATRIX`, `csToAxes(cs)` yields the
 * pair of expected key suffixes, and the four corners are read as
 * `top-left-<h>` / `top-left-<v>` / `bottom-right-<h>` /
 * `bottom-right-<v>`. All four must be present and numeric.
 *
 * `zoom=N` is optional for GCRS / PCRS and **required** for TCRS /
 * TILEMATRIX (the axis \u2192 PCRS mapping is zoom-dependent). Non-OSMTILE
 * projections fall out of {@link axisPairToPcrsBounds}'s current
 * OSMTILE-only support; the caller sees `null` in that case (with no
 * warning, since a viewer-level projection mismatch will already be
 * reported elsewhere).
 *
 * Returns `null` for malformed / incomplete input, unknown axes, or
 * TCRS/TILEMATRIX without `zoom`.
 */
export function parseExtentMeta(
  content: string | null,
  projection: MapmlProjection
): ExtentMeta | null {
  const kv = parseMetaContent(content);
  // Discover the CS by scanning keys for the first `top-left-` or
  // `bottom-right-` entry and passing its axis suffix to `axisToCS`.
  let cs: MapmlCS | null = null;
  for (const key of Object.keys(kv)) {
    if (key === 'zoom') continue;
    let axis: string | null = null;
    if (key.startsWith('top-left-')) axis = key.slice('top-left-'.length);
    else if (key.startsWith('bottom-right-')) axis = key.slice('bottom-right-'.length);
    if (axis === null) continue;
    const c = axisToCS(axis);
    if (c === null) continue;
    cs = c;
    break;
  }
  if (cs === null) return null;

  const [hAxis, vAxis] = csToAxes(cs);
  const tlH = kv[`top-left-${hAxis}`];
  const tlV = kv[`top-left-${vAxis}`];
  const brH = kv[`bottom-right-${hAxis}`];
  const brV = kv[`bottom-right-${vAxis}`];
  if (tlH === undefined || tlV === undefined || brH === undefined || brV === undefined) {
    return null;
  }
  const hMin = Number(tlH);
  const vMin = Number(tlV);
  const hMax = Number(brH);
  const vMax = Number(brV);
  if ([hMin, vMin, hMax, vMax].some((n) => !Number.isFinite(n))) return null;

  let zoom: number | undefined;
  const zRaw = kv['zoom'];
  if (zRaw !== undefined) {
    const zn = Number(zRaw);
    if (Number.isFinite(zn)) zoom = zn;
  }
  // TCRS / TILEMATRIX corners are only meaningful at a specific zoom;
  // upstream throws in this case, we return null.
  if ((cs === 'TCRS' || cs === 'TILEMATRIX') && zoom === undefined) return null;

  const pair: AxisPair = { cs, hMin, hMax, vMin, vMax };
  const bounds = axisPairToPcrsBounds(pair, projection, zoom ?? 0);
  if (bounds === null) return null;
  const out: ExtentMeta = { bounds };
  if (zoom !== undefined) out.zoom = zoom;
  return out;
}

/** Result of {@link parseZoomMeta}. */
export interface ZoomMeta {
  min: number;
  max: number;
}

/**
 * Parse a `<map-meta name="zoom">` content string of the form
 * `min=N,max=M`. Returns `null` if either key is missing or non-numeric.
 */
export function parseZoomMeta(content: string | null): ZoomMeta | null {
  const kv = parseMetaContent(content);
  const min = Number(kv['min']);
  const max = Number(kv['max']);
  if (!Number.isFinite(min) || !Number.isFinite(max)) return null;
  return { min, max };
}
