import { MapExtent } from '../elements/map-extent';
import { MapLayer } from '../elements/map-layer';
import type { MapmlViewer } from '../elements/mapml-viewer';
import type { Locale } from '../i18n/locale';

/**
 * Right-click menu for the {@link LayerControl} fieldsets.
 *
 * Owns two menu panels mounted as siblings of the main {@link ContextMenu}
 * in the viewer's shadow root:
 *
 *   - `.mapml-contextmenu.mapml-layer-menu` shown when the user
 *     right-clicks anywhere on a `fieldset.mapml-layer-item`. Items:
 *     Zoom To Layer (`Z`) and Copy Layer (`L`).
 *   - `.mapml-contextmenu.mapml-extent-menu` shown when the user
 *     right-clicks anywhere on a `fieldset.mapml-layer-extent` (the
 *     extent fieldset is nested inside the layer fieldset, so
 *     `closest()` finds the extent first \u2014 matching MapML.js).
 *
 * Class names + ordering mirror MapML.js's `src/mapml/handlers/ContextMenu.js`
 * so existing layer-context-menu CSS and Playwright selectors keep working.
 *
 * Keyboard semantics (menu open):
 *   - `Z`   activate Zoom To
 *   - `L`   activate Copy
 *   - `Enter` / `Space`  activate focused item
 *   - `Escape`  close
 *   - `ArrowUp` / `ArrowDown` / `Home` / `End`  navigation
 *
 * The menu re-uses the `.mapml-contextmenu` CSS shipped by
 * [`contextMenuCss`](./contextMenu.css.ts).
 */
export class LayerContextMenu {
  readonly #viewer: MapmlViewer;
  readonly #locale: Locale;
  readonly #shadow: ShadowRoot;
  readonly #layerMenu: HTMLDivElement;
  readonly #extentMenu: HTMLDivElement;
  #layerItems: LayerMenuItem[] = [];
  #extentItems: LayerMenuItem[] = [];

  /** The menu currently shown, or `undefined` if both are hidden. */
  #activeMenu: HTMLDivElement | undefined;
  #activeItems: LayerMenuItem[] = [];
  #activeIndex = 0;

  /** The DOM element the user right-clicked, used by item callbacks. */
  #subject: MapLayer | MapExtent | undefined;

  /**
   * The element that held focus before the menu opened; restored on
   * close so keyboard users don’t get dropped back to `<body>`.
   * Matches MapML.js's ContextMenu, which returns focus to the map
   * canvas after keyboard-triggered close.
   */
  #previouslyFocused: Element | null = null;

  readonly #onShadowContextMenu: EventListener;
  readonly #onDocumentMouseDown: (e: MouseEvent) => void;
  readonly #onDocumentKeyDown: (e: KeyboardEvent) => void;

  constructor(viewer: MapmlViewer, mountInto: ShadowRoot, locale: Locale) {
    this.#viewer = viewer;
    this.#locale = locale;
    this.#shadow = mountInto;

    this.#layerMenu = this.#createMenuElement('mapml-layer-menu');
    this.#extentMenu = this.#createMenuElement('mapml-extent-menu');
    mountInto.append(this.#layerMenu, this.#extentMenu);

    this.#buildLayerItems();
    this.#buildExtentItems();

    this.#onShadowContextMenu = (e): void => this.#handleContextMenu(e as MouseEvent);
    this.#onDocumentMouseDown = (e): void => {
      if (!this.#activeMenu) return;
      if (e.composedPath().includes(this.#activeMenu)) return;
      this.close();
    };
    this.#onDocumentKeyDown = (e): void => this.#handleDocumentKeyDown(e);

    mountInto.addEventListener('contextmenu', this.#onShadowContextMenu);
    document.addEventListener('mousedown', this.#onDocumentMouseDown, true);
    document.addEventListener('keydown', this.#onDocumentKeyDown);
  }

  destroy(): void {
    this.#shadow.removeEventListener('contextmenu', this.#onShadowContextMenu);
    document.removeEventListener('mousedown', this.#onDocumentMouseDown, true);
    document.removeEventListener('keydown', this.#onDocumentKeyDown);
    this.close();
    this.#layerMenu.remove();
    this.#extentMenu.remove();
  }

  /** Close whichever menu is currently open. */
  close(): void {
    if (!this.#activeMenu) return;
    this.#activeMenu.hidden = true;
    this.#activeMenu = undefined;
    this.#activeItems = [];
    this.#activeIndex = 0;
    this.#subject = undefined;
    // Return focus to whatever the user was on before the menu opened.
    // Falls back to the map canvas so keyboard users never land on
    // <body> after Escape.
    const restore = this.#previouslyFocused;
    this.#previouslyFocused = null;
    if (restore instanceof HTMLElement && restore.isConnected) {
      restore.focus();
    } else {
      this.#viewer.renderer.map?.getCanvas().focus();
    }
  }

  // -------------------------------------------------------------------
  // DOM
  // -------------------------------------------------------------------

  #createMenuElement(extraClass: string): HTMLDivElement {
    const menu = document.createElement('div');
    menu.className = `mapml-contextmenu ${extraClass}`;
    menu.setAttribute('role', 'menu');
    menu.setAttribute('tabindex', '-1');
    menu.hidden = true;
    return menu;
  }

  #buildLayerItems(): void {
    const L = this.#locale;
    this.#layerItems = [
      this.#createItem(this.#layerMenu, {
        id: 'zoom-to-layer',
        label: L.lmZoomToLayer,
        kbd: 'Z',
        run: (): void => {
          if (this.#subject instanceof MapLayer) this.#subject.zoomTo();
        }
      }),
      this.#createItem(this.#layerMenu, {
        id: 'copy-layer',
        label: L.lmCopyLayer,
        kbd: 'L',
        run: (): void => {
          if (this.#subject instanceof MapLayer) {
            void this.#copy(this.#subject.getOuterHTML());
          }
        }
      })
    ];
  }

  #buildExtentItems(): void {
    const L = this.#locale;
    this.#extentItems = [
      this.#createItem(this.#extentMenu, {
        id: 'zoom-to-extent',
        label: L.lmZoomToExtent,
        kbd: 'Z',
        run: (): void => {
          if (this.#subject instanceof MapExtent) this.#subject.zoomTo();
        }
      }),
      this.#createItem(this.#extentMenu, {
        id: 'copy-extent',
        label: L.lmCopyExtent,
        kbd: 'L',
        run: (): void => {
          if (this.#subject instanceof MapExtent) {
            void this.#copy(this.#subject.getOuterHTML());
          }
        }
      })
    ];
  }

  #createItem(parent: HTMLElement, def: ItemDef): LayerMenuItem {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'mapml-contextmenu-item';
    btn.setAttribute('role', 'menuitem');
    btn.dataset.id = def.id;
    btn.tabIndex = -1;
    btn.innerHTML = `<span>${def.label}</span><kbd>${def.kbd}</kbd>`;
    btn.addEventListener('click', () => {
      def.run();
      this.close();
    });
    parent.appendChild(btn);
    return { el: btn, id: def.id, run: def.run };
  }

  // -------------------------------------------------------------------
  // Open / dispatch
  // -------------------------------------------------------------------

  #handleContextMenu(e: MouseEvent): void {
    const target = e.target as Element | null;
    if (target === null) return;

    // Walk the composed path so we still discriminate correctly when the
    // user right-clicks on a child element (e.g. the name span or the
    // checkbox label) of the fieldset.
    const path = e.composedPath();
    let extentEl: Element | undefined;
    let layerEl: Element | undefined;
    for (const node of path) {
      if (!(node instanceof Element)) continue;
      if (!extentEl && node.classList?.contains('mapml-layer-extent')) extentEl = node;
      if (!layerEl && node.classList?.contains('mapml-layer-item')) layerEl = node;
      if (extentEl && layerEl) break;
    }

    if (!extentEl && !layerEl) return; // not a layer-control fieldset; let other handlers run

    // Extent fieldset is nested inside the layer fieldset, so when both
    // match the extent menu wins \u2014 same as MapML.js's `_show`.
    if (extentEl) {
      const ext = this.#findMapExtentFor(extentEl);
      if (!ext) return;
      e.preventDefault();
      this.#subject = ext;
      this.#openMenu(this.#extentMenu, this.#extentItems, e.clientX, e.clientY);
      return;
    }
    if (layerEl) {
      const layer = this.#findMapLayerFor(layerEl);
      if (!layer) return;
      e.preventDefault();
      this.#subject = layer;
      this.#openMenu(this.#layerMenu, this.#layerItems, e.clientX, e.clientY);
    }
  }

  /**
   * Locate the `<map-layer>` whose `getLayerControlHTML()` produced the
   * given fieldset. The control panel is rebuilt on every layers-changed
   * event, so we walk the registered layers in index order and pick the
   * Nth that owns a non-empty fieldset position. Since the renderer
   * order matches the registered layer order this is robust against
   * label changes and dynamic add/remove.
   */
  #findMapLayerFor(fieldsetEl: Element): MapLayer | undefined {
    const fieldsets = this.#shadow.querySelectorAll('fieldset.mapml-layer-item');
    const idx = Array.prototype.indexOf.call(fieldsets, fieldsetEl);
    if (idx < 0) return undefined;
    return this.#viewer.layers[idx];
  }

  /**
   * Locate the `<map-extent>` whose `getLayerControlHTML()` produced
   * the given fieldset. Each layer's `getLayerControlHTML()` iterates
   * its non-hidden extents in document order, so we map by:
   *   1. the position of the owning layer fieldset (\u2192 owning `<map-layer>`)
   *   2. the position of this extent fieldset within that layer's
   *      grouped-extents fieldset (\u2192 Nth non-hidden `<map-extent>` child)
   */
  #findMapExtentFor(extentFieldsetEl: Element): MapExtent | undefined {
    const layerFieldsetEl = extentFieldsetEl.closest('fieldset.mapml-layer-item');
    if (!layerFieldsetEl) return undefined;
    const owningLayer = this.#findMapLayerFor(layerFieldsetEl);
    if (!owningLayer) return undefined;
    const grouped = layerFieldsetEl.querySelector('fieldset.mapml-layer-grouped-extents');
    const extFieldsets = grouped
      ? grouped.querySelectorAll(':scope > fieldset.mapml-layer-extent')
      : null;
    if (!extFieldsets) return undefined;
    const idx = Array.prototype.indexOf.call(extFieldsets, extentFieldsetEl);
    if (idx < 0) return undefined;
    let i = 0;
    // Iterate `owningLayer.contentRoot.children` so remote-content
    // layers (`<map-layer src="…">`) walk the shadow root, keeping
    // the fieldset-to-extent mapping in sync with the layer control's
    // own DOM order.
    for (const child of owningLayer.contentRoot.children) {
      if (!(child instanceof MapExtent)) continue;
      if (child.hasAttribute('hidden')) continue;
      if (i === idx) return child;
      i++;
    }
    return undefined;
  }

  #openMenu(
    menu: HTMLDivElement,
    items: LayerMenuItem[],
    clientX: number,
    clientY: number
  ): void {
    // Remember the element that had focus so `close()` can restore it.
    // Walk into nested shadow roots for correctness (activeElement on a
    // shadow root returns the outer host — we want the innermost focus).
    let focused: Element | null = this.#shadow.activeElement;
    while (focused?.shadowRoot?.activeElement) {
      focused = focused.shadowRoot.activeElement;
    }
    this.#previouslyFocused = focused;

    // Close any already-open menu (could be the other one).
    if (this.#activeMenu && this.#activeMenu !== menu) {
      this.#activeMenu.hidden = true;
    }
    this.#activeMenu = menu;
    this.#activeItems = items;
    this.#activeIndex = 0;

    // Position relative to the viewer host, then clamp inside it.
    menu.hidden = false;
    const host = this.#viewer.getBoundingClientRect();
    const menuW = menu.offsetWidth;
    const menuH = menu.offsetHeight;
    const x = clientX - host.left;
    const y = clientY - host.top;
    const maxX = Math.max(0, host.width - menuW - 2);
    const maxY = Math.max(0, host.height - menuH - 2);
    menu.style.left = `${Math.min(Math.max(0, x), maxX)}px`;
    menu.style.top = `${Math.min(Math.max(0, y), maxY)}px`;

    this.#focusItem(0);
  }

  /**
   * Returns the layer or extent fieldset currently containing focus,
   * or undefined if focus is elsewhere. Extent fieldsets take
   * precedence when both match (extent is nested inside layer),
   * matching the mouse right-click behaviour above.
   */
  #focusedLayerFieldset(): { kind: 'layer' | 'extent'; el: Element } | undefined {
    // Walk down through nested shadow roots (unlikely here, but future-proof).
    let active: Element | null = this.#shadow.activeElement;
    if (!active) return undefined;
    while (active.shadowRoot && active.shadowRoot.activeElement) {
      active = active.shadowRoot.activeElement;
    }
    const extentEl = active.closest('fieldset.mapml-layer-extent');
    if (extentEl) return { kind: 'extent', el: extentEl };
    const layerEl = active.closest('fieldset.mapml-layer-item');
    if (layerEl) return { kind: 'layer', el: layerEl };
    return undefined;
  }

  /**
   * Open the appropriate menu from a Shift+F10 / ContextMenu keypress.
   * Position defaults to the top-left corner of the fieldset (matching
   * how browsers place their native context menu for keyboard-triggered
   * `contextmenu` events on a focused element).
   */
  #openFromKeyboard(e: KeyboardEvent): void {
    const hit = this.#focusedLayerFieldset();
    if (!hit) return;
    e.preventDefault();
    e.stopPropagation();
    const rect = hit.el.getBoundingClientRect();
    if (hit.kind === 'extent') {
      const ext = this.#findMapExtentFor(hit.el);
      if (!ext) return;
      this.#subject = ext;
      this.#openMenu(this.#extentMenu, this.#extentItems, rect.left, rect.top);
    } else {
      const layer = this.#findMapLayerFor(hit.el);
      if (!layer) return;
      this.#subject = layer;
      this.#openMenu(this.#layerMenu, this.#layerItems, rect.left, rect.top);
    }
  }

  async #copy(text: string): Promise<void> {
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Clipboard API may be unavailable (no permission, insecure context,
      // headless without grants). Tests opt in via context permissions;
      // production callers see a console warning but no crash.
      console.warn('LayerContextMenu: clipboard write failed; copy item is a no-op.');
    }
  }

  // -------------------------------------------------------------------
  // Keyboard
  // -------------------------------------------------------------------

  #handleDocumentKeyDown(e: KeyboardEvent): void {
    if (!this.#activeMenu) {
      // No menu open yet — check for the keyboard "open menu" hotkeys
      // (Shift+F10 and the ContextMenu key). These should open the
      // layer / extent menu if focus is inside the corresponding
      // fieldset, matching MapML.js's `_showAtMousePos` fallback.
      if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) {
        this.#openFromKeyboard(e);
      }
      return;
    }
    // Only act when focus is inside our viewer (the menu lives in the
    // viewer's shadow root, so its activeElement chain leads back to it).
    if (!e.composedPath().includes(this.#viewer)) return;

    switch (e.key) {
      case 'Escape':
        e.preventDefault();
        this.close();
        return;
      case 'ArrowDown':
        e.preventDefault();
        this.#moveFocus(1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        this.#moveFocus(-1);
        return;
      case 'Tab':
        // Trap Tab / Shift+Tab inside the menu and cycle like the
        // arrow keys. Matches MapML.js's ContextMenu handling, which
        // treats Tab and ArrowDown as equivalent (and Shift+Tab as
        // ArrowUp).
        e.preventDefault();
        this.#moveFocus(e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        this.#focusItem(0);
        return;
      case 'End':
        e.preventDefault();
        this.#focusItem(this.#activeItems.length - 1);
        return;
      case 'Enter':
      case ' ': {
        e.preventDefault();
        this.#activeItems[this.#activeIndex]?.el.click();
        return;
      }
    }

    // Single-letter shortcuts (Z / L) match the upstream tests:
    //   page.keyboard.press('z') \u2192 zoom-to
    //   page.keyboard.press('l') \u2192 copy
    if (e.key === 'z' || e.key === 'Z') {
      const it = this.#activeItems.find((i) => i.id.startsWith('zoom-to'));
      if (it) {
        e.preventDefault();
        it.el.click();
      }
      return;
    }
    if (e.key === 'l' || e.key === 'L') {
      const it = this.#activeItems.find((i) => i.id.startsWith('copy'));
      if (it) {
        e.preventDefault();
        it.el.click();
      }
    }
  }

  #moveFocus(delta: 1 | -1): void {
    const n = this.#activeItems.length;
    if (n === 0) return;
    this.#focusItem((this.#activeIndex + delta + n) % n);
  }

  #focusItem(i: number): void {
    if (i < 0 || i >= this.#activeItems.length) return;
    for (let j = 0; j < this.#activeItems.length; j++) {
      this.#activeItems[j]!.el.tabIndex = j === i ? 0 : -1;
    }
    this.#activeIndex = i;
    this.#activeItems[i]!.el.focus();
  }
}

interface ItemDef {
  id: string;
  label: string;
  kbd: string;
  run: () => void;
}

interface LayerMenuItem {
  el: HTMLButtonElement;
  id: string;
  run: () => void;
}
