/**
 * `<mapml-viewer view="…">` presentation modes.
 *
 * Unlike {@link MapmlProjection} (a CRS / tile-grid concept), a `view` is a
 * *camera regime* layered over the same Web-Mercator data:
 *
 * | `view`        | MapLibre projection    | camera                              |
 * |---------------|------------------------|-------------------------------------|
 * | `map`         | `mercator`             | top-down; rotation / tilt locked    |
 * | `globe`       | `globe`                | 3-D globe; rotation / tilt allowed  |
 * | `perspective` | `mercator`             | tilted (pitched) camera over a flat map |
 *
 * The list is intentionally open-ended — future values (`table`, …) can be
 * added here, and unknown authored values warn + fall back to `map`.
 */

export const MAPML_VIEWS = ['map', 'globe', 'perspective'] as const;

export type MapmlView = (typeof MAPML_VIEWS)[number];

export function isMapmlView(value: string): value is MapmlView {
  return (MAPML_VIEWS as readonly string[]).includes(value);
}

/** MapLibre's own projection identifiers (a `view` resolves to one of these). */
export type MapLibreProjectionType = 'mercator' | 'globe' | 'vertical-perspective';

export interface ViewProfile {
  /** MapLibre projection to hand to `map.setProjection({ type })`. */
  projection: MapLibreProjectionType;
  /** Whether interactive rotation + tilt (drag-rotate / touch-pitch) is enabled. */
  allowTilt: boolean;
  /** Pitch (deg) applied when the author gives no explicit `pitch`. */
  defaultPitch: number;
}

/** Resolve a {@link MapmlView} to its concrete MapLibre projection + camera profile. */
export function viewProfile(view: MapmlView): ViewProfile {
  switch (view) {
    case 'globe':
      return { projection: 'globe', allowTilt: true, defaultPitch: 0 };
    case 'perspective':
      return { projection: 'mercator', allowTilt: true, defaultPitch: 60 };
    case 'map':
    default:
      return { projection: 'mercator', allowTilt: false, defaultPitch: 0 };
  }
}

/** The next view in the cycle `map → globe → perspective → map`. */
export function nextView(view: MapmlView): MapmlView {
  const i = MAPML_VIEWS.indexOf(view);
  return MAPML_VIEWS[(i + 1) % MAPML_VIEWS.length]!;
}
