import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * `CompassControl` — shows a compass needle whose black end always points
 * north, and resets the map to north-up when activated.
 *
 * Opt-in via `controlslist="compass"` (default-off, like `view` / `static`).
 * Rendered in the `top-right` well, immediately below the {@link LayerControl}
 * and above the {@link ViewControl}. A single button renders a
 * `<span class="mapml-compass-button-icon">`; the needle span is rotated by
 * `-bearing` so its black end tracks true north as the map rotates (only
 * possible in `globe` / `perspective` views — `map` view stays north-up).
 *
 * The needle stays in sync with camera rotation by listening for the map's
 * `rotate` / `move` events and the viewer's `mapml:viewchanged` event.
 * Activating the button resets the camera to north-up via `resetNorth()`.
 *
 * Icons: authors can override `.mapml-compass-button-icon` with their own
 * `background-image`.
 */
export class CompassControl implements IControl {
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  #icon: HTMLSpanElement | undefined;
  #map: MapLibreMap | undefined;
  readonly #viewer: MapmlViewer;
  #onViewChanged: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-right' {
    return 'top-right';
  }

  onAdd(map: MapLibreMap): HTMLDivElement {
    this.#map = map;

    const container = document.createElement('div');
    container.className = 'maplibregl-ctrl maplibregl-ctrl-group mapml-compass-button';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';

    const icon = document.createElement('span');
    icon.className = 'mapml-compass-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    button.addEventListener('click', this.#onClick);

    container.appendChild(button);
    this.#container = container;
    this.#button = button;
    this.#icon = icon;

    // Track the camera bearing live: `rotate` covers deliberate rotation,
    // `move` covers bearing changes that ride along with other camera moves.
    map.on('rotate', this.#onRotate);
    map.on('move', this.#onRotate);
    const onViewChanged = (): void => this.#render();
    this.#onViewChanged = onViewChanged;
    this.#viewer.addEventListener('mapml:viewchanged', onViewChanged);

    this.#render();
    return container;
  }

  onRemove(): void {
    this.#map?.off('rotate', this.#onRotate);
    this.#map?.off('move', this.#onRotate);
    this.#map = undefined;
    if (this.#onViewChanged) {
      this.#viewer.removeEventListener('mapml:viewchanged', this.#onViewChanged);
      this.#onViewChanged = undefined;
    }
    this.#button?.removeEventListener('click', this.#onClick);
    this.#container?.remove();
    this.#container = undefined;
    this.#button = undefined;
    this.#icon = undefined;
  }

  #onClick = (event: MouseEvent): void => {
    event.stopPropagation();
    // Reset the camera to north-up; `moveend` reflects the bearing back and
    // #onRotate re-renders the needle to straight up.
    this.#map?.resetNorth();
  };

  #onRotate = (): void => this.#render();

  /** Rotate the needle so its black end tracks true north. */
  #render(): void {
    if (!this.#button || !this.#icon) return;
    // MapLibre `bearing` is the compass direction that is "up"; north sits at
    // screen angle `-bearing`, so rotate the needle by `-bearing`.
    const bearing = this.#map?.getBearing() ?? 0;
    this.#icon.style.transform = `rotate(${-bearing}deg)`;
    const label = this.#viewer.locale.btnCompass;
    this.#button.title = label;
    this.#button.setAttribute('aria-label', label);
  }
}
