import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapLayer } from '../elements/map-layer';
import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * `LayerControl` — MapML.js-style layer toggle panel.
 *
 * Visual contract (matches MapML.js to the degree feasible):
 *   - Collapsed pill in the top-right showing the Leaflet-style "stack of
 *     three rectangles" layers icon.
 *   - Expanded panel lists each `<map-layer>` from the owning viewer.
 *     The DOM for each item is produced by `MapLayer.getLayerControlHTML()`
 *     (which in turn calls `MapExtent.getLayerControlHTML()` for sublayers),
 *     so the markup matches the structure produced by MapML.js's
 *     `createLayerControlForLayer.js` / `createLayerControlForExtent.js`.
 *   - Auto-collapses on map movestart (matches MapML.js behaviour).
 *
 * Class names mirror MapML.js / Leaflet (`mapml-layer-control`,
 * `leaflet-control-layers`, `leaflet-control-layers-expanded`,
 * `leaflet-control-layers-toggle`, `leaflet-control-layers-list`,
 * `leaflet-control-layers-selector`) so existing CSS can still target them.
 */
export class LayerControl implements IControl {
  readonly #viewer: MapmlViewer;
  #container: HTMLDivElement | undefined;
  #toggle: HTMLAnchorElement | undefined;
  #list: HTMLDivElement | undefined;
  #map: MapLibreMap | undefined;
  #layersChangedListener: ((event: Event) => void) | undefined;
  #movestartListener: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-right' {
    return 'top-right';
  }

  onAdd(map: MapLibreMap): HTMLDivElement {
    this.#map = map;
    const container = document.createElement('div');
    container.className =
      'maplibregl-ctrl maplibregl-ctrl-group mapml-layer-control leaflet-control-layers';
    container.setAttribute('aria-haspopup', 'true');

    const toggle = document.createElement('a');
    toggle.className = 'leaflet-control-layers-toggle';
    toggle.href = '#';
    toggle.title = 'Layers';
    toggle.setAttribute('role', 'button');
    toggle.setAttribute('aria-label', 'Layers');
    // Icon is applied via CSS background-image on
    // .leaflet-control-layers-toggle (layerControl.css) using MapML.js's
    // stacked-layers SVG data URI — matches the MapML.js reference.

    const list = document.createElement('div');
    list.className = 'leaflet-control-layers-list';

    container.append(toggle, list);

    const expand = (event?: Event): void => {
      event?.preventDefault();
      container.classList.add('leaflet-control-layers-expanded');
      // When expanded via keyboard (Enter/Space on the toggle anchor)
      // move focus to the first layer\u2019s checkbox so the user can
      // immediately navigate the list. Mouse-triggered clicks have
      // `detail > 0`; keyboard-triggered "clicks" have `detail === 0`.
      // Matches MapML.js's `_focusFirstLayer` behaviour on the toggle.
      if (event instanceof MouseEvent && event.detail === 0) {
        // Defer so the freshly-shown fieldsets are laid out first.
        setTimeout(() => this.#focusFirstFieldsetCheckbox(), 0);
      }
    };
    const collapse = (): void => {
      // Match MapML.js: don't collapse while a layer/extent right-click
      // menu is open, otherwise the fieldset the menu targets disappears
      // as soon as the pointer moves off it toward the menu.
      if (this.#isLayerContextMenuOpen()) return;
      container.classList.remove('leaflet-control-layers-expanded');
    };

    toggle.addEventListener('click', expand);
    container.addEventListener('mouseenter', expand);
    container.addEventListener('mouseleave', collapse);

    // Auto-collapse on movestart, matching MapML.js.
    this.#movestartListener = collapse;
    map.on('movestart', this.#movestartListener);

    this.#layersChangedListener = () => this.#rebuildList();
    this.#viewer.addEventListener('mapml:layerschanged', this.#layersChangedListener);

    this.#container = container;
    this.#toggle = toggle;
    this.#list = list;
    this.#rebuildList();

    return container;
  }

  onRemove(): void {
    if (this.#movestartListener && this.#map) {
      this.#map.off('movestart', this.#movestartListener);
    }
    if (this.#layersChangedListener) {
      this.#viewer.removeEventListener('mapml:layerschanged', this.#layersChangedListener);
    }
    this.#container?.remove();
    this.#container = undefined;
    this.#toggle = undefined;
    this.#list = undefined;
    this.#map = undefined;
  }

  #rebuildList(): void {
    const list = this.#list;
    const container = this.#container;
    if (!list || !container) return;

    // Preserve keyboard focus across the rebuild. `replaceChildren()`
    // detaches every fieldset, which unfocuses any focused descendant
    // (browsers move focus to `<body>` when the focused element is
    // removed from live DOM). But cached-DOM sub-parts survive the
    // detach: `MapSelect` reuses the same `<details>`/`<select>`
    // across rebuilds, so we can re-focus the exact same node after
    // the new fieldsets have gone up. Matches MapML.js's parity for
    // the `<select>` "keep focus during interactive redraws" idiom
    // \u2014 without this the `<select>` loses focus on every value
    // change (which cascades a full layer-control rebuild via
    // `unregisterChildLayer` / `registerChildLayer`).
    const root = list.getRootNode() as ShadowRoot | Document;
    const focusedBefore = list.contains(root.activeElement)
      ? (root.activeElement as HTMLElement)
      : null;

    list.replaceChildren();
    const layers = this.#viewer.layers;
    // Skip `<map-layer hidden>`: per the MapML spec, `hidden` hides
    // the layer from the layer control (rendering follows `checked`
    // only). Extents apply the same rule via their own
    // `getLayerControlHTML` in `map-layer.ts`.
    const visibleLayers = layers.filter((l) => !l.hasAttribute('hidden'));
    if (visibleLayers.length === 0) {
      container.setAttribute('hidden', '');
      return;
    }
    container.removeAttribute('hidden');

    // Wrap in an .leaflet-control-layers-overlays fieldset so MapML.js
    // CSS rules that target descendants of that wrapper (e.g. disabled
    // styling) still apply.
    const overlays = document.createElement('fieldset');
    overlays.className = 'leaflet-control-layers-overlays';
    for (const layer of visibleLayers) {
      overlays.appendChild(this.#renderItem(layer));
    }
    list.appendChild(overlays);

    // Refocus the previously-focused control if it survived the
    // rebuild. `list.contains(focusedBefore)` after the appendChild
    // confirms the exact same node was moved back into the fresh
    // fieldset (via cached DOM like MapSelect's `<details>`); if the
    // node isn't in the new subtree the control was rebuilt from
    // scratch and there's no meaningful restore target.
    if (focusedBefore !== null && list.contains(focusedBefore)) {
      focusedBefore.focus({ preventScroll: true });
    }
  }

  #renderItem(layer: MapLayer): HTMLElement {
    // Pass the viewer's active Locale so per-layer button titles,
    // opacity summary, and nested extent labels come from the same
    // locale bundle as the rest of the viewer chrome.
    return layer.getLayerControlHTML(this.#viewer.locale);
  }

  /**
   * True while either the layer or extent right-click menu (owned by
   * {@link LayerContextMenu}, mounted as a sibling in the same shadow
   * root) is visible. Used by the collapse handler so that moving the
   * pointer from the layer fieldset toward the popup menu doesn't
   * strand the menu by hiding the fieldset it targets.
   */
  #isLayerContextMenuOpen(): boolean {
    const container = this.#container;
    if (!container) return false;
    const root = container.getRootNode();
    if (!(root instanceof ShadowRoot) && !(root instanceof Document)) return false;
    const menus = (root as ShadowRoot | Document).querySelectorAll<HTMLElement>(
      '.mapml-contextmenu.mapml-layer-menu, .mapml-contextmenu.mapml-extent-menu'
    );
    for (const menu of menus) {
      if (!menu.hidden) return true;
    }
    return false;
  }

  /**
   * Move focus to the first checkbox in the first layer fieldset,
   * used when the user opens the panel via keyboard. Mirrors
   * MapML.js's `_focusFirstLayer`.
   */
  #focusFirstFieldsetCheckbox(): void {
    const list = this.#list;
    if (!list) return;
    const first = list.querySelector<HTMLInputElement>(
      'fieldset.mapml-layer-item input.leaflet-control-layers-selector'
    );
    first?.focus();
  }
}

