import * as maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';

/**
 * Register the `pmtiles://` protocol handler on first use.
 *
 * MapLibre's `addProtocol` is a global registration \u2014 two
 * `<mapml-viewer>`s on the same page share one handler. `Protocol` in
 * the `pmtiles` npm package is designed exactly for this shape: one
 * instance holds an in-memory LRU of parsed archive metadata, and its
 * `.tile` method is the callback MapLibre invokes per requested tile.
 *
 * Idempotent \u2014 the module-level flag `pmtilesProtocolRegistered`
 * short-circuits repeat calls, so any number of
 * `<map-link rel="tile" type="application/pmtiles">` upgrades share
 * the same handler + cache.
 *
 * Companion to `mapLibreWmsProtocol.ts` \u2014 same pattern (module-scoped
 * registry flag, one-shot `addProtocol` call). No per-layer entries
 * are kept here because the protocol handler doesn't need any
 * out-of-band state: the tile URL alone (`pmtiles://https://server/foo.pmtiles/z/x/y.mvt`)
 * is enough for `Protocol.tile` to serve the requested tile from the
 * right archive.
 */

/** Scheme name for the PMTiles protocol handler. */
export const PMTILES_PROTOCOL = 'pmtiles';

/**
 * Whether {@link ensurePmtilesProtocol} has already registered the
 * shared handler with MapLibre. `addProtocol` throws on double-register,
 * so gate on this flag rather than trying to look up the handler
 * after the fact.
 */
let pmtilesProtocolRegistered = false;

/**
 * Shared `Protocol` instance. Retained module-scoped so its internal
 * LRU (parsed archive directory pages) is shared across every
 * `<map-link rel="tile" type="application/pmtiles">` on the page.
 */
let sharedProtocol: Protocol | undefined;

/**
 * Register the shared `pmtiles://` protocol handler on first use.
 * Idempotent \u2014 subsequent calls short-circuit.
 */
export function ensurePmtilesProtocol(): void {
  if (pmtilesProtocolRegistered) return;
  pmtilesProtocolRegistered = true;
  sharedProtocol = new Protocol();
  maplibregl.addProtocol(PMTILES_PROTOCOL, sharedProtocol.tile);
}
