/**
 * Pretty-print a MapML DOM subtree as an indented string.
 *
 * Used by {@link MapmlViewer.viewSource} so the window opened by the
 * `View Source` context-menu item shows a readable, indented rendering
 * of the viewer's markup rather than a single long line of `outerHTML`.
 *
 * Design goals — MapML.js's `viewSource()` (see
 * `../MapML.js/src/mapml-viewer.js#viewSource`) simply blobs
 * `this.outerHTML` verbatim, so what this module produces is a
 * MapML-MapLibre extension, not a spec requirement. To keep the
 * output content-equivalent to `outerHTML`:
 *
 *  - Attributes are copied exactly as-is (values are HTML-escaped for
 *    display, but never reordered or renamed).
 *  - Element and attribute names are preserved verbatim from the DOM
 *    (which lowercases HTML element names on parse — same as
 *    `outerHTML`).
 *  - Void-element rendering follows the HTML serialisation model:
 *    known void elements (e.g. `<img>`, `<br>`, `<map-input>`) emit
 *    without a closing tag; everything else emits an opening and
 *    matching closing tag even when empty.
 *  - Text nodes containing only whitespace are dropped (they're
 *    formatting artefacts of the original document and would
 *    otherwise fight the new indentation). Non-whitespace text is
 *    trimmed and inlined on the same line as its parent when the
 *    element has no element children.
 *  - Elements with mixed content (both element children and non-
 *    whitespace text) fall back to the raw `outerHTML` — MapML
 *    doesn't normally produce this shape, but if authors nest
 *    prose we don't want to accidentally reflow it.
 *  - Comments are preserved and indented like elements.
 *
 * The output is not round-trip-guaranteed to reproduce the same DOM
 * (whitespace normalisation is inherently lossy); it is byte-equivalent
 * to `outerHTML` when re-parsed and re-serialised through the browser.
 */

/**
 * HTML void elements (never emit a closing tag). Sourced from the HTML
 * Living Standard as of 2024; MapML custom elements that behave as
 * self-closing (`<map-input>`, `<map-meta>`, `<map-link>`) are added
 * to the set so the output looks familiar to MapML authors.
 */
const VOID_ELEMENTS = new Set<string>([
  'area',
  'base',
  'br',
  'col',
  'embed',
  'hr',
  'img',
  'input',
  'link',
  'meta',
  'param',
  'source',
  'track',
  'wbr',
  // MapML self-closing tokens.
  'map-input',
  'map-meta',
  'map-link'
]);

/** Elements whose `textContent` is treated as raw (never HTML-escaped further, never indented). */
const RAW_TEXT_ELEMENTS = new Set<string>(['script', 'style']);

/**
 * Pretty-print `root` and every descendant.
 *
 * @param root  The element to serialise. Its own tags are included.
 * @param indent  Indent string per level. Defaults to two spaces.
 */
export function prettyPrintMapml(root: Element, indent = '  '): string {
  const lines: string[] = [];
  serialiseElement(root, 0, indent, lines);
  return lines.join('\n');
}

function serialiseElement(
  el: Element,
  depth: number,
  indent: string,
  out: string[]
): void {
  const pad = indent.repeat(depth);
  const name = el.tagName.toLowerCase();
  const openTag = formatOpenTag(el);

  // Void elements: self-closing, no children considered.
  if (VOID_ELEMENTS.has(name)) {
    out.push(`${pad}${openTag}`);
    return;
  }

  // Raw text (script / style): keep body verbatim on separate lines
  // between opening and closing tag; do not indent internals.
  if (RAW_TEXT_ELEMENTS.has(name)) {
    const body = (el as HTMLElement).textContent ?? '';
    if (body.length === 0) {
      out.push(`${pad}${openTag}</${name}>`);
    } else {
      out.push(`${pad}${openTag}`);
      out.push(body);
      out.push(`${pad}</${name}>`);
    }
    return;
  }

  const kids = classifyChildren(el);

  if (kids.mode === 'empty') {
    out.push(`${pad}${openTag}</${name}>`);
    return;
  }

  if (kids.mode === 'textOnly') {
    out.push(`${pad}${openTag}${escapeText(kids.text)}</${name}>`);
    return;
  }

  if (kids.mode === 'mixed') {
    // Non-whitespace text intermixed with elements: don't try to
    // reflow. Emit outerHTML verbatim at this element's indent.
    out.push(`${pad}${el.outerHTML}`);
    return;
  }

  // Block mode: element children (and possibly comments); each on its own line.
  out.push(`${pad}${openTag}`);
  for (const child of el.childNodes) {
    serialiseChild(child, depth + 1, indent, out);
  }
  out.push(`${pad}</${name}>`);
}

function serialiseChild(
  node: ChildNode,
  depth: number,
  indent: string,
  out: string[]
): void {
  if (node.nodeType === Node.ELEMENT_NODE) {
    serialiseElement(node as Element, depth, indent, out);
    return;
  }
  if (node.nodeType === Node.COMMENT_NODE) {
    const pad = indent.repeat(depth);
    out.push(`${pad}<!--${(node as Comment).data}-->`);
    return;
  }
  if (node.nodeType === Node.TEXT_NODE) {
    const text = (node.nodeValue ?? '').trim();
    if (text.length === 0) return;
    const pad = indent.repeat(depth);
    out.push(`${pad}${escapeText(text)}`);
    return;
  }
  // Anything else (CDATA, processing instructions, doctype) — ignore.
}

interface ChildClassification {
  mode: 'empty' | 'textOnly' | 'block' | 'mixed';
  text: string;
}

function classifyChildren(el: Element): ChildClassification {
  let hasElementChild = false;
  let hasNonWhitespaceText = false;
  let collectedText = '';

  for (const child of el.childNodes) {
    switch (child.nodeType) {
      case Node.ELEMENT_NODE:
        hasElementChild = true;
        break;
      case Node.TEXT_NODE: {
        const raw = child.nodeValue ?? '';
        if (raw.trim().length > 0) {
          hasNonWhitespaceText = true;
          collectedText += raw;
        }
        break;
      }
      case Node.COMMENT_NODE:
        hasElementChild = true; // Comments render on their own lines like elements.
        break;
      default:
        break;
    }
  }

  if (hasElementChild && hasNonWhitespaceText) {
    return { mode: 'mixed', text: '' };
  }
  if (hasElementChild) return { mode: 'block', text: '' };
  if (hasNonWhitespaceText) return { mode: 'textOnly', text: collectedText.trim() };
  return { mode: 'empty', text: '' };
}

function formatOpenTag(el: Element): string {
  const name = el.tagName.toLowerCase();
  const attrs = Array.from(el.attributes)
    .map((a) => ` ${a.name}="${escapeAttr(a.value)}"`)
    .join('');
  return `<${name}${attrs}>`;
}

function escapeAttr(v: string): string {
  return v
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;');
}

function escapeText(v: string): string {
  return v
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
