import type { MapmlProjection } from './projection';

/**
 * Declarative description of a `<map-input>` element.
 *
 * Mirrors (a subset of) the MapML `<map-input>` attribute set so that
 * the URL template engine can resolve `{name}` tokens in a `<map-link>`'s
 * `tref` without depending on the DOM element class.
 */
export interface MapInputDef {
  name: string;
  type: 'zoom' | 'location' | 'width' | 'height' | 'hidden' | 'bool';
  axis?: 'easting' | 'northing' | 'column' | 'row' | 'longitude' | 'latitude' | 'i' | 'j' | 'x' | 'y';
  units?: 'tilematrix' | 'pcrs' | 'gcrs' | 'tcrs' | 'map' | 'tile';
  /**
   * Author-supplied `position` attribute. MapML.js only inspects it
   * loosely (`.*-left` / `.*-right` / `top-.*` / `bottom-.*`), so the
   * type is deliberately `string` rather than a strict union.
   */
  position?: string;
  min?: number;
  max?: number;
  value?: string;
}

/**
 * Which viewport-corner coordinate a per-tile bbox input resolves to.
 * MapML.js's `TemplatedTileLayer._tileMatrixToPCRSPosition` produces
 * the same four PCRS readings from the tile's (col, row, zoom) — the
 * cornerMap tells the renderer's `mapmlwmstile://` protocol handler
 * which of the four each `{token}` in the stored template URL wants.
 */
export type TileCorner = 'west' | 'south' | 'east' | 'north';

export type TemplateEvaluationResult =
  | { kind: 'maplibre-tile'; url: string }
  | {
      /**
       * WMS-GetMap-per-tile shape. The tref references four viewport-corner
       * inputs (`<map-input type="location" units="tilematrix|pcrs"
       * axis="easting|northing|longitude|latitude" position="…">`) that
       * need to be resolved to the *tile's* PCRS bbox at request time,
       * not the viewport's. `templateUrl` is the tref with every other
       * variable (zoom, width, height, static `value`, `<map-select>`)
       * already substituted; only the four corner tokens remain. The
       * renderer wraps this template behind a `mapmlwmstile://` protocol
       * handler that computes the tile bbox from MapLibre's z/x/y and
       * substitutes the corner tokens per request. `cornerMap` records
       * which corner each remaining token resolves to.
       */
      kind: 'wms-tile';
      templateUrl: string;
      cornerMap: Record<string, TileCorner>;
    }
  | { kind: 'error'; reason: string };

/**
 * Result of resolving a `rel="image"` template against the current
 * map view. `url` is the fully-substituted request URL; `coordinates`
 * is the four-corner `[lon, lat]` box (top-left, top-right, bottom-right,
 * bottom-left) that MapLibre's `type: "image"` source expects.
 *
 * The coordinates are always in GCRS regardless of the units the
 * `<map-input>` declarations use to express the bbox — MapLibre
 * always wants geographic corners for the image source's `coordinates`
 * key. The template's substituted values still respect the author's
 * declared `units` (pcrs vs gcrs), because that's what the remote
 * WMS server expects to receive.
 */
export type ImageTemplateEvaluationResult =
  | {
      kind: 'image';
      url: string;
      coordinates: [
        [number, number],
        [number, number],
        [number, number],
        [number, number]
      ];
    }
  | { kind: 'error'; reason: string };

/**
 * Result of resolving a `rel="query"` template against a click at
 * the current map view. `url` is the fully-substituted GetFeatureInfo
 * / identify URL that the caller should fetch. No coordinates are
 * returned because query responses aren't spatial primitives in
 * MapLibre; the caller opens a popup at the click point on their own.
 */
export type QueryTemplateEvaluationResult =
  | { kind: 'query'; url: string }
  | { kind: 'error'; reason: string };

/**
 * Result of resolving a `rel="features"` template against the current
 * map view. `url` is the fully-substituted MapML-fragment URL that
 * the caller should fetch. The response is expected to be
 * `text/mapml` (an XML MapML document whose `<map-feature>` /
 * `<map-tile>` children get grafted into the link's shadow root).
 */
export type FeaturesTemplateEvaluationResult =
  | { kind: 'features'; url: string }
  | { kind: 'error'; reason: string };

/**
 * A snapshot of the current map view, passed to
 * {@link evaluateImageTemplate} so the URL builder can substitute
 * viewport-dependent values (bbox corners, width, height, zoom).
 *
 * `pcrs` and `gcrs` bboxes describe the *same rectangle* — the
 * viewer's current PCRS extent — expressed in each CS. Both are
 * axis-aligned (north up, west on the left) and normalised so
 * `west < east` and `south < north`. The renderer builds this
 * snapshot once per `moveend` and hands it to every image link so
 * they all resolve against a consistent view.
 */
export interface ViewSnapshot {
  widthPx: number;
  heightPx: number;
  /** Integer zoom level, matching `<map-input type="zoom">` semantics. */
  zoom: number;
  pcrs: { west: number; south: number; east: number; north: number };
  gcrs: { west: number; south: number; east: number; north: number };
}

/**
 * A snapshot of the click that triggered a `rel="query"` request.
 * Every axis/units combination MapML.js's `QueryHandler` recognises
 * has a slot here so {@link evaluateQueryTemplate} can substitute
 * without further computation.
 *
 * All values describe the same click event, expressed in the CRS the
 * author's `<map-input>` declared:
 *
 *   - `iPx / jPx` \u2014 cursor in viewport CSS pixels (top-left origin,
 *     x right, y down), rounded to integer at snapshot time so
 *     WMS GetFeatureInfo (which requires integer I/J) accepts the
 *     request regardless of whether the source was a mouse click
 *     (integer already) or a Space/Enter-at-centre synthetic event
 *     (which projects the map centre and typically produces
 *     fractional pixels). What `<map-input type="location"
 *     units="map" axis="i|j">` resolves to.
 *   - `gcrs` \u2014 cursor position in geographic WGS84. `<map-input
 *     type="location" units="gcrs" axis="longitude|latitude">` (without
 *     `position`).
 *   - `pcrs` \u2014 cursor position in the projection's native units
 *     (meters for OSMTILE). `<map-input type="location" units="pcrs"
 *     axis="easting|northing">` (without `position`).
 *   - `tcrs` \u2014 cursor in tile-pixel space at the current zoom
 *     (`pixel = tile * tileSize`). `<map-input type="location"
 *     units="tcrs" axis="x|y">`.
 *   - `tilematrix` \u2014 integer tile column/row containing the cursor.
 *     `<map-input type="location" units="tilematrix" axis="column|row">`.
 *   - `tile` \u2014 cursor pixel *within* its tile (0..tileSize-1).
 *     `<map-input type="location" units="tile" axis="i|j">`.
 *   - `tileBounds` \u2014 the PCRS bbox of the *tile that contains the
 *     cursor* (west/south/east/north, meters). What a
 *     `<map-input type="location" units="tilematrix" axis="…"
 *     position="…">` resolves to: unlike the `pcrs`/`gcrs` viewport
 *     corners, these edges are scoped to the single tile under the
 *     click, mirroring the per-tile bbox `evaluateTileTemplate`
 *     substitutes for `rel="tile"`. `units="tilematrix"` is the
 *     signal that the input is per-tile rather than per-viewport.
 */
export interface ClickSnapshot {
  iPx: number;
  jPx: number;
  gcrs: { lng: number; lat: number };
  pcrs: { easting: number; northing: number };
  tcrs: { x: number; y: number };
  tilematrix: { column: number; row: number };
  tile: { i: number; j: number };
  tileBounds: { west: number; south: number; east: number; north: number };
}

const TOKEN_RE = /\{([A-Za-z_][\w-]*)\}/g;

/**
 * Return the ordered, unique set of `{name}` tokens referenced by a
 * URL template. Empty when the template has no tokens.
 *
 * Used by `<map-link>.extent` to filter the enclosing `<map-extent>`'s
 * `<map-input>` list down to just the ones this link's `tref` uses \u2014
 * so a link's bounds/zoom can be more specific than the enclosing
 * extent's, mirroring MapML.js's `<map-link>._templateVars.values`.
 */
export function trefTokens(tref: string): string[] {
  const seen = new Set<string>();
  const out: string[] = [];
  for (const m of tref.matchAll(TOKEN_RE)) {
    const name = m[1]!;
    if (!seen.has(name)) {
      seen.add(name);
      out.push(name);
    }
  }
  return out;
}

/**
 * Evaluate a `<map-link rel="tile">` tref against the `<map-input>` declarations
 * in its owning `<map-extent>`.
 *
 * Two shapes are recognised:
 *
 * 1. **Tile-index tref** — `{z}` / `{col}` / `{row}` template variables backed
 *    by `<map-input type="zoom">` + `<map-input type="location" units="tilematrix"
 *    axis="column|row">`. Rewritten to MapLibre-native `{x}`/`{y}`/`{z}` and
 *    returned as `kind: 'maplibre-tile'` so the caller can feed it straight
 *    into a raster tile source.
 * 2. **Bbox tref (WMS-GetMap-per-tile)** — four `<map-input type="location"
 *    units="tilematrix|pcrs|gcrs" axis="easting|northing|longitude|latitude"
 *    position="top-*|bottom-*|*-left|*-right">` inputs that describe the
 *    tile's four PCRS/GCRS corners. Every other referenced input (zoom,
 *    width, height, static `value`, `<map-select>`) is substituted eagerly;
 *    only the four corner tokens survive in the returned `templateUrl`.
 *    The caller wraps the result behind a `mapmlwmstile://` protocol handler
 *    that performs the per-tile bbox substitution on the fly.
 *
 * v1 supports only the OSMTILE / Web Mercator tile pyramid. All other
 * axis/unit combinations are reported as errors so the caller can warn
 * and skip rather than render an incorrect layer.
 */
export function evaluateTileTemplate(
  tref: string,
  inputs: readonly MapInputDef[],
  extentUnits: MapmlProjection
): TemplateEvaluationResult {
  if (extentUnits !== 'OSMTILE') {
    return {
      kind: 'error',
      reason: `<map-extent units="${extentUnits}"> is not yet supported by the MapLibre renderer; provide a rel="alternate" link in OSMTILE.`
    };
  }

  const inputByName = new Map<string, MapInputDef>();
  for (const i of inputs) inputByName.set(i.name, i);

  const tokens = [...tref.matchAll(TOKEN_RE)].map((m) => m[1]!);
  if (tokens.length === 0) {
    return { kind: 'error', reason: 'tref contains no `{name}` variables.' };
  }

  // First pass: classify each token so we know whether this is a pure
  // tile-index tref (all tokens are z/x/y or static) or a bbox tref
  // (at least one token is a tile-corner input).
  interface Classified {
    token: string;
    input: MapInputDef;
    kind: 'maplibre' | 'corner' | 'static';
    /** For 'maplibre': the `{x}`/`{y}`/`{z}` token. */
    maplibreToken?: string;
    /** For 'corner': which of the four cardinal edges the tile input represents. */
    corner?: TileCorner;
    /** For 'static': the substituted string. */
    value?: string;
  }
  const classified: Classified[] = [];
  const seenTokens = new Set<string>();
  for (const token of tokens) {
    if (seenTokens.has(token)) continue;
    seenTokens.add(token);
    const input = inputByName.get(token);
    if (!input) {
      return {
        kind: 'error',
        reason: `tref references {${token}} but no <map-input name="${token}"> was found in the enclosing <map-extent>.`
      };
    }
    const mlt = maplibreTokenFor(input);
    if (mlt !== null) {
      classified.push({ token, input, kind: 'maplibre', maplibreToken: mlt });
      continue;
    }
    const corner = tileCornerRole(input);
    if (corner !== null) {
      classified.push({ token, input, kind: 'corner', corner });
      continue;
    }
    if (input.value !== undefined) {
      classified.push({ token, input, kind: 'static', value: input.value });
      continue;
    }
    return {
      kind: 'error',
      reason: describeUnsupportedInput(input)
    };
  }

  const hasCorner = classified.some((c) => c.kind === 'corner');

  // Pure tile-index path: no bbox tokens, everything is MapLibre-native
  // or a static author-supplied value. Emit the substituted URL as before.
  if (!hasCorner) {
    let url = tref;
    for (const c of classified) {
      const replacement = c.kind === 'maplibre' ? c.maplibreToken! : c.value!;
      url = url.split(`{${c.token}}`).join(replacement);
    }
    return { kind: 'maplibre-tile', url };
  }

  // Bbox tile path: substitute everything except the corner tokens.
  // Corner tokens survive into `templateUrl`; the renderer's
  // `mapmlwmstile://` protocol handler resolves them per tile from
  // MapLibre's z/x/y.
  let templateUrl = tref;
  const cornerMap: Record<string, TileCorner> = {};
  for (const c of classified) {
    if (c.kind === 'corner') {
      cornerMap[c.token] = c.corner!;
      continue;
    }
    // 'maplibre' tokens *would* be substituted by MapLibre if we let
    // them through, but the whole URL is going to be rewritten to a
    // `mapmlwmstile://` scheme (which MapLibre still template-expands
    // for `{z}`/`{x}`/`{y}`). We can therefore leave the MapLibre tokens
    // in place — the protocol handler will see the concrete `z`/`x`/`y`
    // via the incoming URL path. Substitute non-zoom author-named
    // tokens (e.g. `{level}` → `{z}`) so the outer URL still template-
    // expands correctly.
    const replacement = c.kind === 'maplibre' ? c.maplibreToken! : c.value!;
    templateUrl = templateUrl.split(`{${c.token}}`).join(replacement);
  }

  return { kind: 'wms-tile', templateUrl, cornerMap };
}

/**
 * Classify a `<map-input>` as one of the four tile-corner readings
 * (`west` / `east` / `north` / `south`) when its `axis` + `position`
 * describe a corner of a tile's PCRS bbox. Returns `null` when the
 * shape isn't a bbox-corner input.
 *
 * MapML.js's `TemplatedTileLayer._setUpTileTemplateVars` accepts
 * `units="tilematrix"` for these inputs (the min/max attributes are
 * still PCRS meters, per the switch statement that stores them into
 * `east.min/max` / `north.min/max`). We additionally accept
 * `units="pcrs"` / `units="gcrs"` since a WMS server that accepts
 * `CRS=EPSG:3857` receives PCRS meters and a `CRS=EPSG:4326` server
 * receives GCRS degrees — the units label on the input picks which
 * of the two the renderer substitutes at request time.
 */
function tileCornerRole(input: MapInputDef): TileCorner | null {
  if (input.type !== 'location') return null;
  if (
    input.units !== 'tilematrix' &&
    input.units !== 'pcrs' &&
    input.units !== 'gcrs'
  ) {
    return null;
  }
  const axis = input.axis;
  const position = input.position ?? '';
  if (axis === 'easting' || axis === 'longitude') {
    if (/-left/i.test(position)) return 'west';
    if (/-right/i.test(position)) return 'east';
    return null;
  }
  if (axis === 'northing' || axis === 'latitude') {
    if (/^top-/i.test(position)) return 'north';
    if (/^bottom-/i.test(position)) return 'south';
    return null;
  }
  return null;
}

/**
 * Evaluate a `<map-link rel="image">` tref against the current map view.
 *
 * Recognised `<map-input>` shapes (all others fall through to
 * `input.value` when available, else fail):
 *
 *   - `type="zoom"` \u2192 current integer zoom.
 *   - `type="width"` \u2192 viewport width in CSS pixels.
 *   - `type="height"` \u2192 viewport height in CSS pixels.
 *   - `type="location" units="pcrs|gcrs" position="…" axis="easting|northing|longitude|latitude"`
 *     \u2192 the corresponding viewport corner coordinate in the declared CS.
 *     Position/axis pairs map to the four cardinal edges (MapML.js parity):
 *
 *     |                 | axis=easting/longitude | axis=northing/latitude |
 *     | position=top-*  |                        | north edge             |
 *     | position=bottom-* |                      | south edge             |
 *     | position=*-left  | west edge             |                        |
 *     | position=*-right | east edge             |                        |
 *
 *     The specific pair (e.g. `top-left`) only selects one axis; the
 *     other-axis reading is *ignored*, mirroring MapML.js's `switch(axis)`
 *     in `TemplatedImageLayer._setUpExtentTemplateVars`.
 *   - Any `<map-input>` with a `value` attribute and no recognised
 *     type/axis pair \u2192 literal `input.value` substitution (matches
 *     MapML.js's fallback branch that emits `input.getAttribute('value')`).
 *
 * v1 supports OSMTILE only. Non-OSMTILE extents return an error.
 * Cursor-pixel inputs (`axis="i|j"`, `type="location" units="map|tile"`)
 * are query-flavoured and will be handled by the follow-on
 * `evaluateQueryTemplate` slice.
 */
export function evaluateImageTemplate(
  tref: string,
  inputs: readonly MapInputDef[],
  extentUnits: MapmlProjection,
  view: ViewSnapshot
): ImageTemplateEvaluationResult {
  if (extentUnits !== 'OSMTILE') {
    return {
      kind: 'error',
      reason: `<map-extent units="${extentUnits}"> is not yet supported by the MapLibre renderer; provide a rel="alternate" link in OSMTILE.`
    };
  }

  const inputByName = new Map<string, MapInputDef>();
  for (const i of inputs) inputByName.set(i.name, i);

  const tokens = [...tref.matchAll(TOKEN_RE)].map((m) => m[1]!);
  if (tokens.length === 0) {
    return { kind: 'error', reason: 'tref contains no `{name}` variables.' };
  }

  let url = tref;
  for (const token of tokens) {
    const input = inputByName.get(token);
    if (!input) {
      return {
        kind: 'error',
        reason: `tref references {${token}} but no <map-input name="${token}"> was found in the enclosing <map-extent>.`
      };
    }
    const replacement = imageValueFor(input, view);
    if (replacement === null) {
      return {
        kind: 'error',
        reason: describeUnsupportedImageInput(input)
      };
    }
    url = url.split(`{${token}}`).join(replacement);
  }

  const { west, north, east, south } = view.gcrs;
  return {
    kind: 'image',
    url,
    coordinates: [
      [west, north],
      [east, north],
      [east, south],
      [west, south]
    ]
  };
}

function maplibreTokenFor(input: MapInputDef): string | null {
  if (input.type === 'zoom') return '{z}';
  if (input.type === 'location' && input.units === 'tilematrix') {
    if (input.axis === 'column') return '{x}';
    if (input.axis === 'row') return '{y}';
  }
  return null;
}

/**
 * Substitute a single `<map-input>` with its current-view value for
 * `rel="image">` templating. Returns the string replacement (already
 * stringified) or `null` when the input's shape isn't recognised. The
 * caller wraps `null` into a descriptive warning via
 * {@link describeUnsupportedImageInput}.
 */
function imageValueFor(input: MapInputDef, view: ViewSnapshot): string | null {
  if (input.type === 'zoom') return String(view.zoom);
  if (input.type === 'width') return String(view.widthPx);
  if (input.type === 'height') return String(view.heightPx);
  if (input.type === 'location') {
    const edge = locationEdge(input);
    if (edge === null) return null;
    if (input.units === 'pcrs') {
      return String(view.pcrs[edge]);
    }
    if (input.units === 'gcrs') {
      return String(view.gcrs[edge]);
    }
    return null;
  }
  // MapML.js falls through to `input.getAttribute('value')` for any
  // input the switch statement doesn't consume \u2014 typically
  // `type="hidden"` variables baked into the request URL.
  if (input.value !== undefined) return input.value;
  return null;
}

/**
 * Determine which viewport edge a `<map-input type="location">`
 * refers to, based on its axis + position attributes. Returns
 * `null` when the combination is unrecognised. Matches MapML.js's
 * `switch(axis)` behaviour in
 * `TemplatedImageLayer._setUpExtentTemplateVars` \u2014 the axis
 * selects north/south (northing|latitude) vs east/west
 * (easting|longitude), and the position's prefix picks which of the
 * two the input corresponds to.
 */
function locationEdge(input: MapInputDef): 'west' | 'east' | 'north' | 'south' | null {
  const axis = input.axis;
  const position = input.position ?? '';
  if (axis === 'easting' || axis === 'longitude') {
    if (/-left/i.test(position)) return 'west';
    if (/-right/i.test(position)) return 'east';
    return null;
  }
  if (axis === 'northing' || axis === 'latitude') {
    if (/^top-/i.test(position)) return 'north';
    if (/^bottom-/i.test(position)) return 'south';
    return null;
  }
  return null;
}

function describeUnsupportedInput(input: MapInputDef): string {
  const attrs = [
    `name="${input.name}"`,
    `type="${input.type}"`,
    input.axis ? `axis="${input.axis}"` : null,
    input.units ? `units="${input.units}"` : null,
    input.position ? `position="${input.position}"` : null
  ]
    .filter(Boolean)
    .join(' ');
  return `<map-input ${attrs}> is not yet supported by rel="tile". Supported shapes are type="zoom", type="location" axis="column|row" units="tilematrix" (tile-index tref), or type="location" axis="easting|northing|longitude|latitude" units="tilematrix|pcrs|gcrs" position="top-left|top-right|bottom-left|bottom-right" (WMS bbox-per-tile tref). Static \`value\` inputs are also passed through.`;
}

function describeUnsupportedImageInput(input: MapInputDef): string {
  const attrs = [
    `name="${input.name}"`,
    `type="${input.type}"`,
    input.axis ? `axis="${input.axis}"` : null,
    input.units ? `units="${input.units}"` : null,
    input.position ? `position="${input.position}"` : null
  ]
    .filter(Boolean)
    .join(' ');
  return `<map-input ${attrs}> is not a recognised rel="image" template variable. Supported shapes are type="zoom" | type="width" | type="height" | type="location" with axis="easting|northing|longitude|latitude" + position="top-left|top-right|bottom-left|bottom-right" + units="pcrs|gcrs", or any input with a static \`value\` attribute.`;
}

/**
 * Evaluate a `<map-link rel="query">` tref against a click at the
 * current map view. Recognises every rel="image" template shape
 * (viewport bbox, width/height/zoom, static `value`) *plus* the
 * cursor-relative shapes MapML.js's `QueryHandler` supports:
 *
 *   - `type="location" units="map" axis="i|j"` \u2192 cursor pixel in the
 *     viewport (CSS pixels, top-left origin).
 *   - `type="location" units="tile" axis="i|j"` \u2192 cursor pixel within
 *     the tile that contains it (0..tileSize-1).
 *   - `type="location" units="tilematrix" axis="column|row"` (no
 *     `position`) \u2192 integer tile column/row containing the cursor.
 *   - `type="location" units="tcrs" axis="x|y"` (no `position`) \u2192
 *     cursor in tile-pixel space at the current zoom.
 *   - `type="location" units="pcrs" axis="easting|northing"` (no
 *     `position`) \u2192 cursor position in projection meters.
 *   - `type="location" units="gcrs" axis="longitude|latitude"` (no
 *     `position`) \u2192 cursor position in degrees.
 *
 * The presence of a `position` attribute is what distinguishes the
 * viewport-corner branch (`rel="image">` shape) from the cursor branch
 * for `pcrs` / `gcrs` location inputs. TILEMATRIX / TCRS / MAP / TILE
 * units don't accept `position` in v1 \u2014 those inputs always resolve
 * to the cursor's value regardless.
 *
 * v1 supports OSMTILE only. Non-OSMTILE extents return an error.
 */
export function evaluateQueryTemplate(
  tref: string,
  inputs: readonly MapInputDef[],
  extentUnits: MapmlProjection,
  view: ViewSnapshot,
  click: ClickSnapshot
): QueryTemplateEvaluationResult {
  if (extentUnits !== 'OSMTILE') {
    return {
      kind: 'error',
      reason: `<map-extent units="${extentUnits}"> is not yet supported by the MapLibre renderer; provide a rel="alternate" link in OSMTILE.`
    };
  }

  const inputByName = new Map<string, MapInputDef>();
  for (const i of inputs) inputByName.set(i.name, i);

  const tokens = [...tref.matchAll(TOKEN_RE)].map((m) => m[1]!);
  if (tokens.length === 0) {
    return { kind: 'error', reason: 'tref contains no `{name}` variables.' };
  }

  let url = tref;
  for (const token of tokens) {
    const input = inputByName.get(token);
    if (!input) {
      return {
        kind: 'error',
        reason: `tref references {${token}} but no <map-input name="${token}"> was found in the enclosing <map-extent>.`
      };
    }
    const replacement = queryValueFor(input, view, click);
    if (replacement === null) {
      return {
        kind: 'error',
        reason: describeUnsupportedQueryInput(input)
      };
    }
    url = url.split(`{${token}}`).join(replacement);
  }

  return { kind: 'query', url };
}

/**
 * Substitute a single `<map-input>` with its click-relative value
 * for `rel="query">` templating. Falls through to the rel="image"
 * substitution helper for the shared shapes (width/height/zoom,
 * viewport-corner locations, static values); adds the cursor-relative
 * shapes on top.
 */
function queryValueFor(
  input: MapInputDef,
  view: ViewSnapshot,
  click: ClickSnapshot
): string | null {
  // Cursor-relative shapes first: any `<map-input type="location">`
  // whose axis/units combination is inherently cursor-valued.
  if (input.type === 'location') {
    // MAP-space cursor pixel (i/j in CSS viewport pixels).
    if (input.units === 'map' && (input.axis === 'i' || input.axis === 'j')) {
      return String(input.axis === 'i' ? click.iPx : click.jPx);
    }
    // TILE-local cursor pixel (i/j within the tile the cursor is in).
    if (input.units === 'tile' && (input.axis === 'i' || input.axis === 'j')) {
      return String(input.axis === 'i' ? click.tile.i : click.tile.j);
    }
    // TILE-bbox corner: a `units="tilematrix"` location input with a
    // corner `position` resolves to the click's containing tile's PCRS
    // bbox edge (west/south/east/north) — scoped to that one tile, not
    // the viewport. `units="tilematrix"` is the signal that the input
    // is per-tile (mirrors evaluateTileTemplate's tileCornerRole); the
    // tile's min/max are PCRS meters by MapML.js convention.
    if (input.units === 'tilematrix' && input.position !== undefined) {
      const edge = locationEdge(input);
      if (edge !== null) return String(click.tileBounds[edge]);
    }
    // Cursor coordinates in a spatial CS: these are cursor-valued only
    // when `position` is absent. When `position` is present the caller
    // is asking for a viewport corner instead, which the image
    // substituter handles.
    if (input.position === undefined) {
      if (input.units === 'tilematrix') {
        if (input.axis === 'column') return String(click.tilematrix.column);
        if (input.axis === 'row') return String(click.tilematrix.row);
      }
      if (input.units === 'tcrs') {
        if (input.axis === 'x') return String(click.tcrs.x);
        if (input.axis === 'y') return String(click.tcrs.y);
      }
      if (input.units === 'pcrs') {
        if (input.axis === 'easting') return String(click.pcrs.easting);
        if (input.axis === 'northing') return String(click.pcrs.northing);
      }
      if (input.units === 'gcrs') {
        if (input.axis === 'longitude') return String(click.gcrs.lng);
        if (input.axis === 'latitude') return String(click.gcrs.lat);
      }
    }
  }
  // Fall through to the rel="image" recogniser for width/height/zoom
  // and viewport-corner (`position`-driven) location inputs.
  return imageValueFor(input, view);
}

function describeUnsupportedQueryInput(input: MapInputDef): string {
  const attrs = [
    `name="${input.name}"`,
    `type="${input.type}"`,
    input.axis ? `axis="${input.axis}"` : null,
    input.units ? `units="${input.units}"` : null,
    input.position ? `position="${input.position}"` : null
  ]
    .filter(Boolean)
    .join(' ');
  return `<map-input ${attrs}> is not a recognised rel="query" template variable. Supported shapes are the rel="image" set (type="zoom" | type="width" | type="height" | type="location" position="top-left|top-right|bottom-left|bottom-right" axis="easting|northing|longitude|latitude" units="pcrs|gcrs") plus the cursor-relative set (type="location" units="map|tile" axis="i|j", or type="location" without position with units="tilematrix|tcrs|pcrs|gcrs") plus the per-tile bbox set (type="location" units="tilematrix" position="top-left|top-right|bottom-left|bottom-right" axis="easting|northing", resolving to the clicked tile's PCRS bbox edge). Static \`value\` inputs are also passed through.`;
}


/**
 * Evaluate a `<map-link rel="features">` tref against the current
 * map view. Recognises exactly the same `<map-input>` shapes as
 * {@link evaluateImageTemplate} (`width` / `height` / `zoom` /
 * viewport-corner `location` + static `value`), just returning a
 * plain URL string \u2014 no coordinates \u2014 because the response is a
 * MapML fragment fetched over the wire rather than a raster image
 * pinned to viewport corners.
 *
 * Mirrors MapML.js's `TemplatedFeaturesOrTilesLayer._setUpTemplateVars`
 * + `_onMoveEnd` URL-building pipeline. v1 supports OSMTILE only;
 * other extents return an error result.
 */
export function evaluateFeaturesTemplate(
  tref: string,
  inputs: readonly MapInputDef[],
  extentUnits: MapmlProjection,
  view: ViewSnapshot
): FeaturesTemplateEvaluationResult {
  if (extentUnits !== 'OSMTILE') {
    return {
      kind: 'error',
      reason: `<map-extent units="${extentUnits}"> is not yet supported by the MapLibre renderer; provide a rel="alternate" link in OSMTILE.`
    };
  }

  const inputByName = new Map<string, MapInputDef>();
  for (const i of inputs) inputByName.set(i.name, i);

  const tokens = [...tref.matchAll(TOKEN_RE)].map((m) => m[1]!);
  if (tokens.length === 0) {
    return { kind: 'error', reason: 'tref contains no `{name}` variables.' };
  }

  let url = tref;
  for (const token of tokens) {
    const input = inputByName.get(token);
    if (!input) {
      return {
        kind: 'error',
        reason: `tref references {${token}} but no <map-input name="${token}"> was found in the enclosing <map-extent>.`
      };
    }
    const replacement = imageValueFor(input, view);
    if (replacement === null) {
      return {
        kind: 'error',
        reason: describeUnsupportedImageInput(input)
      };
    }
    url = url.split(`{${token}}`).join(replacement);
  }

  return { kind: 'features', url };
}
