import { shadowCrossingClosest, shadowCrossingClosestByTag } from '../core/shadow';
import { MapFeature } from './map-feature';
import { MapLayer } from './map-layer';
import type { MapmlViewer } from './mapml-viewer';

/**
 * `<map-a>` — hyperlink wrapper around a `<map-feature>`'s geometry
 * (or a shape inside a `<map-geometrycollection>`).
 *
 * MapML.js parity: `HTMLAnchorElement` in `../MapML.js/src/map-a.js`.
 * The upstream element is essentially a stub — attribute plumbing
 * only, with all click / navigate behaviour driven by the
 * `<map-feature>`'s rendered path. This port follows the same shape:
 *
 *   - Attribute reflection: `href` / `target` / `type` / `inplace`.
 *   - No rendering of its own — recognition happens when the owning
 *     `<map-feature>.toGeoJsonFeatures()` walks its `<map-geometry>`
 *     subtree, sees any `<map-a>` wrappers around a shape, and bakes
 *     `linkHref` / `linkTarget` / `linkType` / `linkInplace` into the
 *     emitted GeoJSON feature `properties`.
 *   - Mutating any observed attribute nudges the owning `<map-layer>`
 *     to rebuild its aggregated GeoJSON source so the baked link
 *     data stays in sync with authoring changes (same shape as
 *     `<map-feature>`'s own attribute observer).
 *
 * Click / keyboard-Enter dispatch on features carrying link data
 * lives in {@link import('../core/featureLinks').handleFeatureLink}
 * (routed from the renderer's feature-click handler and from
 * {@link FeatureFocusIndex}'s Enter/Space key handler). See that
 * module for the MapML.js `Util._handleLink` port.
 *
 * Deliberately out of scope for the first slice:
 *
 *   - Sub-part links (a `<map-a>` around a bare pair of coordinates
 *     inside a `<map-coordinates>` — MapML.js splits the geometry
 *     into sub-parts and gives the sub-part its own SVG path).
 *   - Link-preview hover toast (MapML.js's `.mapml-link-preview` div
 *     showing the resolved `href` on hover).
 *   - Visited-state styling (MapML.js sets `.map-a-visited` + a
 *     purple stroke on the source path after activation).
 */
export class MapA extends HTMLElement {
  static readonly observedAttributes = ['href', 'target', 'type', 'inplace'] as const;

  #connected = false;

  get href(): string {
    return this.getAttribute('href') ?? '';
  }
  set href(value: string) {
    this.setAttribute('href', value);
  }

  get target(): string {
    return this.getAttribute('target') ?? '';
  }
  set target(value: string) {
    this.setAttribute('target', value);
  }

  get type(): string {
    return this.getAttribute('type') ?? '';
  }
  set type(value: string) {
    this.setAttribute('type', value);
  }

  /**
   * Boolean-attribute-style reflector. Present + any value → `true`
   * (`getAttribute` returns the string value or `''` for a bare
   * `inplace` attribute); absent → `false`. Matches MapML.js's
   * intent (its upstream setter has a typo — `'inpalce'` — this
   * port fixes it).
   */
  get inplace(): boolean {
    return this.hasAttribute('inplace');
  }
  set inplace(value: boolean) {
    if (value) {
      this.setAttribute('inplace', '');
    } else {
      this.removeAttribute('inplace');
    }
  }

  /**
   * MapML.js JS-API parity: return the ancestor `<mapml-viewer>` for
   * this anchor. Shadow-crossing so a `<map-a>` grafted inside a
   * `<map-layer src="…">` remote-content shadow root still resolves
   * the enclosing viewer.
   */
  getMapEl(): MapmlViewer | null {
    return shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null;
  }

  /** MapML.js JS-API parity: ancestor `<map-layer>`, shadow-crossing. */
  getLayerEl(): MapLayer | null {
    return shadowCrossingClosest(
      this,
      (el): el is MapLayer => el instanceof MapLayer
    );
  }

  /** MapML.js JS-API parity: ancestor `<map-feature>`, shadow-crossing. */
  getFeatureEl(): MapFeature | null {
    return shadowCrossingClosest(
      this,
      (el): el is MapFeature => el instanceof MapFeature
    );
  }

  connectedCallback(): void {
    // `data-moving` on an ancestor `<map-layer>` signals a
    // drag-to-reorder DOM shuffle; skip rebuild churn so the
    // layer's aggregated source doesn't re-upload for a no-op
    // reparent. Mirrors the guard in `<map-feature>` /
    // `<map-link>` / `<map-extent>`.
    if (this.closest('[data-moving]')) return;
    this.#connected = true;
  }

  disconnectedCallback(): void {
    if (this.closest('[data-moving]')) return;
    this.#connected = false;
    // Nudge the layer to rebuild so any features that were emitting
    // link data via this anchor drop the link fields.
    this.#notifyOwningLayer();
  }

  attributeChangedCallback(): void {
    if (!this.#connected) return;
    // Any observed attribute change → link data baked into the
    // owning `<map-feature>`'s GeoJSON needs to be refreshed.
    // MapML.js updates the SVG path's link-handler binding directly;
    // we roll it into the layer's coalesced feature rebuild.
    this.#notifyOwningLayer();
  }

  #notifyOwningLayer(): void {
    const layer = this.getLayerEl();
    layer?.notifyFeaturesChanged();
  }
}
