/**
 * Typed port of the MapML.js `DOMTokenList` shim used for the
 * `controlslist` attribute on `<mapml-viewer>`.
 *
 * Semantics mirror upstream (`../../MapML.js/src/mapml/utils/DOMTokenList.js`):
 *
 * - Wraps a donor `<div>`'s native `DOMTokenList` (`element.classList`) so we
 *   get parsing, iteration, and de-dup for free from the platform.
 * - Every mutating call reflects back to the owner element's attribute so
 *   getAttribute/setAttribute stays consistent.
 * - `#valueSet` guard breaks the re-entrance loop between the setter and
 *   the custom element's `attributeChangedCallback`.
 * - `supports()` validates against a fixed token domain — that's how the
 *   viewer decides whether a token like `geolocation` is meaningful.
 *
 * We deliberately keep the class small and expose a `Symbol.iterator` so
 * `for (const t of viewer.controlsList)` works.
 */
export class ControlsTokenList<Token extends string = string> {
  readonly #owner: HTMLElement;
  readonly #attribute: string;
  readonly #domain: readonly string[];
  readonly #inner: DOMTokenList;
  #valueSet = false;

  constructor(
    initialValue: string | null,
    owner: HTMLElement,
    attribute: string,
    domain: readonly Token[]
  ) {
    // Donor div is only used for its classList — never inserted anywhere,
    // and released to GC when this instance is dropped.
    const donor = owner.ownerDocument.createElement('div');
    this.#inner = donor.classList;
    this.#inner.value = initialValue ?? '';
    this.#owner = owner;
    this.#attribute = attribute;
    this.#domain = domain;
  }

  /** True while a mutation from this class is reflecting to the attribute. */
  get valueSet(): boolean {
    return this.#valueSet;
  }

  get length(): number {
    return this.#inner.length;
  }

  get value(): string {
    return this.#inner.value;
  }

  set value(val: string | null) {
    if (val === null) {
      this.#inner.value = '';
    } else {
      this.#inner.value = val.toLowerCase();
    }
    this.#reflect();
  }

  item(index: number): string | null {
    return this.#inner.item(index);
  }

  contains(token: string): boolean {
    return this.#inner.contains(token);
  }

  add(...tokens: string[]): void {
    this.#inner.add(...tokens);
    this.#reflect();
  }

  remove(...tokens: string[]): void {
    this.#inner.remove(...tokens);
    this.#reflect();
  }

  replace(oldToken: string, newToken: string): boolean {
    const result = this.#inner.replace(oldToken, newToken);
    this.#reflect();
    return result;
  }

  toggle(token: string, force?: boolean): boolean {
    const result = this.#inner.toggle(token, force);
    this.#reflect();
    return result;
  }

  supports(token: string): boolean {
    return this.#domain.includes(token);
  }

  forEach(callbackfn: (value: string, key: number, parent: DOMTokenList) => void, thisArg?: unknown): void {
    this.#inner.forEach(callbackfn, thisArg);
  }

  entries(): IterableIterator<[number, string]> {
    return this.#inner.entries();
  }

  keys(): IterableIterator<number> {
    return this.#inner.keys();
  }

  values(): IterableIterator<string> {
    return this.#inner.values();
  }

  [Symbol.iterator](): IterableIterator<string> {
    return this.#inner.values();
  }

  toString(): string {
    return this.#inner.value;
  }

  #reflect(): void {
    this.#valueSet = true;
    try {
      this.#owner.setAttribute(this.#attribute, this.#inner.value);
    } finally {
      this.#valueSet = false;
    }
  }
}

/**
 * Token domain supported by `<mapml-viewer controlslist>`. Matches upstream
 * MapML.js exactly so authors can copy pages across renderers.
 *
 * Subtractive (turn a default-on control off):
 * - `noreload`, `nofullscreen`, `nozoom`, `nolayer`, `noscale`
 *
 * Additive (opt-in to a default-off control):
 * - `geolocation`, `search`, `view`, `static`, `featureindex`, `compass`
 */
export const CONTROLSLIST_TOKENS = [
  'noreload',
  'nofullscreen',
  'nozoom',
  'nolayer',
  'noscale',
  'geolocation',
  'search',
  'view',
  'static',
  'featureindex',
  'compass'
] as const;

export type ControlslistToken = (typeof CONTROLSLIST_TOKENS)[number];
