/**
 * Pure model for `<map-feature>` geometry: parsing `<map-coordinates>` text
 * into typed shapes, and converting those shapes to GeoJSON (WGS84 lon/lat)
 * or to a PCRS bounding box.
 *
 * The renderer consumes only GeoJSON in GCRS (`[lon, lat]`), because that's
 * what MapLibre expects for a `geojson` source. The PCRS bbox is used by
 * `<map-feature>.extent` and by the owning `<map-layer>` to union in
 * feature-derived bounds when computing its own extent — matching MapML.js
 * where `MapFeatureLayer` contributes to `<map-layer>.extent` via
 * `_calculateBounds()`.
 *
 * v1 support:
 *   - Coordinate systems: `gcrs` and `pcrs` (OSMTILE Web Mercator).
 *   - Geometry types: `<map-point>`, `<map-linestring>`, `<map-polygon>`,
 *     `<map-multipoint>`, `<map-multilinestring>`, `<map-multipolygon>`.
 *   - Inner rings (holes) on polygons — each `<map-coordinates>` after
 *     the first inside a `<map-polygon>` becomes a hole ring.
 *
 * Deliberately out of scope: `<map-geometrycollection>` — deferred.
 */

import {
  osmtileGcrsToPcrs,
  osmtilePcrsToGcrs,
  type PcrsBounds
} from './crs';
import type { MapmlProjection } from './projection';

/** Coordinate systems supported by `<map-feature>` geometry in v1. */
export type FeatureCS = 'gcrs' | 'pcrs';

export interface FeaturePointShape {
  kind: 'Point';
  coordinates: [number, number];
}

export interface FeatureLineStringShape {
  kind: 'LineString';
  coordinates: [number, number][];
}

export interface FeaturePolygonShape {
  kind: 'Polygon';
  /**
   * Ring array in GeoJSON order: `coordinates[0]` is the outer ring,
   * `coordinates[1..]` are inner rings (holes). Each ring is closed
   * (its first and last coordinate are identical).
   */
  coordinates: [number, number][][];
}

/**
 * All points of a `<map-multipoint>`, flattened across any
 * `<map-coordinates>` children (matches MapML.js's
 * `<map-multipoint>` semantics: one point per `x y` pair).
 */
export interface FeatureMultiPointShape {
  kind: 'MultiPoint';
  coordinates: [number, number][];
}

/**
 * One line per `<map-coordinates>` child of `<map-multilinestring>`.
 */
export interface FeatureMultiLineStringShape {
  kind: 'MultiLineString';
  coordinates: [number, number][][];
}

/**
 * One polygon per `<map-polygon>` child of `<map-multipolygon>`. Each
 * polygon carries its rings in GeoJSON order (`[outer, hole1, hole2, …]`),
 * so holes-in-multi-polygon are supported the same way as
 * holes-in-polygon.
 */
export interface FeatureMultiPolygonShape {
  kind: 'MultiPolygon';
  coordinates: [number, number][][][];
}

export type FeatureShape =
  | FeaturePointShape
  | FeatureLineStringShape
  | FeaturePolygonShape
  | FeatureMultiPointShape
  | FeatureMultiLineStringShape
  | FeatureMultiPolygonShape;

/**
 * Normalise an author-supplied `cs` string. Returns `null` for unknown
 * values (`tcrs`, `tilematrix`, misspellings) so the caller can fall
 * back to a `<map-meta name="cs">` or the ultimate `gcrs` default,
 * matching MapML.js's `_getFallbackCS()`.
 */
export function parseGeometryCS(raw: string | null | undefined): FeatureCS | null {
  if (raw === null || raw === undefined) return null;
  const v = raw.trim().toLowerCase();
  if (v === 'gcrs' || v === 'pcrs') return v;
  return null;
}

/**
 * Parse the text content of a `<map-coordinates>` element into a flat
 * `[x, y, x, y, …]` list of finite numbers. MapML.js's rules apply:
 * inline markup (e.g. `<map-span>` annotations) is stripped, and any
 * combination of whitespace and commas separates values.
 */
export function parseCoordinatesText(text: string): number[] {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/[,\r\n\t]+/g, ' ')
    .trim()
    .split(/\s+/)
    .filter((s) => s !== '')
    .map(Number)
    .filter((n) => Number.isFinite(n));
}

function pairs(flat: readonly number[]): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i + 1 < flat.length; i += 2) {
    out.push([flat[i]!, flat[i + 1]!]);
  }
  return out;
}

/**
 * Extract every ring from a `<map-polygon>` element. Each child
 * `<map-coordinates>` contributes one ring in document order:
 * the first ring is the polygon's outer boundary, and any subsequent
 * rings are inner rings (holes) — matching MapML.js's
 * `path.js#_coordinateToArrays` behaviour (first ring drives
 * `_parts[0].rings[0]`, further rings become `_parts[0].rings[i]`).
 *
 * Each ring is auto-closed per the GeoJSON spec (the polygon spec
 * requires each ring's first and last coordinate be identical).
 * Rings with fewer than three vertex pairs are skipped.
 */
function ringsFromPolygonElement(polygon: Element): [number, number][][] {
  const rings: [number, number][][] = [];
  for (const c of polygon.querySelectorAll('map-coordinates')) {
    const flat = parseCoordinatesText(c.textContent ?? '');
    if (flat.length < 6) continue;
    const ring = pairs(flat);
    const first = ring[0]!;
    const last = ring[ring.length - 1]!;
    if (first[0] !== last[0] || first[1] !== last[1]) ring.push([first[0], first[1]]);
    rings.push(ring);
  }
  return rings;
}

/**
 * Walk the children of a `<map-geometry>` element and produce the list
 * of typed {@link FeatureShape}s it contains. Recognised element names:
 * `<map-point>`, `<map-linestring>`, `<map-polygon>`,
 * `<map-multipoint>`, `<map-multilinestring>`, `<map-multipolygon>`.
 * All other children are ignored (with no warning — the author may
 * legitimately have commented-out or unsupported geometry mixed in).
 *
 * Structural conventions (match MapML.js's `Util.geojson2mapml` +
 * `path.js`): `<map-multipoint>` groups all points into (usually one)
 * `<map-coordinates>` child, `<map-multilinestring>` uses one
 * `<map-coordinates>` per line, `<map-multipolygon>` uses one
 * `<map-polygon>` per polygon (each with its own `<map-coordinates>`).
 */
export function shapesFromGeometry(geometry: Element): FeatureShape[] {
  return shapesFromGeometryWithSource(geometry).map((entry) => entry.shape);
}

/**
 * Same DOM walk as {@link shapesFromGeometry}, but also returns the
 * source element each shape came from and (when present) the nearest
 * enclosing `<map-a>` wrapper.
 *
 * The `source` element is the direct-descendant `<map-polygon>` /
 * `<map-linestring>` / `<map-multipoint>` / … under `<map-geometry>` —
 * the node MapML.js authors historically decorate with a `class`
 * attribute for CSS styling (Leaflet renders one SVG element per
 * geometry child and copies the `class` onto it). `<map-style>`
 * compilation reads the class from these source elements so a
 * `<map-polygon class="a">` under a `<map-feature>` picks up
 * `.a { fill: red }` rules, matching MapML.js behaviour.
 *
 * `<map-a>` / `<map-span>` wrappers around a shape are unwrapped —
 * the shape is emitted at the same "slot" as if the wrapper wasn't
 * there. When the shape sits under one or more `<map-a>` wrappers,
 * the *innermost* one is returned as `linkWrapper` so callers can
 * lift its `href` / `target` / `type` / `inplace` attributes into the
 * emitted GeoJSON feature's properties (MapML.js's `_convertWrappers`
 * behaves similarly — the innermost `<map-a>` on the wrapper stack
 * wins). MapML.js's rendered SVG binds click / keyboard handlers on
 * whichever anchor the mouse actually hit; our per-feature click
 * granularity doesn't distinguish sub-parts today, so innermost-wins
 * is the closest single-link approximation.
 *
 * `<map-geometrycollection>` is also unwrapped so a `<map-a>` around
 * a whole collection lifts a link onto every emitted shape inside it,
 * and shapes at the top level of a collection contribute individually.
 */
export function shapesFromGeometryWithSource(
  geometry: Element
): Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }> {
  const out: Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }> = [];
  visitShapeCandidates(geometry, null, out);
  return out;
}

/**
 * Walk `parent`'s children collecting recognised shape elements.
 * When a child is a `<map-a>` / `<map-span>` / `<map-geometrycollection>`
 * wrapper, recurse into it — inheriting the innermost `<map-a>` seen
 * along the way as the shape's `linkWrapper`. All other unrecognised
 * elements (comments, whitespace-only text, unknown tags) are
 * silently skipped, matching MapML.js's forgiving `_convertMarkup`
 * pass.
 */
function visitShapeCandidates(
  parent: Element,
  currentLink: Element | null,
  out: Array<{ shape: FeatureShape; source: Element; linkWrapper: Element | null }>
): void {
  for (const child of Array.from(parent.children)) {
    const tag = child.tagName.toLowerCase();
    if (tag === 'map-a') {
      // Innermost wrapper wins — MapML.js semantics for nested
      // `<map-a>` (parent + inplace child in `linkTypes.html`).
      visitShapeCandidates(child, child, out);
      continue;
    }
    if (tag === 'map-span' || tag === 'map-geometrycollection') {
      // `<map-span>` is a class-annotation wrapper; `<map-geometrycollection>`
      // groups sibling geometries. Neither carries a link on its own,
      // so `currentLink` is preserved through the recursion.
      visitShapeCandidates(child, currentLink, out);
      continue;
    }
    const shape = shapeFromElement(child, tag);
    if (shape !== null) {
      out.push({ shape, source: child, linkWrapper: currentLink });
    }
  }
}

/**
 * Turn a single recognised shape element (`<map-point>`,
 * `<map-linestring>`, `<map-polygon>`, or one of the `<map-multi*>`
 * flavours) into a typed {@link FeatureShape}. Returns `null` for
 * unrecognised tags or degenerate coordinate sets (fewer vertices
 * than the type requires).
 */
function shapeFromElement(el: Element, tag: string): FeatureShape | null {
  if (tag === 'map-point' || tag === 'map-linestring' || tag === 'map-multipoint') {
    const flat: number[] = [];
    for (const c of el.querySelectorAll('map-coordinates')) {
      flat.push(...parseCoordinatesText(c.textContent ?? ''));
    }
    if (flat.length < 2) return null;
    if (tag === 'map-point') {
      return { kind: 'Point', coordinates: [flat[0]!, flat[1]!] };
    }
    if (tag === 'map-linestring') {
      if (flat.length < 4) return null;
      return { kind: 'LineString', coordinates: pairs(flat) };
    }
    // map-multipoint: every pair is one point.
    return { kind: 'MultiPoint', coordinates: pairs(flat) };
  }
  if (tag === 'map-polygon') {
    const rings = ringsFromPolygonElement(el);
    if (rings.length === 0) return null;
    return { kind: 'Polygon', coordinates: rings };
  }
  if (tag === 'map-multilinestring') {
    const lines: [number, number][][] = [];
    for (const c of el.querySelectorAll('map-coordinates')) {
      const line = pairs(parseCoordinatesText(c.textContent ?? ''));
      if (line.length >= 2) lines.push(line);
    }
    if (lines.length === 0) return null;
    return { kind: 'MultiLineString', coordinates: lines };
  }
  if (tag === 'map-multipolygon') {
    const polys: [number, number][][][] = [];
    // Iterate direct <map-polygon> children so nested geometries in
    // future authoring don't collapse into this one.
    for (const poly of Array.from(el.children)) {
      if (poly.tagName.toLowerCase() !== 'map-polygon') continue;
      const rings = ringsFromPolygonElement(poly);
      if (rings.length === 0) continue;
      polys.push(rings);
    }
    if (polys.length === 0) return null;
    return { kind: 'MultiPolygon', coordinates: polys };
  }
  return null;
}

/**
 * Convert a source-CS pair to GCRS `[lon, lat]`. For `pcrs`, only
 * OSMTILE / GLOBE are supported today; other projections return the
 * PCRS pair unchanged (the caller has already warned via
 * `warnIfBadProjection`, and the numeric output is at worst visibly wrong,
 * not corrupting).
 */
function toGcrsPoint(
  x: number,
  y: number,
  cs: FeatureCS,
  projection: MapmlProjection
): [number, number] {
  if (cs === 'gcrs') return [x, y];
  // OSMTILE and GLOBE both use the Web Mercator tile pyramid; any
  // future projection lands its own PCRS transform here.
  void projection;
  return osmtilePcrsToGcrs(x, y);
}

/**
 * Convert typed shapes to GeoJSON `Feature`s in GCRS (WGS84 lon/lat).
 * The `properties` argument is copied verbatim onto every emitted
 * feature (typically `{ caption }` from `<map-featurecaption>`).
 */
export function shapesToGeoJson(
  shapes: readonly FeatureShape[],
  cs: FeatureCS,
  projection: MapmlProjection,
  properties: Record<string, unknown> = {}
): GeoJSON.Feature[] {
  const out: GeoJSON.Feature[] = [];
  for (const s of shapes) {
    if (s.kind === 'Point') {
      const [x, y] = s.coordinates;
      out.push({
        type: 'Feature',
        geometry: { type: 'Point', coordinates: toGcrsPoint(x, y, cs, projection) },
        properties: { ...properties }
      });
    } else if (s.kind === 'LineString') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'LineString',
          coordinates: s.coordinates.map(([x, y]) => toGcrsPoint(x, y, cs, projection))
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'Polygon') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'Polygon',
          coordinates: s.coordinates.map((ring) =>
            ring.map(([x, y]) => toGcrsPoint(x, y, cs, projection))
          )
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'MultiPoint') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiPoint',
          coordinates: s.coordinates.map(([x, y]) => toGcrsPoint(x, y, cs, projection))
        },
        properties: { ...properties }
      });
    } else if (s.kind === 'MultiLineString') {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiLineString',
          coordinates: s.coordinates.map((line) =>
            line.map(([x, y]) => toGcrsPoint(x, y, cs, projection))
          )
        },
        properties: { ...properties }
      });
    } else {
      out.push({
        type: 'Feature',
        geometry: {
          type: 'MultiPolygon',
          coordinates: s.coordinates.map((poly) =>
            poly.map((ring) => ring.map(([x, y]) => toGcrsPoint(x, y, cs, projection)))
          )
        },
        properties: { ...properties }
      });
    }
  }
  return out;
}

/**
 * One contiguous boundary run of a shape, split at `<map-span>`
 * boundaries. `className` is the span's `class` attribute for a
 * span-wrapped run, or `null` for a bare-text run (which inherits the
 * geometry's own class). Coordinates are in GCRS `[lon, lat]`.
 */
export interface BoundarySegment {
  coordinates: [number, number][];
  className: string | null;
}

/** Whether any `<map-coordinates>` inside `el` wraps a `<map-span>`. */
export function elementHasCoordinateSpans(el: Element): boolean {
  return el.querySelector('map-coordinates map-span') !== null;
}

/**
 * Extract a shape's boundary as an ordered list of {@link BoundarySegment}s,
 * preserving the `<map-span class="…">` annotations GeoServer uses to
 * mark tile-clip edges. Each `<map-coordinates>` under `el` is walked
 * child-node by child-node: text runs become `className: null`
 * segments (real boundary, stroked with the geometry's own class),
 * `<map-span>` runs become `className: <span class>` segments (a
 * `.bbox { display:none }` rule then hides the tile-edge runs).
 *
 * MapLibre can't per-segment-style one geometry's outline, so the
 * caller emits these as separate `LineString` features for the stroke
 * while the polygon geometry itself carries only the fill. Returns
 * `[]` when `el` has no spans (caller keeps the whole-geometry stroke).
 */
export function boundarySegmentsFromElement(
  el: Element,
  cs: FeatureCS,
  projection: MapmlProjection
): BoundarySegment[] {
  const segments: BoundarySegment[] = [];
  const toGcrs = (flat: number[], className: string | null): void => {
    const pts = pairs(flat);
    if (pts.length < 2) return;
    segments.push({
      coordinates: pts.map(([x, y]) => toGcrsPoint(x, y, cs, projection)),
      className
    });
  };
  for (const coords of el.querySelectorAll('map-coordinates')) {
    let textRun = '';
    const flushText = (): void => {
      const flat = parseCoordinatesText(textRun);
      textRun = '';
      toGcrs(flat, null);
    };
    for (const node of Array.from(coords.childNodes)) {
      if (node.nodeType === node.ELEMENT_NODE) {
        const elNode = node as Element;
        if (elNode.tagName.toLowerCase() === 'map-span') {
          // A span run is its own segment; flush the text accumulated
          // before it so document order is preserved.
          flushText();
          toGcrs(
            parseCoordinatesText(elNode.textContent ?? ''),
            elNode.getAttribute('class')
          );
          continue;
        }
      }
      textRun += ` ${node.textContent ?? ''}`;
    }
    flushText();
  }
  return segments;
}

/**
 * Compute the PCRS bounding box that covers every coordinate in the
 * given shapes. Returns `null` when no coordinates were seen. For
 * `gcrs` inputs the PCRS box is derived by projecting each vertex; for
 * `pcrs` inputs the box is the min/max of the raw values.
 *
 * The result mirrors the shape MapML.js's `<map-feature>.extent`
 * ultimately produces via `Util.boundsToPCRSBounds` +
 * `Util._convertAndFormatPCRS`.
 */
export function shapesToPcrsBounds(
  shapes: readonly FeatureShape[],
  cs: FeatureCS,
  projection: MapmlProjection
): PcrsBounds | null {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  const visit = (x: number, y: number): void => {
    let px: number;
    let py: number;
    if (cs === 'gcrs') {
      [px, py] = osmtileGcrsToPcrs(x, y);
    } else {
      // OSMTILE / GLOBE PCRS is native meters; no per-projection
      // dispatch needed until non-Mercator projections land.
      void projection;
      px = x;
      py = y;
    }
    if (px < minX) minX = px;
    if (py < minY) minY = py;
    if (px > maxX) maxX = px;
    if (py > maxY) maxY = py;
  };
  for (const s of shapes) {
    if (s.kind === 'Point') {
      const [x, y] = s.coordinates;
      visit(x, y);
    } else if (s.kind === 'LineString' || s.kind === 'MultiPoint') {
      for (const [x, y] of s.coordinates) visit(x, y);
    } else if (s.kind === 'MultiLineString') {
      for (const line of s.coordinates) for (const [x, y] of line) visit(x, y);
    } else if (s.kind === 'Polygon') {
      for (const ring of s.coordinates) for (const [x, y] of ring) visit(x, y);
    } else {
      for (const poly of s.coordinates)
        for (const ring of poly) for (const [x, y] of ring) visit(x, y);
    }
  }
  if (!Number.isFinite(minX)) return null;
  return { min: [minX, minY], max: [maxX, maxY] };
}
