/**
 * TypeScript port of MapML.js's `Util.mapml2geojson`
 * (`../MapML.js/src/mapml/utils/Util.js`) — reverse direction of
 * {@link geojson2mapml}. Takes a `<map-layer>` (or `<map-feature>`)
 * element and returns a plain GeoJSON object.
 *
 * Design goals — MapML.js's output shape mirrored field-for-field so
 * pages that call `M.mapml2geojson(...)` on either implementation
 * receive identical `FeatureCollection` documents:
 *
 *   ```ts
 *   {
 *     title: 'Layer Label',
 *     type: 'FeatureCollection',
 *     bbox?: [minLon, minLat, maxLon, maxLat],   // from <map-meta name="extent">
 *     features: [
 *       { type: 'Feature',
 *         geometry: { type: 'Point', coordinates: [...] },
 *         properties: { key: value, ... } }
 *     ]
 *   }
 *   ```
 *
 * Coordinate systems:
 *  - Each `<map-feature>` is read at its effective `cs`
 *    (`<map-geometry cs>` \u2192 parent layer's `<map-meta name="cs">`
 *    \u2192 `gcrs`) via {@link resolveFeatureCs}.
 *  - `options.transform` (default `true`) reprojects coordinates to
 *    GCRS (WGS84 `[lon, lat]`). For `gcrs` inputs this is a passthrough;
 *    for `pcrs` inputs on OSMTILE / GLOBE it's the closed-form Web
 *    Mercator PCRS\u2192GCRS transform ({@link osmtilePcrsToGcrs}).
 *  - `options.transform === false` emits coordinates verbatim in the
 *    source CS. Matches MapML.js's "author knows what they're doing"
 *    escape hatch.
 *
 * `<map-properties>` handling (mirrors MapML.js `Util.mapml2geojson`
 * per-feature branches):
 *  - No `<map-properties>` \u2192 `properties: null`.
 *  - `options.propertyFunction(el)` present \u2192 its return value is
 *    assigned as `properties`.
 *  - `<map-properties>` contains a `<table>` \u2192 parsed via
 *    {@link table2properties} (drops `<thead>`, then key/value from
 *    each `<tr>`'s first two cells).
 *  - Otherwise \u2192 `{ prop0: <innerHTML with all HTML tags
 *    stripped> }`. For per-feature `mapml2geojson` (`MapFeature.mapml2geojson`),
 *    whitespace is also collapsed \u2014 upstream quirk faithfully
 *    reproduced.
 *
 * Deliberately renderer-agnostic (no MapLibre imports); safe to import
 * from tests, tools, or the paste pipeline.
 */

import type { MapmlProjection } from './projection';
import { osmtilePcrsToGcrs } from './crs';
import {
  parseCoordinatesText,
  parseGeometryCS,
  type FeatureCS
} from './feature';
import { parseExtentMeta } from './mapMeta';

/** Options accepted by every `mapml2geojson` entry point. */
export interface Mapml2GeojsonOptions {
  /**
   * Callback that maps a `<map-properties>` element to a plain JSON
   * object used as the emitted feature's `properties`. Overrides the
   * default table / stripped-innerHTML paths.
   */
  propertyFunction?: (propertiesEl: Element) => Record<string, unknown> | null;
  /**
   * When `true` (default), coordinates are reprojected to GCRS
   * (`[lon, lat]`). When `false`, coordinates are emitted verbatim
   * in the source `cs`.
   */
  transform?: boolean;
  /**
   * Projection used to interpret `pcrs` coordinates. Optional \u2014
   * defaults to the parent viewer's `projection` attribute, or
   * `OSMTILE` when the layer isn't in the DOM yet. Only consulted
   * when a feature's effective `cs` is `pcrs`.
   */
  projection?: MapmlProjection;
}

/** GeoJSON output shape mirrored from MapML.js. */
export interface Mapml2GeojsonFeatureCollection {
  title: string;
  type: 'FeatureCollection';
  bbox?: [number, number, number, number];
  features: Mapml2GeojsonFeature[];
}

export interface Mapml2GeojsonFeature {
  type: 'Feature';
  geometry: Mapml2GeojsonGeometry | Record<string, never>;
  properties: Record<string, unknown> | null;
}

export type Mapml2GeojsonGeometry =
  | { type: 'Point'; coordinates: [number, number] }
  | { type: 'LineString'; coordinates: [number, number][] }
  | { type: 'Polygon'; coordinates: [number, number][][] }
  | { type: 'MultiPoint'; coordinates: [number, number][] }
  | { type: 'MultiLineString'; coordinates: [number, number][][] }
  | { type: 'MultiPolygon'; coordinates: [number, number][][][] }
  | { type: 'GeometryCollection'; geometries: Mapml2GeojsonGeometry[] };

/**
 * Convert a `<map-layer>` element to a GeoJSON `FeatureCollection`.
 *
 * Mirrors MapML.js's `Util.mapml2geojson`. Reads `<map-meta name="extent">`
 * for the top-level `bbox` and every direct-descendant `<map-feature>`
 * for the features array.
 */
export function mapml2geojson(
  layer: Element,
  options: Mapml2GeojsonOptions = {}
): Mapml2GeojsonFeatureCollection {
  const layerCs = parentLayerCs(layer);
  const projection = options.projection ?? viewerProjection(layer);
  const out: Mapml2GeojsonFeatureCollection = {
    title: layer.getAttribute('label') ?? '',
    type: 'FeatureCollection',
    features: []
  };
  const bbox = readLayerBbox(layer);
  if (bbox !== null) out.bbox = bbox;

  const features = layer.querySelectorAll(':scope > map-feature');
  for (const f of features) {
    out.features.push(featureToGeoJson(f, options, layerCs, projection));
  }
  return out;
}

/**
 * Convert a single `<map-feature>` to a GeoJSON `Feature`.
 *
 * `layerCsFallback` supplies the effective `cs` when the feature's own
 * geometry doesn't set one \u2014 usually the owning layer's
 * `<map-meta name="cs">`. Exposed so `MapFeature.mapml2geojson` can
 * short-circuit the layer lookup.
 */
export function featureToGeoJson(
  featureEl: Element,
  options: Mapml2GeojsonOptions = {},
  layerCsFallback: FeatureCS | null = null,
  projectionOverride?: MapmlProjection
): Mapml2GeojsonFeature {
  const transform = options.transform !== false;
  const projection =
    options.projection ?? projectionOverride ?? viewerProjection(featureEl);

  const cs = featureCs(featureEl, layerCsFallback);
  const properties = extractProperties(featureEl, options);

  const geometryEl = featureEl.querySelector(':scope > map-geometry');
  const geometry: Mapml2GeojsonGeometry | Record<string, never> =
    geometryEl !== null
      ? geometryFromElement(geometryEl, cs, projection, transform)
      : {};

  return {
    type: 'Feature',
    geometry,
    properties
  };
}

// ---------------------------------------------------------------------
// Geometry
// ---------------------------------------------------------------------

/**
 * Emit GeoJSON geometry from a `<map-geometry>` element.
 *
 * A `<map-geometrycollection>` child expands to a
 * `GeometryCollection`; otherwise every direct-descendant
 * `<map-point>` / `<map-linestring>` / \u2026 child produces one
 * geometry. When multiple non-collection shapes are present, only the
 * first is emitted (matches MapML.js's `feature.querySelector('map-geometry').firstElementChild`).
 */
function geometryFromElement(
  geometryEl: Element,
  cs: FeatureCS,
  projection: MapmlProjection,
  transform: boolean
): Mapml2GeojsonGeometry | Record<string, never> {
  const collection = geometryEl.querySelector(':scope > map-geometrycollection');
  if (collection !== null) {
    const geometries: Mapml2GeojsonGeometry[] = [];
    for (const child of Array.from(collection.children)) {
      // `<map-a>` / `<map-span>` wrappers unwrap into their contained
      // geometry \u2014 matches MapML.js's `[...g.querySelectorAll(...)]`
      // replace-with-children pass.
      const shapes = unwrapShapeElements(child);
      for (const shape of shapes) {
        const g = shapeElementToGeometry(shape, cs, projection, transform);
        if (g !== null) geometries.push(g);
      }
    }
    return { type: 'GeometryCollection', geometries };
  }

  // First non-wrapper shape child.
  const first = firstShapeChild(geometryEl);
  if (first === null) return {};
  return shapeElementToGeometry(first, cs, projection, transform) ?? {};
}

/** Recognised primitive geometry-shape element names. */
const SHAPE_TAGS = new Set([
  'map-point',
  'map-linestring',
  'map-polygon',
  'map-multipoint',
  'map-multilinestring',
  'map-multipolygon'
]);

/**
 * Walk `<map-a>` / `<map-span>` wrappers and return the enclosed
 * shape element(s). MapML.js allows a hyperlink or class-span wrap
 * around a geometry so authors can annotate; the serialiser must
 * see the enclosed geometry directly.
 */
function unwrapShapeElements(el: Element): Element[] {
  const tag = el.tagName.toLowerCase();
  if (tag === 'map-span' || tag === 'map-a') {
    const out: Element[] = [];
    for (const child of Array.from(el.children)) {
      out.push(...unwrapShapeElements(child));
    }
    return out;
  }
  if (SHAPE_TAGS.has(tag)) return [el];
  return [];
}

/** First direct-descendant shape element (unwrapping `map-a` / `map-span`). */
function firstShapeChild(parent: Element): Element | null {
  for (const child of Array.from(parent.children)) {
    const unwrapped = unwrapShapeElements(child);
    if (unwrapped.length > 0) return unwrapped[0]!;
  }
  return null;
}

/** Convert one shape element to a GeoJSON geometry. */
function shapeElementToGeometry(
  el: Element,
  cs: FeatureCS,
  projection: MapmlProjection,
  transform: boolean
): Mapml2GeojsonGeometry | null {
  const project = (x: number, y: number): [number, number] =>
    projectPoint(x, y, cs, projection, transform);

  const tag = el.tagName.toLowerCase();
  switch (tag) {
    case 'map-point': {
      const flat = readCoordinates(el);
      if (flat.length < 2) return null;
      return { type: 'Point', coordinates: project(flat[0]!, flat[1]!) };
    }
    case 'map-linestring': {
      const line = readCoordinatePairs(el);
      if (line.length === 0) return null;
      return {
        type: 'LineString',
        coordinates: line.map(([x, y]) => project(x, y))
      };
    }
    case 'map-polygon': {
      const rings = readPolygonRings(el, project);
      if (rings.length === 0) return null;
      return { type: 'Polygon', coordinates: rings };
    }
    case 'map-multipoint': {
      const flat = readCoordinatePairs(el);
      if (flat.length === 0) return null;
      return {
        type: 'MultiPoint',
        coordinates: flat.map(([x, y]) => project(x, y))
      };
    }
    case 'map-multilinestring': {
      const lines: [number, number][][] = [];
      for (const c of el.querySelectorAll(':scope > map-coordinates')) {
        const line = pairs(parseCoordinatesText(c.textContent ?? ''));
        if (line.length === 0) continue;
        lines.push(line.map(([x, y]) => project(x, y)));
      }
      if (lines.length === 0) return null;
      return { type: 'MultiLineString', coordinates: lines };
    }
    case 'map-multipolygon': {
      const polys: [number, number][][][] = [];
      for (const p of el.querySelectorAll(':scope > map-polygon')) {
        const rings = readPolygonRings(p, project);
        if (rings.length === 0) continue;
        polys.push(rings);
      }
      if (polys.length === 0) return null;
      return { type: 'MultiPolygon', coordinates: polys };
    }
    default:
      return null;
  }
}

function readPolygonRings(
  polygon: Element,
  project: (x: number, y: number) => [number, number]
): [number, number][][] {
  const rings: [number, number][][] = [];
  for (const c of polygon.querySelectorAll(':scope > map-coordinates')) {
    const ring = pairs(parseCoordinatesText(c.textContent ?? ''));
    if (ring.length === 0) continue;
    rings.push(ring.map(([x, y]) => project(x, y)));
  }
  return rings;
}

function readCoordinates(el: Element): number[] {
  const flat: number[] = [];
  for (const c of el.querySelectorAll(':scope > map-coordinates')) {
    flat.push(...parseCoordinatesText(c.textContent ?? ''));
  }
  return flat;
}

function readCoordinatePairs(el: Element): [number, number][] {
  return pairs(readCoordinates(el));
}

function pairs(flat: readonly number[]): [number, number][] {
  const out: [number, number][] = [];
  for (let i = 0; i + 1 < flat.length; i += 2) {
    out.push([flat[i]!, flat[i + 1]!]);
  }
  return out;
}

/**
 * Reproject one `(x, y)` pair from source CS to output CS. When
 * `transform === false`, coordinates are emitted verbatim.
 */
function projectPoint(
  x: number,
  y: number,
  cs: FeatureCS,
  projection: MapmlProjection,
  transform: boolean
): [number, number] {
  if (!transform) return [x, y];
  if (cs === 'gcrs') return [x, y];
  // OSMTILE / GLOBE both use Web Mercator PCRS; other projections
  // land their own PCRS \u2192 GCRS transform here when proj4 arrives.
  void projection;
  return osmtilePcrsToGcrs(x, y);
}

// ---------------------------------------------------------------------
// Properties
// ---------------------------------------------------------------------

function extractProperties(
  featureEl: Element,
  options: Mapml2GeojsonOptions
): Record<string, unknown> | null {
  const propsEl = featureEl.querySelector(':scope > map-properties');
  if (propsEl === null) return null;
  if (typeof options.propertyFunction === 'function') {
    return options.propertyFunction(propsEl);
  }
  const table = propsEl.querySelector(':scope > table');
  if (table !== null) return table2properties(table);
  // Fallback: strip HTML tags. MapML.js's per-layer path preserves
  // whitespace, while the per-feature path (see MapFeature.mapml2geojson)
  // additionally collapses whitespace; layer-side matches upstream by
  // default.
  return {
    prop0: (propsEl.innerHTML ?? '').replace(/(<([^>]+)>)/gi, '')
  };
}

/**
 * Parse an HTML `<table>` into a `{ key: value }` record, mirroring
 * MapML.js's `Util._table2properties`.
 *
 * The `<thead>` (if present) is dropped; every remaining `<tr>` yields
 * one property whose key is the first cell's `innerHTML` and value the
 * second cell's `innerHTML`. Values remain HTML strings \u2014 same
 * quirk as upstream.
 */
export function table2properties(table: Element): Record<string, unknown> {
  // Clone so we don't mutate the source DOM when dropping the thead.
  const clone = table.cloneNode(true) as Element;
  const head = clone.querySelector(':scope > thead');
  if (head !== null) head.remove();
  const out: Record<string, unknown> = {};
  for (const tr of clone.querySelectorAll('tr')) {
    const cells = tr.querySelectorAll('th, td');
    if (cells.length < 2) continue;
    const key = cells[0]!.innerHTML;
    const value = cells[1]!.innerHTML;
    out[key] = value;
  }
  return out;
}

// ---------------------------------------------------------------------
// CS resolution + misc helpers
// ---------------------------------------------------------------------

/** Effective `cs` for a feature: geometry's `cs` attr \u2192 layer's `<map-meta name="cs">` \u2192 `gcrs`. */
function featureCs(featureEl: Element, layerCsFallback: FeatureCS | null): FeatureCS {
  const geom = featureEl.querySelector(':scope > map-geometry');
  const fromGeom = parseGeometryCS(geom?.getAttribute('cs') ?? null);
  if (fromGeom !== null) return fromGeom;
  if (layerCsFallback !== null) return layerCsFallback;
  return 'gcrs';
}

/** Read `<map-meta name="cs">` from the feature's owning `<map-layer>`. */
function parentLayerCs(layer: Element): FeatureCS | null {
  if (layer.tagName.toLowerCase() !== 'map-layer') return null;
  const meta = layer.querySelector(':scope > map-meta[name="cs"]');
  if (meta === null) return null;
  return parseGeometryCS(meta.getAttribute('content'));
}

/** Best-effort viewer projection lookup — walks up to the closest `<mapml-viewer>`. */
function viewerProjection(el: Element): MapmlProjection {
  const viewer = el.closest('mapml-viewer');
  const attr = viewer?.getAttribute('projection');
  if (attr === 'OSMTILE' || attr === 'WGS84' || attr === 'CBMTILE' || attr === 'APSTILE') {
    return attr as MapmlProjection;
  }
  return 'OSMTILE';
}

/**
 * Extract `bbox` from the first `<map-meta name="extent">` inside
 * `layer`. Returns `null` when absent or malformed. Order matches
 * MapML.js: `[top-left-longitude, top-left-latitude,
 * bottom-right-longitude, bottom-right-latitude]`.
 *
 * We reuse {@link parseExtentMeta}, which returns PCRS \u2014 but for
 * GCRS-authored extents (the common case) it just copies the pair
 * through. For PCRS/TCRS/TILEMATRIX metas we transform through
 * {@link osmtilePcrsToGcrs}, matching the "coords are lon/lat" shape
 * MapML.js emits. Non-OSMTILE PCRS falls back gracefully.
 */
function readLayerBbox(layer: Element): [number, number, number, number] | null {
  const meta = layer.querySelector(':scope > map-meta[name="extent"]');
  if (meta === null) return null;
  const content = meta.getAttribute('content');
  if (content === null) return null;
  const projection = viewerProjection(layer);
  const parsed = parseExtentMeta(content, projection);
  if (parsed === null) return null;
  // parseExtentMeta returns PCRS-normalised bounds. Convert corners
  // back to GCRS for the bbox array.
  const [minX, minY] = parsed.bounds.min;
  const [maxX, maxY] = parsed.bounds.max;
  // Check whether the meta looks like GCRS by testing the axis
  // keys directly \u2014 saves a needless round-trip when authors
  // wrote lon/lat straight into the meta.
  if (isGcrsExtentContent(content)) {
    // Extract keys directly for pixel-exact fidelity with the author's
    // input (parseExtentMeta rounds through PCRS on OSMTILE, which
    // introduces sub-meter drift).
    const map = parseKV(content);
    const tlLon = num(map['top-left-longitude']);
    const tlLat = num(map['top-left-latitude']);
    const brLon = num(map['bottom-right-longitude']);
    const brLat = num(map['bottom-right-latitude']);
    if (
      tlLon !== null && tlLat !== null && brLon !== null && brLat !== null
    ) {
      return [tlLon, tlLat, brLon, brLat];
    }
  }
  // PCRS / TCRS / TILEMATRIX \u2014 project corners to GCRS. Only
  // OSMTILE is exact today; other projections use OSMTILE math (the
  // viewer already warned) or the raw PCRS values.
  if (projection === 'OSMTILE') {
    const [tlLon, tlLat] = osmtilePcrsToGcrs(minX, maxY);
    const [brLon, brLat] = osmtilePcrsToGcrs(maxX, minY);
    return [tlLon, tlLat, brLon, brLat];
  }
  return [minX, maxY, maxX, minY];
}

function isGcrsExtentContent(content: string): boolean {
  return /top-left-longitude/i.test(content);
}

function parseKV(content: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const part of content.split(',')) {
    const eq = part.indexOf('=');
    if (eq < 0) continue;
    const k = part.slice(0, eq).trim();
    const v = part.slice(eq + 1).trim();
    if (k.length > 0) out[k] = v;
  }
  return out;
}

function num(v: string | undefined): number | null {
  if (v === undefined) return null;
  const n = Number.parseFloat(v);
  return Number.isFinite(n) ? n : null;
}
