import type { MapLayer } from '../elements/map-layer';
import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * Baked link data lifted from a `<map-a>` wrapper around a shape
 * inside a `<map-feature>`'s `<map-geometry>`. Rides along in the
 * emitted GeoJSON feature's `properties` so click / keyboard
 * activation paths can dispatch without a DOM crawl.
 */
export interface FeatureLinkProperties {
  /** Absolute or relative URL from the `<map-a href>` attribute. */
  linkHref: string;
  /** `_self` / `_blank` / `_parent` / `_top` — MapML.js parity. */
  linkTarget?: string;
  /** MIME type hint — e.g. `text/html`, `text/mapml`, `application/geo+json`. */
  linkType?: string;
  /** `<map-a inplace>` was present. */
  linkInplace?: boolean;
}

/**
 * Read the link properties baked into a GeoJSON feature's
 * `properties` object. Returns `null` when the properties don't
 * carry a `linkHref` (typical for a plain `<map-feature>` with no
 * `<map-a>` wrapper). Otherwise returns a normalised
 * {@link FeatureLinkProperties} object suitable for
 * {@link handleFeatureLink}.
 */
export function readFeatureLink(
  properties: Record<string, unknown> | null | undefined
): FeatureLinkProperties | null {
  if (!properties) return null;
  const href = properties.linkHref;
  if (typeof href !== 'string' || href === '') return null;
  const out: FeatureLinkProperties = { linkHref: href };
  const target = properties.linkTarget;
  if (typeof target === 'string' && target !== '') out.linkTarget = target;
  const type = properties.linkType;
  if (typeof type === 'string' && type !== '') out.linkType = type;
  if (properties.linkInplace === true) out.linkInplace = true;
  return out;
}

/**
 * Port of MapML.js's `Util._handleLink` (see
 * `../MapML.js/src/mapml/utils/Util.js`). Dispatches a `<map-a>`
 * feature-link activation to one of five behaviours based on the
 * link's `href` + `target` + `type`:
 *
 *   1. **URL-fragment-only pan / zoom** — `href` starts with `#` and
 *      encodes `#zoom,lon,lat` (or `#zoom,lon,lat,anything`). The
 *      viewer pans + zooms; no layer is added.
 *   2. **`_top`** — `window.location.href = url`. Navigates the
 *      whole browsing context.
 *   3. **`_blank` + `type="text/html"`** — `window.open(url)`. New
 *      tab, HTML content.
 *   4. **`_blank` (non-html) or default (`_self`) or unrecognised** —
 *      append a new `<map-layer src=… checked>` to the viewer.
 *      For default (`_self`), the owning `<map-layer>` is replaced
 *      in-place (`insertAdjacentElement('beforebegin', …)` + remove).
 *   5. **`_parent`** — remove every sibling `<map-layer>` (other
 *      than the owning layer itself) and then replace the owning
 *      layer with the new one.
 *
 * MapML.js additionally sets a `link.visited` flag and paints the
 * source path purple after activation; that visual state is not
 * ported here yet (see `<map-a>` element docblock for deferred
 * items).
 *
 * `owningLayer` is the `<map-layer>` that contains the feature that
 * carries the link. Used both to locate the layer whose spot the new
 * layer should take (`_self`), and to exempt it from the `_parent`
 * clean-up sweep so the traversal doesn't tear down the layer it
 * launched from mid-flight.
 *
 * The `href` is resolved relative to the viewer's document (`new URL(href, location.href)`)
 * before being handed to `window.open` / `window.location` /
 * `<map-layer src>` — matches MapML.js, where the browser's own
 * anchor-URL resolution kicks in via the `text/html` fast paths
 * and where `<map-layer src>` triggers a `fetch()` that itself
 * resolves the URL against the document base.
 */
export function handleFeatureLink(
  viewer: MapmlViewer,
  owningLayer: MapLayer | null,
  link: FeatureLinkProperties
): void {
  const href = link.linkHref;
  const type = link.linkType ?? '';
  // Fragment-only URLs (`#z,lon,lat`) always pan + zoom regardless
  // of `target` — MapML.js's `_handleLink` sets `justPan` in this
  // branch and short-circuits the layer-append cascade.
  const hashOnly = href.startsWith('#');
  if (hashOnly) {
    const view = parseHashView(href);
    if (view !== null) {
      viewer.zoomTo(view.lat, view.lng, view.zoom);
      viewer.renderer.map?.getCanvas().focus();
    }
    return;
  }

  // Normalise target with MapML.js's rule: for `text/html` links
  // (i.e. classic HTML pages), any target other than `_blank` is
  // treated as `_top` (whole-window navigation) because a
  // `<map-layer src=".html">` wouldn't render as MapML anyway.
  let target = link.linkTarget ?? '_self';
  if (type === 'text/html' && target !== '_blank') target = '_top';

  // A `<map-a href>` is author-untrusted (a pasted/loaded
  // `<map-feature>` is inserted verbatim). Every branch below
  // navigates with `href` — `window.location.href`, `window.open`,
  // or a `<map-layer src>` — so a `javascript:` href would execute
  // on click. Reject anything that doesn't resolve to http(s).
  // (Fragment-only links were already handled and returned above.)
  let resolvedProtocol: string | null;
  try {
    resolvedProtocol = new URL(href, document.baseURI).protocol;
  } catch {
    resolvedProtocol = null;
  }
  if (resolvedProtocol !== 'http:' && resolvedProtocol !== 'https:') {
    console.warn(
      `MapML: ignoring map-a link with unsupported/unsafe URL: ${href}`
    );
    return;
  }

  if (target === '_top') {
    window.location.href = href;
    return;
  }
  if (target === '_blank' && type === 'text/html') {
    window.open(href);
    return;
  }

  // Layer-append variants: `_blank` (non-html), `_parent`, and
  // `_self` all build a new `<map-layer src=… checked>` and
  // insert it — differing only in where the new layer lands and
  // whether other layers are removed first.
  const doc = viewer.ownerDocument ?? document;
  const layer = doc.createElement('map-layer');
  layer.setAttribute('src', href);
  layer.setAttribute('checked', '');

  if (target === '_blank') {
    // Non-html `_blank` → new `<map-layer>` at the end of the
    // viewer's layer list. Existing layers stay put.
    viewer.appendChild(layer);
    return;
  }

  if (target === '_parent') {
    // Remove every sibling `<map-layer>` except the owning layer,
    // then replace the owning layer with the new one. `_parent`
    // is the "swap the whole map" traversal.
    for (const other of Array.from(
      viewer.querySelectorAll(':scope > map-layer')
    )) {
      if (other !== owningLayer) other.remove();
    }
    if (owningLayer && owningLayer.isConnected) {
      owningLayer.insertAdjacentElement('beforebegin', layer);
      owningLayer.remove();
    } else {
      viewer.appendChild(layer);
    }
    return;
  }

  // Default (`_self`, empty, unrecognised): replace the owning
  // layer in-place. Matches MapML.js's `default:` branch, which
  // inserts the new layer immediately before the old one and then
  // removes the old.
  if (owningLayer && owningLayer.isConnected) {
    owningLayer.insertAdjacentElement('beforebegin', layer);
    owningLayer.remove();
  } else {
    viewer.appendChild(layer);
  }
}

/**
 * Parse a `#zoom,lng,lat[,anything]` URL fragment (MapML.js's
 * "pan / zoom only" `<map-a>` shape). Returns `null` for
 * unparseable / incomplete fragments so the caller can fall through
 * to a plain no-op instead of jumping to `(0, 0, 0)`.
 */
function parseHashView(
  href: string
): { zoom: number; lng: number; lat: number } | null {
  // MapML.js's `_handleLink` accepts `#z,lon,lat` and also
  // treats `''` / missing pieces as `0` — we mirror that here so
  // pages using the truncated shape (`#zoom,lon`) still pan
  // meaningfully.
  const raw = href.startsWith('#') ? href.slice(1) : href;
  if (raw === '') return null;
  const parts = raw.split(',');
  const zoom = Number(parts[0] ?? 0);
  const lng = Number(parts[1] ?? 0);
  const lat = Number(parts[2] ?? 0);
  if (!Number.isFinite(zoom) || !Number.isFinite(lng) || !Number.isFinite(lat)) {
    return null;
  }
  return { zoom, lng, lat };
}
