import * as maplibregl from 'maplibre-gl';
import { osmtilePcrsToGcrs, osmtileTilematrixToPcrs } from '../core/crs';
import type { TileCorner } from '../core/template';

/**
 * Shared WMS-per-tile plumbing extracted from `MapLibreRenderer.ts`
 * so both the transitional id-keyed `addWmsTileLayer` adapter and the
 * new `MapLibreWmsTileHandle` (in `MapLibreLayers.ts`) can share the
 * one module-level registry + protocol handler.
 *
 * The registry is module-scoped rather than instance-scoped because
 * `maplibregl.addProtocol` is a global registration — two
 * `<mapml-viewer>`s on the same page both talk to the same handler,
 * so their per-layer entries live in the same table. Keys stay
 * unique because layer ids come from a monotonic counter in
 * `<map-link>` land.
 */

/** Scheme name for the WMS-per-tile protocol handler. */
export const MAPML_WMS_TILE_PROTOCOL = 'mapmlwmstile';

export interface WmsTileRegistryEntry {
  templateUrl: string;
  cornerMap: Record<string, TileCorner>;
  unitsForCorners: 'pcrs' | 'gcrs';
  scheme: 'xyz' | 'tms';
  tileSize: number;
}

export const mapmlWmsTileRegistry = new Map<string, WmsTileRegistryEntry>();

/**
 * Whether {@link ensureMapmlWmsTileProtocol} has already registered
 * the shared handler with MapLibre. `addProtocol` throws on
 * double-register, so gate on this flag rather than trying to look
 * up the handler after the fact.
 */
let mapmlWmsTileProtocolRegistered = false;

/**
 * Register the shared `mapmlwmstile://` protocol handler on first
 * use. Idempotent — subsequent calls short-circuit. The handler
 * parses `mapmlwmstile://<encoded-layer-id>/<z>/<x>/<y>` URLs
 * (MapLibre substitutes `{z}`/`{x}`/`{y}` for us before invoking
 * the handler), looks up the registered template, computes the
 * tile's PCRS/GCRS bbox, substitutes the corner tokens, and fetches
 * the resulting URL. Returns the response body as an ArrayBuffer
 * so MapLibre's raster tile decoder can consume it directly.
 */
export function ensureMapmlWmsTileProtocol(): void {
  if (mapmlWmsTileProtocolRegistered) return;
  mapmlWmsTileProtocolRegistered = true;
  maplibregl.addProtocol(MAPML_WMS_TILE_PROTOCOL, async (params, abortController) => {
    const parsed = parseWmsTileUrl(params.url);
    if (parsed === null) {
      throw new Error(`Malformed ${MAPML_WMS_TILE_PROTOCOL}:// URL: ${params.url}`);
    }
    const entry = mapmlWmsTileRegistry.get(parsed.id);
    if (!entry) {
      // Layer was removed (e.g. layer disabled / extent turned off)
      // between the time MapLibre queued the request and now. Return
      // an empty response so the raster source drops the tile
      // silently rather than reporting a network error.
      return { data: new ArrayBuffer(0) };
    }
    const targetUrl = substituteWmsTileCorners(
      entry.templateUrl,
      entry.cornerMap,
      entry.unitsForCorners,
      entry.scheme,
      parsed.z,
      parsed.x,
      parsed.y
    );
    const init: RequestInit = { signal: abortController.signal };
    if (params.credentials !== undefined) {
      init.credentials = params.credentials as RequestCredentials;
    }
    const response = await fetch(targetUrl, init);
    if (!response.ok) {
      throw new Error(
        `mapmlwmstile fetch ${response.status} ${response.statusText}: ${targetUrl}`
      );
    }
    const data = await response.arrayBuffer();
    return { data };
  });
}

function parseWmsTileUrl(
  url: string
): { id: string; z: number; x: number; y: number } | null {
  const prefix = `${MAPML_WMS_TILE_PROTOCOL}://`;
  if (!url.startsWith(prefix)) return null;
  const rest = url.slice(prefix.length);
  const parts = rest.split('/');
  if (parts.length !== 4) return null;
  const [encId, zStr, xStr, yStr] = parts as [string, string, string, string];
  const z = Number(zStr);
  const x = Number(xStr);
  const y = Number(yStr);
  if (!Number.isFinite(z) || !Number.isFinite(x) || !Number.isFinite(y)) return null;
  return { id: decodeURIComponent(encId), z, x, y };
}

/**
 * Compute tile `(z,x,y)`'s bbox corners and substitute them into a
 * template carrying `{token}` corner placeholders. Shared by the
 * `mapmlwmstile://` raster handler and the `mapmlmetatile://`
 * text/mapml handler (a WMS-bbox `rel="tile" type="text/mapml"` link
 * builds its per-tile document URL the same way a raster tile builds
 * its image URL).
 */
export function substituteWmsTileCorners(
  templateUrl: string,
  cornerMap: Record<string, TileCorner>,
  unitsForCorners: 'pcrs' | 'gcrs',
  scheme: 'xyz' | 'tms',
  z: number,
  x: number,
  y: number
): string {
  let row = y;
  if (scheme === 'tms') {
    const n = Math.pow(2, z);
    row = n - 1 - y;
  }
  const [westPcrs, northPcrs] = osmtileTilematrixToPcrs(x, row, z);
  const [eastPcrs, southPcrs] = osmtileTilematrixToPcrs(x + 1, row + 1, z);

  let west: number;
  let east: number;
  let north: number;
  let south: number;
  if (unitsForCorners === 'gcrs') {
    [west, north] = osmtilePcrsToGcrs(westPcrs, northPcrs);
    [east, south] = osmtilePcrsToGcrs(eastPcrs, southPcrs);
  } else {
    west = westPcrs;
    east = eastPcrs;
    north = northPcrs;
    south = southPcrs;
  }

  let url = templateUrl;
  for (const [token, corner] of Object.entries(cornerMap)) {
    const value =
      corner === 'west' ? west
      : corner === 'east' ? east
      : corner === 'north' ? north
      : south;
    url = url.split(`{${token}}`).join(String(value));
  }
  return url;
}
