/**
 * Serialiser + paste helpers for the map-level context menu's
 * `Copy \u2192 Map / Extent / Location` submenu and its `Paste` item.
 *
 * Behaviour and output shape mirror MapML.js's
 * `src/mapml/handlers/ContextMenu.js` (`_copyMapML`, `_copyExtent`,
 * `_copyLocation` + its `_copyGCRS` / `_copyPCRS` / `_copyTCRS` /
 * `_copyTileMatrix` / `_copyMap` / `_copyTile` family) and its
 * `_paste` + `Util._pasteLayer` pair, so pages copied out of one
 * implementation can round-trip through the clipboard into the other.
 *
 * OSMTILE-only today: the TCRS / TILEMATRIX branches use the
 * closed-form Web Mercator transforms from {@link src/core/crs.ts},
 * matching MapML.js's `_map.project` / `crs.transformation.untransform`
 * output for `EPSG:3857`. Non-OSMTILE projections fall back to GCRS
 * with a console warning \u2014 proj4 + the per-projection tables are
 * the next lift (see [TODO.md](../../TODO.md)).
 */

import {
  OSMTILE_TILE_SIZE,
  osmtileGcrsToPcrs,
  osmtilePcrsToTcrs
} from '../core/crs';
import type { GeoJsonInput } from '../core/geojson2mapml';
import type { MapmlViewer } from '../elements/mapml-viewer';
import type { Locale } from '../i18n/locale';

/**
 * Serialize the viewer as a fresh MapML document body.
 *
 * MapML.js additionally strips the injected `<div class="mapml-web-map">`
 * that Leaflet builds into the light DOM and the two `<style>` blocks
 * that came with it. Our MapLibre renderer keeps all injected DOM in
 * the shadow root, so `outerHTML` on the light-DOM host is already
 * clean \u2014 no post-processing needed.
 */
export function copyMapMLDocument(viewer: MapmlViewer): string {
  return viewer.outerHTML;
}

/**
 * Serialize the current viewer view as a `<map-meta name="extent">`
 * element in the requested coordinate system.
 *
 * `cs` matches MapML.js's `defExtCS` values (case-insensitive):
 * `'pcrs'` (default), `'gcrs'`, `'tcrs'`, `'tilematrix'`. Unknown
 * values fall back to `'pcrs'` with a console warning \u2014 same as
 * MapML.js.
 */
export function copyExtentMeta(viewer: MapmlViewer, cs: string): string {
  const ext = viewer.extent;
  if (!ext) return '';
  const csLower = cs.toLowerCase();
  const tL = ext.topLeft;
  const bR = ext.bottomRight;
  switch (csLower) {
    case 'gcrs':
      return `<map-meta name="extent" content="top-left-longitude=${tL.gcrs.horizontal}, top-left-latitude=${tL.gcrs.vertical}, bottom-right-longitude=${bR.gcrs.horizontal}, bottom-right-latitude=${bR.gcrs.vertical}"></map-meta>`;
    case 'tcrs': {
      // MapML.js quirk: `tL[0]` (zoom 0) for top-left, `bR[bR.length-1]`
      // (max zoom) for bottom-right. Mirrored verbatim so page authors
      // observing this shape in one implementation see the same in the
      // other. The `viewer.extent.topLeft.tcrs` array is
      // `resolutions.length` (25) entries for OSMTILE.
      const tlTcrs = tL.tcrs[0]!;
      const brTcrs = bR.tcrs[bR.tcrs.length - 1]!;
      return `<map-meta name="extent" content="top-left-x=${tlTcrs.horizontal}, top-left-y=${tlTcrs.vertical}, bottom-right-x=${brTcrs.horizontal}, bottom-right-y=${brTcrs.vertical}"></map-meta>`;
    }
    case 'tilematrix': {
      const tlTm = tL.tilematrix[0]!;
      const brTm = bR.tilematrix[bR.tilematrix.length - 1]!;
      return `<map-meta name="extent" content="top-left-column=${tlTm.horizontal}, top-left-row=${tlTm.vertical}, bottom-right-column=${brTm.horizontal}, bottom-right-row=${brTm.vertical}"></map-meta>`;
    }
    case 'pcrs':
      // Falls through: pcrs is the default output shape.
      return `<map-meta name="extent" content="top-left-easting=${Math.round(
        tL.pcrs.horizontal
      )}, top-left-northing=${Math.round(
        tL.pcrs.vertical
      )}, bottom-right-easting=${Math.round(
        bR.pcrs.horizontal
      )}, bottom-right-northing=${Math.round(bR.pcrs.vertical)}"></map-meta>`;
    default:
      console.warn(
        `MapML: copy extent CS "${cs}" is not supported; falling back to pcrs.`
      );
      return copyExtentMeta(viewer, 'pcrs');
  }
}

/** A single geographic point the user right-clicked. */
export interface CopyLocationPoint {
  /** Geographic WGS84, degrees. */
  lng: number;
  lat: number;
  /** Canvas-relative pixel position of the click, matching MapML.js's `containerPoint`. */
  containerPoint: { x: number; y: number };
}

/**
 * Serialize a single geographic point as a `<map-feature>` snippet in
 * the requested coordinate system.
 *
 * `cs` matches MapML.js's `defLocCS` values (case-insensitive):
 * `'gcrs'` (default), `'pcrs'`, `'tcrs'`, `'tilematrix'`, `'tile'`,
 * `'map'`. Unknown values fall back to `'gcrs'` with a console warning.
 *
 * For `'tilematrix'` / `'tile'` / `'map'` the output labels the
 * caption as `(not implemented yet)` and stores the click as GCRS
 * inside the `<map-geometry cs="gcrs">` \u2014 exactly matching
 * MapML.js's placeholder output for those coordinate systems.
 */
export function copyLocationFeature(
  viewer: MapmlViewer,
  point: CopyLocationPoint,
  cs: string
): string {
  const csLower = cs.toLowerCase();
  const projection = viewer.projection;
  const zoom = viewer.renderer.map?.getZoom() ?? 0;
  const zoomInt = Math.round(zoom);
  const lng6 = point.lng.toFixed(6);
  const lat6 = point.lat.toFixed(6);

  const build = (
    caption: string,
    geomCS: string,
    divText: string,
    coordsText: string
  ): string =>
    `<map-feature zoom="${zoomInt}">
        <map-featurecaption>${caption}</map-featurecaption>
        <map-properties>
            <h2>${caption}</h2>
            <div style="text-align:center">${divText}</div>
        </map-properties>
        <map-geometry cs="${geomCS}">
          <map-point>
            <map-coordinates>${coordsText}</map-coordinates>
          </map-point>
        </map-geometry>
      </map-feature>`;

  const gcrs = (): string =>
    build(
      `Copied ${projection} gcrs location`,
      'gcrs',
      `${lng6} ${lat6}`,
      `${lng6} ${lat6}`
    );

  // OSMTILE-only fast paths for tcrs / pcrs / tilematrix / tile. Non-
  // OSMTILE projections warn and fall back to GCRS \u2014 proj4 support
  // will replace this branch.
  if (projection !== 'OSMTILE' && csLower !== 'gcrs' && csLower !== 'map') {
    console.warn(
      `MapML: copy location CS "${cs}" for projection "${projection}" is not implemented yet; falling back to gcrs.`
    );
    return gcrs();
  }

  switch (csLower) {
    case 'gcrs':
      return gcrs();
    case 'pcrs': {
      const [x, y] = osmtileGcrsToPcrs(point.lng, point.lat);
      const px = Math.round(x);
      const py = Math.round(y);
      return build(
        `Copied ${projection} pcrs location`,
        'pcrs',
        `${px} ${py}`,
        `${px} ${py}`
      );
    }
    case 'tcrs': {
      const [x, y] = osmtileGcrsToPcrs(point.lng, point.lat);
      const tcrs = osmtilePcrsToTcrs(x, y, zoom);
      const tx = Math.trunc(tcrs.horizontal);
      const ty = Math.trunc(tcrs.vertical);
      return build(
        `Copied ${projection} tcrs location`,
        'tcrs',
        `${tx} ${ty}`,
        `${tx} ${ty}`
      );
    }
    case 'tilematrix': {
      // MapML.js's placeholder: caption calls out "(not implemented yet)"
      // and stores the point as GCRS inside the geometry. We mirror it
      // faithfully so string-diff tests match.
      const [x, y] = osmtileGcrsToPcrs(point.lng, point.lat);
      const tcrs = osmtilePcrsToTcrs(x, y, zoom);
      const col = Math.trunc(tcrs.horizontal / OSMTILE_TILE_SIZE);
      const row = Math.trunc(tcrs.vertical / OSMTILE_TILE_SIZE);
      return build(
        `Copied ${projection} tilematrix location (not implemented yet)`,
        'gcrs',
        `${col} ${row}`,
        `${lng6} ${lat6}`
      );
    }
    case 'tile': {
      const [x, y] = osmtileGcrsToPcrs(point.lng, point.lat);
      const tcrs = osmtilePcrsToTcrs(x, y, zoom);
      // "Tile" = pixel offset inside the containing tile.
      let px = Math.trunc(tcrs.horizontal) % OSMTILE_TILE_SIZE;
      let py = Math.trunc(tcrs.vertical) % OSMTILE_TILE_SIZE;
      if (px < 0) px += OSMTILE_TILE_SIZE;
      if (py < 0) py += OSMTILE_TILE_SIZE;
      return build(
        `Copied ${projection} tile location (not implemented yet)`,
        'gcrs',
        `${px} ${py}`,
        `${lng6} ${lat6}`
      );
    }
    case 'map': {
      // Canvas-relative pixel position of the click.
      const mx = Math.trunc(point.containerPoint.x);
      const my = Math.trunc(point.containerPoint.y);
      return build(
        `Copied ${projection} map location (not implemented yet)`,
        'gcrs',
        `${mx} ${my}`,
        `${lng6} ${lat6}`
      );
    }
    default:
      console.warn(
        `MapML: copy location CS "${cs}" is not supported; falling back to gcrs.`
      );
      return gcrs();
  }
}

/**
 * Write `text` to the clipboard using the async Clipboard API.
 *
 * Rejects silently (with a `console.warn`) when the API is unavailable
 * (insecure context, headless without permissions, etc.) so context
 * menu callers stay side-effect-free on failure. Playwright tests opt
 * in via the browser-context `clipboard-read` / `clipboard-write`
 * permissions.
 */
export async function writeToClipboard(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
  } catch {
    console.warn('MapML: clipboard write failed; copy is a no-op.');
  }
}

/**
 * Consume the clipboard's current text and inject it into `viewer`
 * following MapML.js's `Util._pasteLayer` shape.
 *
 * Supported inputs (order matters \u2014 first match wins):
 *   1. `<map-layer>\u2026</map-layer>` (comments allowed inside) \u2192
 *      appended verbatim.
 *   2. `<map-feature>\u2026</map-feature>` \u2192 wrapped in a
 *      `<map-layer label="{locale.dfPastedLayer}" checked>` and
 *      appended. A `<map-meta name="projection">` inside the layer
 *      records the projection at paste time (matches MapML.js).
 *   3. Absolute URL \u2192 `fetch`ed and content-type-sniffed:
 *      `application/json` / `application/geo+json` (or a
 *      `.json` / `.geojson` extension when the header is missing
 *      or generic) route through {@link MapmlViewer.geojson2mapml};
 *      anything else appends `<map-layer src="{url}"
 *      label="{locale.dfLayer}" checked>` and lets the remote-layer
 *      pipeline drive the load. Mirrors MapML.js's
 *      `Util._pasteLayer` fetch-then-branch.
 *   4. GeoJSON JSON text (Feature / FeatureCollection / Geometry)
 *      \u2192 handed to {@link MapmlViewer.geojson2mapml}, which
 *      builds and appends a `<map-layer>` containing one
 *      `<map-feature>` per input feature. Uses the viewer's own
 *      projection.
 *
 * Async so callers can `await` the paste before assertions.
 */
export async function pasteToViewer(
  viewer: MapmlViewer,
  raw: string,
  locale: Locale
): Promise<void> {
  // MapML.js strips comments before shape-matching, so `<!-- foo -->
  // <map-layer>...</map-layer>` still counts as a layer paste.
  const text = raw
    .replace(/(<!--.*?-->)|(<!--[\S\s]+?-->)|(<!--[\S\s]*?$)/g, '')
    .trim();

  if (
    text.startsWith('<map-layer') &&
    text.endsWith('</map-layer>')
  ) {
    viewer.insertAdjacentHTML('beforeend', text);
    return;
  }

  if (
    text.startsWith('<map-feature') &&
    text.endsWith('</map-feature>')
  ) {
    const wrapper =
      `<map-layer label="${locale.dfPastedLayer}" checked>` +
      `<map-meta name="projection" content="${viewer.projection}"></map-meta>` +
      text +
      '</map-layer>';
    viewer.insertAdjacentHTML('beforeend', wrapper);
    return;
  }

  // Try URL. `new URL(text)` throws for relative or bare-string inputs;
  // we only accept absolute URLs to avoid accidental interpretation of
  // stray words in the clipboard as a layer src.
  let parsedUrl: URL | undefined;
  try {
    parsedUrl = new URL(text);
  } catch {
    // Not a URL; fall through to the JSON-text branch below.
  }
  if (parsedUrl) {
    await pasteUrlToViewer(viewer, text, parsedUrl, locale);
    return;
  }

  // Last resort: try GeoJSON. Recognise Feature / FeatureCollection /
  // any Geometry, and delegate to viewer.geojson2mapml — same routing
  // MapML.js's `Util._pasteLayer` uses (`mapEl.geojson2mapml(JSON.parse(text))`).
  try {
    const parsed: unknown = JSON.parse(text);
    if (isGeoJsonInput(parsed)) {
      viewer.geojson2mapml(parsed as GeoJsonInput);
      return;
    }
  } catch {
    // Not JSON either.
  }

  console.log('MapML: paste ignored \u2014 unrecognised clipboard content.');
}

/**
 * Fetch `url`, sniff the response's `Content-Type` (with a filename-
 * extension fallback for servers that return generic `application/
 * octet-stream` or drop the header entirely), and route
 * GeoJSON-shaped responses through {@link MapmlViewer.geojson2mapml}.
 * Any other content type (including network errors) falls back to
 * appending a `<map-layer src="…">` \u2014 same conservative default
 * MapML.js applies in its `_pasteLayer` else-branch.
 */
async function pasteUrlToViewer(
  viewer: MapmlViewer,
  raw: string,
  parsed: URL,
  locale: Locale
): Promise<void> {
  let contentType = '';
  let body: string | undefined;
  try {
    const response = await fetch(raw);
    contentType = (response.headers.get('Content-Type') ?? '')
      .split(';')[0]!
      .trim()
      .toLowerCase();
    // Only pull the body when we might need it; a HEAD-like flow
    // isn't worth the extra request round-trip here.
    if (isJsonContentType(contentType) || isJsonUrlExtension(parsed)) {
      body = await response.text();
    }
  } catch {
    // Network failure / CORS. Fall through to the `<map-layer src>`
    // branch so the remote-layer pipeline can surface its own error.
  }

  if (body !== undefined) {
    try {
      const parsedBody: unknown = JSON.parse(body);
      if (isGeoJsonInput(parsedBody)) {
        viewer.geojson2mapml(parsedBody as GeoJsonInput);
        return;
      }
    } catch {
      // Not valid JSON despite the content-type. Fall through.
    }
  }

  const label = locale.dfLayer;
  // Scheme-allowlist the pasted URL before it becomes a
  // `<map-layer src>`. Even though `raw` already parsed as an
  // absolute URL, a `javascript:` / `data:` scheme must not ride
  // into the layer src. Non-http(s) URLs are ignored.
  const safeSrc = sanitizeHttpUrl(raw);
  if (!safeSrc) {
    console.warn(`MapML: ignoring paste of URL with disallowed scheme: ${raw}`);
    return;
  }
  viewer.insertAdjacentHTML(
    'beforeend',
    `<map-layer src="${escapeAttr(safeSrc)}" label="${escapeAttr(label)}" checked></map-layer>`
  );
}

function isJsonContentType(ct: string): boolean {
  return ct === 'application/json' || ct === 'application/geo+json';
}

function isJsonUrlExtension(url: URL): boolean {
  const ext = url.pathname.split('.').pop()?.toLowerCase() ?? '';
  return ext === 'json' || ext === 'geojson';
}

/**
 * True when `v` is a plausible top-level GeoJSON object: has a `type`
 * field matching one of the accepted values. Deliberately loose so
 * paste of an in-progress GeoJSON snippet still routes to
 * {@link geojson2mapml} (which will surface any deeper parse errors
 * via its own console output).
 */
function isGeoJsonInput(v: unknown): boolean {
  if (v === null || typeof v !== 'object') return false;
  const t = (v as { type?: unknown }).type;
  if (typeof t !== 'string') return false;
  return (
    t === 'Feature' ||
    t === 'FeatureCollection' ||
    t === 'Point' ||
    t === 'MultiPoint' ||
    t === 'LineString' ||
    t === 'MultiLineString' ||
    t === 'Polygon' ||
    t === 'MultiPolygon' ||
    t === 'GeometryCollection'
  );
}

/** Minimal attribute-value escaper for the URL branch of paste. */
function escapeAttr(v: string): string {
  return v.replace(/"/g, '&quot;');
}

/**
 * Resolve `raw` and return it only when the scheme is `http:`/
 * `https:`. Returns `''` for other schemes and malformed URLs.
 */
function sanitizeHttpUrl(raw: string): string {
  if (!raw) return '';
  try {
    const u = new URL(raw, document.baseURI);
    if (u.protocol === 'http:' || u.protocol === 'https:') return u.href;
  } catch {
    // malformed URL — fall through to empty return
  }
  return '';
}
