/**
 * Compute MapLibre's `beforeId` argument for the semantic "place
 * `movingId` immediately above `belowId`". MapLibre's `moveLayer`
 * signature is "move `id` to be *before* `beforeId`" — where "before"
 * means "beneath" in z-order. So to end up **above** `belowId`, we
 * need to pass the id of the layer currently sitting just above
 * `belowId` as `beforeId`. If nothing sits above `belowId`, we're
 * moving to the top, which is expressed as `beforeId === undefined`.
 *
 * Skips over `movingId` itself when walking the stack — the caller
 * may already be positioned above `belowId`, in which case the next
 * layer above `belowId` is the one currently above the caller.
 */
function beforeIdForMoveAbove(
  map: MapLibreMapLike,
  movingId: string,
  belowStackingId: string
): string | undefined {
  const layers = map.getStyle().layers;
  const belowIdx = layers.findIndex((l) => l.id === belowStackingId);
  if (belowIdx < 0) return undefined;
  for (let i = belowIdx + 1; i < layers.length; i++) {
    const candidate = layers[i]!.id;
    if (candidate !== movingId) return candidate;
  }
  return undefined;
}

/**
 * Handle-class family that owns per-layer MapLibre state. Extracted
 * from `MapLibreRenderer`'s id-keyed methods so the tree-owning code
 * in `<map-extent>` / `<map-layer>` (Stages 6–8) can retain a handle
 * instead of a string id + parallel renderer method call.
 *
 * Every handle:
 *   - constructs its MapLibre source + layer in the constructor,
 *   - implements `setVisible` / `setOpacity` / `moveAbove` / `remove`
 *     against the same `MapLibreMapLike` reference,
 *   - is safe to `remove()` more than once (idempotent teardown).
 *
 * The FeatureCollection handle lives in a follow-up commit (its
 * composite fill/line/circle sub-layer semantics warrant a dedicated
 * red→green cycle).
 */

/**
 * `<map-link rel="tile">` \u2192 one raster source + one raster layer.
 * The simplest handle: no per-instance state beyond `id` + the map
 * reference; every op is a one-line MapLibre call.
 */
export class MapLibreRasterTileHandle implements RendererLayer {
  readonly id: string;
  readonly kind = 'raster-tile' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;

  constructor(map: MapLibreMapLike, options: RasterTileLayerOptions) {
    this.#map = map;
    this.id = options.id;
    this.topStackingId = options.id;
    const {
      tiles,
      tileSize = 256,
      scheme = 'xyz',
      attribution,
      minzoom,
      maxzoom,
      bounds,
      visible = true
    } = options;

    const source: maplibregl.RasterSourceSpecification = {
      type: 'raster',
      tiles,
      tileSize,
      scheme,
      ...(attribution !== undefined ? { attribution } : {}),
      ...(minzoom !== undefined ? { minzoom } : {}),
      ...(maxzoom !== undefined ? { maxzoom } : {}),
      ...(bounds !== undefined ? { bounds } : {})
    };
    map.addSource(this.id, source);

    map.addLayer({
      id: this.id,
      type: 'raster',
      source: this.id,
      layout: { visibility: visible ? 'visible' : 'none' }
    });
  }

  setVisible(visible: boolean): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setLayoutProperty(
      this.id,
      'visibility',
      visible ? 'visible' : 'none'
    );
  }

  setOpacity(opacity: number): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setPaintProperty(this.id, 'raster-opacity', opacity);
  }

  moveAbove(below?: RendererLayer): void {
    if (!this.#map.getLayer(this.id)) return;
    const beforeId =
      below === undefined
        ? undefined
        : beforeIdForMoveAbove(this.#map, this.id, below.topStackingId);
    this.#map.moveLayer(this.id, beforeId);
  }

  remove(): void {
    if (this.#map.getLayer(this.id)) this.#map.removeLayer(this.id);
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
  }
}

/**
 * `<map-link rel="tile">` WMS-per-tile variant. Shares the raster
 * handle's shape but additionally registers a per-id entry in the
 * module-global {@link mapmlWmsTileRegistry} so the shared
 * `mapmlwmstile://` protocol handler can resolve tile requests.
 */
export class MapLibreWmsTileHandle implements RendererLayer {
  readonly id: string;
  readonly kind = 'wms-tile' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;

  constructor(map: MapLibreMapLike, options: WmsTileLayerOptions) {
    this.#map = map;
    this.id = options.id;
    this.topStackingId = options.id;
    const {
      templateUrl,
      cornerMap,
      unitsForCorners,
      tileSize = 256,
      scheme = 'xyz',
      attribution,
      minzoom,
      maxzoom,
      bounds,
      visible = true
    } = options;

    ensureMapmlWmsTileProtocol();
    mapmlWmsTileRegistry.set(this.id, {
      templateUrl,
      cornerMap,
      unitsForCorners,
      scheme,
      tileSize
    });

    // MapLibre expands `{z}/{x}/{y}` (and `{-y}` for tms schemes) in
    // the outer wrapper URL before calling the protocol handler, so
    // the handler receives the concrete numeric coordinates in the
    // URL path.
    const wrappedTiles = [
      `${MAPML_WMS_TILE_PROTOCOL}://${encodeURIComponent(this.id)}/{z}/{x}/{y}`
    ];

    const source: maplibregl.RasterSourceSpecification = {
      type: 'raster',
      tiles: wrappedTiles,
      tileSize,
      scheme,
      ...(attribution !== undefined ? { attribution } : {}),
      ...(minzoom !== undefined ? { minzoom } : {}),
      ...(maxzoom !== undefined ? { maxzoom } : {}),
      ...(bounds !== undefined ? { bounds } : {})
    };
    map.addSource(this.id, source);

    map.addLayer({
      id: this.id,
      type: 'raster',
      source: this.id,
      layout: { visibility: visible ? 'visible' : 'none' }
    });
  }

  setVisible(visible: boolean): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setLayoutProperty(
      this.id,
      'visibility',
      visible ? 'visible' : 'none'
    );
  }

  setOpacity(opacity: number): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setPaintProperty(this.id, 'raster-opacity', opacity);
  }

  moveAbove(below?: RendererLayer): void {
    if (!this.#map.getLayer(this.id)) return;
    const beforeId =
      below === undefined
        ? undefined
        : beforeIdForMoveAbove(this.#map, this.id, below.topStackingId);
    this.#map.moveLayer(this.id, beforeId);
  }

  remove(): void {
    if (this.#map.getLayer(this.id)) this.#map.removeLayer(this.id);
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
    mapmlWmsTileRegistry.delete(this.id);
  }
}

/**
 * `<map-tile>` contiguous-run raster layer. A run of adjacent
 * `<map-tile>` siblings becomes one of these — the MapLibre analog of
 * MapML.js's `MapTileLayer` (a `GridLayer` subclass). Instead of
 * Leaflet's per-tile `<img>` DOM, the run's author-supplied `src`
 * URLs are registered in the module-global {@link mapmlMapTileRegistry}
 * and served on demand by the shared `mapmltile://` protocol handler,
 * keyed by `"z/x/y"` (OSMTILE: `col`/`row`/`zoom` === `x`/`y`/`z`).
 *
 * `setTiles` re-uploads the table on a `<map-tile src>` mutation or a
 * run add/remove and forces MapLibre to reload the affected cells.
 */
export class MapLibreMapTileRunHandle implements MapTileRunRendererLayer {
  readonly id: string;
  readonly kind = 'map-tile-run' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;

  constructor(map: MapLibreMapLike, options: MapTileRunLayerOptions) {
    this.#map = map;
    this.id = options.id;
    this.topStackingId = options.id;
    const {
      tiles,
      tileSize = 256,
      attribution,
      minzoom,
      maxzoom,
      bounds,
      visible = true
    } = options;

    ensureMapmlMapTileProtocol();
    // Clone so later external mutation of the caller's Map doesn't
    // silently change what the protocol handler resolves.
    mapmlMapTileRegistry.set(this.id, new Map(tiles));
    // Warm the tile bodies now, in parallel, so the protocol handler
    // serves them from memory instead of opening a fresh connection
    // when MapLibre's scheduler asks for each cell (the port's analog
    // of MapML.js's `<map-tile>` `new Image()` cache-warming trick).
    prefetchMapTiles(tiles.values());

    // MapLibre expands `{z}/{x}/{y}` in the wrapper URL before calling
    // the protocol handler, so the handler receives concrete numeric
    // coordinates in the URL path.
    const wrappedTiles = [
      `${MAPML_MAP_TILE_PROTOCOL}://${encodeURIComponent(this.id)}/{z}/{x}/{y}`
    ];

    const source: maplibregl.RasterSourceSpecification = {
      type: 'raster',
      tiles: wrappedTiles,
      tileSize,
      scheme: 'xyz',
      ...(attribution !== undefined ? { attribution } : {}),
      ...(minzoom !== undefined ? { minzoom } : {}),
      ...(maxzoom !== undefined ? { maxzoom } : {}),
      ...(bounds !== undefined ? { bounds } : {})
    };
    map.addSource(this.id, source);

    map.addLayer({
      id: this.id,
      type: 'raster',
      source: this.id,
      layout: { visibility: visible ? 'visible' : 'none' }
    });

    // Align this source's tile-zoom selection with GeoServer's.
    // GeoServer (mapmlfeatures) *floors* the fractional fit-zoom
    // (`TiledCRS.fitProjectedBoundsToDisplay`): it serves the largest
    // integer zoom whose 256px tiles still fit the requested W×H. A
    // MapLibre raster source defaults to `roundZoom: true`, so at a
    // fractional camera zoom ≥ .5 it *rounds up* and requests one zoom
    // level higher than GeoServer served — the registry misses and the
    // mosaic blanks. Flipping this one source to `roundZoom: false`
    // makes MapLibre floor too, so the requested `z/x/y` always matches
    // the served tiles. `roundZoom` isn't in the public source spec
    // (raster sources hard-set it to `true` in their constructor and
    // ignore it in options), so we set it on the source instance
    // post-add; `TileManager` reads `source.roundZoom` live on the next
    // update. Scoped to THIS source only — every other source (base
    // map, features, images) keeps MapLibre's default rounding.
    const src = map.getSource(this.id) as
      | (maplibregl.Source & { roundZoom?: boolean })
      | undefined;
    if (src) src.roundZoom = false;
  }

  setTiles(tiles: Map<string, string>): void {
    mapmlMapTileRegistry.set(this.id, new Map(tiles));
    // Warm the new bodies up front (see the constructor) so the
    // re-request below resolves from memory.
    prefetchMapTiles(tiles.values());
    // The tile-URL template is unchanged, so MapLibre would keep
    // serving cached tiles. `RasterTileSource.setTiles` discards the
    // cache and re-requests every visible cell, picking up the new
    // registry entries. Guarded because the structural
    // `MapLibreMapLike` fake in unit tests may not implement it.
    const source = this.#map.getSource(this.id) as
      | (maplibregl.Source & { setTiles?: (tiles: string[]) => void })
      | undefined;
    source?.setTiles?.([
      `${MAPML_MAP_TILE_PROTOCOL}://${encodeURIComponent(this.id)}/{z}/{x}/{y}`
    ]);
  }

  setVisible(visible: boolean): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setLayoutProperty(
      this.id,
      'visibility',
      visible ? 'visible' : 'none'
    );
  }

  setOpacity(opacity: number): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setPaintProperty(this.id, 'raster-opacity', opacity);
  }

  moveAbove(below?: RendererLayer): void {
    if (!this.#map.getLayer(this.id)) return;
    const beforeId =
      below === undefined
        ? undefined
        : beforeIdForMoveAbove(this.#map, this.id, below.topStackingId);
    this.#map.moveLayer(this.id, beforeId);
  }

  remove(): void {
    if (this.#map.getLayer(this.id)) this.#map.removeLayer(this.id);
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
    mapmlMapTileRegistry.delete(this.id);
  }
}

/**
 * `<map-link rel="tile" type="text/mapml">` → N stacked raster runs.
 *
 * The tref points at a per-tile MapML *document* rather than an image.
 * The `mapmlmetatile://` protocol handler fetches + parses each tile
 * and serves the k-th `<map-tile src>`'s bytes for run source `k`, so
 * a single fetched tile can back several stacked raster layers (one
 * per `<map-tile>` run in document order — painter order, bottom run
 * first). Raster runs are *not* composited into one mosaic: each run
 * is its own MapLibre source + layer.
 *
 * The run set starts at `runCount` (default 1) and grows via
 * {@link setRunCount} when a parsed tile reveals more runs than
 * modelled. Growth inserts each new run layer directly above the
 * current top run so the run substack stays contiguous and below any
 * sibling (e.g. the link's harvested feature) layers.
 *
 * `<map-feature>`s in each tile are surfaced to the caller's
 * `onTileParsed` (registered in the shared meta-tile registry) rather
 * than reparented — the owning `<map-link>` harvests them into its own
 * GeoJSON source.
 */
export class MapLibreMapmlTileHandle implements MapmlTileRendererLayer {
  readonly id: string;
  readonly kind = 'mapml-tile' as const;
  topStackingId: string;
  #map: MapLibreMapLike;
  #tileSize: number;
  #attribution: string | undefined;
  #minzoom: number | undefined;
  #maxzoom: number | undefined;
  #bounds: [number, number, number, number] | undefined;
  #visible: boolean;
  #opacity = 1;
  #runCount = 0;

  constructor(map: MapLibreMapLike, options: MapmlTileLayerOptions) {
    this.#map = map;
    this.id = options.id;
    this.topStackingId = options.id;
    const {
      template,
      runCount = 1,
      tileSize = 256,
      attribution,
      minzoom,
      maxzoom,
      bounds,
      visible = true,
      onTileParsed,
      cornerMap,
      unitsForCorners,
      scheme
    } = options;
    this.#tileSize = tileSize;
    this.#attribution = attribution;
    this.#minzoom = minzoom;
    this.#maxzoom = maxzoom;
    this.#bounds = bounds;
    this.#visible = visible;

    ensureMapmlMetaTileProtocol();
    mapmlMetaTileRegistry.set(this.id, {
      template,
      ...(cornerMap ? { cornerMap } : {}),
      ...(unitsForCorners ? { unitsForCorners } : {}),
      ...(scheme ? { scheme } : {}),
      ...(onTileParsed ? { onTileParsed } : {})
    });

    // At least one run source so MapLibre starts fetching immediately;
    // the first parsed tile calls back with the real run count.
    this.setRunCount(Math.max(1, runCount));
  }

  /** MapLibre source + layer id for run index `k`. */
  #runId(k: number): string {
    return `${this.id}::run${k}`;
  }

  #addRunSource(k: number, beforeId?: string): void {
    const runId = this.#runId(k);
    // MapLibre expands `{z}/{x}/{y}` before invoking the handler, so it
    // receives concrete numeric coordinates plus the run index.
    const wrappedTiles = [
      `${MAPML_META_TILE_PROTOCOL}://${encodeURIComponent(this.id)}/${k}/{z}/{x}/{y}`
    ];
    const source: maplibregl.RasterSourceSpecification = {
      type: 'raster',
      tiles: wrappedTiles,
      tileSize: this.#tileSize,
      scheme: 'xyz',
      ...(this.#attribution !== undefined
        ? { attribution: this.#attribution }
        : {}),
      ...(this.#minzoom !== undefined ? { minzoom: this.#minzoom } : {}),
      ...(this.#maxzoom !== undefined ? { maxzoom: this.#maxzoom } : {}),
      ...(this.#bounds !== undefined ? { bounds: this.#bounds } : {})
    };
    this.#map.addSource(runId, source);
    this.#map.addLayer(
      {
        id: runId,
        type: 'raster',
        source: runId,
        layout: { visibility: this.#visible ? 'visible' : 'none' },
        ...(this.#opacity !== 1
          ? { paint: { 'raster-opacity': this.#opacity } }
          : {})
      },
      beforeId
    );
    // Match GeoServer's floor-based tile-zoom selection (see the note in
    // `MapLibreMapTileRunHandle`'s constructor).
    const src = this.#map.getSource(runId) as
      | (maplibregl.Source & { roundZoom?: boolean })
      | undefined;
    if (src) src.roundZoom = false;
  }

  setRunCount(count: number): void {
    if (count <= this.#runCount) return;
    for (let k = this.#runCount; k < count; k++) {
      // Insert directly above the current top run so the run substack
      // stays contiguous. `undefined` beforeId for the first source
      // lands it on top of the map (fine — nothing else exists yet).
      const beforeId =
        k === 0
          ? undefined
          : beforeIdForMoveAbove(this.#map, this.#runId(k), this.#runId(k - 1));
      this.#addRunSource(k, beforeId);
    }
    this.#runCount = count;
    this.topStackingId = this.#runId(count - 1);
  }

  setVisible(visible: boolean): void {
    this.#visible = visible;
    const value = visible ? 'visible' : 'none';
    for (let k = 0; k < this.#runCount; k++) {
      const runId = this.#runId(k);
      if (this.#map.getLayer(runId)) {
        this.#map.setLayoutProperty(runId, 'visibility', value);
      }
    }
  }

  setOpacity(opacity: number): void {
    this.#opacity = clampOpacity(opacity);
    for (let k = 0; k < this.#runCount; k++) {
      const runId = this.#runId(k);
      if (this.#map.getLayer(runId)) {
        this.#map.setPaintProperty(runId, 'raster-opacity', this.#opacity);
      }
    }
  }

  moveAbove(below?: RendererLayer): void {
    // Re-insert each run layer above the previous anchor: run 0 lands
    // above `below`, each higher run above the run we just moved,
    // preserving painter order (mirrors the vector-tile substack walk).
    if (this.#runCount === 0) return;
    let previousId: string | undefined;
    for (let k = 0; k < this.#runCount; k++) {
      const runId = this.#runId(k);
      if (!this.#map.getLayer(runId)) continue;
      const anchor = previousId ?? below?.topStackingId;
      const beforeId =
        anchor === undefined
          ? undefined
          : beforeIdForMoveAbove(this.#map, runId, anchor);
      this.#map.moveLayer(runId, beforeId);
      previousId = runId;
    }
  }

  remove(): void {
    for (let k = 0; k < this.#runCount; k++) {
      const runId = this.#runId(k);
      if (this.#map.getLayer(runId)) this.#map.removeLayer(runId);
      if (this.#map.getSource(runId)) this.#map.removeSource(runId);
    }
    this.#runCount = 0;
    mapmlMetaTileRegistry.delete(this.id);
    clearMetaTileCache(this.id);
  }
}


/**
 * `<map-link rel="image">` \u2192 one MapLibre `image` source + one
 * raster layer with `raster-fade-duration: 0`. `update()` refreshes
 * the source's URL + corner coordinates on the per-`moveend` cadence
 * driven by `<map-link>`'s move listener.
 *
 * Attribution routes through the *layer* metadata rather than the
 * source spec because `ImageSourceSpecification` doesn't declare an
 * `attribution` field \u2014 our `MapmlAttributionControl` walks raster
 * layers looking for a `mapml:attribution` metadata key.
 */
export class MapLibreImageHandle implements ImageRendererLayer {
  readonly id: string;
  readonly kind = 'image' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;

  constructor(map: MapLibreMapLike, options: ImageLayerOptions) {
    this.#map = map;
    this.id = options.id;
    this.topStackingId = options.id;
    const { url, coordinates, visible = true, attribution } = options;

    const source: maplibregl.ImageSourceSpecification = {
      type: 'image',
      url,
      coordinates
    };
    map.addSource(this.id, source);

    const layerSpec: maplibregl.RasterLayerSpecification = {
      id: this.id,
      type: 'raster',
      source: this.id,
      layout: { visibility: visible ? 'visible' : 'none' },
      paint: { 'raster-fade-duration': 0 }
    };
    if (attribution !== undefined) {
      layerSpec.metadata = { 'mapml:attribution': attribution };
    }
    map.addLayer(layerSpec);
  }

  setVisible(visible: boolean): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setLayoutProperty(
      this.id,
      'visibility',
      visible ? 'visible' : 'none'
    );
  }

  setOpacity(opacity: number): void {
    if (!this.#map.getLayer(this.id)) return;
    this.#map.setPaintProperty(this.id, 'raster-opacity', opacity);
  }

  moveAbove(below?: RendererLayer): void {
    if (!this.#map.getLayer(this.id)) return;
    const beforeId =
      below === undefined
        ? undefined
        : beforeIdForMoveAbove(this.#map, this.id, below.topStackingId);
    this.#map.moveLayer(this.id, beforeId);
  }

  update(payload: ImageLayerUpdate): void {
    const source = this.#map.getSource(this.id);
    if (!source) return;
    const imageSource = source as maplibregl.ImageSource;
    // `updateImage` accepts either `{ url }`, `{ coordinates }`, or
    // both. Passing both in a single call skips the intermediate
    // fetch-with-stale-coords state.
    imageSource.updateImage({
      url: payload.url,
      coordinates: payload.coordinates
    });
  }

  remove(): void {
    if (this.#map.getLayer(this.id)) this.#map.removeLayer(this.id);
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
  }
}

// ─── Vector-tile handle (pmtiles + XYZ MVT) ─────────────────────

/**
 * Which paint properties MapLibre associates with each style layer
 * type. Used by {@link MapLibreVectorTileHandle.setOpacity} to fan a
 * single `opacity` value across every applicable property on every
 * style layer the handle owns \u2014 mirroring how a `<map-layer>` /
 * `<map-extent>`'s `opacity` cascade lands on the raster / image
 * handles' `raster-opacity` in one push.
 *
 * Values are the exhaustive set of `*-opacity` properties for that
 * layer type per the MapLibre style spec
 * (https://maplibre.org/maplibre-style-spec/layers/). Types not listed
 * (background, sky, hillshade, heatmap) are permissible in a
 * stylesheet but currently receive no opacity cascade \u2014 authors
 * needing that can bake `*-opacity` values into the stylesheet itself.
 */
const VECTOR_TILE_OPACITY_PROPS: Record<string, readonly string[]> = {
  fill: ['fill-opacity'],
  line: ['line-opacity'],
  circle: ['circle-opacity', 'circle-stroke-opacity'],
  symbol: ['text-opacity', 'icon-opacity'],
  'fill-extrusion': ['fill-extrusion-opacity'],
  raster: ['raster-opacity']
};

/**
 * `<map-link rel="tile" type="application/pmtiles">` or `<map-link
 * rel="tile" type="application/vnd.mapbox-vector-tile">` \u2192 one
 * MapLibre `type: "vector"` source plus one style layer per entry
 * in the sibling `<map-link rel="stylesheet"
 * type="application/vnd.maplibre-style+json">`'s `layers[]`.
 *
 * Two source shapes, discriminated by
 * {@link ../renderer/MapRenderer.VectorTileLayerOptions.source}:
 *   - `'pmtiles'` \u2192 `{ type: 'vector', url: 'pmtiles://...' }`,
 *     backed by the `pmtiles://` protocol handler.
 *   - `'xyz-mvt'` \u2192 `{ type: 'vector', tiles: [...] }`, plain
 *     HTTP delivery.
 *
 * The handle owns:
 *   - one MapLibre source (id === `options.id`),
 *   - the list of style layer ids it added (all namespaced with
 *     `options.id` so they don't collide with other vector-tile
 *     handles).
 *
 * `topStackingId` is the last layer added (top of the sub-stack in
 * painter order); `moveAbove` re-inserts each of our layers above
 * the anchor, preserving their internal relative order.
 *
 * `setOpacity` fans across every `*-opacity` property MapLibre
 * associates with the style layer's type, matching how raster /
 * image handles cascade opacity onto their single `raster-opacity`
 * slot.
 */
export class MapLibreVectorTileHandle implements RendererLayer {
  readonly id: string;
  readonly kind = 'vector-tile' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;
  #layerIds: readonly string[];
  /**
   * Baseline paint values captured at construction time \u2014 what the
   * stylesheet's `paint` block declared for each `*-opacity` property.
   * Used by {@link setOpacity} to scale the author's declared opacity
   * by the cascade value, rather than clobbering it. Keyed by
   * `${layerId}::${propName}`.
   */
  #baselineOpacity = new Map<string, number>();
  /**
   * Layer types keyed by layer id, so {@link setOpacity} can look up
   * which `*-opacity` properties apply without re-parsing the style
   * layer specs on every call.
   */
  #layerTypes = new Map<string, string>();

  constructor(
    map: MapLibreMapLike,
    options: import('./MapRenderer').VectorTileLayerOptions
  ) {
    this.#map = map;
    this.id = options.id;
    const {
      styleLayers,
      glyphs,
      attribution,
      minzoom,
      maxzoom,
      bounds,
      visible = true
    } = options;

    // Build the MapLibre source spec from the discriminator. The
    // pmtiles branch registers the `pmtiles://` protocol handler on
    // first use; the XYZ MVT branch relies on MapLibre's native
    // HTTP loader with no additional handler.
    let source: maplibregl.SourceSpecification;
    if (options.source === 'pmtiles') {
      ensurePmtilesProtocol();
      source = {
        type: 'vector',
        // MapLibre's pmtiles source consumes `pmtiles://` URLs via
        // the registered protocol handler. If `tileUrl` already
        // carries the scheme (unusual but not impossible \u2014
        // authors mirroring a stock MapLibre style) leave it alone;
        // otherwise prefix it.
        url: options.tileUrl.startsWith('pmtiles://')
          ? options.tileUrl
          : `pmtiles://${options.tileUrl}`,
        ...(attribution !== undefined ? { attribution } : {}),
        ...(minzoom !== undefined ? { minzoom } : {}),
        ...(maxzoom !== undefined ? { maxzoom } : {}),
        ...(bounds !== undefined ? { bounds } : {})
      };
    } else {
      // XYZ MVT: plain HTTP delivery. Tref-substitution already
      // rewrote author-named tokens to MapLibre-native
      // `{x}`/`{y}`/`{z}` by the time we're called.
      source = {
        type: 'vector',
        tiles: [...options.tiles],
        scheme: options.scheme ?? 'xyz',
        ...(attribution !== undefined ? { attribution } : {}),
        ...(minzoom !== undefined ? { minzoom } : {}),
        ...(maxzoom !== undefined ? { maxzoom } : {}),
        ...(bounds !== undefined ? { bounds } : {})
      };
    }

    // Propagate the stylesheet's `glyphs` URL to the map so that
    // `symbol` layers with a `text-field` can resolve their font
    // ranges. Multiple vector-tile handles on the same page with
    // the same URL cost one glyph fetch per range (MapLibre
    // dedupes).
    if (glyphs !== undefined) {
      map.setGlyphs(glyphs);
    }

    map.addSource(this.id, source);

    const layerIds: string[] = [];
    for (const styleLayer of styleLayers) {
      // Namespace the layer id with our composite id so multiple
      // vector-tile handles on the same page don't clash on style-
      // layer ids. Authors write short, meaningful ids in their
      // stylesheet ("water", "roads") and we bury them under a
      // unique prefix.
      const originalId = String(styleLayer['id'] ?? `layer-${layerIds.length}`);
      const namespacedId = `${this.id}::${originalId}`;
      const layerType = String(styleLayer['type'] ?? '');
      // Overwrite `source` with our composite id \u2014 the stylesheet's
      // author-declared source (if any) is ignored so it doesn't need
      // to know the MapML-side id.
      const spec = {
        ...styleLayer,
        id: namespacedId,
        source: this.id
      } as unknown as maplibregl.LayerSpecification;

      // Layout: preserve any author layout keys but force
      // visibility from the caller's `visible` flag.
      const layoutIn =
        (styleLayer['layout'] as Record<string, unknown> | undefined) ?? {};
      (spec as { layout: Record<string, unknown> }).layout = {
        ...layoutIn,
        visibility: visible ? 'visible' : 'none'
      };

      // Capture baseline opacity values from the author's paint
      // block so setOpacity can scale, not clobber.
      const paint =
        (styleLayer['paint'] as Record<string, unknown> | undefined) ?? {};
      const opacityProps = VECTOR_TILE_OPACITY_PROPS[layerType] ?? [];
      for (const prop of opacityProps) {
        const declared = paint[prop];
        const baseline =
          typeof declared === 'number' && Number.isFinite(declared)
            ? declared
            : 1;
        this.#baselineOpacity.set(`${namespacedId}::${prop}`, baseline);
      }
      this.#layerTypes.set(namespacedId, layerType);

      map.addLayer(spec);
      layerIds.push(namespacedId);
    }
    this.#layerIds = layerIds;
    this.topStackingId =
      layerIds.length > 0 ? layerIds[layerIds.length - 1]! : this.id;
  }

  setVisible(visible: boolean): void {
    const value = visible ? 'visible' : 'none';
    for (const id of this.#layerIds) {
      if (this.#map.getLayer(id)) {
        this.#map.setLayoutProperty(id, 'visibility', value);
      }
    }
  }

  setOpacity(opacity: number): void {
    const clamped = clampOpacity(opacity);
    for (const id of this.#layerIds) {
      if (!this.#map.getLayer(id)) continue;
      const layerType = this.#layerTypes.get(id) ?? '';
      const props = VECTOR_TILE_OPACITY_PROPS[layerType] ?? [];
      for (const prop of props) {
        const baseline = this.#baselineOpacity.get(`${id}::${prop}`) ?? 1;
        this.#map.setPaintProperty(id, prop, baseline * clamped);
      }
    }
  }

  moveAbove(below?: RendererLayer): void {
    // Walk our owned layers in painter order and re-insert each above
    // the previous anchor. First layer lands above `below`; subsequent
    // layers land above the layer we just moved. Result: our substack
    // sits contiguously above `below.topStackingId`, preserving its
    // internal relative order.
    if (this.#layerIds.length === 0) return;
    let anchorId = below?.topStackingId;
    let previousId: string | undefined;
    for (const id of this.#layerIds) {
      if (!this.#map.getLayer(id)) continue;
      const beforeId =
        previousId === undefined
          ? anchorId === undefined
            ? undefined
            : beforeIdForMoveAbove(this.#map, id, anchorId)
          : beforeIdForMoveAbove(this.#map, id, previousId);
      this.#map.moveLayer(id, beforeId);
      previousId = id;
    }
  }

  remove(): void {
    for (const id of this.#layerIds) {
      if (this.#map.getLayer(id)) this.#map.removeLayer(id);
    }
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
  }
}

/**
 * Sub-layer ids derived from a composite feature-collection `id`. Each
 * concrete MapLibre layer suffixes its geometry role (`:fill`, `:line`,
 * `:circle`) so the composite `id` alone identifies the source and the
 * whole stack; the caller never needs to know the sub-layer names.
 */
export function featureSubLayerIds(
  id: string
): { fill: string; line: string; circle: string } {
  return {
    fill: `${id}:fill`,
    line: `${id}:line`,
    circle: `${id}:circle`
  };
}

/**
 * Wrap a geometry-role filter with per-feature zoom gating. Each
 * `<map-feature>` bakes its resolved `min` / `max` into its GeoJSON
 * `properties`, so a data-driven filter reproduces MapML.js's
 * per-feature `_checkRender` gate. MapLibre re-evaluates filters that
 * reference `["zoom"]` at every integer zoom crossing.
 */
function featureZoomFilter(
  geomFilter: maplibregl.ExpressionSpecification
): maplibregl.ExpressionSpecification {
  return [
    'all',
    geomFilter,
    ['>=', ['zoom'], ['get', 'min']],
    ['<=', ['zoom'], ['get', 'max']]
  ];
}

const EMPTY_OVERRIDES: PaintOverrides = { fill: {}, line: {}, circle: {} };

/**
 * Environment passed into every `MapLibreFeatureHandle` so it can
 * delegate cross-cutting concerns (hover / click event handling,
 * keyboard-focus publication, "last composite gone" cleanup) back to
 * the owning renderer without importing it.
 */
export interface FeatureHandleEnvironment {
  onFeatureEnter: (e: maplibregl.MapLayerMouseEvent) => void;
  onFeatureMove: (e: maplibregl.MapLayerMouseEvent) => void;
  onFeatureLeave: (e: maplibregl.MapLayerMouseEvent) => void;
  onFeatureClick: (e: maplibregl.MapLayerMouseEvent) => void;
  /**
   * Publisher for keyboard-focus items. Called with `(sourceId,
   * items)` on every `setFocusItems` and with `(sourceId, [])` on
   * `remove` so proxies drop out of the tab order. Optional so
   * unit tests that don't exercise focus can skip it.
   */
  publishFocusItems?: (
    sourceId: string,
    items: readonly FocusItemDraft[]
  ) => void;
  /**
   * Fired after `remove()` if the map no longer carries any composite
   * feature sub-layer (`*:fill|:line|:circle`). Renderers use this to
   * retract shared hover / content popups that would otherwise linger
   * over an empty map.
   */
  onLastCompositeRemoved?: () => void;
  /**
   * Fired with this composite's source id when it is hidden
   * (`setVisible(false)`, i.e. its `<map-layer>` was unchecked) or
   * removed. Renderers use it to retract a feature popup bound to that
   * composite so it can't linger over a layer that has left the map.
   */
  onCompositeHidden?: (sourceId: string) => void;
}

function clampOpacity(o: number): number {
  if (!Number.isFinite(o)) return 1;
  if (o < 0) return 0;
  if (o > 1) return 1;
  return o;
}

/**
 * `<map-layer>`'s aggregated GeoJSON composite. One geojson source
 * shared by three sub-layers (fill / line / circle), each with its
 * own geometry-role + zoom-range filter and its own hover / click
 * bindings.
 *
 * `topStackingId` is the circle sub-layer id — circle is drawn on
 * top of line, which is drawn on top of fill (painter order).
 */
export class MapLibreFeatureHandle implements FeatureRendererLayer {
  readonly id: string;
  readonly kind = 'feature-collection' as const;
  readonly topStackingId: string;
  #map: MapLibreMapLike;
  #env: FeatureHandleEnvironment;
  #sub: { fill: string; line: string; circle: string };
  #cachedStyle: PaintOverrides = EMPTY_OVERRIDES;
  /** Track binding tuples so `off()` can pass the exact-same handler reference. */
  #bindings: Array<{
    type: string;
    layerId: string;
    listener: (e: maplibregl.MapLayerMouseEvent) => void;
  }> = [];

  constructor(
    map: MapLibreMapLike,
    env: FeatureHandleEnvironment,
    options: FeatureCollectionLayerOptions
  ) {
    this.#map = map;
    this.#env = env;
    this.id = options.id;
    this.#sub = featureSubLayerIds(this.id);
    this.topStackingId = this.#sub.circle;

    const { data, visible = true, attribution } = options;
    const source: maplibregl.GeoJSONSourceSpecification = {
      type: 'geojson',
      data,
      ...(attribution !== undefined ? { attribution } : {})
    };
    map.addSource(this.id, source);

    const visLayout = {
      visibility: (visible ? 'visible' : 'none') as 'visible' | 'none'
    };
    // Painter-order: fills at the bottom, then strokes, then points on
    // top. Every filter accepts BOTH the singular geometry type and its
    // `Multi*` sibling (a GeoJSON source's `['geometry-type']` returns
    // the exact author-emitted type — no Multi* collapse).
    map.addLayer({
      id: this.#sub.fill,
      source: this.id,
      type: 'fill',
      filter: featureZoomFilter([
        'in',
        ['geometry-type'],
        ['literal', ['Polygon', 'MultiPolygon']]
      ]),
      paint: { 'fill-color': '#3388ff', 'fill-opacity': 0.2 },
      layout: visLayout
    });
    map.addLayer({
      id: this.#sub.line,
      source: this.id,
      type: 'line',
      filter: featureZoomFilter([
        'any',
        ['in', ['geometry-type'], ['literal', ['LineString', 'MultiLineString']]],
        // Polygons stroke their own outline UNLESS the feature builder
        // split their boundary into `<map-span>`-annotated LineString
        // segments (tile-clip edges), in which case `boundaryEmitted`
        // is set and the whole-ring outline is suppressed so tile
        // borders don't show through.
        [
          'all',
          ['in', ['geometry-type'], ['literal', ['Polygon', 'MultiPolygon']]],
          ['!', ['coalesce', ['get', 'boundaryEmitted'], false]]
        ]
      ]),
      paint: { 'line-color': '#3388ff', 'line-width': 3, 'line-opacity': 1 },
      layout: { ...visLayout, 'line-join': 'round', 'line-cap': 'round' }
    });
    map.addLayer({
      id: this.#sub.circle,
      source: this.id,
      type: 'circle',
      filter: featureZoomFilter([
        'in',
        ['geometry-type'],
        ['literal', ['Point', 'MultiPoint']]
      ]),
      paint: {
        'circle-color': '#3388ff',
        'circle-radius': 5,
        'circle-stroke-color': '#ffffff',
        'circle-stroke-width': 2
      },
      layout: visLayout
    });

    // Bind hover / click handlers to every sub-layer. MapLibre keys
    // listeners by (event, layerId, handler) so we track the exact
    // handler triple to allow precise `off()` on remove.
    for (const layerId of [this.#sub.fill, this.#sub.line, this.#sub.circle]) {
      this.#bind('mouseenter', layerId, env.onFeatureEnter);
      this.#bind('mousemove', layerId, env.onFeatureMove);
      this.#bind('mouseleave', layerId, env.onFeatureLeave);
      this.#bind('click', layerId, env.onFeatureClick);
    }
  }

  setData(data: GeoJSON.FeatureCollection): void {
    const source = this.#map.getSource(this.id);
    if (!source) return;
    const geojson = source as maplibregl.GeoJSONSource;
    geojson.setData(data);
    // Re-apply cached style so a mid-cycle setData doesn't leave the
    // sub-layers on their defaults. MapLibre preserves paint through
    // setData in practice, but a future refactor that tears down +
    // re-adds sub-layers on data change would silently revert; the
    // re-apply is cheap insurance.
    this.setStyle(this.#cachedStyle);
  }

  setStyle(overrides: PaintOverrides): void {
    this.#cachedStyle = overrides;
    const { fill, line, circle } = this.#sub;
    const map = this.#map;

    if (map.getLayer(fill)) {
      map.setPaintProperty(
        fill,
        'fill-color',
        overrides.fill['fill-color'] ?? DEFAULT_FEATURE_PAINT['fill-color']
      );
      map.setPaintProperty(
        fill,
        'fill-opacity',
        overrides.fill['fill-opacity'] ?? DEFAULT_FEATURE_PAINT['fill-opacity']
      );
    }
    if (map.getLayer(line)) {
      map.setPaintProperty(
        line,
        'line-color',
        overrides.line['line-color'] ?? DEFAULT_FEATURE_PAINT['line-color']
      );
      map.setPaintProperty(
        line,
        'line-opacity',
        overrides.line['line-opacity'] ?? DEFAULT_FEATURE_PAINT['line-opacity']
      );
      map.setPaintProperty(
        line,
        'line-width',
        overrides.line['line-width'] ?? DEFAULT_FEATURE_PAINT['line-width']
      );
      // `line-dasharray` has no meaningful baseline (undefined → solid).
      // Only push when the override provides a value — otherwise let
      // MapLibre keep its own default.
      if (overrides.line['line-dasharray'] !== undefined) {
        map.setPaintProperty(
          line,
          'line-dasharray',
          overrides.line['line-dasharray']
        );
      }
    }
    if (map.getLayer(circle)) {
      map.setPaintProperty(
        circle,
        'circle-color',
        overrides.circle['circle-color'] ?? DEFAULT_FEATURE_PAINT['circle-color']
      );
      map.setPaintProperty(
        circle,
        'circle-radius',
        overrides.circle['circle-radius'] ?? DEFAULT_FEATURE_PAINT['circle-radius']
      );
      map.setPaintProperty(
        circle,
        'circle-stroke-color',
        overrides.circle['circle-stroke-color'] ??
          DEFAULT_FEATURE_PAINT['circle-stroke-color']
      );
      map.setPaintProperty(
        circle,
        'circle-stroke-width',
        overrides.circle['circle-stroke-width'] ??
          DEFAULT_FEATURE_PAINT['circle-stroke-width']
      );
      map.setPaintProperty(
        circle,
        'circle-stroke-opacity',
        overrides.circle['circle-stroke-opacity'] ??
          DEFAULT_FEATURE_PAINT['circle-stroke-opacity']
      );
    }
  }

  setFocusItems(items: readonly FocusItemDraft[]): void {
    this.#env.publishFocusItems?.(this.id, items);
  }

  setAttribution(_attribution: string | undefined): void {
    // MapLibre doesn't expose a stable live-update API for source
    // attribution; the initial value from `options.attribution` is
    // baked into the source spec at construction. Callers should pass
    // attribution in `FeatureCollectionLayerOptions` at construction
    // whenever possible.
    void _attribution;
  }

  setVisible(visible: boolean): void {
    const value = visible ? 'visible' : 'none';
    for (const sub of [this.#sub.fill, this.#sub.line, this.#sub.circle]) {
      if (this.#map.getLayer(sub)) {
        this.#map.setLayoutProperty(sub, 'visibility', value);
      }
    }
    // Hiding the composite (layer unchecked) retracts any feature
    // popup bound to it.
    if (!visible) this.#env.onCompositeHidden?.(this.id);
  }

  setOpacity(opacity: number): void {
    const clamped = clampOpacity(opacity);
    const { fill, line, circle } = this.#sub;
    const map = this.#map;
    // Polygon fills keep their baseline 20% translucency and scale
    // down with the requested opacity, so authors setting
    // `opacity="0.5"` on a `<map-layer>` end up with 10% polygon
    // fill (matches MapML.js's default FeatureLayer style).
    if (map.getLayer(fill)) {
      map.setPaintProperty(fill, 'fill-opacity', clamped * 0.2);
    }
    if (map.getLayer(line)) {
      map.setPaintProperty(line, 'line-opacity', clamped);
    }
    if (map.getLayer(circle)) {
      map.setPaintProperty(circle, 'circle-opacity', clamped);
      map.setPaintProperty(circle, 'circle-stroke-opacity', clamped);
    }
  }

  moveAbove(below?: RendererLayer): void {
    // Composite move: fill first (positioned above `below`), then
    // line above fill, then circle above line. Result: fill/line/
    // circle sit contiguously above `below`'s top-most sub-layer,
    // preserving painter order.
    const { fill, line, circle } = this.#sub;
    if (!this.#map.getLayer(fill)) return;
    const anchorId =
      below === undefined
        ? undefined
        : beforeIdForMoveAbove(this.#map, fill, below.topStackingId);
    this.#map.moveLayer(fill, anchorId);
    if (this.#map.getLayer(line)) {
      const nextAnchor = beforeIdForMoveAbove(this.#map, line, fill);
      this.#map.moveLayer(line, nextAnchor);
    }
    if (this.#map.getLayer(circle)) {
      const nextAnchor = beforeIdForMoveAbove(this.#map, circle, line);
      this.#map.moveLayer(circle, nextAnchor);
    }
  }

  remove(): void {
    // Unbind hover / click handlers before dropping the layers so
    // MapLibre doesn't fire a stale mouseleave against a removed
    // sub-layer.
    for (const b of this.#bindings) {
      this.#map.off(b.type, b.layerId, b.listener);
    }
    this.#bindings.length = 0;
    for (const sub of [this.#sub.fill, this.#sub.line, this.#sub.circle]) {
      if (this.#map.getLayer(sub)) this.#map.removeLayer(sub);
    }
    if (this.#map.getSource(this.id)) this.#map.removeSource(this.id);
    // Drop keyboard-focus proxies for this composite so Tab doesn't
    // land on a stale entry pointing at a removed feature.
    this.#env.publishFocusItems?.(this.id, []);
    // Retract any feature popup bound to this composite before the
    // "last composite" sweep below, so removing one of several layers
    // still closes its own popup.
    this.#env.onCompositeHidden?.(this.id);
    // If the map now carries no composite sub-layers at all, let the
    // renderer retract shared popups / etc.
    if (
      !this.#map.getStyle().layers.some((l) => /:(fill|line|circle)$/.test(l.id))
    ) {
      this.#env.onLastCompositeRemoved?.();
    }
  }

  // ── internals ───────────────────────────────────────────────────

  #bind(
    type: string,
    layerId: string,
    listener: (e: maplibregl.MapLayerMouseEvent) => void
  ): void {
    this.#map.on(type, layerId, listener);
    this.#bindings.push({ type, layerId, listener });
  }
}
