/**
 * TypeScript port of MapML.js's `Util.geojson2mapml`
 * (`../MapML.js/src/mapml/utils/Util.js`), producing a
 * `<map-layer>` element from a GeoJSON object.
 *
 * The output shape mirrors MapML.js's `<map-layer>` template
 * field-for-field so that documents copied out of one implementation
 * paste cleanly into the other, and so the parity test fixture in
 * `../MapML.js/test/e2e/geojson/geojson2mapml.html` reproduces the
 * same MapML on our renderer.
 *
 * Layer scaffold (mirrors MapML.js verbatim):
 *
 *   ```html
 *   <map-layer label="…" checked>
 *     <map-meta name="extent" content="top-left-longitude=…, top-left-latitude=…, bottom-right-longitude=…,bottom-right-latitude=…"/>
 *     <map-meta name="projection" content="OSMTILE"/>
 *     <map-meta name="cs" content="gcrs"/>
 *     <map-feature>
 *       <map-featurecaption>…</map-featurecaption>
 *       <map-geometry><…/></map-geometry>
 *       <map-properties>…</map-properties>
 *     </map-feature>
 *     …
 *   </map-layer>
 *   ```
 *
 * Notable parity points:
 *   - The extent `<map-meta>` uses MapML.js's exact whitespace
 *     (`, ` after longitude but a bare `,` before `bottom-right-latitude`).
 *     Downstream string-diff tests match on this quirk.
 *   - `<map-multipolygon>` wraps `<map-polygon>` children (each with
 *     one or more `<map-coordinates>` rings), matching MapML.js.
 *   - `_properties2Table` output uses locale strings for
 *     `popupPropName` / `popupPropValue` — mirrored via {@link Locale}.
 *
 * Kept renderer-agnostic (no MapLibre imports). Uses only `document`
 * for element construction, so it runs equally well from paste,
 * drag-drop, or a direct `viewer.geojson2mapml(json)` call.
 */

import { M, type Locale } from '../i18n/locale';
import type { MapmlProjection } from './projection';

/**
 * Optional shape controlling how {@link geojson2mapml} builds each
 * `<map-feature>`. Field names + semantics mirror MapML.js's
 * `Util.geojson2mapml` `options` argument so pages can re-use the
 * same option bags across implementations.
 */
export interface Geojson2MapmlOptions {
  /** Overrides the layer's `label` attribute. */
  label?: string;
  /** Projection recorded in `<map-meta name="projection">`. Defaults to `OSMTILE`. */
  projection?: MapmlProjection;
  /**
   * `<map-featurecaption>` provider:
   *  - `function`: called with the feature JSON, returns caption text.
   *  - `string`: name of a `properties` key whose value becomes the
   *    caption. If the key is absent, the string itself is used
   *    (matches MapML.js).
   */
  caption?: string | ((feature: GeoJsonFeature) => string);
  /**
   * `<map-properties>` inner content:
   *  - `function`: called with feature JSON, must return an
   *    `HTMLElement` (appended into `<map-properties>`). Falsy returns
   *    fall through to the default table.
   *  - `string`: HTML fragment inserted via `insertAdjacentHTML`.
   *  - `HTMLElement`: appended as-is.
   *  - Otherwise: a `<table>` generated by {@link buildPropertiesTable}.
   */
  properties?: string | HTMLElement | ((feature: GeoJsonFeature) => HTMLElement | false | null | undefined);
  /**
   * Post-processor for each `<map-geometry>` element. Receives the
   * parsed geometry element and the feature JSON; returns the
   * element to append (may be the same or a wrapped copy).
   *
   * Matches MapML.js's `options.geometryFunction`, used by authors to
   * class-annotate or hyperlink geometries.
   */
  geometryFunction?: (
    geometryEl: HTMLElement,
    feature: GeoJsonFeature
  ) => HTMLElement;
}

// Minimal, DOM-safe GeoJSON typings. We deliberately don't pull in
// `@types/geojson` to keep the core package dependency-free; the
// unions below are sufficient for the shapes MapML.js accepts.

/** A GeoJSON position: `[lon, lat]` (elevation optional; ignored here). */
export type GeoJsonPosition = readonly number[];

export interface GeoJsonPoint {
  type: 'Point';
  coordinates: GeoJsonPosition;
}
export interface GeoJsonMultiPoint {
  type: 'MultiPoint';
  coordinates: readonly GeoJsonPosition[];
}
export interface GeoJsonLineString {
  type: 'LineString';
  coordinates: readonly GeoJsonPosition[];
}
export interface GeoJsonMultiLineString {
  type: 'MultiLineString';
  coordinates: readonly (readonly GeoJsonPosition[])[];
}
export interface GeoJsonPolygon {
  type: 'Polygon';
  coordinates: readonly (readonly GeoJsonPosition[])[];
}
export interface GeoJsonMultiPolygon {
  type: 'MultiPolygon';
  coordinates: readonly (readonly (readonly GeoJsonPosition[])[])[];
}
export interface GeoJsonGeometryCollection {
  type: 'GeometryCollection';
  geometries: readonly GeoJsonGeometry[];
}
export type GeoJsonGeometry =
  | GeoJsonPoint
  | GeoJsonMultiPoint
  | GeoJsonLineString
  | GeoJsonMultiLineString
  | GeoJsonPolygon
  | GeoJsonMultiPolygon
  | GeoJsonGeometryCollection;

export interface GeoJsonFeature {
  type: 'Feature';
  id?: string | number;
  geometry: GeoJsonGeometry | null;
  properties?: Record<string, unknown> | null;
  bbox?: readonly number[];
  name?: string;
  title?: string;
}

export interface GeoJsonFeatureCollection {
  type: 'FeatureCollection';
  features: readonly GeoJsonFeature[];
  bbox?: readonly number[];
  name?: string;
  title?: string;
}

export type GeoJsonInput =
  | GeoJsonFeature
  | GeoJsonFeatureCollection
  | GeoJsonGeometry;

/** BBox tuple stored during recursion. Order is `[minLon, minLat, maxLon, maxLat]`. */
type BBoxAcc = [number, number, number, number];

/**
 * Convert a GeoJSON document into a `<map-layer>` element.
 *
 * The returned element is detached; callers append it wherever it
 * belongs (typically `viewer.appendChild(...)`).
 *
 * @param json  GeoJSON. Accepted shapes: Feature, FeatureCollection,
 *   or any Geometry (the latter is wrapped in an anonymous Feature —
 *   matching MapML.js's behaviour when the caller drops a bare
 *   geometry in).
 * @param options  See {@link Geojson2MapmlOptions}.
 * @param locale  Locale bundle for the default `label` fallback and
 *   `<table>` header text. Optional — defaults to `M.options.locale`,
 *   matching MapML.js's `Util.geojson2mapml` which reads
 *   `M.options.locale` inline for both surfaces.
 */
export function geojson2mapml(
  json: GeoJsonInput | string,
  options: Geojson2MapmlOptions = {},
  locale: Locale = M.options.locale
): HTMLElement {
  const parsed: GeoJsonInput = typeof json === 'string' ? (JSON.parse(json) as GeoJsonInput) : json;
  const projection = options.projection ?? 'OSMTILE';
  const label = pickLayerLabel(parsed, options, locale);
  const layer = buildLayerScaffold(label, projection);

  const bboxAcc: BBoxAcc = [
    Number.POSITIVE_INFINITY,
    Number.POSITIVE_INFINITY,
    Number.NEGATIVE_INFINITY,
    Number.NEGATIVE_INFINITY
  ];
  let hasExplicitBbox = false;

  if (isFeatureCollection(parsed)) {
    if (parsed.bbox && parsed.bbox.length >= 4) {
      insertExtentMeta(layer, parsed.bbox);
      hasExplicitBbox = true;
    }
    for (const f of parsed.features) {
      appendFeature(layer, f, options, locale, bboxAcc);
    }
  } else if (isFeature(parsed)) {
    if (parsed.bbox && parsed.bbox.length >= 4) {
      insertExtentMeta(layer, parsed.bbox);
      hasExplicitBbox = true;
    }
    appendFeature(layer, parsed, options, locale, bboxAcc);
  } else if (isGeometry(parsed)) {
    // Bare geometry: wrap in an anonymous Feature so we get the same
    // scaffold (caption / properties / geometry). MapML.js falls
    // through the same path via `Util.geojson2mapml(json, options)`
    // with json.type === 'POINT' etc. — but its output isn't a full
    // layer; the recursive call returns the bare geometry element.
    // Since our public API returns a layer, wrap it here to avoid
    // handing back an isolated `<map-point>`.
    const synthetic: GeoJsonFeature = {
      type: 'Feature',
      geometry: parsed,
      properties: null
    };
    appendFeature(layer, synthetic, options, locale, bboxAcc);
  }

  // Fallback extent meta: derive from accumulated bbox if the JSON
  // didn't carry one. Only insert when at least one coordinate was
  // seen (otherwise the accumulator's Infinity sentinels would
  // corrupt the meta).
  if (!hasExplicitBbox && Number.isFinite(bboxAcc[0])) {
    insertExtentMeta(layer, bboxAcc);
  }

  return layer;
}

// ---------------------------------------------------------------------
// Layer scaffold + attribute helpers
// ---------------------------------------------------------------------

function buildLayerScaffold(label: string, projection: MapmlProjection): HTMLElement {
  const layer = document.createElement('map-layer');
  layer.setAttribute('label', label);
  layer.setAttribute('checked', '');
  // MapML.js inserts these two metas at construction time; extent
  // meta is later prepended via `insertAdjacentHTML('afterbegin', …)`,
  // so the final DOM order is [extent, projection, cs]. We match.
  const projectionMeta = document.createElement('map-meta');
  projectionMeta.setAttribute('name', 'projection');
  projectionMeta.setAttribute('content', projection);
  layer.appendChild(projectionMeta);
  const csMeta = document.createElement('map-meta');
  csMeta.setAttribute('name', 'cs');
  csMeta.setAttribute('content', 'gcrs');
  layer.appendChild(csMeta);
  return layer;
}

/**
 * Prepend the `<map-meta name="extent">` to `layer`.
 *
 * Format matches MapML.js verbatim, including the asymmetric whitespace
 * (spaces after `,` for `top-left-longitude`, none for
 * `bottom-right-longitude`) — string-diff tests key off this shape.
 */
function insertExtentMeta(layer: HTMLElement, bbox: readonly number[]): void {
  const html =
    `<map-meta name="extent" content="top-left-longitude=${bbox[0]},` +
    ` top-left-latitude=${bbox[1]},` +
    ` bottom-right-longitude=${bbox[2]},` +
    `bottom-right-latitude=${bbox[3]}"></map-meta>`;
  layer.insertAdjacentHTML('afterbegin', html);
}

function pickLayerLabel(
  json: GeoJsonInput,
  options: Geojson2MapmlOptions,
  locale: Locale
): string {
  if (options.label !== undefined) return options.label;
  const named = json as { name?: string; title?: string };
  if (typeof named.name === 'string' && named.name.length > 0) return named.name;
  if (typeof named.title === 'string' && named.title.length > 0) return named.title;
  return locale.dfLayer;
}

// ---------------------------------------------------------------------
// Feature construction
// ---------------------------------------------------------------------

function appendFeature(
  layer: HTMLElement,
  feature: GeoJsonFeature,
  options: Geojson2MapmlOptions,
  locale: Locale,
  bboxAcc: BBoxAcc
): void {
  const featureEl = document.createElement('map-feature');
  const captionEl = document.createElement('map-featurecaption');
  const geometryEl = document.createElement('map-geometry');
  const propertiesEl = document.createElement('map-properties');

  // -------- caption --------
  const layerLabel = layer.getAttribute('label') ?? '';
  const caption = resolveCaption(feature, options, layerLabel);
  captionEl.textContent = caption;

  // -------- properties --------
  const propBody = buildPropertiesBody(feature, options, locale);
  if (propBody instanceof HTMLElement) {
    propertiesEl.appendChild(propBody);
  } else if (typeof propBody === 'string') {
    propertiesEl.insertAdjacentHTML('beforeend', propBody);
  }
  // `propBody === false` means the caller's function opted out.

  // -------- geometry --------
  if (feature.geometry !== null && feature.geometry !== undefined) {
    const inner = buildGeometryElement(feature.geometry, bboxAcc);
    if (inner !== null) {
      const wrapped =
        typeof options.geometryFunction === 'function'
          ? options.geometryFunction(inner, feature)
          : inner;
      geometryEl.appendChild(wrapped);
    }
  }

  featureEl.appendChild(captionEl);
  featureEl.appendChild(geometryEl);
  featureEl.appendChild(propertiesEl);
  layer.appendChild(featureEl);
}

function resolveCaption(
  feature: GeoJsonFeature,
  options: Geojson2MapmlOptions,
  layerLabel: string
): string {
  if (typeof options.caption === 'function') {
    return options.caption(feature);
  }
  if (typeof options.caption === 'string') {
    const props = feature.properties ?? {};
    const propVal = (props as Record<string, unknown>)[options.caption];
    if (propVal !== undefined) return String(propVal);
    // MapML.js: fall back to the string itself (as literal text).
    return options.caption;
  }
  // MapML.js: fall back to `feature.id`, else the layer label.
  if (feature.id !== undefined) return String(feature.id);
  return layerLabel;
}

function buildPropertiesBody(
  feature: GeoJsonFeature,
  options: Geojson2MapmlOptions,
  locale: Locale
): HTMLElement | string | false {
  if (typeof options.properties === 'function') {
    const result = options.properties(feature);
    if (result instanceof Element) return result as HTMLElement;
    if (result === false || result === null || result === undefined) return false;
    console.error(
      'options.properties function returns a string instead of an HTMLElement.'
    );
    return false;
  }
  if (typeof options.properties === 'string') return options.properties;
  if (options.properties instanceof HTMLElement) return options.properties;
  return buildPropertiesTable(feature.properties ?? {}, locale);
}

/**
 * Build the default `<table>` MapML.js emits for
 * `<map-properties>`. Header text is localized via
 * `locale.popupPropName` / `locale.popupPropValue`.
 *
 * Row semantics: each own-enumerable key of `props` becomes one row
 * (`<th scope="row">key</th><td itemprop="key">value</td>`). Non-own
 * keys are skipped, matching MapML.js's `Object.prototype.hasOwnProperty`
 * guard.
 */
export function buildPropertiesTable(
  props: Record<string, unknown>,
  locale: Locale
): HTMLTableElement {
  const table = document.createElement('table');
  const thead = table.createTHead();
  const headRow = thead.insertRow();
  const th1 = document.createElement('th');
  const th2 = document.createElement('th');
  th1.appendChild(document.createTextNode(locale.popupPropName));
  th2.appendChild(document.createTextNode(locale.popupPropValue));
  th1.setAttribute('role', 'columnheader');
  th2.setAttribute('role', 'columnheader');
  th1.setAttribute('scope', 'col');
  th2.setAttribute('scope', 'col');
  headRow.appendChild(th1);
  headRow.appendChild(th2);

  const tbody = table.createTBody();
  for (const key of Object.keys(props)) {
    if (!Object.prototype.hasOwnProperty.call(props, key)) continue;
    const row = tbody.insertRow();
    const th = document.createElement('th');
    const td = document.createElement('td');
    th.appendChild(document.createTextNode(key));
    td.appendChild(document.createTextNode(String(props[key])));
    th.setAttribute('scope', 'row');
    td.setAttribute('itemprop', key);
    row.appendChild(th);
    row.appendChild(td);
  }
  return table;
}

// ---------------------------------------------------------------------
// Geometry construction
// ---------------------------------------------------------------------

/**
 * Build the inner element of `<map-geometry>` from a GeoJSON geometry.
 *
 * Recurses for `GeometryCollection` (one `<map-geometrycollection>`
 * containing one child per member geometry).
 *
 * Returns `null` for unsupported types (defensive; `type` field is
 * a required string in valid GeoJSON, so this only fires on malformed
 * input).
 */
function buildGeometryElement(
  geom: GeoJsonGeometry,
  bboxAcc: BBoxAcc
): HTMLElement | null {
  switch (geom.type) {
    case 'Point':
      return buildPointElement(geom, bboxAcc);
    case 'LineString':
      return buildLineStringElement(geom, bboxAcc);
    case 'Polygon':
      return buildPolygonElement(geom, bboxAcc);
    case 'MultiPoint':
      return buildMultiPointElement(geom, bboxAcc);
    case 'MultiLineString':
      return buildMultiLineStringElement(geom, bboxAcc);
    case 'MultiPolygon':
      return buildMultiPolygonElement(geom, bboxAcc);
    case 'GeometryCollection':
      return buildGeometryCollectionElement(geom, bboxAcc);
    default:
      return null;
  }
}

function buildPointElement(g: GeoJsonPoint, bboxAcc: BBoxAcc): HTMLElement {
  const el = document.createElement('map-point');
  const coords = document.createElement('map-coordinates');
  coords.textContent = coordText(g.coordinates, bboxAcc);
  el.appendChild(coords);
  return el;
}

function buildLineStringElement(g: GeoJsonLineString, bboxAcc: BBoxAcc): HTMLElement {
  const el = document.createElement('map-linestring');
  const coords = document.createElement('map-coordinates');
  coords.textContent = ringText(g.coordinates, bboxAcc);
  el.appendChild(coords);
  return el;
}

function buildPolygonElement(g: GeoJsonPolygon, bboxAcc: BBoxAcc): HTMLElement {
  const el = document.createElement('map-polygon');
  for (const ring of g.coordinates) {
    const coords = document.createElement('map-coordinates');
    coords.textContent = ringText(ring, bboxAcc);
    el.appendChild(coords);
  }
  return el;
}

function buildMultiPointElement(g: GeoJsonMultiPoint, bboxAcc: BBoxAcc): HTMLElement {
  const el = document.createElement('map-multipoint');
  const coords = document.createElement('map-coordinates');
  coords.textContent = ringText(g.coordinates, bboxAcc);
  el.appendChild(coords);
  return el;
}

function buildMultiLineStringElement(
  g: GeoJsonMultiLineString,
  bboxAcc: BBoxAcc
): HTMLElement {
  const el = document.createElement('map-multilinestring');
  for (const line of g.coordinates) {
    const coords = document.createElement('map-coordinates');
    coords.textContent = ringText(line, bboxAcc);
    el.appendChild(coords);
  }
  return el;
}

function buildMultiPolygonElement(g: GeoJsonMultiPolygon, bboxAcc: BBoxAcc): HTMLElement {
  const el = document.createElement('map-multipolygon');
  for (const polygon of g.coordinates) {
    const polyEl = document.createElement('map-polygon');
    for (const ring of polygon) {
      const coords = document.createElement('map-coordinates');
      coords.textContent = ringText(ring, bboxAcc);
      polyEl.appendChild(coords);
    }
    el.appendChild(polyEl);
  }
  return el;
}

function buildGeometryCollectionElement(
  g: GeoJsonGeometryCollection,
  bboxAcc: BBoxAcc
): HTMLElement {
  const el = document.createElement('map-geometrycollection');
  for (const inner of g.geometries) {
    const built = buildGeometryElement(inner, bboxAcc);
    if (built !== null) el.appendChild(built);
  }
  return el;
}

/** Emit one point's coordinates, updating bbox. */
function coordText(pt: GeoJsonPosition, bboxAcc: BBoxAcc): string {
  updateBBox(bboxAcc, pt[0]!, pt[1]!);
  return `${pt[0]} ${pt[1]}`;
}

/** Emit `"x y x y "` for an array of positions, updating bbox. Trailing space matches MapML.js. */
function ringText(points: readonly GeoJsonPosition[], bboxAcc: BBoxAcc): string {
  let out = '';
  for (const p of points) {
    updateBBox(bboxAcc, p[0]!, p[1]!);
    out += `${p[0]} ${p[1]} `;
  }
  return out;
}

function updateBBox(acc: BBoxAcc, x: number, y: number): void {
  if (x < acc[0]) acc[0] = x;
  if (y < acc[1]) acc[1] = y;
  if (x > acc[2]) acc[2] = x;
  if (y > acc[3]) acc[3] = y;
}

// ---------------------------------------------------------------------
// Type-guards
// ---------------------------------------------------------------------

function isFeatureCollection(v: GeoJsonInput): v is GeoJsonFeatureCollection {
  return (v as { type?: string }).type === 'FeatureCollection';
}

function isFeature(v: GeoJsonInput): v is GeoJsonFeature {
  return (v as { type?: string }).type === 'Feature';
}

function isGeometry(v: GeoJsonInput): v is GeoJsonGeometry {
  const t = (v as { type?: string }).type;
  return (
    t === 'Point' ||
    t === 'MultiPoint' ||
    t === 'LineString' ||
    t === 'MultiLineString' ||
    t === 'Polygon' ||
    t === 'MultiPolygon' ||
    t === 'GeometryCollection'
  );
}
