import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * `StaticControl` — toggles the viewer's `static` attribute.
 *
 * Opt-in via `controlslist="static"` (default-off, like `search` /
 * `geolocation` / `view`). Rendered in the `top-right` well, immediately
 * below the {@link ViewControl}. A single toggle button flips the viewer's
 * live {@link MapmlViewer.static} setter; the attribute observer then runs
 * `#toggleStatic`, which enables/disables the MapLibre interaction handlers
 * and the zoom buttons.
 *
 * The button stays in sync with programmatic / attribute-driven changes by
 * listening for the viewer's `mapml:staticchanged` event, and reflects the
 * current state via `aria-pressed`.
 *
 * Icons: the button renders a `<span class="mapml-static-button-icon
 * mapml-static-icon-{on|off}">`, styled by `staticControl.css` with the
 * Material Symbols `lock` (on) / `lock_open` (off) icons. Authors can
 * override `.mapml-static-icon-*` with their own `background-image`.
 */
export class StaticControl implements IControl {
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  #icon: HTMLSpanElement | undefined;
  readonly #viewer: MapmlViewer;
  #onStaticChanged: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-right' {
    return 'top-right';
  }

  onAdd(_map: MapLibreMap): HTMLDivElement {
    const container = document.createElement('div');
    container.className = 'maplibregl-ctrl maplibregl-ctrl-group mapml-static-button';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';

    const icon = document.createElement('span');
    icon.className = 'mapml-static-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    button.addEventListener('click', this.#onClick);

    container.appendChild(button);
    this.#container = container;
    this.#button = button;
    this.#icon = icon;

    const onStaticChanged = (): void => this.#render();
    this.#onStaticChanged = onStaticChanged;
    this.#viewer.addEventListener('mapml:staticchanged', onStaticChanged);
    this.#render();
    return container;
  }

  onRemove(): void {
    if (this.#onStaticChanged) {
      this.#viewer.removeEventListener('mapml:staticchanged', this.#onStaticChanged);
      this.#onStaticChanged = undefined;
    }
    this.#button?.removeEventListener('click', this.#onClick);
    this.#container?.remove();
    this.#container = undefined;
    this.#button = undefined;
    this.#icon = undefined;
  }

  #onClick = (event: MouseEvent): void => {
    event.stopPropagation();
    // Drive the viewer through its public `static` setter: the attribute
    // observer owns the mechanics (disabling handlers + zoom buttons).
    this.#viewer.static = !this.#viewer.static;
  };

  /** Sync the icon + label + pressed state to the viewer's `static` flag. */
  #render(): void {
    if (!this.#button || !this.#icon) return;
    const isStatic = this.#viewer.static;
    this.#icon.className = `mapml-static-button-icon mapml-static-icon-${
      isStatic ? 'on' : 'off'
    }`;
    const label = this.#viewer.locale.btnStatic;
    this.#button.title = label;
    this.#button.setAttribute('aria-label', label);
    this.#button.setAttribute('aria-pressed', String(isStatic));
  }
}
