/**
 * Stylesheet for the {@link ContextMenu} overlay.
 *
 * Lives inside the viewer's shadow root, not in MapLibre's control wells,
 * so it can be positioned freely over the canvas.
 *
 * "Toggle Controls" adds/removes the viewer's `controls` attribute (see
 * `#toggleControls` in ContextMenu.ts and the attribute observer in
 * `MapmlViewer.attributeChangedCallback`), so control visibility is
 * managed by installing/uninstalling the controls themselves rather
 * than by CSS. The attribution control is *sacred* and lives outside
 * that install path — authors can omit `<map-link rel="license">` but
 * they cannot suppress the attribution control's existence.
 */
export const contextMenuCss = /* css */ `
.mapml-contextmenu {
  position: absolute;
  z-index: 10000;
  min-width: 200px;
  padding: 4px 0;
  margin: 0;
  background: #fff;
  border: 1px solid #999;
  border-radius: 4px;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
  font: 13px/1.4 sans-serif;
  color: #222;
  list-style: none;
  user-select: none;
}
.mapml-contextmenu[hidden] {
  display: none;
}
.mapml-contextmenu-item {
  display: block;
  width: 100%;
  padding: 4px 12px;
  background: none;
  border: 0;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
}
.mapml-contextmenu-item:hover:not(:disabled),
.mapml-contextmenu-item:focus:not(:disabled) {
  background: #2a72d4;
  color: #fff;
  outline: none;
}
.mapml-contextmenu-item:disabled {
  color: #aaa;
  cursor: default;
}
.mapml-contextmenu-item kbd {
  margin-left: 12px;
  padding: 1px 4px;
  font-family: inherit;
  font-size: 11px;
  color: #555;
  background: #eee;
  border: 1px solid #ccc;
  border-radius: 3px;
}
.mapml-contextmenu-item:hover:not(:disabled) kbd,
.mapml-contextmenu-item:focus:not(:disabled) kbd {
  color: #eee;
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
}
.mapml-contextmenu-separator {
  height: 1px;
  margin: 4px 0;
  background: #ddd;
}
.mapml-contextmenu-submenu-indicator {
  margin-left: 12px;
  color: #666;
}
.mapml-contextmenu-item:hover:not(:disabled) .mapml-contextmenu-submenu-indicator,
.mapml-contextmenu-item:focus:not(:disabled) .mapml-contextmenu-submenu-indicator {
  color: inherit;
}
`;
