import {
  axisPairToPcrsBounds,
  axisToCS,
  axisToXY,
  type MapmlCS,
  type PcrsBounds
} from './crs';
import type { MapmlProjection } from './projection';
import type { MapInputDef } from './template';

/**
 * Derive a {@link PcrsBounds} from a set of `<map-input>` declarations
 * when they describe a valid pair of `type="location"` inputs \u2014 one
 * on a horizontal axis, one on a vertical axis, both in the *same*
 * coordinate system, both with numeric `min` and `max`. Returns `null`
 * when no such pair is found.
 *
 * Mixed-CS pairs (e.g. a `longitude` input plus a `row` input) are
 * rejected: the first location input's CS wins, and later inputs in a
 * different CS are ignored. Matches MapML.js's `<map-link>.getBounds()`
 * which locks to the first horizontal axis found.
 *
 * Zoom for `TILEMATRIX` / `TCRS` pairs is sourced from a sibling
 * `type="zoom"` input, preferring its `value` attribute, then `min`,
 * else `0`.
 *
 * Output is PCRS meters (in a normalised bbox); the caller then hands
 * it to {@link formatPcrsExtent} to build the multi-CRS envelope.
 */
export function inputsToPcrsBounds(
  inputs: readonly MapInputDef[],
  projection: MapmlProjection
): PcrsBounds | null {
  let cs: MapmlCS | null = null;
  let hMin: number | undefined;
  let hMax: number | undefined;
  let vMin: number | undefined;
  let vMax: number | undefined;

  for (const inp of inputs) {
    if (inp.type !== 'location' || inp.axis === undefined) continue;
    if (inp.min === undefined || inp.max === undefined) continue;
    const inputCS = axisToCS(inp.axis);
    if (inputCS === null) continue;
    if (cs === null) cs = inputCS;
    else if (cs !== inputCS) continue;
    const xy = axisToXY(inp.axis);
    if (xy === 'x') {
      hMin = inp.min;
      hMax = inp.max;
    } else if (xy === 'y') {
      vMin = inp.min;
      vMax = inp.max;
    }
  }

  if (
    cs === null ||
    hMin === undefined ||
    hMax === undefined ||
    vMin === undefined ||
    vMax === undefined
  ) {
    return null;
  }

  let zoom = 0;
  if (cs === 'TILEMATRIX' || cs === 'TCRS') {
    const zi = inputs.find((i) => i.type === 'zoom');
    if (zi !== undefined) {
      if (zi.value !== undefined) {
        const n = Number(zi.value);
        if (Number.isFinite(n)) zoom = n;
      } else if (zi.min !== undefined) {
        zoom = zi.min;
      }
    }
  }

  return axisPairToPcrsBounds(
    { cs, hMin, hMax, vMin, vMax },
    projection,
    zoom
  );
}

/**
 * Extract a `{ minZoom, maxZoom }` zoom range from a `<map-input type="zoom">`
 * declaration, if present and complete. Returns `null` when no such
 * input exists or when either `min` or `max` is missing / non-numeric.
 *
 * The output uses MapML.js's field names (`minZoom` / `maxZoom`, not
 * `min` / `max`) so it can be passed directly into
 * {@link formatPcrsExtent}.
 */
export function inputsToZoomRange(
  inputs: readonly MapInputDef[]
): { minZoom: number; maxZoom: number } | null {
  const zi = inputs.find((i) => i.type === 'zoom');
  if (zi === undefined || zi.min === undefined || zi.max === undefined) {
    return null;
  }
  return { minZoom: zi.min, maxZoom: zi.max };
}
