import * as maplibregl from 'maplibre-gl';
import type { Map as MapLibreMap } from 'maplibre-gl';

/**
 * `MapmlScaleControl` — MapLibre `ScaleControl` with the MapML.js
 * accessibility affordances layered on top:
 *
 *   1. **Focusable.** `tabindex="0"` on the control container so the
 *      scale enters the keyboard tab order between the layer control
 *      and the attribution control, matching MapML.js's tab sequence.
 *   2. **Spoken `aria-label`.** After MapLibre paints the ruler text
 *      (e.g. `500 m` / `1 mi`), we compute a full-sentence description
 *      (e.g. `1.2 centimeters to 500 meters`) and mirror it onto the
 *      container's `aria-label` so a screen reader announces it when
 *      the user tabs to the scale.
 *   3. **Live-region announcement.** A visually-hidden
 *      `<output role="status" aria-live="polite" aria-atomic="true">`
 *      is appended to the map container. Its text is refreshed on
 *      every `zoomend` / `moveend` (via the parent's own `_onMove`)
 *      and on map-canvas focus, so screen-reader users hear the
 *      current scale each time they enter the map or pan/zoom.
 *
 * Port of `MapML.js/src/mapml/control/ScaleBar.js`. The class name of
 * the hidden output element (`mapml-screen-reader-output-scale`) is
 * kept identical so existing CSS and Playwright selectors carry over.
 */
export class MapmlScaleControl extends maplibregl.ScaleControl {
  #output: HTMLOutputElement | undefined;
  #canvasFocusHandler: (() => void) | undefined;
  #moveHandler: (() => void) | undefined;
  #mapForCleanup: MapLibreMap | undefined;

  override onAdd(map: MapLibreMap): HTMLElement {
    const container = super.onAdd(map);
    this.#mapForCleanup = map;

    container.classList.add('mapml-control-scale');
    container.tabIndex = 0;
    container.setAttribute('role', 'group');

    // Live region — sibling of MapLibre's own DOM inside the map
    // container so a screen reader treats it as belonging to the map
    // region. Visually hidden via CSS (see layerControl.css.ts).
    const output = document.createElement('output');
    output.className = 'mapml-screen-reader-output-scale';
    output.setAttribute('role', 'status');
    output.setAttribute('aria-live', 'polite');
    output.setAttribute('aria-atomic', 'true');
    map.getContainer().appendChild(output);
    this.#output = output;

    // Initial paint of the ruler happens in super.onAdd()'s
    // synchronous `_onMove()` call; run our refresh in a microtask so
    // the container has non-empty text when we read it.
    queueMicrotask(() => this.#refresh());

    // Refresh on every subsequent `move`. MapLibre's own `_onMove` was
    // wired up first (in super.onAdd), so by the time our handler
    // runs the ruler has already been repainted for this frame.
    // Matches MapML.js's `zoomend moveend` binding (MapLibre doesn't
    // fire those on ScaleControl itself, so we take `move` instead).
    this.#moveHandler = (): void => this.#refresh();
    map.on('move', this.#moveHandler);

    // Re-announce on canvas focus (matches MapML.js which listens on
    // `map._container` focus). Screen-reader users hear the current
    // scale when they enter the map.
    this.#canvasFocusHandler = (): void => this.#announce();
    map.getCanvas().addEventListener('focus', this.#canvasFocusHandler);

    return container;
  }

  override onRemove(): void {
    const map = this.#mapForCleanup;
    if (map) {
      if (this.#moveHandler) map.off('move', this.#moveHandler);
      if (this.#canvasFocusHandler) {
        map.getCanvas().removeEventListener('focus', this.#canvasFocusHandler);
      }
    }
    this.#moveHandler = undefined;
    this.#canvasFocusHandler = undefined;
    this.#output?.remove();
    this.#output = undefined;
    this.#mapForCleanup = undefined;
    super.onRemove();
  }

  /**
   * Rebuild the spoken scale description from MapLibre's current
   * ruler element, mirror it onto the container's `aria-label`, and
   * push it into the live region. Called after MapLibre updates the
   * ruler and on map focus.
   */
  #refresh(): void {
    const container = this._container;
    if (!container) return;
    // MapLibre writes the ruler text directly into the container itself
    // (no inner element): `e.innerHTML = "10\u00A0km"` where `e` is
    // `this._container`. So read text and width from the container.
    const rulerText = (container.textContent ?? '').replace(/\u00A0/g, ' ').trim();
    if (!rulerText) return;

    const widthPx = container.getBoundingClientRect().width;
    const unit = (this.options.unit ?? 'metric') as 'metric' | 'imperial' | 'nautical';
    const description = formatScaleDescription(widthPx, rulerText, unit);
    if (!description) return;

    container.setAttribute('aria-label', description);
    if (this.#output) this.#output.textContent = description;
  }

  /**
   * Force the live region to re-fire even when the text hasn't
   * changed. Matches MapML.js's `_focusOutput` trick: clear, wait a
   * tick, then re-set — some screen readers won't announce an
   * identical string otherwise.
   */
  #announce(): void {
    const out = this.#output;
    if (!out) return;
    const label = this._container?.getAttribute('aria-label') ?? '';
    if (!label) return;
    out.textContent = '';
    setTimeout(() => {
      if (this.#output === out) out.textContent = label;
    }, 100);
  }
}

/**
 * Produce a spoken-form scale description from MapLibre's ruler text
 * and pixel width. Reproduces the sentence shapes MapML.js's ScaleBar
 * builds (`"<paper distance> centimeters to <ground distance>"` /
 * `"<paper distance> inches to <ground distance>"`), and expands the
 * abbreviated unit words so screen readers pronounce them.
 *
 * The paper-distance conversion mirrors MapML.js: `px / (devicePixelRatio * 96)`
 * inches, times 2.54 for centimeters. Values are rounded to one
 * decimal, matching the upstream tests.
 *
 * Exported for direct unit-testing (Playwright/Vitest can call it
 * without spinning up a map).
 */
export function formatScaleDescription(
  widthPx: number,
  rulerText: string,
  unit: 'metric' | 'imperial' | 'nautical'
): string {
  const dpi = (typeof window !== 'undefined' ? window.devicePixelRatio : 1) * 96;
  if (unit === 'imperial') {
    const inches = round1(widthPx / dpi);
    const ground = expandUnits(rulerText, 'imperial');
    return `${inches} inches to ${ground}`;
  }
  // metric and nautical: describe paper distance in centimeters
  const cm = round1((widthPx / dpi) * 2.54);
  const ground = expandUnits(rulerText, unit);
  return `${cm} centimeters to ${ground}`;
}

function round1(v: number): number {
  return Math.round(v * 10) / 10;
}

function expandUnits(rulerText: string, unit: 'metric' | 'imperial' | 'nautical'): string {
  if (unit === 'imperial') {
    return rulerText.replace(/(\d+(?:\.\d+)?)\s*mi\b/g, '$1 miles')
      .replace(/(\d+(?:\.\d+)?)\s*ft\b/g, '$1 feet');
  }
  if (unit === 'nautical') {
    return rulerText.replace(/(\d+(?:\.\d+)?)\s*nm\b/g, '$1 nautical miles');
  }
  // metric
  return rulerText.replace(/(\d+(?:\.\d+)?)\s*km\b/g, '$1 kilometers')
    .replace(/(\d+(?:\.\d+)?)\s*m\b/g, '$1 meters');
}
