import * as maplibregl from 'maplibre-gl';
import {
  decodeBlankTile,
  decodeTileImage,
  fetchTileImage
} from './mapLibreMapTileProtocol';
import { substituteWmsTileCorners } from './mapLibreWmsProtocol';
import type { TileCorner } from '../core/template';

/**
 * Shared plumbing for `<map-link rel="tile" type="text/mapml">` — the
 * "templated MapML tile" variant GeoServer emits with
 * `format_options=…mapmlusetiles:true;mapmlusefeatures:true`. Unlike a
 * plain raster tile (`type="image/*"`) whose tref points straight at an
 * image, a `text/mapml` tref points at a per-tile *MapML document*.
 * Each fetched tile document can contain:
 *
 *   - zero or more raster `<map-tile col row zoom src>` runs (a layer
 *     group can stack more than one raster layer — the DEM base plus,
 *     say, a hillshade), and
 *   - zero or more `<map-feature>` vector features.
 *
 * MapML.js renders this with a Leaflet `TileLayer` subclass
 * (`TemplatedTileLayer`) that fetches each tile in `createTile`, parses
 * the XML, and paints the `<map-tile>`s + `<map-feature>`s into the
 * tile's own SVG. MapLibre has no per-tile DOM hook, so this port
 * bridges the gap the same way the static-`<map-tile>` mosaic does: a
 * custom protocol backing a raster source. MapLibre drives tile
 * coverage, zoom selection, and caching; the handler fetches the tile's
 * MapML, extracts the matching `<map-tile>` `src` for the requested
 * *run index*, and returns its bytes.
 *
 * The tile URL template is
 * `mapmlmetatile://<handle-id>/<run-index>/{z}/{x}/{y}` — MapLibre
 * substitutes the numeric `z`/`x`/`y` before invoking the handler. One
 * raster source is created per run index (run 0, run 1, …), stacked in
 * document order so overlapping raster layers paint back-to-front
 * (painter's model) rather than being flattened into one mosaic.
 *
 * A single MapML document is fetched + parsed *once* per `<id, z/x/y>`
 * even though every run source (and the feature harvester) asks for the
 * same cell — see {@link metaTileParseCache}. When a cell is first
 * parsed, {@link MetaTileConfig.onTileParsed} fires so the owning
 * `<map-link>` can harvest that tile's `<map-feature>`s into its
 * link-owned GeoJSON source and grow its raster-run source set if the
 * document revealed more runs than currently modelled.
 *
 * OSMTILE only: the tref's `<map-input units="tilematrix">` `col`/`row`
 * map directly onto the Web-Mercator `x`/`y` grid, so no CRS transform
 * is needed here.
 */

/** Scheme name for the templated-MapML-tile protocol handler. */
export const MAPML_META_TILE_PROTOCOL = 'mapmlmetatile';

/**
 * Fired once per unique tile after its MapML document is parsed, before
 * any run source's image bytes are resolved. Lets the owning
 * `<map-link>` harvest `<map-feature>`s and react to the discovered run
 * count. `doc` is the parsed tile document (already namespace-adopted
 * as XML); `runCount` is the number of `<map-tile>` elements matching
 * the requested `z/x/y` in document order.
 */
export type MetaTileParsedCallback = (
  info: {
    key: string;
    z: number;
    x: number;
    y: number;
    doc: XMLDocument;
    runCount: number;
  }
) => void;

/** Per-handle configuration, keyed by the handle's id. */
export interface MetaTileConfig {
  /**
   * Tile URL template (already resolved against the link's base),
   * fetched as `text/mapml`. Carries either `{z}`/`{x}`/`{y}` tokens
   * (WMTS GetTile form) or, when {@link cornerMap} is set, the four
   * `{corner}` bbox tokens (WMS GetMap form — see {@link cornerMap}).
   */
  template: string;
  /**
   * When present, {@link template} is a WMS-bbox document URL whose
   * `{token}` placeholders are per-tile bbox corners (the same shape
   * the `mapmlwmstile://` raster handler resolves). The parse resolves
   * them from the requested `z/x/y` before fetching. Absent → the
   * template is a `{z}`/`{x}`/`{y}` WMTS URL.
   */
  cornerMap?: Record<string, TileCorner>;
  /** CS to compute corner values in when {@link cornerMap} is set. */
  unitsForCorners?: 'pcrs' | 'gcrs';
  /** Tile row scheme for corner resolution. Defaults to `'xyz'`. */
  scheme?: 'xyz' | 'tms';
  /** Fired once per unique tile after parse (feature harvest + run growth). */
  onTileParsed?: MetaTileParsedCallback;
}

/**
 * Live meta-tile configs, keyed by handle id. Module-scoped because
 * `maplibregl.addProtocol` is a global registration (see the sibling
 * `mapmltile://` handler). Entries are added when a
 * {@link MapLibreMapmlTileHandle} is created and removed on teardown.
 */
export const mapmlMetaTileRegistry = new Map<string, MetaTileConfig>();

/** Parsed result for one `<id, z/x/y>` cell. */
interface ParsedMetaTile {
  /**
   * Absolute `src` URLs of the `<map-tile>`s matching the requested
   * `z/x/y`, in document order. Index === run index. Empty for a
   * feature-only (or out-of-range / over-zoom) cell.
   */
  runs: string[];
  /**
   * Parsed tile document, retained so {@link harvestMetaTile} can
   * replay {@link MetaTileConfig.onTileParsed} on cache hits when the
   * owning `<map-link>` re-scans the viewport after MapLibre's own
   * raster cache short-circuits protocol invocation. `null` when the
   * fetch / parse failed.
   */
  doc: XMLDocument | null;
  /** Number of raster runs discovered for this cell (`runs.length`). */
  runCount: number;
}

/**
 * In-flight / completed tile-document parses, keyed by
 * `"<id>|<z>/<x>/<y>"`. Dedupes the network fetch + XML parse across
 * the N run sources (and the feature harvester) that all request the
 * same cell. Bounded — the oldest entry is evicted past
 * {@link MAX_PARSE_ENTRIES} so a long pan session doesn't pin unbounded
 * memory. Eviction only drops the *dedupe* cache; already-harvested
 * features live on the `<map-link>`'s own per-tile map until it prunes
 * them by view.
 */
const metaTileParseCache = new Map<string, Promise<ParsedMetaTile>>();

/** Upper bound on {@link metaTileParseCache} size. */
const MAX_PARSE_ENTRIES = 512;

/** Build the `"z/x/y"` sub-key. */
function metaTileKey(z: number, x: number, y: number): string {
  return `${z}/${x}/${y}`;
}

/**
 * Drop every cached parse for a handle id. Called when its
 * `<map-link>` tears down (or its tref changes) so a re-created handle
 * with the same id starts clean and re-fires `onTileParsed`.
 */
export function clearMetaTileCache(id: string): void {
  const prefix = `${id}|`;
  for (const key of metaTileParseCache.keys()) {
    if (key.startsWith(prefix)) metaTileParseCache.delete(key);
  }
}

/**
 * Fetch + parse one tile's MapML document, extract the raster runs
 * matching the requested cell, and fire {@link MetaTileConfig.onTileParsed}
 * exactly once. Never rejects — a network / parse failure resolves to
 * an empty-run tile so run sources render a blank cell and the feature
 * harvester simply contributes nothing.
 */
async function parseMetaTile(
  id: string,
  config: MetaTileConfig,
  z: number,
  x: number,
  y: number
): Promise<ParsedMetaTile> {
  const url = config.cornerMap
    ? substituteWmsTileCorners(
        config.template,
        config.cornerMap,
        config.unitsForCorners ?? 'pcrs',
        config.scheme ?? 'xyz',
        z,
        x,
        y
      )
    : config.template
        .split('{z}')
        .join(String(z))
        .split('{x}')
        .join(String(x))
        .split('{y}')
        .join(String(y));

  let text: string;
  try {
    const response = await fetch(url, {
      redirect: 'follow',
      headers: { Accept: 'text/mapml' }
    });
    if (!response.ok) return { runs: [], doc: null, runCount: 0 };
    text = await response.text();
  } catch {
    // Network failure / abort — blank cell, no features.
    return { runs: [], doc: null, runCount: 0 };
  }

  let doc: XMLDocument;
  try {
    doc = new DOMParser().parseFromString(text, 'application/xml');
  } catch {
    return { runs: [], doc: null, runCount: 0 };
  }
  if (doc.querySelector('parsererror')) {
    return { runs: [], doc: null, runCount: 0 };
  }

  // Match the requested cell exactly, in document order. Mirrors
  // MapML.js's `TemplatedTileLayer._createFeatures` selector
  // `map-tile[row=Y][col=X][zoom=Z]`; an over-zoom request past the
  // raster's native max returns a coarser parent tile that won't match
  // here, so nothing paints (features still harvest — they carry no
  // coord filter).
  const selector = `map-tile[col="${x}"][row="${y}"][zoom="${z}"]`;
  const runs: string[] = [];
  for (const tileEl of doc.querySelectorAll(selector)) {
    const src = tileEl.getAttribute('src');
    if (src === null || src === '') continue;
    // `<map-tile src>` from GeoServer is absolute; resolve against the
    // request URL anyway so a relative src (spec-legal) still works.
    try {
      runs.push(new URL(src, url).href);
    } catch {
      runs.push(src);
    }
  }

  const runCount = runs.length;
  config.onTileParsed?.({
    key: metaTileKey(z, x, y),
    z,
    x,
    y,
    doc,
    runCount
  });

  return { runs, doc, runCount };
}

/**
 * Resolve (or start) the parse for one cell, using {@link metaTileParseCache}
 * to dedupe concurrent requests across run sources + the feature
 * harvester. Fresh parses fire {@link MetaTileConfig.onTileParsed} once
 * inside {@link parseMetaTile}; callers wanting a callback on cache
 * hits should use {@link harvestMetaTile} instead.
 */
function ensureMetaTileParse(
  id: string,
  config: MetaTileConfig,
  z: number,
  x: number,
  y: number
): { pending: Promise<ParsedMetaTile>; fresh: boolean } {
  const cacheKey = `${id}|${metaTileKey(z, x, y)}`;
  const existing = metaTileParseCache.get(cacheKey);
  if (existing !== undefined) return { pending: existing, fresh: false };
  if (metaTileParseCache.size >= MAX_PARSE_ENTRIES) {
    const oldest = metaTileParseCache.keys().next().value;
    if (oldest !== undefined) metaTileParseCache.delete(oldest);
  }
  const pending = parseMetaTile(id, config, z, x, y);
  metaTileParseCache.set(cacheKey, pending);
  return { pending, fresh: true };
}

/**
 * Ensure the cell `<id, z/x/y>` has been parsed and its owning
 * `<map-link>`'s {@link MetaTileConfig.onTileParsed} has fired for
 * *this* invocation — fresh parses fire it inside {@link parseMetaTile};
 * cache hits replay it here so a re-viewed area still gets its features
 * harvested. Called from `<map-link>`'s moveend listener because
 * MapLibre's own raster cache short-circuits protocol invocation when a
 * previously-fetched tile is served from bytes, robbing us of the
 * harvest opportunity.
 *
 * Idempotent from the map-link's perspective: `onTileParsed` overwrites
 * its per-tile feature bucket by key, so a duplicate fire is a no-op
 * beyond the recompile of the feature list.
 */
export async function harvestMetaTile(
  id: string,
  z: number,
  x: number,
  y: number
): Promise<void> {
  const config = mapmlMetaTileRegistry.get(id);
  if (config === undefined) return;
  const { pending, fresh } = ensureMetaTileParse(id, config, z, x, y);
  const tile = await pending;
  // Fresh parses fired the callback inside `parseMetaTile`; only
  // cache hits need a replay here. A failed fetch (`doc === null`)
  // has nothing to harvest either way.
  if (fresh || tile.doc === null) return;
  config.onTileParsed?.({
    key: metaTileKey(z, x, y),
    z,
    x,
    y,
    doc: tile.doc,
    runCount: tile.runCount
  });
}

/**
 * Whether {@link ensureMapmlMetaTileProtocol} has registered the shared
 * handler. `addProtocol` throws on double-register.
 */
let mapmlMetaTileProtocolRegistered = false;

/**
 * Register the shared `mapmlmetatile://` protocol handler on first use.
 * Idempotent. Parses `mapmlmetatile://<id>/<run>/<z>/<x>/<y>` (MapLibre
 * substitutes `{z}`/`{x}`/`{y}` before invoking us), fetches + parses
 * the tile document (deduped across run sources), and returns the
 * `<map-tile src>` bytes for the requested run index. A cell with no
 * matching run — or a run index past the document's run count — returns
 * a transparent tile so the raster source drops it silently.
 */
export function ensureMapmlMetaTileProtocol(): void {
  if (mapmlMetaTileProtocolRegistered) return;
  mapmlMetaTileProtocolRegistered = true;
  maplibregl.addProtocol(MAPML_META_TILE_PROTOCOL, async (params, abortController) => {
    const parsed = parseMetaTileUrl(params.url);
    if (parsed === null) {
      throw new Error(`Malformed ${MAPML_META_TILE_PROTOCOL}:// URL: ${params.url}`);
    }
    const config = mapmlMetaTileRegistry.get(parsed.id);
    if (config === undefined) {
      return { data: await decodeBlankTile() };
    }

    const { pending } = ensureMetaTileParse(
      parsed.id,
      config,
      parsed.z,
      parsed.x,
      parsed.y
    );
    const tile = await pending;

    const src = tile.runs[parsed.run];
    if (src === undefined) {
      // No raster for this run index at this cell (feature-only tile,
      // or a run source above the document's run count). Blank cell.
      return { data: await decodeBlankTile() };
    }
    const init: RequestInit = { signal: abortController.signal };
    if (params.credentials !== undefined) {
      init.credentials = params.credentials as RequestCredentials;
    }
    const data = await fetchTileImage(src, init);
    return data !== null
      ? { data: await decodeTileImage(data) }
      : { data: await decodeBlankTile() };
  });
}

function parseMetaTileUrl(
  url: string
): { id: string; run: number; z: number; x: number; y: number } | null {
  const prefix = `${MAPML_META_TILE_PROTOCOL}://`;
  if (!url.startsWith(prefix)) return null;
  const rest = url.slice(prefix.length);
  const parts = rest.split('/');
  if (parts.length !== 5) return null;
  const [encId, runStr, zStr, xStr, yStr] = parts as [
    string,
    string,
    string,
    string,
    string
  ];
  const run = Number(runStr);
  const z = Number(zStr);
  const x = Number(xStr);
  const y = Number(yStr);
  if (
    !Number.isFinite(run) ||
    !Number.isFinite(z) ||
    !Number.isFinite(x) ||
    !Number.isFinite(y)
  ) {
    return null;
  }
  return { id: decodeURIComponent(encId), run, z, x, y };
}
