import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * `ReloadButton` — MapML.js-style reload button.
 *
 * Visual contract: a single button in the top-left bearing the `↺` glyph
 * (matching MapML.js's `&#x021BA;`). Enabled whenever the viewer's
 * history ring is not parked at the initial entry (i.e. the user has
 * moved at least once and not yet rewound back to the start). Matches
 * MapML.js's rule of disabling Back/Reload together when `historyIndex`
 * hits 0. Clicking rewinds via {@link MapmlViewer.reload}, which empties
 * the ring back to the single initial entry.
 */
export class ReloadButton implements IControl {
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  readonly #viewer: MapmlViewer;
  #onHistoryChanged: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-left' {
    return 'top-left';
  }

  onAdd(_map: MapLibreMap): HTMLDivElement {
    const container = document.createElement('div');
    container.className = 'maplibregl-ctrl maplibregl-ctrl-group mapml-reload-button';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';
    // Localized via the viewer's active {@link Locale} — `cmReload`
    // matches MapML.js's ReloadButton title in `src/mapml/control/ReloadButton.js`.
    // Locale is read once at install time; a subsequent lang change on
    // the viewer will not relabel this button (matches MapML.js).
    const title = this.#viewer.locale.cmReload;
    button.title = title;
    button.setAttribute('aria-label', title);
    button.innerHTML =
      "<span class='mapml-reload-button-icon' aria-hidden='true'>&#x021BA;</span>";
    button.addEventListener('click', this.#onClick);

    container.appendChild(button);
    this.#container = container;
    this.#button = button;

    const onHistoryChanged = (): void => this.#updateDisabled();
    this.#onHistoryChanged = onHistoryChanged;
    this.#viewer.addEventListener('mapml:historychanged', onHistoryChanged);
    this.#updateDisabled();
    return container;
  }

  onRemove(): void {
    if (this.#onHistoryChanged) {
      this.#viewer.removeEventListener('mapml:historychanged', this.#onHistoryChanged);
      this.#onHistoryChanged = undefined;
    }
    this.#button?.removeEventListener('click', this.#onClick);
    this.#container?.remove();
    this.#container = undefined;
    this.#button = undefined;
  }

  #onClick = (event: MouseEvent): void => {
    event.stopPropagation();
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    this.#viewer.reload();
  };

  #updateDisabled(): void {
    if (!this.#button) return;
    const enabled = this.#viewer.historyIndex > 0;
    this.#button.disabled = !enabled;
    this.#button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
  }
}

