import type { MapInputDef } from '../core/template';
import type { MapLayer } from './map-layer';
import type { MapmlViewer } from './mapml-viewer';
import { shadowCrossingClosestByTag } from '../core/shadow';

/**
 * `<map-input>` — declarative variable referenced by a sibling `<map-link>`'s `tref`.
 *
 * This element carries metadata only; it has no rendering of its own. The URL
 * template engine reads the `name`, `type`, `axis`, `units`, `min`, `max` and
 * `value` attributes via {@link toDefinition}.
 *
 * v1 of the MapLibre renderer evaluates only the subset needed for OSMTILE
 * raster tile templates (`type="zoom"`, `type="location" axis="column|row"
 * units="tilematrix"`). Unsupported inputs are still parsed; the template
 * engine reports them as errors when referenced.
 */
export class MapInput extends HTMLElement {
  static readonly observedAttributes = [
    'name',
    'type',
    'axis',
    'units',
    'position',
    'min',
    'max',
    'value'
  ] as const;

  get name(): string {
    return this.getAttribute('name') ?? '';
  }

  get type(): string {
    return this.getAttribute('type') ?? '';
  }

  toDefinition(): MapInputDef {
    const def: MapInputDef = {
      name: this.name,
      type: (this.getAttribute('type') ?? '') as MapInputDef['type']
    };
    const axis = this.getAttribute('axis');
    if (axis !== null) def.axis = axis as NonNullable<MapInputDef['axis']>;
    const units = this.getAttribute('units');
    if (units !== null) def.units = units as NonNullable<MapInputDef['units']>;
    const position = this.getAttribute('position');
    if (position !== null) def.position = position;
    const min = numAttr(this, 'min');
    if (min !== undefined) def.min = min;
    const max = numAttr(this, 'max');
    if (max !== undefined) def.max = max;
    const value = this.getAttribute('value');
    if (value !== null) def.value = value;
    return def;
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<mapml-viewer>`
   * (or `null` when this input is detached). Shadow-crossing so an
   * input hosted inside a `<map-layer src="…">` remote-content
   * shadow root — or a viewer inside another custom element's
   * shadow root — still resolves the enclosing viewer.
   */
  getMapEl(): MapmlViewer | null {
    return shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null;
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<map-layer>` (or
   * `null` when this input is detached). Shadow-crossing so
   * remote-hosted inputs resolve the owning layer through the
   * `<map-layer src>` shadow root.
   */
  getLayerEl(): MapLayer | null {
    // Tag-based walk (not `instanceof`) so we don't have to pull
    // MapLayer in as a runtime import — `<map-input>` participates in
    // MapML markup only via attributes read by the template engine
    // and doesn't otherwise touch the layer class.
    return shadowCrossingClosestByTag(this, 'map-layer') as MapLayer | null;
  }
}

function numAttr(el: HTMLElement, name: string): number | undefined {
  const raw = el.getAttribute(name);
  if (raw === null) return undefined;
  const n = Number(raw);
  return Number.isFinite(n) ? n : undefined;
}
