/**
 * `<map-style>` — author-authored CSS-flavoured styling for
 * `<map-feature>` children of the enclosing `<map-layer>` (also under
 * `<map-extent>` and `<map-link rel="features">`).
 *
 * ## Two audiences, one element
 *
 * MapML.js's `<map-style>` element straddles two rendering
 * pipelines because Leaflet renders every `<map-feature>` as an SVG
 * element in the viewer shadow root, so the browser's CSS engine
 * applies author rules to both features and DOM chrome (popups,
 * controls) with zero extra plumbing.
 *
 * MapLibre draws every feature onto a WebGL `<canvas>`, so plain CSS
 * has no path to reach a feature. This element bridges the gap:
 *
 * 1. **Feature paint (Track B).** The CSS text is compiled via
 *    {@link compileMapStyle} into a normalised rule set, then
 *    translated by {@link compilePaintOverrides} into MapLibre
 *    `["case", …]` paint expressions keyed off each feature's
 *    `properties.classNames` array (baked at feature-emit time in
 *    {@link ../elements/map-feature.MapFeature.toGeoJsonFeatures}).
 *    The enclosing `<map-layer>` aggregates every `<map-style>` in
 *    its subtree (this element registers via
 *    {@link MapLayer.notifyStylesChanged}) and pushes the compiled
 *    bundle to the renderer via
 *    {@link ../renderer/MapRenderer.setFeatureStyle}. The rule
 *    surface is SVG-flavoured (`fill`, `stroke`, `stroke-width`,
 *    `fill-opacity`, `stroke-dasharray`, `r`, `color`) to match
 *    Leaflet / MapML.js author habit; see
 *    {@link ../core/paintExpressions.paintValuesFor} for the property
 *    map.
 *
 * 2. **DOM styling (Track A).** The same CSS text is mirrored into a
 *    `<style>` element appended to the viewer's shadow root, so
 *    popup content (`<map-properties>` HTML), custom controls, and
 *    other shadow-root DOM see the author's rules unmodified. This
 *    handles anything the feature-paint compiler can't (font sizes,
 *    text colour, custom HTML classes inside popup bodies).
 *
 * ## Selector scope (v1)
 *
 * Class selectors only (`.foo`, `.foo.bar`). Anything else logs a
 * warning and is skipped — see {@link compileMapStyle}. Track B does
 * *not* enforce scoping beyond the class attribute: a `<map-style>`
 * with `.foo { fill: red }` under `<map-layer id="A">` paints every
 * feature with `class="foo"` in that layer, regardless of which
 * `<map-extent>` or `<map-link rel="features">` subtree the feature
 * came from. Extent-scoped feature sources may narrow this later; the
 * v1 aggregation model puts all features under one MapLibre source
 * per layer, so per-source scoping *is* per-layer scoping.
 *
 * ## Media queries
 *
 * The `media` attribute gates whether this style contributes to the
 * layer's paint + shadow-root DOM. When the query doesn't match, the
 * mirrored `<style>` is removed and the aggregator filters this
 * contributor out (via {@link MapStyle.isActive}); when it matches,
 * both come back. Ports MapML.js's `_registerMediaQuery` from
 * `../MapML.js/src/map-style.js`. See
 * [src/elements/matchMedia.ts](./matchMedia.ts) for the map-flavoured
 * feature set that queries can reference.
 *
 * ## Lifecycle
 *
 * - `connectedCallback` walks up to the enclosing `<map-layer>` via
 *   {@link shadowCrossingClosestByTag}, adds itself to that layer's
 *   style registry, and schedules a rebuild. Also creates the
 *   mirrored `<style>` in the viewer shadow root (Track A).
 * - `disconnectedCallback` unregisters, tears down the mirrored
 *   `<style>`, and schedules a final rebuild so the layer drops the
 *   contribution from its aggregated ruleset.
 * - A `MutationObserver` on the element's own subtree
 *   (`characterData` + `childList` + `subtree`) treats textContent
 *   edits as a compile-then-rebuild. Matches MapML.js's
 *   `MutationObserver` in `src/map-style.js`.
 */

import { shadowCrossingClosestByTag } from '../core/shadow';
import { MapLayer } from './map-layer';
import type { MapmlViewer } from './mapml-viewer';

export class MapStyle extends HTMLElement {
  static readonly observedAttributes = ['media'] as const;

  #owningLayer: MapLayer | null = null;
  #owningViewer: MapmlViewer | null = null;

  /**
   * Mirrored `<style>` in the viewer shadow root (Track A). Owned
   * exclusively by this element — created in `connectedCallback`,
   * removed in `disconnectedCallback`. Kept as a reference so
   * `MutationObserver`-driven textContent updates can push straight
   * through without a fresh DOM query.
   */
  #mirroredStyle: HTMLStyleElement | null = null;

  /**
   * Watches the author-supplied CSS text for edits. MapML.js does the
   * same in `src/map-style.js#_connect`. Any subtree text change
   * triggers a re-compile + rebuild + mirror update.
   */
  #observer: MutationObserver | null = null;

  #connected = false;

  /**
   * Live matcher returned by {@link MapmlViewer.matchMedia} while the
   * `media` attribute is populated. `null` when the attribute is
   * absent / empty, or before the initial async registration
   * completes. Owned by this element; disposed in
   * {@link #teardownMediaQuery}.
   */
  #mql: MediaQueryList | null = null;
  /**
   * Bound change handler shared across the `#mql` lifetime. Retained
   * so `removeEventListener` sees the same identity used at
   * registration time — MediaQueryList keys listeners by identity.
   */
  #mqlChangeHandler: (() => void) | null = null;
  /**
   * Monotonic token bumped on every {@link #registerMediaQuery} call.
   * When {@link MapmlViewer.whenReady} resolves we bail if the token
   * has since moved — protects against a stale async registration
   * clobbering a fresher `media` value or a disconnect.
   */
  #mqlRegisterToken = 0;
  /**
   * Whether the `media` query currently matches. Default `true` when
   * the attribute is absent (matches unconditionally). Exposed
   * indirectly via {@link isActive} to the layer aggregator; changes
   * here trigger a `notifyStylesChanged` on the owning layer.
   */
  #mediaMatches = true;

  connectedCallback(): void {
    if (this.#connected) return;
    this.#connected = true;

    // The enclosing `<map-layer>` is the single style-registry
    // anchor point. Walk through shadow roots so `<map-style>`
    // grafted into `<map-link rel="features">` shadow content (or
    // `<map-layer src="…">` remote content) still reaches its
    // layer. When missing (element used out-of-context), stay
    // dormant — no crash, no side effects.
    this.#owningLayer = shadowCrossingClosestByTag(
      this,
      'map-layer'
    ) as MapLayer | null;
    this.#owningViewer = shadowCrossingClosestByTag(
      this,
      'mapml-viewer'
    ) as MapmlViewer | null;

    if (this.#owningLayer) {
      this.#owningLayer.registerStyle(this);
    }

    this.#installObserver();

    // Media-query gate. If `media` is set, defer the mirror install
    // to the first change-handler pass so a non-matching query
    // starts off inactive without a wasted install/remove
    // round-trip. Matches MapML.js's `<map-style>.connectedCallback`
    // dispatch in `src/map-style.js`.
    const mq = this.getAttribute('media') ?? '';
    if (mq !== '') {
      void this.#registerMediaQuery(mq);
    } else {
      this.#installMirroredStyle();
    }
  }

  disconnectedCallback(): void {
    if (!this.#connected) return;
    this.#connected = false;
    this.#teardownMediaQuery();
    this.#observer?.disconnect();
    this.#observer = null;
    this.#removeMirroredStyle();
    this.#owningLayer?.unregisterStyle(this);
    this.#owningLayer = null;
    this.#owningViewer = null;
    // Reset for a possible future reconnection (e.g. re-parenting
    // during a layer-control drag). `isActive` needs to start off
    // in the same "matches unconditionally" state a fresh element
    // would have.
    this.#mediaMatches = true;
  }

  attributeChangedCallback(
    name: string,
    oldValue: string | null,
    newValue: string | null
  ): void {
    if (!this.#connected) return;
    if (name === 'media' && oldValue !== newValue) {
      void this.#registerMediaQuery(newValue ?? '');
    }
  }

  /**
   * The CSS text authors wrote inside the `<map-style>` tags. Used
   * by the enclosing `<map-layer>` when it aggregates rules across
   * every registered style. Kept as a plain getter (not cached) so
   * mutation observers don't have to invalidate.
   */
  get cssText(): string {
    return this.textContent ?? '';
  }

  /**
   * The current `media` attribute value, or empty string when absent.
   * Non-empty values are compiled by
   * {@link MapmlViewer.matchMedia} into a live matcher that gates
   * whether this style contributes to the layer's paint. Matches
   * MapML.js's `<map-style>.media` in `src/map-style.js`.
   *
   * Property writes reflect to the attribute so
   * `style.media = '(map-zoom: 13)'` behaves the same as
   * `style.setAttribute('media', '(map-zoom: 13)')`. Setting to the
   * empty string / null / undefined removes the attribute (matches
   * `<map-link>.media`; MapML.js writes the empty string as-is, but
   * either shape triggers the "empty media matches" branch).
   */
  get media(): string {
    return this.getAttribute('media') ?? '';
  }
  set media(value: string) {
    if (value === '' || value === null || value === undefined) {
      this.removeAttribute('media');
    } else {
      this.setAttribute('media', value);
    }
  }

  /**
   * Whether this style is currently "live" (contributing to the
   * layer's paint). Tracks the current `media` query verdict:
   * `true` when the attribute is absent or matching, `false` while
   * a non-matching query is installed. The layer's aggregator
   * filters inactive contributors uniformly (same predicate used by
   * `<map-link rel="stylesheet">`).
   */
  get isActive(): boolean {
    return this.#mediaMatches;
  }

  #installObserver(): void {
    this.#observer = new MutationObserver(() => {
      // Mirror the fresh text into the shadow-root `<style>` and
      // schedule a rebuild. Both directions have to run — the
      // aggregator recompiles from `cssText`, and Track A relies
      // on the mirrored `<style>` having current text.
      if (this.#mirroredStyle) {
        this.#mirroredStyle.textContent = this.cssText;
      }
      this.#owningLayer?.notifyStylesChanged();
    });
    this.#observer.observe(this, {
      childList: true,
      characterData: true,
      subtree: true
    });
  }

  #installMirroredStyle(): void {
    const shadow = this.#owningViewer?.shadowRoot;
    if (!shadow) return;
    const style = document.createElement('style');
    style.textContent = this.cssText;
    // Tag so debugging tools can trace back to the source element.
    style.setAttribute('data-mapml-style', 'mirror');
    shadow.appendChild(style);
    this.#mirroredStyle = style;
  }

  #removeMirroredStyle(): void {
    this.#mirroredStyle?.remove();
    this.#mirroredStyle = null;
  }

  /**
   * Wire (or rewire) this element's `media` gate. Ports MapML.js's
   * `<map-style>._registerMediaQuery` in `src/map-style.js`.
   *
   * - When `mq` is a non-empty string, we await
   *   `viewer.whenReady()` (matchMedia reads the viewer's extent
   *   for the `map-*-easting` / `map-*-northing` features), build
   *   a fresh `MediaQueryList`, seed `#mediaMatches` from the
   *   initial verdict via {@link #applyMediaMatch}, then subscribe
   *   to the `change` event.
   * - When `mq` is empty, we tear the matcher down and force
   *   `#mediaMatches = true` — mirroring MapML.js's "no / empty
   *   media attribute matches" branch.
   *
   * Idempotent per attribute value. The change handler is bound
   * lazily on the first call so `removeEventListener` sees the
   * same identity across re-registrations.
   */
  async #registerMediaQuery(mq: string): Promise<void> {
    if (this.#mqlChangeHandler === null) {
      this.#mqlChangeHandler = (): void => {
        if (this.#mql === null) return;
        this.#applyMediaMatch(this.#mql.matches);
      };
    }
    this.#teardownMediaQuery();

    if (mq === '') {
      // Empty / removed media attribute: matches unconditionally.
      this.#applyMediaMatch(true);
      return;
    }

    const viewer = this.#owningViewer;
    if (viewer === null) return;

    this.#mqlRegisterToken += 1;
    const token = this.#mqlRegisterToken;
    await viewer.whenReady();
    if (
      token !== this.#mqlRegisterToken ||
      !this.#connected ||
      (this.getAttribute('media') ?? '') !== mq
    ) {
      return;
    }
    this.#mql = viewer.matchMedia(mq);
    this.#applyMediaMatch(this.#mql.matches);
    this.#mql.addEventListener('change', this.#mqlChangeHandler);
  }

  /**
   * Tear down the current `#mql` subscription, if any. Idempotent.
   * Retains `#mqlChangeHandler` across calls so a subsequent
   * registration reuses the same bound identity.
   */
  #teardownMediaQuery(): void {
    if (this.#mql !== null && this.#mqlChangeHandler !== null) {
      this.#mql.removeEventListener('change', this.#mqlChangeHandler);
    }
    this.#mql = null;
  }

  /**
   * Sync `#mediaMatches` + mirrored `<style>` presence + layer
   * aggregator notification with the current media-query verdict.
   * Called from every {@link #registerMediaQuery} entry point and
   * from the `change` handler. Idempotent when the verdict hasn't
   * flipped.
   */
  #applyMediaMatch(matches: boolean): void {
    const wasActive = this.#mediaMatches;
    const hadMirror = this.#mirroredStyle !== null;
    this.#mediaMatches = matches;
    if (matches && !hadMirror) {
      this.#installMirroredStyle();
    } else if (!matches && hadMirror) {
      this.#removeMirroredStyle();
    }
    // Only re-notify when the `isActive` verdict actually changed:
    // the layer's aggregator re-runs the compile pass on every
    // notify, so this keeps steady-state moveend / observer
    // triggers cheap.
    if (matches !== wasActive) {
      this.#owningLayer?.notifyStylesChanged();
    }
  }
}
