import * as maplibregl from 'maplibre-gl';
import type { Map as MapLibreMap, IControl, ControlPosition } from 'maplibre-gl';

import type {
  FeatureCollectionLayerOptions,
  ImageLayerOptions,
  ImageLayerUpdate,
  MapmlTileLayerOptions,
  MapRenderer,
  MapTileRunLayerOptions,
  RasterTileLayerOptions,
  RendererInitOptions,
  VectorTileLayerOptions,
  WmsTileLayerOptions
} from './MapRenderer';
import { FeatureFocusIndex, type FeatureFocusItem } from './FeatureFocusIndex';
import type { FeatureIndexHost } from './FeatureIndexOverlay';
import type { Locale } from '../i18n/locale';
import { defaultLocale } from '../i18n/locale';
import { viewProfile, type MapmlView } from '../core/view';
import { LayerGroup, type RendererLayer } from '../core/LayerGroup';
import type {
  FeatureRendererLayer,
  ImageRendererLayer,
  MapmlTileRendererLayer,
  MapTileRunRendererLayer
} from '../core/RendererHandles';
import type { PaintOverrides } from '../core/paintExpressions';
import {
  MapLibreFeatureHandle,
  MapLibreImageHandle,
  MapLibreMapmlTileHandle,
  MapLibreMapTileRunHandle,
  MapLibreRasterTileHandle,
  MapLibreVectorTileHandle,
  MapLibreWmsTileHandle,
  type FeatureHandleEnvironment
} from './MapLibreLayers';

const EMPTY_STYLE = {
  version: 8 as const,
  sources: {},
  layers: []
};

export class MapLibreRenderer implements MapRenderer {
  #map: MapLibreMap | undefined;
  #ready: Promise<void> | undefined;
  /**
   * Shared popup for `<map-featurecaption>` hover / focus tooltips.
   * One popup is reused across every composite feature layer — MapML.js
   * gets the same shape from Leaflet's per-geometry
   * `bindTooltip(title, { interactive: true, sticky: true })` in
   * `MapFeatureLayer._geometryToLayer`, which lazily mounts one
   * tooltip element per feature. We collapse to a single instance
   * here because MapLibre's event model is layer-scoped, not
   * feature-scoped, and a single hover surface is all we ever
   * expose to the user at a time.
   */
  #featurePopup: maplibregl.Popup | undefined;

  /**
   * Click-scoped popup for `<map-properties>` content. A separate
   * instance from {@link #featurePopup} so hover-caption + click-open
   * can coexist without stomping each other (MapLibre's `Popup` is
   * single-shot: `addTo` on one anchor point retracts a previous
   * anchor). Reused across clicks so a second feature-click replaces
   * the first popup rather than stacking.
   */
  #featureContentPopup: maplibregl.Popup | undefined;

  /**
   * Keyboard-focus index for `<map-feature>`s. Owns the invisible
   * proxy-button DOM that gives canvas-drawn features a place in the
   * tab order — the same role Leaflet's SVG paths play for MapML.js.
   * Instantiated on {@link init} and torn down in {@link destroy}.
   */
  #featureFocusIndex: FeatureFocusIndex | undefined;

  /**
   * Cached per-source paint overrides published by
   * {@link setFeatureStyle}. Retained so
   * {@link addOrUpdateFeatureCollection} can re-apply them on the
   * fill / line / circle sub-layers whenever the source is
   * (re-)registered — otherwise a `<map-feature>` mutation that
   * happens *after* the style was published would silently revert
   * the paint.
   *
   * Note: the composite `MapLibreFeatureHandle` also caches its own
   * style internally. We keep the renderer-side cache because
   * `setFeatureStyle` may be called BEFORE the source's handle is
   * created (element-order-dependent) — the cache then feeds the
   * initial `setStyle` in the `addOrUpdateFeatureCollection` adapter.
   */
  #featureStyleOverrides = new Map<string, PaintOverrides>();

  /**
   * Root of the renderer's `LayerGroup` tree. Populated in Stages 6–8
   * as `<map-layer>` / `<map-extent>` migrate off the id-keyed API
   * and start attaching their groups here. Empty during the
   * transitional period covered by the id-keyed adapters below.
   */
  readonly root = new LayerGroup('mapml-root');

  /**
   * Transitional bookkeeping for the legacy id-keyed `MapRenderer`
   * methods: element code that still calls `addRasterTileLayer` /
   * `setLayerVisibility` / `removeLayer` etc. by string id needs its
   * handles looked up somewhere. The adapters below store handles
   * here on `add…`, look them up on `set… / move… / remove…`, and
   * drop them on `remove…`. Deleted in Stage 9 alongside the id-keyed
   * methods themselves.
   */
  #legacyHandles = new Map<string, RendererLayer>();

  /**
   * Shared feature-handle environment. Built once on {@link init} from
   * the pre-bound `#onFeature*` handlers + the focus index + popup
   * cleanup. Passed to every `MapLibreFeatureHandle` on construction
   * so the handle can delegate cross-cutting concerns back here
   * without importing the renderer.
   */
  #featureEnv: FeatureHandleEnvironment | undefined;

  /**
   * The proxy element (if any) that opened the currently-visible
   * content popup. Cleared on popup close. When Escape / Tab-out
   * dismisses the popup this is the element we send focus back to
   * (matches MapML.js's `group.focus()` in `_attachSkipButtons`).
   * `null` when the popup was opened by mouse click — we return
   * focus to the map canvas instead.
   */
  #popupSourceProxy: HTMLElement | null = null;

  /**
   * The focus item paired with {@link #popupSourceProxy}. Retained so
   * we can re-focus the proxy through the index (which may have
   * re-mounted the proxy under a different sort position by the
   * time the popup closes). `null` when the popup was mouse-opened.
   */
  #popupSourceItem: FeatureFocusItem | null = null;

  /**
   * The full array of feature-property bags currently displayed by
   * the content popup. Length \u2265 2 when a `<map-link rel="query">`
   * response yielded multiple features and the nav bar's prev/next
   * buttons cycle through them. Length 1 for the ordinary static
   * `<map-feature>` click path. Empty between popups.
   */
  #popupFeatures: ReadonlyArray<Record<string, unknown>> = [];

  /**
   * Index into {@link #popupFeatures} currently shown in the popup.
   * The nav bar's `<` / `>` buttons decrement / increment this
   * (clamped at the array boundaries \u2014 no wrap-around, matching
   * MapML.js's disabled-at-endpoints prev/next behaviour).
   */
  #popupIndex = 0;

  /**
   * True while the open content popup shows a `<map-link rel="query">`
   * response rather than a static `<map-feature>` click. Query popups
   * are transient results tied to the queried layer(s), so the viewer
   * dismisses them via {@link closeQueryPopup} when a contributing
   * layer / extent is unchecked or removed \u2014 matching MapML.js, where
   * the query popup is bound to the queried layer and closes when that
   * layer leaves the map.
   */
  #contentPopupIsQuery = false;

  /**
   * True while a transient `<map-link rel="query">` highlight overlay
   * is mounted (source {@link #QUERY_HIGHLIGHT_SOURCE} + its paint
   * layers). Guards teardown so {@link #clearQueryHighlight} is a
   * cheap no-op when nothing is highlighted.
   */
  #queryHighlightActive = false;
  /**
   * The feature-collection source id that owns the open content popup
   * (a `<map-feature>` click / keyboard-activation popup), or `null`
   * for query popups (which have no single owning composite). When the
   * owning composite is hidden (`<map-layer>` unchecked) or removed,
   * the renderer retracts the popup so it can't linger over a layer
   * that has left the map \u2014 matching MapML.js, where the feature
   * popup is bound to its layer.
   */
  #contentPopupSourceId: string | null = null;

  /**
   * One-shot guard for the `close` handler: set while switching from
   * one open feature popup straight to another, where MapLibre's
   * `addTo` -> `remove()` fires a spurious `close` after the incoming
   * feature's source state is already in place. Swallows that single
   * close so the switch stays seamless. See {@link #openFeatureContentPopupAt}.
   */
  #suppressPopupCloseOnce = false;

  /**
   * MapML {@link Locale} bundle. Consumed by the click-popup pipeline
   * for the "Zoom to here" link label and the fallback heading when
   * a `<map-feature>` has no `<map-featurecaption>`. Set once in
   * {@link init}; changing the viewer's locale later doesn't relabel
   * already-open popups (matches MapML.js's once-per-install policy).
   */
  #mapmlLocale: Locale = defaultLocale;

  /**
   * Viewer-supplied callback for `<map-a>`-wrapped feature activation
   * via mouse click or keyboard Enter / Space. Undefined when the
   * embedding surface didn't wire feature links (e.g. tests that
   * instantiate the renderer directly).
   */
  #onFeatureLinkActivate: ((item: FeatureFocusItem) => void) | undefined;

  init({
    container,
    projection,
    view,
    center,
    zoom,
    bearing,
    pitch,
    minZoom,
    maxZoom,
    controls,
    locale,
    mapmlLocale,
    onFeatureLinkActivate
  }: RendererInitOptions): void {
    if (mapmlLocale) this.#mapmlLocale = mapmlLocale;
    this.#onFeatureLinkActivate = onFeatureLinkActivate;
    // Resolve the camera regime up front. `projection === 'GLOBE'` is a
    // deprecated alias the viewer already folds into `view`.
    const initialView = view ?? (projection === 'GLOBE' ? 'globe' : 'map');
    const profile = viewProfile(initialView);
    const opts: maplibregl.MapOptions = {
      container,
      // Set the projection through the initial style — calling
      // `map.setProjection` before the style has loaded throws
      // "Style is not done loading".
      style: { ...EMPTY_STYLE, projection: { type: profile.projection } },
      center,
      zoom,
      attributionControl: false
    };
    if (bearing !== undefined) opts.bearing = bearing;
    if (pitch !== undefined) opts.pitch = pitch;
    if (minZoom !== undefined) opts.minZoom = minZoom;
    if (maxZoom !== undefined) opts.maxZoom = maxZoom;
    // MapLibre-native locale map. Keys use MapLibre's internal
    // namespace (`NavigationControl.ZoomIn` etc.); values are the
    // MapML locale strings the viewer resolved for us. Passing this at
    // Map creation is the only supported hook — subsequent locale
    // changes don't propagate to already-mounted stock controls.
    if (locale) opts.locale = locale;
    const map = new maplibregl.Map(opts);

    // Disable MapLibre's stock keyboard handler so we can install a
    // MapML.js-parity replacement in the viewer. MapLibre's default
    // binds Shift+Arrow to pitch/bearing (rotate + tilt) and does
    // nothing on Ctrl+Arrow; MapML.js uses Shift+Arrow as a 3× pan
    // and Ctrl+Arrow as a 1/5 pan. The viewer's `#onCanvasKeyDown`
    // reimplements arrow-pan + `+`/`-` zoom on top of the stock
    // Space/Enter query trigger so all keyboard bindings live in
    // one place.
    map.keyboard.disable();

    this.#map = map;
    // Projection is already set via the initial style; apply only the
    // interaction locks (drag-rotate / touch-pitch) for this view, which
    // don't require the style to be loaded.
    this.#applyViewInteraction(profile);
    this.#ready = new Promise<void>((resolve) => {
      if (map.loaded()) {
        resolve();
      } else {
        map.once('load', () => resolve());
      }
    });

    // Stand up the keyboard-focus index alongside the map. The index
    // installs its DOM container immediately (between the canvas
    // container and the control container) so the tab order is set
    // correctly even before any `<map-feature>`s upload their
    // aggregated source.
    this.#featureFocusIndex = new FeatureFocusIndex(
      map,
      this.#mapmlLocale,
      (item, sourceProxy, lngLat) => {
        this.#openFeatureContentPopupAt(lngLat, [item.properties], 0, {
          sourceProxy,
          sourceItem: item
        });
      },
      // Caption tooltip on keyboard focus: mirror the mouse-hover
      // behaviour so sighted keyboard users see the same
      // `<map-featurecaption>` overlay screen-reader users get via
      // the proxy's `aria-label`. Renderer-side suppresses the
      // tooltip while the content popup is open (parity with the
      // hover path in `#updateFeaturePopupFromCursor`).
      (item, lngLat) => {
        if (item === null || lngLat === null) {
          this.#featurePopup?.remove();
          return;
        }
        if (this.#featureContentPopup?.isOpen()) return;
        if (item.caption === '') return;
        const currentMap = this.#map;
        if (!currentMap) return;
        this.#ensureFeaturePopup()
          .setLngLat(lngLat)
          .setText(item.caption)
          .addTo(currentMap);
      },
      // Enter / Space activation on a `<map-a>`-wrapped feature
      // dispatches through the viewer-supplied callback so the
      // renderer stays agnostic of `<mapml-viewer>` / `<map-layer>`.
      (item) => {
        this.#onFeatureLinkActivate?.(item);
      },
      // Close callback: the feature-index overlay activating a
      // popup-less feature dismisses any popup still open over the map.
      () => {
        this.#featureContentPopup?.remove();
      }
    );

    // Build the FeatureHandle environment: bound event handlers, a
    // focus-items publisher, and a "last composite gone" callback
    // that retracts shared hover / content popups. Reused by every
    // feature handle the factory produces.
    this.#featureEnv = {
      onFeatureEnter: this.#onFeatureEnter,
      onFeatureMove: this.#onFeatureMove,
      onFeatureLeave: this.#onFeatureLeave,
      onFeatureClick: this.#onFeatureClick,
      publishFocusItems: (id, items) => {
        // FocusItemDraft is opaque at the handle-side contract; the
        // real payload is `FeatureFocusItem[]` in this renderer.
        this.#featureFocusIndex?.setFeatureFocusItems(
          id,
          items as readonly FeatureFocusItem[]
        );
      },
      onLastCompositeRemoved: () => {
        this.#featurePopup?.remove();
        this.#featureContentPopup?.remove();
      },
      // A single composite going hidden (`<map-layer>` unchecked) or
      // removed retracts the feature popup it owns, so it can't
      // linger over a layer that just left the map. Query popups
      // (`#contentPopupSourceId === null`) are unaffected here \u2014 they
      // close via `closeQueryPopup`.
      onCompositeHidden: (sourceId: string) => {
        if (this.#contentPopupSourceId !== sourceId) return;
        this.#featurePopup?.remove();
        this.#featureContentPopup?.remove();
      }
    };

    // Controls are installed by the viewer once the renderer is ready,
    // so that custom controls (LayerControl, ReloadButton) get a stable
    // handle. The bare `controls` flag is left here as a no-op marker
    // for parity with the previous behaviour.
    void controls;
  }

  addControl(control: IControl, position?: ControlPosition): void {
    this.#requireMap().addControl(control, position);
  }

  removeControl(control: IControl): void {
    if (this.#map?.hasControl(control)) {
      this.#map.removeControl(control);
    }
  }

  setView(center: [number, number], zoom: number): void {
    this.#map?.jumpTo({ center, zoom });
  }

  applyViewMode(view: MapmlView): void {
    const map = this.#map;
    if (!map) return;
    const profile = viewProfile(view);
    // `setProjection` throws if the style isn't loaded yet (e.g. an
    // author calling `setView` synchronously on connect, before the
    // first `load`). Defer to the `load` event in that case; the
    // handler toggles (which don't need a loaded style) ride along.
    const apply = (): void => {
      map.setProjection({ type: profile.projection });
      this.#applyViewInteraction(profile);
    };
    if (map.isStyleLoaded()) apply();
    else map.once('load', apply);
  }

  /**
   * Enable / disable interactive rotation + tilt for a view profile.
   * Split out from {@link applyViewMode} because these handlers (unlike
   * `setProjection`) don't require the style to be loaded, so `init` can
   * call them synchronously right after map construction.
   *
   * Snapping the camera flat for non-tilt (`map`) views is *not* done
   * here — the caller ({@link MapmlViewer.setView} /
   * `#applyHistoryEntry`) folds `bearing: 0` / `pitch: 0` into its single
   * `jumpTo`, so a view switch fires exactly one `moveend` (a separate
   * `setBearing` / `setPitch` here would fire spurious extra ones that
   * desync history traversal).
   */
  #applyViewInteraction(profile: ReturnType<typeof viewProfile>): void {
    const map = this.#map;
    if (!map) return;
    if (profile.allowTilt) {
      map.dragRotate.enable();
      map.touchZoomRotate.enableRotation();
      map.touchPitch?.enable();
    } else {
      // `map` view is a true 2-D map: forbid interactive rotation / tilt.
      map.dragRotate.disable();
      map.touchZoomRotate.disableRotation();
      map.touchPitch?.disable();
    }
  }

  destroy(): void {
    this.#featurePopup?.remove();
    this.#featurePopup = undefined;
    this.#featureContentPopup?.remove();
    this.#featureContentPopup = undefined;
    this.#featureFocusIndex?.destroy();
    this.#featureFocusIndex = undefined;
    this.#popupSourceProxy = null;
    this.#popupSourceItem = null;
    this.#popupFeatures = [];
    this.#popupIndex = 0;
    this.#contentPopupIsQuery = false;
    this.#contentPopupSourceId = null;
    this.#map?.remove();
    this.#map = undefined;
    this.#ready = undefined;
  }

  whenReady(): Promise<void> {
    return this.#ready ?? Promise.reject(new Error('Renderer not initialised'));
  }

  // ── Factory API (returns handles) ─────────────────────────────────

  createRasterTileLayer(options: RasterTileLayerOptions): RendererLayer {
    return new MapLibreRasterTileHandle(this.#requireMap(), options);
  }

  createWmsTileLayer(options: WmsTileLayerOptions): RendererLayer {
    return new MapLibreWmsTileHandle(this.#requireMap(), options);
  }

  createMapTileRunLayer(
    options: MapTileRunLayerOptions
  ): MapTileRunRendererLayer {
    return new MapLibreMapTileRunHandle(this.#requireMap(), options);
  }

  createMapmlTileLayer(options: MapmlTileLayerOptions): MapmlTileRendererLayer {
    return new MapLibreMapmlTileHandle(this.#requireMap(), options);
  }

  createImageLayer(options: ImageLayerOptions): ImageRendererLayer {
    return new MapLibreImageHandle(this.#requireMap(), options);
  }

  createVectorTileLayer(options: VectorTileLayerOptions): RendererLayer {
    return new MapLibreVectorTileHandle(this.#requireMap(), options);
  }

  createFeatureCollectionLayer(
    options: FeatureCollectionLayerOptions
  ): FeatureRendererLayer {
    const map = this.#requireMap();
    if (!this.#featureEnv) {
      throw new Error('createFeatureCollectionLayer called before init()');
    }
    const handle = new MapLibreFeatureHandle(map, this.#featureEnv, options);
    // Apply any style cached before the handle existed. `setFeatureStyle`
    // may be called *before* the source's handle exists (element order
    // races); the cache carries the overrides across that gap.
    const cached = this.#featureStyleOverrides.get(options.id);
    if (cached) handle.setStyle(cached);
    return handle;
  }

  // ── Legacy id-keyed adapters (deleted in Stage 9) ─────────────────

  /**
   * Look up the handle previously stored by an id-keyed `add…Layer`
   * adapter. Used by transitional element shims
   * (`<map-extent>.registerChildLayer`, `<map-layer>.registerChildLayer`)
   * to translate id-based inputs into the handle-based `LayerGroup` API.
   * Returns `undefined` for an unknown id, matching MapLibre's own
   * lookup semantics.
   */
  getHandle(id: string): RendererLayer | undefined {
    return this.#legacyHandles.get(id);
  }

  addRasterTileLayer(options: RasterTileLayerOptions): void {
    if (this.#legacyHandles.has(options.id)) return; // idempotent
    const handle = this.createRasterTileLayer(options);
    this.#legacyHandles.set(options.id, handle);
  }

  addWmsTileLayer(options: WmsTileLayerOptions): void {
    if (this.#legacyHandles.has(options.id)) return;
    const handle = this.createWmsTileLayer(options);
    this.#legacyHandles.set(options.id, handle);
  }

  addImageLayer(options: ImageLayerOptions): void {
    if (this.#legacyHandles.has(options.id)) return;
    const handle = this.createImageLayer(options);
    this.#legacyHandles.set(options.id, handle);
  }

  updateImageLayer(id: string, update: ImageLayerUpdate): void {
    const handle = this.#legacyHandles.get(id);
    if (!handle || handle.kind !== 'image') return;
    (handle as ImageRendererLayer).update(update);
  }

  addOrUpdateFeatureCollection(options: FeatureCollectionLayerOptions): void {
    const existing = this.#legacyHandles.get(options.id);
    if (existing && existing.kind === 'feature-collection') {
      (existing as FeatureRendererLayer).setData(options.data);
      return;
    }
    const handle = this.createFeatureCollectionLayer(options);
    this.#legacyHandles.set(options.id, handle);
  }

  removeLayer(id: string): void {
    const handle = this.#legacyHandles.get(id);
    if (!handle) return;
    handle.remove();
    this.#legacyHandles.delete(id);
    // Match old behaviour: clear the style cache for this id so a later
    // re-use of the same composite id doesn't inherit stale styles.
    this.#featureStyleOverrides.delete(id);
  }

  moveLayer(id: string, beforeId?: string): void {
    const handle = this.#legacyHandles.get(id);
    if (!handle) return;
    if (beforeId === undefined) {
      handle.moveAbove();
      return;
    }
    const beforeHandle = this.#legacyHandles.get(beforeId);
    if (!beforeHandle) {
      handle.moveAbove();
      return;
    }
    // Old semantic: put `id` BENEATH `beforeId`. No current caller
    // exercises this branch (both applyLayerReorder + applyExtentReorder
    // pass no beforeId); implement best-effort by placing `id` on top,
    // then `beforeId` above it. Deleted in Stage 9 with the whole
    // legacy API.
    handle.moveAbove();
    beforeHandle.moveAbove(handle);
  }

  setLayerVisibility(id: string, visible: boolean): void {
    this.#legacyHandles.get(id)?.setVisible(visible);
  }

  setLayerOpacity(id: string, opacity: number): void {
    this.#legacyHandles.get(id)?.setOpacity(opacity);
  }

  setFeatureFocusItems(
    sourceId: string,
    items: readonly FeatureFocusItem[]
  ): void {
    this.#featureFocusIndex?.setFeatureFocusItems(sourceId, items);
  }

  setFeatureStyle(sourceId: string, overrides: PaintOverrides): void {
    // Cache overrides so a follow-up createFeatureCollectionLayer can
    // re-apply them. Empty bundles clear the cache so the fall-back to
    // the renderer's baseline defaults becomes permanent (matching
    // MapML.js's "drop the `<map-style>` block → revert paint" flow).
    const isEmpty =
      Object.keys(overrides.fill).length === 0 &&
      Object.keys(overrides.line).length === 0 &&
      Object.keys(overrides.circle).length === 0;
    if (isEmpty) {
      this.#featureStyleOverrides.delete(sourceId);
    } else {
      this.#featureStyleOverrides.set(sourceId, overrides);
    }
    const handle = this.#legacyHandles.get(sourceId);
    if (handle && handle.kind === 'feature-collection') {
      (handle as FeatureRendererLayer).setStyle(overrides);
    }
  }
  openContentPopup({
    lngLat,
    features,
    index = 0
  }: {
    lngLat: [number, number];
    features: ReadonlyArray<Record<string, unknown>>;
    index?: number;
  }): void {
    if (features.length === 0) return;
    const clamped = Math.min(Math.max(index, 0), features.length - 1);
    // Route through the same private opener the feature-click
    // handler uses. `source = null` gives it the "mouse-opened"
    // treatment \u2014 Escape / Tab-out returns focus to the map
    // canvas, not to a feature-focus proxy (there is no source
    // proxy for a query response).
    this.#openFeatureContentPopupAt(lngLat, features, clamped, null);
    // Mark this as a query popup so the viewer can dismiss it when a
    // contributing layer / extent is unchecked or removed.
    this.#contentPopupIsQuery = true;
    // Highlight only the feature currently shown in the popup, not the
    // whole aggregated result set — so as the user steps through the
    // `1/N` nav bar the highlight tracks the visible feature one at a
    // time (matching MapML.js's per-feature focus highlight). Covers
    // both MapML-fragment and GeoJSON responses — geometry arrives
    // pre-projected to GCRS on each feature's `highlightGeometries`.
    this.#refreshQueryHighlight();
  }

  /**
   * Dismiss the content popup only when it is currently showing a
   * `<map-link rel="query">` response. Called by the viewer when a
   * layer / extent that could have contributed to the query result is
   * unchecked or removed, so a stale query popup doesn't linger over
   * a layer that is no longer on the map. Static `<map-feature>` click
   * popups are left untouched (they close via their own composite
   * teardown / user dismissal).
   */
  closeQueryPopup(): void {
    if (!this.#contentPopupIsQuery) return;
    this.#contentPopupIsQuery = false;
    this.#featureContentPopup?.remove();
    this.#clearQueryHighlight();
  }

  /**
   * Source id + paint-layer id prefix for the transient query-result
   * highlight overlay. One shared source is reused across queries;
   * {@link #setQueryHighlight} replaces its data each time.
   */
  static readonly #QUERY_HIGHLIGHT_SOURCE = 'mapml-query-highlight';

  /**
   * Highlight only the feature currently shown in the query popup
   * (`#popupFeatures[#popupIndex]`). Called on popup open and after
   * each nav-bar step so the on-map highlight tracks the visible
   * feature one at a time rather than painting the whole aggregated
   * set at once. Clears the overlay when the current feature carries
   * no geometry (HTML / plain-text responses).
   */
  #refreshQueryHighlight(): void {
    const feature = this.#popupFeatures[this.#popupIndex];
    if (!feature) {
      this.#clearQueryHighlight();
      return;
    }
    this.#setQueryHighlight([feature]);
  }

  /**
   * Mount (or refresh) the query-result highlight overlay from the
   * `highlightGeometries` carried on the given popup feature(s).
   * Flattens their geometries into a single GeoJSON
   * `FeatureCollection` and paints it via a fill / line / circle
   * layer triple so polygons, lines, and points all show. Replaces
   * any previous highlight. A no-op (and a teardown of any prior
   * overlay) when no feature carries geometry — e.g. HTML /
   * plain-text GetFeatureInfo responses, which live in the popup only.
   */
  #setQueryHighlight(features: ReadonlyArray<Record<string, unknown>>): void {
    const map = this.#map;
    if (!map) return;
    const collected: GeoJSON.Feature[] = [];
    for (const f of features) {
      const geoms = f.highlightGeometries;
      if (!Array.isArray(geoms)) continue;
      for (const g of geoms as GeoJSON.Geometry[]) {
        collected.push({ type: 'Feature', geometry: g, properties: {} });
      }
    }
    if (collected.length === 0) {
      this.#clearQueryHighlight();
      return;
    }
    const data: GeoJSON.FeatureCollection = {
      type: 'FeatureCollection',
      features: collected
    };
    const sourceId = MapLibreRenderer.#QUERY_HIGHLIGHT_SOURCE;
    const apply = (): void => {
      const existing = map.getSource(sourceId);
      if (existing) {
        (existing as maplibregl.GeoJSONSource).setData(data);
      } else {
        map.addSource(sourceId, { type: 'geojson', data });
        map.addLayer({
          id: `${sourceId}-fill`,
          type: 'fill',
          source: sourceId,
          filter: ['==', ['geometry-type'], 'Polygon'],
          paint: { 'fill-color': '#ffff00', 'fill-opacity': 0.25 }
        });
        map.addLayer({
          id: `${sourceId}-line`,
          type: 'line',
          source: sourceId,
          filter: ['in', ['geometry-type'], ['literal', ['LineString', 'Polygon']]],
          paint: { 'line-color': '#ffcc00', 'line-width': 3 }
        });
        map.addLayer({
          id: `${sourceId}-circle`,
          type: 'circle',
          source: sourceId,
          filter: ['==', ['geometry-type'], 'Point'],
          paint: {
            'circle-radius': 6,
            'circle-color': '#ffff00',
            'circle-opacity': 0.6,
            'circle-stroke-color': '#ffcc00',
            'circle-stroke-width': 2
          }
        });
      }
      this.#queryHighlightActive = true;
    };
    if (map.isStyleLoaded()) apply();
    else map.once('idle', apply);
  }

  /**
   * Tear down the query-result highlight overlay (paint layers +
   * source). Idempotent — safe to call when nothing is highlighted.
   */
  #clearQueryHighlight(): void {
    if (!this.#queryHighlightActive) return;
    this.#queryHighlightActive = false;
    const map = this.#map;
    if (!map) return;
    const sourceId = MapLibreRenderer.#QUERY_HIGHLIGHT_SOURCE;
    for (const suffix of ['-fill', '-line', '-circle']) {
      const id = `${sourceId}${suffix}`;
      if (map.getLayer(id)) map.removeLayer(id);
    }
    if (map.getSource(sourceId)) map.removeSource(sourceId);
  }

  #onFeatureEnter = (e: maplibregl.MapLayerMouseEvent): void => {
    const map = this.#map;
    if (!map) return;
    map.getCanvas().style.cursor = 'pointer';
    // Defer to the shared painter-order pick so the topmost feature
    // wins when concentric layers overlap (e.g. a point on top of a
    // polygon fill — MapLibre fires `mouseenter` per layer with no
    // ordering guarantee, so we can't just use `e.features[0]`).
    this.#updateFeaturePopupFromCursor(e);
  };

  #onFeatureMove = (e: maplibregl.MapLayerMouseEvent): void => {
    this.#updateFeaturePopupFromCursor(e);
  };

  #onFeatureLeave = (e: maplibregl.MapLayerMouseEvent): void => {
    const map = this.#map;
    if (!map) return;
    // While the content popup is open the hover popup is suppressed
    // (see `#updateFeaturePopupFromCursor`); nothing to swap onto.
    // Reset the cursor + retract state so a subsequent close of the
    // content popup lands us in a clean baseline.
    if (this.#featureContentPopup?.isOpen()) {
      map.getCanvas().style.cursor = '';
      return;
    }
    // The pointer may still be inside a lower-stacked feature layer
    // (e.g. leaving a Point but still hovering the underlying Polygon
    // fill). Re-query and keep the popup up on that feature's caption
    // rather than blindly retracting.
    const picked = this.#pickTopFeatureAtCursor(e);
    if (picked !== null) {
      this.#featurePopup?.setLngLat(e.lngLat).setText(picked);
      return;
    }
    map.getCanvas().style.cursor = '';
    this.#featurePopup?.remove();
  };

  /**
   * Click handler for feature sub-layers. Opens a
   * `<map-properties>` popup for the topmost feature under the cursor
   * that carries one; when the top hit has no `<map-properties>`, no
   * popup is shown (matches MapML.js's `MapFeatureLayer.createGeometry`
   * where popup binding is gated on `feature.querySelector('map-properties')`).
   *
   * Static-feature clicks always yield a single-entry popup (`1/1`
   * counter, disabled prev/next). Matches MapML.js, where prev/next
   * are only meaningful for a `<map-link rel="identify">` server
   * response that returns multiple features for a single click —
   * static inline features in the DOM are addressed one-at-a-time.
   * The nav infrastructure (prev/next buttons, counter) is still
   * rendered so `|<` / `>|` remain reachable and the DOM shape stays
   * stable across the future `rel="identify"` port.
   *
   * MapLibre re-fires `click` per layer, but a single click over
   * three sub-layers only surfaces at most three events — the pick
   * pass in {@link #pickTopFeature} normalises them to the top hit,
   * so the popup opens exactly once regardless of geometry-role
   * overlap.
   */
  #onFeatureClick = (e: maplibregl.MapLayerMouseEvent): void => {
    const map = this.#map;
    if (!map) return;
    // Prefer a `<map-a>`-wrapped hit over a plain `<map-properties>`
    // hit when both are stacked under the cursor — matches MapML.js
    // where `attachLinkHandler`'s `mouseup` fires
    // `Util._handleLink` before the layer's own click-popup
    // binding (linked path is painted on top). When there's no
    // link under the cursor, fall through to the properties popup.
    const linkHit = this.#pickTopFeature(e, 'linkHref');
    if (linkHit !== null) {
      const item = this.#featureFocusIndex?.getItem(
        String(linkHit.source ?? ''),
        Number(linkHit.id ?? -1)
      );
      if (item !== undefined) {
        this.#onFeatureLinkActivate?.(item);
      }
      return;
    }
    const feature = this.#pickTopFeature(e, 'propertiesHtml');
    if (feature === null) return;
    this.#openFeatureContentPopupAt(
      e.lngLat,
      [feature.properties ?? {}],
      0,
      null
    );
    // Bind the popup to the composite it was opened from so it
    // retracts when that `<map-layer>` is unchecked / removed.
    this.#contentPopupSourceId =
      typeof feature.source === 'string' ? feature.source : null;
  };

  /**
   * Open the content-popup at `lngLat`, displaying entry `index`
   * from `features`. When `features.length > 1` the nav bar's
   * prev/next buttons cycle through the array; single-entry arrays
   * render as `1/1` with prev/next disabled \u2014 matches
   * MapML.js's static-feature behaviour for the ordinary
   * `<map-feature>` click path and its multi-feature behaviour for
   * `<map-link rel="query">` server responses.
   *
   * `source` is `null` for mouse-opens (Escape returns focus to the
   * canvas) or a `{ sourceProxy, sourceItem }` pair for keyboard-opens
   * (Escape / Tab-out returns focus to the source proxy element via
   * the feature-focus index). Matches MapML.js's
   * `_attachSkipButtons` behaviour: mouse clicks land back at
   * `map._container`; keyboard opens land back at the source `<g>`.
   */
  #openFeatureContentPopupAt(
    lngLat: maplibregl.LngLatLike,
    features: ReadonlyArray<Record<string, unknown>>,
    index: number,
    source: { sourceProxy: HTMLElement; sourceItem: FeatureFocusItem } | null
  ): void {
    const map = this.#map;
    if (!map) return;
    if (features.length === 0) return;
    // Retract the hover popup so it doesn't sit on top of the
    // content popup for the same feature.
    this.#featurePopup?.remove();
    const popup = this.#ensureFeatureContentPopup();
    // Switching from one open feature popup to another (index number
    // keys): MapLibre's `addTo` calls `remove()` first, firing a
    // transient `close` that would wipe the source state set below and
    // bounce the reticle. Suppress that one close so the switch is
    // seamless and Escape / focus-return bind to the new feature.
    if (popup.isOpen()) this.#suppressPopupCloseOnce = true;
    this.#popupSourceProxy = source?.sourceProxy ?? null;
    this.#popupSourceItem = source?.sourceItem ?? null;
    this.#popupFeatures = features;
    // Default to a non-query popup; `openContentPopup` flips this
    // flag back on after the shared opener runs for query responses.
    this.#contentPopupIsQuery = false;
    // Keyboard-opened feature popups carry their owning composite's
    // source id; the mouse-click path sets it after this call, query
    // popups leave it null.
    this.#contentPopupSourceId = source?.sourceItem.sourceId ?? null;
    this.#popupIndex = Math.min(Math.max(index, 0), features.length - 1);
    const content = this.#buildFeatureContentDom(
      features[this.#popupIndex]!,
      this.#popupIndex,
      features.length
    );
    popup.setLngLat(lngLat).setDOMContent(content).addTo(map);
  }

  /**
   * Advance the popup to a new entry within {@link #popupFeatures}
   * by `delta` (typically \u00b11). Rebuilds the popup content in
   * place; the same popup instance stays anchored to the click point
   * across navigation. Clamped to the array boundaries so the
   * disabled state of the prev/next buttons is meaningful
   * (`<` disabled at index 0, `>` disabled at the last entry).
   *
   * Called from the nav bar's `<` / `>` button click handlers built
   * by {@link #buildFeatureNavBar}. Focus returns to the
   * `.mapml-popup-content` wrapper after each navigation so a screen
   * reader re-announces the new heading + properties.
   */
  #navigateFeaturePopup(delta: number): void {
    const total = this.#popupFeatures.length;
    if (total < 2) return;
    const next = this.#popupIndex + delta;
    if (next < 0 || next >= total) return;
    this.#popupIndex = next;
    const popup = this.#featureContentPopup;
    if (!popup || !popup.isOpen()) return;
    const content = this.#buildFeatureContentDom(
      this.#popupFeatures[next]!,
      next,
      total
    );
    popup.setDOMContent(content);
    // Move the on-map highlight to the newly-shown feature so the
    // overlay tracks the popup one feature at a time.
    if (this.#contentPopupIsQuery) this.#refreshQueryHighlight();
    // Re-focus the same-direction nav button so keyboard users can
    // rapidly advance / retreat through the aggregated set without
    // having to Tab back to the nav bar each time. If that button
    // becomes disabled at the endpoint, fall through to the
    // opposite-direction button so focus stays inside the nav bar.
    const el = popup.getElement();
    el?.setAttribute('role', 'dialog');
    this.#focusPopupNavButton(el, delta > 0 ? 'next' : 'prev');
  }

  /**
   * Focus the same-direction nav button (`prev` or `next`) inside
   * the popup after {@link #navigateFeaturePopup} rebuilds the DOM.
   * MapML.js parity: the Prev/Next buttons are always enabled, so
   * focus can stay on the same button across successive Enter
   * presses; even at the endpoint the button remains focusable (the
   * click just no-ops via {@link #navigateFeaturePopup}'s bounds
   * check). No fallback needed since neither button ever becomes
   * disabled.
   */
  #focusPopupNavButton(
    el: HTMLElement | null | undefined,
    role: 'prev' | 'next'
  ): void {
    if (!el) return;
    el.querySelector<HTMLButtonElement>(
      `nav.mapml-focus-buttons button.mapml-popup-button[data-nav-role="${role}"]`
    )?.focus();
  }

  /**
   * Build the DOM tree used inside the feature content-popup. Shape
   * mirrors MapML.js's `MapLayer._attachSkipButtons` output:
   *
   *   <div class="mapml-popup-content" role="document" tabindex="-1">
   *     <h3>{caption or dfFeatureCaption}</h3>
   *     {propertiesHtml — verbatim from <map-properties>}
   *     <a class="mapml-zoom-link">Zoom to here</a>
   *     <hr class="mapml-popup-divider">
   *     <nav class="mapml-focus-buttons">
   *       <button>|&#10094;</button>   <!-- focus map -->
   *       <button>&#10094;</button>    <!-- previous feature -->
   *       <p>n/total</p>
   *       <button>&#10095;</button>    <!-- next feature -->
   *       <button>&#10095;|</button>   <!-- focus controls -->
   *     </nav>
   *   </div>
   *
   * The zoom-link is wired directly to `map.jumpTo` using the
   * per-feature `centerLng` / `centerLat` / `zoom` properties baked
   * in by {@link MapFeature.toGeoJsonFeatures}, so the popup pipeline
   * doesn't need to reach back into the DOM for a `<map-feature>`
   * element.
   *
   * `index` (0-based) + `total` drive the `n/total` counter. Prev /
   * next are always disabled today — MapML.js's parity behaviour is
   * that static inline features are addressed one-at-a-time, so
   * clicking a `<map-feature>` always yields `1/1`. Multi-feature
   * cycling is reserved for the future `<map-link rel="identify">`
   * response path where a single click legitimately produces N hits.
   */
  #buildFeatureContentDom(
    properties: Record<string, unknown>,
    index: number,
    total: number
  ): HTMLElement {
    const map = this.#requireMap();
    const wrapper = document.createElement('div');
    wrapper.className = 'mapml-popup-content';
    wrapper.setAttribute('role', 'document');
    wrapper.tabIndex = -1;

    // Heading = caption when present, else the locale's
    // dfFeatureCaption fallback (matches MapML.js's
    // `_geometryToLayer`'s `title` derivation).
    const caption = properties.caption;
    const heading = document.createElement('h3');
    heading.textContent =
      typeof caption === 'string' && caption !== ''
        ? caption
        : this.#mapmlLocale.dfFeatureCaption;
    wrapper.appendChild(heading);

    // Properties HTML — insertAdjacentHTML matches MapML.js's
    // `options.properties.insertAdjacentHTML('afterbegin', ...)`.
    // The HTML is author-controlled inline markup; no sanitizer is
    // applied (same trust model as MapML.js).
    const html = properties.propertiesHtml;
    if (typeof html === 'string' && html !== '') {
      const props = document.createElement('div');
      props.className = 'mapml-popup-properties';
      props.insertAdjacentHTML('afterbegin', html);
      wrapper.appendChild(props);
    }

    // Zoom-to-here link. Anchor `href` is a placeholder — clicks are
    // intercepted so the browser doesn't navigate.
    const centerLng = properties.centerLng;
    const centerLat = properties.centerLat;
    const zoom = properties.zoom;
    if (
      typeof centerLng === 'number' &&
      typeof centerLat === 'number' &&
      typeof zoom === 'number' &&
      Number.isFinite(centerLng) &&
      Number.isFinite(centerLat) &&
      Number.isFinite(zoom)
    ) {
      const zoomLink = document.createElement('a');
      zoomLink.className = 'mapml-zoom-link';
      zoomLink.href = `#${zoom},${centerLng},${centerLat}`;
      zoomLink.textContent = this.#mapmlLocale.popupZoom;
      const jump = (ev: Event): void => {
        ev.preventDefault();
        map.jumpTo({ center: [centerLng, centerLat], zoom });
        // Clear the source-proxy focus target so the popup's `close`
        // handler falls through to `map.getCanvas().focus()` instead
        // of returning focus to the feature that opened the popup.
        // After a jump the user's context is the new view, not the
        // original feature — and (for keyboard flow) the canvas
        // focus reveals the crosshair via the viewer's canvas
        // `focus` listener, matching the request in BEHAVIOURS.md
        // Q.23 that "when the user activates the zoom to here link
        // with the keyboard, the focus should remain on the map
        // with the crosshair displayed".
        this.#popupSourceProxy = null;
        this.#popupSourceItem = null;
        this.#featureContentPopup?.remove();
      };
      zoomLink.addEventListener('click', jump);
      zoomLink.addEventListener('keydown', (ev) => {
        if ((ev as KeyboardEvent).key === 'Enter') jump(ev);
      });
      wrapper.appendChild(zoomLink);
    }

    // Nav bar. Rendered even for a single-feature popup so the
    // "focus map" / "focus controls" affordances are always
    // reachable. Prev / next are disabled when total <= 1.
    const divider = document.createElement('hr');
    divider.className = 'mapml-popup-divider';
    wrapper.appendChild(divider);
    wrapper.appendChild(this.#buildFeatureNavBar(index, total));

    return wrapper;
  }

  /**
   * Build the `<nav class="mapml-focus-buttons">` element that sits at
   * the bottom of the feature-popup. Shape mirrors MapML.js's
   * `_attachSkipButtons`:
   *
   *   |<   <   n/total   >   >|
   *
   * `|<` closes the popup and focuses the map canvas.
   * `<` / `>` are disabled for static-feature popups (total === 1) —
   * MapML.js only enables cycling when a `<map-link rel="identify">`
   * response returns multiple features for a single click. Rendering
   * them (rather than omitting) keeps the popup DOM shape and layout
   * stable regardless of the popup source.
   * `>|` closes the popup and focuses the first control button.
   */
  #buildFeatureNavBar(index: number, total: number): HTMLElement {
    const map = this.#requireMap();
    const nav = document.createElement('nav');
    nav.className = 'mapml-focus-buttons';
    const safeTotal = total < 1 ? 1 : total;
    const current = Math.min(Math.max(index + 1, 1), safeTotal);

    const makeButton = (
      label: string,
      title: string,
      role: 'focus-map' | 'prev' | 'next' | 'focus-controls',
      onClick: () => void,
      disabled = false
    ): HTMLButtonElement => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-popup-button';
      btn.title = title;
      btn.setAttribute('aria-label', title);
      // `data-nav-role` is a portable hook for the popup 'open' focus
      // handler and {@link #navigateFeaturePopup} to re-focus the
      // correct nav button across DOM rebuilds without depending on
      // localised titles or DOM ordinal.
      btn.dataset.navRole = role;
      btn.disabled = disabled;
      const inner = document.createElement('span');
      inner.setAttribute('aria-hidden', 'true');
      inner.innerHTML = label;
      btn.appendChild(inner);
      btn.addEventListener('click', (ev) => {
        ev.preventDefault();
        onClick();
      });
      return btn;
    };

    nav.appendChild(
      makeButton('|&#10094;', this.#mapmlLocale.kbdFocusMap, 'focus-map', () => {
        // Opt out of the popup-close focus-restore (so the source
        // proxy isn't re-focused underneath us) and put focus on
        // the canvas.
        this.#popupSourceProxy = null;
        this.#popupSourceItem = null;
        this.#featureContentPopup?.remove();
        // MapLibre puts `tabindex="0"` on the canvas element (not its
        // container div), so that's the focusable target that restores
        // keyboard control to the map after popup interaction.
        map.getCanvas().focus();
      })
    );

    // Prev / next click handlers cycle through {@link #popupFeatures}.
    // MapML.js parity: the buttons are never `disabled`, at either
    // endpoint or when there's only one feature to view — the
    // clamping in {@link #navigateFeaturePopup} handles out-of-range
    // deltas as a no-op. Keeping the buttons focusable means a
    // keyboard user can hold Enter to walk to the endpoint and
    // focus stays on the same button when subsequent presses
    // become no-ops. See BEHAVIOURS.md Q.26.
    nav.appendChild(
      makeButton(
        '&#10094;',
        this.#mapmlLocale.kbdPrevFeature,
        'prev',
        () => this.#navigateFeaturePopup(-1)
      )
    );

    const counter = document.createElement('p');
    counter.className = 'mapml-feature-count';
    counter.textContent = `${current}/${safeTotal}`;
    nav.appendChild(counter);

    nav.appendChild(
      makeButton(
        '&#10095;',
        this.#mapmlLocale.kbdNextFeature,
        'next',
        () => this.#navigateFeaturePopup(1)
      )
    );

    nav.appendChild(
      makeButton('&#10095;|', this.#mapmlLocale.kbdFocusControls, 'focus-controls', () => {
        // Opt out of the popup-close focus-restore so the source
        // proxy isn't re-focused underneath us.
        this.#popupSourceProxy = null;
        this.#popupSourceItem = null;
        this.#featureContentPopup?.remove();
        // First-focusable-control fallback. MapML.js uses
        // `map._controlContainer.querySelector('A:not([hidden])')`,
        // which relies on Leaflet's `<a>`-based control buttons.
        // MapLibre uses `<button>`s, so query for the first
        // enabled control button and focus it.
        const firstControlBtn = map
          .getContainer()
          .querySelector<HTMLElement>(
            '.maplibregl-ctrl button:not([disabled])'
          );
        firstControlBtn?.focus();
      })
    );

    return nav;
  }

  #ensureFeatureContentPopup(): maplibregl.Popup {
    if (!this.#featureContentPopup) {
      this.#featureContentPopup = new maplibregl.Popup({
        closeButton: true,
        // MapML.js's popups close on Escape but stay open on a
        // map click that misses the feature; the closest MapLibre
        // opt-in is `closeOnClick: false` (author dismisses via the
        // close button or a subsequent feature click).
        closeOnClick: false,
        className: 'mapml-feature-content-popup',
        // Nudge the anchor up so a Point popup doesn't sit directly
        // on the cursor.
        offset: 12,
        // Cap popup width so a wide `<map-properties>` table (or a
        // WMS GetFeatureInfo iframe) can't push the popup past the
        // map bounds. MapLibre's stock default is 240px which is
        // too narrow to be readable; 340px matches MapML.js's
        // `map.getSize().x * 0.7` heuristic on a typical viewport.
        // The vertical bound is handled in featurePopup.css.ts so
        // the popup body scrolls internally, keeping the zoom-link
        // + nav bar always visible at the bottom.
        maxWidth: '340px',
        // Focus the popup on open so keyboard users don't have to
        // pan through the tab order to reach it. MapLibre focuses
        // the popup content wrapper (or the close button if that's
        // the first focusable), matching MapML.js's
        // `_attachSkipButtons` which calls `content.focus()`.
        focusAfterOpen: true
      });
      // The maplibregl popup container renders outside the shadow
      // root; role="dialog" on that container gives screen readers
      // the same landmark MapML.js sets in `_attachSkipButtons`.
      this.#featureContentPopup.on('open', () => {
        const el = this.#featureContentPopup?.getElement();
        if (!el) return;
        el.setAttribute('role', 'dialog');
        // MapLibre's `focusAfterOpen: true` picks the first focusable
        // descendant, which — with `closeButton: true` — is the close
        // button. MapML.js instead focuses the popup *content
        // wrapper* (a tabindex="-1" `<div>`) so screen readers
        // announce the heading first and the user can then Tab
        // forward to the properties table / zoom-link / nav bar.
        // Match MapML.js: initial focus always lands on the wrapper,
        // even for multi-feature aggregated popups — the user then
        // Tabs to the nav bar and Enters on Next / Prev to cycle,
        // at which point {@link #navigateFeaturePopup} keeps focus
        // on the same-direction button for fast repeat traversal.
        el.querySelector<HTMLElement>('.mapml-popup-content')?.focus();
        // Attach popup-scoped keyboard handling. Escape / Shift+Tab
        // out of the content wrapper / Tab out of the close button
        // all dismiss the popup and return focus to whoever opened
        // it (proxy for keyboard opens, canvas for mouse opens).
        // Matches MapML.js's `focusFeature` handler in
        // `_attachSkipButtons`.
        el.addEventListener('keydown', this.#onPopupKeyDown);
        // Notify the feature-index overlay so it can hide its reticle
        // behind the popup (the container is the shared element both
        // live in; the overlay listens for these events).
        this.#map
          ?.getContainer()
          .dispatchEvent(new CustomEvent('mapml:contentpopupopen'));
      });
      this.#featureContentPopup.on('close', () => {
        // A switch between two open feature popups fires a transient
        // `close` from MapLibre's `addTo` -> `remove()`; swallow it so
        // the source state just set for the incoming feature survives
        // and the reticle doesn't flash back on mid-switch.
        if (this.#suppressPopupCloseOnce) {
          this.#suppressPopupCloseOnce = false;
          return;
        }
        // Only steal focus back to the source when the popup was
        // dismissed while our proxy/canvas still expects it. If
        // focus has already moved elsewhere (e.g. the |< or >|
        // button ran its own `focus()` call), respect that
        // decision — the button handlers clear `#popupSourceProxy`
        // to opt out of the automatic restore.
        this.#returnPopupFocus();
        this.#popupSourceProxy = null;
        this.#popupSourceItem = null;
        this.#popupFeatures = [];
        this.#popupIndex = 0;
        this.#contentPopupIsQuery = false;
        this.#contentPopupSourceId = null;
        // A query popup's highlight overlay is tied to the popup's
        // lifetime — drop it on any dismissal (Escape, close button,
        // or a switch to a static feature popup).
        this.#clearQueryHighlight();
        // Restore the feature-index reticle now the popup is gone.
        this.#map
          ?.getContainer()
          .dispatchEvent(new CustomEvent('mapml:contentpopupclose'));
      });
    }
    return this.#featureContentPopup;
  }

  /**
   * Send focus back to whoever opened the popup. Keyboard opens go
   * to the source proxy (via the feature-focus index, so the sort
   * order can have shifted underneath us); mouse opens fall through
   * to the map canvas. No-op when neither is available (e.g. the
   * popup was dismissed programmatically after the map was destroyed).
   */
  #returnPopupFocus(): void {
    const map = this.#map;
    if (!map) return;
    const proxy = this.#popupSourceProxy;
    const item = this.#popupSourceItem;
    if (proxy !== null && item !== null && this.#featureFocusIndex) {
      const ok = this.#featureFocusIndex.focusProxyForItem(
        item.sourceId,
        item.featureId
      );
      if (ok) return;
      // Fallback: proxy no longer inbound after a pan/zoom while the
      // popup was open. Focus the canvas so the tab order keeps
      // ticking rather than dropping to `<body>`.
    }
    map.getCanvas().focus();
  }

  /**
   * Popup-scoped keydown handler. Wires the MapML.js-parity keyboard
   * dismiss semantics onto the MapLibre popup DOM:
   *
   *   - Escape          → close popup, return focus to opener.
   *   - Shift+Tab from  → close popup, return focus to opener (so
   *     the popup content   Shift+Tab out of the popup lands back at
   *     wrapper              the map/proxy, not at whatever precedes
   *                          the map in tab order).
   *   - Tab from the    → close popup, return focus to opener.
   *     close button       Matches MapML.js's `focusFeature` handler.
   *   - Enter on the    → close popup, return focus to opener (parity
   *     close button       with MapML.js).
   *
   * Any keys landing on internal focusable descendants (buttons,
   * zoom link) inside the popup are left alone — they need to
   * trigger their native activation (Enter fires click on buttons,
   * Space toggles buttons). The nav bar's `|<` / `>|` buttons
   * clear `#popupSourceProxy` themselves before running `focus()`
   * so the popup-close handler doesn't fight them for control.
   */
  #onPopupKeyDown = (ev: KeyboardEvent): void => {
    const key = ev.key;
    const target = ev.target;
    // Escape from anywhere inside the popup closes.
    if (key === 'Escape') {
      ev.preventDefault();
      ev.stopPropagation();
      this.#featureContentPopup?.remove();
      return;
    }
    if (!(target instanceof HTMLElement)) return;
    const isCloseButton = target.classList.contains('maplibregl-popup-close-button');
    // Shift+Tab out of the content wrapper leaves the popup — match
    // MapML.js which closes the popup and returns to the source.
    if (
      key === 'Tab' &&
      ev.shiftKey &&
      target.classList.contains('mapml-popup-content')
    ) {
      ev.preventDefault();
      ev.stopPropagation();
      this.#featureContentPopup?.remove();
      return;
    }
    // Tab off the close button (forward) is the other side of the
    // popup boundary — same treatment.
    if (isCloseButton && key === 'Tab' && !ev.shiftKey) {
      ev.preventDefault();
      ev.stopPropagation();
      this.#featureContentPopup?.remove();
      return;
    }
    // Enter on close button is parity with MapML.js (which
    // conditions on keycode 13 + close-button target).
    if (isCloseButton && key === 'Enter') {
      ev.preventDefault();
      ev.stopPropagation();
      this.#featureContentPopup?.remove();
      return;
    }
  };

  /**
   * Update (or open) the feature-caption popup with whatever the
   * topmost captioned feature under the cursor is. No-op when nothing
   * under the cursor carries a caption — MapLibre's own mouseleave
   * will retract the popup once the pointer clears every feature
   * layer.
   *
   * Suppressed entirely while the content popup is open, so the
   * hover tooltip doesn't paint over the click-popup's text (the
   * caption is already the popup's `<h3>` heading — a second copy
   * over the top would just obscure the properties body).
   */
  #updateFeaturePopupFromCursor(e: maplibregl.MapLayerMouseEvent): void {
    const map = this.#map;
    if (!map) return;
    if (this.#featureContentPopup?.isOpen()) {
      // Belt and braces — the content popup should have retracted
      // this one on open, but a stale mousemove could re-open it
      // between the click and the popup mounting into the DOM.
      this.#featurePopup?.remove();
      return;
    }
    const caption = this.#pickTopFeatureAtCursor(e);
    if (caption === null) return;
    this.#ensureFeaturePopup().setLngLat(e.lngLat).setText(caption).addTo(map);
  }

  /**
   * Query every registered feature sub-layer at the cursor and return
   * the topmost feature's caption. Preference order is
   * point (circle) → linestring (line) → polygon (fill), matching
   * MapML.js's Leaflet behaviour where marker DOM sits above vector
   * SVG and so wins the tooltip race even when a background polygon
   * covers the same pixel. Within each geometry role, painter order
   * still applies (later-added layer on top). Returns `null` when
   * nothing under the cursor carries a caption.
   */
  #pickTopFeatureAtCursor(e: maplibregl.MapLayerMouseEvent): string | null {
    const feature = this.#pickTopFeature(e, 'caption');
    const caption = feature?.properties?.caption;
    return typeof caption === 'string' && caption !== '' ? caption : null;
  }

  /**
   * Painter-order-aware feature pick at the given cursor point. Returns
   * the topmost hit whose `properties[requireProperty]` is a non-empty
   * string, or (when `requireProperty` is omitted) the first hit
   * regardless of properties. Preference order between geometry roles
   * is point (circle) → linestring (line) → polygon (fill), so a
   * small hit target isn't masked by a large polygon underneath it.
   */
  #pickTopFeature(
    e: maplibregl.MapLayerMouseEvent,
    requireProperty?: 'caption' | 'propertiesHtml' | 'linkHref'
  ): maplibregl.MapGeoJSONFeature | null {
    const map = this.#map;
    if (!map) return null;
    const roles: { circle: string[]; line: string[]; fill: string[] } = {
      circle: [],
      line: [],
      fill: []
    };
    for (const l of map.getStyle().layers) {
      const m = /:(fill|line|circle)$/.exec(l.id);
      if (!m) continue;
      roles[m[1] as 'fill' | 'line' | 'circle'].push(l.id);
    }
    for (const bucket of [roles.circle, roles.line, roles.fill]) {
      if (bucket.length === 0) continue;
      const hits = map.queryRenderedFeatures(e.point, { layers: bucket });
      for (const hit of hits) {
        if (requireProperty === undefined) return hit;
        const val = hit.properties?.[requireProperty];
        if (typeof val === 'string' && val !== '') return hit;
      }
    }
    return null;
  }

  #ensureFeaturePopup(): maplibregl.Popup {
    if (!this.#featurePopup) {
      this.#featurePopup = new maplibregl.Popup({
        closeButton: false,
        closeOnClick: false,
        className: 'mapml-feature-caption-popup',
        // Nudge the anchor up a hair so a point's tooltip doesn't
        // sit directly on the cursor and steal `mouseleave`. Matches
        // Leaflet's default tooltip offset for the top anchor.
        offset: 8
      });
    }
    return this.#featurePopup;
  }

  /** Escape hatch for early development; will be replaced by typed APIs. */
  get map(): MapLibreMap | undefined {
    return this.#map;
  }

  /**
   * The live feature data source for the feature-index a11y overlay
   * ({@link import('./FeatureIndexOverlay').FeatureIndexOverlay}). The
   * {@link FeatureFocusIndex} already tracks the inbound, in-zoom feature
   * set and implements {@link import('./FeatureIndexOverlay').FeatureIndexHost}.
   * `undefined` before {@link init}.
   */
  get featureIndexHost(): FeatureIndexHost | undefined {
    return this.#featureFocusIndex;
  }

  #requireMap(): MapLibreMap {
    if (!this.#map) {
      throw new Error('MapLibreRenderer.init() has not been called');
    }
    return this.#map;
  }
}

