import { LayerGroup, type LayerGroupOptions } from '../LayerGroup';

export interface MapmlLayerGroupOptions extends LayerGroupOptions {
  checked?: boolean;
  disabled?: boolean;
  hidden?: boolean;
}

/**
 * `LayerGroup` subclass carrying the MapML-spec `checked` / `disabled` /
 * `hidden` semantics that both `<map-layer>` and `<map-extent>` need.
 *
 * MapML separates "affects rendering" (checked + disabled) from
 * "affects LayerControl visibility" (hidden). This class implements
 * that split so the elements no longer duplicate the two-branch
 * predicate. Concretely:
 *   - `effectiveRendered()` ANDs `checked && !disabled` against every
 *     ancestor's own `checked && !disabled`. `hidden` is deliberately
 *     NOT consulted — per spec, hidden hides from the control but
 *     does not affect rendering.
 *   - `isRenderControlVisible()` is the LayerControl's "should this
 *     layer show up in the drawer?" predicate; it consults `hidden`
 *     and non-emptiness.
 *
 * Note on names: `rendered` here means "in the render list" (the
 * `checked && !disabled` cascade). Distinct from MapML.js's
 * `<map-link>.isVisible()` which is a bounds-intersects-viewport
 * predicate — that concept stays on `<map-link>` unchanged.
 *
 * Everything else (add / remove / opacity cascade / reorder) is
 * inherited unchanged from `LayerGroup`.
 */
export class MapmlLayerGroup extends LayerGroup {
  #checked: boolean;
  #disabled: boolean;
  #hidden: boolean;

  constructor(id: string, options: MapmlLayerGroupOptions = {}) {
    super(id, options);
    this.#checked = options.checked ?? true;
    this.#disabled = options.disabled ?? false;
    this.#hidden = options.hidden ?? false;
  }

  isChecked(): boolean {
    return this.#checked;
  }

  isDisabled(): boolean {
    return this.#disabled;
  }

  isHidden(): boolean {
    return this.#hidden;
  }

  /**
   * Layer-control-side visibility: shown when not hidden AND
   * the group contains at least one leaf.
   */
  isRenderControlVisible(): boolean {
    return !this.#hidden && !this.isEmpty();
  }

  /**
   * Own contribution to the render chain. Extends the base
   * primitive's `isRendered()` axis with MapML's `checked` +
   * `disabled` state. The base class's own `setRendered` remains
   * available but is not what MapML callers should use — they should
   * use `setChecked` / `setDisabled`.
   */
  override effectiveRendered(): boolean {
    if (!this.isRendered()) return false;
    if (!this.#checked) return false;
    if (this.#disabled) return false;
    const p = this.parent();
    if (p === null) return true;
    return p.effectiveRendered();
  }

  setChecked(value: boolean): void {
    if (this.#checked === value) return;
    this.#checked = value;
    this._recomputeEffectiveRendered();
  }

  setDisabled(value: boolean): void {
    if (this.#disabled === value) return;
    this.#disabled = value;
    this._recomputeEffectiveRendered();
  }

  setHidden(value: boolean): void {
    // hidden affects the LayerControl only, never the renderer.
    // Deliberately NO cascade — leaves must not receive
    // setVisible(false) when the author hides a layer.
    if (this.#hidden === value) return;
    this.#hidden = value;
  }
}
