import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import { M } from '../i18n/locale';
import type { MapmlViewer } from '../elements/mapml-viewer';

/**
 * `FeatureIndexControl` — top-right toggle button for the feature-index
 * accessibility overlay (the numbered "1..7" list of features overlapping
 * the map-centre reticle, ported in
 * {@link import('../renderer/FeatureIndexOverlay').FeatureIndexOverlay}).
 *
 * Opt-in via `controlslist="featureindex"` (default-off, like `view` /
 * `static`). Rendered in the `top-right` well, immediately below the
 * {@link StaticControl}. The icon is Material Symbols `campaign`
 * (megaphone), styled by `featureIndexControl.css`.
 *
 * The button drives the viewer's public {@link MapmlViewer.featureIndex}
 * property (never the overlay internals), and re-renders on the viewer's
 * `mapml:featureindexchanged` event — mirroring how {@link StaticControl}
 * drives `viewer.static` and listens for `mapml:staticchanged`.
 *
 * When the user / UA preference `M.options.featureIndexOverlayOption` forces
 * the state (`'on'` / `'off'`), the button reflects that pressed state but
 * renders `disabled` + `aria-disabled`, and clicking is a no-op: an
 * accessibility preference can't be overridden from the map UI.
 */
export class FeatureIndexControl implements IControl {
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  #icon: HTMLSpanElement | undefined;
  readonly #viewer: MapmlViewer;
  #onFeatureIndexChanged: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-right' {
    return 'top-right';
  }

  onAdd(_map: MapLibreMap): HTMLDivElement {
    const container = document.createElement('div');
    container.className =
      'maplibregl-ctrl maplibregl-ctrl-group mapml-feature-index-button';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';

    const icon = document.createElement('span');
    icon.className = 'mapml-feature-index-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    button.addEventListener('click', this.#onClick);

    container.appendChild(button);
    this.#container = container;
    this.#button = button;
    this.#icon = icon;

    const onChanged = (): void => this.#render();
    this.#onFeatureIndexChanged = onChanged;
    this.#viewer.addEventListener('mapml:featureindexchanged', onChanged);
    this.#render();
    return container;
  }

  onRemove(): void {
    if (this.#onFeatureIndexChanged) {
      this.#viewer.removeEventListener(
        'mapml:featureindexchanged',
        this.#onFeatureIndexChanged
      );
      this.#onFeatureIndexChanged = undefined;
    }
    this.#button?.removeEventListener('click', this.#onClick);
    this.#container?.remove();
    this.#container = undefined;
    this.#button = undefined;
    this.#icon = undefined;
  }

  #onClick = (event: MouseEvent): void => {
    event.stopPropagation();
    // A user / UA preference overrides the map UI: can't toggle when forced.
    if (M.options.featureIndexOverlayOption) return;
    // Drive the viewer through its public `featureIndex` setter; the
    // property owns the overlay lifecycle + change event.
    this.#viewer.featureIndex = !this.#viewer.featureIndex;
  };

  /** Sync the label + pressed / disabled state to the viewer's state. */
  #render(): void {
    if (!this.#button) return;
    const forced = M.options.featureIndexOverlayOption !== undefined;
    const active = this.#viewer.featureIndex;
    const label = this.#viewer.locale.btnFeatureIndex;
    this.#button.title = label;
    this.#button.setAttribute('aria-label', label);
    this.#button.setAttribute('aria-pressed', String(active));
    this.#button.disabled = forced;
    if (forced) this.#button.setAttribute('aria-disabled', 'true');
    else this.#button.removeAttribute('aria-disabled');
  }
}
