import type * as maplibregl from 'maplibre-gl';
import type { Map as MapLibreMap } from 'maplibre-gl';
import type { MapmlViewer } from '../elements/mapml-viewer';
import {
  OSMTILE_TILE_SIZE,
  osmtileGcrsToPcrs,
  osmtilePcrsToGcrs,
  osmtilePcrsToTcrs,
  osmtileTilematrixToPcrs
} from '../core/crs';

/** GeoJSON source id backing the layer / total / projection-centre boxes. */
const VECTORS_SOURCE = 'mapml-debug-vectors';
const FILL_LAYER = 'mapml-debug-vectors-fill';
const LINE_LAYER = 'mapml-debug-vectors-line';
const CENTER_LAYER = 'mapml-debug-vectors-center';

/**
 * Per-layer box colours, cycled in registration order. Matches the
 * palette MapML.js's `DebugVectors._addBounds` uses so screenshots
 * line up across implementations.
 */
const BOX_COLORS = ['#FF5733', '#8DFF33', '#3397FF', '#E433FF', '#F3FF33'];

/**
 * Debug overlay for `<mapml-viewer>`, ported from MapML.js's
 * `src/mapml/layers/DebugOverlay.js`.
 *
 * Three surfaces, toggled together:
 *
 *   1. **Bounding boxes** (the point of the overlay): one GeoJSON
 *      rectangle per on-screen (checked, non-disabled) `<map-layer>`,
 *      drawn from that layer's `extent.topLeft.gcrs` /
 *      `bottomRight.gcrs` corners, plus a grey union-of-all-layers
 *      "total bounds" box and a projection-centre marker at `0,0`.
 *      Rebuilt on `mapml:layerschanged`; the boxes are static in
 *      geographic space so MapLibre reprojects them on pan/zoom for
 *      free (no `moveend` rebuild needed).
 *
 *   2. **Tile grid**: a self-drawn OSMTILE (256 px) grid — one
 *      positioned `<div>` per visible tile, labelled `col,row,zoom` —
 *      computed at the OSMTILE zoom MapLibre is actually rendering
 *      (`round(mapZoom) + 1`; see {@link DebugOverlay.osmtileZoom}).
 *      MapLibre's built-in `showTileBoundaries` is deliberately
 *      avoided: it walks MapLibre's 512 px base-tile pyramid and
 *      labels tiles in that scheme, so it never agrees with the MapML
 *      OSMTILE tilematrix. Drawing our own grid from the same CRS
 *      helpers and the same zoom as the panel keeps the two
 *      consistent, like MapML.js's `DebugGrid`.
 *
 *   3. **Coordinate panel**: a `<table>` mounted inside the map
 *      container (below the controls) that echoes the pointer position
 *      in every MapML CRS — tile `i,j`, map `i,j`, gcrs `lon,lat`,
 *      tcrs `x,y`, tilematrix `col,row`, pcrs `easting,northing` —
 *      updated on `mousemove`, matching MapML.js's `DebugPanel`.
 *
 * Reachable today only through the map context menu's "Toggle Debug
 * Mode" item (and its `D` shortcut).
 */
export class DebugOverlay {
  readonly #viewer: MapmlViewer;
  #panel: HTMLTableElement | null = null;
  #rows: Record<string, HTMLTableRowElement> = {};
  #grid: HTMLDivElement | null = null;
  #enabled = false;

  #onMouseMove: (e: maplibregl.MapMouseEvent) => void;
  #onMove: () => void;
  #onLayersChanged: () => void;
  #onViewChanged: () => void;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
    this.#onMouseMove = (e) => this.#updateCoords(e);
    this.#onMove = () => this.#updateGrid();
    this.#onLayersChanged = () => this.#refreshBounds();
    this.#onViewChanged = () => this.#updateGrid();
  }

  get enabled(): boolean {
    return this.#enabled;
  }

  enable(): void {
    if (this.#enabled) return;
    const map = this.#viewer.renderer.map;
    if (!map) return;
    this.#enabled = true;

    this.#buildGrid(map);
    this.#buildPanel(map);
    this.#updateGrid();
    this.#refreshBounds();

    map.on('mousemove', this.#onMouseMove);
    map.on('move', this.#onMove);
    this.#viewer.addEventListener('mapml:layerschanged', this.#onLayersChanged);
    // Switching view can change the projection (globe) without emitting a
    // `move`, so re-evaluate grid suppression on the viewer's own signal.
    this.#viewer.addEventListener('mapml:viewchanged', this.#onViewChanged);
  }

  disable(): void {
    if (!this.#enabled) return;
    this.#enabled = false;
    const map = this.#viewer.renderer.map;

    if (map) {
      map.off('mousemove', this.#onMouseMove);
      map.off('move', this.#onMove);
      this.#teardownBounds(map);
    }
    this.#viewer.removeEventListener('mapml:layerschanged', this.#onLayersChanged);
    this.#viewer.removeEventListener('mapml:viewchanged', this.#onViewChanged);

    this.#grid?.remove();
    this.#grid = null;
    this.#panel?.remove();
    this.#panel = null;
    this.#rows = {};
  }

  toggle(): void {
    if (this.#enabled) this.disable();
    else this.enable();
  }

  /**
   * (Re)build the GeoJSON source + fill / line / circle layers that
   * draw the per-layer boxes, the total-bounds box, and the
   * projection-centre marker.
   */
  #refreshBounds(): void {
    const map = this.#viewer.renderer.map;
    if (!map || !this.#enabled) return;
    if (!map.isStyleLoaded()) {
      map.once('idle', () => this.#refreshBounds());
      return;
    }

    const data = this.#buildBoundsFeatures();
    const existing = map.getSource(VECTORS_SOURCE) as
      | maplibregl.GeoJSONSource
      | undefined;
    if (existing) {
      existing.setData(data);
      // Layers added since the overlay was enabled (a newly checked
      // `<map-layer>`) stack above ours, so re-raise the debug layers
      // to keep the boxes visible on top.
      for (const id of [FILL_LAYER, LINE_LAYER, CENTER_LAYER]) {
        if (map.getLayer(id)) map.moveLayer(id);
      }
      return;
    }

    map.addSource(VECTORS_SOURCE, { type: 'geojson', data });
    map.addLayer({
      id: FILL_LAYER,
      type: 'fill',
      source: VECTORS_SOURCE,
      filter: ['==', ['geometry-type'], 'Polygon'],
      paint: {
        'fill-color': ['get', 'color'],
        'fill-opacity': 0.05
      }
    });
    map.addLayer({
      id: LINE_LAYER,
      type: 'line',
      source: VECTORS_SOURCE,
      filter: ['==', ['geometry-type'], 'Polygon'],
      paint: {
        'line-color': ['get', 'color'],
        'line-width': ['case', ['==', ['get', 'kind'], 'total'], 5, 2],
        'line-opacity': ['case', ['==', ['get', 'kind'], 'total'], 0.5, 1]
      }
    });
    map.addLayer({
      id: CENTER_LAYER,
      type: 'circle',
      source: VECTORS_SOURCE,
      filter: ['==', ['get', 'kind'], 'center'],
      paint: {
        'circle-radius': 6,
        'circle-color': '#3388ff',
        'circle-opacity': 0.4,
        'circle-stroke-color': '#3388ff',
        'circle-stroke-width': 2
      }
    });
  }

  #teardownBounds(map: MapLibreMap): void {
    for (const id of [FILL_LAYER, LINE_LAYER, CENTER_LAYER]) {
      if (map.getLayer(id)) map.removeLayer(id);
    }
    if (map.getSource(VECTORS_SOURCE)) map.removeSource(VECTORS_SOURCE);
  }

  #buildBoundsFeatures(): GeoJSON.FeatureCollection {
    const features: GeoJSON.Feature[] = [];
    let west = Infinity;
    let south = Infinity;
    let east = -Infinity;
    let north = -Infinity;
    let colorIndex = 0;

    for (const layer of this.#viewer.layers) {
      if (!layer.checked || layer.disabled) continue;
      const extent = layer.extent;
      if (!extent) continue;
      const w = extent.topLeft.gcrs.horizontal;
      const n = extent.topLeft.gcrs.vertical;
      const e = extent.bottomRight.gcrs.horizontal;
      const s = extent.bottomRight.gcrs.vertical;

      features.push(
        this.#rectangle(w, s, e, n, {
          kind: 'layer',
          color: BOX_COLORS[colorIndex % BOX_COLORS.length]!,
          label: layer.label
        })
      );
      colorIndex += 1;

      west = Math.min(west, w);
      east = Math.max(east, e);
      south = Math.min(south, s);
      north = Math.max(north, n);
    }

    // Grey union-of-all-checked-layers box, matching MapML.js's
    // `map.totalLayerBounds` outline.
    if (colorIndex > 0 && Number.isFinite(west)) {
      features.push(
        this.#rectangle(west, south, east, north, {
          kind: 'total',
          color: '#808080'
        })
      );
    }

    // Projection centre at PCRS 0,0 (GCRS 0,0 for OSMTILE).
    features.push({
      type: 'Feature',
      properties: { kind: 'center', color: '#3388ff' },
      geometry: { type: 'Point', coordinates: [0, 0] }
    });

    return { type: 'FeatureCollection', features };
  }

  #rectangle(
    west: number,
    south: number,
    east: number,
    north: number,
    properties: Record<string, unknown>
  ): GeoJSON.Feature {
    return {
      type: 'Feature',
      properties,
      geometry: {
        type: 'Polygon',
        coordinates: [
          [
            [west, north],
            [east, north],
            [east, south],
            [west, south],
            [west, north]
          ]
        ]
      }
    };
  }

  /**
   * Mount the coordinate panel inside the map container, *before* the
   * MapLibre control container so it stacks below the controls.
   */
  #buildPanel(map: MapLibreMap): void {
    const table = document.createElement('table');
    table.className = 'mapml-debug';

    const caption = document.createElement('caption');
    caption.className = 'mapml-debug-banner';
    caption.textContent = 'Debug mode';
    table.appendChild(caption);

    const tbody = document.createElement('tbody');
    tbody.className = 'mapml-debug-panel';
    for (const key of ['tile', 'map', 'tcrs', 'tilematrix', 'pcrs', 'gcrs']) {
      const tr = document.createElement('tr');
      tr.className = 'mapml-debug-coordinates';
      tbody.appendChild(tr);
      this.#rows[key] = tr;
    }
    table.appendChild(tbody);

    const container = map.getContainer();
    const ctrlContainer = container.querySelector(
      '.maplibregl-control-container'
    );
    if (ctrlContainer) container.insertBefore(table, ctrlContainer);
    else container.appendChild(table);
    this.#panel = table;
  }

  /**
   * Mount the (empty) tile-grid container inside the map container,
   * *before* the MapLibre control container so it stacks below the
   * controls. Tiles are populated by {@link #updateGrid} on `move`.
   */
  #buildGrid(map: MapLibreMap): void {
    const grid = document.createElement('div');
    grid.className = 'mapml-debug-grid';
    const container = map.getContainer();
    const ctrlContainer = container.querySelector(
      '.maplibregl-control-container'
    );
    if (ctrlContainer) container.insertBefore(grid, ctrlContainer);
    else container.appendChild(grid);
    this.#grid = grid;
  }

  /**
   * Integer OSMTILE (256 px) zoom level whose native resolution best
   * matches the current display — i.e. the tile level MapLibre is
   * actually rendering. MapLibre's zoom is defined against 512 px base
   * tiles, so a 256 px OSMTILE source renders one level finer:
   * `z_osmtile = round(mapZoom) + 1`. (Empirically: mapZoom 2 → OSM
   * z3, 4 → z5, 5 → z6.) Both the grid and the coordinate panel use
   * this so their `col,row,zoom` always agree with each other and with
   * the tiles on screen.
   */
  #osmtileZoom(map: MapLibreMap): number {
    return Math.max(0, Math.round(map.getZoom()) + 1);
  }

  /**
   * The self-drawn tile grid only makes sense for a flat, top-down
   * mercator camera: each tile is drawn as an axis-aligned rectangle
   * from its NW / SE corners, which only holds with no globe
   * projection, pitch, or bearing. In `globe` / `perspective` views
   * (or any manually tilted / rotated camera) the tiles warp into
   * quads the rectangles can't track, so the grid is suppressed rather
   * than drawn wrong. The GeoJSON bounding boxes and coordinate panel
   * stay live in every view.
   */
  #gridSupported(map: MapLibreMap): boolean {
    const isGlobe = map.getProjection?.()?.type === 'globe';
    return !isGlobe && map.getPitch() === 0 && map.getBearing() === 0;
  }

  /**
   * Redraw the OSMTILE grid for the current view. One `<div>` per
   * visible tile at zoom {@link #osmtileZoom}, positioned by projecting
   * each tile's NW / SE corners through MapLibre. On-screen tiles stay
   * in the ~180–360 px range, so the visible-tile count is small; a
   * hard cap guards pathological cases. Suppressed in tilted / globe
   * views (see {@link #gridSupported}).
   */
  #updateGrid(): void {
    const grid = this.#grid;
    const map = this.#viewer.renderer.map;
    if (!grid || !map) return;

    if (!this.#gridSupported(map)) {
      grid.innerHTML = '';
      return;
    }

    const zoom = this.#osmtileZoom(map);
    const n = 2 ** zoom;

    const cornerTile = (lng: number, lat: number): [number, number] => {
      const [x, y] = osmtileGcrsToPcrs(lng, lat);
      const t = osmtilePcrsToTcrs(x, y, zoom);
      return [
        Math.floor(t.horizontal / OSMTILE_TILE_SIZE),
        Math.floor(t.vertical / OSMTILE_TILE_SIZE)
      ];
    };

    const b = map.getBounds();
    const clampLat = (v: number): number => Math.max(-85.05, Math.min(85.05, v));
    const [colMin, rowMin] = cornerTile(b.getWest(), clampLat(b.getNorth()));
    const [colMax, rowMax] = cornerTile(b.getEast(), clampLat(b.getSouth()));

    const lo = (v: number): number => Math.max(0, Math.min(n - 1, v));
    const c0 = lo(Math.min(colMin, colMax));
    const c1 = lo(Math.max(colMin, colMax));
    const r0 = lo(Math.min(rowMin, rowMax));
    const r1 = lo(Math.max(rowMin, rowMax));

    let html = '';
    let drawn = 0;
    const MAX_TILES = 400;
    for (let col = c0; col <= c1 && drawn < MAX_TILES; col++) {
      for (let row = r0; row <= r1 && drawn < MAX_TILES; row++) {
        const nw = this.#tileCornerPoint(map, col, row, zoom);
        const se = this.#tileCornerPoint(map, col + 1, row + 1, zoom);
        const left = Math.round(nw.x);
        const top = Math.round(nw.y);
        const width = Math.round(se.x - nw.x);
        const height = Math.round(se.y - nw.y);
        html +=
          `<div class="mapml-debug-tile" style="left:${left}px;top:${top}px;` +
          `width:${width}px;height:${height}px">` +
          `col: ${col}, row: ${row}, zoom: ${zoom}</div>`;
        drawn++;
      }
    }
    grid.innerHTML = html;
  }

  #tileCornerPoint(
    map: MapLibreMap,
    col: number,
    row: number,
    zoom: number
  ): { x: number; y: number } {
    const [px, py] = osmtileTilematrixToPcrs(col, row, zoom);
    const [lng, lat] = osmtilePcrsToGcrs(px, py);
    return map.project([lng, lat]);
  }

  #updateCoords(e: maplibregl.MapMouseEvent): void {
    if (!this.#panel) return;
    if (this.#viewer.contextMenuOpen) return;

    const { lng, lat } = e.lngLat;
    const zoom = this.#osmtileZoom(e.target as MapLibreMap);
    const [x, y] = osmtileGcrsToPcrs(lng, lat);
    const tcrs = osmtilePcrsToTcrs(x, y, zoom);

    let tileI = tcrs.horizontal % OSMTILE_TILE_SIZE;
    let tileJ = tcrs.vertical % OSMTILE_TILE_SIZE;
    if (tileI < 0) tileI += OSMTILE_TILE_SIZE;
    if (tileJ < 0) tileJ += OSMTILE_TILE_SIZE;

    this.#rows.tile!.innerHTML = `
      <th scope="row">tile: </th>
      <td>i: ${Math.trunc(tileI)}, </td>
      <td>j: ${Math.trunc(tileJ)}</td>`;
    this.#rows.map!.innerHTML = `
      <th scope="row">map: </th>
      <td>i: ${Math.trunc(e.point.x)}, </td>
      <td>j: ${Math.trunc(e.point.y)}</td>`;
    this.#rows.tcrs!.innerHTML = `
      <th scope="row">tcrs: </th>
      <td>x: ${Math.trunc(tcrs.horizontal)}, </td>
      <td>y: ${Math.trunc(tcrs.vertical)}</td>`;
    this.#rows.tilematrix!.innerHTML = `
      <th scope="row">tilematrix: </th>
      <td>column: ${Math.trunc(tcrs.horizontal / OSMTILE_TILE_SIZE)}, </td>
      <td>row: ${Math.trunc(tcrs.vertical / OSMTILE_TILE_SIZE)}</td>`;
    this.#rows.pcrs!.innerHTML = `
      <th scope="row">pcrs: </th>
      <td>easting: ${x.toFixed(2)}, </td>
      <td>northing: ${y.toFixed(2)}</td>`;
    this.#rows.gcrs!.innerHTML = `
      <th scope="row">gcrs: </th>
      <td>lon: ${lng.toFixed(6)}, </td>
      <td>lat: ${lat.toFixed(6)}</td>`;
  }
}
