import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapmlViewer } from '../elements/mapml-viewer';
import { nextView, type MapmlView } from '../core/view';

/**
 * `ViewControl` — cycles `<mapml-viewer>` between its presentation modes.
 *
 * Opt-in via `controlslist="view"` (default-off, like `search` /
 * `geolocation`). Rendered in the `top-right` well, immediately below the
 * LayerControl. A single button shows the current view's icon; activating
 * it advances to the next mode in the cycle `map → globe → perspective →
 * map` by assigning the viewer's live {@link MapmlViewer.view} setter.
 *
 * The button stays in sync with programmatic / history-driven view changes
 * by listening for the viewer's `mapml:viewchanged` event.
 *
 * Icons: each state renders a `<span class="mapml-view-button-icon
 * mapml-view-icon-{map|globe|perspective}">`. The unicode glyphs below are
 * placeholders — override `.mapml-view-icon-*` with `background-image` (and
 * `font-size: 0`) in author CSS to drop in real icons.
 */
export class ViewControl implements IControl {
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  #icon: HTMLSpanElement | undefined;
  readonly #viewer: MapmlViewer;
  #onViewChanged: (() => void) | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
  }

  getDefaultPosition(): 'top-right' {
    return 'top-right';
  }

  onAdd(_map: MapLibreMap): HTMLDivElement {
    const container = document.createElement('div');
    container.className = 'maplibregl-ctrl maplibregl-ctrl-group mapml-view-button';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-button';

    const icon = document.createElement('span');
    icon.className = 'mapml-view-button-icon';
    icon.setAttribute('aria-hidden', 'true');
    button.appendChild(icon);
    button.addEventListener('click', this.#onClick);

    container.appendChild(button);
    this.#container = container;
    this.#button = button;
    this.#icon = icon;

    const onViewChanged = (): void => this.#render();
    this.#onViewChanged = onViewChanged;
    this.#viewer.addEventListener('mapml:viewchanged', onViewChanged);
    this.#render();
    return container;
  }

  onRemove(): void {
    if (this.#onViewChanged) {
      this.#viewer.removeEventListener('mapml:viewchanged', this.#onViewChanged);
      this.#onViewChanged = undefined;
    }
    this.#button?.removeEventListener('click', this.#onClick);
    this.#container?.remove();
    this.#container = undefined;
    this.#button = undefined;
    this.#icon = undefined;
  }

  #onClick = (event: MouseEvent): void => {
    event.stopPropagation();
    // Drive the viewer through its public `view` setter: the control
    // states intent ("next mode"), the viewer owns the mechanics.
    this.#viewer.view = nextView(this.#viewer.view);
  };

  /** Sync the icon + label to the viewer's current view. */
  #render(): void {
    if (!this.#button || !this.#icon) return;
    const view = this.#viewer.view;
    const locale = this.#viewer.locale;
    // Reset per-state classes, then apply the current one.
    this.#icon.className = `mapml-view-button-icon mapml-view-icon-${view}`;
    this.#icon.textContent = VIEW_GLYPH[view];
    const name = VIEW_LABEL[view](locale);
    const upcoming = VIEW_LABEL[nextView(view)](locale);
    const label = `${locale.btnView}: ${name} (${upcoming})`;
    this.#button.title = label;
    this.#button.setAttribute('aria-label', label);
  }
}

/**
 * Text glyph per view. Every view now renders a real icon via the CSS
 * `background-image` on its `.mapml-view-icon-*` class, so the text is blank
 * (authors can still override the background-image).
 */
const VIEW_GLYPH: Record<MapmlView, string> = {
  map: '',
  globe: '',
  perspective: ''
};

/** Localized display name per view. */
const VIEW_LABEL: Record<MapmlView, (locale: MapmlViewer['locale']) => string> = {
  map: (l) => l.viewMap,
  globe: (l) => l.viewGlobe,
  perspective: (l) => l.viewPerspective
};
