/**
 * MapML projection identifiers, partitioned by whether the MapLibre renderer
 * can actually draw them.
 *
 * MapLibre GL JS exposes only three projection identifiers (`mercator`,
 * `globe`, `vertical-perspective`) and accepts tile sources in the Web
 * Mercator (EPSG:3857) grid only — `globe` and `vertical-perspective` are
 * camera transforms over Mercator data, not separate tile grids. The
 * Leaflet-based MapML.js additionally supports `WGS84`, `CBMTILE` and
 * `APSTILE` because Leaflet allows arbitrary CRS plug-ins; MapLibre does
 * not, and there is no public API for registering a non-Mercator tile grid.
 *
 * Authors targeting `WGS84`/`CBMTILE`/`APSTILE` should provide a
 * `<map-link rel="alternate" projection="OSMTILE" href="…">` so the viewer
 * can negotiate to a Mercator equivalent. Until that negotiation is wired
 * in (see TODO.md), the viewer warns and falls back to `OSMTILE`.
 */

/** Projections the MapLibre renderer can actually draw. */
export const MAPML_PROJECTIONS = ['OSMTILE', 'GLOBE'] as const;

export type MapmlProjection = (typeof MAPML_PROJECTIONS)[number];

export function isMapmlProjection(value: string): value is MapmlProjection {
  return (MAPML_PROJECTIONS as readonly string[]).includes(value);
}

/**
 * Projections defined by MapML.js / the MapML vocabulary but **not** drawable
 * by this MapLibre-backed viewer. Recognising these by name lets the viewer
 * emit an actionable warning (pointing at `rel="alternate"`) instead of the
 * generic "Undefined projection" message reserved for truly unknown names.
 */
export const MAPML_RENDERER_UNSUPPORTED_PROJECTIONS = [
  'WGS84',
  'CBMTILE',
  'APSTILE'
] as const;

export type UnsupportedMapmlProjection =
  (typeof MAPML_RENDERER_UNSUPPORTED_PROJECTIONS)[number];

export function isUnsupportedMapmlProjection(
  value: string
): value is UnsupportedMapmlProjection {
  return (MAPML_RENDERER_UNSUPPORTED_PROJECTIONS as readonly string[]).includes(value);
}
