export const viewControlCss = /* css */ `
.mapml-view-button button.mapml-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  padding: 0;
  color: #333;
}

.mapml-view-button .mapml-view-button-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  font-size: 24px;
  line-height: 1;
  background-position: center;
  background-repeat: no-repeat;
  background-size: 24px 24px;
}

.mapml-view-button .mapml-view-icon-map {
  /* Real icon via background-image; hide any residual text node. */
  font-size: 0;
  background-image: ${MAP_SVG_URL};
}

.mapml-view-button .mapml-view-icon-globe {
  font-size: 0;
  background-image: ${GLOBE_SVG_URL};
}

.mapml-view-button .mapml-view-icon-perspective {
  font-size: 0;
  background-image: ${PERSPECTIVE_SVG_URL};
}
`;

