import {
  formatPcrsExtent,
  projectionMaxZoom,
  projectionPcrsBounds,
  unionPcrsBounds,
  type MapmlExtent,
  type PcrsBounds
} from '../core/crs';
import {
  parseExtentMeta,
  parseZoomMeta,
  type ExtentMeta,
  type ZoomMeta
} from '../core/mapMeta';
import {
  mapml2geojson,
  type Mapml2GeojsonFeatureCollection,
  type Mapml2GeojsonOptions
} from '../core/mapml2geojson';
import { shadowCrossingClosestByTag, type ContentRoot } from '../core/shadow';
import { MapExtent } from './map-extent';
import { MapFeature } from './map-feature';
import { MapLink } from './map-link';
import { MapTitle } from './map-title';
import type { MapMeta } from './map-meta';
import type { MapmlViewer } from './mapml-viewer';
import { nextControlId, settingsGearSvg } from '../controls/layerControlDom';
import { installDragToReorder } from '../controls/layerControlDrag';
import type { Locale } from '../i18n/locale';
import type { FeatureFocusItem } from '../renderer/FeatureFocusIndex';
// Explicit `import type * as GeoJSON` (rather than relying on the
// UMD `export as namespace GeoJSON` global) so VS Code's TS server
// with `verbatimModuleSyntax: true` reliably resolves the namespace
// inside this module. CLI tsc succeeds either way; the editor is
// stricter about ambient globals inside modules.
import type * as GeoJSON from 'geojson';
import {
  compileMapStyle,
  type CompiledRule
} from '../core/mapStyleCompiler';
import { compilePaintOverrides } from '../core/paintExpressions';
import type { PaintOverrides } from '../core/paintExpressions';
import { MapmlLayerGroup } from '../core/mapml/MapmlLayerGroup';
import type { GroupChild } from '../core/LayerGroup';
import type { FeatureRendererLayer } from '../core/RendererHandles';
/** Monotonic id source for `<map-layer>`'s internal `MapmlLayerGroup`. */
let nextLayerGroupId = 0;

/**
 * Contract satisfied by every element that contributes CSS text to
 * a `<map-layer>`'s aggregated style. Currently just `<map-style>`;
 * `<map-link rel="stylesheet">` will implement the same shape once
 * Track D lands.
 */
export interface StyleContributor {
  readonly cssText: string;
  readonly isActive: boolean;
}

/**
 * Extent surface for `<map-layer>` \u2014 the same multi-CRS envelope
 * MapML.js exposes on `<map-layer>.extent`. See {@link MapmlExtent} in
 * `src/core/crs.ts` for the field layout. Kept as a re-export under
 * the historical `LayerExtent` name for backward compatibility with
 * existing callers.
 */
export type LayerExtent = MapmlExtent;

/** Monotonic id source for per-layer GeoJSON feature-collection sources. */
let nextFeatureLayerId = 0;

/**
 * `<map-layer>` — author-visible toggleable layer in the map.
 *
 * Acts as a logical grouping for `<map-extent>` children (and, later,
 * `<map-style>`, `<map-meta>`, …). Visibility of any renderer layers
 * registered by descendant `<map-link>` elements follows
 * `checked && !hidden` on this element ANDed with the same on the
 * owning `<map-extent>`.
 *
 * The `<mapml-viewer controls>` LayerControl reads the `label` attribute
 * and the `checked` state, and toggles `checked` when the user clicks.
 */
export class MapLayer extends HTMLElement {
  static readonly observedAttributes = ['checked', 'label', 'hidden', 'opacity', 'disabled', 'src', 'media'] as const;

  /**
   * Internal {@link MapmlLayerGroup} that owns:
   *   - direct-child renderer leaves registered via {@link registerChildLayer}
   *     (the `<map-link>`s directly under this `<map-layer>` with no
   *     `<map-extent>` ancestor — a rare / legacy authoring path);
   *   - each child `<map-extent>`'s own group (attached in
   *     `MapExtent.connectedCallback`), so opacity + rendered-state
   *     compose multiplicatively through the tree;
   *   - the aggregated feature-collection composite handle
   *     ({@link #featureHandle}) when at least one `<map-feature>`
   *     is registered.
   *
   * `MapmlLayerGroup.effectiveRendered()` ANDs `checked && !disabled`
   * against every ancestor's own `checked && !disabled`. This layer
   * only ever calls `setChecked` (its own `disabled` axis is
   * intentionally left at the group's default `false`): a layer
   * being disabled marks the fieldset stylistically but doesn't
   * suppress rendering — matches MapML.js's `map-layer._validateDisabled`,
   * where `disabled` is a control-side badge rather than a render gate.
   */
  #group = new MapmlLayerGroup(`map-layer-${++nextLayerGroupId}`);

  /**
   * Handle for this layer's aggregated GeoJSON feature composite.
   * `null` until the first `<map-feature>` register triggers a
   * non-empty rebuild in {@link #rebuildFeatures}. Torn down + set
   * back to `null` when the last feature leaves. Owned directly
   * (bypasses `renderer.#legacyHandles`) — nobody looks up feature
   * composites by id anymore.
   */
  #featureHandle: FeatureRendererLayer | null = null;
  /**
   * Whether the layer-control settings drawer is expanded. Persisted
   * on the element so a mid-interaction rebuild (e.g. `<map-select>`
   * change firing `notifyLayersChanged`) doesn't slam the drawer
   * shut. Same rationale as `MapExtent.#settingsExpanded`.
   */
  #settingsExpanded = false;

  /**
   * Bound listener for the `changestyle` `CustomEvent` dispatched by
   * a descendant `<map-link rel="style">`'s layer-control radio
   * button (see `MapLink.#applyStyle`). Sets this layer's `src`
   * attribute to the chosen URL, which triggers
   * `attributeChangedCallback` → {@link #loadRemote}. Matches
   * MapML.js's `_onAdd` handler in `src/layer.js` that pipes the
   * same event into `this.src = e.detail.src`.
   *
   * Retained as a bound function so `disconnectedCallback` can
   * `removeEventListener` with the exact same identity.
   */
  #changeStyleListener = (e: Event): void => {
    const detail = (e as CustomEvent<{ src?: string }>).detail;
    const src = detail?.src;
    if (typeof src !== 'string' || src === '') return;
    e.stopPropagation();
    this.setAttribute('src', src);
  };
  /**
   * Cached at connect-time. Once `disconnectedCallback` runs the element
   * is already detached from the DOM, so `this.closest('mapml-viewer')`
   * returns `null` — we'd otherwise silently fail to unregister.
   */
  #owningViewer: MapmlViewer | null = null;
  /**
   * Set while `validateDisabled` is writing the `disabled` attribute
   * so the observer doesn't re-enter the tally. External writes still
   * fall through to the observer, where they get overwritten by the
   * next validation pass — the attribute is a read-only reflection of
   * `validateDisabled`, matching MapML.js.
   */
  #writingDisabled = false;

  /**
   * Live matcher returned by {@link MapmlViewer.matchMedia} while the
   * `media` attribute is populated. `null` when the attribute is
   * absent / empty / whitespace-only, or before the initial async
   * registration completes. Owned by this layer; disposed in
   * {@link #teardownMediaQuery}.
   */
  #mql: MediaQueryList | null = null;
  /**
   * Bound change handler shared across the `#mql` lifetime. Retained
   * so `removeEventListener` sees the same identity used at
   * registration time — MediaQueryList keys listeners by identity.
   */
  #mqlChangeHandler: (() => void) | null = null;
  /**
   * Monotonic token bumped on every {@link #registerMediaQuery} call.
   * When {@link MapmlViewer.whenReady} resolves we bail if the token
   * has since moved — protects against a stale async registration
   * clobbering a fresher `media` value or a disconnect.
   */
  #mqlRegisterToken = 0;
  /**
   * Whether the `media` query currently matches. Default `true` when
   * the attribute is absent / empty / whitespace-only (matches
   * unconditionally, mirroring MapML.js's "no / empty media
   * attribute matches" branch). When `false`, the layer is REALLY
   * disabled — unregistered from the viewer (out of the layer
   * control) and detached from `renderer.root` (nothing paints) —
   * matching MapML.js's `<map-layer>._registerMediaQuery` +
   * `_onRemove` / `_onAdd` cycle.
   */
  #mediaMatches = true;
  /**
   * `true` while {@link #deactivateForMedia} has torn the layer off
   * the viewer + renderer root. Guards against
   * `#activateForMedia` doing redundant work when the layer is
   * already active, and vice versa. Distinct from `#mediaMatches`
   * so a fresh (never-activated) element doesn't run the
   * activate branch spuriously.
   */
  #mediaDeactivated = false;

  /**
   * Direct `<map-feature>` children currently tracked for the layer's
   * aggregated GeoJSON source. `<map-feature>` calls
   * {@link registerFeature} on connect and {@link unregisterFeature}
   * on disconnect. All features under this layer share a single
   * MapLibre GeoJSON source + fill / line / circle sub-layers, matching
   * MapML.js's `MapFeatureLayer` (one Leaflet layer per `<map-layer>`).
   */
  #features = new Set<MapFeature>();
  /** Microtask coalescing flag for {@link notifyFeaturesChanged}. */
  #featuresChangeScheduled = false;

  /**
   * `<map-style>` (and future `<map-link rel="stylesheet">`)
   * contributors under this layer's subtree. Each contributor
   * registers on connect and unregisters on disconnect; the layer
   * aggregates their compiled rules and pushes a
   * {@link PaintOverrides} bundle to the renderer via
   * {@link ../renderer/MapRenderer.setFeatureStyle}.
   *
   * Insertion order matches registration order, which (for elements
   * connected during initial parse) matches DOM order — CSS cascade
   * "later wins for equal specificity" falls out naturally from the
   * compiled `["case", …]` walking the rules in registration order.
   */
  #styles = new Set<StyleContributor>();
  /** Microtask coalescing flag for {@link notifyStylesChanged}. */
  #stylesChangeScheduled = false;

  /**
   * Monotonic token for the current in-flight remote fetch. Every new
   * `#loadRemote` bumps this and captures the value; when the fetch
   * resolves, we bail out if the layer has since started a newer
   * load. Prevents stale grafts when `src` is thrashed in quick
   * succession.
   */
  #remoteLoadToken = 0;

  /**
   * `true` when the last `#loadRemote` failed (network error, non-2xx,
   * parse error, or missing `<mapml->` root). Exposed only so tests
   * and callers can detect the error state without listening for the
   * `error` event.
   */
  #fetchError = false;

  /**
   * Counter for consecutive projection-alternate re-fetches during
   * one `#loadRemote` chain. Reset on any successful non-alternate
   * load. Bumped by {@link #selectAlternate}; aborts with a
   * `console.warn` when it exceeds `#MAX_ALT_REDIRECTS`.
   */
  #altRedirects = 0;
  static readonly #MAX_ALT_REDIRECTS = 3;

  /**
   * Attach the shadow root lazily on the first `src` load rather
   * than eagerly in the constructor. `<map-layer>` without `src`
   * keeps its light-DOM authoring model unchanged — no shadow root
   * means no compositional surprises for surrounding controls (an
   * always-attached empty shadow root subtly disturbs some
   * MapLibre-native re-render paths). Once `src` is set,
   * {@link #loadRemote} attaches the shadow root before grafting
   * and never detaches it (attachShadow is one-shot); subsequent
   * `src` removals just clear the shadow content.
   *
   * `mode: 'open'` so external JS / tests can inspect the grafted
   * content via `layer.shadowRoot`.
   */
  #ensureShadowRoot(): ShadowRoot {
    return this.shadowRoot ?? this.attachShadow({ mode: 'open' });
  }

  get viewer(): MapmlViewer | null {
    return (
      this.#owningViewer ??
      (shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null)
    );
  }

  /**
   * The DOM subtree hosting this layer's MapML children.
   *
   *   * When the layer carries a `src` attribute (remote-content
   *     mode), returns the shadow root — which is where a fetched
   *     MapML doc's `<map-head>` / `<map-body>` children are
   *     grafted (see {@link src}). The shadow root is attached
   *     lazily on the first fetch (see {@link #ensureShadowRoot});
   *     during the pre-fetch window this getter returns the
   *     element itself (which has no children yet).
   *   * Otherwise returns the element itself — the light-DOM case
   *     used by inline authoring.
   *
   * Matches MapML.js's `this.src ? this.shadowRoot : this` idiom in
   * `src/layer.js`. All child-walking code paths (extent iteration,
   * own-`<map-meta>` lookup, layer-scoped `<map-link>` traversal,
   * license attribution extraction, …) go through this getter so
   * remote and inline content behave identically.
   */
  get contentRoot(): ContentRoot {
    if (this.hasAttribute('src') && this.shadowRoot) return this.shadowRoot;
    return this;
  }

  /**
   * `src` URL of the remote MapML document, or `null` when the layer
   * carries inline `<map-extent>` / `<map-feature>` children.
   *
   * Setting `src` clears any grafted content, then fetches the given
   * URL with `Accept: text/mapml`, parses the response as XML, and
   * adopts every direct child of `<map-head>` / `<map-body>` into the
   * layer's shadow root. Errors (non-2xx, network, parse, missing
   * `<mapml->` root) suppress the graft and dispatch an `error` event
   * on the layer; other layers keep rendering.
   *
   * Setting `src` to `null` removes the attribute and tears down any
   * previously grafted content.
   */
  get src(): string | null {
    return this.getAttribute('src');
  }
  set src(value: string | null) {
    if (value === null) this.removeAttribute('src');
    else this.setAttribute('src', value);
  }

  /**
   * Read-only reflection: `true` when the last remote fetch failed.
   * Cleared to `false` on the next successful load. Test-only surface.
   */
  get fetchError(): boolean {
    return this.#fetchError;
  }

  get checked(): boolean {
    return this.hasAttribute('checked');
  }

  set checked(value: boolean) {
    if (value) this.setAttribute('checked', '');
    else this.removeAttribute('checked');
  }

  /**
   * Read-only reflection of the `disabled` attribute. Set only by
   * {@link MapLayer.validateDisabled}; author writes get overwritten
   * on the next validation pass. Matches MapML.js's
   * `map-layer.disabled` semantics: `true` when every non-hidden
   * `<map-extent>` child is disabled (and the layer has at least one
   * such extent).
   */
  get disabled(): boolean {
    return this.hasAttribute('disabled');
  }

  /**
   * The current `media` attribute value, or empty string when absent.
   * When non-empty, the layer is gated by a {@link MediaQueryList}
   * the viewer builds via {@link MapmlViewer.matchMedia}: whenever
   * the query does not match, the layer is REALLY disabled — the
   * `disabled` attribute is set (as a state marker), the layer is
   * removed from the layer control (via
   * `viewer.unregisterLayer`), and its group is detached from
   * `renderer.root` (so nothing paints). `src=` fetches are aborted
   * via the standard `#remoteLoadToken` bump. Mirrors MapML.js's
   * `<map-layer>._registerMediaQuery` / `_onRemove` / `_onAdd`.
   *
   * Setting the empty string / null / undefined removes the
   * attribute — matches the setter used by `<map-link>` and
   * `<map-style>`.
   */
  get media(): string {
    return this.getAttribute('media') ?? '';
  }
  set media(value: string) {
    if (value === '' || value === null || value === undefined) {
      this.removeAttribute('media');
    } else {
      this.setAttribute('media', value);
    }
  }

  get label(): string {
    // `<map-title>` inside the layer's content root wins over the
    // author's `label` attribute — matches MapML.js's precedence:
    // remote-doc `<map-title>` → `label` attr → locale default.
    // Applies uniformly to inline authoring (unusual) and to remote
    // content (typical).
    //
    // Walk children directly instead of using `:scope > map-title`;
    // `ShadowRoot.querySelector(':scope > …')` isn't universally
    // supported (the spec's `:scope` reference-node semantics for
    // shadow roots are underspecified in some engines) whereas
    // `.children` iteration is safe.
    for (const child of this.contentRoot.children) {
      if (child.tagName.toLowerCase() !== 'map-title') continue;
      if (child instanceof MapTitle) {
        const v = child.value;
        if (v !== null) return v;
      }
      // Fallback for the pre-upgrade window: read `textContent`
      // directly. Rare (customElement upgrade normally beats the
      // first `label` read) but the guard is cheap.
      const raw = child.textContent?.trim();
      if (raw !== undefined && raw.length > 0) return raw;
    }
    // Fall back to the localized default (`dfLayer`) so authors who omit
    // `label` see the same string MapML.js would show. `viewer` is null
    // between construction and connectedCallback, in which case we
    // return the English literal — matches the pre-locale behaviour.
    return this.getAttribute('label') ?? this.viewer?.locale.dfLayer ?? 'Layer';
  }

  /**
   * Absolute URL of a legend document advertised by a `<map-link
   * rel="legend">` inside this layer's {@link contentRoot}, or
   * `null` when none is present (or the declared href fails
   * sanitization).
   *
   * Mirrors MapML.js's `parseLicenseAndLegend()` in
   * `src/mapml/layers/MapLayer.js`: pick the first
   * `<map-link rel="legend">` under the layer, take its `href`
   * attribute, and expose it as the destination for the
   * layer-control row's title anchor
   * (see {@link getLayerControlHTML}). The link may be authored
   * inline as a direct child of `<map-layer>` (light-DOM) or
   * grafted into the layer's shadow root from a fetched MapML
   * doc's `<map-head>` (remote mode) — {@link contentRoot} unifies
   * both cases.
   *
   * Base-URL resolution matches `<map-link>#getBaseUrl`: when the
   * layer is in remote mode (`src` attribute present) relative
   * hrefs resolve against the fetched doc's URL; otherwise against
   * the host page's `baseURI`. Only `http:` / `https:` (or
   * relatives that resolve to one of those) survive
   * sanitization — `javascript:`, `data:`, `blob:`, `file:` and
   * any other scheme are rejected at parse time so the layer-
   * control row cannot become a script injection vector.
   */
  get legendUrl(): string | null {
    // Walk direct children of `contentRoot` for the first
    // `<map-link rel="legend">`. Iteration (rather than a
    // `:scope > map-link[rel="legend"]` selector) mirrors the
    // {@link label} getter's compatibility guard: `ShadowRoot`'s
    // `querySelector(':scope > …')` isn't universally supported
    // because `:scope`'s reference-node semantics for shadow roots
    // are under-specified. `.children` iteration is safe on both
    // the remote-content shape (children of the shadow root grafted
    // from `<map-head>`) and the inline shape (light-DOM children
    // of `<map-layer>`). Deeper links (inside a `<map-extent>`,
    // say) are intentionally ignored — they're not the layer's
    // legend.
    for (const child of this.contentRoot.children) {
      if (child.tagName.toLowerCase() !== 'map-link') continue;
      if (child.getAttribute('rel') !== 'legend') continue;
      const rawHref = child.getAttribute('href');
      if (rawHref === null || rawHref === '') return null;
      return sanitizeLegendHref(rawHref, this.#legendBaseUrl());
    }
    return null;
  }

  /**
   * Base URL for resolving a `<map-link rel="legend">`'s `href`.
   * Mirrors `<map-link>#getBaseUrl` for the layer scope: when this
   * layer is running in remote mode, resolve against the fetched
   * doc's URL (so a relative legend href in the remote doc points
   * at the remote server); otherwise resolve against the host
   * page's `baseURI`. Kept private — external callers should
   * consume {@link legendUrl} which returns an already-resolved,
   * already-sanitized URL.
   */
  #legendBaseUrl(): string {
    const src = this.getAttribute('src');
    if (src !== null && src !== '') {
      try {
        return new URL(src, this.baseURI).href;
      } catch {
        // Fall through to the page baseURI on a malformed src.
      }
    }
    return this.baseURI;
  }

  /**
   * Parsed `<map-meta name="extent">` content as PCRS bounds (already
   * reprojected from whichever CS the author used) plus an optional
   * pinned zoom, or `null` when no such direct-child meta exists.
   *
   * Looks only at *direct-child* `<map-meta>` of this layer, never the
   * viewer's nor a `<map-extent>`'s. Reprojection uses the viewer's
   * projection when the layer is attached; before connect (or when a
   * projection isn't yet resolvable) the parser is called with a
   * safe `OSMTILE` default.
   */
  get extentMeta(): ExtentMeta | null {
    const m = this.contentRoot.querySelector(
      ':scope > map-meta[name="extent"]'
    ) as MapMeta | null;
    if (m === null) return null;
    return parseExtentMeta(m.content, this.viewer?.projection ?? 'OSMTILE');
  }

  /**
   * Parsed `<map-meta name="zoom">` content (`{ min, max }`), or `null`
   * when absent / malformed. Used by descendant `<map-link rel="tile">`
   * to constrain the renderer source's `minzoom` / `maxzoom`.
   */
  get zoomMeta(): ZoomMeta | null {
    const m = this.contentRoot.querySelector(
      ':scope > map-meta[name="zoom"]'
    ) as MapMeta | null;
    if (m === null) return null;
    return parseZoomMeta(m.content);
  }

  /**
   * The multi-CRS extent envelope for this layer (matches MapML.js's
   * `<map-layer>.extent`).
   *
   * Derivation:
   *   - **bounds**: seeded from this layer's own
   *     `<map-meta name="extent">` (decoded in whichever CS the
   *     author wrote), then extended with each child `<map-extent>`'s
   *     PCRS bounds and each direct-child `<map-feature>`'s PCRS
   *     bbox. When nothing contributes at all, the whole projection
   *     extent is used \u2014 matching MapML.js's `_calculateBounds`,
   *     which starts from `Util.getBoundsFromMeta(...)` and calls
   *     `bnds.extend(...)` for each `<map-extent>` and each
   *     `MapFeatureLayer`.
   *   - **zoom**: seeded from own `<map-meta name="zoom">`, then
   *     extended by each `<map-extent>`'s zoom range. When nothing
   *     contributes, `{ minZoom: 0, maxZoom: 24 }` (the projection's
   *     native range) is used.
   *
   * Returns `null` only when the layer isn't yet attached to a viewer
   * (mirrors MapML.js's `<map-layer>.extent` return of `null` when
   * `this._layer` is unset).
   */
  get extent(): LayerExtent | null {
    const projection = this.viewer?.projection;
    if (projection === undefined) return null;

    // Seed from own `<map-meta name="extent">` / `<map-meta name="zoom">`
    // so child `<map-extent>` and `<map-feature>` contributions
    // *extend* the meta bounds instead of masking them. Matches
    // `Util.getBoundsFromMeta` seeding in MapML.js's `_calculateBounds`.
    const em = this.extentMeta;
    const zm = this.zoomMeta;
    let pcrs: PcrsBounds | null = em?.bounds ?? null;
    let zoom: { minZoom: number; maxZoom: number } | null =
      zm !== null ? { minZoom: zm.min, maxZoom: zm.max } : null;
    for (const ext of this.#extents()) {
      const contribPcrs = (ext as MapExtent).pcrsBounds;
      if (contribPcrs !== null) {
        pcrs = pcrs === null ? contribPcrs : unionPcrsBounds(pcrs, contribPcrs);
      }
      const contribZoom = (ext as MapExtent).zoomRange;
      if (contribZoom !== null) {
        zoom =
          zoom === null
            ? { ...contribZoom }
            : {
                minZoom: Math.min(zoom.minZoom, contribZoom.minZoom),
                maxZoom: Math.max(zoom.maxZoom, contribZoom.maxZoom)
              };
      }
    }
    // Fold in any direct-child `<map-feature>` bounds. Matches
    // MapML.js's `_calculateBounds`, which unions `MapFeatureLayer`
    // bounds into `<map-layer>.extent` alongside the extents'.
    for (const feature of this.#features) {
      const fpcrs = feature.pcrsBounds;
      if (fpcrs === null) continue;
      pcrs = pcrs === null ? fpcrs : unionPcrsBounds(pcrs, fpcrs);
    }
    if (pcrs === null) pcrs = projectionPcrsBounds(projection);
    if (zoom === null) zoom = { minZoom: 0, maxZoom: projectionMaxZoom(projection) };
    return formatPcrsExtent(pcrs, projection, zoom);
  }

  get opacity(): number {
    return this.#group.getOpacity();
  }

  /**
   * Reflect the numeric opacity back to the `opacity` attribute so
   * `element.opacity = 0.5` and `element.setAttribute('opacity', '0.5')`
   * both round-trip through the same code path. Out-of-range values are
   * ignored to match MapML.js's setter contract.
   */
  set opacity(value: number) {
    const n = Number(value);
    if (!Number.isFinite(n) || n < 0 || n > 1) return;
    this.setAttribute('opacity', String(n));
  }

  /**
   * Set opacity (0..1) for every renderer layer registered under this
   * `<map-layer>`. Under the tree-native cascade, extent groups are
   * children of this layer's group, so a single `#group.setOpacity`
   * multiplies through each extent's own opacity (and each extent's
   * own leaves) — matching MapML.js Leaflet's DOM-CSS opacity
   * nesting behaviour (layer=0.5, extent=0.5 → 0.25 effective).
   */
  setOpacity(value: number): void {
    const clamped = Math.max(0, Math.min(1, Number.isFinite(value) ? value : 1));
    this.#group.setOpacity(clamped);
  }

  /**
   * Public getter for this layer's internal {@link MapmlLayerGroup}.
   * Exposed so `MapmlViewer.applyLayerReorder` can restack renderer
   * layers by reordering group children, and `MapExtent` can attach
   * its own group under this one. Return type is widened to the
   * subclass so callers who need the MapML-shape `setChecked` /
   * `setDisabled` / `setHidden` axes can reach them without a
   * downcast. Prefer this over the transitional `renderedLayerIds()`
   * iterator for new code.
   */
  get group(): MapmlLayerGroup {
    return this.#group;
  }

  /**
   * Register a `<map-link>` child that lives directly under this
   * `<map-layer>` (no `<map-extent>` ancestor — rare / legacy path).
   * Looks up the handle stored by the renderer's id-keyed adapter
   * and adds it to {@link #group}. `<map-extent>` also calls this
   * for legacy compatibility, but its own extent-scoped group is
   * the primary storage for extent-scoped links; see Stage 8.
   */
  registerChildLayer(id: string): void {
    const handle = this.viewer?.renderer.getHandle(id);
    if (handle === undefined) return;
    if (this.#group.hasLayer(handle)) return;
    this.#group.addLayer(handle);
  }

  unregisterChildLayer(id: string): void {
    for (const leaf of this.#group.children()) {
      if (leaf.id === id) {
        this.#group.removeLayer(leaf);
        break;
      }
    }
  }

  /**
   * Register a `<map-feature>` child so its geometry contributes to
   * this layer's aggregated GeoJSON source. Called by
   * `<map-feature>.connectedCallback`. Schedules a rebuild via
   * {@link notifyFeaturesChanged}.
   */
  registerFeature(feature: MapFeature): void {
    if (this.#features.has(feature)) return;
    this.#features.add(feature);
    this.notifyFeaturesChanged();
  }

  /**
   * Unregister a `<map-feature>` child. Called by
   * `<map-feature>.disconnectedCallback`. When the last feature leaves
   * the layer, the composite MapLibre feature layer is torn down.
   */
  unregisterFeature(feature: MapFeature): void {
    if (!this.#features.delete(feature)) return;
    this.notifyFeaturesChanged();
  }

  /**
   * Register a `<map-style>` (or other {@link StyleContributor})
   * whose rules should feed this layer's aggregated paint. Called
   * from the contributor's `connectedCallback`. Schedules a
   * paint-only rebuild via {@link notifyStylesChanged}.
   */
  registerStyle(style: StyleContributor): void {
    if (this.#styles.has(style)) return;
    this.#styles.add(style);
    this.notifyStylesChanged();
  }

  /**
   * Unregister a style contributor. Called from the contributor's
   * `disconnectedCallback`. Schedules a paint-only rebuild so the
   * layer drops the contribution.
   */
  unregisterStyle(style: StyleContributor): void {
    if (!this.#styles.delete(style)) return;
    this.notifyStylesChanged();
  }

  /**
   * Coalesced style-rebuild trigger. Any `<map-style>` register /
   * unregister / textContent-mutation calls this; multiple calls in
   * the same synchronous block fold into one paint-property push on
   * the next microtask. Matches the shape of
   * {@link notifyFeaturesChanged}.
   */
  notifyStylesChanged(): void {
    if (this.#stylesChangeScheduled) return;
    this.#stylesChangeScheduled = true;
    queueMicrotask(() => {
      this.#stylesChangeScheduled = false;
      void this.#rebuildStyles();
    });
  }

  /**
   * Compile every active style contributor and push the aggregated
   * paint overrides to the renderer. Runs at most once per
   * microtask (see {@link notifyStylesChanged}).
   *
   * No-op until the aggregated feature source exists — an author
   * `<map-style>` block that lands before any `<map-feature>` still
   * gets remembered here and will be re-applied on the next
   * `#rebuildFeatures` because the renderer caches the last
   * `setFeatureStyle` bundle per source id.
   */
  async #rebuildStyles(): Promise<void> {
    const viewer = this.viewer;
    if (!viewer) return;
    await viewer.whenReady();
    // Layer may have disconnected while we awaited the initial load.
    if (!this.isConnected || this.viewer !== viewer) return;
    if (this.#featureHandle === null) return;
    const rules: CompiledRule[] = [];
    for (const style of this.#styles) {
      if (!style.isActive) continue;
      const compiled = compileMapStyle(style.cssText);
      for (const w of compiled.warnings) console.warn(w);
      rules.push(...compiled.rules);
    }
    const overrides = compilePaintOverrides(rules);
    this.#featureHandle.setStyle(overrides);
  }

  /**
   * Compile this layer's active `<map-style>` contributors into
   * MapLibre paint overrides — the same bundle `#rebuildStyles`
   * pushes to the layer's aggregated feature source.
   *
   * Exposed for `<map-link rel="tile" type="text/mapml">`, whose
   * harvested `<map-feature>`s render on a *link-owned* GeoJSON source
   * (not the layer's aggregated source) yet must paint identically:
   * the link re-reads this on each tile flush so late-loading
   * `<map-style>` blocks are picked up without a subscription.
   *
   * @internal
   */
  featurePaintOverrides(): PaintOverrides {
    const rules: CompiledRule[] = [];
    for (const style of this.#styles) {
      if (!style.isActive) continue;
      const compiled = compileMapStyle(style.cssText);
      rules.push(...compiled.rules);
    }
    return compilePaintOverrides(rules);
  }

  /**
   * Coalesced rebuild trigger. Any feature register / unregister /
   * mutation calls this; multiple calls in the same synchronous block
   * (e.g. HTML-parser insertion of a `<map-layer>` with many
   * `<map-feature>` children) fold into one source upload on the next
   * microtask.
   */
  notifyFeaturesChanged(): void {
    if (this.#featuresChangeScheduled) return;
    this.#featuresChangeScheduled = true;
    queueMicrotask(() => {
      this.#featuresChangeScheduled = false;
      void this.#rebuildFeatures();
    });
  }

  /**
   * Build the FeatureCollection from every direct-child
   * `<map-feature>` and push it to the renderer. Lazy-creates the
   * composite handle in `#featureHandle` on first upload and slots
   * it into `#group` so opacity / rendered-state cascade from
   * `<map-layer>`'s own attribute handlers reaches the feature
   * stack via the group. Tears down the composite when the last
   * feature is removed.
   *
   * `whenReady()` guards the initial upload against the "Style is not
   * done loading" MapLibre error: `<map-feature>`s attached during
   * parser insertion register before the renderer's first `load`
   * fires, and `map.addSource` on an unloaded style throws.
   */
  async #rebuildFeatures(): Promise<void> {
    const viewer = this.viewer;
    if (!viewer) return;
    await viewer.whenReady();
    // Abort if the layer disconnected (or got re-hosted to a
    // different viewer) while we were awaiting the initial style load.
    if (!this.isConnected || this.viewer !== viewer) return;
    const renderer = viewer.renderer;
    const features: GeoJSON.Feature[] = [];
    // Parallel array of focus-index items. One entry per
    // `<map-feature>` (not per emitted GeoJSON feature) so arrow-key
    // navigation lands on whole features, not on individual parts of
    // a `Multi*` geometry. The featureId is the id assigned to the
    // *first* GeoJSON feature the element emits — stable across
    // rebuilds because we walk children in DOM order.
    const focusItems: FeatureFocusItem[] = [];
    /**
     * Fold one `<map-feature>` into the accumulating arrays. Extracted
     * so the direct-children walk and the deeper walk into
     * `<map-link rel="features">` subtrees share the same shape.
     */
    const consumeFeature = (child: MapFeature): void => {
      const emitted = child.toGeoJsonFeatures();
      if (emitted.length === 0) return;
      const firstId = features.length;
      features.push(...emitted);
      const props = emitted[0]!.properties ?? {};
      const centerLng = props.centerLng;
      const centerLat = props.centerLat;
      // No centroid → no meaningful proxy anchor; skip. Only
      // happens for a `<map-feature>` with an empty
      // `<map-geometry>`, which also wouldn't render.
      if (
        typeof centerLng !== 'number' ||
        typeof centerLat !== 'number' ||
        !Number.isFinite(centerLng) ||
        !Number.isFinite(centerLat)
      ) {
        return;
      }
      // GCRS bounding box for the focus-ring overlay. Falls back
      // to a degenerate box at the centroid when `.extent` is
      // unavailable (rare — MapFeature.extent is derivable
      // whenever `pcrsBounds` is, which we just proved above).
      // MapmlExtent's `topLeft.gcrs` is (west, north);
      // `bottomRight.gcrs` is (east, south).
      const ext = child.extent;
      const bboxWest = ext?.topLeft.gcrs.horizontal ?? centerLng;
      const bboxNorth = ext?.topLeft.gcrs.vertical ?? centerLat;
      const bboxEast = ext?.bottomRight.gcrs.horizontal ?? centerLng;
      const bboxSouth = ext?.bottomRight.gcrs.vertical ?? centerLat;
      focusItems.push({
        sourceId: '', // filled in below once the id is known
        featureId: firstId,
        featureEl: child,
        caption: typeof props.caption === 'string' ? props.caption : '',
        hasPopup: typeof props.propertiesHtml === 'string' && props.propertiesHtml !== '',
        hasLink: typeof props.linkHref === 'string' && props.linkHref !== '',
        centerLng,
        centerLat,
        bboxWest,
        bboxSouth,
        bboxEast,
        bboxNorth,
        zoom: typeof props.zoom === 'number' ? props.zoom : 0,
        min: typeof props.min === 'number' ? props.min : 0,
        max: typeof props.max === 'number' ? props.max : Number.POSITIVE_INFINITY,
        properties: { ...props }
      });
    };
    // Walk direct children in DOM order so downstream event handlers
    // (once popups land) can rely on painter order matching source
    // order. `contentRoot` handles both the inline (light DOM) and
    // remote (Slice B: shadow root) cases uniformly.
    //
    // Also dive one level into `<map-extent> > <map-link rel="features">`
    // to pick up features that a templated link has grafted into its
    // shadow root (remote MapML fragments) or that an author has
    // authored directly as `<map-link>` light-DOM children (inline
    // MapML fragments). Both paths route their `<map-feature>` set
    // into this layer's aggregated GeoJSON source \u2014 features anywhere
    // under one `<map-layer>` share a single MapLibre source, matching
    // MapML.js's `MapFeatureLayer` model.
    for (const child of this.contentRoot.children) {
      if (child instanceof MapFeature) {
        consumeFeature(child);
      } else if (child instanceof MapExtent) {
        // Skip features under an unchecked / disabled extent so the
        // aggregated source respects the extent-level visibility
        // toggle. `<map-link rel="features">` doesn't register a
        // renderer-layer id, so the normal `refreshVisibility` fan-
        // out from `MapExtent.attributeChangedCallback('checked')`
        // doesn't reach it \u2014 filtering here is the single choke-
        // point for both inline and remote features modes.
        //
        // Filter on extent-level state only (`checked` + `disabled`),
        // NOT on the full `renders` cascade: layer-level `checked`
        // is honoured via composite-source visibility fan-out
        // downstream, so unchecking the whole `<map-layer>` hides
        // its sub-layers rather than tearing down the composite \u2014
        // matches the direct-under-layer `<map-feature>` model.
        if (!child.checked || child.disabled) continue;
        for (const grand of child.children) {
          if (grand instanceof MapLink && grand.rel === 'features') {
            // Author-set `<map-link rel="features" disabled>`: skip
            // both the inline light-DOM `<map-feature>` children and
            // any grafted-from-remote shadow-root children. In remote
            // mode `#teardown` also wipes the shadow root when the
            // disabled attribute is added, so the shadow tree is
            // empty here; the filter is still cheap and correct for
            // the inline path where the light DOM is authoritative.
            if (grand.disabled) continue;
            const linkRoot: ParentNode = grand.shadowRoot ?? grand;
            for (const inner of linkRoot.children) {
              if (inner instanceof MapFeature) consumeFeature(inner);
            }
          }
        }
      }
    }
    // Assign a stable, monotonically-increasing numeric `id` to every
    // emitted feature. MapLibre preserves these on `queryRenderedFeatures`
    // hits, and the popup pipeline uses `(hit.source, hit.id)` to
    // locate the clicked feature inside the pop-up navigation list
    // (see `#buildFeatureNavList` in the renderer).
    features.forEach((f, i) => {
      f.id = i;
    });
    if (features.length === 0) {
      if (this.#featureHandle !== null) {
        // Detach from the group first so we don't leak a dead handle
        // reference; `handle.remove()` tears down the MapLibre
        // sources / layers.
        this.#group.removeLayer(this.#featureHandle);
        this.#featureHandle.remove();
        this.#featureHandle = null;
        this.viewer?.notifyLayersChanged();
      }
      return;
    }
    if (this.#featureHandle === null) {
      // First non-empty rebuild: lazy-create the composite handle
      // via the renderer factory and slot it into our group. The
      // group's `#pushEffectiveToChild` then applies the layer's
      // current effective opacity + rendered-state to it.
      const id = `map-features-${++nextFeatureLayerId}`;
      this.#featureHandle = renderer.createFeatureCollectionLayer({
        id,
        data: { type: 'FeatureCollection', features: [] },
        visible: this.checked
      });
      this.#group.addLayer(this.#featureHandle);
      // Freshly-registered composite: notify the layer control so an
      // otherwise-empty layer flips to "has content".
      this.viewer?.notifyLayersChanged();
      // First feature ever on this layer: any `<map-style>` block
      // that registered before a feature landed now has a source id
      // to target. Schedule a paint-only rebuild so the initial
      // upload lands with the author's styles applied on the same
      // frame — otherwise the map would flash the default `#3388ff`
      // before the follow-up microtask painted over it.
      if (this.#styles.size > 0) this.notifyStylesChanged();
    }
    const layerId = this.#featureHandle.id;
    for (const item of focusItems) item.sourceId = layerId;
    const collection: GeoJSON.FeatureCollection = {
      type: 'FeatureCollection',
      features
    };
    this.#featureHandle.setData(collection);
    // Publish focus proxies for the keyboard-index pipeline. Empty
    // when the layer is currently unchecked (`visible: false`); the
    // proxies come back on toggle-on via a follow-up rebuild.
    this.#featureHandle.setFocusItems(this.checked ? focusItems : []);
    // Opacity is already applied by the group's cascade on addLayer;
    // no explicit setOpacity call needed here.
  }

  /** True if the layer has at least one registered renderer leaf (anywhere in the tree). */
  get hasRenderableContent(): boolean {
    return !this.#group.isEmpty();
  }

  /**
   * Iterate every renderer layer id owned by this `<map-layer>`, in
   * DOM order. Under the tree-native cascade, `#group.leaves()`
   * recurses through extent sub-groups automatically, so a single
   * walk suffices. Consumed by {@link MapmlViewer.applyLayerReorder}
   * to re-stack MapLibre layers after a drag-to-reorder.
   */
  *renderedLayerIds(): IterableIterator<string> {
    for (const leaf of this.#group.leaves()) yield leaf.id;
  }

  /**
   * Re-sort this layer's group children to match current DOM order —
   * the guard that keeps `<map-extent>` z-order authoritative when the
   * DOM is mutated at runtime (script, paste, drag-drop) after the
   * initial parse. `<map-extent>.connectedCallback` attaches its group
   * in connection order, which diverges from DOM order for an extent
   * inserted mid-list. The aggregated feature composite and any legacy
   * direct-child handles keep their relative order after the extents.
   *
   * Called from {@link MapmlViewer.notifyLayersChanged}'s coalesced
   * restack; the viewer runs the global leaf cascade afterwards.
   */
  reassertExtentOrder(): void {
    const desired: GroupChild[] = [];
    for (const el of this.contentRoot.children) {
      if (el instanceof MapExtent && this.#group.hasLayer(el.group)) {
        desired.push(el.group);
      }
    }
    for (const child of this.#group.children()) {
      if (!desired.includes(child)) desired.push(child);
    }
    if (desired.length === this.#group.size) this.#group.reorder(desired);
  }

  /**
   * Pan + zoom the viewer to this layer's extent.
   *
   * Reads the layer's own {@link MapLayer.extent} envelope, calls
   * MapLibre's `fitBounds` on the `topLeft.gcrs` / `bottomRight.gcrs`
   * corners with `maxZoom = ext.zoom.maxZoom`, and bumps up to
   * `minZoom` if `fitBounds` naturally lands below it. Matches
   * MapML.js's `<map-layer>.zoomTo` \u2192 `Util.getMaxZoom(bounds, map,
   * minZoom, maxZoom)` behaviour.
   */
  zoomTo(): void {
    const map = this.viewer?.renderer.map;
    if (!map) return;
    const ext = this.extent;
    if (ext === null) return;
    const west = ext.topLeft.gcrs.horizontal;
    const north = ext.topLeft.gcrs.vertical;
    const east = ext.bottomRight.gcrs.horizontal;
    const south = ext.bottomRight.gcrs.vertical;
    map.fitBounds(
      [
        [west, south],
        [east, north]
      ],
      {
        animate: false,
        padding: 0,
        maxZoom: ext.zoom.maxZoom
      }
    );
    if (map.getZoom() < ext.zoom.minZoom) {
      map.setZoom(ext.zoom.minZoom);
    }
  }

  /**
   * Outer HTML for this layer, suitable for the layer-context-menu's
   * “Copy Layer” action. Just `this.outerHTML` today; the upstream
   * MapML.js version additionally strips Leaflet-internal data
   * attributes that we never emit.
   */
  getOuterHTML(): string {
    return this.outerHTML;
  }

  /**
   * Serialise this `<map-layer>` and every direct-descendant
   * `<map-feature>` as a GeoJSON `FeatureCollection`. Mirrors
   * MapML.js's `<map-layer>.mapml2geojson(options)`.
   *
   * @see {@link mapml2geojson} for the option shape.
   */
  mapml2geojson(options: Mapml2GeojsonOptions = {}): Mapml2GeojsonFeatureCollection {
    return mapml2geojson(this, options);
  }

  connectedCallback(): void {
    // `data-moving` on this element (or any ancestor, though for
    // <map-layer> only self ever carries it) signals that the parent
    // is being re-parented by the layer-control drag-to-reorder
    // machinery. Skip register/validate churn so the underlying
    // renderer layers stay attached across the DOM move — matches the
    // MapML.js `data-moving` contract in `src/layer.js`.
    if (this.hasAttribute('data-moving')) return;
    this.#owningViewer = this.closest('mapml-viewer') as MapmlViewer | null;
    this.#owningViewer?.registerLayer(this);
    // Listen for `changestyle` events bubbled up from a descendant
    // `<map-link rel="style">`'s layer-control radio. See
    // `#changeStyleListener` for the src-rewriting semantics.
    this.addEventListener('changestyle', this.#changeStyleListener);
    // Attach this layer's group as a child of `renderer.root`.
    // Child extent groups attach themselves under this group (see
    // `MapExtent.connectedCallback`) so opacity + rendered-state
    // compose multiplicatively through the tree — matches MapML.js
    // Leaflet's DOM/CSS opacity nesting semantic.
    const root = this.#owningViewer?.renderer.root;
    if (root && !root.hasLayer(this.#group)) {
      root.addLayer(this.#group);
    }
    // Sync the group's `checked` axis with our own so any handles
    // that get added later inherit the correct visibility. The
    // group's `#pushEffectiveToChild` will do the right thing.
    // `disabled` is deliberately left at the group's default `false`
    // — a disabled layer marks its fieldset stylistically but
    // doesn't suppress rendering (matches MapML.js).
    this.#group.setChecked(this.checked);
    // Extents that upgraded before this layer already called
    // validateDisabled on us during their own connect; run one more
    // pass now that we're fully wired so a layer with no extents
    // (yet) still lands in a defined state.
    this.validateDisabled();
    // Kick off the remote fetch if `src` is already set. The
    // attribute-observer path also fires for the initial `src` — but
    // only when the attribute is set *after* upgrade. HTML-parser
    // insertion of `<map-layer src="…">` upgrades the element with
    // the attribute already present, in which case
    // `attributeChangedCallback` fires *before* `connectedCallback`
    // and its `this.isConnected` check has to gate the fetch there.
    // Handling it here (post-connect) covers both paths.
    if (this.hasAttribute('src')) {
      void this.#loadRemote();
    }
    // Register the `media` gate after the initial setup. If the
    // query doesn't match, `#registerMediaQuery` will call
    // `#deactivateForMedia` — a small wasted round-trip (register,
    // then immediately unregister) but keeps the "matches from the
    // start" fast path allocation-free. Matches MapML.js's
    // `<map-layer>.connectedCallback` ordering, which does the
    // same "apply then media-gate" dance.
    const mq = this.getAttribute('media') ?? '';
    if (mq !== '') {
      void this.#registerMediaQuery(mq);
    }
  }

  disconnectedCallback(): void {
    // See connectedCallback: skip unregister when the layer is only
    // being re-parented as part of a drag-to-reorder DOM shuffle.
    if (this.hasAttribute('data-moving')) return;
    // Drop the media-query subscription first so a resolving async
    // registration can't race the rest of the teardown.
    this.#teardownMediaQuery();
    // Symmetric with the connectedCallback bind — remove with the
    // exact same function identity so the listener actually detaches.
    this.removeEventListener('changestyle', this.#changeStyleListener);
    // Bump the in-flight token so any pending remote fetch aborts
    // its graft when it resolves.
    this.#remoteLoadToken++;
    // Clear the shadow root so a subsequent reconnect starts from
    // a clean slate. Matches MapML.js's `_onRemove` at
    // `src/layer.js:225` which likewise clears the shadowRoot.
    if (this.shadowRoot) this.shadowRoot.replaceChildren();
    // Tear down the aggregated feature layer. Individual
    // `<map-feature>` disconnects call `unregisterFeature` first,
    // which schedules a rebuild that will now see an empty layer
    // (feature children have all disconnected in DOM order before
    // this layer); the microtask, however, aborts on `!isConnected`.
    // Handle the cleanup here so the composite doesn't leak in the
    // renderer.
    if (this.#featureHandle !== null) {
      this.#group.removeLayer(this.#featureHandle);
      this.#featureHandle.remove();
      this.#featureHandle = null;
    }
    this.#features.clear();
    // Detach this layer's group from `renderer.root` before we lose
    // the viewer reference. Any remaining handles in the group are
    // torn down by their `<map-link>` disconnect (which fires before
    // this callback since links are descendants), so the group is
    // typically empty here.
    this.#owningViewer?.renderer.root.removeLayer(this.#group);
    this.#owningViewer?.unregisterLayer(this);
    this.#owningViewer = null;
    // Reset media-query state so a possible future reconnection
    // (re-parenting during layer-control drag, or JS-driven
    // append after detach) starts from the same "matches
    // unconditionally" state a fresh element would have.
    this.#mediaMatches = true;
    this.#mediaDeactivated = false;
  }

  attributeChangedCallback(
    name: string,
    _oldValue: string | null,
    newValue: string | null
  ): void {
    if (name === 'media') {
      // Media changes route through the media-query pipeline. The
      // pre-connect burst is a no-op — `connectedCallback` runs the
      // initial registration itself.
      if (!this.isConnected) return;
      void this.#registerMediaQuery(newValue ?? '');
      return;
    }
    if (name === 'src') {
      // Attribute observer fires both for the initial parse-time
      // attribute (before `connectedCallback`) and for later
      // mutations. Gate on `isConnected` so the pre-connect burst is
      // a no-op — `connectedCallback` runs the initial load.
      if (!this.isConnected) return;
      // Media-deactivated: don't spin up a fetch while the layer is
      // supposed to be REALLY disabled. The pending `src` value is
      // preserved as an attribute; the `#activateForMedia` path
      // will pick it up on re-enable.
      if (this.#mediaDeactivated) return;
      if (newValue === null) {
        // `src` removed: tear down remote content and revert to
        // light-DOM authoring (the shadow root remains attached,
        // just empty; `contentRoot` now returns `this`).
        this.#teardownRemote();
      } else {
        // `src` set / changed: re-fetch. `#loadRemote` bumps the
        // token so any in-flight prior load's graft is skipped.
        void this.#loadRemote();
      }
      return;
    }
    if (name === 'checked') {
      // Single group.setChecked call cascades through this layer's
      // group → each child extent's group → each extent's leaves,
      // AND to this layer's own direct-child leaves + feature
      // composite. No manual per-extent fan-out needed under the
      // tree-native cascade.
      this.#group.setChecked(this.checked);
      // A visibility change on this layer can strand an open query
      // popup whose result came from a `<map-link rel="query">` under
      // it. Dismiss it (no-op for a static feature-click popup) so
      // unchecking the layer clears the popup — matching MapML.js.
      this.viewer?.renderer.closeQueryPopup();
      // Keep the focus-index in sync with `checked`. Rebuilding the
      // aggregated GeoJSON is a no-op reupload (features haven't
      // changed), but the rebuild also republishes the focus items
      // gated on `this.checked` so unchecked layers drop out of the
      // tab order entirely — matches MapML.js, where a hidden
      // `FeatureLayer` has no focusable SVG paths.
      if (this.#features.size > 0) {
        this.notifyFeaturesChanged();
      }
      // Deliberately do NOT notify the layer control. The checkbox in
      // the control panel already reflects the user's click; rebuilding
      // would discard the panel's expanded-settings state, focus, and
      // in-progress opacity drags. Authors who mutate `checked`
      // programmatically should not expect the control to re-sync
      // until we add a more granular update path.
    } else if (name === 'hidden') {
      // `hidden` controls only whether the layer appears in the
      // layer control — it must NOT gate rendering. Per the MapML
      // spec (map-layer-markup skill: "the layer is hidden in the
      // layer control"), rendering follows `checked` only. Rebuild
      // the control so the layer's fieldset shows / hides, but skip
      // any renderer visibility fan-out.
      this.viewer?.notifyLayersChanged();
    } else if (name === 'label') {
      this.viewer?.notifyLayersChanged();
    } else if (name === 'disabled') {
      if (this.#writingDisabled) return;
      // Author writes to `disabled` don't stick — recompute from the
      // extents. If the author-written value matches the computed
      // value the recomputation is a no-op; if not, it snaps back on
      // the next microtask.
      this.validateDisabled();
      this.viewer?.notifyLayersChanged();
    } else if (name === 'opacity') {
      // Parse the attribute; missing/blank/non-numeric falls back to 1.
      const parsed = newValue === null ? 1 : Number(newValue);
      this.setOpacity(Number.isFinite(parsed) ? parsed : 1);
      // Rebuild the layer control so the slider's `value` reflects the
      // new opacity (the slider is initialised from `#group.getOpacity()`
      // when the fieldset is built).
      this.viewer?.notifyLayersChanged();
    }
  }

  /**
   * Tally direct-child `<map-extent>` elements to derive this layer's
   * own `disabled` state and reflect it to the attribute. Matches
   * MapML.js's `map-layer._validateDisabled`: the layer becomes
   * disabled when it has at least one non-hidden extent and every one
   * of them is disabled.
   *
   * Called by each `<map-extent>` after its own `#validateDisabled`
   * flips state, and by `connectedCallback` so a layer with no
   * extents lands in a defined state.
   */
  validateDisabled(): boolean {
    // Media-forced disabled overrides the extent tally. The
    // `disabled` attribute has already been written by
    // {@link #deactivateForMedia}; short-circuit so a subsequent
    // extent tally doesn't clear it. Matches MapML.js's semantic:
    // a media-mismatched layer is disabled regardless of what its
    // extents say (there's nothing to render either way).
    if (!this.#mediaMatches) return true;
    let total = 0;
    let disabled = 0;
    for (const ext of this.#extents()) {
      // MapML.js's tally excludes `hidden` extents (they can't be
      // seen by the user anyway). Match that: a layer whose only
      // visible extent is enabled shouldn't be flagged disabled just
      // because a hidden sibling has a projection mismatch.
      if (ext.hasAttribute('hidden')) continue;
      total += 1;
      if (ext.disabled) disabled += 1;
    }
    const shouldBeDisabled = total > 0 && disabled === total;
    const isDisabled = this.hasAttribute('disabled');
    if (shouldBeDisabled === isDisabled) return shouldBeDisabled;
    this.#writingDisabled = true;
    try {
      if (shouldBeDisabled) this.setAttribute('disabled', '');
      else this.removeAttribute('disabled');
    } finally {
      this.#writingDisabled = false;
    }
    this.viewer?.notifyLayersChanged();
    return shouldBeDisabled;
  }

  *#extents(): IterableIterator<MapExtent> {
    // `contentRoot` transparently handles the remote-content case:
    // for a `<map-layer src="…">` (Slice B onwards) the extents live
    // in the shadow root; for inline authoring they live in the
    // light DOM. Either way `.children` gives us the direct kids.
    for (const child of this.contentRoot.children) {
      // Filter by `instanceof` rather than tagName so that we never
      // hand out a not-yet-upgraded child (which can happen briefly
      // during HTML-parser insertion when the parent's callbacks fire
      // before the children's customElements upgrade reactions run).
      if (child instanceof MapExtent) {
        yield child;
      }
    }
  }

  /**
   * Build the MapML.js-style layer-control fieldset for this `<map-layer>`.
   * Mirrors the DOM shape produced by `createLayerControlForLayer.js`:
   *
   *   fieldset.mapml-layer-item
   *     div.mapml-layer-item-properties
   *       label.mapml-layer-item-toggle  →  checkbox + span.mapml-layer-item-name
   *       div.mapml-layer-item-controls  →  remove button + settings button
   *     div.mapml-layer-item-settings (hidden)
   *       details.mapml-layer-item-opacity.mapml-control-layers
   *         summary + range input
   *       fieldset.mapml-layer-grouped-extents
   *         (each <map-extent>.getLayerControlHTML())
   *
   * `locale` is passed in by the {@link LayerControl} so all UI strings
   * (button titles, opacity summary) come from the same {@link Locale}
   * object that drives the rest of the viewer's chrome.
   */
  getLayerControlHTML(locale: Locale): HTMLFieldSetElement {
    const fieldset = document.createElement('fieldset');
    fieldset.className = 'mapml-layer-item';
    fieldset.setAttribute('aria-grabbed', 'false');

    const properties = document.createElement('div');
    properties.className = 'mapml-layer-item-properties';
    fieldset.appendChild(properties);

    const settings = document.createElement('div');
    settings.className = 'mapml-layer-item-settings';
    settings.hidden = !this.#settingsExpanded;
    fieldset.appendChild(settings);

    // Toggle: checkbox + name
    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'mapml-layer-item-toggle';
    properties.appendChild(toggleLabel);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'leaflet-control-layers-selector';
    checkbox.checked = this.checked;
    checkbox.addEventListener('change', () => {
      this.checked = checkbox.checked;
      // `map-change` fires ONLY from user-driven layer-control
      // interaction (mouse click on the checkbox, or keyboard
      // Space/Enter which natively dispatches `change`). Programmatic
      // `layer.checked = …` writes and direct `setAttribute` /
      // `removeAttribute('checked')` calls do NOT fire it — the event
      // is dispatched here, not from the `checked` setter or
      // `attributeChangedCallback`, so authors have a UI-only signal
      // distinct from any layer-state mutation. Matches MapML.js's
      // `createLayerControlForLayer.js#changeCheck` contract.
      this.dispatchEvent(new CustomEvent('map-change'));
    });
    toggleLabel.appendChild(checkbox);

    const nameSpan = document.createElement('span');
    nameSpan.className = 'mapml-layer-item-name';
    const nameId = `mapml-layer-item-name-${nextControlId()}`;
    nameSpan.id = nameId;
    // A `<map-link rel="legend">` under this layer's contentRoot
    // upgrades the title to a hyperlink (opens in a new tab).
    // Matches MapML.js's `createLayerControlForLayer.js`:
    //   if (this._layer._legendUrl) { … <a href=legendUrl target=_blank> … }
    // The anchor sits inside the label so it inherits the layer-
    // control row's styling, but `click` is stopped so the
    // enclosing `<label>` doesn't also toggle the checkbox — the
    // user's intent when clicking the legend link is to open the
    // legend, not to switch layer visibility.
    const legendUrl = this.legendUrl;
    if (legendUrl !== null) {
      const anchor = document.createElement('a');
      anchor.href = legendUrl;
      anchor.target = '_blank';
      anchor.rel = 'noopener noreferrer';
      anchor.textContent = this.label;
      anchor.draggable = false;
      anchor.addEventListener('click', (e) => {
        e.stopPropagation();
      });
      nameSpan.appendChild(anchor);
    } else {
      nameSpan.textContent = this.label;
    }
    fieldset.setAttribute('aria-labelledby', nameId);
    toggleLabel.appendChild(nameSpan);

    // Controls: remove + settings buttons
    const controls = document.createElement('div');
    controls.className = 'mapml-layer-item-controls';
    properties.appendChild(controls);

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'mapml-layer-item-remove-control mapml-button';
    removeBtn.title = locale.lmRemoveLayer;
    removeBtn.innerHTML = "<span aria-hidden='true'>&#10005;</span>";
    removeBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.remove();
    });
    controls.appendChild(removeBtn);

    const settingsBtn = document.createElement('button');
    settingsBtn.type = 'button';
    settingsBtn.className = 'mapml-layer-item-settings-control mapml-button';
    settingsBtn.title = locale.lmLayerSettings;
    settingsBtn.setAttribute('aria-expanded', String(this.#settingsExpanded));
    const settingsIconHost = document.createElement('span');
    settingsIconHost.className = 'mapml-button-icon';
    settingsIconHost.setAttribute('aria-hidden', 'true');
    settingsIconHost.appendChild(settingsGearSvg());
    settingsBtn.appendChild(settingsIconHost);
    settingsBtn.addEventListener('click', () => {
      // Coerce to `boolean` — newer DOM lib.d.ts types `hidden` as
      // `boolean | 'until-found'`; we only ever set it to `true` /
      // `false` here so this is safe.
      const willOpen = !!settings.hidden;
      settings.hidden = !willOpen;
      this.#settingsExpanded = willOpen;
      settingsBtn.setAttribute('aria-expanded', String(willOpen));
    });
    controls.appendChild(settingsBtn);

    // Opacity control
    const opacityDetails = document.createElement('details');
    opacityDetails.className = 'mapml-layer-item-opacity mapml-control-layers';
    settings.appendChild(opacityDetails);

    const opacitySummary = document.createElement('summary');
    opacitySummary.textContent = locale.lcOpacity;
    const summaryId = `mapml-layer-item-opacity-${nextControlId()}`;
    opacitySummary.id = summaryId;
    opacityDetails.appendChild(opacitySummary);

    const opacitySlider = document.createElement('input');
    opacitySlider.type = 'range';
    opacitySlider.min = '0';
    opacitySlider.max = '1';
    opacitySlider.step = '0.1';
    opacitySlider.value = String(this.#group.getOpacity());
    opacitySlider.setAttribute('aria-labelledby', summaryId);
    opacitySlider.addEventListener('input', () => {
      this.setOpacity(Number(opacitySlider.value));
    });
    opacityDetails.appendChild(opacitySlider);

    // Alternate-style radio group. Every descendant `<map-link>` with
    // `rel="style"` / `rel="self style"` / `rel="style self"` (looked
    // up on `contentRoot` so remote-content layers work too) has
    // already built a `<div>` radio option in its `#applyStyle`; we
    // gather them here into a shared `<details
    // class="mapml-layer-item-style mapml-control-layers">`.
    // MapML.js's `layer.js#getAlternateStyles` only emits the details
    // when there are *at least two* style links (a single style is
    // just the currently-loaded stylesheet; no alternative to
    // switch to). Port that behaviour.
    const styleLinks = this.contentRoot.querySelectorAll<MapLink>(
      'map-link[rel="style"], map-link[rel="self style"], map-link[rel="style self"]'
    );
    if (styleLinks.length > 1) {
      const styleDetails = document.createElement('details');
      styleDetails.className =
        'mapml-layer-item-style mapml-control-layers';
      const styleSummary = document.createElement('summary');
      styleSummary.textContent = locale.lmStyle;
      styleDetails.appendChild(styleSummary);
      let appended = 0;
      for (const link of styleLinks) {
        const opt = link.getLayerControlOption();
        if (opt) {
          styleDetails.appendChild(opt);
          appended += 1;
        }
      }
      // Only append the fieldset if at least one link had a
      // realised option — a link may still be mid-connect when the
      // control renders.
      if (appended > 0) {
        settings.appendChild(styleDetails);
      }
    }

    // Grouped extents (sublayers) fieldset
    const extentsFieldset = document.createElement('fieldset');
    extentsFieldset.className = 'mapml-layer-grouped-extents';
    extentsFieldset.setAttribute('aria-label', 'Sublayers');

    let visibleExtentCount = 0;
    for (const ext of this.#extents()) {
      if (ext.hasAttribute('hidden')) continue;
      extentsFieldset.appendChild(ext.getLayerControlHTML(locale));
      visibleExtentCount += 1;
    }
    if (visibleExtentCount === 0) {
      extentsFieldset.setAttribute('hidden', '');
    }
    settings.appendChild(extentsFieldset);

    // Reflect the current `disabled` state onto the freshly-built
    // fieldset. Matches MapML.js's `toggleLayerControlDisabled`:
    // disable the checkbox + opacity slider and italicise the label
    // and opacity summary. Buttons stay enabled so the context menu
    // remains reachable. See the equivalent block in
    // MapExtent.getLayerControlHTML for why we use a class instead of
    // aria-disabled on the outer fieldset.
    if (this.disabled) {
      fieldset.classList.add('mapml-layer-item-disabled');
      checkbox.disabled = true;
      checkbox.setAttribute('aria-disabled', 'true');
      opacitySlider.disabled = true;
      opacitySlider.setAttribute('aria-disabled', 'true');
      toggleLabel.style.fontStyle = 'italic';
      opacitySummary.style.fontStyle = 'italic';
    }

    // Wire drag-to-reorder. The fieldset carries a back-reference to
    // its `<map-layer>` so the drop callback can translate the new
    // fieldset order into the corresponding `<map-layer>` DOM order.
    // Ports the pointer/touch handler from MapML.js's
    // `createLayerControlForLayer.js`.
    (fieldset as HTMLFieldSetElement & { _mapLayer?: MapLayer })._mapLayer = this;
    const viewer = this.viewer;
    const hitTestRoot = viewer?.shadowRoot as ShadowRoot | null;
    if (viewer && hitTestRoot) {
      installDragToReorder({
        fieldset,
        hitTestRoot,
        siblingSelector: 'fieldset.mapml-layer-item',
        onDrop: (newOrder) => {
          const orderedLayers: MapLayer[] = [];
          for (const fs of newOrder) {
            const l = (fs as HTMLFieldSetElement & { _mapLayer?: MapLayer })
              ._mapLayer;
            if (l) orderedLayers.push(l);
          }
          viewer.applyLayerReorder(orderedLayers);
        }
      });
    }

    return fieldset;
  }

  /**
   * Fetch the remote MapML document at `this.src`, parse it, and
   * graft its `<map-head>` / `<map-body>` children into this layer's
   * shadow root. Errors (non-2xx, network, parse, missing `<mapml->`
   * root, non-XML body) dispatch an `error` event on the layer and
   * leave the shadow root empty; other layers keep rendering.
   *
   * Concurrency: every call bumps `#remoteLoadToken`; when the
   * fetch resolves we bail out if the token has moved (another
   * `src` change kicked off a newer load). Adopted content only
   * gets committed to the shadow root on the winning token.
   *
   * Custom-element upgrade is a **contract of the MapML document
   * format**: the `<mapml-` root MUST declare
   * `xmlns="http://www.w3.org/1999/xhtml"` (all upstream fixtures
   * and this port's demo fixtures do). That makes parsed elements
   * HTML-namespaced, so the DOM's implicit "adopting steps" +
   * "insertion steps" upgrade any `<map-*>` tag that's in the
   * customElements registry as soon as it lands in the shadow
   * root — exactly the same "it just happens" path MapML.js relies
   * on. XML documents in *other* namespaces (or with no `xmlns`)
   * won't upgrade; that's an author error surfaced by the
   * behaviour being wrong rather than a diagnostic here.
   */
  async #loadRemote(): Promise<void> {
    const url = this.getAttribute('src');
    if (!url) {
      this.#teardownRemote();
      return;
    }
    // Attach a shadow root on first fetch so we have a stable
    // grafting target. Idempotent — subsequent calls reuse the
    // existing root.
    const shadow = this.#ensureShadowRoot();
    // Clear any previously grafted content up-front so the layer is
    // observably empty during the in-flight fetch. Matches upstream's
    // `_onRemove` + `_onAdd` flow.
    shadow.replaceChildren();
    // Feature-layer teardown mirrors `disconnectedCallback` for the
    // pieces that don't require the element to actually detach —
    // shadow content that included `<map-feature>` won't clean up
    // via its own `disconnectedCallback` because we've already
    // replaced the shadow children (mutation observer batches this).
    if (this.#featureHandle !== null) {
      this.#group.removeLayer(this.#featureHandle);
      this.#featureHandle.remove();
      this.#featureHandle = null;
    }
    this.#features.clear();
    // Rebuild the layer control (the fieldset now shows no extents).
    this.viewer?.notifyLayersChanged();

    const token = ++this.#remoteLoadToken;
    this.#fetchError = false;

    let text: string;
    try {
      const response = await fetch(url, {
        headers: { Accept: 'text/mapml' }
      });
      if (!response.ok) {
        throw new Error(`HTTP ${response.status} fetching ${url}`);
      }
      text = await response.text();
    } catch (err) {
      // Bail if a newer load has since started (or the layer was
      // detached).
      if (token !== this.#remoteLoadToken) return;
      this.#reportRemoteError(err);
      return;
    }
    if (token !== this.#remoteLoadToken) return;

    // Parse as XML (matches upstream). Any well-formed XML body works
    // — the mapml payload uses `xmlns="http://www.w3.org/1999/xhtml"`
    // so adopted elements end up HTML-namespaced and can upgrade as
    // custom elements.
    const parser = new DOMParser();
    let doc: XMLDocument;
    try {
      doc = parser.parseFromString(text, 'text/xml');
    } catch (err) {
      this.#reportRemoteError(err);
      return;
    }
    if (doc.querySelector('parsererror')) {
      this.#reportRemoteError(new Error(`XML parse error in ${url}`));
      return;
    }
    const mapmlRoot = doc.querySelector('mapml-');
    if (!mapmlRoot) {
      this.#reportRemoteError(
        new Error(`No <mapml-> root in ${url}`)
      );
      return;
    }

    // Graft every direct child of `<map-head>` / `<map-body>` into
    // the shadow root. Matches MapML.js's
    // `copyRemoteContentToShadowRoot` selector at `src/layer.js:441`.
    const nodes = doc.querySelectorAll(
      'map-head > *, map-body > *'
    );
    const frag = document.createDocumentFragment();
    for (const node of nodes) {
      // Move the element from the XML doc into the host document
      // without cloning; identity is preserved. Because the source
      // doc's `<mapml->` root carries `xmlns="…/1999/xhtml"`, each
      // adopted node arrives in the HTML namespace and will upgrade
      // to its customElement class automatically when the fragment
      // is inserted below (see method docblock).
      frag.appendChild(document.adoptNode(node));
    }
    shadow.appendChild(frag);

    // Projection negotiation (Rm.10): if the remote doc declares a
    // native projection that doesn't match the viewer's, walk its
    // <map-link rel="alternate" projection="…"> children for a
    // compatible URL and re-fetch. `#selectAlternate` returns true
    // when it kicked off a re-fetch, in which case bail out so the
    // rest of this pass doesn't run — the alternate load will run
    // its own notify + validate on completion.
    if (this.#selectAlternate(url)) return;

    // Force the layer control (and, indirectly, the LayerControl
    // fieldset for this layer) to redraw with the new label / extent
    // count. `mapml:layerschanged` also propagates so downstream
    // listeners (attribution, extent tallies) update.
    this.viewer?.notifyLayersChanged();
    // Re-tally disabled state now that extents may have arrived.
    this.validateDisabled();
    // Successful non-alternate load: reset the redirect counter so a
    // *subsequent* author-driven `src` change starts from zero.
    this.#altRedirects = 0;
  }

  /**
   * Teardown the shadow content, without dispatching an error. Called
   * when `src` is removed at runtime or during disconnect.
   */
  #teardownRemote(): void {
    // Bump the token so any in-flight fetch bails out on resolve.
    this.#remoteLoadToken++;
    if (this.shadowRoot) this.shadowRoot.replaceChildren();
    if (this.#featureHandle !== null) {
      this.#group.removeLayer(this.#featureHandle);
      this.#featureHandle.remove();
      this.#featureHandle = null;
    }
    this.#features.clear();
    this.#fetchError = false;
    this.viewer?.notifyLayersChanged();
    this.validateDisabled();
  }

  /**
   * Wire (or rewire) this layer's `media` gate.
   *
   * Ports MapML.js's `<map-layer>._registerMediaQuery` in
   * `src/layer.js`. Idempotent per attribute value; the change
   * handler is bound lazily on the first call so
   * `removeEventListener` sees the same identity across
   * re-registrations.
   *
   * - When `mq` is a non-empty / non-whitespace-only string, we
   *   await `viewer.whenReady()` (matchMedia reads
   *   `viewer.extent` for the bbox features), build a fresh
   *   `MediaQueryList`, seed `#mediaMatches` from the initial
   *   verdict via {@link #applyMediaMatch}, then subscribe to the
   *   `change` event.
   * - When `mq` is empty / whitespace-only, we tear the matcher
   *   down and force `#mediaMatches = true` — mirroring
   *   MapML.js's "no / empty media attribute matches" branch. Also
   *   mirrors upstream's `_registerMediaQuery(newValue)` where
   *   `newValue` is `null`.
   *
   * When the query stops matching, {@link #deactivateForMedia}
   * fully unregisters the layer from the viewer (layer control),
   * detaches its group from `renderer.root` (nothing paints), and
   * aborts any in-flight remote fetch. When it starts matching
   * again, {@link #activateForMedia} restores all three.
   */
  async #registerMediaQuery(mq: string): Promise<void> {
    if (this.#mqlChangeHandler === null) {
      this.#mqlChangeHandler = (): void => {
        if (this.#mql === null) return;
        this.#applyMediaMatch(this.#mql.matches);
      };
    }
    this.#teardownMediaQuery();

    // Whitespace-only or empty is equivalent to no media attribute —
    // matches MapML.js's `<map-layer>` media-media test which uses
    // `l.setAttribute('media', ' ')` to expect an "enabled" outcome.
    const trimmed = mq.trim();
    if (trimmed === '') {
      this.#applyMediaMatch(true);
      return;
    }

    const viewer = this.#owningViewer;
    if (viewer === null) return;

    this.#mqlRegisterToken += 1;
    const token = this.#mqlRegisterToken;
    await viewer.whenReady();
    if (
      token !== this.#mqlRegisterToken ||
      !this.isConnected ||
      (this.getAttribute('media') ?? '') !== mq
    ) {
      return;
    }
    this.#mql = viewer.matchMedia(mq);
    this.#applyMediaMatch(this.#mql.matches);
    this.#mql.addEventListener('change', this.#mqlChangeHandler);
  }

  /**
   * Tear down the current `#mql` subscription, if any. Idempotent.
   * Retains `#mqlChangeHandler` across calls so a subsequent
   * registration reuses the same bound identity.
   */
  #teardownMediaQuery(): void {
    if (this.#mql !== null && this.#mqlChangeHandler !== null) {
      this.#mql.removeEventListener('change', this.#mqlChangeHandler);
    }
    this.#mql = null;
  }

  /**
   * Sync `#mediaMatches` + activation state with the current
   * media-query verdict. Called from every
   * {@link #registerMediaQuery} entry point and from the `change`
   * handler. Idempotent when the verdict hasn't flipped.
   */
  #applyMediaMatch(matches: boolean): void {
    if (matches === this.#mediaMatches) {
      // No verdict change, but the initial pass may still have
      // pending activation work (e.g. connectedCallback registered
      // us then `#registerMediaQuery` fires with matches=true).
      // Both cases where `matches === this.#mediaMatches`:
      //   - initial matches=true, deactivated=false: no-op.
      //   - initial matches=false, deactivated=false: still need
      //     to deactivate (handled below).
      if (matches || this.#mediaDeactivated) return;
    }
    this.#mediaMatches = matches;
    if (matches) {
      this.#activateForMedia();
    } else {
      this.#deactivateForMedia();
    }
  }

  /**
   * REALLY disable the layer — unregister from the viewer (drops
   * the fieldset from the layer control), detach its group from
   * `renderer.root` (nothing paints), bump the remote-load token
   * to abort any in-flight fetch, and set `disabled=""` as a
   * user-visible state marker.
   *
   * Idempotent. Guarded by `#mediaDeactivated` so a spurious
   * repeated call is cheap. Ports MapML.js's `_onRemove` slice used
   * inside the media change handler.
   */
  #deactivateForMedia(): void {
    if (this.#mediaDeactivated) return;
    this.#mediaDeactivated = true;

    // Abort any in-flight remote fetch. `#loadRemote` compares the
    // token after each `await`; a bump here causes it to bail.
    this.#remoteLoadToken++;
    // For remote (`src=`) layers, drop the grafted shadow content
    // so features / extents / links inside disconnect and clean up
    // their own state via their own `disconnectedCallback`s.
    // Inline (light-DOM) authoring is left alone — those elements
    // are not part of the shadow, and MapML.js also doesn't touch
    // light-DOM children unless `src` is set (`if (this.src)
    // this.innerHTML = ''` in `src/layer.js`).
    if (this.hasAttribute('src') && this.shadowRoot) {
      this.shadowRoot.replaceChildren();
    }
    // Tear down the aggregated feature composite; inline features
    // still exist in the DOM but their handle is gone. On re-enable
    // we rebuild via `notifyFeaturesChanged`.
    if (this.#featureHandle !== null) {
      this.#group.removeLayer(this.#featureHandle);
      this.#featureHandle.remove();
      this.#featureHandle = null;
    }

    // Detach the group from `renderer.root` — this is what actually
    // stops the layer painting. Child extent / link handles stay in
    // the group (and re-attach with the group on re-enable), so we
    // don't need to walk them individually.
    this.#owningViewer?.renderer.root.removeLayer(this.#group);
    // Unregister from the viewer's layer list — this is what drops
    // the fieldset from the layer control.
    this.#owningViewer?.unregisterLayer(this);

    // Set the `disabled` state marker. Guard the observer so
    // `attributeChangedCallback('disabled', …)` doesn't re-enter
    // `validateDisabled`.
    this.#writingDisabled = true;
    try {
      this.setAttribute('disabled', '');
    } finally {
      this.#writingDisabled = false;
    }

    this.#owningViewer?.notifyLayersChanged();
  }

  /**
   * Undo {@link #deactivateForMedia}. Restores the viewer + renderer
   * registration and, for `src=` layers, kicks off a fresh
   * `#loadRemote`. Removes the `disabled` state marker (subsequent
   * `validateDisabled` calls may re-add it based on the extent tally).
   *
   * Idempotent. Guarded by `#mediaDeactivated` so a spurious call
   * is cheap.
   */
  #activateForMedia(): void {
    if (!this.#mediaDeactivated) {
      // The layer was never deactivated (media matched from the
      // start) — no work to do beyond ensuring the disabled
      // attribute reflects the extent tally.
      this.validateDisabled();
      return;
    }
    this.#mediaDeactivated = false;

    // Restore renderer + layer-control registration in the same
    // order as `connectedCallback`.
    this.#owningViewer?.registerLayer(this);
    const root = this.#owningViewer?.renderer.root;
    if (root && !root.hasLayer(this.#group)) {
      root.addLayer(this.#group);
    }
    this.#group.setChecked(this.checked);

    // Clear the media-forced `disabled` state marker before
    // re-tallying. `validateDisabled` may set it again if every
    // extent is disabled, but that's the correct semantic.
    this.#writingDisabled = true;
    try {
      this.removeAttribute('disabled');
    } finally {
      this.#writingDisabled = false;
    }

    // Restart the remote fetch (for `<map-layer src=…>`) so the
    // shadow content re-grafts and its extents / features register.
    // For inline (light-DOM) layers, re-run the aggregate rebuild
    // so any registered features paint again.
    if (this.hasAttribute('src')) {
      void this.#loadRemote();
    } else if (this.#features.size > 0) {
      this.notifyFeaturesChanged();
    }

    this.validateDisabled();
    this.#owningViewer?.notifyLayersChanged();
  }

  /**
   * Mark the fetch as failed and dispatch a bubbling `error` event so
   * authors can observe the failure. The layer stays in the map with
   * an empty shadow root; other layers keep rendering.
   */
  #reportRemoteError(cause: unknown): void {
    this.#fetchError = true;
    // Localised console warning \u2014 matches upstream's
    // `console.log(err)` at `src/layer.js:394`.
    console.warn('<map-layer src>: failed to load remote content', cause);
    this.dispatchEvent(
      new CustomEvent('error', {
        detail: { src: this.getAttribute('src'), cause },
        bubbles: false,
        cancelable: false
      })
    );
  }

  /**
   * Read the remote MapML doc's declared projection from its
   * `<map-head>` \u2014 grafted into the shadow root by this point.
   * Precedence mirrors MapML.js:
   *   1. `<map-meta name="projection" content="\u2026">` in the shadow root
   *      (equivalent to the fetched doc's `<map-head>`).
   *   2. Fallback: the first `<map-extent units="\u2026">` in the shadow.
   *
   * Returns `null` when neither exists \u2014 no projection declared,
   * no mismatch to detect, negotiation is skipped.
   */
  #getRemoteProjection(): string | null {
    const root = this.shadowRoot;
    if (!root) return null;
    for (const child of root.children) {
      if (
        child.tagName.toLowerCase() === 'map-meta' &&
        (child.getAttribute('name') ?? '').toLowerCase() === 'projection'
      ) {
        const content = child.getAttribute('content');
        if (content) return content.trim();
      }
    }
    // Fallback to the first `<map-extent units>` in DOM order.
    for (const child of root.children) {
      if (child.tagName.toLowerCase() === 'map-extent') {
        const units = child.getAttribute('units');
        if (units) return units.trim();
      }
    }
    return null;
  }

  /**
   * Projection negotiation. Called by {@link #loadRemote} after the
   * initial graft. If the remote doc's declared projection differs
   * from the viewer's projection AND the shadow content declares a
   * `<map-link rel="alternate" projection="\u2026" href="\u2026">` matching
   * the viewer's projection, this:
   *
   *   1. Resolves the alternate's `href` against `currentSrc` (the
   *      URL that was just fetched \u2014 matches MapML.js: alternates
   *      are relative to the current remote doc, not the host page).
   *   2. Bumps `#altRedirects`; aborts with a warn when the count
   *      exceeds `#MAX_ALT_REDIRECTS` (guards against a chain of
   *      alternates each mismatched with no viable target).
   *   3. Sets `this.src = absoluteAlternateUrl`, which fires
   *      `attributeChangedCallback('src', \u2026)` and triggers a fresh
   *      `#loadRemote()` pass.
   *
   * Returns `true` when a re-fetch was kicked off (caller bails);
   * `false` when the doc's projection matches, or no matching
   * alternate exists (caller finalises the current load with a
   * console warn \u2014 v1 renders in the native projection, which for
   * OSMTILE-only support means visibly-wrong tiles). Matches
   * MapML.js's `selectAlternateOrChangeProjection` at
   * `src/layer.js:409-433`.
   */
  #selectAlternate(currentSrc: string): boolean {
    const mapProj = this.viewer?.projection;
    const layerProj = this.#getRemoteProjection();
    if (!mapProj || !layerProj || layerProj === mapProj) {
      return false;
    }
    // Look for a matching alternate directly under the shadow root
    // \u2014 matches the fetched doc's `<map-head>` shape.
    let alternate: HTMLElement | null = null;
    const root = this.shadowRoot;
    if (root) {
      for (const child of root.children) {
        if (child.tagName.toLowerCase() !== 'map-link') continue;
        const rel = (child.getAttribute('rel') ?? '').toLowerCase();
        // MapML uses space-separated rel token lists; upstream's
        // selector is `[rel~="alternate"]`.
        if (!rel.split(/\s+/).includes('alternate')) continue;
        if (child.getAttribute('projection') !== mapProj) continue;
        const href = child.getAttribute('href');
        if (href) {
          alternate = child as HTMLElement;
          break;
        }
      }
    }
    if (alternate === null) {
      console.warn(
        `<map-layer src>: projection mismatch ` +
          `(map=${mapProj}, layer=${layerProj}) with no matching ` +
          `<map-link rel="alternate" projection="${mapProj}">; ` +
          `rendering in the native projection may produce garbage`
      );
      return false;
    }
    this.#altRedirects += 1;
    if (this.#altRedirects > MapLayer.#MAX_ALT_REDIRECTS) {
      console.warn(
        `<map-layer src>: alternate re-fetch loop aborted after ` +
          `${MapLayer.#MAX_ALT_REDIRECTS} redirects starting from ${currentSrc}`
      );
      this.#altRedirects = 0;
      return false;
    }
    const href = alternate.getAttribute('href')!;
    // `currentSrc` may be relative (matches whatever the author put
    // in the `src` attribute); `new URL(rel, rel)` throws, so
    // absolutize against `this.baseURI` first.
    const currentAbsolute = new URL(currentSrc, this.baseURI).href;
    const absoluteUrl = new URL(href, currentAbsolute).href;
    // Setting the attribute triggers `attributeChangedCallback`,
    // which calls `#loadRemote()` for the alternate URL. Do this
    // *after* incrementing the counter so a same-projection loop
    // (mismatched alternate → same doc → same mismatch → …)
    // hits the ceiling.
    this.setAttribute('src', absoluteUrl);
    return true;
  }
}

/**
 * Resolve a `<map-link rel="legend">`'s raw `href` against the
 * owning layer's base URL and reject any scheme that could turn
 * the layer-control row's title anchor into a script-execution
 * or data-URL vector. Only `http:` and `https:` (and relatives
 * that resolve to one of those) survive.
 *
 * Matches MapML.js's `parseLicenseAndLegend()` shape but adds the
 * scheme allow-list — MapML.js relies on trusting the fetched
 * doc's contents; the port is stricter about untrusted input
 * because the same code path serves both inline authoring and
 * remote content.
 *
 * Returns `null` on:
 *   - unparseable URL (malformed relative / absolute reference);
 *   - non-http(s) scheme (e.g. `javascript:`, `data:`, `blob:`,
 *     `file:`, `ftp:`, `mailto:`, …).
 */
function sanitizeLegendHref(rawHref: string, base: string): string | null {
  let resolved: URL;
  try {
    resolved = new URL(rawHref, base);
  } catch {
    return null;
  }
  if (resolved.protocol !== 'http:' && resolved.protocol !== 'https:') {
    return null;
  }
  return resolved.href;
}
