/**
 * Drag-to-reorder for `<fieldset class="mapml-layer-item">` and
 * `<fieldset class="mapml-layer-extent">` inside the layer control.
 *
 * Ports the pointer/touch handler from MapML.js's
 * `createLayerControlForLayer.js` / `createLayerControlForExtent.js`.
 * Both files there duplicate the same algorithm; we factor it out.
 *
 * Behaviour (MapML.js parity, user-observable):
 *   - Drag only starts when the pointer goes down on the label surface
 *     (the toggle label wrapping the checkbox + name span) — not on the
 *     checkbox itself, and not on the settings/remove buttons.
 *   - The dragged fieldset is translated with the pointer and its
 *     siblings shuffle around it via `insertBefore`; a 15px dead-zone
 *     avoids jitter on tiny movements.
 *   - `aria-grabbed` / `aria-dropeffect` cycle for AT, and the parent
 *     container gets the `mapml-draggable` class while a drag is in
 *     progress (used by CSS to disable pointer-events on siblings).
 *   - Uses the shadow root's `elementFromPoint` so hit testing works
 *     from inside `<mapml-viewer>`'s shadow DOM.
 *   - On drop, if the fieldset ended up at a different index, invokes
 *     `onDrop(newOrder)` with the fieldsets in their post-drop order.
 *     The callback is expected to (a) move the corresponding MapML
 *     elements in the light-DOM tree using the `data-moving` guard so
 *     the elements' connect/disconnect callbacks don't tear down their
 *     renderer state, and (b) update z-order in the renderer.
 */

/** Root the drag helper uses for `elementFromPoint`. */
type HitTestRoot = Pick<Document, 'elementFromPoint'>;

export interface DragToReorderOptions {
  /** The draggable fieldset. */
  fieldset: HTMLFieldSetElement;
  /**
   * Shadow root (or document) to hit-test against during the drag.
   * `document.elementFromPoint` would return the shadow host, not the
   * fieldset under the pointer, so callers pass in the viewer's shadow
   * root here.
   */
  hitTestRoot: HitTestRoot;
  /** Selector matching sibling fieldsets that are legal swap targets. */
  siblingSelector: string;
  /**
   * Invoked after the pointer is released when the fieldset ended up at
   * a different index than where it started. `newOrder` reflects the
   * post-drop fieldset order inside the same parent.
   */
  onDrop: (newOrder: readonly HTMLFieldSetElement[]) => void;
}

/**
 * Install pointer + touch drag handlers on `fieldset`. Returns a
 * teardown function; callers rarely need it because rebuilding the
 * layer control tears down the whole fieldset anyway.
 */
export function installDragToReorder(options: DragToReorderOptions): () => void {
  const { fieldset, hitTestRoot, siblingSelector, onDrop } = options;

  const start = (downEvent: MouseEvent | TouchEvent): void => {
    const target = downEvent.target;
    if (!(target instanceof Element)) return;
    // Only start on the toggle label (or its non-input descendants) —
    // matches MapML.js so the checkbox and the remove/settings buttons
    // stay clickable without inadvertently starting a drag.
    const label = target.closest('label.mapml-layer-item-toggle');
    if (!label) return;
    if (target.tagName.toLowerCase() === 'input') return;

    const parent = fieldset.parentElement;
    if (!parent) return;

    downEvent.stopPropagation();
    const point = getPointerPoint(downEvent);
    let yPos = point.clientY;
    let moving = false;
    const startIndex = indexAmong(fieldset, siblingSelector);

    const onMove = (moveEvent: MouseEvent | TouchEvent): void => {
      moveEvent.preventDefault();
      const p = getPointerPoint(moveEvent);
      const offset = p.clientY - yPos;
      // 15px dead-zone before we commit to a drag; matches MapML.js.
      moving = Math.abs(offset) > 15 || moving;

      const parentRect = parent.getBoundingClientRect();
      const controlRect = fieldset.getBoundingClientRect();
      if (
        !moving ||
        parent.childElementCount <= 1 ||
        parentRect.top > controlRect.bottom ||
        parentRect.bottom < controlRect.top
      ) {
        return;
      }

      parent.classList.add('mapml-draggable');
      fieldset.style.transform = `translateY(${offset}px)`;
      fieldset.style.pointerEvents = 'none';
      fieldset.setAttribute('aria-grabbed', 'true');
      fieldset.setAttribute('aria-dropeffect', 'move');

      const elementAt = hitTestRoot.elementFromPoint(p.clientX, p.clientY);
      let swapTarget: HTMLFieldSetElement =
        (elementAt?.closest(siblingSelector) as HTMLFieldSetElement | null) ??
        fieldset;
      // Below the target's own height, we're still on top of ourselves.
      if (Math.abs(offset) <= swapTarget.offsetHeight) {
        swapTarget = fieldset;
      }
      if (swapTarget.parentElement === parent) {
        // Two-sibling insert: `insertBefore` needs the *next* sibling
        // when swapping downward, per MapML.js.
        const insertBeforeNode =
          swapTarget !== fieldset.nextSibling
            ? swapTarget
            : swapTarget.nextSibling;
        if (fieldset !== swapTarget) {
          yPos = p.clientY;
          fieldset.style.transform = '';
        }
        parent.insertBefore(fieldset, insertBeforeNode);
      }
    };

    const onUp = (): void => {
      const endIndex = indexAmong(fieldset, siblingSelector);
      fieldset.setAttribute('aria-grabbed', 'false');
      fieldset.removeAttribute('aria-dropeffect');
      fieldset.style.pointerEvents = '';
      fieldset.style.transform = '';
      parent.classList.remove('mapml-draggable');
      document.body.removeEventListener('mousemove', onMove);
      document.body.removeEventListener('touchmove', onMove);
      document.body.removeEventListener('mouseup', onUp);
      document.body.removeEventListener('touchend', onUp);
      if (startIndex !== endIndex) {
        const finalOrder = Array.from(
          parent.querySelectorAll<HTMLFieldSetElement>(siblingSelector)
        );
        onDrop(finalOrder);
      }
    };

    document.body.addEventListener('mousemove', onMove);
    document.body.addEventListener('touchmove', onMove, { passive: false });
    document.body.addEventListener('mouseup', onUp);
    document.body.addEventListener('touchend', onUp);
  };

  fieldset.addEventListener('mousedown', start);
  fieldset.addEventListener('touchstart', start, { passive: true });

  return () => {
    fieldset.removeEventListener('mousedown', start);
    fieldset.removeEventListener('touchstart', start);
  };
}

function getPointerPoint(
  ev: MouseEvent | TouchEvent
): { clientX: number; clientY: number } {
  if ('touches' in ev) {
    const t = ev.touches[0] ?? ev.changedTouches?.[0];
    return { clientX: t?.clientX ?? 0, clientY: t?.clientY ?? 0 };
  }
  return { clientX: ev.clientX, clientY: ev.clientY };
}

function indexAmong(fieldset: HTMLFieldSetElement, siblingSelector: string): number {
  const parent = fieldset.parentElement;
  if (!parent) return -1;
  const siblings = Array.from(
    parent.querySelectorAll<HTMLFieldSetElement>(siblingSelector)
  );
  return siblings.indexOf(fieldset);
}
