/**
 * MapML-flavoured search control.
 *
 * Ports MapML.js's `SearchButton` (`src/mapml/control/SearchButton.js`)
 * to a MapLibre `IControl`. When the viewer opts in via
 * `controlslist="search"`, a 44×44 magnifier button is installed at
 * `top-left`. Clicking (or `Enter`-activating) it slides in a 250px-
 * wide search panel from the left edge of the map container, with an
 * input, a scrollable results list, and a close button.
 *
 * ## What Phase 2 covers
 *  - The button + panel scaffolding, `open` / `close`, `Escape`
 *    handling.
 *  - Default GeoJSON search: `Enter` in the input dispatches a fetch
 *    to every `map-link[rel="search"]` under a *checked* `<map-layer>`
 *    substituting `{searchTerms}` in the link's `tref`; the first
 *    feature of the first response drives navigation (bbox →
 *    `map.fitBounds`, point → `map.flyTo`), and all features render
 *    as clickable result buttons.
 *  - Clicking a result re-issues a search with the result's formatted
 *    name — matches MapML.js's `_selectResult` behaviour.
 *  - Arrow-key navigation within the results list.
 *
 * ## What Phase 2 explicitly does NOT cover (added in later phases)
 *  - Suggestions typeahead (`rel="suggestions"`, debounce, IME) — Phase 3.
 *  - Enable/disable state driven by a MutationObserver — Phase 4.
 *  - Cancelable `mapsearch` / `mapsuggestions` custom events — Phase 5.
 *
 * ## Panel host
 * The panel is appended to `map.getContainer()` so it slides over the
 * map area (matching MapML.js). Because the map container lives inside
 * the viewer's shadow root, the `.mapml-search-*` CSS injected there
 * (see [searchControl.css.ts](./searchControl.css)) styles it correctly.
 */

import type { IControl, Map as MapLibreMap } from 'maplibre-gl';

import type { MapmlViewer } from '../elements/mapml-viewer';
import type { Locale } from '../i18n/locale';

/** Minimal GeoJSON shape we consume from search endpoints. */
interface SearchFeature {
  readonly bbox?: readonly number[];
  readonly geometry?: {
    readonly coordinates?: readonly number[];
  };
  readonly properties?: Record<string, unknown>;
}

/** A checked `<map-layer>` and one of its search / suggestions `<map-link>`s. */
interface LinkHandle {
  readonly link: HTMLElement;
  readonly layer: HTMLElement;
}

/** A resolved fetch response bundled with the link + layer it came from. */
interface SearchResponse {
  readonly data: { readonly features?: readonly SearchFeature[] } | null;
  readonly link: HTMLElement;
  readonly layer: HTMLElement;
}

/**
 * Author-facing item shape consumed by `event.detail.setResults(items)`
 * on the `mapsearch` / `mapsuggestions` custom events. Ports the
 * `_setResults` item contract from MapML.js's `SearchButton.js`:
 *
 *   - `text` (required): display string.
 *   - `value`: if present, clicking the item refines the search by
 *     re-running the search pipeline with `value` as the query.
 *   - `lat` / `lng`: if `value` is absent, clicking navigates the map
 *     to the point at zoom 14.
 *   - `bbox` (`[west, south, east, north]`): if present, clicking
 *     drives `fitBounds` and supersedes `lat` / `lng`.
 */
export interface SearchResultItem {
  readonly text: string;
  readonly value?: string;
  readonly lat?: number;
  readonly lng?: number;
  readonly bbox?: readonly [number, number, number, number];
}

const SEARCH_ICON_SVG =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="24" width="24" viewBox="0 0 15 15" fill="currentColor">' +
  '<path d="M6 0C9.31 0 12 2.69 12 6C12 7.3 11.59 8.5 10.89 9.48L14.71 13.29C15.1 13.68 15.1 14.32 14.71 14.71C14.32 15.1 13.68 15.1 13.29 14.71L9.48 10.89C8.5 11.59 7.3 12 6 12C2.69 12 0 9.31 0 6C0 2.69 2.69 0 6 0ZM6 2C3.79 2 2 3.79 2 6C2 8.21 3.79 10 6 10C8.21 10 10 8.21 10 6C10 3.79 8.21 2 6 2Z"/>' +
  '</svg>';

const CLOSE_ICON_SVG =
  '<svg aria-hidden="true" xmlns="http://www.w3.org/2000/svg" height="18" width="18" viewBox="0 0 24 24" fill="currentColor">' +
  '<path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6 1.41-1.41z"/>' +
  '</svg>';

export class MapmlSearchControl implements IControl {
  readonly #viewer: MapmlViewer;
  readonly #locale: Locale;
  #map: MapLibreMap | undefined;
  #container: HTMLDivElement | undefined;
  #button: HTMLButtonElement | undefined;
  #panel: HTMLDivElement | undefined;
  #input: HTMLInputElement | undefined;
  #results: HTMLDivElement | undefined;
  #closeBtn: HTMLButtonElement | undefined;
  /** Aborts an in-flight `fetch` when a new one starts or the panel closes. */
  #abortController: AbortController | undefined;
  /**
   * Debounce timer for the {@link #onInput} handler. A pending timer
   * is cleared when a fresh keystroke arrives, when the user presses
   * Enter (search supersedes suggestions), and when the panel
   * closes. Ports MapML.js's 300 ms window from
   * `SearchButton.js:118` / `:135`.
   */
  #suggestDebounceTimer: number | undefined;
  /**
   * `true` while the user is inside an IME composition (kana / hanzi /
   * hangul input). We suppress `input` events during composition so we
   * don't fire fetches on intermediate pre-edit strings. Reset by
   * `compositionend`, which then triggers one debounced fetch.
   * Ports MapML.js's `_isComposing` gate.
   */
  #isComposing = false;
  /**
   * Light-DOM MutationObserver on the viewer element. Watches for:
   *   - `<map-layer>` add / remove (childList + subtree),
   *   - `checked` / `rel` / `src` attribute flips on any descendant.
   * Any mutation triggers {@link #updateDisabled}. Ports the observer
   * MapML.js installs in `SearchButton.js:174-193`. Set in
   * {@link #onAdd}, cleared in {@link #onRemove}.
   */
  #layerObserver: MutationObserver | undefined;
  /**
   * Nested MutationObservers attached to `<map-layer src="…">` shadow
   * roots. The main {@link #layerObserver} can't see grafted content
   * behind a shadow boundary, so for each remote layer we install a
   * child observer keyed by the layer element. Established lazily by
   * {@link #syncShadowObservers} whenever the outer observer fires
   * (or on initial install), and torn down in {@link #onRemove}.
   */
  #shadowObservers = new Map<Element, MutationObserver>();
  /**
   * Handle for the pending close-panel cleanup (transitionend +
   * setTimeout safety net) so {@link #openPanel} can cancel a
   * still-running close and prevent the safety net from re-hiding
   * the freshly-reopened panel. Cleared once the cleanup actually
   * runs.
   */
  #pendingClose:
    | { readonly cancel: () => void }
    | undefined;

  constructor(viewer: MapmlViewer) {
    this.#viewer = viewer;
    this.#locale = viewer.locale;
  }

  getDefaultPosition(): 'top-left' {
    return 'top-left';
  }

  onAdd(map: MapLibreMap): HTMLDivElement {
    this.#map = map;

    // Container matches the MapLibre control-group markup so it
    // stacks visually with zoom / reload / fullscreen.
    const container = document.createElement('div');
    container.className =
      'maplibregl-ctrl maplibregl-ctrl-group mapml-search-control';

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'mapml-search-button mapml-button';
    button.title = this.#locale.btnSearch;
    button.setAttribute('aria-label', this.#locale.btnSearch);
    // Start disabled — {@link #updateDisabled} flips this on if any
    // checked layer advertises a `<map-link rel="search">`. The
    // {@link #layerObserver} below re-runs the check on any DOM
    // change so late-arriving layers (or `checked` toggles) take
    // effect without a re-mount.
    button.setAttribute('aria-disabled', 'true');
    button.innerHTML = SEARCH_ICON_SVG;
    button.addEventListener('click', this.#onButtonClick);
    button.addEventListener('keydown', this.#onButtonKeydown);
    container.appendChild(button);
    this.#button = button;

    // Panel is a sibling of the map canvas inside the MapLibre
    // container so it slides over the canvas (matching MapML.js's
    // `map.getContainer().appendChild(panel)`).
    const panel = document.createElement('div');
    panel.className = 'mapml-search-panel';
    panel.setAttribute('hidden', '');
    // Keep interactions inside the panel from bubbling out to the
    // map (drag-to-pan, wheel-to-zoom).
    panel.addEventListener('mouseenter', this.#onPanelMouseEnter);
    panel.addEventListener('mouseleave', this.#onPanelMouseLeave);
    panel.addEventListener('wheel', this.#stopPropagation);
    panel.addEventListener('mousedown', this.#stopPropagation);
    map.getContainer().appendChild(panel);
    this.#panel = panel;

    const input = document.createElement('input');
    input.type = 'search';
    input.className = 'mapml-search-input';
    input.placeholder = this.#locale.searchPlaceholder;
    input.setAttribute('aria-label', this.#locale.btnSearch);
    input.addEventListener('keydown', this.#onInputKeydown);
    // Debounced typeahead — fires `rel="suggestions"` fetches as the
    // user types. IME composition suppresses intermediate fetches;
    // `compositionend` re-runs the debounce so the final composed
    // string is queried once.
    input.addEventListener('input', this.#onInput);
    input.addEventListener('compositionstart', this.#onCompositionStart);
    input.addEventListener('compositionend', this.#onCompositionEnd);
    panel.appendChild(input);
    this.#input = input;

    const results = document.createElement('div');
    results.className = 'mapml-search-results';
    panel.appendChild(results);
    this.#results = results;

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'mapml-search-close mapml-button';
    closeBtn.title = this.#locale.btnSearchClose;
    closeBtn.setAttribute('aria-label', this.#locale.btnSearchClose);
    closeBtn.innerHTML = CLOSE_ICON_SVG;
    closeBtn.addEventListener('click', this.#onCloseClick);
    panel.appendChild(closeBtn);
    this.#closeBtn = closeBtn;

    this.#container = container;

    // Wire the layer observer BEFORE the initial `#updateDisabled`
    // so we don't miss late-arriving mutations that happen between
    // check and observe.
    this.#layerObserver = new MutationObserver(() => this.#updateDisabled());
    this.#layerObserver.observe(this.#viewer, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['checked', 'rel', 'src']
    });
    this.#updateDisabled();

    return container;
  }

  onRemove(): void {
    this.#pendingClose?.cancel();
    this.#pendingClose = undefined;
    this.#abortController?.abort();
    this.#abortController = undefined;
    if (this.#suggestDebounceTimer !== undefined) {
      window.clearTimeout(this.#suggestDebounceTimer);
      this.#suggestDebounceTimer = undefined;
    }
    this.#layerObserver?.disconnect();
    this.#layerObserver = undefined;
    for (const obs of this.#shadowObservers.values()) obs.disconnect();
    this.#shadowObservers.clear();
    this.#button?.removeEventListener('click', this.#onButtonClick);
    this.#button?.removeEventListener('keydown', this.#onButtonKeydown);
    this.#closeBtn?.removeEventListener('click', this.#onCloseClick);
    this.#input?.removeEventListener('keydown', this.#onInputKeydown);
    this.#input?.removeEventListener('input', this.#onInput);
    this.#input?.removeEventListener('compositionstart', this.#onCompositionStart);
    this.#input?.removeEventListener('compositionend', this.#onCompositionEnd);
    this.#panel?.removeEventListener('mouseenter', this.#onPanelMouseEnter);
    this.#panel?.removeEventListener('mouseleave', this.#onPanelMouseLeave);
    this.#panel?.removeEventListener('wheel', this.#stopPropagation);
    this.#panel?.removeEventListener('mousedown', this.#stopPropagation);
    this.#panel?.remove();
    this.#container?.remove();
    this.#map = undefined;
    this.#container = undefined;
    this.#button = undefined;
    this.#panel = undefined;
    this.#input = undefined;
    this.#results = undefined;
    this.#closeBtn = undefined;
  }

  // ─── event handlers ────────────────────────────────────────────────

  #onButtonClick = (event: MouseEvent): void => {
    event.stopPropagation();
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    this.#openPanel();
  };

  #onButtonKeydown = (event: KeyboardEvent): void => {
    if (event.key !== 'Enter') return;
    event.stopPropagation();
    event.preventDefault();
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    this.#openPanel();
  };

  #onCloseClick = (event: MouseEvent): void => {
    event.stopPropagation();
    this.#closePanel();
  };

  #onInputKeydown = (event: KeyboardEvent): void => {
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.preventDefault();
      const input = this.#input;
      const results = this.#results;
      if (input && input.value) {
        input.value = '';
        if (results) results.innerHTML = '';
        // A pending suggestion fetch would just render results the
        // user has abandoned — cancel both the debounce and the
        // in-flight fetch.
        this.#cancelSuggest();
      } else {
        this.#closePanel();
      }
      return;
    }
    if (event.key === 'Enter') {
      event.stopPropagation();
      event.preventDefault();
      // Search supersedes any pending suggestion fetch — clear the
      // debounce so a stale suggestions response doesn't clobber the
      // search results we're about to render (matches MapML.js
      // `SearchButton.js:78-82`).
      this.#cancelSuggest();
      this.#doSearch(this.#input?.value.trim() ?? '');
      return;
    }
    if (event.key === 'ArrowDown' || event.key === 'Down') {
      event.stopPropagation();
      event.preventDefault();
      const first = this.#results?.querySelector<HTMLButtonElement>(
        '.mapml-search-result'
      );
      first?.focus();
    }
  };

  #onInput = (): void => {
    // IME pre-edit strings are meaningless as search queries —
    // wait until `compositionend` before scheduling a fetch.
    if (this.#isComposing) return;
    this.#scheduleSuggest();
  };

  #onCompositionStart = (): void => {
    this.#isComposing = true;
  };

  #onCompositionEnd = (): void => {
    this.#isComposing = false;
    // Fire one debounced fetch against the finalised composed
    // string (matches MapML.js `SearchButton.js:108-124`).
    this.#scheduleSuggest();
  };

  #onPanelMouseEnter = (): void => {
    this.#map?.scrollZoom.disable();
  };

  #onPanelMouseLeave = (): void => {
    this.#map?.scrollZoom.enable();
  };

  #stopPropagation = (event: Event): void => {
    event.stopPropagation();
  };

  // ─── panel show / hide ─────────────────────────────────────────────

  #openPanel(): void {
    const panel = this.#panel;
    const input = this.#input;
    const results = this.#results;
    if (!panel || !input || !results) return;
    // Cancel any in-flight close teardown so its safety-net timer
    // (or a late transitionend from the outgoing animation) can't
    // re-hide the panel we're about to open.
    this.#pendingClose?.cancel();
    this.#pendingClose = undefined;
    panel.removeAttribute('hidden');
    input.value = '';
    results.innerHTML = '';
    // Defer the class flip one frame so the transition actually
    // runs (browsers batch style + class in the same tick otherwise).
    window.requestAnimationFrame(() => {
      panel.classList.add('mapml-search-panel-open');
      input.focus();
    });
  }

  #closePanel(): void {
    const panel = this.#panel;
    const button = this.#button;
    if (!panel || !button) return;
    // Supersede any earlier pending close so its listener / timer
    // don't fire against a panel we're about to touch again.
    this.#pendingClose?.cancel();
    panel.classList.remove('mapml-search-panel-open');
    this.#cancelSuggest();
    this.#abortController?.abort();
    this.#abortController = undefined;
    let done = false;
    const onEnd = (): void => {
      if (done) return;
      done = true;
      panel.removeEventListener('transitionend', onEnd);
      window.clearTimeout(timer);
      this.#pendingClose = undefined;
      panel.setAttribute('hidden', '');
      button.focus();
    };
    panel.addEventListener('transitionend', onEnd);
    // Fallback if `transitionend` doesn't fire (panel wasn't visible
    // yet, reduced-motion, etc.). Matches MapML.js's 300ms safety net.
    const timer = window.setTimeout(onEnd, 300);
    this.#pendingClose = {
      cancel: (): void => {
        if (done) return;
        done = true;
        panel.removeEventListener('transitionend', onEnd);
        window.clearTimeout(timer);
        this.#pendingClose = undefined;
      }
    };
  }

  // ─── link discovery ────────────────────────────────────────────────

  /**
   * True when at least one *checked* `<map-layer>` under the viewer
   * carries a `<map-link rel="search">`. Ports MapML.js's
   * `_hasSearchLayers` in `SearchButton.js:225-236`.
   */
  #hasSearchLayers(): boolean {
    const layers = this.#viewer.querySelectorAll<HTMLElement>('map-layer[checked]');
    for (const layer of Array.from(layers)) {
      const root: ParentNode = layer.hasAttribute('src')
        ? layer.shadowRoot ?? layer
        : layer;
      if (root.querySelector('map-link[rel="search"]')) return true;
    }
    return false;
  }

  /**
   * Re-evaluate the button's enabled state against the current DOM.
   * Called by the {@link #layerObserver} on every mutation, and
   * synchronously once during {@link #onAdd}. When the button becomes
   * disabled while the panel is open, the panel closes so the user
   * can't type into a dead input. Ports MapML.js's `_updateDisabled`.
   */
  #updateDisabled(): void {
    const button = this.#button;
    if (!button) return;
    // Refresh shadow-root observers first \u2014 a newly-added remote
    // `<map-layer src>` may have just gained its shadow root.
    this.#syncShadowObservers();
    const enabled = this.#hasSearchLayers();
    button.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    if (!enabled) {
      // Close the panel if it's open \u2014 the user has no search links
      // to query against right now.
      const panel = this.#panel;
      if (panel && !panel.hasAttribute('hidden')) {
        this.#closePanel();
      }
    }
  }

  /**
   * For every `<map-layer src="\u2026">` under the viewer that has an
   * attached shadow root, install a nested MutationObserver on that
   * shadow root so mutations inside remote content (e.g. `<map-head>`
   * grafting after a fetch completes) trigger a re-check. Layers with
   * no `src` are covered by the outer {@link #layerObserver} (which
   * observes the viewer's light-DOM subtree).
   *
   * Idempotent \u2014 re-entering with the same layer is a no-op. When a
   * previously-observed layer is removed from the DOM the stale
   * observer is disconnected here.
   */
  #syncShadowObservers(): void {
    const observed = this.#shadowObservers;
    const seen = new Set<Element>();
    const srcLayers = this.#viewer.querySelectorAll<HTMLElement>('map-layer[src]');
    for (const layer of Array.from(srcLayers)) {
      const root = layer.shadowRoot;
      if (!root) continue;
      seen.add(layer);
      if (observed.has(layer)) continue;
      const obs = new MutationObserver(() => this.#updateDisabled());
      obs.observe(root, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ['rel']
      });
      observed.set(layer, obs);
    }
    // Prune observers for layers that are no longer under the viewer
    // or have lost their shadow root.
    for (const [layer, obs] of observed) {
      if (!seen.has(layer)) {
        obs.disconnect();
        observed.delete(layer);
      }
    }
  }

  /**
   * Walk every *checked* `<map-layer>` under the viewer and collect
   * its `<map-link rel="{rel}">` children. Remote-content layers (with
   * a `src` attribute) expose their `<map-head>` inside a shadow root
   * — matches MapML.js's `layer.src ? layer.shadowRoot : layer` idiom.
   */
  #getLinks(rel: string): LinkHandle[] {
    const out: LinkHandle[] = [];
    const layers = this.#viewer.querySelectorAll<HTMLElement>('map-layer[checked]');
    const selector = `map-link[rel="${rel}"]`;
    for (const layer of Array.from(layers)) {
      const root: ParentNode = layer.hasAttribute('src')
        ? layer.shadowRoot ?? layer
        : layer;
      const link = root.querySelector<HTMLElement>(selector);
      if (link) out.push({ link, layer });
    }
    return out;
  }

  #getSearchLinks(): LinkHandle[] {
    return this.#getLinks('search');
  }

  #getSuggestionsLinks(): LinkHandle[] {
    return this.#getLinks('suggestions');
  }

  /**
   * Substitute `{searchTerms}` in the link's `tref` and resolve the
   * result against the link's base URL. Ports the base-URL rule from
   * MapML.js's `getBase()` in `src/map-link.js` — shadow-hosted links
   * (inside a `<map-layer src="…">`) resolve against the host's `src`,
   * light-DOM links against the page.
   */
  #resolveUrl(link: HTMLElement, query: string): string {
    const tref = link.getAttribute('tref') ?? '';
    const substituted = tref.replace('{searchTerms}', encodeURIComponent(query));
    const root = link.getRootNode();
    let base: string;
    if (root instanceof ShadowRoot) {
      const host = root.host as HTMLElement;
      const src = host.getAttribute('src');
      base = src ? new URL(src, host.baseURI).href : link.baseURI;
    } else {
      base = link.baseURI;
    }
    try {
      return new URL(substituted, base).href;
    } catch {
      return substituted;
    }
  }

  // ─── search pipeline ───────────────────────────────────────────────
  /**
   * Debounce entry for the `input` handler. If the trimmed query is
   * shorter than 2 characters we clear the results and abort any
   * in-flight fetch — no schedule. Otherwise (re)start the 300 ms
   * timer that will call {@link #fetchSuggestions}. Matches MapML.js
   * `SearchButton.js:127-138`.
   */
  #scheduleSuggest(): void {
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    const input = this.#input;
    const results = this.#results;
    if (!input || !results) return;
    if (this.#suggestDebounceTimer !== undefined) {
      window.clearTimeout(this.#suggestDebounceTimer);
      this.#suggestDebounceTimer = undefined;
    }
    const query = input.value.trim();
    if (query.length < 2) {
      // Below the min-length threshold — clear stale results and
      // any in-flight fetch so the panel is quiet.
      results.innerHTML = '';
      this.#abortController?.abort();
      this.#abortController = undefined;
      return;
    }
    this.#suggestDebounceTimer = window.setTimeout(() => {
      this.#suggestDebounceTimer = undefined;
      this.#fetchSuggestions(query);
    }, 300);
  }

  /**
   * Cancel a pending debounce timer AND abort any in-flight
   * suggestions fetch. Called on Enter (search supersedes
   * suggestions), Escape-clear, and panel close.
   */
  #cancelSuggest(): void {
    if (this.#suggestDebounceTimer !== undefined) {
      window.clearTimeout(this.#suggestDebounceTimer);
      this.#suggestDebounceTimer = undefined;
    }
    this.#abortController?.abort();
    this.#abortController = undefined;
  }

  #fetchSuggestions(query: string): void {
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    const suggestionsLinks = this.#getSuggestionsLinks();
    if (suggestionsLinks.length === 0) return;

    this.#abortController?.abort();
    const abortController = new AbortController();
    this.#abortController = abortController;
    const { signal } = abortController;

    const fetches = suggestionsLinks.map(({ link, layer }) => {
      const url = this.#resolveUrl(link, query);
      return fetch(url, { signal })
        .then((r) => r.json())
        .then((data) => ({ data, link, layer }) as SearchResponse);
    });

    void Promise.allSettled(fetches).then((settled) => {
      if (signal.aborted) return;
      const responses: SearchResponse[] = [];
      for (const s of settled) {
        if (s.status === 'fulfilled') responses.push(s.value);
      }
      // Give authors a chance to render a bespoke result set. If they
      // call `preventDefault()` we skip the built-in renderer; otherwise
      // fall through. Matches MapML.js's dispatch in `SearchButton.js`.
      const cancelled = !this.#dispatchResults(
        'mapsuggestions',
        query,
        responses
      );
      if (!cancelled) this.#defaultSuggestionsHandler(responses);
    });
  }

  /**
   * Default renderer for a suggestions response. Unlike
   * {@link #defaultSearchHandler}, this does NOT navigate the map —
   * suggestions are purely typeahead affordances; navigation only
   * happens when the user commits to a suggestion (by clicking it,
   * which re-runs {@link #doSearch}, or by pressing Enter).
   */
  #defaultSuggestionsHandler(responses: readonly SearchResponse[]): void {
    this.#renderResults(responses);
  }
  #doSearch(query: string): void {
    if (!query) return;
    if (this.#button?.getAttribute('aria-disabled') === 'true') return;
    const searchLinks = this.#getSearchLinks();
    if (searchLinks.length === 0) return;

    this.#abortController?.abort();
    const abortController = new AbortController();
    this.#abortController = abortController;
    const { signal } = abortController;

    const fetches = searchLinks.map(({ link, layer }) => {
      const url = this.#resolveUrl(link, query);
      return fetch(url, { signal })
        .then((r) => r.json())
        .then((data) => ({ data, link, layer }) as SearchResponse);
    });

    void Promise.allSettled(fetches).then((settled) => {
      if (signal.aborted) return;
      const responses: SearchResponse[] = [];
      for (const s of settled) {
        if (s.status === 'fulfilled') responses.push(s.value);
      }
      const cancelled = !this.#dispatchResults('mapsearch', query, responses);
      if (!cancelled) this.#defaultSearchHandler(responses);
    });
  }

  #defaultSearchHandler(responses: readonly SearchResponse[]): void {
    this.#renderResults(responses);
    // Navigate to the first feature of the first non-empty response.
    for (const { data } of responses) {
      const first = data?.features?.[0];
      if (first) {
        this.#navigateToFeature(first);
        break;
      }
    }
    this.#input?.focus();
  }

  /**
   * Dispatch a cancelable `mapsearch` or `mapsuggestions` CustomEvent
   * on the viewer. The event `detail` carries the query, per-link
   * responses, and a bound `setResults(items)` callback so the author's
   * handler can render a bespoke result list without touching the
   * shadow DOM. Returns `false` when the author called `preventDefault()`
   * — that's the signal to skip the default renderer.
   *
   * Ports the two dispatch sites in MapML.js `SearchButton.js` —
   * see the `_fetchSuggestions` / `_doSearch` `dispatchEvent` calls.
   */
  #dispatchResults(
    type: 'mapsearch' | 'mapsuggestions',
    query: string,
    responses: readonly SearchResponse[]
  ): boolean {
    const event = new CustomEvent(type, {
      bubbles: true,
      cancelable: true,
      detail: {
        query,
        responses,
        setResults: (items: readonly SearchResultItem[]): void =>
          this.#setResults(items)
      }
    });
    return this.#viewer.dispatchEvent(event);
  }

  /**
   * Author-facing result renderer. Consumed via the `setResults`
   * callback in the `detail` of the two custom events. Each item is
   * rendered as a `<button.mapml-search-result>` — clicking one either
   * re-runs `#doSearch(value)` (when `value` is present, i.e.
   * suggestion-shaped) or navigates directly to the item's coordinates
   * / bbox (result-shaped). Ports MapML.js's `_setResults` verbatim.
   */
  #setResults(items: readonly SearchResultItem[]): void {
    const results = this.#results;
    if (!results) return;
    results.innerHTML = '';
    if (!Array.isArray(items)) return;
    for (const item of items) {
      const btn = document.createElement('button');
      btn.className = 'mapml-search-result';
      btn.type = 'button';
      btn.textContent = item.text ?? '';
      const bound = item;
      btn.addEventListener('click', () => {
        if (bound.value != null) {
          // Suggestion mode — refine the search.
          if (this.#input) this.#input.value = bound.value;
          this.#doSearch(bound.value);
        } else {
          this.#navigateToItem(bound);
        }
      });
      btn.addEventListener('keydown', this.#onResultKeydown);
      results.appendChild(btn);
    }
  }

  /** Navigate to a plain author-provided item (bbox or lat/lng pair). */
  #navigateToItem(item: SearchResultItem): void {
    const map = this.#map;
    if (!map) return;
    if (isBbox4(item.bbox)) {
      const [west, south, east, north] = item.bbox;
      map.fitBounds(
        [
          [west, south],
          [east, north]
        ],
        { animate: false }
      );
      return;
    }
    if (typeof item.lat === 'number' && typeof item.lng === 'number') {
      map.jumpTo({ center: [item.lng, item.lat], zoom: 14 });
    }
  }

  #renderResults(responses: readonly SearchResponse[]): void {
    const results = this.#results;
    if (!results) return;
    results.innerHTML = '';
    for (const { data } of responses) {
      const features = data?.features;
      if (!features) continue;
      for (const feature of features) {
        const btn = document.createElement('button');
        btn.className = 'mapml-search-result';
        btn.type = 'button';
        btn.textContent = this.#formatResultName(feature.properties);
        const boundFeature = feature;
        btn.addEventListener('click', () => this.#selectResult(boundFeature));
        btn.addEventListener('keydown', this.#onResultKeydown);
        results.appendChild(btn);
      }
    }
  }

  #onResultKeydown = (event: KeyboardEvent): void => {
    const btn = event.currentTarget as HTMLButtonElement;
    const prev = btn.previousElementSibling as HTMLButtonElement | null;
    const next = btn.nextElementSibling as HTMLButtonElement | null;
    if (
      event.key === 'ArrowDown' ||
      event.key === 'ArrowRight' ||
      event.key === 'Down' ||
      event.key === 'Right'
    ) {
      event.stopPropagation();
      event.preventDefault();
      if (next?.classList.contains('mapml-search-result')) next.focus();
      return;
    }
    if (
      event.key === 'ArrowUp' ||
      event.key === 'ArrowLeft' ||
      event.key === 'Up' ||
      event.key === 'Left'
    ) {
      event.stopPropagation();
      event.preventDefault();
      if (prev?.classList.contains('mapml-search-result')) prev.focus();
      else this.#input?.focus();
      return;
    }
    if (event.key === 'Escape') {
      event.stopPropagation();
      event.preventDefault();
      this.#input?.focus();
    }
  };

  #formatResultName(props: SearchFeature['properties']): string {
    const fallback = this.#locale.searchResultWithNoName;
    if (!props) return fallback;
    const displayName = props['display_name'];
    if (typeof displayName === 'string' && displayName.length > 0) return displayName;
    const name = props['name'];
    const parts: string[] = [];
    if (typeof name === 'string' && name.length > 0) parts.push(name);
    // Build context from common geocoder property names (Photon, etc.).
    for (const key of ['city', 'county', 'state', 'country'] as const) {
      const v = props[key];
      if (typeof v === 'string' && v.length > 0 && v !== name) parts.push(v);
    }
    return parts.length > 0 ? parts.join(', ') : fallback;
  }

  #selectResult(feature: SearchFeature): void {
    const input = this.#input;
    if (!input) return;
    // Use the result's display name as a refined search query
    // (matches MapML.js's `_selectResult`).
    const name = this.#formatResultName(feature.properties);
    input.value = name;
    this.#doSearch(name);
  }

  // ─── navigation ────────────────────────────────────────────────────

  #navigateToFeature(feature: SearchFeature): void {
    const map = this.#map;
    if (!map) return;
    // Standard GeoJSON `bbox`, then Photon-style `properties.extent`.
    let bbox: readonly number[] | undefined = feature.bbox;
    if (!isBbox4(bbox)) {
      const ext = feature.properties?.['extent'];
      if (Array.isArray(ext)) bbox = ext as readonly number[];
    }
    if (isBbox4(bbox)) {
      const [west, south, east, north] = bbox;
      map.fitBounds(
        [
          [west, south],
          [east, north]
        ],
        { animate: false }
      );
      return;
    }
    const coords = feature.geometry?.coordinates;
    if (Array.isArray(coords) && coords.length >= 2) {
      const lon = coords[0];
      const lat = coords[1];
      if (typeof lon === 'number' && typeof lat === 'number') {
        const zoom = readNumber(feature.properties?.['zoom']) ?? 14;
        map.jumpTo({ center: [lon, lat], zoom });
      }
    }
  }
}

function isBbox4(v: readonly number[] | undefined): v is readonly [number, number, number, number] {
  return (
    Array.isArray(v) &&
    v.length === 4 &&
    v.every((n) => typeof n === 'number' && Number.isFinite(n))
  );
}

function readNumber(v: unknown): number | undefined {
  return typeof v === 'number' && Number.isFinite(v) ? v : undefined;
}
