import type { MapInputDef } from '../core/template';
import {
  formatPcrsExtent,
  projectionMaxZoom,
  projectionPcrsBounds,
  type PcrsBounds
} from '../core/crs';
import { inputsToPcrsBounds, inputsToZoomRange } from '../core/inputBounds';
import {
  parseExtentMeta,
  parseZoomMeta,
  type ExtentMeta,
  type ZoomMeta
} from '../core/mapMeta';
import { isMapmlProjection, type MapmlProjection } from '../core/projection';
import { shadowCrossingClosest, shadowCrossingClosestByTag } from '../core/shadow';
import { MapInput } from './map-input';
import { MapLayer, type LayerExtent } from './map-layer';
import { MapLink } from './map-link';
import type { MapMeta } from './map-meta';
import { MapSelect } from './map-select';
import type { MapmlViewer } from './mapml-viewer';
import { nextControlId, settingsGearSvg } from '../controls/layerControlDom';
import { installDragToReorder } from '../controls/layerControlDrag';
import type { Locale } from '../i18n/locale';
import { MapmlLayerGroup } from '../core/mapml/MapmlLayerGroup';

/** Monotonic id source for `MapExtent`'s internal `MapmlLayerGroup`. */
let nextExtentGroupId = 0;

/**
 * `<map-extent>` — projection-scoped grouping of `<map-input>` and `<map-link>`.
 *
 * Provides:
 *   - `units`: the projection identifier (`OSMTILE`, `GLOBE`); the URL template
 *     engine refuses unsupported projections.
 *   - `checked` / `hidden`: visibility flags ANDed with the parent `<map-layer>`'s
 *     own `checked`/`hidden` to determine whether registered renderer layers
 *     should be shown.
 *   - `opacity`: 0..1 applied to all renderer layers registered by descendant
 *     `<map-link>` elements.
 *
 * Child `<map-link>` elements ask their owning extent for the `MapInputDef`
 * list before evaluating their `tref`.
 */
export class MapExtent extends HTMLElement {
  static readonly observedAttributes = [
    'units',
    'checked',
    'hidden',
    'label',
    'opacity',
    'disabled'
  ] as const;

  /**
   * Internal {@link MapmlLayerGroup} that owns this extent's
   * `RendererLayer` handles. Replaces the earlier `#childLayerIds:
   * Set<string>` + `#opacity: number` pair — the group holds handles
   * directly, and the group's cascade drives visibility + opacity on
   * the handles.
   *
   * `MapmlLayerGroup.effectiveRendered()` ANDs `checked && !disabled`
   * against every ancestor's own `checked && !disabled`, so the
   * `<map-layer>` → `<map-extent>` → leaf composition happens through
   * the tree cascade automatically — no manual `checked && !disabled`
   * composition at this element's `setRendered` call site anymore.
   *
   * Populated via {@link registerChildLayer} / {@link unregisterChildLayer}
   * (the transitional shims called by `<map-link>` today); in Stage 8
   * `<map-link>` will call `group.addLayer(handle)` directly and the
   * shims disappear.
   */
  #group = new MapmlLayerGroup(`map-extent-${++nextExtentGroupId}`);
  /**
   * Whether the layer-control settings drawer (the fieldset's
   * `<div class="mapml-layer-item-settings">`) is expanded. Persisted
   * on the element itself so it survives `LayerControl` rebuilds \u2014
   * without which a rebuild triggered mid-interaction (e.g. a
   * `<map-select>` change firing `unregisterChildLayer` +
   * `registerChildLayer`) would slam the drawer shut and hide the
   * control the user is still interacting with. MapML.js keeps the
   * `<details open>` state around the same way \u2014 the DOM node
   * carrying the state is the source of truth.
   */
  #settingsExpanded = false;
  /** Cached at connect-time; see the equivalent field on `MapLayer`. */
  #owningViewer: MapmlViewer | null = null;
  #owningLayer: MapLayer | null = null;
  /**
   * Set while {@link #validateDisabled} is writing the `disabled`
   * attribute so the observer doesn't re-enter this element's own
   * validation. External writes still fall through to the observer,
   * where they get overwritten by the next validation pass — the
   * `disabled` attribute is a computed read-only reflection of
   * `#validateDisabled`, matching MapML.js semantics.
   */
  #writingDisabled = false;

  /**
   * Public getter for this extent's internal {@link MapmlLayerGroup}.
   * Exposed so `<map-link>` (from Stage 8 onwards) can push handles
   * directly via `extent.group.addLayer(handle)`, and `MapmlViewer`'s
   * reorder pipeline can restack this extent's leaves via
   * `group.reorder(…)`. Return type is widened to the subclass so
   * callers who need the MapML-shape `setChecked` / `setDisabled` /
   * `setHidden` axes can reach them without a downcast.
   */
  get group(): MapmlLayerGroup {
    return this.#group;
  }

  get viewer(): MapmlViewer | null {
    // Shadow-crossing lookup so a remote-hosted extent (Slice B
    // onwards, inside `<map-layer src="…">`'s shadow root) can still
    // find the enclosing `<mapml-viewer>`. `closest()` alone does
    // not cross shadow boundaries.
    return (
      this.#owningViewer ??
      (shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null)
    );
  }

  get parentLayer(): MapLayer | null {
    // Use a shadow-crossing walker so remote-content extents (Slice B:
    // `<map-layer src="…">` grafts them into a shadow root) can still
    // reach the owning layer — `Element.closest()` deliberately does
    // not cross shadow boundaries.
    return (
      this.#owningLayer ??
      shadowCrossingClosest(
        this,
        (el): el is MapLayer => el instanceof MapLayer
      )
    );
  }

  get units(): MapmlProjection {
    const raw = this.getAttribute('units') ?? 'OSMTILE';
    return isMapmlProjection(raw) ? raw : 'OSMTILE';
  }

  get checked(): boolean {
    return this.hasAttribute('checked');
  }

  set checked(value: boolean) {
    if (value) this.setAttribute('checked', '');
    else this.removeAttribute('checked');
  }

  /**
   * Read-only reflection of the `disabled` attribute. The attribute is
   * written only by {@link #validateDisabled}; setting it from author
   * code has no persistent effect — the next validation pass will
   * overwrite it. Matches MapML.js's `map-extent.disabled` semantics.
   *
   * An extent is disabled when:
   *   1. Its `units` don't match the viewer's `projection`, or
   *   2. None of its tref-bearing `<map-link>` children is currently
   *      visible (bounds don't overlap the map view, current zoom is
   *      outside every link's zoom range, or the extent has no
   *      tref-bearing links at all).
   *
   * Rule 2 tracks the current view: the viewer's `moveend` handler
   * re-runs `validateDisabled` on every extent so panning off a
   * layer's bounds flips its author-visible state to disabled.
   */
  get disabled(): boolean {
    return this.hasAttribute('disabled');
  }

  get label(): string {
    // MapML.js falls back to `mapEl.locale.dfExtent` (e.g. "Sub-layer"),
    // not the projection identifier. `viewer` is null between construction
    // and connectedCallback — in that window we return `units` as a
    // technical placeholder so unlabelled extents still self-describe.
    const attr = this.getAttribute('label');
    if (attr !== null) return attr;
    return this.viewer?.locale.dfExtent ?? this.units;
  }

  get opacity(): number {
    return this.#group.getOpacity();
  }

  /**
   * Reflect the numeric opacity back to the `opacity` attribute so
   * `element.opacity = 0.5` and `element.setAttribute('opacity', '0.5')`
   * both round-trip through the same code path. Out-of-range values are
   * ignored to match MapML.js's setter contract.
   */
  set opacity(value: number) {
    const n = Number(value);
    if (!Number.isFinite(n) || n < 0 || n > 1) return;
    this.setAttribute('opacity', String(n));
  }

  setOpacity(value: number): void {
    const clamped = Math.max(0, Math.min(1, Number.isFinite(value) ? value : 1));
    // Fan-out to renderer handles is handled by the group's cascade.
    this.#group.setOpacity(clamped);
  }

  /**
   * True when this extent's registered renderer layers should be
   * painted — i.e. the extent is `checked`, not `disabled`, and its
   * owning `<map-layer>` is `checked`. The `hidden` attribute is
   * deliberately **not** consulted (per the MapML spec, `hidden`
   * hides the extent from the layer control but does not affect
   * rendering).
   *
   * NOTE: distinct from MapML.js's `isVisible()` — which asks
   * whether the extent's *bounds* and *zoom* intersect the current
   * map view. `<map-link>.isVisible()` in this port carries that
   * viewport-intersection semantic; `renders` is purely about the
   * `checked` / `disabled` on/off state driving the renderer.
   */
  get renders(): boolean {
    if (this.disabled) return false;
    const layer = this.parentLayer;
    const layerOn = layer ? layer.checked : true;
    return layerOn && this.checked;
  }

  /**
   * Snapshot of all direct `<map-input>` + `<map-select>` children as
   * plain definitions. `<map-select>`s are synthesised as `type:
   * "hidden"` inputs whose `value` is the current selection \u2014 the
   * template engine's existing fallback branch (`imageValueFor` /
   * `queryValueFor`) then substitutes them without special-casing.
   * Matches MapML.js's `_setUpTemplateVars` behaviour, which likewise
   * treats a `<map-select>` as an input whose `value` is `htmlselect.value`.
   */
  getInputs(): MapInputDef[] {
    // MapML elements adopted from a remote doc carry the xhtml
    // namespace and auto-upgrade at insertion time (see
    // `MapLayer.#loadRemote`), so we do NOT need to force-upgrade
    // descendants here. An earlier version called
    // `customElements.upgrade(this)` as a safety net, but that
    // synchronously fires connectedCallback on sibling `<map-link>`s
    // that the HTML parser has not yet reached, which inverts the
    // order in which tile links register their renderer handles
    // (labels PNG ends up beneath imagery JPG, etc.).
    const inputs: MapInputDef[] = [];
    for (const child of this.children) {
      if (child instanceof MapInput) {
        inputs.push(child.toDefinition());
      } else if (child instanceof MapSelect) {
        inputs.push(child.toDefinition());
      }
    }
    return inputs;
  }

  /**
   * Parsed direct-child `<map-meta name="extent">` as PCRS bounds
   * (already reprojected from whichever CS the author wrote), or
   * `null` when absent / malformed. Only *direct* children are
   * inspected, so a meta nested deeper (e.g. inside a `<map-link>`
   * sub-tree) does not leak up.
   */
  get extentMeta(): ExtentMeta | null {
    const m = this.querySelector(
      ':scope > map-meta[name="extent"]'
    ) as MapMeta | null;
    if (m === null) return null;
    return parseExtentMeta(m.content, this.units);
  }

  /**
   * Parsed direct-child `<map-meta name="zoom">` as `{ min, max }`, or
   * `null` when absent / malformed.
   */
  get zoomMeta(): ZoomMeta | null {
    const m = this.querySelector(
      ':scope > map-meta[name="zoom"]'
    ) as MapMeta | null;
    if (m === null) return null;
    return parseZoomMeta(m.content);
  }

  /**
   * Bounds contributed by this extent to its parent layer's union, in
   * PCRS meters. Sourced from:
   *
   *   1. `<map-input type="location">` axis pair, via
   *      {@link inputsToPcrsBounds}.
   *   2. Direct-child `<map-meta name="extent">` (GCRS \u2192 PCRS).
   *   3. `null` when neither is present.
   *
   * The parent `<map-layer>` walks its extents' `pcrsBounds` and unions
   * them; when nothing contributes, the layer falls back to its own
   * meta / projection default. Splitting the intermediate value out
   * keeps the derivation composable across the layer / extent pair
   * and mirrors MapML.js's `_extentLayer.bounds` field.
   */
  get pcrsBounds(): PcrsBounds | null {
    const inputs = this.getInputs();
    const inputPcrs = inputsToPcrsBounds(inputs, this.units);
    if (inputPcrs !== null) return inputPcrs;
    const em = this.extentMeta;
    if (em !== null) return em.bounds;
    return null;
  }

  /**
   * Zoom range contributed by this extent to its parent layer's union.
   * Uses MapML.js's fallback priority (own `<map-meta name="zoom">` \u2192
   * parent `<map-layer>`'s `<map-meta name="zoom">` \u2192
   * `<map-input type="zoom">` min/max), matching `_getZoomBounds` in
   * `map-link.js`. Returns `null` when nothing declares a range.
   */
  get zoomRange(): { minZoom: number; maxZoom: number } | null {
    const zm = this.zoomMeta;
    if (zm !== null) return { minZoom: zm.min, maxZoom: zm.max };
    const parentZm = this.parentLayer?.zoomMeta ?? null;
    if (parentZm !== null) return { minZoom: parentZm.min, maxZoom: parentZm.max };
    const inputs = this.getInputs();
    const iz = inputsToZoomRange(inputs);
    return iz;
  }

  /**
   * The multi-CRS extent envelope for this element (matches MapML.js's
   * `<map-extent>.extent`). See {@link MapmlExtent} in `src/core/crs.ts`
   * for the field layout.
   *
   * Bounds fallback chain (first hit wins):
   *   1. {@link MapExtent.pcrsBounds} \u2014 own `<map-input>` pair or
   *      own `<map-meta name="extent">`.
   *   2. Parent `<map-layer>`'s `<map-meta name="extent">`.
   *   3. Projection's whole extent.
   *
   * Zoom fallback: {@link MapExtent.zoomRange} (which already cascades
   * through extent-meta \u2192 parent-layer-meta \u2192 input min/max)
   * \u2192 projection's native zoom range.
   *
   * The middle step (parent-layer meta) matches MapML.js's
   * `<map-link>.getFallbackBounds` walk-up via `getMeta('extent')`, so
   * a bare `<map-extent>` still inherits a useful bbox when the layer
   * declares one.
   *
   * Returns `null` only when the extent isn't yet attached to a viewer.
   */
  get extent(): LayerExtent | null {
    const projection = this.viewer?.projection ?? this.units;
    let pcrs = this.pcrsBounds;
    if (pcrs === null) {
      const lm = this.parentLayer?.extentMeta ?? null;
      if (lm !== null) {
        pcrs = lm.bounds;
      } else {
        pcrs = projectionPcrsBounds(projection);
      }
    }
    const zoom =
      this.zoomRange ?? { minZoom: 0, maxZoom: projectionMaxZoom(projection) };
    return formatPcrsExtent(pcrs, projection, zoom);
  }

  registerChildLayer(id: string): void {
    // Look up the concrete `RendererLayer` handle the renderer stashed
    // in its `#legacyHandles` map when `<map-link>` called
    // `addRasterTileLayer` / `addWmsTileLayer` / `addImageLayer`.
    // Once Stage 8 lands, `<map-link>` will hand us the handle
    // directly and this shim can be deleted (Stage 9).
    const handle = this.viewer?.renderer.getHandle(id);
    if (handle === undefined) return;
    if (this.#group.hasLayer(handle)) return;
    this.#group.addLayer(handle);
    // `group.setRendered(this.renders)` may have been called before
    // the handle was attached; the group's `#pushEffectiveToChild`
    // already pushed the correct visibility + opacity onto the leaf
    // during `addLayer`. Nothing else to do here.
    this.viewer?.notifyLayersChanged();
  }

  unregisterChildLayer(id: string): void {
    // `<map-link>` teardown calls `renderer.removeLayer(id)` *before*
    // `extent.unregisterChildLayer(id)`, which means the handle is
    // already gone from `#legacyHandles`. Look it up by id in the
    // group instead of via the renderer's registry.
    for (const leaf of this.#group.children()) {
      if (leaf.id === id) {
        this.#group.removeLayer(leaf);
        break;
      }
    }
    this.viewer?.notifyLayersChanged();
  }

  /** Number of renderer layers this extent currently owns. */
  get childLayerCount(): number {
    return this.#group.size;
  }

  /**
   * Iterate the renderer layer ids owned by this extent, in group
   * DOM order (which is the order in which `<map-link>` children
   * registered themselves). Consumed by
   * {@link MapmlViewer.applyLayerReorder} to re-stack MapLibre
   * layers after a drag-to-reorder.
   */
  *childLayerIds(): IterableIterator<string> {
    for (const child of this.#group.children()) yield child.id;
  }

  /**
   * Force this extent's own group-rendered state to reflect its
   * `checked` and `disabled` axes. Layer-level `checked` is composed
   * automatically via the tree cascade (this group is a child of
   * the owning layer's group), so it must NOT be consulted here —
   * doing so would double-count the layer's contribution.
   *
   * The two axes are pushed independently onto the group; the
   * subclass's `effectiveRendered()` ANDs them (and cascades to
   * leaves + descendant groups) internally. Same net effect as the
   * previous single `setRendered(checked && !disabled)` call, with
   * the composition responsibility moved off this element and onto
   * the group primitive that owns the semantics.
   */
  refreshVisibility(): void {
    this.#group.setChecked(this.checked);
    this.#group.setDisabled(this.disabled);
  }

  /**
   * Teardown + re-apply every direct-child `<map-link>` so a
   * `<map-select>` change (or any other extent-level input mutation)
   * flows through as a fresh template resolution. Each link's
   * {@link MapLink.refresh} unregisters its MapLibre source /
   * listeners and re-fires `#apply()`, which reads the current
   * {@link getInputs} \u2014 including the up-to-date
   * `<map-select>.value` \u2014 to build the new URL.
   *
   * Mirrors MapML.js's `_extentLayer.redraw()` seam that
   * `<map-select>`'s change handler kicks in `map-select.js`.
   */
  refreshLinks(): void {
    for (const child of this.children) {
      if (child instanceof MapLink) {
        child.refresh();
      }
    }
    // Inline features under `<map-link rel="features">` don't fetch,
    // but their light-DOM `<map-feature>` set may reference the
    // select value indirectly (e.g. via author-supplied styles \u2014
    // future work). Rebuilding the parent layer's aggregated GeoJSON
    // source is a cheap microtask-coalesced no-op when nothing
    // changed, so it's safe to trigger unconditionally.
    this.parentLayer?.notifyFeaturesChanged();
  }

  /**
   * Pan + zoom the viewer to this extent. Reads
   * {@link MapExtent.extent} and drives MapLibre's `fitBounds`
   * using the envelope's `topLeft.gcrs` / `bottomRight.gcrs` corners,
   * clamped to the declared `zoom.minZoom` / `zoom.maxZoom` range.
   *
   * MapML.js's `zoomTo` calls `map.setView(center, Util.getMaxZoom(...))`
   * which picks the tightest zoom that keeps the bbox visible in the
   * viewport, then clamps to `[minZoom, maxZoom]`. Our MapLibre
   * equivalent lets `fitBounds` pick the natural zoom (via
   * `maxZoom`), then bumps up if it lands below `minZoom`.
   */
  zoomTo(): void {
    const map = this.viewer?.renderer.map;
    if (!map) return;
    const ext = this.extent;
    if (ext === null) return;
    const west = ext.topLeft.gcrs.horizontal;
    const north = ext.topLeft.gcrs.vertical;
    const east = ext.bottomRight.gcrs.horizontal;
    const south = ext.bottomRight.gcrs.vertical;
    map.fitBounds(
      [
        [west, south],
        [east, north]
      ],
      {
        animate: false,
        padding: 0,
        maxZoom: ext.zoom.maxZoom
      }
    );
    if (map.getZoom() < ext.zoom.minZoom) {
      map.setZoom(ext.zoom.minZoom);
    }
  }

  /**
   * Outer HTML for this extent, used by the layer-context-menu's
   * “Copy Sub-layer” action.
   */
  getOuterHTML(): string {
    return this.outerHTML;
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<mapml-viewer>`
   * (or `null` when this extent is detached). Shadow-crossing so a
   * remote-hosted extent inside a `<map-layer src="…">` shadow root
   * still resolves the enclosing viewer. Thin alias for the
   * {@link viewer} getter, kept for source-compatibility with
   * MapML.js callers (`ext.getMapEl()`).
   */
  getMapEl(): MapmlViewer | null {
    return this.viewer;
  }

  /**
   * MapML.js JS-API parity: returns the ancestor `<map-layer>` (or
   * `null` when this extent is detached). Thin alias for
   * {@link parentLayer}, kept for source-compatibility with
   * MapML.js callers (`ext.getLayerEl()`).
   */
  getLayerEl(): MapLayer | null {
    return this.parentLayer;
  }

  /**
   * MapML.js JS-API parity: look up the nearest `<map-meta>` for a
   * given axis (`'zoom'` / `'extent'` / `'cs'`). Search order:
   *
   *   1. this extent's own direct-child `<map-meta name=…>`,
   *   2. the parent `<map-layer>`'s direct-child `<map-meta name=…>`
   *      — via {@link MapLayer.contentRoot} so remote-content layers
   *      (with grafted `<map-head>` metas in the shadow root) resolve
   *      transparently.
   *
   * Nested metas (e.g. under a `<map-link>`) are deliberately NOT
   * searched — matches MapML.js's `:scope >` traversal.
   *
   * Returns `null` for any name outside the recognised set or when no
   * matching meta exists. Mirrors MapML.js's `map-extent.getMeta`.
   */
  getMeta(name: string): MapMeta | null {
    const key = name.toLowerCase();
    if (key !== 'zoom' && key !== 'extent' && key !== 'cs') return null;
    // Walk direct children rather than `querySelector(':scope > …')`:
    // `:scope` isn't universally honoured by `ShadowRoot.querySelector`
    // (Chromium returns null for `shadowRoot.querySelector(':scope > x')`
    // even when `x` is a direct child). Same rationale as the `label`
    // getter in `<map-layer>`. Iterating `.children` is safe on both
    // `Element` and `ShadowRoot`.
    const findDirect = (root: Element | ShadowRoot): MapMeta | null => {
      for (const el of root.children) {
        if (el.tagName.toLowerCase() !== 'map-meta') continue;
        if (el.getAttribute('name')?.toLowerCase() === key) {
          return el as MapMeta;
        }
      }
      return null;
    };
    const own = findDirect(this);
    if (own !== null) return own;
    const parent = this.parentLayer;
    if (parent === null) return null;
    return findDirect(parent.contentRoot);
  }

  connectedCallback(): void {
    // `data-moving` on this element (or an ancestor `<map-layer>`)
    // signals a drag-to-reorder DOM shuffle: skip the register-and-
    // validate work so the extent's renderer child layers stay
    // attached across the DOM move. Matches MapML.js's `data-moving`
    // contract in `src/map-extent.js`.
    if (this.closest('[data-moving]')) return;
    // Shadow-crossing lookups: remote-hosted extents (Slice B) sit
    // inside `<map-layer>`'s shadow root, so `Element.closest` alone
    // would stop at the shadow boundary and return null.
    this.#owningViewer = shadowCrossingClosestByTag(
      this,
      'mapml-viewer'
    ) as MapmlViewer | null;
    this.#owningLayer = shadowCrossingClosestByTag(
      this,
      'map-layer'
    ) as MapLayer | null;
    // Attach this extent's group as a child of the owning layer's
    // group so opacity + rendered-state compose multiplicatively
    // through the tree — matches MapML.js Leaflet's DOM-based CSS
    // opacity nesting (`layer._container > extent._container > tile`
    // where CSS opacity composes as a product). No owning layer
    // (rare / detached extent) → fall back to root so the extent is
    // still visible.
    const owningGroup =
      this.#owningLayer?.group ?? this.#owningViewer?.renderer.root;
    if (owningGroup && !owningGroup.hasLayer(this.#group)) {
      owningGroup.addLayer(this.#group);
    }
    // Compute the projection-mismatch disabled state now that we have
    // a reference to the viewer. Also nudges the owning layer to
    // re-tally its extents so its own `disabled` state stays in sync.
    this.#validateDisabled();
    this.#owningLayer?.validateDisabled();
    // Sync the group's `checked` + `disabled` axes with our own state
    // so leaves attached later inherit correctly. NOTE: layer-level
    // checked is NOT consulted here — the tree cascade handles that
    // via the owning layer's group. We only carry the extent's own
    // axes; the group's `effectiveRendered()` ANDs them (and the
    // ancestor chain) internally.
    this.#group.setChecked(this.checked);
    this.#group.setDisabled(this.disabled);
  }

  disconnectedCallback(): void {
    // On drag-to-reorder we set `data-moving` on the element we're
    // about to move; when a `<map-layer>` is the moved element this
    // extent's ancestor still carries it, so a `closest` walk finds
    // it. When *this* extent is the one being dragged, `data-moving`
    // is on self. Either way, skip teardown so renderer state
    // survives the DOM move.
    if (this.closest('[data-moving]') || this.hasAttribute('data-moving')) return;
    // Snapshot the layer we were attached to before we clear it, so
    // the removal can trigger a re-tally on the (still-connected)
    // layer's remaining extents. Without this, removing the last
    // disabled extent from an otherwise-disabled layer would leave
    // the layer stuck in the disabled state.
    const layer = this.#owningLayer;
    // Detach the group from its parent (usually the owning layer's
    // group; falls back to renderer.root for the rare orphan-extent
    // case). Any handles still in the group are torn down via
    // `<map-link>`'s own disconnect path (fires before ours because
    // links are descendants), so the group is empty here.
    const owningGroup =
      layer?.group ?? this.#owningViewer?.renderer.root;
    if (owningGroup && owningGroup.hasLayer(this.#group)) {
      owningGroup.removeLayer(this.#group);
    }
    // The extent's child <map-link>s have already torn themselves down via
    // their own disconnectedCallback, but if this extent had no child links
    // the viewer still needs to refresh the layer control.
    this.#owningViewer?.notifyLayersChanged();
    this.#owningViewer = null;
    this.#owningLayer = null;
    layer?.validateDisabled();
  }

  attributeChangedCallback(
    name: string,
    _oldValue: string | null,
    newValue: string | null
  ): void {
    if (name === 'checked') {
      this.refreshVisibility();
      // A visibility change on this extent can strand an open query
      // popup whose result came from a `<map-link rel="query">` under
      // it. Dismiss it (no-op for a static feature-click popup) so
      // unchecking the extent clears the popup — matching MapML.js.
      this.viewer?.renderer.closeQueryPopup();
      // `<map-link rel="features">` doesn't register a renderer-layer
      // id, so the composite feature-source needs an out-of-band poke
      // to pick up (or drop) the features under this extent. The
      // walker in `MapLayer.#rebuildFeatures` filters by
      // `extent.renders`, so this notify covers both toggle
      // directions.
      this.parentLayer?.notifyFeaturesChanged();
      // Remote-mode `rel="features"` links additionally need a fresh
      // fetch when re-checked \u2014 their moveend listener bails while
      // unchecked, so the cached graft (if any) may be stale for the
      // current viewport.
      if (this.renders) {
        for (const child of this.children) {
          if (
            child instanceof MapLink &&
            child.rel === 'features' &&
            child.hasAttribute('tref')
          ) {
            child.refreshFeatures();
          }
        }
      }
      // Don't notify the layer control; the extent checkbox in the
      // settings panel is already in the right state from the click.
      // See the equivalent comment in MapLayer.attributeChangedCallback.
    } else if (name === 'hidden') {
      // `hidden` controls only whether this extent appears in the
      // settings panel — it must NOT gate rendering. Per the MapML
      // spec (map-extent-markup / map-layer-markup skills), "the
      // layer is rendered or not depending on the `checked` attribute
      // state" regardless of `hidden`. So we rebuild the control but
      // deliberately skip `refreshVisibility()`.
      this.viewer?.notifyLayersChanged();
    } else if (name === 'label') {
      this.viewer?.notifyLayersChanged();
    } else if (name === 'units') {
      // A projection change re-runs the disable check; the owning
      // layer then re-tallies its extents.
      this.#validateDisabled();
      this.parentLayer?.validateDisabled();
    } else if (name === 'disabled') {
      if (this.#writingDisabled) return;
      // Author writes to `disabled` don't stick — recompute from the
      // canonical inputs. If the author-written value happens to
      // match the computed value the recomputation is a no-op; if
      // not, the attribute snaps back on the next microtask.
      this.#validateDisabled();
      // Disabled extents don't render; force visibility fan-out.
      this.refreshVisibility();
      // Rebuild the layer control so the fieldset picks up the new
      // disabled styling (italic label, disabled checkbox/slider).
      this.viewer?.notifyLayersChanged();
    } else if (name === 'opacity') {
      // Parse the attribute; missing/blank/non-numeric falls back to 1.
      const parsed = newValue === null ? 1 : Number(newValue);
      this.setOpacity(Number.isFinite(parsed) ? parsed : 1);
      // Rebuild the layer control so the slider's `value` reflects the
      // new opacity (the slider is initialised from `#group.getOpacity()`
      // when the fieldset is built).
      this.viewer?.notifyLayersChanged();
    }
  }

  /**
   * Public entry point for parents/tests to force a disabled recheck.
   * Delegates to the private `#validateDisabled`. Named without a
   * leading `_` because it's a real API surface (called from the
   * owning `<map-layer>`'s own `validateDisabled`).
   */
  validateDisabled(): boolean {
    return this.#validateDisabled();
  }

  /**
   * Compare this extent's raw `units` attribute against the viewer's
   * **effective** projection (the `projection` getter, which folds an
   * unsupported author value such as `CBMTILE` down to the renderable
   * `OSMTILE`). We bypass only the sanitising `units` getter — reading
   * the raw `units` attribute — so an author-written `units="CBMTILE"`
   * is still recognised as its own projection. Using the effective
   * viewer projection (not the raw `projection` attribute) means that
   * when a `projection="CBMTILE"` viewer degrades to `OSMTILE`, a
   * sibling `units="OSMTILE"` extent matches (stays enabled and draws)
   * while the un-renderable `units="CBMTILE"` extent is disabled.
   * Missing attributes fall back to the same `OSMTILE` default the
   * getters use.
   */
  #projectionMatch(): boolean {
    const rawUnits = this.getAttribute('units') ?? 'OSMTILE';
    const effectiveViewerProj = this.viewer?.projection ?? 'OSMTILE';
    return rawUnits.toUpperCase() === effectiveViewerProj.toUpperCase();
  }

  /**
   * Recompute the `disabled` state and reflect it to the attribute.
   * MapML.js's `_validateDisabled` rule: an extent is disabled when
   * the projection doesn't match **or** none of its tref-bearing
   * `<map-link>` children is currently visible (bounds don't overlap
   * the map view, or current zoom is outside every link's zoom range).
   *
   * The current-view check is what makes layers/sub-layers flip to
   * disabled as the user pans off their bounds. The viewer schedules
   * a global re-tally on every `moveend`.
   *
   * Returns the boolean `disabled` state so `<map-layer>` can tally
   * without re-reading the attribute.
   */
  #validateDisabled(): boolean {
    const shouldBeDisabled =
      !this.#projectionMatch() || !this.#anyTemplateVisible();
    const isDisabled = this.hasAttribute('disabled');
    if (shouldBeDisabled === isDisabled) return shouldBeDisabled;
    // Guard the observer so `attributeChangedCallback('disabled')`
    // doesn't loop back into this method.
    this.#writingDisabled = true;
    try {
      if (shouldBeDisabled) this.setAttribute('disabled', '');
      else this.removeAttribute('disabled');
    } finally {
      this.#writingDisabled = false;
    }
    // Author-visible state changed → renderer visibility and layer
    // control both need a refresh. Also nudge the owning layer to
    // re-tally: an extent whose disabled state flipped may take its
    // parent layer with it (e.g. the last disabled extent on a layer
    // becoming enabled must clear the layer's `disabled` too). The
    // parent's tally is a pure function of its extents, so re-running
    // it here can only ever flip once. Matches MapML.js, whose
    // `map-extent._validateDisabled` calls `_handleChange` which in
    // turn re-evaluates the parent map-layer.
    this.refreshVisibility();
    this.#owningLayer?.validateDisabled();
    this.viewer?.notifyLayersChanged();
    return shouldBeDisabled;
  }

  /**
   * True when at least one tref-bearing `<map-link>` descendant of
   * this extent is visible at the current map view. An extent with
   * *no* tref-bearing links has nothing to draw and counts as
   * "not visible" \u2014 matching MapML.js's `_validateDisabled`, where
   * `disabledTemplateCount === totalTemplateCount` is true (both zero)
   * for an empty extent.
   */
  #anyTemplateVisible(): boolean {
    const links = this.querySelectorAll(
      ':scope > map-link[rel="tile"], :scope > map-link[rel="image"], :scope > map-link[rel="features"], :scope > map-link[rel="query"]'
    );
    if (links.length === 0) return false;
    for (const link of links) {
      // Guard against un-upgraded children (rare, but possible during
      // HTML-parser insertion): only real `MapLink` instances have
      // `isVisible`.
      const maybe = link as HTMLElement & { isVisible?: () => boolean };
      if (typeof maybe.isVisible === 'function' && maybe.isVisible()) {
        return true;
      }
    }
    return false;
  }

  /**
   * Build the MapML.js-style layer-control fieldset for this extent. The
   * returned `<fieldset class="mapml-layer-extent">` carries the same class
   * structure as MapML.js so authors can target it with the same CSS.
   *
   * `locale` is passed in by the parent {@link MapLayer.getLayerControlHTML}
   * so all UI strings come from the same {@link Locale} object that
   * drives the rest of the viewer's chrome.
   */
  getLayerControlHTML(locale: Locale): HTMLFieldSetElement {
    const fieldset = document.createElement('fieldset');
    fieldset.className = 'mapml-layer-extent';
    fieldset.setAttribute('aria-grabbed', 'false');

    const properties = document.createElement('div');
    properties.className = 'mapml-layer-item-properties';
    fieldset.appendChild(properties);

    const settings = document.createElement('div');
    settings.className = 'mapml-layer-item-settings';
    settings.hidden = !this.#settingsExpanded;
    fieldset.appendChild(settings);

    // Toggle (checkbox + name)
    const toggleLabel = document.createElement('label');
    toggleLabel.className = 'mapml-layer-item-toggle';
    properties.appendChild(toggleLabel);

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.className = 'leaflet-control-layers-selector';
    checkbox.checked = this.checked;
    checkbox.addEventListener('change', () => {
      this.checked = checkbox.checked;
      // See `MapLayer.getLayerControlHTML` for the `map-change`
      // contract: dispatched only from user-driven layer-control
      // interaction, never from programmatic property or attribute
      // writes. Matches MapML.js's
      // `createLayerControlForExtent.js#changeCheck`.
      this.dispatchEvent(new CustomEvent('map-change'));
    });
    toggleLabel.appendChild(checkbox);

    const nameSpan = document.createElement('span');
    nameSpan.className = 'mapml-extent-item-name';
    const nameId = `mapml-extent-item-name-${nextControlId()}`;
    nameSpan.id = nameId;
    nameSpan.textContent = this.label;
    fieldset.setAttribute('aria-labelledby', nameId);
    toggleLabel.appendChild(nameSpan);

    // Buttons (remove, settings)
    const controls = document.createElement('div');
    controls.className = 'mapml-layer-item-controls';
    properties.appendChild(controls);

    const removeBtn = document.createElement('button');
    removeBtn.type = 'button';
    removeBtn.className = 'mapml-layer-item-remove-control mapml-button';
    removeBtn.title = locale.lmRemoveExtent;
    removeBtn.innerHTML = "<span aria-hidden='true'>&#10005;</span>";
    removeBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.remove();
    });
    controls.appendChild(removeBtn);

    const settingsBtn = document.createElement('button');
    settingsBtn.type = 'button';
    settingsBtn.className = 'mapml-layer-item-settings-control mapml-button';
    settingsBtn.title = locale.lmExtentSettings;
    settingsBtn.setAttribute('aria-expanded', String(this.#settingsExpanded));
    const settingsIconHost = document.createElement('span');
    settingsIconHost.className = 'mapml-button-icon';
    settingsIconHost.setAttribute('aria-hidden', 'true');
    settingsIconHost.appendChild(settingsGearSvg());
    settingsBtn.appendChild(settingsIconHost);
    settingsBtn.addEventListener('click', () => {
      const willOpen = Boolean(settings.hidden);
      settings.hidden = !willOpen;
      this.#settingsExpanded = willOpen;
      settingsBtn.setAttribute('aria-expanded', String(willOpen));
    });
    controls.appendChild(settingsBtn);

    // Opacity control
    const opacityDetails = document.createElement('details');
    opacityDetails.className = 'mapml-layer-item-details mapml-control-layers';
    settings.appendChild(opacityDetails);

    const opacitySummary = document.createElement('summary');
    opacitySummary.textContent = locale.lcOpacity;
    const summaryId = `mapml-extent-item-opacity-${nextControlId()}`;
    opacitySummary.id = summaryId;
    opacityDetails.appendChild(opacitySummary);

    const opacitySlider = document.createElement('input');
    opacitySlider.type = 'range';
    opacitySlider.min = '0';
    opacitySlider.max = '1';
    opacitySlider.step = '0.1';
    opacitySlider.value = String(this.#group.getOpacity());
    opacitySlider.setAttribute('aria-labelledby', summaryId);
    opacitySlider.addEventListener('input', () => {
      this.setOpacity(Number(opacitySlider.value));
    });
    opacityDetails.appendChild(opacitySlider);

    // `<map-select>` children: each one contributes a
    // `<details><summary><label>name</label></summary><select>\u2026</select></details>`
    // block to the extent's settings drawer. Ports MapML.js's
    // `createLayerControlForExtent.js` `frag.appendChild(mapSelects[i].selectdetails)`.
    // The `<details>` element is cached on the `<map-select>` itself,
    // so successive layer-control rebuilds re-attach the same live
    // `<select>` and the current selection persists across rebuilds.
    for (const child of this.children) {
      if (child instanceof MapSelect) {
        settings.appendChild(child.getLayerControlDetails());
      }
    }

    // Reflect the current `disabled` state onto the freshly-built
    // fieldset. Matches MapML.js's `toggleLayerControlDisabled`:
    // disable the checkbox + opacity slider and italicise the label
    // and opacity summary. Buttons (remove, settings) stay enabled so
    // that the context menu and settings drawer remain reachable —
    // matching MapML.js's accessibility contract for disabled items.
    //
    // NB: we tag the fieldset with the class `mapml-layer-item-disabled`
    // (and not `aria-disabled="true"` on the outer fieldset) because
    // ARIA's disabled semantics cascade to descendants — including the
    // remove/settings buttons, which we deliberately want to stay
    // reachable.
    if (this.disabled) {
      fieldset.classList.add('mapml-layer-item-disabled');
      checkbox.disabled = true;
      checkbox.setAttribute('aria-disabled', 'true');
      opacitySlider.disabled = true;
      opacitySlider.setAttribute('aria-disabled', 'true');
      toggleLabel.style.fontStyle = 'italic';
      opacitySummary.style.fontStyle = 'italic';
    }

    // Wire drag-to-reorder for sub-layers within their parent layer's
    // grouped-extents fieldset. Only extents sharing the same parent
    // `<map-layer>` can swap places. Ports the pointer/touch handler
    // from MapML.js's `createLayerControlForExtent.js`.
    (fieldset as HTMLFieldSetElement & { _mapExtent?: MapExtent })._mapExtent = this;
    const viewer = this.viewer;
    const owningLayer = this.parentLayer;
    const hitTestRoot = viewer?.shadowRoot as ShadowRoot | null;
    if (viewer && owningLayer && hitTestRoot) {
      installDragToReorder({
        fieldset,
        hitTestRoot,
        siblingSelector: 'fieldset.mapml-layer-extent',
        onDrop: (newOrder) => {
          const orderedExtents: MapExtent[] = [];
          for (const fs of newOrder) {
            const e = (fs as HTMLFieldSetElement & { _mapExtent?: MapExtent })
              ._mapExtent;
            if (e) orderedExtents.push(e);
          }
          viewer.applyExtentReorder(owningLayer, orderedExtents);
        }
      });
    }

    return fieldset;
  }
}

