/**
 * TypeScript port of MapML.js's viewer-level `matchMedia(query)` API
 * (`../MapML.js/src/mapml/elementSupport/viewers/matchMedia.js`).
 *
 * Extends the native `window.matchMedia` set of media features with
 * map-specific ones so authors can write CSS-style queries against the
 * live viewer state:
 *
 *   - `map-projection`   — matches the viewer's `projection` attribute
 *     (lowercased for the comparison).
 *   - `map-zoom`         — integer, current zoom level.
 *   - `map-top-left-easting` / `map-top-left-northing` /
 *     `map-bottom-right-easting` / `map-bottom-right-northing` —
 *     integer PCRS corner values of the viewer's current extent.
 *   - `prefers-color-scheme` — delegated to `window.matchMedia`, so
 *     the same OS-level setting wins.
 *   - `prefers-lang`     — matches the primary subtag of
 *     `navigator.language`.
 *   - `prefers-map-content` — reads `M.options.contentPreference` (not
 *     wired in MapML-MapLibre yet; returns an empty list, matching
 *     upstream when the option is unset).
 *
 * The return value is a live {@link MediaQueryList}-shaped object: it
 * exposes `matches` / `media` and `addEventListener('change', …)` /
 * `removeEventListener('change', …)` (via {@link EventTarget}), so
 * consumers can register a listener the same way they would for a
 * `window.matchMedia` result. Change detection is driven by:
 *
 *   1. The viewer's own `map-moveend` DOM event — dispatched by
 *      {@link MapmlViewer} on every MapLibre `moveend`, covering all
 *      of `map-zoom` / `map-*-easting` / `map-*-northing`.
 *   2. The viewer's `map-projectionchange` DOM event — dispatched
 *      whenever the `projection` attribute changes. (Live projection
 *      switching isn't rendered in v1, but the event still fires so
 *      queries observing `map-projection` react.)
 *   3. `window.matchMedia('(prefers-color-scheme: dark)')` change
 *      events — for the OS-level color-scheme flip.
 *
 * The listener wiring only installs when the caller has at least one
 * `change` listener registered, and is torn down when the last one
 * unregisters — matches upstream's lazy observe/unobserve pattern.
 */

import type { FeatureNode } from 'media-query-parser';
import { parseMediaQueryList } from 'media-query-parser';
import { solveMediaQueryList } from 'media-query-solver';

import type { MapmlExtent } from '../core/crs';
import type { MapmlProjection } from '../core/projection';
import { M } from '../i18n/locale';

/**
 * The subset of `<mapml-viewer>` (or any future MapML host element)
 * that {@link matchMedia} needs to read state from and subscribe to.
 *
 * Keeping the surface narrow makes the function trivially unit-testable
 * against a hand-rolled mock — no real MapLibre map required.
 */
export interface MatchMediaMapContext {
  /**
   * Current MapML projection. Compared verbatim (lowercased) against
   * `(map-projection: …)` query values.
   */
  readonly projection: MapmlProjection;
  /**
   * Current integer zoom level. Fractional MapLibre zooms are
   * truncated by the viewer's own `zoom` getter before we ever see
   * them — matches MapML.js, which is integer-only.
   */
  readonly zoom: number;
  /**
   * Current multi-CRS extent envelope. `null` before the underlying
   * renderer has initialised — any `map-*-easting` / `map-*-northing`
   * feature evaluates to `unknown` in that window (so `not (…)` is
   * `unknown` too), matching how `window.matchMedia` treats unknown
   * features.
   */
  readonly extent: MapmlExtent | null;
  addEventListener(type: string, listener: EventListener): void;
  removeEventListener(type: string, listener: EventListener): void;
}

/**
 * Names of the map-specific media features this bridge understands.
 * Anything outside this list falls through to the media-query-solver
 * default handling (i.e. `window.matchMedia`-style semantics).
 */
const MAP_RANGE_FEATURES = new Set([
  'map-zoom',
  'map-top-left-easting',
  'map-top-left-northing',
  'map-bottom-right-easting',
  'map-bottom-right-northing'
]);

/**
 * Evaluate a `<map-*>`-scoped range feature against the current
 * viewer state. Returns `'unknown'` when the extent isn't available
 * yet or the feature is out of scope — matches upstream.
 */
function solveRangeFeature(
  featureNode: FeatureNode,
  ctx: MatchMediaMapContext
): 'true' | 'false' | 'unknown' {
  const feature = featureNode.feature;
  if (!feature.startsWith('map-')) return 'unknown';
  const currentValue = getMapFeatureValue(feature, ctx);
  if (currentValue === undefined) return 'unknown';

  // Range-feature comparisons only make sense with a numeric RHS.
  // The parser returns numeric values as `{ _t: 'number', value: N }`
  // / `{ _t: 'dimension', value: N }`; both expose `.value` as a
  // number.
  const readValue = (
    node: { value: unknown } | undefined
  ): number | undefined => {
    if (!node || node.value === undefined) return undefined;
    const v = (node as { value: { value?: unknown } }).value.value;
    return typeof v === 'number' ? v : undefined;
  };

  if (featureNode.context === 'value') {
    // Plain case: `<mf-name>: <mf-value>` — e.g. `(map-zoom: 15)`.
    const plain = featureNode as { value: { value: unknown } };
    const rhs = readValue({ value: plain.value });
    if (rhs === undefined) return 'unknown';
    return currentValue === rhs ? 'true' : 'false';
  }

  if (featureNode.context === 'range') {
    // Single-op range case: `<mf-name> <mf-comparison> <mf-value>` —
    // e.g. `(map-zoom < 15)`. The double-range shape (`0 <= map-zoom
    // < 15`) is not accepted upstream; the parser produces a
    // different node shape for it and we deliberately don't handle
    // it (matches MapML.js).
    const range = featureNode as {
      op?: string;
      value: { value: unknown };
    };
    const rhs = readValue({ value: range.value });
    if (rhs === undefined) return 'unknown';
    switch (range.op) {
      case '<':
        return currentValue < rhs ? 'true' : 'false';
      case '<=':
        return currentValue <= rhs ? 'true' : 'false';
      case '>':
        return currentValue > rhs ? 'true' : 'false';
      case '>=':
        return currentValue >= rhs ? 'true' : 'false';
      case '=':
        return currentValue === rhs ? 'true' : 'false';
      default:
        return 'unknown';
    }
  }

  return 'unknown';
}

/**
 * Look up the numeric current value for one of the `map-*` range
 * features. Returns `undefined` when the viewer's extent hasn't been
 * computed yet (renderer not ready) so the caller can decay to
 * `'unknown'` and match upstream semantics.
 */
function getMapFeatureValue(
  feature: string,
  ctx: MatchMediaMapContext
): number | undefined {
  if (feature === 'map-zoom') return ctx.zoom;
  const extent = ctx.extent;
  if (extent === null) return undefined;
  switch (feature) {
    case 'map-top-left-easting':
      return Math.trunc(extent.topLeft.pcrs.horizontal);
    case 'map-top-left-northing':
      return Math.trunc(extent.topLeft.pcrs.vertical);
    case 'map-bottom-right-easting':
      return Math.trunc(extent.bottomRight.pcrs.horizontal);
    case 'map-bottom-right-northing':
      return Math.trunc(extent.bottomRight.pcrs.vertical);
    default:
      return undefined;
  }
}

/**
 * Feature-catalogue shape accepted by {@link solveMediaQueryList}'s
 * `features` config option. Extracted locally instead of imported to
 * keep the surface obvious (the exported name in the solver package
 * is buried under a `Partial<Omit<…>>` chain).
 */
type FeatureCatalogue = Record<
  string,
  | {
      type: 'discrete';
      values: Array<string | number>;
    }
  | {
      type: 'range';
      valueType: 'length' | 'integer' | 'resolution';
      canBeZero: boolean;
      canBeNegative: boolean;
      extraValues?: Record<string, number | 'unknown'>;
    }
>;

/**
 * Build the `features` map handed to `media-query-solver` for its
 * catalogue-based fast path. Values are recomputed on every call so
 * `matches` sees the current viewer state — the solver reads the
 * getters as it walks the AST.
 *
 * Field shapes mirror upstream's `matchMedia.js` — see the module
 * docstring for the full list of supported features.
 */
function buildFeatures(ctx: MatchMediaMapContext): FeatureCatalogue {
  return {
    'prefers-lang': {
      type: 'discrete',
      get values(): string[] {
        return [navigator.language.substring(0, 2)];
      }
    },
    'map-projection': {
      type: 'discrete',
      get values(): string[] {
        return [ctx.projection.toLowerCase()];
      }
    },
    'map-zoom': {
      type: 'range',
      valueType: 'integer',
      canBeNegative: false,
      canBeZero: true,
      get extraValues(): Record<string, number | 'unknown'> {
        return { min: 0, max: ctx.zoom };
      }
    },
    'map-top-left-easting': {
      type: 'range',
      valueType: 'integer',
      canBeNegative: true,
      canBeZero: true
    },
    'map-top-left-northing': {
      type: 'range',
      valueType: 'integer',
      canBeNegative: true,
      canBeZero: true
    },
    'map-bottom-right-easting': {
      type: 'range',
      valueType: 'integer',
      canBeNegative: true,
      canBeZero: true
    },
    'map-bottom-right-northing': {
      type: 'range',
      valueType: 'integer',
      canBeNegative: true,
      canBeZero: true
    },
    'prefers-color-scheme': {
      type: 'discrete',
      get values(): string[] {
        return [
          typeof window !== 'undefined' &&
          typeof window.matchMedia === 'function' &&
          window.matchMedia('(prefers-color-scheme: dark)').matches
            ? 'dark'
            : 'light'
        ];
      }
    },
    'prefers-map-content': {
      type: 'discrete',
      get values(): string[] {
        // MapML.js reads `M.options.contentPreference`; the option is
        // present in its `GlobalM.js` but is not seeded anywhere by
        // default. MapML-MapLibre's `M.options` doesn't declare it at
        // all, so authors who set it get the same behaviour they'd
        // get upstream. Fall back to an empty list when unset.
        const value = (M.options as unknown as { contentPreference?: unknown })
          .contentPreference;
        if (Array.isArray(value)) return value as string[];
        if (typeof value === 'string') return [value];
        return [];
      }
    }
  };
}

/**
 * Compute the `matches` verdict for the given AST + viewer state.
 *
 * Wraps {@link solveMediaQueryList} with our unknown-feature bridge
 * so `map-*` and `prefers-lang` / `prefers-color-scheme` /
 * `prefers-map-content` route through the same code path.
 */
function evaluate(
  parsedQuery: ReturnType<typeof parseMediaQueryList>,
  ctx: MatchMediaMapContext
): boolean {
  const features = buildFeatures(ctx);
  const result = solveMediaQueryList(parsedQuery, {
    features,
    solveUnknownFeature: (featureNode: FeatureNode) => {
      const feature = featureNode.feature;
      const featureValues = (features as Record<string, { values?: unknown }>)[
        feature
      ];
      // `context === 'boolean'` (feature name only, no value) matches
      // any non-empty value list.
      if (featureNode.context === 'boolean') {
        const list = featureValues?.values as unknown as
          | string[]
          | undefined;
        return list !== undefined && list.length > 0 ? 'true' : 'false';
      }
      if (feature === 'prefers-lang') {
        const list = (features['prefers-lang'] as { values: string[] }).values;
        const rhs = getStringValue(featureNode);
        return rhs !== undefined && list.includes(rhs) ? 'true' : 'false';
      }
      if (MAP_RANGE_FEATURES.has(feature)) {
        return solveRangeFeature(featureNode, ctx);
      }
      if (feature === 'map-projection') {
        const list = (features['map-projection'] as { values: string[] })
          .values;
        const rhs = getStringValue(featureNode);
        return rhs !== undefined && list.includes(rhs) ? 'true' : 'false';
      }
      if (feature === 'prefers-color-scheme') {
        const list = (
          features['prefers-color-scheme'] as { values: string[] }
        ).values;
        const rhs = getStringValue(featureNode);
        return rhs !== undefined && list.includes(rhs) ? 'true' : 'false';
      }
      if (feature === 'prefers-map-content') {
        const list = (
          features['prefers-map-content'] as { values: string[] }
        ).values;
        const rhs = getStringValue(featureNode);
        return rhs !== undefined && list.includes(rhs) ? 'true' : 'false';
      }
      return 'false';
    }
  });
  return result === 'true';
}

/**
 * Extract a string value from a `context: 'value'` feature node —
 * used for the discrete features (`prefers-lang`, `map-projection`,
 * `prefers-color-scheme`, `prefers-map-content`).
 *
 * The parser exposes identifier values as `{ _t: 'ident', value: '…' }`;
 * numeric values (as in `(map-zoom: 5)`) go through the range path.
 */
function getStringValue(featureNode: FeatureNode): string | undefined {
  if (featureNode.context !== 'value') return undefined;
  const node = featureNode as { value: { value: unknown } };
  const v = node.value.value;
  return typeof v === 'string' ? v : undefined;
}

/**
 * MapML-flavoured `matchMedia`, called with the viewer element as
 * `this`. Returns an `EventTarget`-based live matcher analogous to
 * `window.matchMedia`'s `MediaQueryList`.
 *
 * See the module docstring for the full list of supported features
 * and the change-detection cadence.
 */
export function matchMedia(
  this: MatchMediaMapContext,
  query: string
): MediaQueryList {
  const parsedQuery = parseMediaQueryList(query);
  const ctx = this;

  let matches = evaluate(parsedQuery, ctx);

  // Extend a fresh EventTarget so `mql.addEventListener('change', …)`
  // works with the exact same shape `window.matchMedia` returns.
  // Casting to `MediaQueryList` is intentional: the DOM lib type is
  // marked as having a `Symbol(Symbol.toStringTag)`-tagged internal
  // slot we can't fabricate, but every reachable property + method
  // matches.
  const mediaQueryList = Object.assign(new EventTarget(), {
    matches,
    media: query,
    listeners: [] as EventListener[],
    onchange: null as ((this: MediaQueryList, ev: MediaQueryListEvent) => unknown) | null,

    addEventListener(type: string, listener: EventListener) {
      if (type === 'change') {
        (this as unknown as { listeners: EventListener[] }).listeners.push(
          listener
        );
        // Start observing when the first listener registers.
        if (
          (this as unknown as { listeners: EventListener[] }).listeners
            .length === 1
        ) {
          observeProperties();
        }
      }
      EventTarget.prototype.addEventListener.call(this, type, listener);
    },

    removeEventListener(type: string, listener: EventListener) {
      if (type === 'change') {
        const self = this as unknown as { listeners: EventListener[] };
        self.listeners = self.listeners.filter((l) => l !== listener);
        if (self.listeners.length === 0) {
          stopObserving?.();
          stopObserving = undefined;
        }
      }
      EventTarget.prototype.removeEventListener.call(this, type, listener);
    }
  }) as unknown as MediaQueryList;

  let stopObserving: (() => void) | undefined;

  const observeProperties = (): void => {
    const notifyIfChanged = (): void => {
      const newMatches = evaluate(parsedQuery, ctx);
      if (newMatches !== (mediaQueryList as { matches: boolean }).matches) {
        (mediaQueryList as { matches: boolean }).matches = newMatches;
        mediaQueryList.dispatchEvent(new Event('change'));
      }
    };

    ctx.addEventListener('map-projectionchange', notifyIfChanged);
    ctx.addEventListener('map-moveend', notifyIfChanged);

    // `prefers-color-scheme` reacts to the OS-level flip.
    let colorSchemeQuery: MediaQueryList | undefined;
    if (
      typeof window !== 'undefined' &&
      typeof window.matchMedia === 'function'
    ) {
      colorSchemeQuery = window.matchMedia('(prefers-color-scheme: dark)');
      colorSchemeQuery.addEventListener('change', notifyIfChanged);
    }

    stopObserving = (): void => {
      ctx.removeEventListener('map-projectionchange', notifyIfChanged);
      ctx.removeEventListener('map-moveend', notifyIfChanged);
      colorSchemeQuery?.removeEventListener('change', notifyIfChanged);
    };
  };

  return mediaQueryList;
}
