import type { MapmlViewer } from '../elements/mapml-viewer';
import { M, type Locale } from '../i18n/locale';
import {
  type CopyLocationPoint,
  copyExtentMeta,
  copyLocationFeature,
  copyMapMLDocument,
  pasteToViewer,
  writeToClipboard
} from './contextMenuCopyPaste';

/**
 * Right-click / keyboard-activated context menu for `<mapml-viewer>`.
 *
 * Item ordering matches MapML.js's `src/mapml/handlers/ContextMenu.js`
 * verbatim (Back / Forward / Reload / Fullscreen / — / Copy / Paste /
 * — / Toggle Controls / Toggle Debug Mode / View Source). Copy opens
 * a submenu popup (Map / Extent / Location) mounted as a sibling of
 * the main menu in the viewer's shadow root; Paste consumes the
 * clipboard and delegates to {@link pasteToViewer}. Toggle Debug Mode
 * flips the debug overlay (tile grid + coordinate panel + layer
 * bounding boxes) via {@link MapmlViewer.toggleDebug}. View Source calls
 * {@link MapmlViewer.viewSource}, which opens a new tab with the
 * pretty-printed viewer markup.
 *
 * Currently active items: Back / Forward / Reload / Fullscreen / Copy
 * (with Map / Extent / Location submenu) / Paste / Toggle Controls /
 * Toggle Debug Mode / View Source.
 *
 * The menu is rendered into the viewer's shadow root (not into a
 * MapLibre control well) so its positioning is unconstrained.
 *
 * Keyboard semantics match MapML.js
 * (see src/mapml/handlers/ContextMenu.js + src/mapml-viewer.js):
 *
 *   Map-wide (viewer focused, menu may be closed):
 *     - `Ctrl+R`   reload (only when the history ring has > 1 entry;
 *                  otherwise the browser's own reload is allowed through)
 *     - `Alt+ArrowLeft`   back()
 *     - `Alt+ArrowRight`  forward()
 *
 *   Menu-open (focus inside the menu):
 *     - `F`   toggle fullscreen
 *     - `D`   toggle debug overlay
 *     - `T`   toggle controls
 *     - `C`   open Copy submenu (focus lands on first submenu item)
 *     - `P`   paste from clipboard
 *     - `V`   view source (opens a new tab with pretty-printed markup)
 *     - `Enter` / `Space`   activate focused item
 *     - `Escape`   close
 *     - `ArrowUp` / `ArrowDown` / `Home` / `End`   navigation
 *     - `ArrowRight` on the Copy item opens the submenu
 *
 *   Copy submenu open:
 *     - `ArrowUp` / `ArrowDown` / `Home` / `End`  navigate submenu
 *     - `ArrowLeft`  close submenu, refocus Copy
 *     - `Enter` / `Space`  activate focused item
 *     - `Escape`  close everything
 *
 * Labels are pulled from {@link Locale} so the menu shows the same
 * strings as MapML.js and the Firefox MapML extension in every
 * shipped language. Shortcut hints stay English by policy — they
 * mirror physical keys, not the UI text.
 *
 * Project policy: "Toggle Controls" adds or removes the viewer's
 * `controls` attribute (matching MapML.js's `_toggleControls` in
 * src/mapml/handlers/ContextMenu.js, which flips `mapEl.controls`).
 * The attribute observer in {@link MapmlViewer} then installs or
 * uninstalls every optional control. The attribution control is
 * *sacred* — it lives outside `#installControls` / `#uninstallControls`
 * so authors cannot, even inadvertently, suppress the data-licensing UI.
 */

/**
 * KeyboardEvent `code` values recognised as menu navigation. Used by
 * the document-level handler to route arrow / Tab / Home / End /
 * Enter / Space to the appropriate per-menu handler when focus is
 * outside the menu (e.g. mouse-opened menus where the canvas keeps
 * focus). Matches the codes recognised by `#onMenuKeyDown` /
 * `#onCopySubmenuKeyDown`.
 */
const NAV_KEY_CODES: ReadonlySet<string> = new Set([
  'ArrowUp',
  'ArrowDown',
  'ArrowLeft',
  'ArrowRight',
  'Home',
  'End',
  'Enter',
  'Space',
  'Tab'
]);

export class ContextMenu {
  readonly #viewer: MapmlViewer;
  readonly #locale: Locale;
  readonly #menu: HTMLDivElement;
  readonly #copySubmenu: HTMLDivElement;
  #items: ContextMenuItem[] = [];
  #copyItems: CopySubmenuItem[] = [];
  #copyItemIndex = 0;
  /** True while the copy submenu is showing next to the main menu. */
  #copyOpen = false;
  /** Right-click point (canvas pixels + geographic) captured for Copy Location. */
  #lastClick: CopyLocationPoint | undefined;
  #activeIndex = 0;
  #wasOpenedByKeyboard = false;
  /** True while we've suppressed MapLibre's keyboard handler for an open menu. */
  #suppressedMapKeyboard = false;
  #onHistoryChanged: () => void;
  #onDocumentMouseDown: (e: MouseEvent) => void;
  #onDocumentKeyDown: (e: KeyboardEvent) => void;
  #onFullscreenChange: () => void;
  #mapContextHandler:
    | ((e: {
        point: { x: number; y: number };
        lngLat: { lng: number; lat: number };
      }) => void)
    | undefined;
  /**
   * Long-press (touch) support for the map canvas. MapLibre only fires
   * its own `contextmenu` map event from a native DOM `contextmenu`
   * event, which the browser suppresses on the canvas during touch
   * gestures — so a long-press never reaches the menu the way a
   * mouse right-click does. We detect the long-press ourselves and
   * open the menu at the touch point, mirroring Leaflet's `TapHold`
   * handler (which MapML.js gets for free). See `#bindToCanvas`.
   */
  #canvasContainer: HTMLElement | undefined;
  #onCanvasTouchStart: ((e: TouchEvent) => void) | undefined;
  #onCanvasTouchMove: ((e: TouchEvent) => void) | undefined;
  #onCanvasTouchEnd: ((e: TouchEvent) => void) | undefined;
  #longPressTimer: ReturnType<typeof setTimeout> | undefined;
  #longPressStart: { x: number; y: number } | undefined;
  /** Set when a long-press just opened the menu, so touchend can
   * suppress the browser's compatibility mouse events (which would
   * otherwise immediately close the menu via `#onDocumentMouseDown`). */
  #longPressFired = false;

  constructor(viewer: MapmlViewer, mountInto: ShadowRoot, locale: Locale) {
    this.#viewer = viewer;
    this.#locale = locale;

    this.#menu = document.createElement('div');
    this.#menu.className = 'mapml-contextmenu';
    this.#menu.setAttribute('role', 'menu');
    this.#menu.setAttribute('tabindex', '-1');
    this.#menu.hidden = true;
    mountInto.appendChild(this.#menu);

    // Sibling submenu popup for the Copy > Map / Extent / Location
    // items. Class `.mapml-submenu` matches MapML.js so shared CSS
    // rules keep working; positioning is relative to the viewer host
    // just like the parent menu.
    this.#copySubmenu = document.createElement('div');
    this.#copySubmenu.className = 'mapml-contextmenu mapml-submenu';
    this.#copySubmenu.setAttribute('role', 'menu');
    this.#copySubmenu.setAttribute('tabindex', '-1');
    this.#copySubmenu.hidden = true;
    mountInto.appendChild(this.#copySubmenu);

    this.#buildItems();
    this.#buildCopySubmenu();

    this.#onHistoryChanged = (): void => this.#updateEnabledState();
    this.#onDocumentMouseDown = (e: MouseEvent): void => {
      if (this.#menu.hidden) return;
      const path = e.composedPath();
      if (path.includes(this.#menu) || path.includes(this.#copySubmenu)) return;
      this.close();
    };
    this.#onDocumentKeyDown = (e: KeyboardEvent): void => this.#handleDocumentKeyDown(e);
    this.#onFullscreenChange = (): void => this.#syncFullscreenLabel();

    this.#viewer.addEventListener('mapml:historychanged', this.#onHistoryChanged);
    this.#menu.addEventListener('keydown', this.#onMenuKeyDown);
    this.#copySubmenu.addEventListener('keydown', this.#onCopySubmenuKeyDown);
    document.addEventListener('mousedown', this.#onDocumentMouseDown, true);
    document.addEventListener('keydown', this.#onDocumentKeyDown);
    document.addEventListener('fullscreenchange', this.#onFullscreenChange);

    void this.#bindToCanvas();
    this.#updateEnabledState();
  }

  destroy(): void {
    this.#viewer.removeEventListener('mapml:historychanged', this.#onHistoryChanged);
    this.#menu.removeEventListener('keydown', this.#onMenuKeyDown);
    this.#copySubmenu.removeEventListener('keydown', this.#onCopySubmenuKeyDown);
    document.removeEventListener('mousedown', this.#onDocumentMouseDown, true);
    document.removeEventListener('keydown', this.#onDocumentKeyDown);
    document.removeEventListener('fullscreenchange', this.#onFullscreenChange);

    const map = this.#viewer.renderer.map;
    if (map) {
      if (this.#mapContextHandler) map.off('contextmenu', this.#mapContextHandler);
      if (this.#suppressedMapKeyboard) {
        map.keyboard.enable();
        this.#suppressedMapKeyboard = false;
      }
    }

    if (this.#longPressTimer !== undefined) {
      clearTimeout(this.#longPressTimer);
      this.#longPressTimer = undefined;
    }
    const container = this.#canvasContainer;
    if (container) {
      if (this.#onCanvasTouchStart)
        container.removeEventListener('touchstart', this.#onCanvasTouchStart);
      if (this.#onCanvasTouchMove)
        container.removeEventListener('touchmove', this.#onCanvasTouchMove);
      if (this.#onCanvasTouchEnd) {
        container.removeEventListener('touchend', this.#onCanvasTouchEnd);
        container.removeEventListener('touchcancel', this.#onCanvasTouchEnd);
      }
    }

    this.#menu.remove();
    this.#copySubmenu.remove();
  }

  async #bindToCanvas(): Promise<void> {
    await this.#viewer.whenReady();
    const map = this.#viewer.renderer.map;
    if (!map) return;
    this.#mapContextHandler = (e): void => {
      this.#lastClick = {
        lng: e.lngLat.lng,
        lat: e.lngLat.lat,
        containerPoint: { x: e.point.x, y: e.point.y }
      };
      this.#openAtPoint(e.point.x, e.point.y, false);
    };
    map.on('contextmenu', this.#mapContextHandler);

    // Long-press → context menu on touch devices. A single-finger
    // press held for `LONG_PRESS_MS` without moving beyond
    // `MOVE_TOLERANCE` px opens the menu at the touch point. Movement
    // (a pan) or a second finger (pinch/rotate) cancels it.
    const LONG_PRESS_MS = 600;
    const MOVE_TOLERANCE = 10;
    const container = map.getCanvasContainer();
    this.#canvasContainer = container;

    const cancel = (): void => {
      if (this.#longPressTimer !== undefined) {
        clearTimeout(this.#longPressTimer);
        this.#longPressTimer = undefined;
      }
      this.#longPressStart = undefined;
    };

    this.#onCanvasTouchStart = (e: TouchEvent): void => {
      if (e.touches.length !== 1) {
        cancel();
        return;
      }
      const t = e.touches[0];
      if (!t) return;
      this.#longPressStart = { x: t.clientX, y: t.clientY };
      this.#longPressTimer = setTimeout(() => {
        this.#longPressTimer = undefined;
        const start = this.#longPressStart;
        this.#longPressStart = undefined;
        if (!start) return;
        const rect = container.getBoundingClientRect();
        const px = start.x - rect.left;
        const py = start.y - rect.top;
        const lngLat = map.unproject([px, py]);
        this.#lastClick = {
          lng: lngLat.lng,
          lat: lngLat.lat,
          containerPoint: { x: px, y: py }
        };
        this.#longPressFired = true;
        this.#openAtPoint(px, py, false);
      }, LONG_PRESS_MS);
    };

    this.#onCanvasTouchMove = (e: TouchEvent): void => {
      const start = this.#longPressStart;
      if (!start) return;
      const t = e.touches[0];
      if (!t) {
        cancel();
        return;
      }
      if (
        Math.abs(t.clientX - start.x) > MOVE_TOLERANCE ||
        Math.abs(t.clientY - start.y) > MOVE_TOLERANCE
      ) {
        cancel();
      }
    };

    this.#onCanvasTouchEnd = (e: TouchEvent): void => {
      cancel();
      // Suppress the compatibility mouse events the browser would
      // otherwise synthesise after this touch — they'd fire a
      // document mousedown that closes the just-opened menu.
      if (this.#longPressFired) {
        e.preventDefault();
        this.#longPressFired = false;
      }
    };

    container.addEventListener('touchstart', this.#onCanvasTouchStart, {
      passive: true
    });
    container.addEventListener('touchmove', this.#onCanvasTouchMove, {
      passive: true
    });
    container.addEventListener('touchend', this.#onCanvasTouchEnd);
    container.addEventListener('touchcancel', this.#onCanvasTouchEnd);
  }

  #buildItems(): void {
    const L = this.#locale;
    const make = (def: ItemDef): ContextMenuItem => {
      if (def.kind === 'separator') {
        const sep = document.createElement('div');
        sep.className = 'mapml-contextmenu-separator';
        sep.setAttribute('role', 'separator');
        this.#menu.appendChild(sep);
        return { kind: 'separator', el: sep };
      }
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      // `<span class="mapml-contextmenu-submenu-indicator">` — separate
      // element (not concatenated into the label text) so tests can
      // assert against the label alone with `:has-text` / `toContainText`.
      const indicator = def.submenuIndicator
        ? '<span class="mapml-contextmenu-submenu-indicator" aria-hidden="true">\u25B8</span>'
        : '';
      btn.innerHTML = `<span>${def.label}</span>${indicator}${def.kbd ? `<kbd>${def.kbd}</kbd>` : ''}`;
      if (def.submenuIndicator) {
        btn.setAttribute('aria-haspopup', 'true');
        btn.setAttribute('aria-expanded', 'false');
        btn.setAttribute('aria-controls', 'mapml-copy-submenu');
      }
      btn.addEventListener('click', () => {
        if (btn.disabled) return;
        if (def.openSubmenu) {
          this.#openCopySubmenu(true);
          return;
        }
        def.run();
        this.close();
      });
      // Mouseover on a main-menu item auto-opens or closes the Copy
      // submenu depending on which item is under the cursor, matching
      // MapML.js's `_onItemMouseOver` / `_onItemMouseOut` pair. This is
      // a mouse-only affordance: on touch the synthesized hover fires
      // *before* the tap's click, so opening the submenu here would
      // reposition `copy-map` under the finger and the click would land
      // on it — copying to the clipboard instead of opening the submenu.
      // Touch relies on the click handler above to open the submenu.
      btn.addEventListener('pointerenter', (e) => {
        if (e.pointerType !== 'mouse') return;
        if (btn.disabled) return;
        if (def.openSubmenu) {
          this.#openCopySubmenu(false);
        } else if (this.#copyOpen) {
          this.#hideCopySubmenu();
        }
      });
      this.#menu.appendChild(btn);
      return {
        kind: 'item',
        el: btn,
        id: def.id,
        isEnabled: def.isEnabled ?? ((): boolean => true),
        openSubmenu: def.openSubmenu === true
      };
    };

    // Order and shortcut-hint text taken from MapML.js ContextMenu.js.
    // MapML.js index → our index (mapping shown for clarity):
    //   0 Back, 1 Forward, 2 Reload, 3 Fullscreen, 4 sep,
    //   5 Copy (submenu), 6 Paste, 7 sep, 8 Toggle Controls, 9 Debug,
    //   10 View Source.
    this.#items = [
      make({ kind: 'item', id: 'back', label: L.cmBack, kbd: 'Alt+Left Arrow', run: () => this.#viewer.back(), isEnabled: () => this.#viewer.historyIndex > 0 }),
      make({ kind: 'item', id: 'forward', label: L.cmForward, kbd: 'Alt+Right Arrow', run: () => this.#viewer.forward(), isEnabled: () => this.#viewer.historyIndex + 1 < this.#viewer.historyLength }),
      make({ kind: 'item', id: 'reload', label: L.cmReload, kbd: 'Ctrl+R', run: () => this.#viewer.reload(), isEnabled: () => this.#viewer.historyIndex > 0 }),
      make({ kind: 'item', id: 'fullscreen', label: L.btnFullScreen, kbd: 'F', run: () => this.#toggleFullscreen() }),
      make({ kind: 'separator' }),
      // Copy opens the Map / Extent / Location submenu (built below).
      // `openSubmenu: true` makes click / mouseenter open it instead
      // of closing the menu. The `\u25B8` marker mirrors MapML.js.
      make({
        kind: 'item',
        id: 'copy',
        label: L.cmCopyCoords,
        kbd: 'C',
        submenuIndicator: true,
        openSubmenu: true,
        run: () => {}
      }),
      make({
        kind: 'item',
        id: 'paste',
        label: L.cmPasteLayer,
        kbd: 'P',
        run: () => this.#runPaste()
      }),
      make({ kind: 'separator' }),
      make({ kind: 'item', id: 'toggle-controls', label: L.cmToggleControls, kbd: 'T', run: () => this.#toggleControls() }),
      make({ kind: 'item', id: 'toggle-debug', label: L.cmToggleDebug, kbd: 'D', run: () => this.#viewer.toggleDebug() }),
      make({ kind: 'item', id: 'view-source', label: L.cmViewSource, kbd: 'V', run: () => this.#viewer.viewSource() })
    ];
  }

  /**
   * Build the three-item Copy submenu popup. Item IDs `copy-map`,
   * `copy-extent`, `copy-location` mirror MapML.js's `CPYMENUMAP` /
   * `CPYMENUEXTENT` / `CPYMENULOC` slots (in the same order). Each
   * item reads the active CS from {@link M.options} at click time so
   * pages that mutate `M.options.defaultExtCoor` / `defaultLocCoor`
   * see the effect immediately.
   */
  #buildCopySubmenu(): void {
    const L = this.#locale;
    this.#copySubmenu.id = 'mapml-copy-submenu';
    const defs: readonly {
      id: string;
      label: string;
      run: () => void;
    }[] = [
      {
        id: 'copy-map',
        label: L.cmCopyMapML,
        run: () => void writeToClipboard(copyMapMLDocument(this.#viewer))
      },
      {
        id: 'copy-extent',
        label: L.cmCopyExtent,
        run: () =>
          void writeToClipboard(
            copyExtentMeta(this.#viewer, M.options.defaultExtCoor)
          )
      },
      {
        id: 'copy-location',
        label: L.cmCopyLocation,
        run: () => {
          const pt = this.#lastClick ?? this.#defaultCenterClick();
          if (!pt) return;
          void writeToClipboard(
            copyLocationFeature(this.#viewer, pt, M.options.defaultLocCoor)
          );
        }
      }
    ];
    this.#copyItems = defs.map((def, i) => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'mapml-contextmenu-item';
      btn.setAttribute('role', 'menuitem');
      btn.dataset.id = def.id;
      btn.tabIndex = -1;
      btn.innerHTML = `<span>${def.label}</span>`;
      btn.addEventListener('click', () => {
        def.run();
        this.close();
      });
      btn.addEventListener('mouseenter', () => this.#focusCopyItem(i));
      this.#copySubmenu.appendChild(btn);
      return { el: btn, id: def.id, run: def.run };
    });
  }

  /**
   * Build a synthetic {@link CopyLocationPoint} for the current map
   * center + canvas midpoint. Used when Copy \u2192 Location is
   * activated without a preceding right-click (keyboard open flow),
   * matching MapML.js's fallback to `map.getCenter()` in the same
   * scenario.
   */
  #defaultCenterClick(): CopyLocationPoint | undefined {
    const map = this.#viewer.renderer.map;
    if (!map) return undefined;
    const c = map.getCenter();
    const canvas = map.getCanvas();
    return {
      lng: c.lng,
      lat: c.lat,
      containerPoint: { x: canvas.width / 2, y: canvas.height / 2 }
    };
  }

  #openCopySubmenu(focusFirst: boolean): void {
    if (this.#copyOpen) {
      if (focusFirst) this.#focusCopyItem(0);
      return;
    }
    this.#copyOpen = true;
    this.#copySubmenu.hidden = false;
    const copyItem = this.#items.find(
      (it): it is Extract<ContextMenuItem, { kind: 'item' }> =>
        it.kind === 'item' && it.id === 'copy'
    );
    copyItem?.el.setAttribute('aria-expanded', 'true');

    // Position: to the right of the parent menu when there's room;
    // otherwise flush to the left of the parent menu. Vertical
    // alignment tracks the Copy button's top so the pointer lands on
    // the first submenu item.
    const host = this.#viewer.getBoundingClientRect();
    const parentLeft = this.#menu.offsetLeft;
    const parentWidth = this.#menu.offsetWidth;
    const submenuWidth = this.#copySubmenu.offsetWidth;
    let left: number;
    if (parentLeft + parentWidth + submenuWidth <= host.width) {
      left = parentLeft + parentWidth;
    } else {
      left = Math.max(0, parentLeft - submenuWidth);
    }
    const copyTop = copyItem ? copyItem.el.offsetTop : 0;
    this.#copySubmenu.style.left = `${left}px`;
    this.#copySubmenu.style.top = `${this.#menu.offsetTop + copyTop}px`;

    this.#copyItemIndex = 0;
    if (focusFirst) this.#focusCopyItem(0);
  }

  #hideCopySubmenu(): void {
    if (!this.#copyOpen) return;
    this.#copyOpen = false;
    this.#copySubmenu.hidden = true;
    const copyItem = this.#items.find(
      (it): it is Extract<ContextMenuItem, { kind: 'item' }> =>
        it.kind === 'item' && it.id === 'copy'
    );
    copyItem?.el.setAttribute('aria-expanded', 'false');
  }

  #focusCopyItem(i: number): void {
    if (i < 0 || i >= this.#copyItems.length) return;
    for (let j = 0; j < this.#copyItems.length; j++) {
      this.#copyItems[j]!.el.tabIndex = j === i ? 0 : -1;
    }
    this.#copyItemIndex = i;
    this.#copyItems[i]!.el.focus();
  }

  /**
   * Read the clipboard and hand its text to
   * {@link pasteToViewer} for shape-based dispatch. Runs when the
   * user activates the Paste menu item (click / Enter / P shortcut).
   * The menu closes first so any paste side-effects (e.g. a new
   * layer registering + firing `mapml:layerschanged`) don't race with
   * a still-open menu.
   */
  async #runPaste(): Promise<void> {
    let text = '';
    try {
      text = await navigator.clipboard.readText();
    } catch {
      console.warn('MapML: clipboard read failed; paste is a no-op.');
      return;
    }
    if (!text) return;
    await pasteToViewer(this.#viewer, text, this.#locale);
  }

  #updateEnabledState(): void {
    for (const item of this.#items) {
      if (item.kind !== 'item') continue;
      const enabled = item.isEnabled();
      item.el.disabled = !enabled;
      item.el.setAttribute('aria-disabled', enabled ? 'false' : 'true');
    }
    this.#syncFullscreenLabel();
  }

  /**
   * Swap the fullscreen item's label between “View fullscreen” and
   * “Exit fullscreen” based on the current fullscreen element. We use
   * the same target as the MapLibre `FullscreenControl` (the map
   * container) so the menu, the control, and the browser stay in sync.
   */
  #syncFullscreenLabel(): void {
    const item = this.#items.find((it) => it.kind === 'item' && it.id === 'fullscreen');
    if (!item || item.kind !== 'item') return;
    const inFs = this.#isFullscreen();
    const label = inFs ? this.#locale.btnExitFullScreen : this.#locale.btnFullScreen;
    item.el.innerHTML = `<span>${label}</span><kbd>F</kbd>`;
  }

  #fullscreenTarget(): HTMLElement | undefined {
    // Match the element passed to MapLibre's FullscreenControl in
    // mapml-viewer.ts (the viewer host) so the control and the menu
    // agree on what "fullscreen" means. Fullscreening the host keeps
    // the menu rendered (it's a sibling of the map container inside
    // the shadow root).
    return this.#viewer;
  }

  #isFullscreen(): boolean {
    const target = this.#fullscreenTarget();
    if (!target) return false;
    const fe = document.fullscreenElement;
    if (!fe) return false;
    // Fast path: viewer is in the top-level document.
    if (fe === target) return true;
    // Shadow-root case: when the viewer is inside another custom
    // element's shadow root, calling `viewer.requestFullscreen()`
    // still fullscreens the viewer, but `document.fullscreenElement`
    // on the top-level document exposes the outermost shadow-hosting
    // ancestor instead (per the Fullscreen API — each ShadowRoot has
    // its own `fullscreenElement`, and the top document only sees the
    // outermost host). Walk up from the viewer through
    // `ShadowRoot.host` chains looking for a match against
    // `document.fullscreenElement`. Matches both nested-shadow and
    // deeply-nested scenarios (e.g. viewer inside a light-DOM child
    // of a shadow-hosted wrapper).
    let node: Node = target;
    while (node.getRootNode() instanceof ShadowRoot) {
      const root = node.getRootNode() as ShadowRoot;
      if (root.host === fe) return true;
      node = root.host;
    }
    return false;
  }

  #openAtPoint(x: number, y: number, byKeyboard: boolean): void {
    this.#updateEnabledState();
    this.#wasOpenedByKeyboard = byKeyboard;
    this.#menu.hidden = false;
    // Suppress MapLibre's arrow-key panning while the menu is up so
    // arrow keys reach the menu even on a mouse-opened menu (focus
    // stays on the canvas). Matches MapML.js's `_mapMenuVisible` gate.
    const kb = this.#viewer.renderer.map?.keyboard;
    if (kb && kb.isEnabled()) {
      kb.disable();
      this.#suppressedMapKeyboard = true;
    }
    // Any prior submenu state is stale when the main menu reopens.
    this.#hideCopySubmenu();

    const host = this.#viewer.getBoundingClientRect();
    const menuW = this.#menu.offsetWidth;
    const menuH = this.#menu.offsetHeight;
    const maxX = Math.max(0, host.width - menuW - 2);
    const maxY = Math.max(0, host.height - menuH - 2);
    this.#menu.style.left = `${Math.min(Math.max(0, x), maxX)}px`;
    this.#menu.style.top = `${Math.min(Math.max(0, y), maxY)}px`;

    if (byKeyboard) {
      const first = this.#firstEnabledIndex();
      if (first >= 0) this.#focusItem(first);
      else this.#menu.focus();
    }
  }

  /**
   * True while the map-level context menu (or its Copy submenu) is
   * visible. Consumers (e.g. {@link MapmlViewer.#onCanvasKeyDown})
   * use this to bail out of their own keyboard handling so arrow
   * keys and single-letter shortcuts flow to the menu instead of
   * panning the map or triggering a query. Matches the effect of
   * MapML.js's `_mapMenuVisible` gate on its keydown handler.
   */
  get isOpen(): boolean {
    return !this.#menu.hidden;
  }

  close(): void {
    // Always tear the submenu down first — it lives in the shadow root
    // as a sibling of the main menu, so an orphaned open submenu would
    // otherwise stay visible after the parent hides.
    this.#hideCopySubmenu();
    if (this.#menu.hidden) return;
    this.#menu.hidden = true;
    // Restore MapLibre's keyboard handler suppressed on open.
    if (this.#suppressedMapKeyboard) {
      this.#viewer.renderer.map?.keyboard.enable();
      this.#suppressedMapKeyboard = false;
    }
    if (this.#wasOpenedByKeyboard) {
      this.#viewer.renderer.map?.getCanvas().focus();
    }
    this.#wasOpenedByKeyboard = false;
  }

  // --- Keyboard handlers ---

  /**
   * Document-level fallback so map-wide bindings work even when focus
   * is on the viewer host (or its shadow root) rather than the canvas
   * itself. We only act when the event's composed path includes our
   * viewer, to avoid swallowing keys for other elements on the page —
   * with one exception: when the menu is visible, MapML.js treats
   * every keydown as menu-scoped regardless of where focus is (see
   * `_mapMenuVisible` in `../MapML.js/src/mapml/handlers/ContextMenu.js`),
   * so a mouse-opened menu still responds to arrow keys / single-
   * letter shortcuts while focus stays on the map canvas or body.
   */
  #handleDocumentKeyDown(e: KeyboardEvent): void {
    const path = e.composedPath();
    if (!path.includes(this.#viewer) && this.#menu.hidden) return;

    // Escape closes the menu from anywhere when it's open. Matches
    // MapML.js where Escape on the map keydown handler closes it.
    if (!this.#menu.hidden && e.key === 'Escape') {
      e.preventDefault();
      this.close();
      return;
    }

    // ContextMenu / Shift+F10 toggle the menu — close when already open.
    if (!this.#menu.hidden && (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))) {
      e.preventDefault();
      this.close();
      return;
    }

    // Menu-open single-letter shortcuts. MapML.js gates these on
    // `_mapMenuVisible` (not on focus), so a right-click that opens
    // the menu without moving focus still lets the user press P /
    // C / F / T / L / Z to activate items. If focus is already inside
    // the menu, `#onMenuKeyDown` will have preventDefault'd first;
    // this branch is a fallback for the focus-elsewhere case.
    if (!this.#menu.hidden && !e.defaultPrevented) {
      // Navigation keys are handled by `#onMenuKeyDown` /
      // `#onCopySubmenuKeyDown` when focus is inside the menu, but
      // MapML.js also lets them work on a mouse-opened menu (where
      // focus stays on the map canvas) \u2014 see `_onKeyDown` in
      // `../MapML.js/src/mapml/handlers/ContextMenu.js`, which hooks
      // on `document` and only gates on `_mapMenuVisible`. Route the
      // event to the appropriate handler so both menu- and canvas-
      // focused sessions behave the same. `defaultPrevented` above
      // ensures we don't double-fire when the menu already got it.
      if (NAV_KEY_CODES.has(e.code)) {
        if (!this.#copySubmenu.hidden) {
          this.#onCopySubmenuKeyDown(e);
        } else {
          this.#onMenuKeyDown(e);
        }
        if (e.defaultPrevented) return;
      }
      if (this.#handleMenuLetterShortcut(e)) return;
    }

    if (this.#menu.hidden) {
      this.#handleMapWideShortcut(e);
    }
  }

  /**
   * Menu-open single-letter shortcuts, callable from either the menu's
   * own keydown listener or the document-level fallback. Returns
   * `true` when the event was consumed. Mirrors the `KeyC` / `KeyP` /
   * `KeyF` / `KeyT` cases in MapML.js's `_onKeyDown`.
   */
  #handleMenuLetterShortcut(e: KeyboardEvent): boolean {
    if (this.#menu.hidden) return false;
    // Ignore when a modifier is held (Ctrl+P / Cmd+P etc. belong to
    // the browser, not to us).
    if (e.ctrlKey || e.metaKey || e.altKey) return false;
    switch (e.code) {
      case 'KeyT': {
        e.preventDefault();
        this.#toggleControls();
        this.close();
        return true;
      }
      case 'KeyF': {
        e.preventDefault();
        this.#toggleFullscreen();
        this.close();
        return true;
      }
      case 'KeyD': {
        e.preventDefault();
        this.#viewer.toggleDebug();
        this.close();
        return true;
      }
      case 'KeyC': {
        const copy = this.#items.find(
          (it): it is Extract<ContextMenuItem, { kind: 'item' }> =>
            it.kind === 'item' && it.id === 'copy'
        );
        if (copy && !copy.el.disabled) {
          e.preventDefault();
          this.#focusItem(this.#items.indexOf(copy));
          this.#openCopySubmenu(true);
          return true;
        }
        return false;
      }
      case 'KeyP': {
        const paste = this.#items.find(
          (it): it is Extract<ContextMenuItem, { kind: 'item' }> =>
            it.kind === 'item' && it.id === 'paste'
        );
        if (paste && !paste.el.disabled) {
          e.preventDefault();
          paste.el.click();
          return true;
        }
        return false;
      }
      case 'KeyV': {
        const view = this.#items.find(
          (it): it is Extract<ContextMenuItem, { kind: 'item' }> =>
            it.kind === 'item' && it.id === 'view-source'
        );
        if (view && !view.el.disabled) {
          e.preventDefault();
          view.el.click();
          return true;
        }
        return false;
      }
      default:
        return false;
    }
  }

  /**
   * Map-wide bindings, plus the ContextMenu / Shift+F10 keys that open the
   * menu itself. Mirrors MapML.js's mapml-viewer.js keydown handler
   * (Ctrl+R / Alt+Arrow) plus the menu-open hotkeys.
   */
  #handleMapWideShortcut(e: KeyboardEvent): void {
    if (this.#menu.hidden && (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10'))) {
      // Defer to LayerContextMenu when focus is inside a layer or
      // extent fieldset — that menu will open at the fieldset instead
      // of at map center. Also stand down if a layer / extent menu is
      // already open (focus is on its buttons, not in a fieldset, but
      // stealing the shortcut would open a second menu on top).
      if (this.#isFocusInLayerFieldset() || this.#isLayerContextMenuOpen()) return;
      e.preventDefault();
      const rect = this.#viewer.renderer.map!.getCanvas().getBoundingClientRect();
      const host = this.#viewer.getBoundingClientRect();
      this.#openAtPoint(
        rect.left - host.left + rect.width / 2,
        rect.top - host.top + rect.height / 2,
        true
      );
      return;
    }
    if (e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
      if (e.code === 'ArrowLeft') {
        e.preventDefault();
        this.#viewer.back();
        return;
      }
      if (e.code === 'ArrowRight') {
        e.preventDefault();
        this.#viewer.forward();
        return;
      }
    }
    if ((e.ctrlKey || e.metaKey) && e.code === 'KeyR' && !e.altKey && !e.shiftKey) {
      if (this.#viewer.historyLength > 1) {
        e.preventDefault();
        this.#viewer.reload();
      }
    }
  }

  /**
   * True when focus is currently on an element inside a layer or extent
   * fieldset of the LayerControl. Lives here (rather than being pulled
   * from LayerContextMenu) so ContextMenu stays self-sufficient — the
   * check is a couple of `closest()` calls against the shadow root.
   */
  #isFocusInLayerFieldset(): boolean {
    const shadow = this.#viewer.shadowRoot;
    if (!shadow) return false;
    let active: Element | null = shadow.activeElement;
    if (!active) return false;
    while (active.shadowRoot && active.shadowRoot.activeElement) {
      active = active.shadowRoot.activeElement;
    }
    return !!active.closest(
      'fieldset.mapml-layer-item, fieldset.mapml-layer-extent'
    );
  }

  /**
   * True while either the layer-menu or extent-menu popup owned by
   * `LayerContextMenu` is visible. Same detection strategy as
   * LayerControl uses when deciding whether to auto-collapse.
   */
  #isLayerContextMenuOpen(): boolean {
    const shadow = this.#viewer.shadowRoot;
    if (!shadow) return false;
    const menus = shadow.querySelectorAll<HTMLElement>(
      '.mapml-contextmenu.mapml-layer-menu, .mapml-contextmenu.mapml-extent-menu'
    );
    for (const menu of menus) {
      if (!menu.hidden) return true;
    }
    return false;
  }

  /**
   * Menu-open bindings: single-letter item shortcuts plus navigation.
   * Mirrors `_onKeyDown` in MapML.js's ContextMenu.js — which exits
   * early when the menu isn't visible, so the same keys do nothing when
   * the menu is closed.
   */
  #onMenuKeyDown = (e: KeyboardEvent): void => {
    switch (e.code) {
      case 'Escape':
        e.preventDefault();
        this.close();
        return;
      case 'ArrowDown':
        e.preventDefault();
        this.#moveFocus(1);
        return;
      case 'ArrowUp':
        e.preventDefault();
        this.#moveFocus(-1);
        return;
      case 'ArrowRight': {
        // On the Copy item, ArrowRight enters the submenu (matches
        // WAI-ARIA menubar semantics + MapML.js).
        const active = this.#items[this.#activeIndex];
        if (active && active.kind === 'item' && active.id === 'copy' && !active.el.disabled) {
          e.preventDefault();
          this.#openCopySubmenu(true);
        }
        return;
      }
      case 'Tab':
        // Trap Tab / Shift+Tab inside the menu and cycle like the arrow
        // keys. Matches MapML.js's ContextMenu, which treats Tab as
        // ArrowDown and Shift+Tab as ArrowUp (see `_onKeyDown`).
        e.preventDefault();
        this.#moveFocus(e.shiftKey ? -1 : 1);
        return;
      case 'Home':
        e.preventDefault();
        this.#focusItem(this.#firstEnabledIndex());
        return;
      case 'End':
        e.preventDefault();
        this.#focusItem(this.#lastEnabledIndex());
        return;
      case 'Enter':
      case 'Space': {
        const active = this.#items[this.#activeIndex];
        if (active && active.kind === 'item' && !active.el.disabled) {
          e.preventDefault();
          active.el.click();
        }
        return;
      }
      case 'KeyT':
      case 'KeyF':
      case 'KeyC':
      case 'KeyP':
      case 'KeyV':
        // Delegate to the shared letter-shortcut handler so keyboard
        // (menu-focused) and mouse-opened (focus-elsewhere) flows go
        // through the same branch.
        this.#handleMenuLetterShortcut(e);
        return;
    }
  };

  /**
   * Copy-submenu keyboard handler. Mirrors the parent menu's shape
   * (ArrowUp / Down / Home / End / Enter / Escape) plus ArrowLeft
   * to close the submenu and return focus to the Copy item.
   */
  #onCopySubmenuKeyDown = (e: KeyboardEvent): void => {
    const n = this.#copyItems.length;
    if (n === 0) return;
    switch (e.code) {
      case 'Escape':
        e.preventDefault();
        this.close();
        return;
      case 'ArrowDown':
      case 'Tab': {
        e.preventDefault();
        const delta = e.code === 'Tab' && e.shiftKey ? -1 : 1;
        this.#focusCopyItem((this.#copyItemIndex + delta + n) % n);
        return;
      }
      case 'ArrowUp':
        e.preventDefault();
        this.#focusCopyItem((this.#copyItemIndex - 1 + n) % n);
        return;
      case 'ArrowLeft':
        e.preventDefault();
        this.#hideCopySubmenu();
        // Restore focus to the Copy parent item.
        {
          const idx = this.#items.findIndex(
            (it) => it.kind === 'item' && it.id === 'copy'
          );
          if (idx >= 0) this.#focusItem(idx);
        }
        return;
      case 'Home':
        e.preventDefault();
        this.#focusCopyItem(0);
        return;
      case 'End':
        e.preventDefault();
        this.#focusCopyItem(n - 1);
        return;
      case 'Enter':
      case 'Space':
        e.preventDefault();
        this.#copyItems[this.#copyItemIndex]?.el.click();
        return;
    }
  };

  // --- Navigation helpers ---

  #moveFocus(delta: 1 | -1): void {
    const n = this.#items.length;
    if (n === 0) return;
    let i = this.#activeIndex;
    for (let step = 0; step < n; step++) {
      i = (i + delta + n) % n;
      const it = this.#items[i]!;
      if (it.kind === 'item' && !it.el.disabled) {
        this.#focusItem(i);
        return;
      }
    }
  }

  #firstEnabledIndex(): number {
    for (let i = 0; i < this.#items.length; i++) {
      const it = this.#items[i]!;
      if (it.kind === 'item' && !it.el.disabled) return i;
    }
    return -1;
  }

  #lastEnabledIndex(): number {
    for (let i = this.#items.length - 1; i >= 0; i--) {
      const it = this.#items[i]!;
      if (it.kind === 'item' && !it.el.disabled) return i;
    }
    return -1;
  }

  #focusItem(i: number): void {
    if (i < 0) return;
    for (let j = 0; j < this.#items.length; j++) {
      const it = this.#items[j]!;
      if (it.kind !== 'item') continue;
      it.el.tabIndex = j === i ? 0 : -1;
    }
    this.#activeIndex = i;
    const it = this.#items[i];
    if (it && it.kind === 'item') it.el.focus();
  }

  // --- Actions ---

  /**
   * Flip the viewer's `controls` property, mirroring MapML.js's
   * `_toggleControls` in `src/mapml/handlers/ContextMenu.js`
   * (`if (mapEl.controls) mapEl.controls = false; else mapEl.controls = true;`).
   * The setter on {@link MapmlViewer} reflects to the `controls`
   * attribute, and the viewer's `attributeChangedCallback` handles
   * install/uninstall of the individual controls (zoom, fullscreen,
   * layer control, reload, scale, geolocate). Attribution is sacred
   * and lives outside that path.
   */
  #toggleControls(): void {
    this.#viewer.controls = !this.#viewer.controls;
  }

  #toggleFullscreen(): void {
    if (this.#isFullscreen()) {
      void document.exitFullscreen();
      return;
    }
    const target = this.#fullscreenTarget();
    if (target) void target.requestFullscreen();
  }
}

type ItemDef =
  | { kind: 'separator' }
  | {
      kind: 'item';
      id: string;
      label: string;
      kbd?: string;
      /**
       * If true, the item renders a trailing `\u25B8` glyph indicating
       * that activating it will open a submenu (`aria-haspopup="true"`
       * is also set for AT compatibility). Used by the `copy` item.
       */
      submenuIndicator?: boolean;
      /**
       * If true, clicking / mouseenter opens the Copy submenu instead
       * of running `run()` + closing. `run` is still called by the
       * fallback (keyboard Enter on an unfocused item, defensive).
       */
      openSubmenu?: boolean;
      run: () => void;
      isEnabled?: () => boolean;
    };

type ContextMenuItem =
  | { kind: 'separator'; el: HTMLDivElement }
  | {
      kind: 'item';
      el: HTMLButtonElement;
      id: string;
      isEnabled: () => boolean;
      /** True when this item opens the Copy submenu. */
      openSubmenu: boolean;
    };

interface CopySubmenuItem {
  el: HTMLButtonElement;
  id: string;
  run: () => void;
}
