import * as maplibregl from 'maplibre-gl';

/**
 * Shared plumbing for `<map-tile>` rendering. A contiguous run of
 * `<map-tile>` elements is rendered as a single MapLibre raster
 * source whose tiles are resolved on demand from author-supplied
 * `src` URLs rather than a URL template.
 *
 * MapML.js renders the same content with a Leaflet `GridLayer`
 * subclass (`MapTileLayer`) that keys tiles by `col:row:zoom` and
 * looks up the matching `<map-tile>` in `createTile`. MapLibre has
 * no per-tile DOM hook, so we bridge the gap with a protocol
 * handler: the raster source's tile template is
 * `mapmltile://<id>/{z}/{x}/{y}`, and MapLibre substitutes the
 * numeric `z`/`x`/`y` before invoking the handler. The handler looks
 * up the author `src` registered for that `<id, z/x/y>` and fetches
 * it. A coordinate with no registered `<map-tile>` returns an empty
 * tile (silent drop) — the sparse-grid analog of MapML.js's
 * `GridLayer` simply not creating a tile for a missing cell.
 *
 * The registry is module-scoped rather than instance-scoped because
 * `maplibregl.addProtocol` is a global registration — two
 * `<mapml-viewer>`s on the same page both talk to the same handler,
 * so their per-run entries live in the same table. Keys stay unique
 * because run ids come from a monotonic counter.
 *
 * OSMTILE only (the only projection the port ships): the `<map-tile>`
 * `col`/`row`/`zoom` map directly onto the standard Web-Mercator
 * `x`/`y`/`z` tile grid, so no CRS transform is needed here.
 */

/** Scheme name for the static-tile protocol handler. */
export const MAPML_MAP_TILE_PROTOCOL = 'mapmltile';

/**
 * Per-run tile table: `"z/x/y"` → absolute `src` URL. One entry per
 * live {@link MapLibreMapTileRunHandle}, keyed by the handle's id.
 */
export const mapmlMapTileRegistry = new Map<string, Map<string, string>>();

/** Build the registry sub-key MapLibre's `{z}/{x}/{y}` resolves to. */
export function mapTileKey(z: number, x: number, y: number): string {
  return `${z}/${x}/${y}`;
}

/**
 * A 1×1 fully transparent PNG, returned for coordinates with no
 * authored `<map-tile>`. MapLibre's raster decoder needs a *valid,
 * decodable* image: a zero-length `ArrayBuffer` — or malformed PNG
 * bytes — reject in `createImageBitmap`, which leaves the tile's
 * `texture` undefined and then crashes MapLibre's raster draw on
 * `tile.texture.bind(...)`, freezing the whole render loop until the
 * next repaint. The tile-run raster source is intentionally left
 * unbounded (see {@link MapLibreMapTileRunHandle}), so MapLibre
 * requests every viewport cell at the natural zoom and may ask for
 * fringe cells the server didn't return — those must decode cleanly as
 * transparent instead of erroring.
 *
 * NB: this 1×1 PNG must decode to a fully transparent pixel
 * (RGBA 0,0,0,0). The base64 below is verified — its single pixel is
 * `[0,0,0,0]`. If you ever swap it, re-verify BOTH that it decodes via
 * `createImageBitmap` AND that the pixel is transparent: node has no
 * `createImageBitmap`, so unit tests can't catch a non-transparent (or
 * invalid) swap, but it paints as a solid tile in the browser.
 *
 * Exported so the sibling `mapmlmetatile://` handler
 * ({@link ./mapLibreMapmlTileProtocol}) can return the same blank cell
 * without re-deriving the base64.
 */
export const TRANSPARENT_TILE_PNG = Uint8Array.from(
  atob(
    'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR4nGNgAAIAAAUAAXpeqz8AAAAASUVORK5CYII='
  ),
  (ch) => ch.charCodeAt(0)
);

/**
 * Upper bound on the number of prefetched tile bodies held in
 * {@link prefetchCache} at once. A GeoServer features response
 * typically returns one viewport's worth of tiles (tens, not
 * thousands), so this ceiling is generous; it exists only to keep a
 * pathological run (a huge static mosaic) from pinning unbounded
 * memory. The oldest entry is evicted when the cap is reached.
 */
const MAX_PREFETCH_ENTRIES = 512;

/**
 * In-flight / completed tile bodies, keyed by absolute `src` URL.
 *
 * This is the MapLibre analog of MapML.js's `<map-tile>` cache-warming
 * trick. MapML.js eagerly runs `new Image().src = src` in the tile's
 * `connectedCallback` so that by the time Leaflet inserts the real
 * `<img>` the bytes are already cached. The port never renders an
 * `<img>` — MapLibre pulls tile bytes through the protocol handler's
 * `fetch` — so instead of warming the *browser image cache* we warm
 * the *exact bytes the handler returns*. Storing the resolved
 * `ArrayBuffer` here (rather than leaning on the HTTP cache) makes the
 * speed-up independent of the tile server's cache headers: it works
 * even when the server sends `Cache-Control: no-store`.
 *
 * Entries are consumed (deleted) the first time the handler serves
 * them — a raster tile is uploaded to a GPU texture and its buffer may
 * be transferred/neutered, so there's no value in retaining it.
 *
 * A resolved value of `null` means the warm-up produced no usable
 * image (HTTP error, non-image body, or network failure); the handler
 * treats that as a blank cell (or retries on-demand with credentials).
 */
const prefetchCache = new Map<string, Promise<ArrayBuffer | null>>();

/**
 * Tile `src`s we've already warned about, so a mosaic full of
 * un-renderable cells logs each bad URL once instead of on every
 * MapLibre tile request. Bounded — cleared wholesale when it grows
 * large, which at worst re-warns a long-lived session's stalest URLs.
 */
const warnedTileSrcs = new Set<string>();

/** Log a per-`src` warning at most once. */
function warnOnceForTile(src: string, reason: string): void {
  if (warnedTileSrcs.has(src)) return;
  if (warnedTileSrcs.size >= 256) warnedTileSrcs.clear();
  warnedTileSrcs.add(src);
  console.warn(`<map-tile> ${MAPML_MAP_TILE_PROTOCOL}: ${reason}: ${src}`);
}

/**
 * Sniff the leading bytes for a raster image magic number MapLibre's
 * decoder can consume. GeoServer's `mapmlfeatures` can emit a
 * `<map-tile>` for a cell it can't actually render and then answer the
 * tile URL with an XML `ServiceExceptionReport` — sometimes with an
 * HTTP error, sometimes (misconfigured) with a `200`. Handing those
 * bytes to MapLibre rejects in `createImageBitmap`, leaves the tile's
 * `texture` undefined, and crashes the raster draw on
 * `tile.texture.bind(...)`, freezing the render loop. Gating on the
 * signature keeps non-images out of the pipeline entirely.
 */
function looksLikeImage(buffer: ArrayBuffer): boolean {
  const b = new Uint8Array(buffer);
  if (b.length < 4) return false;
  // PNG: 89 50 4E 47
  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return true;
  // JPEG: FF D8 FF
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return true;
  // GIF: 47 49 46 38  ("GIF8")
  if (b[0] === 0x47 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x38) return true;
  // WebP: "RIFF" .... "WEBP"
  if (
    b.length >= 12 &&
    b[0] === 0x52 && b[1] === 0x49 && b[2] === 0x46 && b[3] === 0x46 &&
    b[8] === 0x57 && b[9] === 0x45 && b[10] === 0x42 && b[11] === 0x50
  ) {
    return true;
  }
  return false;
}

/**
 * Fetch a single tile `src`, returning its bytes only if they are a
 * decodable raster image, else `null`. Never rejects: an aborted
 * request (MapLibre cancels tiles as the view moves), an HTTP error,
 * a network failure, or a non-image body all resolve to `null` so
 * callers can substitute a blank cell rather than crashing or spamming
 * the tile pipeline. Aborts are silent (they're normal); every other
 * miss logs once per `src` (see {@link warnOnceForTile}).
 *
 * Exported so the sibling `mapmlmetatile://` handler
 * ({@link ./mapLibreMapmlTileProtocol}) reuses the same image-sniffing
 * + warn-once fetch path when resolving a `<map-tile src>` nested
 * inside a fetched tile document.
 */
export async function fetchTileImage(
  src: string,
  init: RequestInit
): Promise<ArrayBuffer | null> {
  let response: Response;
  try {
    response = await fetch(src, init);
  } catch (err) {
    if (init.signal?.aborted) return null;
    warnOnceForTile(
      src,
      `fetch failed (${err instanceof Error ? err.message : String(err)})`
    );
    return null;
  }
  if (!response.ok) {
    warnOnceForTile(src, `HTTP ${response.status} ${response.statusText}`);
    return null;
  }
  const data = await response.arrayBuffer();
  if (!looksLikeImage(data)) {
    warnOnceForTile(src, 'response body was not a decodable image');
    return null;
  }
  return data;
}

/**
 * Cap on concurrent {@link decodeTileImage} decodes. MapLibre v6 hands
 * every custom-protocol raster tile to its own internal
 * `createImageBitmap` (`arrayBufferToImageBitmap`) with no ceiling and no
 * retry, so a burst of tiles becomes a synchronized wall of decodes that
 * intermittently chokes headless Chromium ("source image could not be
 * decoded"); the failure escapes unhandled and wedges the tile so the map
 * never reaches `idle`. Decoding here — behind a small semaphore, handing
 * MapLibre a ready `ImageBitmap` — both skips that fragile internal path
 * and keeps the number of in-flight decodes bounded.
 */
const MAX_CONCURRENT_TILE_DECODES = 3;
let activeTileDecodes = 0;
const tileDecodeQueue: Array<() => void> = [];

function acquireTileDecodeSlot(): Promise<void> {
  if (activeTileDecodes < MAX_CONCURRENT_TILE_DECODES) {
    activeTileDecodes++;
    return Promise.resolve();
  }
  return new Promise<void>((resolve) => tileDecodeQueue.push(resolve));
}

function releaseTileDecodeSlot(): void {
  const next = tileDecodeQueue.shift();
  // Hand the slot straight to the next waiter (count unchanged), or free it.
  if (next) next();
  else activeTileDecodes--;
}

/**
 * Decode raster tile bytes into an `ImageBitmap` so MapLibre uploads the
 * tile directly instead of running its own un-retried, unbounded decode.
 * See {@link MAX_CONCURRENT_TILE_DECODES}.
 *
 * `createImageBitmap` is unavailable under Vitest's `node` environment,
 * where we return the raw bytes (MapLibre accepts either an `ImageBitmap`
 * or an `ArrayBuffer`, and the browser-only decode is moot in unit tests).
 */
export async function decodeTileImage(
  bytes: ArrayBuffer
): Promise<ImageBitmap | ArrayBuffer> {
  if (typeof createImageBitmap !== 'function') return bytes;
  await acquireTileDecodeSlot();
  try {
    const image = await decodeWithRetry(
      new Blob([new Uint8Array(bytes)], { type: 'image/png' })
    );
    if (image !== null) return image;
    // Every attempt lost the headless decode race. Never hand MapLibre the
    // raw bytes — its own decode is un-retried and would wedge the tile the
    // same way, so the map would never reach `idle`. A decoded blank cell
    // keeps the pipeline moving (worst case: one transparent tile).
    const blank = await decodeWithRetry(
      new Blob([new Uint8Array(TRANSPARENT_TILE_PNG)], { type: 'image/png' })
    );
    return blank ?? bytes;
  } finally {
    releaseTileDecodeSlot();
  }
}

/**
 * Try `createImageBitmap` back-to-back on the same blob (no scheduler
 * yields — yielding only lets more concurrent decodes pile up). Returns
 * the decoded image, or `null` if every attempt lost the decode race.
 */
async function decodeWithRetry(blob: Blob): Promise<ImageBitmap | null> {
  for (let attempt = 0; attempt <= TILE_DECODE_RETRIES; attempt++) {
    try {
      return await createImageBitmap(blob);
    } catch {
      // Transient headless decode race — retry immediately on the same blob.
    }
  }
  return null;
}

/** Back-to-back {@link decodeWithRetry} attempts before giving up on bytes. */
const TILE_DECODE_RETRIES = 3;

/**
 * A freshly decoded transparent-tile image for a blank cell. Decoded per
 * call (never shared) so MapLibre can safely close the `ImageBitmap` after
 * uploading it to a GPU texture. See {@link decodeTileImage}.
 */
export function decodeBlankTile(): Promise<ImageBitmap | ArrayBuffer> {
  return decodeTileImage(TRANSPARENT_TILE_PNG.slice().buffer);
}

/**
 * Eagerly download a batch of tile `src` URLs so the on-demand
 * protocol handler can resolve them without a fresh network
 * round-trip. Called by the tile-run handle the moment its tiles are
 * registered — well before MapLibre's scheduler gets around to
 * requesting each cell — so the fetches run early and in parallel
 * instead of being gated one-at-a-time by MapLibre's tile queue.
 *
 * The warm-up result is authoritative: the handler consumes whatever
 * it produced (image bytes, or `null` → a blank cell) and does NOT
 * re-fetch. That keeps a mosaic to exactly one request per cell — GeoServer's
 * `mapmlfeatures` can emit `<map-tile>`s for cells it then refuses with
 * an HTTP 400, and a re-fetch would double every such failed request.
 * (MapLibre never sets `credentials` on this custom protocol, so there
 * is no credentialed retry to preserve.)
 */
export function prefetchMapTiles(srcs: Iterable<string>): void {
  for (const src of srcs) {
    if (src === '' || prefetchCache.has(src)) continue;
    if (prefetchCache.size >= MAX_PREFETCH_ENTRIES) {
      // Map preserves insertion order, so the first key is the oldest.
      const oldest = prefetchCache.keys().next().value;
      if (oldest !== undefined) prefetchCache.delete(oldest);
    }
    // Result is authoritative — the handler consumes it (image or a
    // `null` blank cell) without re-fetching. The handler deletes the
    // entry on consume, so a later re-request can re-warm.
    const pending = fetchTileImage(src, {});
    prefetchCache.set(src, pending);
  }
}

/**
 * Whether {@link ensureMapmlMapTileProtocol} has already registered
 * the shared handler with MapLibre. `addProtocol` throws on
 * double-register, so gate on this flag.
 */
let mapmlMapTileProtocolRegistered = false;

/**
 * Register the shared `mapmltile://` protocol handler on first use.
 * Idempotent — subsequent calls short-circuit. The handler parses
 * `mapmltile://<encoded-run-id>/<z>/<x>/<y>` URLs (MapLibre
 * substitutes `{z}`/`{x}`/`{y}` for us before invoking the handler),
 * looks up the author `src` registered for that run + coordinate, and
 * fetches it. Returns the response body as an ArrayBuffer so
 * MapLibre's raster tile decoder can consume it directly.
 */
export function ensureMapmlMapTileProtocol(): void {
  if (mapmlMapTileProtocolRegistered) return;
  mapmlMapTileProtocolRegistered = true;
  maplibregl.addProtocol(MAPML_MAP_TILE_PROTOCOL, async (params, abortController) => {
    const parsed = parseMapTileUrl(params.url);
    if (parsed === null) {
      throw new Error(`Malformed ${MAPML_MAP_TILE_PROTOCOL}:// URL: ${params.url}`);
    }
    const table = mapmlMapTileRegistry.get(parsed.id);
    const src = table?.get(mapTileKey(parsed.z, parsed.x, parsed.y));
    if (src === undefined) {
      // No `<map-tile>` authored at this coordinate (or the run was
      // removed between MapLibre queuing the request and now). Return
      // a transparent tile so the raster source drops the cell
      // silently rather than failing to decode an empty buffer.
      // `slice()` hands MapLibre a fresh, detachable copy (the worker
      // transfer path may neuter the underlying buffer).
      return { data: TRANSPARENT_TILE_PNG.slice().buffer };
    }
    // Fast path: the tile-run handle warmed this `src` at registration
    // time (see `prefetchMapTiles`). The warm-up is authoritative —
    // consume it (image bytes, or `null` → blank cell) without a second
    // request. Consume-delete once: the bytes are uploaded to a GPU
    // texture and the buffer may be neutered, and a later re-request
    // can re-warm.
    const prefetched = prefetchCache.get(src);
    if (prefetched !== undefined) {
      prefetchCache.delete(src);
      const warm = await prefetched;
      // Hand MapLibre a fresh copy; the worker transfer path may detach
      // the underlying buffer, and a shared src (rare) could otherwise
      // be double-consumed.
      return warm !== null
        ? { data: warm.slice(0) }
        : { data: TRANSPARENT_TILE_PNG.slice().buffer };
    }
    // No warm-up for this cell (e.g. MapLibre requested it before the
    // run registered, or after the entry was consumed) — fetch on
    // demand, carrying the abort signal + any credentials.
    const init: RequestInit = { signal: abortController.signal };
    if (params.credentials !== undefined) {
      init.credentials = params.credentials as RequestCredentials;
    }
    const data = await fetchTileImage(src, init);
    if (data === null) {
      // No decodable image for this authored cell (e.g. GeoServer
      // answered with an XML ServiceExceptionReport). Render it blank
      // rather than throwing — a rejected protocol request spams the
      // tile pipeline, and a non-image body would crash the raster
      // draw (see `looksLikeImage`).
      return { data: TRANSPARENT_TILE_PNG.slice().buffer };
    }
    return { data };
  });
}

function parseMapTileUrl(
  url: string
): { id: string; z: number; x: number; y: number } | null {
  const prefix = `${MAPML_MAP_TILE_PROTOCOL}://`;
  if (!url.startsWith(prefix)) return null;
  const rest = url.slice(prefix.length);
  const parts = rest.split('/');
  if (parts.length !== 4) return null;
  const [encId, zStr, xStr, yStr] = parts as [string, string, string, string];
  const z = Number(zStr);
  const x = Number(xStr);
  const y = Number(yStr);
  if (!Number.isFinite(z) || !Number.isFinite(x) || !Number.isFinite(y)) return null;
  return { id: decodeURIComponent(encId), z, x, y };
}
