import {
  formatPcrsExtent,
  osmtilePcrsToGcrs,
  projectionMaxZoom,
  type MapmlExtent,
  type PcrsBounds
} from '../core/crs';
import {
  parseGeometryCS,
  shapesFromGeometry,
  shapesFromGeometryWithSource,
  shapesToGeoJson,
  shapesToPcrsBounds,
  boundarySegmentsFromElement,
  elementHasCoordinateSpans,
  type FeatureCS,
  type FeatureShape
} from '../core/feature';
import {
  featureToGeoJson,
  type Mapml2GeojsonFeature,
  type Mapml2GeojsonOptions
} from '../core/mapml2geojson';
import { parseZoomMeta } from '../core/mapMeta';
import { findAncestorMeta, shadowCrossingClosest, shadowCrossingClosestByTag } from '../core/shadow';
import { MapLayer } from './map-layer';
import type { MapmlViewer } from './mapml-viewer';

/**
 * `<map-feature>` — vector map feature.
 *
 * A container for a feature's accessible name (`<map-featurecaption>`),
 * scalar properties (`<map-properties>`), and its geometry
 * (`<map-geometry>` → `<map-point>` / `<map-linestring>` / `<map-polygon>`).
 *
 * Rendering is aggregated: every `<map-feature>` under the same
 * `<map-layer>` contributes to a single per-layer GeoJSON source in the
 * MapLibre renderer (mirrors MapML.js's `MapFeatureLayer`, which is one
 * Leaflet layer per `<map-layer>`). The owning layer rebuilds and
 * re-uploads the FeatureCollection on any structural change (feature
 * add / remove / attribute / subtree mutation), coalesced onto the
 * next microtask.
 *
 * v1 slice — inline features under `<map-layer>` only. Not yet
 * supported: `<map-feature>` under `<map-link rel="features">` (remote
 * / templated feature docs), the focus-proxy a11y overlay, and the
 * in-popup next/previous feature navigation. `<map-featurecaption>`
 * renders as a hover tooltip; `<map-properties>` renders as a
 * click-popup with a "Zoom to here" link — see
 * {@link MapLibreRenderer} for the popup pipeline. Per-feature `min`
 * / `max` zoom filtering *is* live: each feature's resolved range is
 * baked into its GeoJSON `properties` and gated by a data-driven
 * filter on the renderer's fill/line/circle sub-layers (see
 * `featureZoomFilter` in `../renderer/MapLibreRenderer.ts`),
 * matching MapML.js's per-feature `_checkRender` gate.
 */
export class MapFeature extends HTMLElement {
  static readonly observedAttributes = ['zoom', 'min', 'max'] as const;

  #owningViewer: MapmlViewer | null = null;
  #owningLayer: MapLayer | null = null;
  #connected = false;
  /**
   * Watches this feature's own subtree for changes to `<map-geometry>`,
   * `<map-coordinates>`, and `<map-featurecaption>`. Any change nudges
   * the owning layer to rebuild its aggregated FeatureCollection.
   * MapML.js does the equivalent via a per-feature `MutationObserver`
   * installed in `connectedCallback` (`src/map-feature.js`).
   */
  #observer: MutationObserver | null = null;

  get viewer(): MapmlViewer | null {
    return (
      this.#owningViewer ??
      (shadowCrossingClosestByTag(this, 'mapml-viewer') as MapmlViewer | null)
    );
  }

  get parentLayer(): MapLayer | null {
    // Use a shadow-crossing walker so remote-content features (Slice
    // B: `<map-layer src="…">` grafts them into a shadow root) can
    // still reach the owning layer — `Element.closest()` deliberately
    // does not cross shadow boundaries.
    return (
      this.#owningLayer ??
      shadowCrossingClosest(
        this,
        (el): el is MapLayer => el instanceof MapLayer
      )
    );
  }

  /**
   * Native render zoom. Attribute takes precedence; otherwise falls
   * back to the layer's `<map-meta name="zoom">` `value` field (not
   * yet parsed — MapML.js's `_metaContentToObject` recognises `value=`
   * but our port only reads `min` / `max` today) and finally to the
   * viewer's current zoom, matching MapML.js's static-feature fallback
   * (`this._initialZoom`).
   */
  get zoom(): number {
    const attr = this.getAttribute('zoom');
    if (attr !== null) {
      const n = Number(attr);
      if (Number.isFinite(n)) return n;
    }
    const map = this.viewer?.renderer.map;
    return map ? map.getZoom() : 0;
  }

  set zoom(value: number) {
    const n = Number(value);
    if (Number.isFinite(n)) this.setAttribute('zoom', String(n));
  }

  /**
   * Minimum render zoom. Attribute takes precedence; otherwise falls
   * back to the closest ancestor `<map-meta name="zoom">` (walk crosses
   * shadow-root boundaries so a grafted `<map-head>` `<map-meta>`
   * inside `<map-link rel="features">.shadowRoot` is honoured before
   * the outer `<map-layer>`'s), then to the projection's minimum
   * zoom (`0` for OSMTILE). Matches MapML.js's static-feature `get
   * min()` cascade.
   */
  get min(): number {
    const attr = this.getAttribute('min');
    if (attr !== null) {
      const n = Number(attr);
      if (Number.isFinite(n)) return n;
    }
    const meta = findAncestorMeta(this, 'zoom');
    if (meta !== null) {
      const parsed = parseZoomMeta(meta.getAttribute('content'));
      if (parsed !== null) return parsed.min;
    }
    return 0;
  }

  set min(value: number) {
    const n = Number(value);
    if (Number.isFinite(n)) this.setAttribute('min', String(n));
  }

  /**
   * Maximum render zoom. Attribute takes precedence; otherwise falls
   * back to the closest ancestor `<map-meta name="zoom">` (walk crosses
   * shadow-root boundaries — see {@link min}), then to the projection's
   * maximum zoom (24 for OSMTILE). Matches MapML.js's static-feature
   * `get max()` cascade.
   */
  get max(): number {
    const attr = this.getAttribute('max');
    if (attr !== null) {
      const n = Number(attr);
      if (Number.isFinite(n)) return n;
    }
    const meta = findAncestorMeta(this, 'zoom');
    if (meta !== null) {
      const parsed = parseZoomMeta(meta.getAttribute('content'));
      if (parsed !== null) return parsed.max;
    }
    return projectionMaxZoom(this.viewer?.projection ?? 'OSMTILE');
  }

  set max(value: number) {
    const n = Number(value);
    if (Number.isFinite(n)) this.setAttribute('max', String(n));
  }

  /** The (first) direct-child `<map-geometry>` element, or `null`. */
  get geometryEl(): Element | null {
    return this.querySelector(':scope > map-geometry');
  }

  /** Accessible name from the direct-child `<map-featurecaption>`, trimmed. */
  get featureCaption(): string {
    const el = this.querySelector(':scope > map-featurecaption');
    return el?.textContent?.trim() ?? '';
  }

  /** The (first) direct-child `<map-properties>` element, or `null`. */
  get propertiesEl(): Element | null {
    return this.querySelector(':scope > map-properties');
  }

  /**
   * Author-supplied HTML content of `<map-properties>` (empty when the
   * element is absent). Mirrors MapML.js's
   * `feature.querySelector('map-properties').innerHTML`, which is fed
   * verbatim into the popup's `mapml-popup-content` div. The value is
   * trusted (inline authoring under the page author's control); the
   * renderer inserts it via `insertAdjacentHTML`, which does not
   * execute inline `<script>` per the HTML spec.
   */
  get propertiesHtml(): string {
    const el = this.propertiesEl;
    return el ? el.innerHTML : '';
  }

  /**
   * Resolved coordinate system for this feature's `<map-geometry>`.
   *
   * Priority (matches MapML.js's `_getFallbackCS`):
   *   1. `<map-geometry cs="…">` attribute (only `gcrs` / `pcrs` are
   *      accepted in v1; unknown values fall through).
   *   2. Closest ancestor `<map-meta name="cs">` — walk crosses
   *      shadow-root boundaries so a grafted `<map-head>`
   *      `<map-meta>` inside `<map-link rel="features">.shadowRoot`
   *      (typical for GeoServer's `mapmlfeatures:true` response)
   *      wins over any outer `<map-layer>` default.
   *   3. Ultimate default: `gcrs`.
   */
  get cs(): FeatureCS {
    const geom = this.geometryEl;
    const fromGeom = parseGeometryCS(geom?.getAttribute('cs'));
    if (fromGeom !== null) return fromGeom;
    const meta = findAncestorMeta(this, 'cs');
    if (meta !== null) {
      const parsed = parseGeometryCS(meta.getAttribute('content'));
      if (parsed !== null) return parsed;
    }
    return 'gcrs';
  }

  /** Parsed typed shapes from the `<map-geometry>` subtree. */
  get shapes(): FeatureShape[] {
    const g = this.geometryEl;
    if (g === null) return [];
    return shapesFromGeometry(g);
  }

  /**
   * GeoJSON `Feature`s (in GCRS `[lon, lat]`, ready for MapLibre) that
   * this element contributes to its owning layer's aggregated source.
   * Each `<map-geometry>` child (`<map-polygon>`, `<map-linestring>`,
   * `<map-multipolygon>`, …) becomes one `Feature`; caption + min /
   * max / zoom ride along as `properties` so downstream renderers /
   * event handlers can key off them.
   *
   * Per-shape `class` handling: the `class` attribute is read off the
   * geometry-child element (`<map-polygon class="a">`) because that's
   * where MapML.js authors have historically placed it — MapML.js
   * renders one SVG element per geometry child and Leaflet applies
   * the class there. `<map-feature class="…">` is honoured as a
   * fallback for authors who class the containing element instead.
   *
   * `<map-multipolygon>` / `<map-multilinestring>` are single-shape
   * emitters even though they contain multiple `<map-polygon>` /
   * `<map-coordinates>` children — MapLibre's data-driven `class`
   * paint is per-feature, not per-ring. When the parent multi-*
   * element carries no class of its own, we hoist the first child's
   * class onto the emitted feature. This matches every real-world
   * MapML doc I've seen (Alabama / Alaska / Wisconsin in the
   * choropleth demos all class every `<map-polygon>` inside a
   * `<map-multipolygon>` identically, and the intent is clearly
   * "paint the whole multi-polygon this colour").
   */
  toGeoJsonFeatures(): GeoJSON.Feature[] {
    const geometry = this.querySelector(':scope > map-geometry');
    if (geometry === null) return [];
    const shapesWithSource = shapesFromGeometryWithSource(geometry);
    if (shapesWithSource.length === 0) return [];
    const projection = this.viewer?.projection ?? 'OSMTILE';
    // Shared properties across every emitted shape from this feature.
    // Per-shape `class` is added below; everything else (caption,
    // min/max/zoom, centroid, propertiesHtml) is feature-scoped.
    const sharedProperties: Record<string, unknown> = {
      // The MapML.js FeatureLayer decorates each rendered feature with
      // its native zoom + range for downstream tooling; expose the
      // same on the GeoJSON so consumers can filter without re-reading
      // the DOM.
      min: this.min,
      max: this.max,
      zoom: this.zoom
    };
    const caption = this.featureCaption;
    if (caption !== '') sharedProperties.caption = caption;
    // `<map-properties>` HTML rides along as `propertiesHtml`; the
    // renderer inserts it into a click-popup when the user clicks the
    // feature (matches MapML.js's `options.properties` path in
    // `MapFeatureLayer.createGeometry`). Feature-popup content is only
    // built when this key is present + non-empty.
    const propertiesHtml = this.propertiesHtml.trim();
    if (propertiesHtml !== '') sharedProperties.propertiesHtml = propertiesHtml;
    // Bake the feature's centroid (in GCRS) so the click-popup's
    // "Zoom to here" link can pan without re-reading the DOM.
    const shapes = shapesWithSource.map((s) => s.shape);
    const pcrs = shapesToPcrsBounds(shapes, this.cs, projection);
    if (pcrs !== null) {
      const cx = (pcrs.min[0] + pcrs.max[0]) / 2;
      const cy = (pcrs.min[1] + pcrs.max[1]) / 2;
      // OSMTILE / GLOBE both use Web Mercator PCRS; other projections
      // will land their own PCRS→GCRS transform here alongside the
      // rest of the CRS wiring.
      const [lng, lat] = osmtilePcrsToGcrs(cx, cy);
      sharedProperties.centerLng = lng;
      sharedProperties.centerLat = lat;
    }
    // Feature-level fallback class: honoured only when the geometry-
    // child element carries no class of its own.
    const featureClassTokens = readClassTokens(this);
    const out: GeoJSON.Feature[] = [];
    for (const { shape, source, linkWrapper } of shapesWithSource) {
      const perShape: Record<string, unknown> = { ...sharedProperties };
      const tokens =
        readClassTokens(source) ??
        readClassTokens(firstClassBearingChild(source)) ??
        featureClassTokens;
      if (tokens !== null) {
        perShape.className = tokens.join(' ');
        perShape.classNames = tokens;
      }
      // `<map-a>` wrapper (innermost) around this shape → bake the
      // link's `href` / `target` / `type` / `inplace` into the
      // emitted feature's properties so the renderer's click handler
      // and the FeatureFocusIndex's Enter/Space handler can dispatch
      // via `handleFeatureLink` without re-crawling the DOM.
      if (linkWrapper !== null) {
        const href = linkWrapper.getAttribute('href');
        if (href !== null && href !== '') {
          perShape.linkHref = href;
          const target = linkWrapper.getAttribute('target');
          if (target !== null && target !== '') perShape.linkTarget = target;
          const type = linkWrapper.getAttribute('type');
          if (type !== null && type !== '') perShape.linkType = type;
          if (linkWrapper.hasAttribute('inplace')) perShape.linkInplace = true;
        }
      }
      // Emit exactly one Feature via `shapesToGeoJson` on a single-
      // element shape list so the projection + CS conversion stays
      // in one place.
      //
      // `<map-span>`-annotated boundaries (GeoServer's tile-clip
      // edges) can't be per-segment-styled on a single MapLibre
      // geometry, so when the source carries coordinate spans we split
      // the boundary into one `LineString` per span / non-span run and
      // emit those for the stroke. Polygons still emit their ring for
      // the fill, flagged `boundaryEmitted` so the renderer's line
      // sub-layer skips the whole-ring outline (the tile edges would
      // otherwise show through).
      const isBoundaryShape =
        shape.kind === 'Polygon' ||
        shape.kind === 'MultiPolygon' ||
        shape.kind === 'LineString' ||
        shape.kind === 'MultiLineString';
      if (isBoundaryShape && elementHasCoordinateSpans(source)) {
        const isPolygon = shape.kind === 'Polygon' || shape.kind === 'MultiPolygon';
        if (isPolygon) {
          const fillProps = { ...perShape, boundaryEmitted: true };
          out.push(...shapesToGeoJson([shape], this.cs, projection, fillProps));
        }
        for (const seg of boundarySegmentsFromElement(source, this.cs, projection)) {
          const segProps: Record<string, unknown> = { ...perShape };
          if (seg.className !== null) {
            const segTokens = seg.className.trim().split(/\s+/).filter((t) => t !== '');
            // A span with an empty class inherits the geometry's class.
            if (segTokens.length > 0) {
              segProps.className = segTokens.join(' ');
              segProps.classNames = segTokens;
            }
          }
          out.push({
            type: 'Feature',
            geometry: { type: 'LineString', coordinates: seg.coordinates },
            properties: segProps
          });
        }
        continue;
      }
      out.push(...shapesToGeoJson([shape], this.cs, projection, perShape));
    }
    return out;
  }

  /**
   * PCRS bounding box that covers every coordinate in this feature.
   * Used by the owning `<map-layer>` to union feature-derived bounds
   * into its own `.extent` — matching MapML.js's
   * `MapFeatureLayer._computeLayerBounds()` behaviour.
   */
  get pcrsBounds(): PcrsBounds | null {
    const shapes = this.shapes;
    if (shapes.length === 0) return null;
    const projection = this.viewer?.projection ?? 'OSMTILE';
    return shapesToPcrsBounds(shapes, this.cs, projection);
  }

  /**
   * The multi-CRS extent envelope for this feature (matches MapML.js's
   * `<map-feature>.extent`). Zoom range uses this feature's own
   * `min`/`max` fallback chain.
   */
  get extent(): MapmlExtent | null {
    if (!this.isConnected) return null;
    const pcrs = this.pcrsBounds;
    if (pcrs === null) return null;
    const projection = this.viewer?.projection ?? 'OSMTILE';
    return formatPcrsExtent(pcrs, projection, {
      minZoom: this.min,
      maxZoom: this.max
    });
  }

  /**
   * MapML.js JS-API parity: return the ancestor `<mapml-viewer>` /
   * `<map-layer>` for this feature. Thin aliases for the
   * shadow-crossing {@link viewer} / {@link parentLayer} getters,
   * kept for source compatibility with MapML.js callers
   * (`feature.getMapEl()` / `feature.getLayerEl()`). Shadow-crossing
   * so a feature grafted inside a `<map-layer src="…">` remote-content
   * shadow root — or a viewer inside another custom element's shadow
   * root — still resolves the enclosing viewer / layer.
   */
  getMapEl(): MapmlViewer | null {
    return this.viewer;
  }
  getLayerEl(): MapLayer | null {
    return this.parentLayer;
  }

  /**
   * Pan + zoom the viewer to this feature.
   *
   * Reads the feature's own extent envelope, fits the map to its
   * `topLeft.gcrs` / `bottomRight.gcrs` corners, and clamps into the
   * feature's `[min, max]` zoom window (matches MapML.js's
   * `<map-feature>.zoomTo` behaviour via `getZoomToZoom`). No-op if
   * the feature has no geometry or the map isn't ready.
   *
   * Point features degenerate to a `jumpTo` at the feature's centroid
   * + declared native `zoom`, so `fitBounds` doesn't collapse to zoom
   * 0 for a zero-area extent.
   */
  zoomTo(): void {
    const map = this.viewer?.renderer.map;
    if (!map) return;
    const ext = this.extent;
    if (ext === null) return;
    const west = ext.topLeft.gcrs.horizontal;
    const north = ext.topLeft.gcrs.vertical;
    const east = ext.bottomRight.gcrs.horizontal;
    const south = ext.bottomRight.gcrs.vertical;
    if (west === east && north === south) {
      // Point (or any zero-area geometry) — jumpTo lands us at a
      // useful zoom rather than fitBounds collapsing to level 0.
      map.jumpTo({ center: [west, north], zoom: this.zoom });
      return;
    }
    map.fitBounds(
      [
        [west, south],
        [east, north]
      ],
      { animate: false, padding: 0, maxZoom: this.max }
    );
    if (map.getZoom() < this.min) {
      map.setZoom(this.min);
    }
  }

  /**
   * Serialise this `<map-feature>` as a GeoJSON `Feature`. Mirrors
   * MapML.js's `<map-feature>.mapml2geojson(options)`. Uses the same
   * property-extraction + coordinate-transform semantics as
   * {@link mapml2geojson} on `<map-layer>`.
   */
  mapml2geojson(options: Mapml2GeojsonOptions = {}): Mapml2GeojsonFeature {
    const projection = options.projection ?? this.viewer?.projection ?? 'OSMTILE';
    return featureToGeoJson(this, options, null, projection);
  }

  connectedCallback(): void {
    // `data-moving` on an ancestor `<map-layer>` signals a
    // drag-to-reorder DOM shuffle; skip register churn so the layer's
    // aggregated source doesn't re-upload for a no-op reparent.
    // Mirrors the equivalent guard in `<map-link>` /
    // `<map-extent>`.
    if (this.closest('[data-moving]')) return;
    // Shadow-crossing lookups: remote-hosted features (Slice B) sit
    // inside `<map-layer>`'s shadow root, so `Element.closest` alone
    // would stop at the shadow boundary and return null.
    this.#owningViewer = shadowCrossingClosestByTag(
      this,
      'mapml-viewer'
    ) as MapmlViewer | null;
    this.#owningLayer = shadowCrossingClosestByTag(
      this,
      'map-layer'
    ) as MapLayer | null;
    this.#connected = true;
    this.#owningLayer?.registerFeature(this);
    if (!this.#observer) {
      this.#observer = new MutationObserver(() => {
        this.#owningLayer?.notifyFeaturesChanged();
      });
      this.#observer.observe(this, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true
      });
    }
  }

  disconnectedCallback(): void {
    if (this.closest('[data-moving]')) return;
    this.#connected = false;
    this.#observer?.disconnect();
    this.#observer = null;
    const layer = this.#owningLayer;
    this.#owningLayer = null;
    this.#owningViewer = null;
    layer?.unregisterFeature(this);
  }

  attributeChangedCallback(): void {
    if (!this.#connected) return;
    // `zoom` / `min` / `max` change the properties baked into the
    // aggregated GeoJSON. Rebuild via the layer's coalescer so
    // batched attribute writes fold into a single source update.
    this.#owningLayer?.notifyFeaturesChanged();
  }
}

/**
 * Whitespace-split `class` attribute of `el` (or `null` when the
 * element is nullish, missing the attribute, or has only whitespace
 * tokens). Kept as a module-local helper so
 * {@link MapFeature.toGeoJsonFeatures} can read classes off multiple
 * DOM anchors uniformly (the geometry-child element, its first class-
 * bearing descendant, and the `<map-feature>` itself).
 */
function readClassTokens(el: Element | null): string[] | null {
  if (el === null) return null;
  const raw = el.getAttribute('class');
  if (raw === null) return null;
  const tokens = raw.trim().split(/\s+/).filter((t) => t !== '');
  return tokens.length > 0 ? tokens : null;
}

/**
 * Return the first direct-child element of `parent` that carries a
 * non-empty `class` attribute. Used as a fallback for `<map-multi*>`
 * elements whose class is authored on their child `<map-polygon>` /
 * `<map-linestring>` / `<map-point>` rather than on the multi-*
 * wrapper. Returns `null` when nothing matches.
 */
function firstClassBearingChild(parent: Element): Element | null {
  for (const child of Array.from(parent.children)) {
    if (readClassTokens(child) !== null) return child;
  }
  return null;
}
