import type { MapInputDef } from '../core/template';
import { MapExtent } from './map-extent';

/**
 * `<map-select>` \u2014 declarative dropdown that binds a template variable
 * to a user-chosen value. Sibling of `<map-input>` inside `<map-extent>`.
 *
 * Renders as a `<details><summary>label</summary><select>\u2026</select></details>`
 * block inside the enclosing extent's layer-control fieldset. When the
 * user picks a different option, every child `<map-link>` of the
 * enclosing extent tears down and re-applies with the new value baked
 * into its template.
 *
 * Mirrors MapML.js's `HTMLSelectElement` (`../MapML.js/src/map-select.js`),
 * which likewise transcribes `<map-option>` children into a live
 * `<select>` element and hooks its `change` handler to redraw the
 * extent's rendered layers. In upstream this is done via
 * `_extentLayer.redraw()`; here the equivalent is
 * {@link MapExtent.refreshLinks}, which uniformly tears down + re-
 * applies every child `<map-link>` (tile / image / features / query).
 *
 * Template-engine integration: {@link toDefinition} synthesises a
 * `MapInputDef` with `type: "hidden"` and `value: currentValue`, so
 * the existing `imageValueFor` fallback picks the current select
 * value up without special-casing.
 */
export class MapSelect extends HTMLElement {
  static readonly observedAttributes = ['name', 'id'] as const;

  /**
   * The transcribed `<select>` element that appears in the layer
   * control. Owned by this custom element (created lazily in
   * {@link getLayerControlDetails}); MapML.js's parity trick is
   * to keep the same reference alive across layer-control rebuilds
   * so the current selection persists.
   */
  #htmlselect: HTMLSelectElement | null = null;

  /**
   * The cached `<details>` container built for the layer control.
   * See {@link getLayerControlDetails} \u2014 kept as a single instance
   * so successive `getLayerControlDetails()` calls hand back the
   * same node the parent fieldset can just re-attach.
   */
  #details: HTMLDetailsElement | null = null;

  get name(): string {
    return this.getAttribute('name') ?? '';
  }
  set name(value: string) {
    this.setAttribute('name', value);
  }

  /**
   * Current selection. Returns the transcribed `<select>`'s live
   * value once the layer control has requested it via
   * {@link getLayerControlDetails}; otherwise falls back to the
   * default-selected `<map-option>` (or the first option if none
   * declared `selected`).
   */
  get value(): string {
    if (this.#htmlselect !== null) return this.#htmlselect.value;
    return this.#defaultValue();
  }

  /**
   * Programmatic selection. Updates the transcribed `<select>` when
   * one exists (which fires its `change` handler and cascades to the
   * enclosing extent's `refreshLinks`); otherwise this is a no-op
   * because no layer control has been asked for yet, meaning
   * nothing downstream is listening.
   */
  set value(v: string) {
    if (this.#htmlselect !== null) {
      this.#htmlselect.value = v;
      // `HTMLSelectElement.value` setter doesn't fire a native
      // `change` event, so synthesize one to keep the change
      // cascade uniform with the user-driven path.
      this.#htmlselect.dispatchEvent(new Event('change', { bubbles: true }));
    }
  }

  /**
   * Snapshot as a {@link MapInputDef} for the template engine. Every
   * `<map-select>` appears as a `type: "hidden"` input whose `value`
   * is the current selection; token substitution then flows through
   * the same `imageValueFor` fallback that literal `type="hidden"`
   * inputs use.
   */
  toDefinition(): MapInputDef {
    return {
      name: this.name,
      type: 'hidden',
      value: this.value
    };
  }

  /**
   * Build (or return the cached) `<details><summary><label></label></summary>
   * <select>\u2026</select></details>` block for the enclosing extent's
   * layer-control fieldset. Mirrors MapML.js's
   * `_createLayerControlForSelect`.
   *
   * The change handler synthesises the redraw cascade via
   * {@link MapExtent.refreshLinks}, which uniformly tears down + re-
   * applies every child `<map-link>` \u2014 the current select value
   * flows back through `toDefinition` on each re-apply.
   */
  getLayerControlDetails(): HTMLDetailsElement {
    if (this.#details !== null) return this.#details;

    this.#htmlselect = this.#transcribe();
    this.#htmlselect.addEventListener('change', () => {
      // Walk up to the enclosing `<map-extent>` and trigger the
      // teardown + re-apply cascade. `closest('map-extent')` is
      // sufficient here because `<map-select>` is defined only as
      // a direct child of `<map-extent>` in the MapML spec, so a
      // remote-content `<map-select>` (grafted into a `<map-layer
      // src>` shadow root) still lands next to a `<map-extent>`
      // sibling.
      const extent = this.closest('map-extent');
      if (extent instanceof MapExtent) {
        extent.refreshLinks();
      }
    });

    const details = document.createElement('details');
    details.className = 'mapml-layer-item-details mapml-control-layers';

    const summary = document.createElement('summary');
    const label = document.createElement('label');
    label.textContent = this.name;
    const idAttr = this.getAttribute('id');
    if (idAttr !== null) label.setAttribute('for', idAttr);
    summary.appendChild(label);
    details.appendChild(summary);

    details.appendChild(this.#htmlselect);
    this.#details = details;
    return details;
  }

  /**
   * Clone this element's `<map-option>` children into a live HTML
   * `<select>` element. All attributes on the source `<map-select>`
   * are copied to the `<select>`; each `<map-option>`'s attributes
   * + textContent are copied to a matching `<option>`. Mirrors
   * MapML.js's `transcribe()` verbatim.
   */
  #transcribe(): HTMLSelectElement {
    const select = document.createElement('select');
    for (const attr of this.getAttributeNames()) {
      select.setAttribute(attr, this.getAttribute(attr) ?? '');
    }
    for (const child of this.children) {
      if (child.tagName.toLowerCase() !== 'map-option') continue;
      const option = document.createElement('option');
      for (const attr of child.getAttributeNames()) {
        option.setAttribute(attr, child.getAttribute(attr) ?? '');
      }
      option.textContent = child.textContent ?? '';
      select.appendChild(option);
    }
    return select;
  }

  /**
   * Pre-transcription default value: the `<map-option>` marked
   * `selected` (or the first one) provides the initial substitution
   * for the template engine before any layer control renders.
   */
  #defaultValue(): string {
    let firstValue = '';
    let firstSeen = false;
    for (const child of this.children) {
      if (child.tagName.toLowerCase() !== 'map-option') continue;
      const v = child.getAttribute('value') ?? child.textContent?.trim() ?? '';
      if (child.hasAttribute('selected')) return v;
      if (!firstSeen) {
        firstValue = v;
        firstSeen = true;
      }
    }
    return firstValue;
  }
}
