import { osmtilePcrsToGcrs } from './crs';
import {
  parseGeometryCS,
  shapesFromGeometry,
  shapesToGeoJson,
  shapesToPcrsBounds
} from './feature';
import { geojson2mapml, type GeoJsonFeature, type GeoJsonInput } from './geojson2mapml';
import type { Locale } from '../i18n/locale';
import type { MapmlProjection } from './projection';

/**
 * A single feature-shaped popup entry produced by parsing a
 * `<map-link rel="query">` server response. The shape matches what
 * `MapLibreRenderer.#buildFeatureContentDom` expects on its
 * `properties` bag \u2014 same slots the `<map-feature>` click-popup
 * pipeline consumes, so query responses reuse the identical popup
 * DOM + keyboard behaviour.
 *
 * `centerLng` / `centerLat` / `zoom` drive the popup's "Zoom to here"
 * link. Populated when we can extract a centroid from the returned
 * feature's `<map-geometry>` (works for MapML responses, GeoJSON
 * responses via `geojson2mapml`, and any WMS response whose null
 * geometries got replaced by a Point at the click location). Absent
 * for HTML / plain-text responses \u2014 the popup builder skips the
 * zoom-link when any of the three is missing.
 */
export interface QueryFeatureProperties {
  /**
   * Open-ended index signature. Query feature properties are
   * server-supplied bags; the fields declared below are the ones
   * this codebase canonicalizes and consumes explicitly, but the
   * shape is otherwise arbitrary. The signature is also what
   * lets a `QueryFeatureProperties[]` flow into the renderer's
   * `openContentPopup({ features: ReadonlyArray<Record<string,
   * unknown>> })` parameter without a cast.
   */
  [key: string]: unknown;
  /**
   * Rendered as the popup's `<h3>` heading. Empty string falls
   * through to the localized `dfFeatureCaption` label.
   */
  caption: string;
  /**
   * HTML inserted verbatim into the popup body. For query responses
   * this is always a sandboxed `<iframe srcdoc>` wrapping the
   * server-supplied body (MapML.js parity \u2014 the iframe is the
   * origin isolation boundary between the host page and untrusted
   * server responses).
   */
  propertiesHtml: string;
  /**
   * GCRS longitude of the feature's centroid, derived from the
   * returned `<map-geometry>`'s bbox (Point features use the point
   * itself). Populated when the feature carries geometry. When
   * present alongside {@link centerLat} + {@link zoom}, the popup
   * renders the localised "Zoom to here" link that jumps the map to
   * that point.
   */
  centerLng?: number;
  /** GCRS latitude of the feature's centroid. See {@link centerLng}. */
  centerLat?: number;
  /**
   * Target zoom for the "Zoom to here" jump. Reads
   * `<map-feature zoom="N">` when the response declares one
   * (matches MapML.js's `getZoomToZoom` priority); otherwise falls
   * back to the map's current zoom \u2014 conservative default that
   * recenters without changing zoom level.
   */
  zoom?: number;
  /**
   * GCRS (WGS84 lon/lat) GeoJSON geometries for this feature, used to
   * paint a transient highlight overlay on the map while the query
   * popup is open. One entry per shape in the returned
   * `<map-geometry>` (a multi-shape geometry yields several). Present
   * for MapML and GeoJSON query responses that carry geometry
   * (including WMS GetFeatureInfo rows whose null geometry was
   * replaced by a Point at the click); absent for HTML / plain-text
   * responses. Matches MapML.js's `QueryHandler._query`, which adds
   * the returned features to the map as a highlighted feature layer
   * for the lifetime of the popup.
   */
  highlightGeometries?: GeoJSON.Geometry[];
}

/**
 * Parse a `<map-link rel="query">` server response into an array of
 * feature-shaped popup entries. The renderer opens a single popup
 * that cycles through this array via the `|< < N/total > >|` nav
 * bar; single-entry arrays render as `1/1` with prev/next disabled
 * (matches the static feature-click popup shape).
 *
 * Content-Type sniff:
 *
 *   - `text/mapml`, `application/vnd.mapml-mime-type`,
 *     `application/mapml+xml` \u2192 parse XML, extract every
 *     `<map-feature>` in the document. Malformed XML falls through
 *     to the plain-text path.
 *   - `application/json`, `application/geo+json`,
 *     `application/geojson` \u2192 JSON.parse, run
 *     {@link geojson2mapml} to synthesise a `<map-layer>`, extract
 *     its `<map-feature>` children. Null-geometry features get a
 *     Point at the click location before conversion (matches
 *     MapML.js's `_query` fallback). Malformed JSON falls through
 *     to the plain-text path.
 *   - `text/html`, `application/xhtml+xml` \u2192 single feature with
 *     the whole body as an iframe.
 *   - `text/plain` (and anything unrecognised) \u2192 single feature
 *     with the body wrapped in `<pre>`, HTML-escaped.
 *
 * Empty responses (whole-body empty *or* a well-formed but empty
 * envelope like `{"type":"FeatureCollection","features":[]}` or
 * `<mapml-></mapml->`) yield a zero-length array \u2014 the caller
 * suppresses the popup entirely (matches MapML.js's
 * `if (layer._mapmlFeatures.length > 0) displayFeaturesPopup(\u2026)`).
 * *Un*recognisable JSON / XML falls through to the plain-text
 * branch so the author still sees the body for debugging.
 */
export function parseQueryResponse(
  contentType: string,
  body: string,
  clickLng: number,
  clickLat: number,
  projection: MapmlProjection,
  locale: Locale,
  currentZoom: number
): QueryFeatureProperties[] {
  const ct = (contentType.split(';')[0] ?? '').trim().toLowerCase();
  const trimmed = body.trim();
  if (trimmed === '') return [];

  if (isMapmlContentType(ct)) {
    const features = parseMapmlFeatures(
      body,
      projection,
      currentZoom,
      clickLng,
      clickLat
    );
    if (features !== null) return features;
    // Malformed XML: fall through to plain-text.
    return [singleTextFeature(body, clickLng, clickLat, currentZoom)];
  }

  if (isJsonContentType(ct)) {
    const features = parseGeoJsonFeatures(
      body,
      clickLng,
      clickLat,
      projection,
      locale,
      currentZoom
    );
    if (features !== null) return features;
    // Malformed JSON: fall through to plain-text.
    return [singleTextFeature(body, clickLng, clickLat, currentZoom)];
  }

  if (isHtmlContentType(ct)) {
    return [singleHtmlFeature(body, clickLng, clickLat, currentZoom)];
  }

  return [singleTextFeature(body, clickLng, clickLat, currentZoom)];
}

function isMapmlContentType(ct: string): boolean {
  return (
    ct === 'text/mapml' ||
    ct === 'application/vnd.mapml-mime-type' ||
    ct === 'application/mapml+xml'
  );
}

function isJsonContentType(ct: string): boolean {
  return (
    ct === 'application/json' ||
    ct === 'application/geo+json' ||
    ct === 'application/geojson'
  );
}

function isHtmlContentType(ct: string): boolean {
  return ct === 'text/html' || ct === 'application/xhtml+xml';
}

/**
 * Parse a MapML XML document body into query feature entries.
 *
 * Return values distinguish three cases (same shape as
 * {@link parseGeoJsonFeatures}):
 *
 *   - **Recognisable MapML, non-empty** \u2192
 *     `QueryFeatureProperties[]` with one entry per `<map-feature>`.
 *   - **Recognisable MapML, empty** (a `<mapml->` or `<map-body>`
 *     root with zero `<map-feature>` children) \u2192 empty array.
 *     The outer caller suppresses the popup entirely, matching
 *     MapML.js's silent no-op for zero-hit responses. Common shape
 *     for a MapML query server that returns an empty envelope when
 *     no features intersect the click.
 *   - **Not recognisable as MapML** (malformed XML, `<parsererror>`,
 *     or a root that isn't `<mapml->` / `<map-body>`) \u2192 `null`.
 *     The outer caller falls through to a plain-text popup so the
 *     author still sees the body for debugging.
 */
function parseMapmlFeatures(
  body: string,
  projection: MapmlProjection,
  currentZoom: number,
  clickLng: number,
  clickLat: number
): QueryFeatureProperties[] | null {
  let doc: Document;
  try {
    doc = new DOMParser().parseFromString(body, 'application/xml');
  } catch {
    return null;
  }
  if (doc.querySelector('parsererror')) return null;
  // A recognisable MapML document has either the `<mapml->` root
  // (client-side MapML documents; see the MapML content spec) or a
  // bare `<map-body>` element (server-side response fragments).
  // Anything else with an XML shell but no MapML root is treated as
  // arbitrary XML and falls through.
  const hasMapmlRoot = doc.querySelector('mapml-, map-body') !== null;
  if (!hasMapmlRoot) return null;
  // Document-level default CS. MapML.js's `QueryHandler._query`
  // hoists `<map-meta name="cs">` off the response and attaches it
  // to each returned `<map-feature>` so its geometry inherits the
  // declared CS. GeoServer's `info_format=text/mapml` output ships
  // coordinates as PCRS meters and stamps `<map-meta name="cs"
  // content="pcrs">` at the `<map-body>` level rather than on each
  // `<map-geometry>` \u2014 without this fallback we default to `gcrs`
  // and produce garbage centroids (meters treated as degrees). Ports
  // MapML.js's `_getFallbackCS` behaviour for the query pipeline.
  const csMeta = doc.querySelector('map-meta[name="cs"]');
  const defaultCs =
    parseGeometryCS(csMeta?.getAttribute('content') ?? null) ?? 'gcrs';
  const featureEls = Array.from(doc.querySelectorAll('map-feature'));
  // Recognised MapML but empty envelope \u2192 empty array
  // (suppresses the popup, MapML.js parity).
  return featureEls.map((el) =>
    mapFeatureElementToQueryProperties(
      el,
      projection,
      currentZoom,
      defaultCs,
      clickLng,
      clickLat
    )
  );
}

/**
 * Convert a parsed `<map-feature>` element (from an XML document
 * or from a `geojson2mapml`-synthesized `<map-layer>`) into the
 * popup-property bag. Reads `<map-featurecaption>` for the heading,
 * `<map-properties>` for the iframe body, and (when present) walks
 * `<map-geometry>` via {@link shapesFromGeometry} +
 * {@link shapesToPcrsBounds} to derive a centroid \u2014 GCRS
 * lon/lat baked into `centerLng` / `centerLat` so the popup builder
 * can render the "Zoom to here" link. `zoom` picks up the
 * `<map-feature zoom="N">` attribute when present (MapML.js's
 * `getZoomToZoom` priority), else the map's current zoom as a
 * conservative default.
 *
 * `defaultCs` is the fallback coordinate system used when the
 * `<map-geometry>` element has no explicit `cs` attribute. For
 * MapML responses this is sourced from `<map-meta name="cs">` in
 * the response document (defaults to `gcrs` per the MapML spec when
 * absent). For GeoJSON responses the caller passes `pcrs` when the
 * body carries projected coordinates (see
 * {@link hasProjectedCoordinates}).
 *
 * Element lookup uses `querySelector` on lowercase tag names, which
 * works across both XML documents (case-sensitive) and HTML
 * documents (case-insensitive) as long as the source markup uses
 * lowercase \u2014 which MapML canonically does.
 */
function mapFeatureElementToQueryProperties(
  featureEl: Element,
  projection: MapmlProjection,
  currentZoom: number,
  defaultCs: 'gcrs' | 'pcrs',
  clickLng: number,
  clickLat: number
): QueryFeatureProperties {
  const captionEl = featureEl.querySelector('map-featurecaption');
  const propertiesEl = featureEl.querySelector('map-properties');
  const geometryEl = featureEl.querySelector('map-geometry');
  const caption = captionEl?.textContent?.trim() ?? '';
  const innerHtml = propertiesEl?.innerHTML ?? '';
  const props: QueryFeatureProperties = {
    caption,
    propertiesHtml: wrapInIframe(innerHtml)
  };

  // Centroid: geometry-derived when available and parseable,
  // otherwise the click location. Matches MapML.js's
  // `QueryHandler._query` which synthesises a
  // `<map-geometry><map-point>` at the click for every
  // geometryless `<map-feature>` in the response \u2014 typical of
  // WMS GetFeatureInfo servers that return attribute rows without
  // geometry (GeoServer's `info_format=text/mapml` is one such).
  // Falling back to the click keeps the popup's "Zoom to here"
  // link always present; clicking it recenters the map on the
  // click point (and picks up the feature's `zoom` attribute when
  // one is declared).
  let centroid: { lng: number; lat: number } | null = null;
  if (geometryEl !== null) {
    const cs = parseGeometryCS(geometryEl.getAttribute('cs')) ?? defaultCs;
    const shapes = shapesFromGeometry(geometryEl);
    if (shapes.length > 0) {
      // Centroid: PCRS bbox centre reprojected to GCRS. Matches
      // MapML.js's `<a class="mapml-zoom-link">`, which averages the
      // feature's GCRS corners. Point geometries collapse the bbox
      // to a single coordinate so the centre *is* the point.
      const bounds = shapesToPcrsBounds(shapes, cs, projection);
      if (bounds !== null) {
        const [minX, minY] = bounds.min;
        const [maxX, maxY] = bounds.max;
        const [lng, lat] = osmtilePcrsToGcrs(
          (minX + maxX) / 2,
          (minY + maxY) / 2
        );
        centroid = { lng, lat };
      }
      // Transient highlight overlay geometry (GCRS lon/lat). One
      // GeoJSON geometry per shape so the renderer can paint the
      // returned feature on the map for the popup's lifetime.
      const geoms = shapesToGeoJson(shapes, cs, projection)
        .map((f) => f.geometry)
        .filter((g): g is GeoJSON.Geometry => g != null);
      if (geoms.length > 0) props.highlightGeometries = geoms;
    }
  }
  if (centroid === null) {
    centroid = { lng: clickLng, lat: clickLat };
  }
  props.centerLng = centroid.lng;
  props.centerLat = centroid.lat;

  // `<map-feature zoom="N">` mirrors MapML.js's `getZoomToZoom`
  // priority: an explicit attribute wins over the current view.
  const zoomAttr = featureEl.getAttribute('zoom');
  const zoomAttrN = zoomAttr !== null ? Number(zoomAttr) : NaN;
  props.zoom = Number.isFinite(zoomAttrN) ? zoomAttrN : currentZoom;

  return props;
}

/**
 * Parse a GeoJSON body via {@link geojson2mapml} into query feature
 * entries. Null-geometry features get a Point at the click location
 * before conversion so `geojson2mapml` doesn't error out on
 * MapML.js-style WMS GetFeatureInfo responses (which return
 * properties without geometry).
 *
 * Return values distinguish three cases:
 *
 *   - **Recognised, non-empty** \u2192 `QueryFeatureProperties[]` with
 *     one entry per feature.
 *   - **Recognised but empty** (e.g. `FeatureCollection` with an
 *     empty `features` array) \u2192 empty array. The outer caller
 *     suppresses the popup entirely (MapML.js-parity silent no-op
 *     for zero-hit GetFeatureInfo responses).
 *   - **Not recognisable as GeoJSON** (malformed JSON, missing/
 *     unknown `type`, or `geojson2mapml` threw) \u2192 `null`. The
 *     outer caller falls through to a plain-text popup so the
 *     author still sees the body for debugging.
 *
 * The recognisable-GeoJSON check gates on the top-level `type`
 * being one of the nine values the GeoJSON RFC enumerates
 * (`FeatureCollection`, `Feature`, or any of the seven geometry
 * types), and \u2014 for FeatureCollection \u2014 that `features` is
 * actually an array. Anything else is treated as arbitrary JSON
 * and falls through, so `{"foo": "bar"}` still renders as text.
 */
function parseGeoJsonFeatures(
  body: string,
  clickLng: number,
  clickLat: number,
  projection: MapmlProjection,
  locale: Locale,
  currentZoom: number
): QueryFeatureProperties[] | null {
  let json: unknown;
  try {
    json = JSON.parse(body);
  } catch {
    return null;
  }
  if (json === null || typeof json !== 'object') return null;
  const jsonWithType = json as { type?: unknown; features?: unknown; geometry?: unknown };
  const type = jsonWithType.type;

  const isFeatureCollection =
    type === 'FeatureCollection' && Array.isArray(jsonWithType.features);
  const isFeature = type === 'Feature';
  const isGeometry =
    typeof type === 'string' &&
    (type === 'Point' ||
      type === 'MultiPoint' ||
      type === 'LineString' ||
      type === 'MultiLineString' ||
      type === 'Polygon' ||
      type === 'MultiPolygon' ||
      type === 'GeometryCollection');

  // Not GeoJSON-shaped \u2192 caller falls through to plain-text so the
  // author sees the body for debugging.
  if (!isFeatureCollection && !isFeature && !isGeometry) return null;

  // Recognised as GeoJSON but empty (WMS GetFeatureInfo commonly
  // returns `{type: "FeatureCollection", features: []}` when no
  // features intersect the click). Return an empty array so the
  // outer caller silently suppresses the popup \u2014 matches
  // MapML.js's `if (features.length > 0) displayFeaturesPopup(\u2026)`
  // guard and is politer than showing a raw JSON blob to the user.
  if (
    isFeatureCollection &&
    (jsonWithType.features as unknown[]).length === 0
  ) {
    return [];
  }

  // Replace null / missing geometries with a Point at the click
  // location. Matches MapML.js's `_query` fallback for WMS
  // GetFeatureInfo responses that carry attributes but no geometry.
  const clickGeom = { type: 'Point' as const, coordinates: [clickLng, clickLat] };
  if (isFeatureCollection) {
    for (const f of jsonWithType.features as GeoJsonFeature[]) {
      if (f.geometry === null || f.geometry === undefined) {
        f.geometry = clickGeom;
      }
    }
  } else if (isFeature) {
    const feature = jsonWithType as unknown as GeoJsonFeature;
    if (feature.geometry === null || feature.geometry === undefined) {
      feature.geometry = clickGeom;
    }
  }

  let layerEl: HTMLElement;
  try {
    layerEl = geojson2mapml(json as GeoJsonInput, { projection }, locale);
  } catch {
    return null;
  }
  // WMS servers configured with a non-WGS84 `crs=` return GeoJSON
  // whose coordinates are actually projection meters, not the
  // RFC 7946 canonical WGS84 lng/lat. `geojson2mapml` doesn't know
  // this \u2014 it builds `<map-geometry>` elements without a `cs`
  // attribute and lets the default win at read time. Detecting the
  // projected shape up front lets us pass `defaultCs = 'pcrs'` into
  // {@link mapFeatureElementToQueryProperties}, which
  // {@link geometryCentroid} then honours as the geometry's
  // effective CS. Matches MapML.js's `QueryHandler` which does the
  // same thing via
  // `mapmlLayer.querySelector('map-meta[name=cs]').setAttribute('content','pcrs')`
  // \u2014 our threading is per-call rather than via DOM stamping so
  // the meta remains cosmetic on the synthesised layer.
  const defaultCs: 'gcrs' | 'pcrs' = hasProjectedCoordinates(json)
    ? 'pcrs'
    : 'gcrs';
  const featureEls = Array.from(layerEl.querySelectorAll('map-feature'));
  // `geojson2mapml` on a recognised-but-empty input shouldn't reach
  // here \u2014 the early-return above catches that. A truly zero-
  // feature output from a recognised input is degenerate; treat it
  // the same way as an empty FeatureCollection (suppress the
  // popup).
  return featureEls.map((el) =>
    mapFeatureElementToQueryProperties(
      el,
      projection,
      currentZoom,
      defaultCs,
      clickLng,
      clickLat
    )
  );
}

/**
 * Heuristic: does a GeoJSON payload carry projected (non-WGS84)
 * coordinates? Ports MapML.js's `_hasProjectedCoordinates` from
 * `src/mapml/handlers/QueryHandler.js` verbatim:
 *
 *   1. If the input has a top-level `crs` member (even though the
 *      RFC 7946 deprecates it, plenty of WMS servers still emit it
 *      to advertise the response CRS), treat as projected.
 *   2. Otherwise, sniff the first coordinate pair. Anything outside
 *      the WGS84 ranges (\u00b1180 lng, \u00b190 lat) can't be lat/lng.
 *
 * `Feature` and `FeatureCollection` wrappers are unpacked so the
 * check reaches the actual coordinate arrays.
 *
 * Exported for unit testing; the module-internal consumer is
 * {@link parseGeoJsonFeatures}.
 */
export function hasProjectedCoordinates(json: unknown): boolean {
  if (json === null || typeof json !== 'object') return false;
  const j = json as { crs?: unknown };
  if (j.crs !== null && j.crs !== undefined) return true;
  const c = firstCoordinate(json);
  if (c === null) return false;
  return Math.abs(c[0]) > 180 || Math.abs(c[1]) > 90;
}

/**
 * Extract the first `[x, y]` coordinate pair from a GeoJSON object,
 * drilling through `FeatureCollection` \u2192 `Feature` \u2192 `Geometry`.
 * For coordinate arrays deeper than a Point, walks down the
 * left-most branch until a `[number, number]` leaf is reached.
 * Returns `null` when the object doesn't have any traversable
 * coordinates (empty FC, geometry-less feature, etc.).
 */
function firstCoordinate(json: unknown): [number, number] | null {
  if (json === null || typeof json !== 'object') return null;
  const j = json as {
    type?: unknown;
    features?: unknown;
    geometry?: unknown;
    coordinates?: unknown;
    geometries?: unknown;
  };
  const type = typeof j.type === 'string' ? j.type.toUpperCase() : '';
  if (type === 'FEATURECOLLECTION') {
    const features = j.features;
    if (Array.isArray(features) && features.length > 0) {
      return firstCoordinate(features[0]);
    }
    return null;
  }
  if (type === 'FEATURE') {
    return firstCoordinate(j.geometry);
  }
  if (type === 'GEOMETRYCOLLECTION') {
    const gs = j.geometries;
    if (Array.isArray(gs) && gs.length > 0) return firstCoordinate(gs[0]);
    return null;
  }
  const coords: unknown = j.coordinates;
  if (coords === null || coords === undefined) return null;
  let walker: unknown = coords;
  while (Array.isArray(walker) && Array.isArray(walker[0])) {
    walker = walker[0];
  }
  if (
    Array.isArray(walker) &&
    walker.length >= 2 &&
    typeof walker[0] === 'number' &&
    typeof walker[1] === 'number'
  ) {
    return [walker[0], walker[1]];
  }
  return null;
}

/**
 * Package a single non-feature response body (text/html) into the
 * popup's `QueryFeatureProperties` bag. The click location + current
 * zoom are baked in so the popup's "Zoom to here" link renders and
 * recentres the map on the click point \u2014 matches MapML.js which
 * synthesises a `<map-geometry><map-point>` at the click for every
 * geometryless response and lets its usual zoom-link machinery kick
 * in from there. The link isn't super useful for a plain-text WMS
 * output ("zoom to where you already clicked"), but it keeps the
 * popup shape consistent so authors and screen-readers see the same
 * affordance across every response type.
 */
function singleHtmlFeature(
  body: string,
  clickLng: number,
  clickLat: number,
  currentZoom: number
): QueryFeatureProperties {
  return {
    caption: '',
    propertiesHtml: wrapInIframe(body),
    centerLng: clickLng,
    centerLat: clickLat,
    zoom: currentZoom
  };
}

function singleTextFeature(
  body: string,
  clickLng: number,
  clickLat: number,
  currentZoom: number
): QueryFeatureProperties {
  return {
    caption: '',
    propertiesHtml:
      '<div class="mapml-query-response-text"><pre>' +
      escapeHtml(body) +
      '</pre></div>',
    centerLng: clickLng,
    centerLat: clickLat,
    zoom: currentZoom
  };
}

/**
 * Wrap a server-supplied HTML fragment in a sandboxed iframe for
 * popup display. Matches MapML.js's
 * `iframe.srcdoc + sandbox="allow-same-origin allow-forms"`
 * (no `allow-scripts`) \u2014 the iframe is the origin-isolation
 * boundary between the host page and untrusted server responses.
 * Callers should not embed script tags in `<map-properties>` and
 * expect them to run.
 *
 * `<script>` elements are stripped from the body first: the sandbox
 * already blocks them from executing, but leaving them in makes the
 * browser log a "Blocked script execution in 'about:srcdoc'" warning
 * for every response (GeoServer's HTML GetFeatureInfo templates ship
 * a script). Removing them keeps the security posture identical while
 * silencing that noise.
 */
function wrapInIframe(bodyHtml: string): string {
  return (
    '<div class="mapml-query-response">' +
    '<iframe sandbox="allow-same-origin allow-forms" srcdoc="' +
    escapeAttr(stripScripts(bodyHtml)) +
    '"></iframe></div>'
  );
}

/** Remove `<script>…</script>` elements (the sandbox blocks them anyway). */
function stripScripts(html: string): string {
  return html.replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, '');
}

function escapeAttr(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/"/g, '&quot;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
